--

CREATE FUNCTION discourse_functions.skip_piggyback_browser_pageview_events() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.source = 1 THEN
    RETURN NULL;
  END IF;

  RETURN NEW;
END;
$$;


