icker-bg: var(--secondary) !default;\\n$pd-picker-border: var(--primary-low) !default;\\n$pd-picker-border-bottom: var(--primary-low) !default;\\n$pd-picker-shadow: rgb(0,0,0,.5) !default;\\n$pd-th-color: var(--primary) !default;\\n$pd-day-color: var(--primary) !default;\\n$pd-day-bg: var(--secondary) !default;\\n$pd-day-hover-color: var(--primary) !default;\\n$pd-day-hover-bg: var(--tertiary-low) !default;\\n$pd-day-today-color: var(--tertiary) !default;\\n$pd-day-selected-color: var(--secondary) !default;\\n$pd-day-selected-bg: var(--tertiary) !default;\\n$pd-day-selected-shadow: var(--tertiary-low) !default;\\n$pd-day-disabled-color: var(--primary) !default;\\n$pd-week-color: var(--primary) !default;\\n\\n// Font\\n$pd-font-family: arial, sans-serif !default;\\n\\n\\n.pika-single {\\n    z-index: 9999;\\n    display: block;\\n    position: relative;\\n    color: $pd-text-color;\\n    background: $pd-picker-bg;\\n    border: 1px solid $pd-picker-border;\\n    border-bottom-color: $pd-picker-border-bottom;\\n    font-family: $pd-font-family;\\n\\n    &.is-hidden {\\n        display: none;\\n    }\\n\\n    &.is-bound {\\n        position: absolute;\\n        box-shadow: 0 5px 15px -5px $pd-picker-shadow;\\n    }\\n}\\n\\n// clear child float (pika-lendar), using the famous micro clearfix hack\\n// http://nicolasgallagher.com/micro-clearfix-hack/\\n/* stylelint-disable-next-line no-duplicate-selectors */\\n.pika-single {\\n    &::before,\\n    &::after {\\n        content: \\" \\";\\n        display: table;\\n    }\\n\\n    &::after { clear: both }\\n}\\n\\n.pika-lendar {\\n    float: left;\\n    width: 240px;\\n    margin: 8px;\\n}\\n\\n.pika-title {\\n    position: relative;\\n    text-align: center;\\n\\n    select {\\n        cursor: pointer;\\n        position: absolute;\\n        z-index: 9998;\\n        margin: 0;\\n        left: 0;\\n        top: 5px;\\n        filter: alpha(opacity=0);\\n        opacity: 0;\\n    }\\n}\\n\\n.pika-label {\\n    display: inline-block;\\n    position: relative;\\n    z-index: 9999;\\n    overflow: hidden;\\n    margin: 0;\\n    padding: 5px 3px;\\n    font-size: 14px;\\n    line-height: 20px;\\n    font-weight: bold;\\n    color: $pd-title-color;\\n    background-color: $pd-title-bg;\\n}\\n\\n.pika-prev,\\n.pika-next {\\n    display: block;\\n    cursor: pointer;\\n    position: relative;\\n    outline: none;\\n    border: 0;\\n    padding: 0;\\n    width: 20px;\\n    height: 30px;\\n    text-indent: 20px; // hide text using text-indent trick, using width value (it's enough)\\n    white-space: nowrap;\\n    overflow: hidden;\\n    background-color: var(--primary); // sets color of SVG masks below\\n    background-size: 75% 75%;\\n    opacity: .5;\\n\\n    &:hover, &:focus {\\n        opacity: 1;\\n        background: var(--tertiary);\\n    }\\n\\n    &.is-disabled {\\n        cursor: default;\\n        opacity: .2;\\n    }\\n}\\n\\n.pika-prev,\\n.is-rtl .pika-next {\\n    float: left;\\n    mask: svg-uri(\\n        '<svg aria-hidden=\\"true\\" role=\\"img\\" xmlns=\\"http://www.w3.org/2000/svg\\" width=\\"14px\\" height=\\"16px\\" viewBox=\\"0 0 192 512\\"><path d=\\"M192 127.338v257.324c0 17.818-21.543 26.741-34.142 14.142L29.196 270.142c-7.81-7.81-7.81-20.474 0-28.284l128.662-128.662c12.599-12.6 34.142-3.676 34.142 14.142z\\"></path></svg>'\\n      )\\n      no-repeat 50% 50%;\\n}\\n\\n.pika-next,\\n.is-rtl .pika-prev {\\n    float: right;\\n    mask: svg-uri(\\n        '<svg aria-hidden=\\"true\\" role=\\"img\\" xmlns=\\"http://www.w3.org/2000/svg\\" width=\\"14px\\" height=\\"16px\\" viewBox=\\"0 0 192 512\\"><path d=\\"M0 384.662V127.338c0-17.818 21.543-26.741 34.142-14.142l128.662 128.662c7.81 7.81 7.81 20.474 0 28.284L34.142 398.804C21.543 411.404 0 402.48 0 384.662z\\"></path></svg>'\\n      )\\n      no-repeat 50% 50%;\\n  }\\n\\n.pika-select {\\n    display: inline-block;\\n}\\n\\n.pika-table {\\n    width: 100%;\\n    border-collapse: collapse;\\n    border-spacing: 0;\\n    border: 0;\\n\\n    th,\\n    td {\\n        width: 14.285714285714286%;\\n        padding: 0;\\n    }\\n\\n    th {\\n        color: $pd-th-color;\\n        font-size: 12px;\\n        line-height: 25px;\\n        font-weight: bold;\\n        text-align: center;\\n    }\\n\\n    abbr {\\n        border-bottom: none;\\n        cursor: help;\\n    }\\n}\\n\\n.pika-button {\\n    cursor: pointer;\\n    display: block;\\n    box-sizing: border-box;\\n    outline: none;\\n    border: 0;\\n    margin: 0;\\n    width: 100%;\\n    padding: 5px;\\n    color: $pd-day-color;\\n    font-size: 12px;\\n    line-height: 15px;\\n    text-align: right;\\n    background: $pd-day-bg;\\n\\n    .is-today & {\\n        color: $pd-day-today-color;\\n        font-weight: bold;\\n    }\\n\\n    .is-selected & {\\n        color: $pd-day-selected-color;\\n        font-weight: bold;\\n        background: $pd-day-selected-bg;\\n        box-shadow: inset 0 1px 3px $pd-day-selected-shadow;\\n        border-radius: 3px;\\n    }\\n\\n    .is-disabled &,\\n    .is-outside-current-month & {\\n        pointer-events: none;\\n        cursor: default;\\n        color: $pd-day-disabled-color;\\n        opacity: .3;\\n    }\\n\\n    &:hover {\\n        color: $pd-day-hover-color;\\n        background: $pd-day-hover-bg;\\n        box-shadow: none;\\n        border-radius: 3px;\\n    }\\n}\\n\\n.pika-week {\\n    font-size: 11px;\\n    color: $pd-week-color;\\n}\\n\\n.is-inrange .pika-button {\\n    background: #D5E9F7;\\n}\\n\\n.is-startrange .pika-button {\\n    color: var(--secondary);\\n    background: #6CB31D;\\n    box-shadow: none;\\n    border-radius: 3px;\\n}\\n\\n.is-endrange .pika-button {\\n    color: var(--secondary);\\n    background: var(--tertiary);\\n    box-shadow: none;\\n    border-radius: 3px;\\n}\\n\\n.pika-day {\\n    &:focus {\\n        background-color: var(--tertiary-very-low);\\n    }\\n}\\n","// Overrides for Windows High Contrast Mode\\n\\n/*\\n  Some @media (forced-colors: active) {} styles\\n  have also been used inside mixins in:\\n  - common/components/buttons.scss\\n\\n  See file above for overrides.\\n*/\\n\\n// Select Kit\\n.select-kit {\\n  .select-kit-row {\\n    &:hover,\\n    &:focus {\\n      @media (forced-colors: active) {\\n        outline: 2px auto transparent;\\n      }\\n    }\\n  }\\n}\\n","// --------------------------------------------------\\n// Generic helper classes\\n// --------------------------------------------------\\n\\n// Floats\\n// --------------------------------------------------\\n.pull-left {\\n  float: left;\\n}\\n\\n.pull-right {\\n  float: right;\\n}\\n\\n// Element visibility\\n// --------------------------------------------------\\n.show {\\n  display: block;\\n}\\n\\n.hide,\\n.hidden {\\n  display: none !important;\\n}\\n\\n.invisible {\\n  visibility: hidden;\\n}\\n\\n.sr-only {\\n  position: absolute;\\n  width: 1px;\\n  height: 1px;\\n  padding: 0;\\n  margin: -1px;\\n  overflow: hidden;\\n  clip-path: rect(0 0 0 0);\\n  border: 0;\\n}\\n\\n// Contain floats\\n// --------------------------------------------------\\n.clearfix {\\n  &::before,\\n  &::after {\\n    display: table;\\n    content: \\" \\";\\n  }\\n\\n  &::after {\\n    clear: both;\\n  }\\n}\\n\\n// Overflow\\n// --------------------------------------------------\\n.overflow-ellipsis {\\n  white-space: nowrap;\\n  overflow: hidden;\\n  text-overflow: ellipsis;\\n}\\n\\n// Clickable elements\\n// --------------------------------------------------\\n.clickable {\\n  cursor: pointer;\\n}\\n\\n.non-clickable {\\n  cursor: default;\\n}\\n","// These CSS custom properties are added here instead of in variables.scss\\n// because variables.scss is injected into every theme CSS file\\n// which causes problems when overriding custom properties in themes\\n:root {\\n  --topic-body-width: #{$topic-body-width};\\n  --topic-body-width-padding: var(--space-3);\\n  --topic-avatar-width: #{$topic-avatar-width};\\n  --d-border-radius: 4px;\\n  --d-border-radius-large: calc(var(--d-border-radius) * 2);\\n  --d-border-radius-fixed: 4px; // very subtle soft borders that never make sense to change with global theming\\n  --d-border-radius-pill: 1em; // pill-like elements that also shouldn't be influenced by normal border-radius\\n  --d-nav-pill-border-radius: var(--d-border-radius);\\n  --d-input-border-radius: var(--d-border-radius);\\n  --d-content-background: initial;\\n  --d-link-text-decoration: none;\\n\\n  // used for padding & margin\\n  --space: 0.25rem; // 4px\\n  --space-half: calc(var(--space) / 2); // 2px\\n  --space-1: var(--space); // 4px\\n  --space-2: calc(var(--space) * 2);\\n  --space-3: calc(var(--space) * 3);\\n  --space-4: calc(var(--space) * 4);\\n  --space-5: calc(var(--space) * 5);\\n  --space-6: calc(var(--space) * 6);\\n  --space-7: calc(var(--space) * 7);\\n  --space-8: calc(var(--space) * 8);\\n  --space-9: calc(var(--space) * 9);\\n  --space-10: calc(var(--space) * 10);\\n  --space-11: calc(var(--space) * 11);\\n  --space-12: calc(var(--space) * 12);\\n}\\n\\n// --------------------------------------------------\\n// Base styles for HTML elements\\n// --------------------------------------------------\\nhtml {\\n  color: var(--primary);\\n  font-family: var(--font-family);\\n  font-size: var(--base-font-size);\\n  line-height: var(--line-height-large);\\n  background-color: var(--secondary);\\n  direction: ltr;\\n\\n  &.text-size-smallest {\\n    font-size: var(--base-font-size-smallest);\\n  }\\n\\n  &.text-size-smaller {\\n    font-size: var(--base-font-size-smaller);\\n  }\\n\\n  &.text-size-larger {\\n    font-size: var(--base-font-size-larger);\\n  }\\n\\n  &.text-size-largest {\\n    font-size: var(--base-font-size-largest);\\n  }\\n}\\n\\n// Links\\n// --------------------------------------------------\\na,\\na:visited,\\na:hover,\\na:active {\\n  color: var(--d-link-color);\\n  text-decoration: var(--d-link-text-decoration);\\n  cursor: pointer;\\n}\\n\\n// Typography\\n// --------------------------------------------------\\nhr {\\n  display: block;\\n  height: 1px;\\n  margin: 1em 0;\\n  border: 0;\\n  border-top: 1px solid var(--content-border-color);\\n  padding: 0;\\n}\\n\\n.dot-separator {\\n  @include dot-separator;\\n}\\n\\n// Lists\\n// --------------------------------------------------\\nul,\\nol,\\ndd {\\n  margin: 1em 0 1em 1.25em;\\n  padding: 0;\\n}\\n\\n.cooked ul,\\n.cooked ol,\\n.cooked dd {\\n  clear: both;\\n}\\n\\n.cooked,\\n.d-editor-preview {\\n  ul,\\n  ol {\\n    padding-inline-start: 1.25em;\\n  }\\n}\\n\\nli,\\n.cooked li,\\n.d-editor-preview li {\\n  > ul,\\n  > ol {\\n    margin: 0;\\n  }\\n}\\n\\n// Embedded content\\n// --------------------------------------------------\\nimg {\\n  vertical-align: middle;\\n}\\n\\n.svg-icon {\\n  color: inherit;\\n}\\n\\n// Forms\\n// --------------------------------------------------\\nfieldset {\\n  margin: 0;\\n  border: 0;\\n  padding: 0;\\n}\\n\\npre code {\\n  overflow: auto;\\n  tab-size: 4;\\n\\n  &.lang-markdown {\\n    white-space: pre-wrap;\\n  }\\n}\\n\\n// Tables\\n// --------------------------------------------------\\ntable {\\n  border-collapse: collapse;\\n}\\n\\ntbody {\\n  border-top: var(--d-table-border-top-height) solid var(--table-border-color);\\n}\\n\\n.topic-list-item,\\ntbody tr {\\n  border-bottom: var(--table-border-width) solid var(--table-border-color);\\n\\n  @media (prefers-reduced-motion: no-preference) {\\n    &.highlighted {\\n      animation: background-fade-highlight 2.5s ease-out;\\n    }\\n  }\\n}\\n\\n// https://en.wikipedia.org/wiki/Ruby_character\\nruby > rt {\\n  font-size: 72%; // ~10px with 14px base\\n}\\n\\n// Buttons (was in normalized)\\n// --------------------------------------------------\\nbutton,\\nhtml input[type=\\"button\\"],\\ninput[type=\\"reset\\"],\\ninput[type=\\"submit\\"] {\\n  cursor: pointer;\\n}\\n\\n// Inline form\\n// --------------------------------------------------\\n.inline-form {\\n  display: inline-flex;\\n  align-items: center;\\n  flex-wrap: wrap;\\n\\n  &.full-width {\\n    display: flex;\\n  }\\n\\n  > input[type=\\"text\\"],\\n  > input[type=\\"search\\"],\\n  > input[type=\\"password\\"] {\\n    display: inline-flex;\\n    flex: 1;\\n  }\\n\\n  > .select-kit,\\n  > input[type=\\"text\\"],\\n  > input[type=\\"search\\"],\\n  > input[type=\\"password\\"],\\n  > label,\\n  > .btn,\\n  > .d-date-input {\\n    margin-bottom: 0.5em; // for when items wrap (mobile, narrow windows)\\n    margin-right: 0.5em;\\n\\n    &:last-child {\\n      margin-right: 0;\\n    }\\n  }\\n}\\n\\n// Inputs\\n// --------------------------------------------------\\ninput[type=\\"checkbox\\"],\\ninput[type=\\"radio\\"] {\\n  accent-color: var(--tertiary);\\n}\\n\\ntextarea,\\ninput,\\nselect,\\nbutton {\\n  font-variation-settings: inherit;\\n  font-feature-settings: inherit;\\n}\\n","// --------------------------------------------------\\n// Mixins used throughout the theme\\n// --------------------------------------------------\\n\\n// Media queries\\n// --------------------------------------------------\\n\\n@use \\"sass:color\\";\\n@use \\"sass:math\\";\\n@use \\"sass:string\\";\\n@use \\"sass:map\\";\\n@use \\"lib/viewport\\";\\n\\n$breakpoints: (\\n  mobile-small: map.get(viewport.$breakpoints, sm),\\n  mobile-medium: map.get(viewport.$breakpoints, sm),\\n  mobile-large: map.get(viewport.$breakpoints, sm),\\n  mobile-extra-large: map.get(viewport.$breakpoints, sm),\\n  tablet: map.get(viewport.$breakpoints, md),\\n  medium: map.get(viewport.$breakpoints, lg),\\n  large: map.get(viewport.$breakpoints, lg),\\n  extra-large: map.get(viewport.$breakpoints, xl),\\n);\\n\\n/* breakpoint is a legacy mixin. Use `@use \\"lib/viewport\\"` instead. */\\n@mixin breakpoint($bp, $rule: max-width, $type: screen, $sidebar: false) {\\n  /* stylelint-disable-next-line scss/no-global-function-names */\\n  $bp-value: map-get($breakpoints, $bp);\\n\\n  @if $rule == min-width {\\n    $bp-value: calc(#{$bp-value} + 1px);\\n  }\\n\\n  @media #{$type} and (#{$rule}: #{$bp-value}) {\\n    @content;\\n  }\\n\\n  // if you want to consider the sidebar in your breakpoint\\n  // you can pass in $sidebar: true\\n  // note that your breakpoint will need to be at the root level\\n  @if $sidebar {\\n    // when the sidebar is shown, we want to increase the breakpoints by the width of the sidebar\\n    /* stylelint-disable-next-line scss/no-global-function-names */\\n    @media #{$type} and (#{$rule}: calc(#{map-get($breakpoints, $bp)} + #{$d-sidebar-width})) {\\n      .has-sidebar-page {\\n        @content;\\n      }\\n    }\\n  }\\n}\\n\\n// CSS3 properties\\n// --------------------------------------------------\\n\\n// Clearfix\\n\\n@mixin clearfix() {\\n  &::before,\\n  &::after {\\n    content: \\"\\";\\n    display: table;\\n  }\\n\\n  &::after {\\n    clear: both;\\n  }\\n}\\n\\n@mixin linear-gradient($start-color, $end-color) {\\n  background-color: $start-color;\\n  background-image: linear-gradient(to bottom, $start-color, $end-color);\\n}\\n\\n@mixin darken-background($background-color, $amt) {\\n  $overlay: dark-light-choose(\\n    rgb(var(--primary-rgb), $amt),\\n    rgb(var(--secondary-rgb), $amt)\\n  );\\n  background-image: linear-gradient(to bottom, $overlay 100%, $overlay 100%);\\n}\\n\\n// Visibility\\n// --------------------------------------------------\\n\\n// Only shows hover on non-touch devices\\n@mixin hover {\\n  .discourse-no-touch &,\\n  .no-ember & {\\n    &:hover,\\n    &.btn-hover {\\n      @content;\\n    }\\n  }\\n}\\n\\n@mixin ellipsis {\\n  overflow: hidden;\\n  white-space: nowrap;\\n  text-overflow: ellipsis;\\n}\\n\\n@mixin line-clamp($lines) {\\n  display: -webkit-box;\\n  overflow: hidden;\\n  text-overflow: ellipsis;\\n  overflow-wrap: break-word;\\n  -webkit-line-clamp: $lines;\\n  -webkit-box-orient: vertical;\\n}\\n\\n//\\n// --------------------------------------------------\\n\\n$vpad: 0.5em;\\n$hpad: 0.65em;\\n\\n// for consistent sizing across inputs, buttons and dropdowns\\n@mixin form-item-sizing {\\n  border: 1px solid transparent;\\n  font-size: var(--font-0);\\n  line-height: normal;\\n  box-sizing: border-box;\\n  padding: $vpad $hpad;\\n}\\n\\n// Used to handle -webkit prefix, but now we have autoprefixer\\n// Keeping for backward-compat with plugins/themes only\\n@mixin user-select($mode) {\\n  user-select: $mode;\\n}\\n\\n// Unselectable (avoids unwanted selections with iPad, touch laptops, etc)\\n@mixin unselectable {\\n  cursor: default;\\n\\n  @include user-select(none);\\n}\\n\\n// Stuff we repeat\\n@mixin d-animation($name, $duration, $easing: ease) {\\n  animation: $name $duration $easing forwards;\\n\\n  @media (prefers-reduced-motion) {\\n    /* stylelint-disable-next-line no-invalid-position-declaration */\\n    animation-duration: 0s;\\n  }\\n}\\n\\n@mixin default-focus() {\\n  border-color: var(--d-input-focused-color);\\n  outline: 2px solid var(--d-input-focused-color);\\n  outline-offset: -2px;\\n}\\n\\n/// Helper function to easily use an SVG inline in CSS\\n/// without encoding it to base64, saving bytes.\\n/// It also helps with browser support, especially for IE11.\\n///\\n/// @author Jakob Eriksen\\n/// @link http://codepen.io/jakob-e/pen/doMoML\\n/// @param {String} $svg - SVG image to encode\\n/// @return {String} - Encoded SVG data uri\\n@function svg-uri($svg) {\\n  $encoded: \\"\\";\\n  $slice: 2000;\\n  $index: 0;\\n  $loops: math.ceil(math.div(string.length($svg), $slice));\\n\\n  @for $i from 1 through $loops {\\n    $chunk: string.slice($svg, $index, $index + $slice - 1);\\n    $chunk: str-replace($chunk, '\\"', \\"'\\");\\n    $chunk: str-replace($chunk, \\"<\\", \\"%3C\\");\\n    $chunk: str-replace($chunk, \\">\\", \\"%3E\\");\\n    $chunk: str-replace($chunk, \\"&\\", \\"%26\\");\\n    $chunk: str-replace($chunk, \\"#\\", \\"%23\\");\\n    $encoded: #{$encoded}#{$chunk};\\n    $index: $index + $slice;\\n  }\\n\\n  @return url(\\"data:image/svg+xml;charset=utf8,#{$encoded}\\");\\n}\\n\\n/// Replace `$search` with `$replace` in `$string`\\n/// @author Hugo Giraudel\\n/// @link http://sassmeister.com/gist/1b4f2da5527830088e4d\\n/// @param {String} $string - Initial string\\n/// @param {String} $search - Substring to replace\\n/// @param {String} $replace ('') - New value\\n/// @return {String} - Updated string\\n@function str-replace($string, $search, $replace: \\"\\") {\\n  $index: string.index($string, $search);\\n\\n  @if $index {\\n    @return string.slice($string, 1, $index - 1) + $replace +\\n      str-replace(\\n        string.slice($string, $index + string.length($search)),\\n        $search,\\n        $replace\\n      );\\n  }\\n\\n  @return $string;\\n}\\n\\n// SCSS accepts HEX or RGB colors for rgba($color, 0.5)\\n// CSS custom properties only accept RGB\\n// Example usage:\\n\\n// --primary-rgb: #{hexToRGB($primary)};\\n// ...\\n// rgba(var(--primary-low-rgb), 0.5)\\n\\n@function hexToRGB($hex) {\\n  @return color.red($hex), color.green($hex), color.blue($hex);\\n}\\n\\n@function schemeType() {\\n  @if is-light-color-scheme() {\\n    @return \\"light\\";\\n  } @else {\\n    @return \\"dark\\";\\n  }\\n}\\n\\n@function absolute-image-url($path) {\\n  // public_image_path is added by the stylesheet importer\\n  // it returns a CDN or subfolder path (if applicable).\\n  // SCSS will compile (and return the relative path) if public_image_path is missing.\\n  /* stylelint-disable-next-line scss/no-global-function-names */\\n  @if global-variable-exists(public_image_path) {\\n    @if string.index(\\"#{$path}\\", \\"/plugins\\") == 1 {\\n      $plugin_asset_path: str-replace($public_image_path, \\"/images\\", \\"\\");\\n\\n      @return url(\\"#{$plugin_asset_path}#{$path}\\");\\n    } @else {\\n      @return url(\\"#{$public_image_path}#{$path}\\");\\n    }\\n  } @else {\\n    @return url(\\"#{$path}\\");\\n  }\\n}\\n\\n@mixin mention() {\\n  // memo to self: do not make this inline-flex because it breaks text alignments and causes a whole avalance of unpleasant consequences\\n  display: inline-block;\\n  font-size: 0.93em;\\n  font-weight: normal;\\n  color: var(--primary);\\n  padding: 0.2em 0.34em;\\n  background: var(--mention-background-color);\\n  border-radius: 0.6em;\\n  text-decoration: none;\\n  text-wrap: nowrap;\\n  line-height: 1;\\n  unicode-bidi: plaintext;\\n\\n  &[data-valid=\\"false\\"] {\\n    background: unset;\\n    padding: 0;\\n  }\\n\\n  &.--bot {\\n    background: var(--success-low);\\n  }\\n\\n  &.--wide {\\n    background: var(--highlight-low-or-medium);\\n  }\\n}\\n\\n@mixin nav-active() {\\n  color: var(--d-nav-color--active);\\n  background: var(--d-nav-bg-color--active);\\n\\n  .d-icon {\\n    color: var(--d-nav-color--active);\\n  }\\n\\n  &::after {\\n    content: \\"\\";\\n    position: absolute;\\n    left: 0;\\n    bottom: 0;\\n    right: 0;\\n    height: var(--d-nav-underline-height);\\n    background: var(--d-nav-color--active);\\n\\n    // Forced colors drop backgrounds, which is the only thing that marks\\n    // the active item.\\n    @media (forced-colors: active) {\\n      background: Highlight;\\n      forced-color-adjust: none;\\n    }\\n  }\\n}\\n\\n@mixin nav-hover() {\\n  color: var(--d-nav-color--hover);\\n  background: var(--d-nav-bg-color--hover);\\n\\n  .d-icon {\\n    color: var(--d-nav-color--active);\\n  }\\n}\\n\\n// A strip that hides its scrollbar and fades the edge beyond which more\\n// content lies. The fade reads the data-d-scroll-* attributes stamped by\\n// the scroll-edges watcher, which DOverflowControls and the dScrollEdges\\n// modifier both run. The band starts fully transparent across --fade-inset\\n// so strip content never shows through a chevron parked on the edge, which\\n// assumes the chevron covers that band: a wrapper that pads the scroller's\\n// scrolling edge moves the chevron off it and hides content under nothing.\\n// #000 is deliberate: a mask reads only alpha, so a colour token would be\\n// wrong here.\\n@mixin scroll-strip() {\\n  // The bands are capped so the two ends cannot cross on a narrow strip.\\n  // Crossed bands leave no opaque middle.\\n  --scroll-strip-fade-start: min(var(--fade-inset, 0px), 15%);\\n  --scroll-strip-fade-end: min(\\n    calc(var(--fade-inset, 0px) + var(--fade-width, 2em)),\\n    40%\\n  );\\n  min-width: 0;\\n  min-height: 0;\\n  scrollbar-width: none;\\n  scroll-padding: calc(var(--fade-inset, 0px) + var(--fade-width, 2em));\\n\\n  &::-webkit-scrollbar {\\n    display: none;\\n  }\\n\\n  // Forced colors drop the mask, which would otherwise lower text contrast\\n  // for exactly the users who opted out of decoration.\\n  @media (forced-colors: none) {\\n    &[data-d-scroll-axis=\\"horizontal\\"][data-d-scroll-overflow] {\\n      mask-image: linear-gradient(\\n        to right,\\n        transparent var(--scroll-strip-fade-start),\\n        #000 var(--scroll-strip-fade-end),\\n        #000 calc(100% - var(--scroll-strip-fade-end)),\\n        transparent calc(100% - var(--scroll-strip-fade-start))\\n      );\\n\\n      // The edges are logical, the gradients physical, so RTL swaps them.\\n      &[data-d-scroll-at-start] {\\n        mask-image: linear-gradient(\\n          to right,\\n          #000 calc(100% - var(--scroll-strip-fade-end)),\\n          transparent calc(100% - var(--scroll-strip-fade-start))\\n        );\\n\\n        .rtl & {\\n          mask-image: linear-gradient(\\n            to left,\\n            #000 calc(100% - var(--scroll-strip-fade-end)),\\n            transparent calc(100% - var(--scroll-strip-fade-start))\\n          );\\n        }\\n      }\\n\\n      &[data-d-scroll-at-end] {\\n        mask-image: linear-gradient(\\n          to right,\\n          transparent var(--scroll-strip-fade-start),\\n          #000 var(--scroll-strip-fade-end)\\n        );\\n\\n        .rtl & {\\n          mask-image: linear-gradient(\\n            to left,\\n            transparent var(--scroll-strip-fade-start),\\n            #000 var(--scroll-strip-fade-end)\\n          );\\n        }\\n      }\\n    }\\n\\n    &[data-d-scroll-axis=\\"vertical\\"][data-d-scroll-overflow] {\\n      mask-image: linear-gradient(\\n        to bottom,\\n        transparent var(--scroll-strip-fade-start),\\n        #000 var(--scroll-strip-fade-end),\\n        #000 calc(100% - var(--scroll-strip-fade-end)),\\n        transparent calc(100% - var(--scroll-strip-fade-start))\\n      );\\n\\n      &[data-d-scroll-at-start] {\\n        mask-image: linear-gradient(\\n          to bottom,\\n          #000 calc(100% - var(--scroll-strip-fade-end)),\\n          transparent calc(100% - var(--scroll-strip-fade-start))\\n        );\\n      }\\n\\n      &[data-d-scroll-at-end] {\\n        mask-image: linear-gradient(\\n          to bottom,\\n          transparent var(--scroll-strip-fade-start),\\n          #000 var(--scroll-strip-fade-end)\\n        );\\n      }\\n    }\\n\\n    // The .rtl copy only exists to outrank the .rtl at-start/at-end rules\\n    // above, which score a class higher than the bare selector.\\n    &[data-d-scroll-overflow][data-d-scroll-at-start][data-d-scroll-at-end],\\n    .rtl\\n      &[data-d-scroll-overflow][data-d-scroll-at-start][data-d-scroll-at-end] {\\n      mask-image: none;\\n    }\\n  }\\n}\\n\\n// The scroll strip on the horizontal axis. The caller keeps its own items\\n// on one row; the mixin does not.\\n@mixin horizontal-scroll-strip() {\\n  @include scroll-strip;\\n  overflow-x: auto;\\n}\\n\\n@mixin click-counter-badge {\\n  content: attr(data-clicks);\\n  font-weight: normal;\\n  background-color: var(--primary-low);\\n  color: var(--primary-medium);\\n  position: relative;\\n  top: -1px;\\n  padding: 0.21em 0.42em;\\n  min-width: 0.5em;\\n  line-height: var(--line-height-small);\\n  font-size: var(--font-down-2);\\n  text-align: center;\\n  border-radius: 10px;\\n  white-space: nowrap;\\n  display: inline-block;\\n  margin: 0.15em;\\n}\\n\\n@mixin topic-list-icons {\\n  .d-icon-thumbtack {\\n    color: var(--primary-med-or-secondary-med);\\n  }\\n\\n  .d-icon-thumbtack.unpinned {\\n    color: var(--primary-med-or-secondary-med);\\n  }\\n\\n  a.title {\\n    color: var(--primary);\\n  }\\n\\n  .d-icon-bookmark {\\n    color: var(--primary-med-or-secondary-med);\\n  }\\n}\\n\\n@mixin hide-posters {\\n  width: 2em;\\n  text-align: center;\\n\\n  a:first-child .avatar.latest:not(.single) {\\n    top: 0;\\n    left: 0;\\n  }\\n\\n  a:not(.latest) {\\n    display: none;\\n  }\\n\\n  a.latest {\\n    width: 100%;\\n\\n    img {\\n      margin: 0 auto;\\n    }\\n  }\\n}\\n\\n@mixin dot-separator($size: 0.35em) {\\n  display: inline-block;\\n  width: $size;\\n  height: $size;\\n  margin-inline: var(--space-1);\\n  border-radius: 6.25em;\\n  background: var(--primary-low-mid);\\n  flex-shrink: 0;\\n}\\n\\n@mixin menu-item {\\n  display: inline-flex;\\n  gap: var(--d-sidebar-section-link-prefix-margin-right);\\n  padding: var(--space-2) var(--d-sidebar-row-horizontal-padding);\\n  width: 100%;\\n  justify-content: flex-start;\\n  background: rgb(0, 0, 0, 0);\\n  border-radius: var(--d-border-radius);\\n\\n  &:not(.notifications-tracking-btn, .--with-description, .pinned-options-btn) {\\n    height: var(--d-sidebar-row-height);\\n    padding-block: 0;\\n  }\\n\\n  &.-selected {\\n    background: var(--d-hover);\\n  }\\n\\n  &.btn-danger {\\n    color: var(--danger);\\n\\n    .d-icon {\\n      color: inherit;\\n    }\\n  }\\n\\n  .svg-icon {\\n    width: var(--d-sidebar-section-link-prefix-width);\\n    margin-right: 0;\\n  }\\n\\n  &:hover,\\n  &:focus-visible {\\n    .discourse-no-touch & {\\n      background: var(--d-hover);\\n      color: var(--primary);\\n\\n      .d-icon {\\n        color: inherit;\\n      }\\n\\n      &.btn-danger {\\n        background: var(--danger-low);\\n        color: var(--danger);\\n\\n        .d-icon {\\n          color: var(--danger-hover);\\n        }\\n      }\\n    }\\n  }\\n}\\n\\n@mixin unstyled-list {\\n  list-style: none;\\n  padding: 0;\\n  margin: 0;\\n}\\n",".form-kit {\\n  &__fieldset {\\n    display: flex;\\n    flex-direction: column;\\n    gap: 0.75rem;\\n\\n    &.--inline {\\n      flex-flow: row wrap;\\n      align-items: center;\\n      gap: 0.5rem 1.5rem;\\n\\n      > :not(.form-kit__field) {\\n        flex-basis: 100%;\\n      }\\n    }\\n  }\\n\\n  &__fieldset-title {\\n    display: flex;\\n    align-items: center;\\n    margin: 0 0 0.25rem;\\n    font-size: var(--font-down-1-rem);\\n    color: var(--primary);\\n  }\\n\\n  &__fieldset-description {\\n    display: flex;\\n    align-items: center;\\n    margin: 0;\\n    color: var(--primary);\\n  }\\n}\\n",".form-kit__alert {\\n  // reset\\n  margin: 0;\\n  width: 100%;\\n  border-radius: var(--d-border-radius);\\n  box-sizing: border-box;\\n  padding: 0.5em;\\n}\\n",".form-kit__char-counter {\\n  margin-left: auto;\\n  padding-top: 0.15em;\\n\\n  &.--exceeded {\\n    color: var(--danger);\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.form-kit__col {\\n  flex: 0 0 auto;\\n  box-sizing: border-box;\\n}\\n\\n@include viewport.until(lg) {\\n  .--col-1,\\n  .--col-2,\\n  .--col-3,\\n  .--col-4,\\n  .--col-5,\\n  .--col-6,\\n  .--col-7,\\n  .--col-8,\\n  .--col-9,\\n  .--col-10,\\n  .--col-11,\\n  .--col-12 {\\n    width: 100% !important;\\n  }\\n}\\n\\n.--col-1 {\\n  width: 8.33333333%;\\n}\\n\\n.--col-2 {\\n  width: 16.66666667%;\\n}\\n\\n.--col-3 {\\n  width: 25%;\\n}\\n\\n.--col-4 {\\n  width: 33.33333333%;\\n}\\n\\n.--col-5 {\\n  width: 41.66666667%;\\n}\\n\\n.--col-6 {\\n  width: 50%;\\n}\\n\\n.--col-7 {\\n  width: 58.33333333%;\\n}\\n\\n.--col-8 {\\n  width: 66.66666667%;\\n}\\n\\n.--col-9 {\\n  width: 75%;\\n}\\n\\n.--col-10 {\\n  width: 83.33333333%;\\n}\\n\\n.--col-11 {\\n  width: 91.66666667%;\\n}\\n\\n.--col-12 {\\n  width: 100%;\\n}\\n","@use \\"breakpoints\\";\\n\\n$breakpoints: breakpoints.$breakpoints;\\n\\n@mixin from($bp) {\\n  @media (width >= #{breakpoints.get($bp)}) {\\n    @content;\\n  }\\n}\\n\\n@mixin until($bp) {\\n  @media (width < #{breakpoints.get($bp)}) {\\n    @content;\\n  }\\n}\\n\\n@mixin between($from, $until) {\\n  @media (#{breakpoints.get($from)} <= width < #{breakpoints.get($until)}) {\\n    @content;\\n  }\\n}\\n",".form-kit__object {\\n  display: flex;\\n  flex-direction: column;\\n  gap: var(--form-kit-gutter-y);\\n  width: 100%;\\n}\\n",".form-kit__collection {\\n  display: flex;\\n  flex-direction: column;\\n  gap: var(--form-kit-gutter-y);\\n  width: 100%;\\n}\\n","@use \\"lib/viewport\\";\\n\\n.form-kit__conditional-display {\\n  display: flex;\\n  flex-direction: column;\\n  gap: var(--space-4);\\n\\n  &-content {\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-3);\\n  }\\n}\\n\\n.--radio-cards {\\n  width: 100%;\\n\\n  .form-kit__conditional-display,\\n  .form-kit__field.--large .form-kit__container-content {\\n    width: 100%;\\n  }\\n\\n  .form-kit__inline-radio {\\n    gap: var(--space-2);\\n    width: 100%;\\n\\n    .form-kit__control-radio-label:not(.--disabled):hover {\\n      cursor: pointer;\\n      border-color: var(--tertiary);\\n    }\\n\\n    > * {\\n      width: 50%;\\n    }\\n\\n    .fk-d-tooltip__trigger-container {\\n      width: 100%;\\n    }\\n  }\\n\\n  .form-kit__control-radio-label {\\n    flex: 1 1 50%;\\n    padding: 0.5em var(--space-2);\\n    border: 1px solid var(--primary-low-mid);\\n    border-radius: var(--d-input-border-radius);\\n    justify-content: center;\\n    position: relative;\\n    line-height: normal;\\n\\n    &:has(:focus-visible) {\\n      outline: 1px solid var(--d-input-focused-color);\\n      border: 1px solid var(--d-input-focused-color);\\n    }\\n\\n    &.--disabled {\\n      color: var(--primary-medium);\\n      cursor: not-allowed;\\n    }\\n\\n    // Like --disabled, but the option stays clickable.\\n    &.--locked {\\n      color: var(--primary-medium);\\n      background: var(--d-input-bg-color--disabled);\\n\\n      .d-icon {\\n        color: currentcolor;\\n        display: inline-block;\\n      }\\n    }\\n\\n    .d-icon {\\n      display: none;\\n    }\\n\\n    input {\\n      position: absolute;\\n      width: 1px;\\n      height: 1px;\\n      opacity: 0;\\n    }\\n\\n    &:has(input[disabled]) {\\n      background: var(--d-input-bg-color--disabled);\\n\\n      .d-icon {\\n        color: currentcolor;\\n        display: inline-block;\\n      }\\n    }\\n\\n    &:has(input:checked) {\\n      color: var(--tertiary);\\n      border-color: var(--tertiary);\\n      background: var(--tertiary-very-low);\\n\\n      .d-icon {\\n        color: currentcolor;\\n        display: inline-block;\\n      }\\n    }\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.form-kit__container {\\n  display: flex;\\n  gap: 0.25rem;\\n  flex-direction: column;\\n  align-items: flex-start;\\n\\n  &.--full {\\n    width: 100%;\\n  }\\n\\n  @include viewport.until(sm) {\\n    width: 100%;\\n  }\\n\\n  &.--column {\\n    .form-kit__container-content {\\n      flex-direction: column;\\n    }\\n  }\\n\\n  &-title {\\n    display: inline;\\n    gap: 0.25em;\\n    margin: 0;\\n    font-size: var(--font-down-1-rem);\\n    color: var(--primary);\\n    font-weight: 600 !important;\\n  }\\n\\n  &-subtitle {\\n    display: flex;\\n    align-items: center;\\n    gap: 0.25em;\\n    margin: 0;\\n    font-size: var(--font-down-1-rem);\\n    color: var(--primary-medium);\\n\\n    > * {\\n      margin: 0;\\n    }\\n  }\\n\\n  &-optional {\\n    font-size: var(--font-down-2-rem);\\n    color: var(--primary-high-or-secondary-low);\\n    font-weight: normal;\\n  }\\n\\n  &-content {\\n    display: flex;\\n    gap: 0.25em;\\n    flex-direction: row;\\n    align-items: flex-start;\\n    max-width: 100%;\\n    width: var(--form-kit-medium-input);\\n\\n    @include viewport.until(sm) {\\n      width: 100%;\\n    }\\n  }\\n}\\n\\n.form-kit__container-title,\\n.form-kit__container-description,\\n.form-kit__container-content {\\n  .--small & {\\n    width: var(--form-kit-small-input);\\n  }\\n\\n  @include viewport.from(sm) {\\n    .--medium & {\\n      width: var(--form-kit-medium-input);\\n    }\\n\\n    .--large & {\\n      width: var(--form-kit-large-input);\\n    }\\n\\n    .--max & {\\n      max-width: var(--form-kit-max-input);\\n      width: 100%;\\n    }\\n\\n    .--full & {\\n      width: 100%;\\n      min-width: var(--form-kit-small-input);\\n    }\\n  }\\n}\\n\\n// Override: child has its own modifier from @titleFormat / @descriptionFormat.\\n// Lives in a separate block AFTER the cascade so on equal specificity, source\\n// order makes the explicit override win. Yes, this one sucks a bit. I know.\\n.form-kit__container-title,\\n.form-kit__container-description,\\n.form-kit__container-content {\\n  &.--small {\\n    width: var(--form-kit-small-input);\\n  }\\n\\n  @include viewport.from(sm) {\\n    &.--medium {\\n      width: var(--form-kit-medium-input);\\n    }\\n\\n    &.--large {\\n      width: var(--form-kit-large-input);\\n    }\\n\\n    &.--max {\\n      max-width: var(--form-kit-max-input);\\n      width: 100%;\\n    }\\n\\n    &.--full {\\n      width: 100%;\\n      min-width: var(--form-kit-small-input);\\n    }\\n  }\\n}\\n",".form-kit {\\n  &__control-checkbox {\\n    position: absolute;\\n    opacity: 0;\\n\\n    &-label {\\n      position: relative;\\n      display: flex;\\n      gap: 0.75em;\\n      margin: 0;\\n      font-weight: normal !important;\\n      color: var(--primary);\\n      font-size: var(--font-down-1-rem);\\n      cursor: pointer;\\n\\n      .form-kit__field[data-disabled] & {\\n        cursor: not-allowed;\\n      }\\n    }\\n  }\\n\\n  &__control-checkbox-checkmark {\\n    width: 1.25em;\\n    height: 1.25em;\\n    border: 2px solid var(--primary-low-mid);\\n    border-radius: 5px;\\n    align-items: center;\\n    display: flex;\\n    justify-content: center;\\n    position: relative;\\n    box-sizing: border-box;\\n    background: var(--secondary);\\n    flex-shrink: 0;\\n    overflow: hidden;\\n    transition: border 0.2s ease;\\n\\n    &::before {\\n      content: \\"\\";\\n      position: absolute;\\n      top: 50%;\\n      left: 50%;\\n      width: 50%;\\n      height: 50%;\\n      background: var(--tertiary);\\n      border-radius: 50%;\\n      transition: transform 0.35s cubic-bezier(0.4, 0, 0.2, 1);\\n      opacity: 0;\\n      transform: translate(-50%, -50%) scale(0);\\n    }\\n\\n    .d-icon {\\n      display: none;\\n      width: 75%;\\n      height: 75%;\\n    }\\n  }\\n\\n  &__control-checkbox-content {\\n    display: flex;\\n    flex-direction: column;\\n    gap: 0.25rem;\\n  }\\n\\n  &__control-checkbox-description {\\n    color: var(--primary-medium);\\n\\n    &:empty {\\n      display: none;\\n    }\\n  }\\n}\\n\\n.form-kit__control-checkbox-label:hover .form-kit__control-checkbox-checkmark {\\n  border-color: var(--tertiary);\\n}\\n\\n.form-kit__control-checkbox:checked + .form-kit__control-checkbox-checkmark {\\n  border-color: var(--tertiary-low);\\n\\n  &::before {\\n    opacity: 1;\\n    transform: translate(-50%, -50%) scale(3);\\n  }\\n\\n  .d-icon {\\n    display: initial;\\n    color: var(--secondary);\\n  }\\n}\\n",".form-kit__field[data-control-type=\\"code\\"] {\\n  .ace-wrapper {\\n    width: 100%;\\n\\n    > .loading-container {\\n      width: 100%;\\n    }\\n  }\\n\\n  .ace-wrapper[data-disabled=\\"true\\"] {\\n    opacity: 0.5;\\n\\n    .ace_scroller {\\n      cursor: not-allowed !important;\\n    }\\n  }\\n\\n  .ace-wrapper[data-disabled=\\"false\\"] {\\n    .ace_focus {\\n      outline: 2px solid var(--tertiary);\\n      outline-offset: -1px;\\n\\n      @include default-input {\\n        height: unset;\\n        border-color: var(--tertiary);\\n      }\\n    }\\n  }\\n}\\n\\n.form-kit__control-code {\\n  min-height: 250px !important;\\n  width: 100%;\\n  box-sizing: border-box;\\n\\n  .form-kit__field.has-error & {\\n    border-color: var(--danger);\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n@mixin default-input {\\n  width: 100%;\\n  height: var(--space-9);\\n  background: var(--token-color-background-input);\\n  border: 1px solid var(--primary-low-mid) !important;\\n  border-radius: var(--d-input-border-radius);\\n  padding: 0 0.5em !important;\\n  box-sizing: border-box;\\n  margin: 0 !important;\\n  appearance: none;\\n\\n  @content;\\n\\n  @include viewport.until(sm) {\\n    width: 100% !important;\\n  }\\n\\n  &:focus,\\n  &:focus-visible,\\n  &:focus:focus-visible,\\n  &:active {\\n    // these `!important` flags are another great case for having a button element without that pesky default styling\\n    &:not(:disabled) {\\n      background-color: var(--token-color-background-input) !important;\\n      color: var(--primary) !important;\\n      border-color: var(--token-color-background-accent-bolder);\\n      outline: 2px solid var(--token-color-background-accent-bolder);\\n      outline-offset: -2px;\\n\\n      .d-icon {\\n        color: inherit !important;\\n      }\\n    }\\n  }\\n\\n  &:hover:not(:disabled) {\\n    .discourse-no-touch & {\\n      background-color: var(--token-color-background-input);\\n      color: var(--primary);\\n      border-color: var(--token-color-background-accent-bolder);\\n\\n      .d-icon {\\n        color: inherit;\\n      }\\n    }\\n  }\\n\\n  .has-errors & {\\n    border-color: var(--danger);\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.form-kit__control-color {\\n  display: flex;\\n  flex-direction: column;\\n  gap: var(--space-2);\\n  width: 100%;\\n}\\n\\n.form-kit__control-color-input {\\n  --color-button-height: var(--space-9);\\n  --color-button-width: var(--space-9);\\n  display: flex;\\n  align-items: center;\\n  gap: var(--space-1);\\n}\\n\\n.form-kit__control-color-input-prefix {\\n  border: 1px solid var(--primary-low-mid);\\n  border-right: 0;\\n  padding-inline: var(--space-2);\\n  box-sizing: border-box;\\n  background: var(--primary-low);\\n  display: flex;\\n  align-items: center;\\n  margin-right: -0.25em;\\n  border-radius: var(--d-input-border-radius) 0 0 var(--d-input-border-radius);\\n  align-self: stretch;\\n}\\n\\n.form-kit__control-color-input-hex {\\n  @include default-input;\\n  width: 5.5em;\\n  min-width: auto !important;\\n\\n  .form-kit__control-color-input-prefix + & {\\n    border-radius: 0 var(--d-input-border-radius) var(--d-input-border-radius) 0;\\n    border-left: none;\\n  }\\n\\n  // Wider when no prefix (named colors mode) to accommodate longer values\\n  &:first-child {\\n    width: 8em;\\n  }\\n\\n  .form-kit__field.has-error & {\\n    border-color: var(--danger);\\n  }\\n}\\n\\n.form-kit__control-color-picker-wrapper {\\n  position: relative;\\n  display: inline-flex;\\n\\n  .d-icon {\\n    position: absolute;\\n    top: 50%;\\n    left: 50%;\\n    transform: translate(-50%, -50%);\\n    pointer-events: none;\\n    font-size: var(--font-down-1);\\n  }\\n\\n  &.--is-light .d-icon {\\n    color: black;\\n  }\\n\\n  &.--is-dark .d-icon {\\n    color: white;\\n  }\\n}\\n\\n.form-kit__control-color-input-picker[type=\\"color\\"] {\\n  --color-input-border-width: 1px;\\n  width: var(--color-button-width);\\n  height: var(--color-button-height);\\n  padding: 0;\\n  border: var(--color-input-border-width) solid var(--primary-low-mid);\\n  border-radius: var(--d-button-border-radius);\\n  cursor: pointer;\\n\\n  &::-webkit-color-swatch-wrapper {\\n    padding: 2px;\\n  }\\n\\n  &::-webkit-color-swatch {\\n    border: none;\\n    border-radius: calc(\\n      var(--d-button-border-radius) - var(--color-input-border-width)\\n    );\\n  }\\n\\n  &::-moz-color-swatch {\\n    border: none;\\n    border-radius: calc(\\n      var(--d-button-border-radius) - var(--color-input-border-width)\\n    );\\n  }\\n\\n  &:focus,\\n  &:focus-visible {\\n    &:not(:disabled) {\\n      border-color: var(--tertiary);\\n      outline: 2px solid var(--tertiary);\\n      outline-offset: -2px;\\n    }\\n  }\\n\\n  &:disabled {\\n    cursor: not-allowed;\\n    opacity: 0.5;\\n  }\\n}\\n\\n.form-kit__control-color-swatches-btn {\\n  --d-button-default-border: 1px solid var(--d-button-default-bg-color); // match input height\\n  width: var(--color-button-width);\\n  height: var(--color-button-height);\\n}\\n\\n.form-kit__control-color-swatches {\\n  display: flex;\\n  flex-wrap: wrap;\\n  gap: 0.25em;\\n\\n  @include viewport.from(sm) {\\n    // 10 swatches per row on larger screens\\n    max-width: calc((var(--space) * 9) + (var(--space-5) * 10));\\n  }\\n\\n  &-label {\\n    width: 100%;\\n    display: flex;\\n    justify-content: space-between;\\n  }\\n\\n  .color-swatches-menu-content & {\\n    padding: var(--space-2);\\n  }\\n}\\n\\n.color-swatches-menu-content {\\n  .fk-d-menu__inner-content {\\n    display: flex;\\n    flex-direction: column;\\n  }\\n}\\n\\n.form-kit__control-color-swatch {\\n  width: var(--space-5);\\n  height: var(--space-5);\\n  padding: 0;\\n  border: 1px solid var(--primary-medium);\\n  border-radius: 2px;\\n  cursor: pointer;\\n  display: flex;\\n  align-items: center;\\n  justify-content: center;\\n\\n  &:hover {\\n    transform: scale(1.1);\\n  }\\n\\n  &:disabled {\\n    cursor: not-allowed;\\n    opacity: 0.5;\\n\\n    &:hover {\\n      transform: none;\\n    }\\n  }\\n}\\n",".form-kit__control-composer {\\n  // same default effective height (150px) than a text control\\n  height: 189px;\\n  width: 100%;\\n\\n  .d-editor-preview-wrapper {\\n    display: none;\\n  }\\n\\n  &.--preview {\\n    .d-editor-preview-wrapper {\\n      display: block;\\n    }\\n  }\\n\\n  .d-editor-button-bar {\\n    > .btn {\\n      border-radius: 0;\\n    }\\n  }\\n\\n  .d-editor-textarea-wrapper {\\n    @include default-input {\\n      padding: 0 !important;\\n    }\\n  }\\n\\n  .d-editor-input {\\n    // same padding than a text control\\n    padding: 0.5em;\\n  }\\n}\\n",".form-kit__control-icon {\\n  .d-icon-grid-picker {\\n    width: 100%;\\n    min-width: var(--form-kit-small-input);\\n  }\\n\\n  .d-icon-grid-pi