ap: 1.5em;\\n  align-items: flex-start;\\n\\n  .alert {\\n    // we space elements with gap, so don't need the margin\\n    margin-bottom: 0;\\n  }\\n}\\n",".form-kit__meta {\\n  display: flex;\\n  flex-wrap: nowrap;\\n  justify-content: space-between;\\n  align-items: start;\\n  gap: 0.25em;\\n  font-size: var(--font-down-2-rem);\\n  color: var(--primary-high);\\n  width: 100%;\\n  min-height: 20px;\\n  line-height: var(--line-height-medium);\\n\\n  &-description {\\n    margin: 0;\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.form-kit__row {\\n  display: flex;\\n  flex-wrap: wrap;\\n  margin-right: calc(-0.5 * var(--form-kit-gutter-x));\\n  margin-left: calc(-0.5 * var(--form-kit-gutter-x));\\n  row-gap: calc(var(--form-kit-gutter-y) + 1.75em);\\n  padding-top: 1.75em;\\n  width: 100%;\\n\\n  > * {\\n    flex-shrink: 0;\\n    padding-right: calc(var(--form-kit-gutter-x) * 0.5);\\n    padding-left: calc(var(--form-kit-gutter-x) * 0.5);\\n  }\\n\\n  > *:not(.col-*) {\\n    width: 100%;\\n  }\\n\\n  .form-kit__container-content {\\n    width: 100% !important;\\n  }\\n\\n  .form-kit__col:not(:has(.form-kit__button)) {\\n    position: relative;\\n  }\\n\\n  .form-kit__button {\\n    height: 2.25em;\\n\\n    @include viewport.from(sm) {\\n      height: 2em;\\n    }\\n  }\\n\\n  .form-kit__container-title {\\n    position: absolute;\\n    top: -1.75em;\\n  }\\n}\\n",".form-kit__section {\\n  display: flex;\\n  flex-direction: column;\\n  gap: 1.5rem;\\n  width: 100%;\\n\\n  &.form-kit__actions {\\n    align-items: center;\\n    flex-direction: row;\\n    gap: 1rem;\\n  }\\n}\\n\\n.form-kit__section-title {\\n  margin: 0;\\n  font-size: var(--font-up-1);\\n}\\n\\n.form-kit__section-header {\\n  border-bottom: 1px solid var(--content-border-color);\\n  padding-bottom: 0.5em;\\n}\\n\\n.form-kit__section-subtitle {\\n  margin-top: calc(var(--space-4) * -1); // Offset the gap of the section\\n  color: var(--primary-medium);\\n  font-size: var(--font-down-1);\\n}\\n\\n.form-kit__section.emphasis {\\n  border: 2px solid var(--content-border-color);\\n  border-radius: var(--d-border-radius);\\n  padding: 1em;\\n  box-sizing: border-box;\\n\\n  &.emphasis-success {\\n    border-color: var(--success-medium);\\n  }\\n\\n  &.emphasis-error {\\n    border-color: var(--danger-medium);\\n  }\\n\\n  &.emphasis-warning {\\n    border-color: var(--highlight);\\n  }\\n\\n  &.emphasis-info {\\n    border-color: var(--tertiary-medium);\\n  }\\n}\\n",":root {\\n  --form-kit-gutter-x: 1rem;\\n  --form-kit-gutter-y: 1rem;\\n  --form-kit-max-input: 75ch;\\n  --form-kit-large-input: 325px;\\n  --form-kit-medium-input: 200px;\\n  --form-kit-small-input: 75px;\\n}\\n",".form-kit__tooltip {\\n  color: var(--primary-medium);\\n}\\n",".fk-d-menu {\\n  width: max-content;\\n  position: absolute;\\n  top: 0;\\n  max-width: 600px;\\n  display: flex;\\n  padding: 0;\\n  z-index: calc(z(\\"composer\\", \\"dropdown\\") + 1);\\n\\n  &__trigger {\\n    .touch & {\\n      @include unselectable;\\n    }\\n  }\\n\\n  &.-animated {\\n    @include d-animation(float-down, 250ms, ease);\\n\\n    &.-closing {\\n      @include d-animation(dissolve-up, 125ms, ease);\\n    }\\n\\n    &[data-placement^=\\"bottom\\"] {\\n      transform-origin: top center;\\n    }\\n\\n    &[data-placement^=\\"top\\"] {\\n      @include d-animation(float-up, 250ms, ease);\\n      transform-origin: bottom center;\\n\\n      &.-closing {\\n        @include d-animation(dissolve-down, 125ms, ease);\\n      }\\n    }\\n\\n    &[data-placement^=\\"right\\"] {\\n      transform-origin: center left;\\n    }\\n\\n    &[data-placement^=\\"left\\"] {\\n      transform-origin: center right;\\n    }\\n  }\\n\\n  &[data-strategy=\\"fixed\\"] {\\n    position: fixed;\\n  }\\n\\n  &__inner-content {\\n    display: flex;\\n    border-radius: var(--d-border-radius);\\n    background-color: var(--secondary);\\n    border: 1px solid var(--content-border-color);\\n    box-shadow: var(--shadow-dropdown);\\n    overscroll-behavior: contain;\\n    overflow: auto;\\n  }\\n\\n  .arrow {\\n    position: absolute;\\n    color: var(--secondary);\\n  }\\n\\n  &[data-placement^=\\"top\\"] {\\n    .arrow {\\n      bottom: -9px;\\n      rotate: 180deg;\\n    }\\n  }\\n\\n  &[data-placement^=\\"bottom\\"] {\\n    .arrow {\\n      top: -10px;\\n    }\\n  }\\n\\n  &[data-placement^=\\"right\\"] {\\n    .arrow {\\n      rotate: -90deg;\\n      left: -9px;\\n    }\\n  }\\n\\n  &[data-placement^=\\"left\\"] {\\n    .arrow {\\n      rotate: 90deg;\\n      right: -9px;\\n    }\\n  }\\n}\\n\\n// should probably be renamed fk-d-menu__list\\n.dropdown-menu {\\n  min-width: 200px;\\n  display: flex;\\n  flex-direction: column;\\n  gap: var(--d-sidebar-vertical-gap);\\n  padding: var(--space-1);\\n  margin: 0;\\n  list-style: none;\\n\\n  &__item {\\n    .btn {\\n      @include menu-item;\\n    }\\n  }\\n\\n  &__divider {\\n    margin: 0;\\n  }\\n\\n  &__subheader {\\n    padding: var(--space-2) var(--d-sidebar-row-horizontal-padding)\\n      var(--space-1);\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1-rem);\\n    font-weight: bold;\\n  }\\n}\\n","// used when @modalForMobile={{true}} is set on the d-menu component\\n.fk-d-menu-modal {\\n  z-index: z(\\"modal\\", \\"content\\");\\n\\n  &__grip {\\n    position: absolute;\\n    top: 2.5px;\\n    left: 50%;\\n    transform: translateX(-50%);\\n    background: var(--primary-medium);\\n    height: 5px;\\n    width: 15vw;\\n    max-width: 100px;\\n    border-radius: 10px;\\n  }\\n\\n  .d-modal__body {\\n    padding: 1em 0;\\n  }\\n\\n  h3 {\\n    padding-top: 0.25em;\\n  }\\n\\n  .dropdown-menu {\\n    li a:focus-visible {\\n      outline: 0;\\n    }\\n\\n    &__item {\\n      .btn {\\n        border-radius: 0; // overruling the general border-radius var on all btns\\n        // all specific overrules to make sure touch devices don't show focus states, which we apply on opening of the menu\\n        &:focus-visible,\\n        &:active {\\n          .discourse-touch & {\\n            background: transparent;\\n            color: var(--primary);\\n\\n            .d-icon {\\n              color: inherit;\\n            }\\n\\n            &.btn-danger {\\n              background: transparent;\\n              color: var(--danger);\\n\\n              .d-icon {\\n                color: var(--danger-hover);\\n              }\\n            }\\n          }\\n        }\\n      }\\n    }\\n\\n    li > .btn,\\n    li > a {\\n      padding: 0.75em 1rem;\\n    }\\n  }\\n}\\n","@keyframes d-tooltip-opening {\\n  0% {\\n    opacity: 0;\\n  }\\n\\n  100% {\\n    opacity: 1;\\n  }\\n}\\n\\n.fk-d-tooltip {\\n  &__trigger {\\n    display: inline-flex;\\n    cursor: pointer;\\n\\n    .touch & {\\n      @include unselectable;\\n    }\\n\\n    &-container {\\n      display: flex;\\n    }\\n  }\\n\\n  &__inner-content {\\n    box-sizing: border-box;\\n    display: flex;\\n    max-height: 60dvh;\\n    overflow-x: hidden;\\n    overflow-y: auto;\\n    overscroll-behavior: contain;\\n    overflow-wrap: break-word;\\n    padding: 0.5rem;\\n\\n    // `safe` so content taller than the cap starts at the top instead of being centred,\\n    // which would put the first lines above the scrollport and out of reach\\n    align-items: safe center;\\n  }\\n\\n  &__content {\\n    background-color: var(--secondary);\\n    border-radius: var(--d-border-radius);\\n    border: 1px solid var(--content-border-color);\\n    box-shadow: var(--shadow-dropdown);\\n    z-index: z(\\"max\\");\\n    width: max-content;\\n    position: absolute;\\n    top: 0;\\n    display: flex !important;\\n    padding: 0;\\n\\n    &.-animated {\\n      animation: d-tooltip-opening 0.15s ease-in;\\n\\n      &[data-placement^=\\"bottom\\"] {\\n        transform-origin: top center;\\n      }\\n\\n      &[data-placement^=\\"top\\"] {\\n        transform-origin: bottom center;\\n      }\\n\\n      &[data-placement^=\\"right\\"] {\\n        transform-origin: center left;\\n      }\\n\\n      &[data-placement^=\\"left\\"] {\\n        transform-origin: center right;\\n      }\\n    }\\n\\n    .arrow {\\n      z-index: z(\\"max\\");\\n      position: absolute;\\n    }\\n\\n    &[data-placement^=\\"top\\"] {\\n      .arrow {\\n        bottom: -11px;\\n        rotate: 180deg;\\n      }\\n    }\\n\\n    &[data-placement^=\\"top-start\\"] {\\n      .arrow {\\n        margin-left: 10px;\\n      }\\n    }\\n\\n    &[data-placement^=\\"bottom\\"] {\\n      .arrow {\\n        top: -11px;\\n      }\\n    }\\n\\n    &[data-placement^=\\"right\\"] {\\n      .arrow {\\n        rotate: -90deg;\\n        left: -11px;\\n      }\\n    }\\n\\n    &[data-placement^=\\"left\\"] {\\n      .arrow {\\n        rotate: 90deg;\\n        right: -11px;\\n      }\\n    }\\n  }\\n}\\n",".fk-d-button-tooltip {\\n  display: inline-flex;\\n  align-items: center;\\n\\n  .fk-d-tooltip__trigger {\\n    background: var(--primary-very-low);\\n    height: 100%;\\n    align-items: center;\\n    display: flex;\\n    padding-inline: 0.5rem;\\n  }\\n}\\n","@keyframes d-toast-opening {\\n  from {\\n    transform: translateY(var(--transform-y, 10px));\\n  }\\n}\\n\\n.fk-d-toasts {\\n  --transform-y: 0;\\n  position: fixed;\\n  top: calc(var(--header-offset) + 0.33rem);\\n  right: 5px;\\n  z-index: z(\\"max\\");\\n  display: flex;\\n  flex-direction: column;\\n  gap: 5px 0;\\n  flex: 1 1 auto;\\n\\n  .mobile-view & {\\n    left: 5px;\\n  }\\n\\n  .fk-d-toast {\\n    box-sizing: border-box;\\n    opacity: 1;\\n    transition: opacity 0.5s;\\n    border-radius: var(--d-border-radius);\\n    overflow: hidden;\\n    background-color: var(--secondary);\\n    border: 1px solid var(--content-border-color);\\n    box-shadow: var(--shadow-dropdown);\\n    overflow-wrap: break-word;\\n    display: flex;\\n    animation: d-toast-opening 0.3s ease-in-out;\\n    will-change: transform;\\n\\n    .desktop-view & {\\n      margin-left: auto;\\n    }\\n\\n    &:hover {\\n      border-color: var(--primary-300);\\n    }\\n\\n    &.-fade-out {\\n      opacity: 0;\\n    }\\n\\n    & + .d-toast {\\n      margin-top: 0.25rem;\\n    }\\n  }\\n}\\n\\n@media (prefers-reduced-motion: no-preference) {\\n  .fk-d-toasts {\\n    --transform-y: 2vh;\\n  }\\n}\\n",".fk-d-default-toast {\\n  display: flex;\\n  flex: 1 1 auto;\\n  padding: 0.5rem;\\n\\n  &__close-container {\\n    width: calc(40px - 0.5rem);\\n    height: calc(1em + (2 * 0.65em));\\n  }\\n\\n  &__icon-container {\\n    flex: 1 0 auto;\\n    display: flex;\\n    width: calc(40px - 0.5rem);\\n    height: calc(1em + (2 * 0.65em));\\n    align-items: center;\\n    justify-content: center;\\n\\n    &.alert-success {\\n      background-color: var(--success-low);\\n      color: var(--primary);\\n    }\\n\\n    &.alert-error {\\n      background-color: var(--danger-low);\\n      color: var(--primary);\\n    }\\n\\n    &.alert-warning {\\n      background-color: var(--highlight-bg);\\n      color: var(--primary);\\n    }\\n\\n    &.alert-info {\\n      background-color: var(--tertiary-low);\\n      color: var(--primary);\\n\\n      &.clickable {\\n        color: var(--tertiary);\\n        z-index: z(\\"base\\");\\n      }\\n    }\\n\\n    .-success & {\\n      .d-icon {\\n        color: var(--success);\\n      }\\n    }\\n\\n    .-error & {\\n      .d-icon {\\n        color: var(--danger);\\n      }\\n    }\\n\\n    .-warning & {\\n      .d-icon {\\n        color: var(--highlight);\\n      }\\n    }\\n\\n    .-info & {\\n      .d-icon {\\n        color: var(--tertiary);\\n      }\\n    }\\n  }\\n\\n  &__main-container {\\n    box-sizing: border-box;\\n    display: flex;\\n    flex-direction: column;\\n    width: 100%;\\n    min-height: calc(1em + (2 * 0.65em));\\n  }\\n\\n  &__progress-bar {\\n    width: 100%;\\n    height: 5px;\\n    top: 0;\\n    left: 0;\\n    position: absolute;\\n    background-color: var(--success);\\n    transform-origin: 0 0;\\n  }\\n\\n  .fk-d-default-toast:has(&__progress-bar) {\\n    padding-top: 15px;\\n  }\\n\\n  &__texts {\\n    min-height: inherit;\\n    display: flex;\\n    justify-content: center;\\n    flex-direction: column;\\n  }\\n\\n  &__actions {\\n    display: flex;\\n    flex-wrap: wrap;\\n    padding-top: 1rem;\\n    margin-bottom: -0.5rem;\\n\\n    .btn {\\n      margin-right: 0.5rem;\\n      margin-bottom: 0.5rem;\\n    }\\n  }\\n\\n  &__title {\\n    display: flex;\\n    font-weight: 700;\\n  }\\n\\n  &__message {\\n    display: flex;\\n    color: var(--primary-high);\\n  }\\n}\\n",".select-kit {\\n  &.categories-admin-dropdown {\\n    .select-kit-body {\\n      min-width: auto;\\n      width: 250px;\\n    }\\n\\n    .select-kit-header .d-icon {\\n      justify-content: space-between;\\n    }\\n  }\\n}\\n",".select-kit {\\n  &.combo-box {\\n    &.category-chooser {\\n      width: 300px;\\n\\n      .select-kit-row {\\n        display: flex;\\n        align-items: flex-start;\\n        flex-direction: column;\\n\\n        &.none {\\n          .topic-count {\\n            display: none;\\n          }\\n        }\\n\\n        .topic-count {\\n          font-size: var(--font-down-1);\\n          color: var(--primary-medium);\\n          white-space: nowrap;\\n          margin-left: 0.5em;\\n          font-weight: normal;\\n        }\\n\\n        .category-status {\\n          color: var(--primary);\\n          line-height: var(--line-height-large);\\n          flex: 1 1 auto;\\n        }\\n\\n        .category-desc {\\n          flex: 1 1 auto;\\n          font-size: var(--font-down-1);\\n          line-height: var(--line-height-large);\\n        }\\n      }\\n    }\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.select-kit {\\n  &.combo-box {\\n    &.category-drop {\\n      min-width: auto;\\n\\n      .badge-category__wrapper {\\n        font-size: var(--font-0);\\n        font-weight: normal;\\n        max-width: 260px;\\n      }\\n\\n      .category-drop-header {\\n        &[data-value=\\"\\"] {\\n          color: var(--primary-high);\\n        }\\n\\n        &.is-none .selected-name {\\n          color: inherit;\\n        }\\n      }\\n\\n      .angle-icon {\\n        color: var(--primary-high);\\n      }\\n\\n      &.has-selection {\\n        .category-drop-header {\\n          border-color: var(--d-nav-border-color--active);\\n        }\\n      }\\n\\n      .select-kit-row {\\n        flex-direction: column;\\n        align-items: flex-start;\\n\\n        &[data-value=\\"all-categories\\"],\\n        &[data-value=\\"no-categories\\"] {\\n          color: var(--tertiary);\\n          font-weight: 700;\\n        }\\n\\n        .category-desc {\\n          font-weight: normal;\\n          color: var(--primary-medium);\\n          margin-top: 2px;\\n        }\\n\\n        .category-status {\\n          align-items: center;\\n        }\\n\\n        .topic-count {\\n          margin-left: 0.5em;\\n          font-weight: normal;\\n          color: var(--primary-medium);\\n          font-size: var(--font-down-1);\\n        }\\n      }\\n\\n      .category-drop-footer {\\n        align-items: center;\\n        border-top: 1px solid var(--content-border-color);\\n        display: flex;\\n        font-size: var(--font-down-1);\\n        height: 30px;\\n        justify-content: space-between;\\n        width: 100%;\\n\\n        a,\\n        span {\\n          color: var(--primary-high);\\n          margin: 0 10px;\\n\\n          &.active {\\n            display: none;\\n          }\\n        }\\n      }\\n    }\\n  }\\n}\\n",".select-kit {\\n  .select-kit-row.category-row {\\n    flex-direction: column;\\n    align-items: flex-start;\\n\\n    .category-status {\\n      display: flex;\\n      align-items: baseline;\\n      max-width: 100%;\\n      flex: 1 1 auto;\\n      gap: 0 0.5em;\\n    }\\n\\n    .category-desc p {\\n      margin: 0;\\n    }\\n\\n    .category-desc {\\n      margin: 0;\\n      font-size: var(--font-down-1);\\n      color: var(--primary-medium);\\n    }\\n\\n    .topic-count {\\n      white-space: nowrap;\\n    }\\n\\n    .read-only {\\n      padding: 0.1em 0.5em;\\n      margin: 0 0 0.25em 0.5em;\\n      border-radius: 8px;\\n      color: var(--secondary);\\n      font-size: var(--font-down-1);\\n      background: var(--primary-low-mid);\\n    }\\n  }\\n}\\n",".select-kit,\\n.select-kit-box {\\n  &.category-selector,\\n  &.multiple-categories-selector {\\n    .category-row {\\n      max-width: 100%;\\n\\n      .category-status {\\n        gap: 0 0.5em;\\n      }\\n\\n      .topic-count {\\n        margin-left: 0.25em;\\n      }\\n\\n      .plus-subcategories {\\n        font-size: var(--font-down-2);\\n        margin-left: 0.25em;\\n      }\\n    }\\n\\n    .selected-choice-category {\\n      .badge-category .d-icon {\\n        margin: 0;\\n      }\\n\\n      .badge-category__wrapper + .badge-category__wrapper {\\n        margin-inline-start: var(--space-1);\\n      }\\n\\n      &:hover,\\n      &:focus {\\n        .badge-category {\\n          color: var(--d-button-default-text-color--hover);\\n        }\\n      }\\n    }\\n  }\\n}\\n",".select-kit {\\n  &.combo-box {\\n    &.color-palettes {\\n      .color-palettes-row {\\n        .palettes {\\n          display: flex;\\n          align-items: center;\\n          margin-left: 0.5em;\\n          flex: 1 0 0;\\n          padding: 8px;\\n\\n          .palette {\\n            height: 15px;\\n            width: 15px;\\n            display: block;\\n          }\\n        }\\n      }\\n    }\\n  }\\n}\\n",".select-kit {\\n  &.color-palette-picker {\\n    .color-palette-picker-row {\\n      gap: 0.5em;\\n      position: relative;\\n\\n      &__badge {\\n        padding: 0.07rem 0.15rem;\\n        border-radius: 4px;\\n        letter-spacing: 0.25px;\\n        align-items: center;\\n        display: inline-flex;\\n        gap: 0.25rem;\\n        background-color: var(--tertiary);\\n        color: var(--secondary);\\n        position: absolute;\\n        left: 10px;\\n        top: 10px;\\n        font-size: var(--font-down-6);\\n        text-transform: uppercase;\\n      }\\n\\n      &__preview {\\n        background: var(--secondary--preview, #fff);\\n        padding: 5px;\\n\\n        svg {\\n          height: 40px;\\n        }\\n      }\\n    }\\n  }\\n}\\n",".select-kit {\\n  &.combo-box {\\n    .select-kit-body {\\n      border-radius: 0;\\n    }\\n\\n    .select-kit-row {\\n      margin: 0;\\n      min-height: 1px;\\n\\n      &.no-content {\\n        font-weight: normal;\\n      }\\n    }\\n\\n    .select-kit-filter {\\n      .filter-input,\\n      .filter-input:focus,\\n      .filter-input:active {\\n        flex: 1;\\n      }\\n\\n      .filter-icon {\\n        margin-left: 0.25em;\\n      }\\n    }\\n\\n    .select-kit-header {\\n      background: var(--secondary);\\n      border-color: var(--input-border-color);\\n\\n      &.is-focused {\\n        @include default-focus;\\n      }\\n    }\\n\\n    .select-kit-collection {\\n      display: flex;\\n      flex-direction: column;\\n      padding: 0;\\n      min-width: 100px;\\n\\n      .collection-header {\\n        a {\\n          white-space: nowrap;\\n          line-height: var(--line-height-medium);\\n          font-weight: bold;\\n          display: block;\\n          padding: 0.75em;\\n          color: var(--tertiary);\\n\\n          &:hover {\\n            text-decoration: underline;\\n          }\\n        }\\n      }\\n    }\\n\\n    &.is-disabled {\\n      .select-kit-header {\\n        background: var(--d-input-bg-color--disabled);\\n        border-color: var(--primary-low-mid);\\n        color: var(--primary-medium);\\n\\n        .d-icon {\\n          color: var(--primary-medium);\\n        }\\n      }\\n    }\\n\\n    &.is-highlighted {\\n      .select-kit-header {\\n        @include default-focus;\\n      }\\n    }\\n\\n    &.tag-drop,\\n    &.group-dropdown {\\n      min-width: auto;\\n    }\\n\\n    &.tag-drop {\\n      color: var(--primary-high);\\n    }\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.select-kit {\\n  &.single-select {\\n    &.dropdown-select-box {\\n      display: inline-flex;\\n      min-width: auto;\\n      border: none;\\n      white-space: nowrap;\\n\\n      .select-kit-body {\\n        border: 1px solid var(--content-border-color);\\n        background-clip: padding-box;\\n        box-shadow: var(--shadow-dropdown);\\n        border-radius: var(--d-border-radius);\\n      }\\n\\n      .select-kit-row {\\n        margin: 0;\\n\\n        .icons {\\n          display: flex;\\n          align-self: flex-start;\\n          margin-right: 0.5em;\\n\\n          .d-icon {\\n            flex: 0 0 100%;\\n            overflow: hidden;\\n            font-size: var(--font-up-2);\\n            margin-right: 0;\\n          }\\n        }\\n\\n        .texts {\\n          line-height: var(--line-height-medium);\\n          flex: 1 1 0%;\\n          align-items: flex-start;\\n          display: flex;\\n          flex-wrap: wrap;\\n          flex-direction: column;\\n\\n          .name {\\n            flex: 1 1 auto;\\n            font-weight: bold;\\n            font-size: var(--font-0);\\n            color: var(--primary);\\n            padding: 0;\\n            max-width: 100%;\\n\\n            @include ellipsis;\\n\\n            @include viewport.until(sm) {\\n              font-weight: normal;\\n            }\\n          }\\n\\n          .desc {\\n            flex: 1 1 auto;\\n            font-size: var(--font-down-1);\\n            font-weight: normal;\\n            color: var(--primary-medium);\\n            white-space: normal;\\n          }\\n        }\\n\\n        @include viewport.until(sm) {\\n          .svg-icon-title {\\n            width: auto;\\n            height: auto;\\n          }\\n        }\\n      }\\n\\n      .select-kit-collection {\\n        padding: 0;\\n        max-height: 100%;\\n\\n        @include viewport.until(sm) {\\n          overflow-y: auto;\\n        }\\n      }\\n\\n      .select-kit-header {\\n        displ