n      .d-icon + .name {\\n        margin-left: 0.5em;\\n      }\\n\\n      .name {\\n        display: inline-flex;\\n        gap: 0.5em;\\n        min-width: 0;\\n\\n        > .d-icon {\\n          margin-left: 0.5em;\\n          margin-right: 0;\\n        }\\n      }\\n\\n      > .d-icon {\\n        margin-right: 0;\\n      }\\n\\n      &.select-kit-selected-color {\\n        border-bottom-width: 5px;\\n        border-bottom-style: solid;\\n      }\\n    }\\n\\n    .btn-clear {\\n      margin-left: 0.25em;\\n      padding: 0 0.2em;\\n      border: 0;\\n      background: none;\\n      min-height: auto;\\n    }\\n\\n    .icon {\\n      margin-right: 5px;\\n    }\\n\\n    .angle-icon {\\n      margin-left: auto;\\n      margin-right: 0;\\n      padding-left: 5px;\\n      pointer-events: none;\\n      color: var(--primary-medium);\\n    }\\n\\n    .d-button-label {\\n      display: flex;\\n      align-items: center;\\n      white-space: nowrap;\\n      overflow: hidden;\\n      line-height: var(--line-height-medium);\\n\\n      .d-icon {\\n        margin-left: 5px;\\n        margin-right: 0;\\n      }\\n    }\\n  }\\n\\n  .select-kit-body {\\n    display: none;\\n    background: var(--secondary);\\n    box-sizing: border-box;\\n    width: max-content;\\n\\n    .selected-content {\\n      max-height: 300px;\\n      overflow-y: auto;\\n    }\\n  }\\n\\n  .select-kit-row {\\n    cursor: pointer;\\n    outline: none;\\n    display: flex;\\n    flex: 1 0 auto;\\n    box-sizing: border-box;\\n    align-items: center;\\n    justify-content: flex-start;\\n    padding: 0.5em;\\n\\n    @include viewport.until(sm) {\\n      padding-block: 0.75em;\\n    }\\n\\n    &.disabled {\\n      pointer-events: none;\\n      opacity: 0.4;\\n    }\\n\\n    > * {\\n      pointer-events: none;\\n    }\\n\\n    .name {\\n      margin: 0;\\n      overflow: hidden;\\n      text-overflow: ellipsis;\\n      flex: 1 1 0%;\\n    }\\n\\n    .d-icon + .name,\\n    .svg-icon-title + .name {\\n      margin-left: 0.5em;\\n    }\\n\\n    &.is-highlighted {\\n      background: var(--d-hover);\\n    }\\n\\n    &.is-selected,\\n    &.is-selected.is-highlighted {\\n      background: var(--d-selected);\\n      color: var(--d-selected-text-color);\\n    }\\n\\n    .discourse-tag,\\n    .discourse-tag:visited,\\n    .discourse-tag:hover {\\n      color: var(--primary-high);\\n    }\\n\\n    &.create-color-row {\\n      border-left-style: solid;\\n      border-left-width: 5px;\\n    }\\n  }\\n\\n  .select-kit-collection {\\n    overflow-x: hidden;\\n    overflow-y: auto;\\n    margin: 0;\\n    max-height: 250px;\\n    width: 100%;\\n\\n    &:hover .select-kit-row.is-highlighted:hover {\\n      background: var(--d-hover);\\n    }\\n\\n    &:hover .select-kit-row.is-selected.is-highlighted:hover {\\n      background: var(--d-selected-hover);\\n    }\\n\\n    .validation-message {\\n      white-space: nowrap;\\n      color: var(--danger);\\n      flex: 1 0 auto;\\n      margin: 5px;\\n      padding: 0 2px;\\n    }\\n\\n    &::-webkit-scrollbar {\\n      appearance: none;\\n      width: 10px;\\n    }\\n\\n    &::-webkit-scrollbar-thumb {\\n      cursor: pointer;\\n      border-radius: 5px;\\n      background: var(--primary-med-or-secondary-med);\\n    }\\n\\n    &::-webkit-scrollbar-track {\\n      background: transparent;\\n      border-radius: 0;\\n    }\\n  }\\n\\n  .select-kit-filter {\\n    box-sizing: border-box;\\n    align-items: center;\\n    justify-content: space-between;\\n    width: 100%;\\n    position: relative;\\n\\n    .filter-input {\\n      background: none;\\n      margin: 0;\\n      padding: 0;\\n      flex: 1 0 0px;\\n      outline: none;\\n      border: 0;\\n      border-radius: 0;\\n      box-shadow: none;\\n      width: 100%;\\n      box-sizing: border-box;\\n      min-height: 30px;\\n\\n      @include viewport.until(sm) {\\n        font-size: var(--font-0);\\n      }\\n    }\\n\\n    &.is-hidden {\\n      width: 1px;\\n      height: 1px;\\n      border: 0;\\n      margin: -1px;\\n      padding: 0;\\n      overflow: hidden;\\n      position: fixed;\\n      outline: 0;\\n      left: 0;\\n      top: 0;\\n    }\\n  }\\n\\n  .select-kit-errors-collection {\\n    background: var(--danger);\\n    padding: 0.25em 1em;\\n    margin: 0;\\n    width: 100%;\\n    box-sizing: border-box;\\n\\n    .select-kit-error {\\n      list-style: none;\\n      color: var(--secondary);\\n    }\\n  }\\n\\n  .no-content,\\n  .results-count {\\n    display: flex;\\n    flex: 1 0 auto;\\n    padding: 0.5em;\\n    width: 100%;\\n    box-sizing: border-box;\\n    background: var(--secondary);\\n  }\\n\\n  .results-count {\\n    font-size: var(--font-down-1);\\n    color: var(--primary-med-or-secondary-med);\\n    position: absolute;\\n    clip-path: inset(50%);\\n    padding: 0;\\n    border: 0;\\n    height: 1px;\\n    width: 1px;\\n    overflow: hidden;\\n    white-space: nowrap;\\n  }\\n\\n  @keyframes lineDrawToRight {\\n    0% {\\n      width: 0;\\n    }\\n\\n    100% {\\n      width: 100%;\\n    }\\n  }\\n}\\n",".select-kit.single-select {\\n  .select-kit-filter {\\n    display: flex;\\n\\n    &.is-expanded {\\n      border-bottom: 1px solid var(--content-border-color);\\n    }\\n  }\\n\\n  &.is-expanded .select-kit-header:not(.btn),\\n  .select-kit-header:not(.btn):focus,\\n  .select-kit-header:not(.btn):active {\\n    @include default-focus;\\n  }\\n\\n  .select-kit-header:focus {\\n    @include default-focus;\\n  }\\n\\n  .select-kit-header.btn:focus,\\n  .select-kit-header.btn:active {\\n    outline: none;\\n  }\\n\\n  &.is-disabled {\\n    .select-kit-header {\\n      opacity: 0.5;\\n    }\\n  }\\n}\\n",".tag-category-admin-dropdown {\\n  .badge-category__wrapper {\\n    font-size: var(--font-0);\\n  }\\n\\n  .discourse-tag {\\n    display: inline;\\n    vertical-align: baseline;\\n  }\\n}\\n",".select-kit {\\n  &.tag-chooser,\\n  &.mini-tag-chooser,\\n  &.tag-drop {\\n    border-radius: var(--d-input-border-radius);\\n\\n    .select-kit-row {\\n      display: flex;\\n      align-items: baseline;\\n      flex-wrap: wrap;\\n\\n      .discourse-tag-count {\\n        margin-left: 5px;\\n      }\\n\\n      .synonym-hint {\\n        margin-left: 0.5em;\\n        color: var(--primary-medium);\\n      }\\n\\n      &.disabled {\\n        opacity: 1;\\n\\n        .discourse-tag {\\n          opacity: 0.5;\\n        }\\n\\n        .disabled-reason {\\n          width: 100%;\\n          font-size: var(--font-down-1);\\n          color: var(--primary-medium);\\n          font-style: italic;\\n        }\\n      }\\n    }\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.select-kit {\\n  &.combo-box {\\n    &.tag-drop {\\n      min-width: auto;\\n\\n      .tag-drop-header,\\n      .selected-name {\\n        color: var(--primary-high);\\n      }\\n\\n      @include viewport.until(sm) {\\n        .tag-drop-header {\\n          font-size: var(--font-0);\\n\\n          .d-icon {\\n            font-size: var(--font-0);\\n          }\\n        }\\n      }\\n\\n      .select-kit-row {\\n        &[data-value=\\"all-tags\\"],\\n        &[data-value=\\"no-tags\\"] {\\n          color: var(--tertiary);\\n          font-weight: 700;\\n        }\\n\\n        @include viewport.until(sm) {\\n          font-weight: normal;\\n        }\\n      }\\n\\n      .angle-icon {\\n        color: var(--primary-high);\\n      }\\n\\n      &.has-selection {\\n        .tag-drop-header {\\n          color: var(--d-nav-border-color--active);\\n          border-color: var(--d-nav-border-color--active);\\n        }\\n      }\\n    }\\n  }\\n}\\n",".select-kit {\\n  &.combo-box {\\n    &.topic-chooser {\\n      .select-kit-row {\\n        display: initial;\\n      }\\n    }\\n  }\\n}\\n",".topic-notifications-button {\\n  display: contents;\\n}\\n\\n// This is a weird fix for a weird issue in iOS/iPadOS, the browser freezes\\n// when changing the notification level while in the fullscreen topic footer.\\n// This prevents the selected option icon from being hidden while saving,\\n// and somehow that makes Safari happy.\\n.timeline-fullscreen {\\n  .topic-notifications-button.is-loading {\\n    .selected-name .d-icon {\\n      display: inline-flex;\\n    }\\n  }\\n}\\n",".user-chooser {\\n  .select-kit-row.user-row {\\n    .avatar {\\n      margin-left: 0;\\n      margin-right: 0.5em;\\n    }\\n\\n    .username {\\n      color: var(--primary);\\n      white-space: nowrap;\\n    }\\n\\n    .name {\\n      color: var(--primary-high);\\n      font-size: var(--font-down-1);\\n      margin-left: 0.5em;\\n      overflow: hidden;\\n      white-space: nowrap;\\n      text-overflow: ellipsis;\\n    }\\n  }\\n}\\n","/* `touch-action` for elements carrying the press-drag-transform gesture. The\\n   modifier reflects its `touchAction` arg to `data-pointer-drag`, because the\\n   declaration has to be in effect before a touch begins and consumers bind\\n   `style` themselves.\\n\\n   `none` suits a small handle. Anything large enough that a user might start a\\n   scroll or a pinch-zoom on it wants a value that leaves those gestures alone. */\\n\\n[data-pointer-drag=\\"none\\"] {\\n  touch-action: none;\\n}\\n\\n[data-pointer-drag=\\"pan-x\\"] {\\n  touch-action: pan-x pinch-zoom;\\n}\\n\\n[data-pointer-drag=\\"pan-y\\"] {\\n  touch-action: pan-y pinch-zoom;\\n}\\n\\n[data-pointer-drag=\\"manipulation\\"] {\\n  touch-action: manipulation;\\n}\\n\\n[data-pointer-drag=\\"pinch-zoom\\"] {\\n  touch-action: pinch-zoom;\\n}\\n","/* The handle's own cursor, keyed off the component's class and its axis attribute\\n   rather than `aria-orientation`: that describes the element to assistive\\n   technology, and what a thing promises AT should not decide how it looks. Note the\\n   attribute names the axis being RESIZED, which is the opposite of the separator's\\n   announced orientation. */\\n\\n.d-resize-separator[data-resize-axis=\\"vertical\\"] {\\n  cursor: ns-resize;\\n}\\n\\n.d-resize-separator[data-resize-axis=\\"horizontal\\"] {\\n  cursor: ew-resize;\\n}\\n\\n/* Held on the body by `DResizeSeparator` for the length of a gesture.\\n\\n   The handle's own cursor is not enough: whether the cursor of the element a drag\\n   began on survives the pointer leaving it is engine-dependent, and these handles\\n   are only a few pixels thick, so the pointer spends most of a resize outside the\\n   one it grabbed. Stating it on the body keeps the cursor for the whole gesture.\\n\\n   It reaches only what inherits `cursor`, so a link or a button passed over\\n   mid-drag still shows its own. A gesture that must hold the cursor absolutely\\n   everywhere wants an overlay rather than this. */\\n\\nbody.d-resizing-ns {\\n  cursor: ns-resize;\\n}\\n\\nbody.d-resizing-ew {\\n  cursor: ew-resize;\\n}\\n","/* Full-strength `--tertiary`, not `--token-color-border-accent`: that tint\\n   misses the 3:1 contrast a non-text UI component needs on a light surface. */\\n\\n:root {\\n  --d-drag-indicator-color: var(--tertiary);\\n}\\n\\n@mixin d-drag-line($axis) {\\n  content: \\"\\";\\n  position: absolute;\\n  background: var(--d-drag-indicator-color);\\n  pointer-events: none;\\n\\n  @if $axis == horizontal {\\n    left: 0;\\n    right: 0;\\n    height: 2px;\\n  } @else {\\n    top: 0;\\n    bottom: 0;\\n    width: 2px;\\n  }\\n}\\n\\n@mixin d-drag-outline {\\n  outline: 2px solid var(--d-drag-indicator-color);\\n  outline-offset: -2px;\\n}\\n\\n[data-drag-source] {\\n  &.--dragging {\\n    opacity: 0.5;\\n  }\\n}\\n\\n/* `:where()` so a target that positions itself keeps its own value; the line's\\n   pseudo-element only needs some containing block. */\\n\\n:where(\\n  [data-drop-target].--drag-above,\\n  [data-drop-target].--drag-below,\\n  [data-drop-target].--drag-left,\\n  [data-drop-target].--drag-right,\\n  [data-drop-target-external].--drag-above,\\n  [data-drop-target-external].--drag-below,\\n  [data-drop-target-external].--drag-left,\\n  [data-drop-target-external].--drag-right\\n) {\\n  position: relative;\\n}\\n\\n[data-drop-target],\\n[data-drop-target-external] {\\n  &.--drag-above {\\n    &::before {\\n      @include d-drag-line(horizontal);\\n      top: -1px;\\n    }\\n  }\\n\\n  &.--drag-below {\\n    &::after {\\n      @include d-drag-line(horizontal);\\n      bottom: -1px;\\n    }\\n  }\\n\\n  /* `--drag-left` / `--drag-right` name the physical side under the pointer, so\\n     the RTL flip must leave them alone. */\\n\\n  &.--drag-left {\\n    &::before {\\n      @include d-drag-line(vertical);\\n\\n      /*! rtl:ignore */\\n      left: -1px;\\n    }\\n  }\\n\\n  &.--drag-right {\\n    &::after {\\n      @include d-drag-line(vertical);\\n\\n      /*! rtl:ignore */\\n      right: -1px;\\n    }\\n  }\\n\\n  &.--drag-inside {\\n    @include d-drag-outline;\\n  }\\n}\\n\\n[data-drop-target-external] {\\n  &.--drag-over-external {\\n    @include d-drag-outline;\\n  }\\n}\\n","/* The one look for every displayed shortcut: a single chip around the whole\\n   combination, keys separated by a gap. Both selectors reset everything the\\n   app-wide `kbd` rule sets and outrank a surface's own `kbd` rule. */\\n\\nkbd.d-shortcut {\\n  display: inline-flex;\\n  align-items: center;\\n  justify-content: center;\\n  gap: 0;\\n  flex: none;\\n  box-sizing: border-box;\\n  min-width: 0;\\n  margin: 0;\\n  padding: var(--space-half) var(--space-2);\\n  border: 0;\\n  border-radius: var(--d-border-radius);\\n  background: var(--primary-low);\\n  color: var(--primary-high);\\n  font-family: var(--font-family);\\n  font-size: var(--font-down-1);\\n  font-weight: 600;\\n  line-height: var(--line-height-medium);\\n  vertical-align: middle;\\n  white-space: nowrap;\\n}\\n\\n.btn > .d-shortcut {\\n  margin-left: var(--space-2);\\n}\\n\\n.d-shortcut .d-shortcut__key {\\n  display: inline;\\n  gap: 0;\\n  flex: none;\\n  box-sizing: border-box;\\n  min-width: 0;\\n  margin: 0;\\n  padding: 0;\\n  border: 0;\\n  border-radius: 0;\\n  background: none;\\n  color: inherit;\\n  font: inherit;\\n  line-height: inherit;\\n}\\n\\n/* Keys are spaced out, except that modifier glyphs run together (⌘⇧ D). The\\n   chip is always left-to-right, so the gap is logical rather than physical. */\\n\\n.d-shortcut .d-shortcut__key + .d-shortcut__key {\\n  margin-inline-start: var(--space-2);\\n}\\n\\n.d-shortcut .d-shortcut__key--glyph + .d-shortcut__key--glyph {\\n  margin-inline-start: 0;\\n}\\n","@use \\"lib/viewport\\";\\n\\n.d-tabs {\\n  display: flex;\\n  flex-direction: column;\\n  min-width: 0;\\n\\n  &__strip {\\n    display: flex;\\n    align-items: center;\\n    min-width: 0;\\n  }\\n\\n  &__strip-controls {\\n    flex: 1 1 auto;\\n    min-width: 0;\\n  }\\n\\n  &__tablist {\\n    @include horizontal-scroll-strip;\\n    display: flex;\\n    gap: 0.5em;\\n\\n    &[aria-orientation=\\"vertical\\"] {\\n      flex-direction: column;\\n      align-items: stretch;\\n\\n      // The strip watches only the vertical axis, so a long label wraps\\n      // instead of scrolling sideways with no affordance.\\n      overflow: hidden auto;\\n\\n      .d-tabs__tab {\\n        white-space: normal;\\n        overflow-wrap: anywhere;\\n\\n        // The explicit min-height below replaces the flex automatic minimum,\\n        // so a bounded strip would otherwise crush a wrapped label out of its\\n        // own button rather than scroll.\\n        flex-shrink: 0;\\n      }\\n    }\\n  }\\n\\n  &__tab {\\n    position: relative;\\n    display: flex;\\n    align-items: center;\\n    min-height: 30px;\\n    padding: 0.65em 0.75em;\\n    color: var(--d-nav-color);\\n    background: var(--d-nav-bg-color);\\n    border: 0;\\n    border-radius: var(--d-nav-pill-border-radius);\\n    line-height: var(--line-height-small);\\n    white-space: nowrap;\\n    cursor: pointer;\\n    transition: var(--d-button-transition);\\n\\n    @include viewport.between(sm, lg) {\\n      font-size: var(--font-0);\\n      padding: var(--space-2) var(--space-3);\\n    }\\n\\n    .d-icon {\\n      margin-right: 5px;\\n      color: var(--primary-high);\\n      transition: color 0.2s;\\n    }\\n\\n    &:hover {\\n      @include nav-hover;\\n    }\\n\\n    &[aria-selected=\\"true\\"] {\\n      @include nav-active;\\n    }\\n\\n    &[aria-disabled=\\"true\\"] {\\n      color: var(--primary-low-mid);\\n      background: var(--d-nav-bg-color);\\n      cursor: not-allowed;\\n\\n      .d-icon {\\n        color: var(--primary-low-mid);\\n      }\\n\\n      // aria-disabled gets no system colour of its own.\\n      @media (forced-colors: active) {\\n        color: GrayText;\\n      }\\n    }\\n\\n    &:focus-visible {\\n      @include default-focus;\\n      outline-offset: -2px;\\n    }\\n  }\\n\\n  &__panel {\\n    min-width: 0;\\n  }\\n}\\n",".ace-wrapper .grippie {\\n  background: var(--primary-low);\\n  border-top: 1px solid var(--primary-400);\\n\\n  &::before {\\n    border-top: 3px double var(--primary-medium);\\n  }\\n}\\n\\n.ace-wrapper {\\n  border: 1px solid var(--primary-400);\\n  border-radius: var(--d-input-border-radius);\\n  overflow: hidden;\\n}\\n","@use \\"lib/viewport\\";\\n\\n.autocomplete {\\n  z-index: z(\\"composer\\", \\"dropdown\\") + 1;\\n  max-width: 370px;\\n  min-width: 300px;\\n  background-color: var(--secondary);\\n  border: 1px solid var(--primary-low);\\n  box-shadow: var(--shadow-dropdown);\\n  border-radius: 8px;\\n\\n  @include viewport.from(sm) {\\n    max-width: 600px;\\n  }\\n\\n  ul {\\n    @include unstyled-list;\\n\\n    li {\\n      &:first-of-type a {\\n        border-top-left-radius: 8px;\\n        border-top-right-radius: 8px;\\n      }\\n\\n      &:last-of-type a {\\n        border-bottom-left-radius: 8px;\\n        border-bottom-right-radius: 8px;\\n      }\\n\\n      a {\\n        align-items: center;\\n        color: var(--primary);\\n        display: flex;\\n        gap: 0.25em;\\n        padding: 0.3em 1em;\\n\\n        @include hover {\\n          background-color: var(--d-hover);\\n          text-decoration: none;\\n        }\\n\\n        &.selected {\\n          background-color: var(--d-selected);\\n          color: var(--d-selected-text-color);\\n        }\\n\\n        .avatar {\\n          margin-right: 0.25em;\\n        }\\n\\n        .name {\\n          display: contents;\\n          font-size: var(--font-down-1);\\n          color: var(--primary-high);\\n        }\\n\\n        .user-status-message {\\n          display: flex;\\n          align-items: center;\\n          gap: 0.25em;\\n\\n          .user-status-message-description {\\n            @include ellipsis;\\n            font-size: var(--font-down-2);\\n            color: var(--primary-high);\\n            margin: 0;\\n          }\\n        }\\n\\n        .relative-date {\\n          font-size: var(--font-down-3);\\n        }\\n\\n        .text-content {\\n          @include ellipsis;\\n          display: inline-block;\\n          max-width: 100%;\\n          vertical-align: top;\\n\\n          .username,\\n          .name {\\n            display: inline;\\n          }\\n        }\\n\\n        .d-icon + .text-content {\\n          max-width: calc(100% - 1em);\\n        }\\n      }\\n\\n      .d-icon-users {\\n        color: var(--primary-medium);\\n        padding: 0 2px;\\n      }\\n    }\\n  }\\n\\n  &.ac-user {\\n    li a {\\n      padding: 0.5em 1em;\\n\\n      .text-content {\\n        max-width: calc(100% - 24px); // 24px is for `tiny` avatar width\\n      }\\n    }\\n\\n    .emoji {\\n      height: 0.75em;\\n      width: 0.75em;\\n    }\\n  }\\n\\n  &.ac-emoji {\\n    li:last-of-type a {\\n      color: var(--primary-high);\\n    }\\n\\n    .emoji {\\n      margin-right: 0.25em;\\n    }\\n  }\\n}\\n","// --------------------------------------------------\\n// Badges\\n// --------------------------------------------------\\n\\n// Base\\n// --------------------------------------------------\\n:root {\\n  --category-badge-size: 0.75em;\\n  --category-badge-border-radius: 2px;\\n}\\n\\n%badge {\\n  display: inline-block;\\n  font-weight: normal;\\n  white-space: nowrap;\\n  border-radius: 10px;\\n}\\n\\n// Category badges\\n// --------------------------------------------------\\n.badge-category__wrapper {\\n  color: var(--primary-high);\\n  overflow: hidden;\\n  text-overflow: ellipsis;\\n  font-size: var(--font-down-1);\\n  white-space: nowrap;\\n  position: relative;\\n  display: inline-flex;\\n  align-items: baseline;\\n\\n  .badge-category {\\n    display: inline-flex;\\n    align-items: baseline;\\n    gap: 0.33em;\\n    color: var(--primary-high);\\n    min-width: 0;\\n\\n    &.--style-square::before {\\n      content: \\"\\";\\n      background: var(--category-badge-color);\\n      flex: 0 0 auto;\\n      width: var(--category-badge-size);\\n      height: var(--category-badge-size);\\n      border-radius: var(--category-badge-border-radius);\\n    }\\n\\n    &.--style-emoji,\\n    &.--style-icon {\\n      display: flex;\\n      align-items: center;\\n\\n      .d-icon,\\n      .emoji {\\n        width: 0.74em;\\n        height: 0.74em;\\n      }\\n    }\\n\\n    &.--style-icon .d-icon {\\n      color: var(--category-badge-color);\\n    }\\n\\n    &.--style-icon .d-icon + .d-icon {\\n      color: var(--primary-medium);\\n    }\\n\\n    &__name {\\n      color: var(--category-badge-title-color);\\n      text-overflow: ellipsis;\\n      overflow: hidden;\\n      min-width: 0;\\n    }\\n\\n    &.--has-parent {\\n      &::before {\\n        background: linear-gradient(\\n          90deg,\\n          var(--parent-category-badge-color) 50%,\\n          var(--category-badge-color) 50%\\n        );\\n      }\\n    }\\n\\n    .extra-info-wrapper & {\\n      color: var(--header_primary-high);\\n    }\\n  }\\n\\n  .d-icon {\\n    width: 0.74em;\\n    height: 0.74em;\\n    color: var(--primary-medium);\\n  }\\n}\\n\\n// Notification badge\\n// --------------------------------------------------\\n.badge-notification {\\n  @extend %badge;\\n  position: relative;\\n  top: -2px;\\n  padding: 0.21em 0.42em;\\n  min-width: 0.5em;\\n  color: var(--secondary);\\n  font-size: var(--font-down-2);\\n  line-height: var(--line-height-small);\\n  text-align: center;\\n  background-color: var(--primary-low-mid-or-secondary-low);\\n\\n  &[href] {\\n    color: var(--secondary);\\n  }\\n\\n  &:hover {\\n    color: var(--secondary);\\n  }\\n\\n  // Unread posts\\n  &.unread-posts {\\n    background-color: var(--tertiary-med-or-tertiary);\\n    color: var(--secondary);\\n    font-weight: dark-light-choose(normal, bold);\\n  }\\n\\n  &.new-topic,\\n  &.new-replies {\\n    background-color: transparent;\\n    padding-left: 0.15em;\\n  }\\n\\n  &.new-topic::before,\\n  &.new-replies::before {\\n    content: \\"\\";\\n    background: var(--tertiary-med-or-tertiary);\\n    display: inline-block;\\n    height: 8px;\\n    width: 8px;\\n    border-radius: 50%;\\n  }\\n}\\n\\n// Posts badge\\n// --------------------------------------------------\\n.badge-posts {\\n  font-weight: normal;\\n  font-size: var(--font-0);\\n  line-height: var(--line-height-small);\\n\\n  &[href] {\\n    color: var(--primary-med-or-secondary-med);\\n  }\\n}\\n\\n// Group badge\\n// --------------------------------------------------\\n.badge-group {\\n  @extend %badge;\\n  padding: 2px 5px;\\n  color: var(--primary);\\n  background-color: var(--primary-low);\\n  border-color: var(--primary-low);\\n  font-size: var(--font-down-1);\\n}\\n","// --------------------------------------------------\\n// Banner\\n// --------------------------------------------------\\n#banner {\\n  padding: 1em;\\n  background: var(--tertiary-low);\\n  color: var(--primary);\\n  z-index: z(\\"base\\") + 1;\\n  margin-bottom: 1em;\\n  max-height: 20vh;\\n  overflow: auto;\\n\\n  .floated-buttons {\\n    float: right;\\n    display: flex;\\n\\n    > .btn {\\n      padding-top: 0;\\n      padding-bottom: 0;\\n      color: var(--primary-high);\\n\\n      .d-icon {\\n        color: var(--primary-medium);\\n      }\\n\\n      &:hover {\\n        color: var(--primary);\\n\\n        .d-icon {\\n          color: var(--primary-high);\\n        }\\n      }\\n    }\\n\\n    .desktop-view & .btn.close {\\n      margin-left: 0.25em;\\n    }\\n  }\\n}\\n\\n#banner-content {\\n  hr {\\n    border-color: var(--primary-medium);\\n  }\\n\\n  > p:first-child {\\n    margin-top: 0;\\n  }\\n\\n  > p:last-child {\\n    margin-bottom: 0;\\n  }\\n\\n  a.anchor {\\n    display: none;\\n  }\\n}\\n",".d-breadcrumbs {\\n  display: flex;\\n  flex-wrap: wrap;\\n  margin: var(--space-2) 0 var(--space-4) 0;\\n\\n  &__item {\\n    list-style-type: none;\\n    white-space: nowrap;\\n  }\\n\\n  &__link,\\n  &__link:visited {\\n    color: var(--primary-medium);\\n  }\\n\\n  li {\\n    .separator {\\n      margin-right: var(--space-1);\\n\\n      .d-icon {\\n        color: var(--primary-medium);\\n        font-size: var(--font-down-1);\\n      }\\n    }\\n  }\\n}\\n","$mobile-breakpoint: 700px;\\n\\n.d-page-header,\\n.d-page-subheader {\\n  &__title-row {\\n    display: flex;\\n    flex-wrap: wrap;\\n    justify-content: space-between;\\n    align-items: stretch;\\n    margin-bottom: var(--space-2);\\n\\n    h1,\\n    h2 {\\n      margin: 0;\\n    }\\n\\n    h2 {\\n      font-size: var(--font-up-2);\\n    }\\n\\n    .d-page-header__actions,\\n    .d-page-subheader__actions {\\n      display: flex;\\n      align-items: center;\\n      justify-content: flex-end;\\n\\n      @media (max-width: $mobile-breakpoint) {\\n        flex-direction: column;\\n      }\\n\\n      button {\\n        margin-left: var(--space-2);\\n\\n        @media (max-width: $mobile-breakpoint) {\\n          width: 100%;\\n          margin-bottom: var(--space-2);\\n          margin-left: 0;\\n        }\\n      }\\n    }\\n  }\\n\\n  .d-nav-submenu {\\n    background: transparent;\\n    border-bottom: 1px solid var(--content-border-color);\\n\\n    .horizontal-overflow-nav {\\n      background: transparent;\\n\\n      &::before {\\n        display: none;\\n      }\\n\\n      &::after {\\n        display: none;\\n      }\\n    }\\n\\n    .nav-pills {\\n      width: auto;\\n      margin: 0;\\n    }\\n  }\\n}\\n\\n.d-page-header {\\n  &__title-row {\\n    @media (max-width: $mobile-breakpoint) {\\n      flex-direction: row;\\n      align-items: center;\\n\\n      .d-page-header__actions {\\n        button {\\n          margin-bottom: 0;\\n        }\\n      }\\n    }\\n  }\\n\\n  &__drawer {\\n    display: flex;\\n    align-items: center;\\n    margin-bottom: var(--space-2);\\n\\n    &:not(:has(*)) {\\n      display: none;\\n    }\\n  }\\n}\\n\\n.d-page-subheader {\\n  &__title-row {\\n    @media (max-width: $mobile-breakpoint) {\\n      flex-direction: row;\\n      align-items: center;\\n    }\\n  }\\n}\\n\\n.d-page-action-list-item {\\n  .btn-primary {\\n    color: var(--primary);\\n  }\\n}\\n\\n.d-page-header__learn-more {\\n  &::before {\\n    content: \\"• \\";\\n  }\\n}\\n",".d-stat-tiles {\\n  display: grid;\\n  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));\\n  gap: 1em;\\n  margin-bottom: 2em;\\n\\n  .d-stat-tile {\\n    display: flex;\\n    flex-direction: column;\\n    padding: 1em;\\n    background: var(--primary-very-low);\\n    border-radius: 0.25em;\\n\\n    &__label {\\n      color: var(--primary-medium);\\n      font-size: 0.875em;\\n      margin-bottom: 0.5em;\\n    }\\n\\n    &__value {\\n      color: var(--primary);\\n      font-size: 1.5em;\\n      font-weight: bold;\\n    }\\n  }\\n\\n  &.--compact {\\n    display: flex;\\n    gap: 0.5em;\\n    margin-bottom: 0;\\n\\n    .d-stat-tile {\\n      padding: 0.25em 0.5em;\\n\\n      &__label {\\n        font-size: var(--font-down-2);\\n        margin-bottom: 0;\\n      }\\n\\n      &__value {\\n        font-size: var(--font-down-1);\\n      }\\n    }\\n  }\\n}\\n","$mobile-breakpoint: 700px;\\n\\n.bookmark-list {\\n  .topic-list-data.post-metadata {\\n    text-align: center;\\n  }\\n}\\n\\n.bookmark-list-item {\\n  .topic-list-data.post-metadata {\\n    text-align: center;\\n  }\\n\\n  @media (max-width: $mobile-breakpoint) {\\n    .main-link {\\n      padding-right: 0.5em;\\n    }\\n  }\\n\\n  .author-avatar img.avatar {\\n    height: 24px;\\n    width: 24px;\\n  }\\n\\n  .main-link.topic-list-data {\\n    .bookmark-status-with-link {\\n      a.title {\\n        padding: 0;\\n      }\\n    }\\n  }\\n\\n  .d-icon.bookmark-pinned {\\n    font-size: var(--font-down-2);\\n    margin-right: 0.2em;\\n  }\\n\\n  .bookmark-metadata {\\n    font-size: var(--font-down-2);\\n    margin-bottom: 0.25em;\\n\\n    &-item {\\n      display: inline-block;\\n      margin-right: 1em;\\n      margin-bottom: 0.25em;\\n      line-height: var(--line-height-medium);\\n\\n      span {\\n        word-break: break-word;\\n      }\\n\\n      &.bookmark-expired-reminder {\\n        color: var(--danger);\\n      }\\n    }\\n\\n    .d-icon {\\n      margin-right: 0.25em;\\n    }\\n  }\\n\\n  .bookmark-status-with-link {\\n    display: flex;\\n    flex-direction: row;\\n    align-items: center;\\n\\n    .mobile-view & {\\n      margin-bottom: 0.15em;\\n    }\\n\\n    .topic-statuses {\\n      float: none;\\n    }\\n  }\\n\\n  .post-excerpt {\\n    overflow: hidden;\\n    padding-right: 1em;\\n  }\\n\\n  .mobile-view & {\\n    .avatar {\\n      float: left;\\n      margin: 0.27em 0.27em 0 0;\\n    }\\n  }\\n}\\n\\n.select-kit.bookmark-actions-dropdown {\\n  .select-kit-body {\\n    max-width: 350px;\\n  }\\n}\\n",".bookmark-reminder-modal {\\n  .d-modal {\\n    &__body {\\n      box-sizing: border-box;\\n\\n      .control-label {\\n        font-weight: 700;\\n      }\\n\\n      .ember-text-field.bookmark-name {\\n        width: 100%;\\n        margin-bottom: 0.5em;\\n      }\\n    }\\n\\n    &__footer {\\n      .delete-bookmark {\\n        margin-left: auto;\\n        margin-right: 0;\\n      }\\n    }\\n  }\\n\\n  .existing-reminder-at-alert {\\n    display: flex;\\n    flex-direction: row;\\n    align-items: center;\\n\\n    .d-icon {\\n      margin-right: 1em;\\n    }\\n  }\\n\\n  .bookmark-options-panel {\\n    margin-bottom: 18px;\\n\\n    .select-kit {\\n      width: 100%;\\n    }\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.bookmark-menu-content {\\n  .bookmark-menu__title {\\n    background: var(--tertiary-low);\\n    color: var(--tertiary);\\n\\n    .d-icon {\\n      color: var(--tertiary);\\n    }\\n  }\\n\\n  .bookmark-menu__row-title,\\n  .bookmark-menu__title {\\n    display: flex;\\n    align-items: center;\\n    font-weight: bold;\\n    gap: var(--d-sidebar-section-link-prefix-margin-right);\\n    height: var(--d-sidebar-row-height);\\n    padding-inline: var(--d-sidebar-row-horizontal-padding);\\n    border-radius: var(--d-border-radius);\\n\\n    .d-icon {\\n      width: var(--d-sidebar-section-link-prefix-width);\\n    }\\n  }\\n}\\n\\n.topic-bookmarks-menu-content {\\n  @include viewport.from(sm) {\\n    max-height: 60vh;\\n  }\\n\\n  .--jump {\\n    .btn {\\n      .discourse-no-touch & {\\n        &:hover,\\n        &:focus-visible {\\n          background: var(--d-hover);\\n        }\\n      }\\n    }\\n  }\\n\\n  .--has-name {\\n    .btn {\\n      height: auto;\\n      min-height: 2.2em;\\n      padding: var(--space-1);\\n    }\\n\\n    .d-icon {\\n      align-self: flex-start;\\n      padding-top: var(--space-1);\\n    }\\n  }\\n\\n  .bookmark-menu__row-texts {\\n    line-height: var(--line-height-medium);\\n    display: flex;\\n    flex-direction: column;\\n    align-items: flex-start;\\n  }\\n\\n  .bookmark-menu__row-description {\\n    font-size: var(--font-down-1);\\n    color: var(--primary-medium);\\n    white-space: normal;\\n    overflow-wrap: anywhere;\\n    text-align: left;\\n    max-width: 35ch;\\n  }\\n\\n  .--post-bookmark {\\n    .d-button__suffix-icon {\\n      margin-left: auto;\\n      color: var(--primary-medium);\\n    }\\n  }\\n\\n  .bookmark-menu__section-title {\\n    display: flex;\\n    align-items: center;\\n    font-weight: 700;\\n    font-size: var(--font-down-1);\\n    color: var(--primary-medium);\\n    gap: var(--d-sidebar-section-link-prefix-margin-right);\\n    padding-inline: var(--d-sidebar-row-horizontal-padding);\\n    padding-block: 0.35em;\\n\\n    .d-icon {\\n      width: var(--d-sidebar-section-link-prefix-width);\\n    }\\n\\n    span {\\n      overflow: hidden;\\n      text-overflow: ellipsis;\\n      white-space: nowrap;\\n    }\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.manage-tags-form {\\n  &__remove-section {\\n    position: relative;\\n\\n    #control-remove_all_tags {\\n      position: absolute;\\n      top: 0;\\n      right: 0;\\n      width: auto;\\n\\n      .form-kit__container-title {\\n        color: var(--primary-medium);\\n        font-weight: normal !important;\\n        white-space: nowrap;\\n      }\\n    }\\n  }\\n\\n  &__warning {\\n    margin-top: 2rem;\\n  }\\n\\n  &__replace {\\n    .form-kit__container-content {\\n      flex-direction: column;\\n      row-gap: var(--space-2);\\n    }\\n\\n    .form-kit__row {\\n      padding-top: 0;\\n\\n      // Form-kit collapses every `--col-*` to 100% width below `lg`, which\\n      // stacks the from-chooser, arrow, to-chooser and remove button into a\\n      // tall column. Restore the desktop ratios so the replace row stays on\\n      // a single line on mobile.\\n      // TODO: looking at adding a proper opt-out in form-kit so we don't\\n      // need this override.\\n      @include viewport.until(lg) {\\n        .--col-1 {\\n          width: 8.33333333% !important;\\n        }\\n\\n        .--col-5 {\\n          width: 41.66666667% !important;\\n        }\\n      }\\n    }\\n  }\\n\\n  &__replace-arrow {\\n    text-align: center;\\n    height: 2.25em;\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n  }\\n\\n  &__replace-row-add {\\n    width: 100%;\\n  }\\n}\\n",":root {\\n  // global\\n  --d-button-border-radius: var(--d-border-radius);\\n  --d-button-transition: none;\\n  --d-button-border: 1px solid transparent;\\n\\n  // .btn-default\\n  --d-button-default-text-color: var(--primary);\\n  --d-button-default-text-color--hover: var(--secondary);\\n  --d-button-default-bg-color: var(--primary-low);\\n  --d-button-default-bg-color--hover: var(--primary-medium);\\n  --d-button-default-icon-color: var(--primary-high);\\n  --d-button-default-icon-color--hover: var(--primary-low);\\n  --d-button-default-border: var(--d-button-border);\\n  --d-button-default-border--hover: var(--d-button-border);\\n\\n  // .btn-primary\\n  --d-button-primary-text-color: var(--secondary);\\n  --d-button-primary-text-color--hover: var(--secondary);\\n  --d-button-primary-bg-color: var(--tertiary);\\n  --d-button-primary-bg-color--hover: var(--tertiary-hover);\\n  --d-button-primary-icon-color: var(--secondary);\\n  --d-button-primary-icon-color--hover: var(--secondary);\\n  --d-button-primary-border: var(--d-button-border);\\n  --d-button-primary-border--hover: var(--d-button-border);\\n\\n  // .btn-danger and .btn.cancel\\n  --d-button-danger-text-color: var(--secondary);\\n  --d-button-danger-text-color--hover: var(--secondary);\\n  --d-button-danger-bg-color: var(--danger);\\n  --d-button-danger-bg-color--hover: var(--danger-hover);\\n  --d-button-danger-icon-color: var(--danger-low);\\n  --d-button-danger-icon-color--hover: var(--danger-low);\\n  --d-button-danger-border: var(--d-button-border);\\n  --d-button-danger-border--hover: var(--d-button-border);\\n\\n  // .btn-success and .btn.ok\\n  --d-button-success-text-color: var(--secondary);\\n  --d-button-success-text-color--hover: var(--secondary);\\n  --d-button-success-bg-color: var(--success);\\n  --d-button-success-bg-color--hover: var(--success-hover);\\n  --d-button-success-icon-color: var(--success-low);\\n  --d-button-success-icon-color--hover: var(--success-low);\\n  --d-button-success-border: var(--d-button-border);\\n  --d-button-success-border--hover: var(--d-button-border);\\n\\n  // .btn-flat\\n  --d-button-flat-text-color: var(--tertiary);\\n  --d-button-flat-text-color--hover: var(--primary);\\n  --d-button-flat-icon-color: var(--primary-low-mid);\\n  --d-button-flat-icon-color--hover: var(--primary);\\n  --d-button-flat-bg-color: transparent;\\n  --d-button-flat-bg-color--hover: var(--d-hover);\\n  --d-button-flat-bg-color--focus: var(--d-hover);\\n  --d-button-flat-text-color--disabled: var(--primary);\\n\\n  // .btn-flat.close\\n  --d-button-flat-close-text-color: var(--primary-high);\\n  --d-button-flat-close-bg-color: transparent;\\n  --d-button-flat-close-icon-color: var(--primary-high);\\n  --d-button-flat-close-icon-color--hover: var(--primary);\\n\\n  // .btn-transparent\\n  --d-button-transparent-text-color: var(--primary);\\n  --d-button-transparent-text-color--hover: var(--tertiary-hover);\\n  --d-button-transparent-icon-color: var(--primary-high);\\n  --d-button-transparent-icon-color--hover: var(--tertiary-hover);\\n}\\n\\n/* Base */\\n@mixin btn(\\n  $text-color: var(--d-button-default-text-color),\\n  $bg-color: var(--d-button-default-bg-color),\\n  $icon-color: var(--d-button-default-icon-color),\\n  $hover-text-color: var(--d-button-default-text-color--hover),\\n  $hover-bg-color: var(--d-button-default-bg-color--hover),\\n  $hover-icon-color: var(--d-button-default-icon-color--hover),\\n  $border: var(--d-button-border),\\n  $hover-border: var(--d-button-border)\\n) {\\n  color: $text-color;\\n  background-color: $bg-color;\\n  transition: var(--d-button-transition);\\n  border: $border;\\n\\n  &:visited {\\n    /* covers cases where we add button classes to links */\\n    color: $text-color;\\n  }\\n\\n  .d-icon {\\n    color: $icon-color;\\n    margin-right: 0.45em;\\n    transition: var(--d-button-transition);\\n\\n    /* For Windows High Contrast (see whcm.scss for more) */\\n    @media (forced-colors: active) {\\n      color: ButtonText;\\n    }\\n  }\\n\\n  .d-button-label + .d-icon {\\n    margin-left: 0.45em;\\n    margin-right: 0;\\n  }\\n\\n  &.no-text {\\n    .d-icon {\\n      margin-right: 0;\\n    }\\n  }\\n\\n  @include hover {\\n    background-color: $hover-bg-color;\\n    color: $hover-text-color;\\n    border: $hover-border;\\n\\n    .d-icon {\\n      color: $hover-icon-color;\\n\\n      /* For Windows High Contrast (see whcm.scss for more) */\\n      @media (forced-colors: active) {\\n        color: Highlight;\\n      }\\n    }\\n  }\\n\\n  &:focus-visible {\\n    outline: none;\\n    background-color: $hover-bg-color;\\n    color: $hover-text-color;\\n\\n    .d-icon {\\n      color: $hover-icon-color;\\n\\n      @media (forced-colors: active) {\\n        color: Highlight;\\n      }\\n    }\\n  }\\n\\n  &[disabled],\\n  &.disabled {\\n    cursor: not-allowed;\\n\\n    &:not(.is-loading) {\\n      opacity: 0.4;\\n    }\\n\\n    &:hover {\\n      color: $text-color;\\n      background: $bg-color;\\n      border: $border;\\n\\n      .d-icon {\\n        color: $icon-color;\\n      }\\n    }\\n  }\\n\\n  .loading-container {\\n    display: none;\\n    margin: 0 6.75px 0 0;\\n  }\\n\\n  &.is-loading {\\n    &.btn-small {\\n      .loading-icon {\\n        font-size: var(--font-down-1);\\n        margin-right: 0.2em;\\n      }\\n    }\\n\\n    .loading-icon {\\n      animation:\\n        rotate-forever 1s infinite linear,\\n        fadein 1s;\\n    }\\n  }\\n}\\n\\n/* Generic btn */\\n.btn {\\n  @include btn;\\n  display: inline-flex;\\n  align-items: center;\\n  justify-content: center;\\n  margin: 0;\\n  font-weight: normal;\\n  background-image: linear-gradient(\\n    to bottom,\\n    rgb(0, 0, 0, 0),\\n    rgb(0, 0, 0, 0)\\n  );\\n  box-sizing: border-box;\\n  padding: $vpad $hpad;\\n  cursor: pointer;\\n  line-height: normal;\\n  white-space: nowrap;\\n\\n  .d-button__suffix-icon {\\n    margin-left: auto;\\n\\n    .d-icon {\\n      margin-right: 0;\\n    }\\n  }\\n}\\n\\n/* link button */\\n.btn-link {\\n  background: transparent;\\n  border: 0;\\n  padding: 0;\\n  color: var(--tertiary);\\n\\n  @include hover {\\n    background-color: transparent;\\n    color: var(--tertiary-hover);\\n    border: 0;\\n\\n    .d-icon {\\n      color: var(--tertiary-hover);\\n\\n      /* For Windows High Contrast (see whcm.scss for more) */\\n      @media (forced-colors: active) {\\n        color: Highlight;\\n      }\\n    }\\n  }\\n\\n  &:focus-visible {\\n    color: var(--tertiary);\\n    background: transparent;\\n\\n    @include default-focus;\\n  }\\n\\n  &[disabled],\\n  &.disabled {\\n    color: var(--d-button-transparent-text-color);\\n    cursor: not-allowed;\\n\\n    &:not(.is-loading) {\\n      opacity: 0.4;\\n    }\\n\\n    &:hover {\\n      background: transparent;\\n\\n      .d-icon {\\n        color: inherit;\\n      }\\n    }\\n  }\\n}\\n\\n/* Default button */\\n.btn-default {\\n  border: var(--d-button-default-border);\\n  border-radius: var(--d-button-border-radius);\\n\\n  @include hover {\\n    border: var(--d-button-default-border--hover);\\n  }\\n}\\n\\n/* Primary button */\\n.btn-primary {\\n  @include btn(\\n    $text-color: var(--d-button-primary-text-color),\\n    $bg-color: var(--d-button-primary-bg-color),\\n    $icon-color: var(--d-button-primary-icon-color),\\n    $hover-text-color: var(--d-button-primary-text-color--hover),\\n    $hover-bg-color: var(--d-button-primary-bg-color--hover),\\n    $hover-icon-color: var(--d-button-primary-icon-color--hover),\\n    $border: var(--d-button-primary-border),\\n    $hover-border: var(--d-button-primary-border--hover)\\n  );\\n  border-radius: var(--d-button-border-radius);\\n}\\n\\n/* Danger button */\\n.btn-danger,\\n.btn.cancel {\\n  @include btn(\\n    $text-color: var(--d-button-danger-text-color),\\n    $bg-color: var(--d-button-danger-bg-color),\\n    $icon-color: var(--d-button-danger-icon-color),\\n    $hover-text-color: var(--d-button-danger-text-color--hover),\\n    $hover-bg-color: var(--d-button-danger-bg-color--hover),\\n    $hover-icon-color: var(--d-button-danger-icon-color--hover),\\n    $border: var(--d-button-danger-border),\\n    $hover-border: var(--d-button-danger-border--hover)\\n  );\\n  border-radius: var(--d-button-border-radius);\\n}\\n\\n/* Success button */\\n.btn-success,\\n.btn.ok {\\n  @include btn(\\n    $text-color: var(--d-button-success-text-color),\\n    $bg-color: var(--d-button-success-bg-color),\\n    $icon-color: var(--d-button-success-icon-color),\\n    $hover-text-color: var(--d-button-success-text-color--hover),\\n    $hover-bg-color: var(--d-button-success-bg-color--hover),\\n    $hover-icon-color: var(--d-button-success-icon-color--hover),\\n    $border: var(--d-button-success-border),\\n    $hover-border: var(--d-button-success-border--hover)\\n  );\\n  border-radius: var(--d-button-border-radius);\\n}\\n\\n/* Social buttons */\\n.btn-social {\\n  color: #000;\\n  background: #fff;\\n  border-radius: var(--d-border-radius);\\n\\n  &:focus-visible {\\n    outline: 1px solid #000;\\n  }\\n\\n  &[href] {\\n    color: var(--secondary);\\n  }\\n\\n  &::before {\\n    margin-right: 9px;\\n    font-size: var(--font-0);\\n  }\\n\\n  .d-icon,\\n  &.btn:hover .d-icon {\\n    color: #000;\\n  }\\n\\n  &.cas {\\n    .d-icon {\\n      color: var(--cas);\\n    }\\n\\n    &:hover {\\n      .d-icon {\\n        color: var(--cas);\\n      }\\n    }\\n  }\\n\\n  &.twitter {\\n    .d-icon {\\n      color: var(--twitter);\\n    }\\n\\n    &:hover {\\n      .d-icon {\\n        color: var(--twitter);\\n      }\\n    }\\n  }\\n\\n  &.github {\\n    .d-icon {\\n      color: var(--github);\\n    }\\n\\n    &:hover {\\n      .d-icon {\\n        color: var(--github);\\n      }\\n    }\\n  }\\n\\n  &.discord {\\n    .d-icon {\\n      color: var(--discord);\\n    }\\n\\n    &:hover {\\n      .d-icon {\\n        color: var(--discord);\\n      }\\n    }\\n  }\\n\\n  &.discourse_id {\\n    background-color: var(--discourse_id-background);\\n    color: var(--discourse_id-text);\\n\\n    .d-icon {\\n      color: var(--discourse_id-icon);\\n    }\\n\\n    &:hover {\\n      background-color: var(--discourse_id-background-hover);\\n      color: var(--discourse_id-text-hover);\\n\\n      .d-icon {\\n        color: var(--discourse_id-icon-hover);\\n      }\\n    }\\n  }\\n\\n  /* https://developers.facebook.com/docs/facebook-login/userexperience/#buttondesign\\n  if you are unable to use Facebook blue, revert to black and white. */\\n}\\n\\n/* Button Sizes */\\n\\n/* Small */\\n.btn-small {\\n  font-size: var(--font-down-1);\\n  min-height: 20px;\\n}\\n\\n/* Large */\\n.btn-large {\\n  font-size: var(--font-up-1);\\n}\\n\\n/* Bonus Buttons */\\n.btn-flat {\\n  @include btn(\\n    $text-color: var(--d-button-default-text-color),\\n    $bg-color: var(--d-button-flat-bg-color),\\n    $icon-color: var(--d-button-flat-icon-color),\\n    $hover-text-color: var(--d-button-flat-text-color--hover),\\n    $hover-bg-color: var(--d-button-flat-bg-color--hover),\\n    $hover-icon-color: var(--d-button-flat-icon-color--hover)\\n  );\\n  border-radius: var(--d-button-border-radius);\\n\\n  .discourse-no-touch & {\\n    &:focus-visible {\\n      background: var(--d-button-flat-bg-color--focus);\\n    }\\n  }\\n\\n  &.close {\\n    background: var(--d-button-flat-close-bg-color);\\n\\n    .d-icon {\\n      color: var(--d-button-flat-close-icon-color);\\n    }\\n\\n    .discourse-no-touch & {\\n      &:hover,\\n      &:focus-visible {\\n        background: var(--d-button-flat-close-bg-color);\\n\\n        .d-icon {\\n          color: var(--d-button-flat-close-icon-color--hover);\\n        }\\n      }\\n    }\\n\\n    &:focus-visible {\\n      background: var(--d-button-flat-close-bg-color);\\n\\n      .d-icon {\\n        color: var(--d-button-flat-close-icon-color--hover);\\n      }\\n    }\\n  }\\n\\n  &:focus-visible {\\n    outline: none;\\n    background: var(--primary-low);\\n\\n    .d-icon {\\n      color: var(--primary);\\n    }\\n  }\\n}\\n\\n@mixin btn-colors($btn-type) {\\n  color: var(--d-button-#{$btn-type}-bg-color);\\n\\n  .d-icon {\\n    color: currentcolor;\\n  }\\n\\n  &:focus-visible {\\n    color: var(--d-button-#{$btn-type}-bg-color--hover);\\n  }\\n\\n  .discourse-no-touch & {\\n    &:hover {\\n      color: var(--d-button-#{$btn-type}-bg-color--hover);\\n    }\\n  }\\n}\\n\\n.btn-transparent {\\n  &,\\n  &.btn-default, // preferably NOT used in conjuction with btn-default\\n  &.btn-icon,\\n  &.no-text {\\n    @include btn(\\n      $text-color: var(--d-button-transparent-text-color),\\n      $bg-color: transparent,\\n      $icon-color: var(--d-button-transparent-icon-color),\\n      $hover-text-color: var(--d-button-transparent-text-color--hover),\\n      $hover-bg-color: transparent,\\n      $hover-icon-color: currentcolor,\\n      $border: 0,\\n      $hover-border: 0\\n    );\\n\\n    &:focus-visible {\\n      background: transparent;\\n      color: var(--d-button-transparent-text-color--hover);\\n\\n      .d-icon {\\n        color: currentcolor;\\n      }\\n    }\\n  }\\n\\n  /* The full classname is the old way of combining transparent buttons with colours – no longer use like this\\n  Use the --modifiers approach instead\\n  */\\n\\n  &.btn-primary,\\n  &.--primary {\\n    @include btn-colors(\\"primary\\");\\n  }\\n\\n  &.btn-danger,\\n  &.--danger {\\n    @include btn-colors(\\"danger\\");\\n  }\\n\\n  &.btn-success,\\n  &.--success {\\n    @include btn-colors(\\"success\\");\\n  }\\n\\n  &.back-button {\\n    --d-button-transparent-text-color: var(--tertiary);\\n    --d-button-transparent-icon-color: var(--tertiary);\\n    margin-bottom: 1em;\\n    padding-left: 0;\\n  }\\n}\\n",".d-segmented-control {\\n  position: relative;\\n  display: inline-flex;\\n  align-items: center;\\n  box-sizing: border-box;\\n  overflow: hidden;\\n  background: var(--primary-very-low);\\n  gap: var(--space-2);\\n  border-radius: var(--d-border-radius);\\n  padding: var(--space-1) var(--space-2);\\n  height: var(--space-9);\\n\\n  &__legend {\\n    position: absolute;\\n    width: 1px;\\n    height: 1px;\\n    padding: 0;\\n    margin: 0;\\n    overflow: hidden;\\n    clip-path: inset(50%);\\n    white-space: nowrap;\\n  }\\n\\n  &__slider {\\n    position: absolute;\\n    top: var(--space-1);\\n    left: 0;\\n    width: var(--slider-width, 0);\\n    height: calc(100% - var(--space-2));\\n    transform: translateX(var(--slider-x, 0));\\n    background: var(--secondary);\\n    border-radius: var(--d-border-radius);\\n    box-shadow: 0 1px 6px rgb(0, 0, 0, 0.1);\\n    pointer-events: none;\\n\\n    &.is-animated {\\n      transition:\\n        transform 0.25s cubic-bezier(0.4, 0, 0.2, 1),\\n        width 0.25s cubic-bezier(0.4, 0, 0.2, 1);\\n\\n      @media (prefers-reduced-motion: reduce) {\\n        transition-duration: 0ms;\\n      }\\n    }\\n  }\\n\\n  &__input[type=\\"radio\\"] {\\n    position: absolute;\\n    width: 1px;\\n    height: 1px;\\n    padding: 0;\\n    margin: 0;\\n    overflow: hidden;\\n    clip-path: inset(50%);\\n  }\\n\\n  &.--full-width {\\n    display: flex;\\n    width: 100%;\\n\\n    .d-segmented-control__label {\\n      flex: 1;\\n    }\\n  }\\n\\n  &--small {\\n    gap: 2px;\\n    padding: 1px;\\n    height: auto;\\n\\n    .d-segmented-control__slider {\\n      top: 1px;\\n      height: calc(100% - 2px);\\n    }\\n\\n    .d-segmented-control__label {\\n      padding: 0 var(--space-1);\\n      height: auto;\\n      font-size: var(--font-down-2);\\n\\n      .d-icon {\\n        font-size: var(--font-down-2);\\n      }\\n    }\\n  }\\n\\n  &__label {\\n    z-index: 1;\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    font-weight: normal;\\n    padding: var(--space-1) var(--space-4);\\n    margin: 0;\\n    border-radius: var(--d-border-radius);\\n    color: var(--primary-high);\\n    height: var(--space-5);\\n    cursor: pointer;\\n    user-select: none;\\n    white-space: nowrap;\\n\\n    &:hover {\\n      background: var(--primary-low);\\n      color: var(--primary);\\n    }\\n\\n    &:has(:focus-visible) {\\n      outline: 2px solid var(--tertiary);\\n      outline-offset: -2px;\\n    }\\n\\n    &:has(:checked),\\n    &:has(:checked):hover {\\n      background: transparent;\\n      color: var(--primary);\\n    }\\n\\n    &.is-disabled {\\n      cursor: not-allowed;\\n      opacity: 0.45;\\n      pointer-events: none;\\n    }\\n  }\\n}\\n",".d-native-select {\\n  width: 100%;\\n  height: 2.25em;\\n  background: var(--secondary);\\n  border: 1px solid var(--primary-400);\\n  border-radius: var(--d-input-border-radius);\\n  box-sizing: border-box;\\n  margin: 0;\\n  padding: 0 2em 0 0.5em !important;\\n  appearance: none;\\n  background-image: svg-uri(\\n    \\"<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16'><path fill='none' stroke='#{$primary-medium}' stroke-linecap='round' stroke-linejoin='round' stroke-width='3' d='m2 5 6 6 6-6'/></svg>\\"\\n  );\\n  background-repeat: no-repeat;\\n  background-position: right 0.5rem center;\\n  background-size: 16px 12px;\\n  cursor: pointer;\\n\\n  @include ellipsis;\\n\\n  &:focus,\\n  &:focus-visible,\\n  &:focus:focus-visible,\\n  &:active {\\n    // these `!important` flags are another great case for having a button element without that pesky default styling\\n    &:not(:disabled) {\\n      background-color: var(--secondary) !important;\\n      color: var(--primary) !important;\\n      border-color: var(--tertiary);\\n      outline: 2px solid var(--tertiary);\\n      outline-offset: -2px;\\n\\n      .d-icon {\\n        color: inherit !important;\\n      }\\n    }\\n  }\\n\\n  &:hover:not(:disabled) {\\n    .discourse-no-touch & {\\n      background-color: var(--secondary);\\n      color: var(--primary);\\n      border-color: var(--tertiary);\\n\\n      .d-icon {\\n        color: inherit;\\n      }\\n    }\\n  }\\n}\\n","// Theming tokens (fill, shimmer, duration, radius) are deliberately not declared\\n// here: left undeclared they can be set by a consumer class on the skeleton or\\n// scoped from any ancestor, and their defaults live at the point of use below.\\n// Layout tokens are declared, so an ancestor cannot silently relay out a nested\\n// skeleton that had nothing to do with the intent — but at zero specificity, so\\n// a consumer's own class still outranks them whatever order the stylesheets load\\n// in. Variant blocks override this one and must follow it.\\n:where(.d-skeleton) {\\n  --d-skeleton-gap: 0.5em;\\n  --d-skeleton-display: flex;\\n  --d-skeleton-item-width: auto;\\n}\\n\\n// A lone line matches the real element's line box; stacked lines drop to ink\\n// height and sit one leading apart, so a paragraph reads as separate lines. The\\n// two are mutually exclusive rather than ordered, so moving one cannot change\\n// what wins.\\n:where(.d-skeleton--text:not(.d-skeleton--multiline)) {\\n  --d-skeleton-item-height: 1lh;\\n}\\n\\n:where(.d-skeleton--text.d-skeleton--multiline) {\\n  --d-skeleton-item-height: 1em;\\n\\n  // The leading is deliberately not derived from the item height a caller may\\n  // have supplied. That value can be taller than the line box, or `auto`, or a\\n  // variable resolving to nothing — each of which either bottoms the\\n  // subtraction out or makes it uncomputable, closing the gap entirely.\\n  --d-skeleton-gap: max(0.25em, calc(1lh - 1em));\\n}\\n\\n:where(.d-skeleton--rect) {\\n  --d-skeleton-item-height: 2.5em;\\n}\\n\\n:where(.d-skeleton--circle) {\\n  --d-skeleton-item-height: 2em;\\n  --d-skeleton-item-width: 2em;\\n  --d-skeleton-radius: 50%;\\n}\\n\\n// Structure keeps its normal specificity: only the tokens above are meant to be\\n// overridden.\\n.d-skeleton {\\n  display: var(--d-skeleton-display);\\n  flex-direction: column;\\n  gap: var(--d-skeleton-gap);\\n\\n  &__item {\\n    width: var(--d-skeleton-item-width);\\n    height: var(--d-skeleton-item-height, 1em);\\n\\n    // The reserved height is the point, so don't let a constrained parent\\n    // compress it.\\n    flex-shrink: 0;\\n    background: var(--d-skeleton-fill, var(--primary-very-low));\\n    border-radius: var(--d-skeleton-radius, var(--d-border-radius, 0.25em));\\n\\n    @media (prefers-reduced-motion: no-preference) {\\n      &.placeholder-animation {\\n        background-image: linear-gradient(\\n          to right,\\n          var(--d-skeleton-fill, var(--primary-very-low)),\\n          var(--d-skeleton-shimmer, var(--primary-low)) 50%,\\n          var(--d-skeleton-fill, var(--primary-very-low))\\n        );\\n\\n        // fixed band matching the shared keyframe's 2100px travel, so the\\n        // shimmer loops seamlessly at a width-independent speed\\n        background-size: 2100px 100%;\\n        animation-duration: var(--d-skeleton-duration, 2.5s);\\n      }\\n    }\\n  }\\n}\\n",".d-access-control {\\n  --d-access-control-prefix-width: var(--space-6);\\n  display: flex;\\n  flex-direction: column;\\n  gap: var(--space-2);\\n  width: 100%;\\n\\n  &__chooser {\\n    width: 100%;\\n  }\\n\\n  &__chooser .select-kit-header {\\n    font-weight: 400;\\n  }\\n\\n  &__rows {\\n    display: flex;\\n    flex-direction: column;\\n    border: 1px solid var(--content-border-color);\\n    border-radius: var(--d-border-radius);\\n  }\\n\\n  &__row {\\n    display: flex;\\n    align-items: center;\\n    justify-content: space-between;\\n    gap: var(--space-2);\\n    border-bottom: 1px solid var(--content-border-color);\\n    padding: var(--space-1) var(--space-2);\\n\\n    &:last-child {\\n      border-bottom: none;\\n    }\\n  }\\n\\n  &__item {\\n    flex: 1 1 auto;\\n    min-width: 0;\\n    overflow: hidden;\\n    text-overflow: ellipsis;\\n    white-space: nowrap;\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-1);\\n  }\\n\\n  &__row.--group .d-access-control__item-icon {\\n    border-radius: 999px;\\n    background-color: var(--primary-100);\\n    width: var(--d-access-control-prefix-width);\\n    height: var(--d-access-control-prefix-width);\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n  }\\n\\n  &__row.--group .d-access-control__item-icon svg {\\n    width: var(--space-3);\\n    height: var(--space-3);\\n  }\\n\\n  &__tooltip {\\n    font-size: var(--font-down-3);\\n    background: var(--primary-100);\\n    padding: var(--space-half) var(--space-1);\\n    border-radius: var(--d-border-radius);\\n    color: var(--d-input-text-color--disabled);\\n  }\\n\\n  &__permission.btn-default {\\n    border: none;\\n\\n    &:hover {\\n      border: none;\\n    }\\n  }\\n\\n  &__permission-menu-content {\\n    z-index: z(\\"modal\\", \\"dropdown\\");\\n  }\\n\\n  &__permission-option.--remove .d-access-control__permission-label {\\n    color: var(--danger);\\n  }\\n\\n  &__permission-texts {\\n    display: flex;\\n    flex-direction: column;\\n    align-items: flex-start;\\n    line-height: var(--line-height-medium);\\n  }\\n\\n  &__permission-label {\\n    font-weight: bold;\\n    color: var(--primary);\\n  }\\n\\n  &__permission-description {\\n    font-size: var(--font-down-1);\\n    color: var(--primary-medium);\\n    white-space: normal;\\n    text-align: start;\\n  }\\n\\n  &__add {\\n    width: 100%;\\n  }\\n}\\n",".color-picker {\\n  display: flex;\\n  align-items: stretch;\\n  position: relative;\\n  width: 12em;\\n\\n  .add-on {\\n    @include form-item-sizing;\\n    position: absolute;\\n    pointer-events: none;\\n  }\\n\\n  .hex-input {\\n    border-radius: 0;\\n    border-bottom-left-radius: var(--d-input-border-radius);\\n    border-top-left-radius: var(--d-input-border-radius);\\n    margin: 0;\\n    width: 50%;\\n  }\\n\\n  .add-on + .hex-input {\\n    padding-left: 1.33em;\\n  }\\n\\n  .picker {\\n    padding: 0;\\n    border-left: none;\\n    border-bottom-left-radius: 0;\\n    border-top-left-radius: 0;\\n    cursor: pointer;\\n    margin-bottom: 0;\\n    height: unset;\\n    width: 50%;\\n  }\\n}\\n",".char-counter {\\n  &__ratio {\\n    display: block;\\n    text-align: right;\\n    margin-top: 0.5rem;\\n  }\\n\\n  &.exceeded {\\n    > textarea {\\n      border-color: var(--danger);\\n      outline-color: var(--danger);\\n    }\\n\\n    &__ratio {\\n      color: var(--danger);\\n    }\\n  }\\n}\\n",".conditional-loading-section {\\n  &.is-loading {\\n    padding: 2em;\\n    margin: 1em;\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    background: var(--primary-very-low);\\n    flex-direction: column;\\n\\n    .title {\\n      font-size: var(--font-up-1);\\n      font-weight: 700;\\n    }\\n  }\\n\\n  &:not(.is-loading) {\\n    animation: fadein 0.5s;\\n\\n    @media (prefers-reduced-motion) {\\n      animation-duration: 0s;\\n    }\\n  }\\n\\n  @keyframes fadein {\\n    from {\\n      opacity: 0;\\n    }\\n\\n    to {\\n      opacity: 1;\\n    }\\n  }\\n}\\n",".calendar-date-time-input {\\n  padding: 5px;\\n  border: 1px solid var(--content-border-color);\\n  z-index: 1;\\n  background: var(--secondary);\\n  width: 200px;\\n  box-sizing: border-box;\\n  margin-left: 1em;\\n\\n  .fake-input {\\n    display: none;\\n  }\\n\\n  .date-picker {\\n    display: flex;\\n    flex-direction: column;\\n    width: auto;\\n    box-sizing: border-box;\\n\\n    .pika-single {\\n      position: relative !important;\\n      flex: 1;\\n      display: flex;\\n      border: 0;\\n    }\\n  }\\n\\n  .time-pickers {\\n    display: flex;\\n    justify-content: center;\\n    flex: 1;\\n    margin-top: 1em;\\n    align-items: center;\\n    padding: 0.25em;\\n    border-top: 1px solid var(--primary-low-mid);\\n    box-sizing: border-box;\\n\\n    .d-icon {\\n      color: var(--primary-medium);\\n      margin-right: 0.5em;\\n    }\\n\\n    .time-picker {\\n      box-shadow: none;\\n      margin: 0;\\n      box-sizing: border-box;\\n      width: 100%;\\n    }\\n  }\\n}\\n",".composer-toggle-switch {\\n  --toggle-switch-width: 52px;\\n  --toggle-switch-height: 26px;\\n  justify-content: center;\\n  display: flex;\\n  align-items: center;\\n  border: 0;\\n  padding: 0;\\n  background: transparent;\\n\\n  &:focus-visible {\\n    outline: none;\\n  }\\n\\n  &[disabled] {\\n    opacity: 0.5;\\n    cursor: not-allowed;\\n  }\\n\\n  &__slider {\\n    display: inline-block;\\n    background: var(--primary-low);\\n    width: var(--toggle-switch-width);\\n    height: var(--toggle-switch-height);\\n    position: relative;\\n    vertical-align: middle;\\n    border-radius: var(--d-border-radius);\\n\\n    :focus-visible & {\\n      outline: 2px solid var(--tertiary);\\n      outline-offset: 2px;\\n    }\\n\\n    &:hover {\\n      background: var(--d-hover);\\n    }\\n\\n    &:active {\\n      background-color: var(--primary-low);\\n    }\\n\\n    &::before {\\n      content: \\"\\";\\n      display: block;\\n      position: absolute;\\n      background-color: var(--tertiary-low);\\n      width: calc(var(--toggle-switch-height) - var(--space-half));\\n      height: calc(var(--toggle-switch-height) - var(--space-1));\\n      top: var(--space-half);\\n      border-radius: var(--d-border-radius);\\n      box-shadow: 0 1px 2px 1px rgb(var(--tertiary-rgb), 0.2);\\n\\n      .--markdown & {\\n        transform: translateX(0.125rem);\\n      }\\n\\n      .--rte & {\\n        transform: translateX(\\n          calc(var(--toggle-switch-width) - var(--toggle-switch-height))\\n        );\\n      }\\n    }\\n  }\\n\\n  &__left-icon,\\n  &__right-icon {\\n    display: inline-flex;\\n    align-items: center;\\n    justify-content: center;\\n    position: absolute;\\n    height: 100%;\\n    width: calc(var(--toggle-switch-height) - var(--space-half));\\n    color: var(--primary-high);\\n\\n    .d-icon {\\n      vertical-align: text-bottom;\\n    }\\n\\n    @media (prefers-reduced-motion: reduce) {\\n      transition-duration: 0ms;\\n    }\\n  }\\n\\n  &__left-icon {\\n    left: var(--space-half);\\n\\n    .--markdown & {\\n      color: var(--primary);\\n    }\\n  }\\n\\n  &__right-icon {\\n    right: var(--space-half);\\n\\n    .--rte & {\\n      color: var(--primary);\\n    }\\n  }\\n}\\n",".convert-to-public-topic .modal-body {\\n  .instructions {\\n    margin-bottom: 1em;\\n  }\\n}\\n",".content-language-preferences-modal {\\n  &__understood {\\n    display: grid;\\n    gap: var(--space-1);\\n    width: 100%;\\n\\n    > span {\\n      color: var(--primary);\\n      font-size: var(--font-down-1-rem);\\n      font-weight: 600;\\n    }\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.fk-d-menu[data-identifier=\\"d-autocomplete\\"] {\\n  z-index: z(\\"modal\\", \\"dialog\\") + 1;\\n  animation: fade-in ease 0.25s 1 forwards !important;\\n\\n  --d-border-radius: var(--space-2);\\n\\n  // Override compose.scss autocomplete styles to remove double styling\\n  // Let d-menu handle the container border/shadow/radius\\n  .autocomplete {\\n    border: none;\\n    box-shadow: none;\\n    border-radius: 0;\\n\\n    ul {\\n      li {\\n        &:first-of-type a {\\n          border-top-left-radius: 0;\\n          border-top-right-radius: 0;\\n        }\\n\\n        &:last-of-type a {\\n          border-bottom-left-radius: 0;\\n          border-bottom-right-radius: 0;\\n        }\\n      }\\n    }\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.filter-input.d-filter-controls__input {\\n  padding-left: 0;\\n}\\n\\n.d-filter-controls {\\n  display: flex;\\n  gap: var(--space-2);\\n  margin-block: var(--space-2);\\n\\n  .filter-input-container {\\n    flex: 1 1 auto;\\n  }\\n\\n  &.--dropdowns-in-filter-drawer {\\n    display: flex;\\n    flex-direction: column;\\n  }\\n\\n  &__inputs {\\n    display: flex;\\n    gap: var(--space-2);\\n    flex: 1 1 auto;\\n  }\\n\\n  &__dropdowns {\\n    display: grid;\\n    grid-template-columns: repeat(auto-fit, minmax(5em, 1fr));\\n    gap: var(--space-2);\\n  }\\n\\n  &__additional-filters {\\n    display: flex;\\n    flex-wrap: wrap;\\n    align-items: end;\\n    gap: var(--space-2);\\n  }\\n\\n  &__dropdown {\\n    flex: 1 1 auto;\\n\\n    &.--active {\\n      border-color: var(--tertiary);\\n    }\\n  }\\n\\n  &__no-results {\\n    display: flex;\\n    flex-direction: column;\\n    text-align: center;\\n    justify-content: center;\\n    padding: var(--space-4);\\n    gap: var(--space-2);\\n\\n    .btn {\\n      align-self: center;\\n    }\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.docked-composer {\\n  --docked-composer-input-min-height: 2.5em;\\n  --docked-composer-max-width: 100%;\\n  --docked-composer-content-offset: 0;\\n  --docked-composer-drag-offset: 0px;\\n  position: sticky;\\n  bottom: 0;\\n  z-index: 50;\\n  background: var(--secondary);\\n  padding: 0.75em 0 max(env(safe-area-inset-bottom), 0.75em);\\n  margin-top: 1em;\\n  display: flex;\\n  flex-direction: column;\\n  gap: 0.5em;\\n\\n  // fade scrolling content into the sticky composer's solid background\\n  &::before {\\n    content: \\"\\";\\n    position: absolute;\\n    left: 0;\\n    right: 0;\\n    top: -2.5em;\\n    height: 2.5em;\\n    background: linear-gradient(to bottom, transparent, var(--secondary));\\n    pointer-events: none;\\n  }\\n\\n  html.keyboard-visible & {\\n    padding-bottom: 0.5em;\\n  }\\n\\n  &__resize-handle {\\n    width: 100%;\\n    max-width: var(--docked-composer-max-width);\\n    padding-left: var(--docked-composer-content-offset);\\n    margin: 0 auto;\\n    box-sizing: border-box;\\n    height: 0.5em;\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    user-select: none;\\n\\n    &::after {\\n      content: \\"\\";\\n      width: 2em;\\n      height: 3px;\\n      background: var(--primary-low);\\n      border-radius: 3px;\\n      transition: background 0.15s ease-in-out;\\n    }\\n\\n    &:hover::after,\\n    &:active::after,\\n    &:focus-visible::after {\\n      background: var(--primary-medium);\\n    }\\n\\n    &:focus-visible {\\n      outline: 2px solid var(--tertiary);\\n      outline-offset: 2px;\\n    }\\n  }\\n\\n  &__header {\\n    width: 100%;\\n    max-width: var(--docked-composer-max-width);\\n    padding-left: var(--docked-composer-content-offset);\\n    margin: 0 auto;\\n    box-sizing: border-box;\\n  }\\n\\n  &__inner {\\n    display: flex;\\n    align-items: flex-end;\\n    gap: 0.5em;\\n    width: 100%;\\n    max-width: var(--docked-composer-max-width);\\n    box-sizing: border-box;\\n  }\\n\\n  &__editor {\\n    flex: 1 1 auto;\\n    min-width: 0;\\n    contain: inline-size;\\n    position: relative;\\n\\n    .d-editor-container {\\n      background: transparent;\\n    }\\n\\n    .d-editor-button-bar__scroll-btn {\\n      --fade-color: var(--d-input-bg-color);\\n    }\\n\\n    .d-editor-textarea-column {\\n      position: relative;\\n      border: var(--d-input-border);\\n      border-radius: var(--d-input-border-radius);\\n      background: var(--d-input-bg-color);\\n      transition: border-color 0.15s ease-in-out;\\n\\n      &:focus-within {\\n        border-color: var(--d-input-focused-color);\\n        outline: 2px solid var(--d-input-focused-color);\\n        outline-offset: -2px;\\n      }\\n\\n      &:has(.d-editor-input[disabled]) {\\n        background: var(--d-input-bg-color--disabled);\\n      }\\n    }\\n\\n    // we deliberately don't show the preview in the docked composer — users\\n    // can toggle to the rich editor via the toolbar's RTE switch for a\\n    // live preview. `@processPreview={{false}}` on DEditor skips cooking,\\n    // but DEditor still renders a wrapper element that we hide here.\\n    .d-editor-preview-wrapper {\\n      display: none;\\n    }\\n\\n    .d-editor-textarea-wrapper {\\n      border: none;\\n      background: transparent;\\n      box-shadow: none;\\n\\n      &.in-focus {\\n        outline: none;\\n      }\\n    }\\n\\n    .d-editor-input {\\n      border: none;\\n      background: transparent;\\n      max-height: 70vh;\\n      min-height: calc(\\n        var(--docked-composer-input-min-height) +\\n          var(--docked-composer-drag-offset, 0px)\\n      );\\n      resize: none;\\n\\n      // reserve room for the absolutely-positioned send button\\n      padding-right: 3.5em;\\n\\n      &:focus-visible {\\n        outline: none;\\n      }\\n    }\\n  }\\n\\n  &--auto-resize {\\n    --docked-composer-auto-resize-max-height: min(\\n      70vh,\\n      calc(\\n        var(--docked-composer-input-min-height) +\\n          var(--docked-composer-max-resize-offset, 400px)\\n      )\\n    );\\n  }\\n\\n  &--auto-resize &__editor {\\n    .d-editor-input {\\n      flex: none;\\n      height: auto;\\n      max-height: var(--docked-composer-auto-resize-max-height);\\n      min-height: var(--docked-composer-input-min-height);\\n      overflow-y: auto;\\n    }\\n\\n    textarea.d-editor-input {\\n      field-sizing: content;\\n    }\\n\\n    .ProseMirror-container {\\n      height: auto;\\n      max-height: var(--docked-composer-auto-resize-max-height);\\n    }\\n\\n    .ProseMirror.d-editor-input {\\n      flex: none;\\n      overflow-y: visible;\\n    }\\n  }\\n\\n  // submit button yielded into DEditor's textarea column, positioned in\\n  // the bottom-right corner of the input box (ChatGPT-style) — icon only.\\n  // Consumers overriding the `<:submit>` block should reuse this class so\\n  // their buttons inherit positioning + chrome.\\n  &__submit-btn.btn {\\n    position: absolute;\\n    right: 0.5em;\\n    bottom: 0.5em;\\n    z-index: 2;\\n    min-width: auto;\\n    min-height: auto;\\n    padding: 0.35em 0.5em;\\n    border-radius: var(--d-button-border-radius);\\n    background: transparent !important;\\n\\n    .d-icon {\\n      color: var(--tertiary) !important;\\n      font-size: var(--font-up-1);\\n    }\\n\\n    &:hover:not(:disabled),\\n    &:focus-visible {\\n      background: var(--primary-very-low) !important;\\n\\n      .d-icon {\\n        color: var(--tertiary-hover, var(--tertiary)) !important;\\n      }\\n    }\\n\\n    &:disabled,\\n    &[disabled] {\\n      cursor: not-allowed;\\n\\n      .d-icon {\\n        color: var(--primary-low-mid) !important;\\n      }\\n    }\\n  }\\n\\n  &__uploads {\\n    display: flex;\\n    flex-wrap: wrap;\\n    gap: 0.5em;\\n    width: 100%;\\n    max-width: var(--docked-composer-max-width);\\n    padding-block: 1rem;\\n    padding-left: var(--docked-composer-content-offset);\\n    margin: 0 auto;\\n    box-sizing: border-box;\\n  }\\n\\n  &__upload {\\n    display: flex;\\n    align-items: center;\\n    border: 1px solid var(--primary-low);\\n    border-radius: 10em;\\n    padding-left: 0.75em;\\n    color: var(--primary-high);\\n    font-size: var(--font-down-2);\\n\\n    &-progress {\\n      margin-left: 0.5em;\\n    }\\n\\n    &-remove:hover .d-icon,\\n    &-cancel:hover .d-icon {\\n      color: var(--danger);\\n    }\\n  }\\n}\\n",".d-toggle-switch {\\n  --toggle-switch-width: 45px;\\n  --toggle-switch-height: 24px;\\n  display: flex;\\n  align-items: center;\\n  gap: 0.5rem;\\n\\n  &:focus {\\n    .d-toggle-switch__checkbox-slider {\\n      outline: 2px solid var(--tertiary);\\n      outline-offset: 2px;\\n    }\\n  }\\n\\n  &:hover {\\n    .d-toggle-switch__checkbox-slider {\\n      background-color: var(--primary-high);\\n    }\\n\\n    .d-toggle-switch__checkbox[aria-checked=\\"true\\"]:not([disabled])\\n      + .d-toggle-switch__checkbox-slider {\\n      background-color: var(--tertiary-hover);\\n    }\\n  }\\n\\n  &__label {\\n    position: relative;\\n    display: inline-block;\\n    cursor: pointer;\\n    margin: 0;\\n  }\\n\\n  &__checkbox {\\n    position: absolute;\\n    border: 0;\\n    padding: 0;\\n    background: transparent;\\n\\n    &:focus {\\n      + .d-toggle-switch__checkbox-slider {\\n        outline: 2px solid var(--tertiary);\\n        outline-offset: 2px;\\n      }\\n\\n      // Outline should show only when tabbing, not clicking\\n      &:not(:focus-visible) {\\n        + .d-toggle-switch__checkbox-slider {\\n          outline: none;\\n        }\\n      }\\n    }\\n  }\\n\\n  &__checkbox[aria-checked=\\"true\\"] + .d-toggle-switch__checkbox-slider {\\n    background-color: var(--tertiary);\\n  }\\n\\n  &__checkbox[aria-checked=\\"true\\"] + .d-toggle-switch__checkbox-slider::before {\\n    left: calc(\\n      var(--toggle-switch-width) - var(--toggle-switch-height) * 0.875\\n    );\\n  }\\n\\n  &__checkbox[disabled] + .d-toggle-switch__checkbox-slider {\\n    opacity: 0.5;\\n    cursor: not-allowed;\\n\\n    &::before {\\n      cursor: not-allowed;\\n    }\\n  }\\n\\n  &__checkbox-slider {\\n    display: inline-block;\\n    cursor: pointer;\\n    background: var(--primary-low-mid);\\n    border-radius: var(--toggle-switch-height);\\n    width: var(--toggle-switch-width);\\n    height: var(--toggle-switch-height);\\n    position: relative;\\n    vertical-align: middle;\\n    transition: background 0.25s;\\n\\n    .d-icon {\\n      width: calc(var(--toggle-switch-height) * 0.54) !important;\\n      height: calc(var(--toggle-switch-height) * 0.54) !important;\\n      color: var(--secondary) !important;\\n      position: absolute;\\n      top: 50%;\\n      left: calc(var(--toggle-switch-height) * 0.291);\\n      transform: translateY(-50%);\\n    }\\n  }\\n\\n  &__checkbox-slider::before,\\n  &__checkbox-slider::after {\\n    content: \\"\\";\\n    display: block;\\n    position: absolute;\\n    cursor: pointer;\\n  }\\n\\n  &__checkbox-slider::before {\\n    background: var(--secondary);\\n    border-radius: 50%;\\n    width: calc(var(--toggle-switch-height) * 0.75);\\n    height: calc(var(--toggle-switch-height) * 0.75);\\n    top: calc(var(--toggle-switch-height) * 0.125);\\n    left: calc(var(--toggle-switch-height) * 0.125);\\n    transition: left 0.25s;\\n\\n    @media (prefers-reduced-motion: reduce) {\\n      transition-duration: 0ms;\\n    }\\n  }\\n}\\n",".d-virtual-list {\\n  /* This element is the scroll viewport the virtualizer measures and drives. Its\\n     height belongs to the consumer: a zero-height element yields an empty window\\n     and silently renders nothing. Box spacing here would offset the engine's\\n     measured total from the DOM scroll height permanently, so put padding and\\n     borders on a wrapper or on the rows.\\n\\n     Vertical only: rows are absolutely positioned and stretched across the inline\\n     axis, so they offer no intrinsic width for an inline scrollbar to act on.\\n     Content wider than the viewport has to scroll inside its own row. */\\n  overflow: hidden auto;\\n  overscroll-behavior: contain;\\n\\n  /* Rows are absolutely positioned to approximate offsets, so the browser must not\\n     pick the list as a scroll anchor — its correction would fight the virtualizer's\\n     own scroll compensation and produce a jump. */\\n  overflow-anchor: none;\\n\\n  &__sizer {\\n    margin: 0;\\n    padding: 0;\\n\\n    /* Removing the marker also removes the implicit list semantics in some\\n       screen readers, so only do it once the element is carrying an explicit\\n       role of its own. */\\n\\n    &[role] {\\n      list-style: none;\\n    }\\n  }\\n}\\n","$calendar-icon: '<svg xmlns=\\"http://www.w3.org/2000/svg\\" width=\\"14px\\" height=\\"16px\\" viewBox=\\"0 0 448 512\\"><path d=\\"M400 64h-48V12c0-6.6-5.4-12-12-12h-40c-6.6 0-12 5.4-12 12v52H160V12c0-6.6-5.4-12-12-12h-40c-6.6 0-12 5.4-12 12v52H48C21.5 64 0 85.5 0 112v352c0 26.5 21.5 48 48 48h352c26.5 0 48-21.5 48-48V112c0-26.5-21.5-48-48-48zm-6 400H54c-3.3 0-6-2.7-6-6V160h352v298c0 3.3-2.7 6-6 6z\\"></path></svg>';\\n\\n.d-date-input {\\n  display: inline-flex;\\n  cursor: pointer;\\n  flex-direction: column;\\n  min-width: 140px;\\n  flex: 1 0 auto;\\n\\n  .date-picker {\\n    cursor: pointer;\\n    margin: 0;\\n    text-align: left;\\n    width: 100%;\\n    box-shadow: none;\\n    position: relative;\\n\\n    &::placeholder {\\n      font-size: var(--font-0);\\n      color: var(--primary-medium);\\n    }\\n\\n    &:focus {\\n      @include default-focus;\\n    }\\n\\n    // iOS doesn't display the placeholder attribute for date inputs\\n    html.ios-device &:not(.--has-value)::after {\\n      font-size: var(--font-0);\\n      color: var(--primary-medium);\\n      content: attr(placeholder);\\n    }\\n\\n    // use custom icon and fix issues across browsers\\n    // - Safari does not use an icon\\n    // - default Chrome/IE icon too tall, makes input height inconsistent\\n    // - default Chrome/IE icon are black on dark themes\\n    // - allows themes to style as needed\\n    // Note that this does nothing in Firefox\\n    html:not(.ios-device) & {\\n      &::after {\\n        content: \\"\\";\\n        mask: svg-uri($calendar-icon) no-repeat 50% 50%;\\n        position: absolute;\\n        right: 4px;\\n        top: 0;\\n        box-sizing: border-box;\\n        background-color: var(--primary);\\n        height: 100%;\\n        width: 20px;\\n        z-index: 1;\\n      }\\n\\n      &::-webkit-calendar-picker-indicator {\\n        background: transparent;\\n        position: absolute;\\n        cursor: pointer;\\n        right: 0;\\n        z-index: 2;\\n      }\\n    }\\n  }\\n\\n  .pika-single {\\n    margin-left: -1px;\\n    margin-top: 1px;\\n\\n    .pika-row td {\\n      .pika-button.pika-day {\\n        box-shadow: none;\\n        border-radius: 0;\\n      }\\n    }\\n  }\\n}\\n\\n.d-date-input + .d-time-input {\\n  margin-left: 1px;\\n}\\n\\n.d-time-input + .d-date-input {\\n  margin-left: 1px;\\n}\\n\\n.d-date-input + .clear-date-time {\\n  margin-left: 1px;\\n}\\n",".pika-table {\\n  th,\\n  td {\\n    padding: 0 !important;\\n    border-top: none !important;\\n    border-bottom: none !important;\\n  }\\n}\\n\\n.date-picker-wrapper {\\n  position: relative;\\n  display: inline-block;\\n}\\n\\ninput.date-picker {\\n  margin: 0;\\n  max-width: 180px;\\n}\\n\\n.pika-single {\\n  position: absolute !important;\\n}\\n","@use \\"lib/viewport\\";\\n\\n.d-date-range-picker {\\n  --d-date-range-picker-nav-size: var(--space-10);\\n  display: grid;\\n  grid-template-columns: max-content 1fr;\\n  background: var(--secondary);\\n  min-width: 0;\\n  box-sizing: border-box;\\n\\n  @include viewport.from(sm) {\\n    width: 40rem;\\n    max-width: 100vw;\\n  }\\n\\n  @include viewport.until(sm) {\\n    grid-template-columns: 1fr;\\n    grid-template-rows: max-content 1fr;\\n  }\\n\\n  &__presets {\\n    display: flex;\\n    flex-direction: column;\\n    padding: var(--space-2) 0;\\n    border-right: 1px solid var(--primary-low);\\n    min-width: min-content;\\n\\n    @include viewport.until(sm) {\\n      flex-direction: row;\\n      gap: var(--space-1);\\n      padding: var(--space-2) var(--space-4);\\n      border-right: none;\\n      border-bottom: 1px solid var(--primary-low);\\n      min-width: 0;\\n      overflow-x: auto;\\n      scrollbar-width: none;\\n      mask-image: linear-gradient(\\n        to right,\\n        transparent 0,\\n        black var(--space-4),\\n        black calc(100% - var(--space-6)),\\n        transparent 100%\\n      );\\n\\n      &::-webkit-scrollbar {\\n        display: none;\\n      }\\n    }\\n  }\\n\\n  &__preset {\\n    text-align: left;\\n    background: transparent;\\n    border: 0;\\n    padding: var(--space-2) var(--space-3);\\n    font: inherit;\\n    color: var(--primary);\\n    cursor: pointer;\\n    border-radius: 0;\\n\\n    &:hover {\\n      background: var(--primary-low);\\n    }\\n\\n    &.is-active {\\n      background: var(--tertiary-low);\\n      font-weight: 700;\\n    }\\n\\n    @include viewport.until(sm) {\\n      flex-shrink: 0;\\n      border: 1px solid var(--primary-low);\\n      border-radius: var(--space-1);\\n      white-space: nowrap;\\n    }\\n  }\\n\\n  &__body {\\n    display: flex;\\n    flex-direction: column;\\n    padding: var(--space-2);\\n    min-width: 0;\\n  }\\n\\n  &__nav {\\n    width: var(--d-date-range-picker-nav-size);\\n\\n    &.--prev {\\n      grid-column: 1;\\n    }\\n\\n    &.--next {\\n      grid-column: 3;\\n    }\\n\\n    &:hover {\\n      background: var(--primary-low);\\n      color: var(--primary);\\n    }\\n  }\\n\\n  &__months {\\n    display: flex;\\n    gap: var(--space-4);\\n    min-width: 0;\\n\\n    @include viewport.until(sm) {\\n      gap: 0;\\n    }\\n  }\\n\\n  &__month {\\n    flex: 1;\\n    min-width: 0;\\n  }\\n\\n  &__month-header {\\n    display: grid;\\n    grid-template-columns:\\n      var(--d-date-range-picker-nav-size)\\n      1fr\\n      var(--d-date-range-picker-nav-size);\\n    align-items: center;\\n    min-height: var(--d-date-range-picker-nav-size);\\n    font-weight: 500;\\n    padding-bottom: var(--space-2);\\n  }\\n\\n  &__month-title {\\n    grid-column: 2;\\n    text-align: center;\\n  }\\n\\n  &__weekdays {\\n    display: grid;\\n    grid-template-columns: repeat(7, minmax(0, 1fr));\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-2);\\n    text-align: center;\\n    padding-bottom: var(--space-1);\\n  }\\n\\n  &__grid {\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-1);\\n  }\\n\\n  &__week {\\n    display: grid;\\n    grid-template-columns: repeat(7, minmax(0, 1fr));\\n  }\\n\\n  &__day {\\n    background: transparent;\\n    border: 0;\\n    padding: 0;\\n    border-radius: var(--space-1);\\n    color: var(--primary);\\n    aspect-ratio: 1;\\n    font-size: var(--font-down-2-rem);\\n\\n    @include viewport.until(sm) {\\n      font-size: var(--font-down-1-rem);\\n    }\\n\\n    &:hover:not(.--disabled) {\\n      background: var(--tertiary-low);\\n    }\\n\\n    &.--disabled {\\n      color: var(--primary-low-mid);\\n      cursor: not-allowed;\\n    }\\n\\n    &.--in-range {\\n      background: var(--tertiary-very-low, var(--tertiary-low));\\n    }\\n\\n    &.--hover-preview,\\n    &.--hover-end {\\n      background: var(--tertiary-low);\\n    }\\n\\n    &.--start,\\n    &.--end {\\n      background: var(--tertiary);\\n      color: var(--secondary);\\n      font-weight: 600;\\n\\n      &:hover {\\n        background: var(--tertiary-hover, var(--tertiary));\\n      }\\n    }\\n\\n    // range cells form a continuous strip, rounded only where the strip ends:\\n    // at a cap, a row edge, or a month edge;\\n    // :where keeps this reset below the corner rules' specificity\\n    &:where(.--in-range, .--hover-preview, .--hover-end, .--start, .--end) {\\n      border-radius: 0;\\n    }\\n\\n    &.--start,\\n    &.--month-start,\\n    &:first-child {\\n      border-start-start-radius: var(--space-1);\\n      border-end-start-radius: var(--space-1);\\n    }\\n\\n    &.--end,\\n    &.--hover-end,\\n    &.--month-end,\\n    &:last-child {\\n      border-start-end-radius: var(--space-1);\\n      border-end-end-radius: var(--space-1);\\n    }\\n\\n    &:focus-visible {\\n      outline: 2px solid var(--tertiary);\\n      outline-offset: -2px;\\n    }\\n  }\\n\\n  &__inputs {\\n    display: grid;\\n    grid-template-columns: 1fr 1fr;\\n    gap: var(--space-2);\\n    margin-top: var(--space-3);\\n  }\\n\\n  &__input {\\n    width: 100%;\\n    box-sizing: border-box;\\n    border: 1px solid var(--primary-low);\\n    padding: var(--space-1) var(--space-2);\\n    border-radius: var(--space-1);\\n    background: var(--secondary);\\n    color: var(--primary);\\n    font-size: var(--font-down-1);\\n    min-height: 1.75rem;\\n\\n    &:focus-visible {\\n      outline: 2px solid var(--tertiary);\\n      outline-offset: -1px;\\n    }\\n  }\\n\\n  &__footer {\\n    display: flex;\\n    justify-content: flex-end;\\n    gap: var(--space-2);\\n    margin-top: var(--space-3);\\n  }\\n}\\n",".d-date-time-input-range {\\n  .from {\\n    margin-bottom: 0.5em;\\n  }\\n}\\n",".d-date-time-input {\\n  display: flex;\\n  box-sizing: border-box;\\n  position: relative;\\n\\n  .date-picker {\\n    max-width: unset;\\n  }\\n\\n  .d-date-time-input {\\n    margin-left: auto;\\n    flex: 1 1 auto;\\n  }\\n\\n  .d-time-input {\\n    .select-kit-header {\\n      border-color: transparent;\\n    }\\n  }\\n\\n  .d-date-input + .d-time-input {\\n    margin-left: 1px;\\n  }\\n\\n  .d-time-input + .d-date-input {\\n    margin-right: 1px;\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.d-combo-button {\\n  display: inline-flex;\\n\\n  &.--has-menu {\\n    .d-combo-button-button {\\n      border-top-right-radius: 0;\\n      border-bottom-right-radius: 0;\\n      border-right-color: transparent;\\n    }\\n\\n    .d-combo-button-menu {\\n      border-top-left-radius: 0;\\n      border-bottom-left-radius: 0;\\n      border-left-color: transparent;\\n      margin-left: 0.1em; // more flexible than border, and scales with UI zoom\\n\\n      &.fk-d-menu__trigger .d-icon {\\n        font-size: var(--font-down-1);\\n      }\\n    }\\n\\n    // A filled variant reads the gutter above as a slot between two solid fills.\\n    // A bordered one has no fill to separate, so the same gutter leaves the top\\n    // and bottom border unpainted across it; those halves overlap onto one shared\\n    // line instead. :where() adds no specificity, so theme overrides still win.\\n    .d-combo-button-button:where(.btn-default) {\\n      border-right: var(--d-button-default-border);\\n    }\\n\\n    // Both facing edges stay painted and overlap exactly, so they coincide into a\\n    // single 1px divider instead of stacking into a 2px double line.\\n    .d-combo-button-menu:where(.btn-default) {\\n      border-left: var(--d-button-default-border);\\n      margin-left: -1px;\\n    }\\n  }\\n\\n  @include viewport.until(sm) {\\n    .d-icon {\\n      margin-right: 0;\\n    }\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.topic-drafts-menu-content .dropdown-menu {\\n  .btn .d-button-label {\\n    @include ellipsis;\\n  }\\n\\n  .view-all-drafts {\\n    display: flex;\\n    justify-content: space-between;\\n\\n    span:first-child {\\n      color: var(--primary-high);\\n    }\\n  }\\n\\n  @include viewport.from(sm) {\\n    max-width: 350px;\\n    min-width: 275px;\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.empty-state {\\n  &__container {\\n    &.--with-image {\\n      text-align: center;\\n    }\\n\\n    &.--text-only {\\n      .empty-state__title {\\n        font-family: var(--heading-font-family);\\n        font-weight: var(--heading-font-weight);\\n        font-size: var(--font-up-1);\\n      }\\n    }\\n\\n    &.--empty-topic-filter {\\n      margin: 0 auto;\\n      width: 75%;\\n\\n      @include viewport.from(sm) {\\n        padding-top: 7rem;\\n      }\\n    }\\n\\n    &.--empty-channels-list {\\n      display: flex;\\n      flex-direction: column;\\n      justify-content: center;\\n      align-items: center;\\n      gap: 1rem;\\n      height: 100%;\\n\\n      .empty-state__image {\\n        margin-top: 0;\\n      }\\n    }\\n  }\\n\\n  &__image {\\n    svg {\\n      width: 200px;\\n\\n      @include viewport.until(sm) {\\n        width: 65vw;\\n      }\\n    }\\n\\n    @include viewport.until(sm) {\\n      margin-top: 8vh;\\n    }\\n  }\\n\\n  &__cta {\\n    margin-top: 2rem;\\n  }\\n\\n  &__tip {\\n    margin-top: 2rem;\\n    font-size: var(--font-down-1);\\n    color: var(--primary-medium);\\n\\n    .d-icon {\\n      font-size: var(--font-down-1);\\n    }\\n  }\\n}\\n",".expanding-text-area {\\n  width: 100%;\\n  min-width: 0;\\n\\n  > textarea {\\n    field-sizing: content;\\n    height: auto;\\n    resize: none;\\n    max-width: 100%;\\n    padding: var(--expanding-text-area-padding, 0.5em 0.65em);\\n    min-height: var(--expanding-text-area-min-height, auto);\\n    max-height: var(--expanding-text-area-max-height, none);\\n  }\\n\\n  @supports not (field-sizing: content) {\\n    display: grid;\\n    grid-template-columns: minmax(0, 1fr);\\n\\n    > textarea {\\n      grid-area: 1 / 1;\\n    }\\n\\n    &::after {\\n      content: attr(data-replicated-value) \\" \\";\\n      white-space: pre-wrap;\\n      word-break: break-word;\\n      visibility: hidden;\\n      grid-area: 1 / 1;\\n      box-sizing: border-box;\\n      padding: var(--expanding-text-area-padding, 0.5em 0.65em);\\n      border: 1px solid transparent;\\n      font: inherit;\\n      min-height: var(--expanding-text-area-min-height, auto);\\n      max-height: var(--expanding-text-area-max-height, none);\\n    }\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.feature-section {\\n  &__description {\\n    width: 100%;\\n  }\\n\\n  &__pin-message {\\n    margin-bottom: var(--space-1);\\n\\n    .d-icon {\\n      @include viewport.until(sm) {\\n        display: none;\\n      }\\n    }\\n  }\\n}\\n",".file-size-picker {\\n  display: flex;\\n\\n  .file-size-input {\\n    flex: 1;\\n    margin-bottom: 0;\\n  }\\n\\n  .file-size-unit-selector {\\n    flex: 0 0 8em;\\n  }\\n\\n  .select-kit .select-kit-header {\\n    border-left: 0;\\n  }\\n}\\n","// --------------------------------------------------\\n// Footer nav bar (displayed in DiscourseHub app and PWAs)\\n// --------------------------------------------------\\n\\n$footer-nav-height: 49px;\\n\\n:root {\\n  --footer-nav-height: #{$footer-nav-height};\\n}\\n\\nhtml.footer-nav-visible {\\n  #main-outlet {\\n    padding-bottom: calc(var(--footer-nav-height) + 15px);\\n  }\\n\\n  .with-topic-progress {\\n    bottom: calc(\\n      var(--footer-nav-height) + env(safe-area-inset-bottom) +\\n        var(--composer-height, 0px)\\n    );\\n  }\\n\\n  .posts-filtered-notice {\\n    transition: all linear 0.1s;\\n    bottom: calc(var(--footer-nav-height) + env(safe-area-inset-bottom));\\n  }\\n}\\n\\n.footer-nav {\\n  background-color: rgb(var(--header_background-rgb), 0.9);\\n  box-shadow: var(--shadow-footer-nav);\\n  height: var(--footer-nav-height);\\n  position: fixed;\\n  bottom: calc(var(--footer-nav-height) * -1);\\n  left: 0;\\n  width: 100%;\\n  z-index: z(\\"footer-nav\\");\\n  transition: all linear 0.1s;\\n\\n  .d-icon {\\n    color: var(--header_primary-medium);\\n  }\\n\\n  &.visible {\\n    bottom: 0;\\n    padding-bottom: max(5px, env(safe-area-inset-bottom));\\n  }\\n\\n  .footer-nav-widget {\\n    display: flex;\\n    justify-content: \\"space-evenly\\";\\n\\n    @include unselectable;\\n\\n    button {\\n      flex: 1;\\n      margin: 4px;\\n      border-radius: 2px;\\n      padding: 14px 18px;\\n\\n      &:disabled {\\n        opacity: 0.6;\\n      }\\n    }\\n  }\\n}\\n\\nhtml:not(.footer-nav-ipad) .footer-nav {\\n  background-color: rgb(var(--header_background-rgb), 0.7);\\n  backdrop-filter: blur(20px);\\n}\\n\\nhtml.footer-nav-ipad {\\n  padding-top: var(--footer-nav-height);\\n\\n  .footer-nav {\\n    bottom: auto;\\n    top: 0;\\n    background-color: var(--header_background);\\n    z-index: z(\\"ipad-header-nav\\");\\n    padding-bottom: 0; // resets safe-area-inset-bottom\\n  }\\n\\n  .d-header-wrap {\\n    top: var(--footer-nav-height);\\n  }\\n}\\n",".form-template-field {\\n  position: relative;\\n\\n  input,\\n  textarea,\\n  select {\\n    width: 100%;\\n  }\\n\\n  &__dropdown {\\n    border: 1px solid var(--primary-medium);\\n    border-radius: var(--d-input-border-radius);\\n    padding: 0.5em 0.65em;\\n    font-size: var(--font-0);\\n  }\\n\\n  &__multi-select {\\n    border: 1px solid var(--primary-medium);\\n    border-radius: var(--d-input-border-radius);\\n    padding: 0.5em 0.65em;\\n    font-size: var(--font-0);\\n  }\\n\\n  // END of what should be removed after updating dropdown/multi-select to use select-kit\\n  &__required-indicator {\\n    color: var(--danger);\\n    margin-left: 0.5em;\\n    font-size: var(--font-down-4);\\n  }\\n\\n  &__uploaded-files {\\n    list-style: none;\\n    margin-left: 0;\\n\\n    li {\\n      padding: 0.5rem;\\n      margin-block: 0.25rem;\\n      border: 1px solid var(--primary-low-mid);\\n      background: var(--primary-low);\\n      border-radius: var(--d-border-radius);\\n      display: flex;\\n      align-items: center;\\n\\n      a {\\n        @include ellipsis;\\n        width: 70%;\\n      }\\n\\n      span {\\n        color: var(--primary-high);\\n        margin-left: auto;\\n        font-size: var(--font-down-1);\\n      }\\n    }\\n\\n    .d-icon {\\n      color: var(--tertiary);\\n      margin-right: 0.5rem;\\n    }\\n  }\\n\\n  &__textarea {\\n    min-height: 100px;\\n  }\\n\\n  &__description {\\n    display: inline-block;\\n    margin-bottom: 0.25rem;\\n    font-size: var(--font-down-1);\\n    color: var(--primary-medium);\\n  }\\n\\n  &__upload-hidden-input,\\n  &__composer-hidden-input {\\n    position: absolute;\\n    opacity: 0;\\n    pointer-events: none;\\n  }\\n\\n  &__composer {\\n    // same default effective height (150px) than a text control\\n    height: 189px;\\n    width: 100%;\\n\\n    .d-editor-preview-wrapper {\\n      display: none;\\n    }\\n  }\\n}\\n",".group-member-dropdown {\\n  text-align: left;\\n}\\n",".group-selector-wrapper {\\n  .d-multi-select-trigger__selected-item > {\\n    .d-multi-select-trigger__selection-label {\\n      max-width: 10em;\\n    }\\n  }\\n\\n  .d-multi-select-trigger {\\n    width: 100%;\\n  }\\n}\\n",".group-form-automatic-membership-automatic,\\n.groups-form-grant-trust-level {\\n  margin-bottom: var(--space-3);\\n}\\n\\n.groups-form-visibility-access {\\n  .groups-form-visibility-label,\\n  .groups-form-members-visibility-label,\\n  .group-form-public-exit-label {\\n    margin-top: var(--space-4);\\n  }\\n\\n  .group-form-public-exit-label {\\n    margin-bottom: var(--space-5);\\n  }\\n\\n  .groups-form-join-method {\\n    margin-bottom: 0;\\n    padding: 0;\\n    border: 0;\\n    min-inline-size: 0;\\n\\n    legend {\\n      font-weight: normal;\\n      font-size: var(--font-0);\\n      color: var(--primary-high);\\n      padding: 0;\\n      margin-bottom: var(--space-2);\\n    }\\n  }\\n\\n  .groups-form-membership-request-template {\\n    margin-top: var(--space-4);\\n  }\\n}\\n",".hashtag-cooked {\\n  @include mention;\\n\\n  &:visited,\\n  &:hover {\\n    color: var(--primary);\\n  }\\n\\n  .hashtag-icon-placeholder {\\n    width: 0.72em;\\n    height: 0.72em;\\n    display: inline-block;\\n    color: var(--primary-medium);\\n    margin-right: var(--space-1);\\n  }\\n\\n  img.emoji,\\n  svg {\\n    width: 0.93em;\\n    height: 0.93em;\\n    vertical-align: -0.125em;\\n    margin-right: var(--space-1);\\n  }\\n\\n  .hashtag-category-square {\\n    display: inline-block;\\n    width: 0.72em;\\n    height: 0.72em;\\n    margin-left: 0.1em;\\n    margin-right: var(--space-1);\\n  }\\n}\\n\\n.hashtag-autocomplete {\\n  max-height: 13.5em;\\n  overflow-y: auto;\\n  box-shadow: var(--shadow-dropdown);\\n  border-radius: 8px;\\n\\n  &__fadeout {\\n    height: inherit;\\n    max-height: inherit;\\n    overflow-y: auto;\\n\\n    &::after {\\n      content: \\"\\";\\n      position: absolute;\\n      bottom: 0;\\n      width: 100%;\\n      height: 1.5em;\\n      background: linear-gradient(\\n        to bottom,\\n        rgb(var(--secondary-rgb), 0),\\n        rgb(var(--secondary-rgb), 100%)\\n      );\\n    }\\n  }\\n\\n  &__option {\\n    &:last-of-type {\\n      .hashtag-autocomplete__link {\\n        position: relative;\\n        z-index: 1;\\n      }\\n    }\\n  }\\n\\n  &__link {\\n    .autocomplete & {\\n      // silly but needed to overrule the autocomplete styles\\n      gap: var(--space-2);\\n    }\\n\\n    .hashtag-category-icon,\\n    .hashtag-category-emoji {\\n      width: 1em;\\n      height: 1em;\\n    }\\n\\n    .hashtag-category-square {\\n      width: 0.93em;\\n      height: 0.93em;\\n      display: inline-block;\\n    }\\n\\n    img.emoji,\\n    svg {\\n      width: 0.93em;\\n      height: 0.93em;\\n      vertical-align: top;\\n    }\\n  }\\n\\n  &__text {\\n    display: flex;\\n    align-items: center;\\n    gap: 0.25em;\\n    flex: 1;\\n    text-overflow: ellipsis;\\n    white-space: nowrap;\\n    overflow: hidden;\\n  }\\n\\n  &__meta-text {\\n    color: var(--primary-700);\\n    font-size: var(--font-down-1);\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.header-search--enabled,\\n.search-header--visible {\\n  .panel .header-dropdown-toggle.search-dropdown,\\n  .panel .search-menu {\\n    display: none;\\n  }\\n\\n  a.search-link {\\n    color: var(--tertiary);\\n\\n    .d-icon {\\n      color: var(--primary-medium);\\n    }\\n\\n    .search-item-slug,\\n    .keyword {\\n      color: var(--primary);\\n    }\\n  }\\n\\n  .floating-search-input + .panel {\\n    margin-left: 0;\\n  }\\n\\n  .floating-search-input-wrapper {\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    flex-grow: 1;\\n  }\\n\\n  &.welcome-banner--enabled {\\n    .floating-search-input {\\n      @include d-animation(float-up, 0.25s, ease);\\n    }\\n  }\\n\\n  .floating-search-input {\\n    width: 100%;\\n    max-width: 550px; // half of default d-max-width\\n\\n    .search-banner {\\n      height: 100%;\\n\\n      &-inner.wrap {\\n        height: 100%;\\n        padding: 0;\\n\\n        .search-menu {\\n          height: 100%;\\n          width: 100%;\\n          margin: 0 auto;\\n          position: relative;\\n\\n          @include viewport.until(lg) {\\n            width: 80%;\\n          }\\n\\n          @include viewport.until(md) {\\n            width: 90%;\\n          }\\n\\n          // Hide search-icon when search-context is present\\n          .search-input .search-context ~ .search-icon {\\n            display: none;\\n          }\\n\\n          .search-input .search-context ~ .search-term__input {\\n            padding-left: 0.5em;\\n          }\\n\\n          .searching .extra-search-icons ~ .clear-search {\\n            display: none;\\n          }\\n\\n          .searching {\\n            width: 3em;\\n            justify-content: flex-end;\\n\\n            .show-advanced-search,\\n            a.clear-search {\\n              display: inline-flex;\\n              align-items: center;\\n            }\\n          }\\n\\n          .search-icon {\\n            background: transparent;\\n            pointer-events: none;\\n            color: var(--header_primary-medium);\\n            margin-left: calc(1rem - 0.65em);\\n            height: 100%;\\n            position: absolute;\\n            z-index: 2;\\n          }\\n\\n          .search-menu-panel {\\n            padding: 0;\\n            border: 1px solid var(--content-border-color);\\n            border-radius: var(--d-border-radius);\\n            max-height: calc(100vh - var(--header-offset));\\n          }\\n\\n          .search-input {\\n            display: flex;\\n            padding: 0 0 0 2em;\\n            border-radius: var(--d-input-border-radius);\\n\\n            .search-term__input {\\n              height: 100%;\\n              width: 100%;\\n              margin: 0;\\n              padding: 0.5em;\\n              border-radius: var(--d-input-border-radius);\\n\\n              &:focus {\\n                outline: none;\\n              }\\n            }\\n          }\\n\\n          .results {\\n            &:empty {\\n              display: none;\\n            }\\n            background: var(--secondary);\\n            position: relative;\\n            box-sizing: border-box;\\n            width: 100%;\\n\\n            ul.list,\\n            ul {\\n              list-style: none;\\n              margin: 0;\\n            }\\n          }\\n        }\\n      }\\n    }\\n  }\\n\\n  // Styling for extra icons\\n  .search-bar-icons--icon {\\n    .d-icon {\\n      color: var(--primary-low-mid);\\n    }\\n\\n    &:hover .d-icon {\\n      color: var(--primary-high);\\n    }\\n  }\\n}\\n",".horizontal-overflow-nav {\\n  min-width: 0;\\n  width: 100%;\\n\\n  .nav-pills {\\n    @include horizontal-scroll-strip;\\n    margin: 0;\\n    height: 100%;\\n    position: relative;\\n  }\\n}\\n\\n// Chained to outrank the primitive's own declaration on the same element.\\n.d-overflow-controls.horizontal-overflow-nav__controls {\\n  --fade-width: 1.5em;\\n  height: 100%;\\n\\n  .d-overflow-controls__btn .d-icon {\\n    color: var(--d-nav-color--active);\\n    margin-bottom: 0.2em;\\n  }\\n}\\n",".d-overflow-controls {\\n  --fade-width: 2rem;\\n  --fade-color: var(--secondary);\\n\\n  // rem, because the button and the scroller resolve the value separately\\n  // and their font sizes can differ.\\n  --d-overflow-controls-btn-size: 1.5rem;\\n  position: relative;\\n  min-width: 0;\\n  min-height: 0;\\n\\n  // The chevron is positioned against this wrapper, so it sits over the\\n  // strip's edge and the fade starts beyond it. Pad this wrapper on a\\n  // scrolling edge and that stops being true; pad the scroller instead.\\n  > [data-d-scroll-axis] {\\n    --fade-inset: var(--d-overflow-controls-btn-size);\\n  }\\n\\n  &__content {\\n    @include scroll-strip;\\n  }\\n\\n  &__btn {\\n    position: absolute;\\n    z-index: 2;\\n    background: var(--fade-color);\\n    border: none;\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    padding: 0;\\n    cursor: pointer;\\n    color: var(--primary-high);\\n    user-select: none;\\n    -webkit-touch-callout: none;\\n\\n    &:hover {\\n      color: var(--primary);\\n    }\\n\\n    &.--left,\\n    &.--right {\\n      top: 0;\\n      bottom: 0;\\n      width: var(--d-overflow-controls-btn-size);\\n      margin-block: 1px;\\n    }\\n\\n    &.--up,\\n    &.--down {\\n      left: 0;\\n      right: 0;\\n      height: var(--d-overflow-controls-btn-size);\\n      margin-inline: 1px;\\n    }\\n\\n    &.--left {\\n      /*! rtl:ignore */\\n      left: 0;\\n\\n      // Undo automatic icon flip since button stays in physical position\\n      .rtl & .d-icon {\\n        transform: scaleX(1);\\n      }\\n    }\\n\\n    &.--right {\\n      /*! rtl:ignore */\\n      right: 0;\\n\\n      // Undo automatic icon flip since button stays in physical position\\n      .rtl & .d-icon {\\n        transform: scaleX(1);\\n      }\\n    }\\n\\n    &.--up {\\n      top: 0;\\n    }\\n\\n    &.--down {\\n      bottom: 0;\\n    }\\n  }\\n}\\n",".iframed-html {\\n  background: white;\\n  border: none;\\n}\\n",".user-ignore {\\n  .btn-icon-text {\\n    margin-top: 0.5em;\\n  }\\n}\