zing: border-box;\\n\\n  .filter-input-container {\\n    grid-column: 1 / -1;\\n    margin-bottom: 1em;\\n  }\\n\\n  .keyboard-shortcuts-help__container {\\n    columns: 2 20em; // Set maximum of 2 columns\\n\\n    section {\\n      display: inline-block;\\n      margin-bottom: 1.5em;\\n      width: 100%;\\n    }\\n  }\\n\\n  &:focus {\\n    outline: none;\\n  }\\n\\n  @for $i from 1 through 25 {\\n    .span-#{$i} {\\n      grid-row-end: span $i;\\n    }\\n  }\\n\\n  table {\\n    border-collapse: collapse;\\n    width: 100%;\\n  }\\n\\n  tbody tr {\\n    border-bottom: 1px solid var(--content-border-color);\\n  }\\n\\n  td {\\n    padding: 0.25rem 1rem;\\n    vertical-align: middle;\\n  }\\n\\n  .shortcut-description {\\n    width: 100%;\\n  }\\n\\n  .shortcut-key {\\n    text-align: right;\\n    white-space: nowrap;\\n\\n    .delimiter-newline {\\n      display: block;\\n      text-align: right;\\n    }\\n  }\\n}\\n",".load-more-sentinel {\\n  height: 1px; // 0px height causes issues with intersection observer in some cases\\n  width: 100%;\\n  margin: 0;\\n  padding: 0;\\n  pointer-events: none;\\n  user-select: none;\\n  visibility: hidden;\\n  position: relative;\\n}\\n","@use \\"lib/viewport\\";\\n\\n.more-topics__container {\\n  position: relative;\\n  padding-bottom: max(env(safe-area-inset-bottom), 1em);\\n  max-width: calc(var(--d-max-width) * 0.87);\\n\\n  .nav {\\n    margin-block: 0;\\n\\n    @include viewport.until(sm) {\\n      margin-block: 0 7px;\\n      border-bottom: 1px solid var(--content-border-color);\\n    }\\n\\n    li {\\n      @include viewport.until(sm) {\\n        position: relative;\\n        bottom: -1px; // compensate for the border-bottom\\n      }\\n\\n      .btn {\\n        color: var(--d-nav-color);\\n        background-color: var(--d-nav-bg-color);\\n        padding: var(--d-topic-list-header-data-padding-y) 0.8em;\\n        border: none;\\n        border-radius: 0;\\n        line-height: var(--line-height-medium);\\n\\n        .d-icon {\\n          color: var(--primary-high);\\n        }\\n\\n        &:focus-visible,\\n        &:hover {\\n          color: var(--d-nav-color--hover);\\n          background: var(--d-nav-bg-color--hover);\\n\\n          .d-icon {\\n            color: currentcolor;\\n          }\\n        }\\n\\n        &.active {\\n          color: var(--d-nav-color--active);\\n\\n          .d-icon {\\n            color: currentcolor;\\n          }\\n        }\\n      }\\n    }\\n  }\\n\\n  .more-topics__lists {\\n    &:not(.single-list) {\\n      .more-topics__list-title {\\n        display: none;\\n      }\\n    }\\n  }\\n\\n  .more-topics__list {\\n    .topic-list-body {\\n      border-top-width: 1px;\\n    }\\n\\n    .topic-list-header:has(.nav-pills) {\\n      th.topic-list-data {\\n        padding-bottom: 0;\\n\\n        &:first-of-type {\\n          padding-left: 0;\\n        }\\n      }\\n    }\\n\\n    @include viewport.until(sm) {\\n      .topic-list-header.--has-tabs {\\n        display: flex;\\n\\n        .nav-pills {\\n          margin: 0;\\n          border: none;\\n        }\\n\\n        th:not(.default) {\\n          display: none;\\n        }\\n      }\\n    }\\n  }\\n\\n  // Target the .badge-category text, the bullet icon needs to maintain `display: block`\\n  .suggested-topics-message .badge-category__wrapper .badge-category {\\n    display: inline;\\n    vertical-align: baseline;\\n    margin-right: 0;\\n    line-height: 0.8;\\n    max-width: 150px;\\n  }\\n\\n  .more-topics__list-title,\\n  .more-topics__browse-more {\\n    padding-left: 0.5em;\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n// --------------------------------------------------\\n// Navigation menus\\n// --------------------------------------------------\\n\\n// Base\\n// --------------------------------------------------\\n\\n%nav {\\n  margin-left: 0;\\n  list-style: none;\\n\\n  li a {\\n    display: block;\\n    text-decoration: none;\\n  }\\n}\\n\\n// Pill nav\\n// --------------------------------------------------\\n.nav-pills {\\n  @extend %nav;\\n  display: flex;\\n  flex-direction: row;\\n  align-items: stretch;\\n  gap: 0.5em;\\n\\n  > li {\\n    display: flex;\\n\\n    > a,\\n    button {\\n      position: relative;\\n      border: 0;\\n      border-radius: var(--d-nav-pill-border-radius);\\n      padding: 0.65em 0.75em;\\n      color: var(--d-nav-color);\\n      line-height: var(--line-height-small);\\n      box-sizing: border-box;\\n      min-height: 30px;\\n      display: flex;\\n      align-items: center;\\n      background-color: var(--d-nav-bg-color);\\n      transition: var(--d-button-transition);\\n      white-space: nowrap;\\n\\n      @include viewport.between(sm, lg) {\\n        font-size: var(--font-0);\\n        padding: var(--space-2) var(--space-3);\\n      }\\n\\n      .d-icon {\\n        margin-right: 5px;\\n        color: var(--primary-high);\\n        transition: color 0.2s;\\n      }\\n\\n      &:hover {\\n        @include nav-hover;\\n      }\\n    }\\n\\n    a.active,\\n    button.active {\\n      @include nav-active;\\n    }\\n  }\\n}\\n\\n// Stacked nav\\n// --------------------------------------------------\\n.nav-stacked {\\n  @extend %nav;\\n  padding: 0;\\n\\n  li {\\n    border-bottom: 1px solid var(--content-border-color);\\n\\n    &:last-of-type {\\n      border-bottom: 0;\\n    }\\n\\n    &.indent {\\n      padding-left: 15px;\\n    }\\n  }\\n\\n  a {\\n    margin: 0;\\n    padding: 0.75em;\\n    line-height: var(--line-height-small);\\n    cursor: pointer;\\n    color: var(--primary);\\n\\n    @include ellipsis;\\n\\n    &:hover {\\n      background: var(--d-sidebar-highlight-background);\\n    }\\n\\n    &.active {\\n      color: var(--d-selected-text-color);\\n      background-color: var(--d-selected);\\n      font-weight: bold;\\n      font-weight: var(--d-sidebar-active-font-weight);\\n    }\\n  }\\n\\n  .count {\\n    font-size: var(--font-down-1);\\n  }\\n\\n  .glyph {\\n    font-size: var(--font-down-1);\\n    width: 1.25em;\\n    text-align: center;\\n    margin-right: 0.25em;\\n    line-height: var(--line-height-large);\\n  }\\n}\\n\\n.user-navigation .nav-pills > li {\\n  a,\\n  button {\\n    border-radius: 0;\\n  }\\n}\\n",".offline-indicator {\\n  position: fixed;\\n  top: var(--header-offset);\\n  left: 50%;\\n  transform: translate(-50%, 0);\\n  padding: 0.5em 1em;\\n  background-color: var(--primary-very-low);\\n  border-radius: var(--d-nav-pill-border-radius);\\n  z-index: z(\\"header\\") - 10;\\n}\\n",".pick-files-button {\\n  input[type=\\"file\\"] {\\n    display: none;\\n  }\\n}\\n",".powered-by-discourse {\\n  grid-area: below-content;\\n  justify-self: start;\\n  font-size: var(--font-down-1);\\n  letter-spacing: 0.2px; // extra spacing makes small text easier to read\\n  padding: 2px; // animated hover \\"border\\" width\\n  background: var(--secondary);\\n  border-radius: 0.75em;\\n  transition: all 0.25s ease-in-out;\\n  margin-bottom: 0.45em;\\n  color: var(--primary-medium);\\n\\n  .admin-area &,\\n  .has-full-page-chat &,\\n  .static-login &,\\n  .invite-page &,\\n  .account-created-page &,\\n  .admin-invite-page &,\\n  .activate-account-page & {\\n    display: none !important;\\n  }\\n\\n  &:visited {\\n    color: var(--primary-medium);\\n  }\\n\\n  &__content {\\n    display: inline-flex;\\n    align-items: center;\\n    gap: 0.5em;\\n    color: currentcolor;\\n    background: var(--secondary);\\n    border-radius: 0.62em;\\n    padding: 0.25em 0.65em 0.25em 0.5em;\\n  }\\n\\n  .d-icon {\\n    position: relative;\\n    top: 0.05em; // vertical alignment\\n  }\\n\\n  .discourse-no-touch & {\\n    &:hover {\\n      color: var(--primary-high);\\n\\n      @media (prefers-reduced-motion: no-preference) {\\n        // secondary repeat is an intentional buffer\\n        background: linear-gradient(\\n          45deg,\\n          var(--secondary),\\n          var(--secondary),\\n          var(--secondary),\\n          var(--secondary),\\n          var(--secondary),\\n          #d0232b,\\n          #f15d22,\\n          #fff9ae,\\n          #00a94f,\\n          #00aeef\\n        );\\n        background-size: 300%;\\n        animation: d-rainbow-shimmer 0.5s;\\n        animation-fill-mode: forwards;\\n        animation-timing-function: ease-in-out;\\n        animation-delay: 0.15s; // avoid animating on passing hover\\n      }\\n    }\\n\\n    @keyframes d-rainbow-shimmer {\\n      0% {\\n        background-position: 0% 50%;\\n      }\\n\\n      100% {\\n        background-position: 100% 50%;\\n      }\\n    }\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.post-translations-modal {\\n  table {\\n    width: 100%;\\n  }\\n\\n  &__language-settings {\\n    display: grid;\\n    gap: var(--space-3);\\n    margin-block-end: var(--space-4);\\n  }\\n\\n  &__language-control {\\n    display: grid;\\n    grid-template-columns: minmax(0, 1fr) auto;\\n    gap: var(--space-2);\\n    align-items: end;\\n\\n    @include viewport.until(sm) {\\n      display: contents;\\n    }\\n  }\\n\\n  &__language-actions {\\n    display: flex;\\n    gap: var(--space-1);\\n\\n    @include viewport.until(sm) {\\n      order: 1;\\n    }\\n\\n    &.is-hidden {\\n      visibility: hidden;\\n      pointer-events: none;\\n\\n      @include viewport.until(sm) {\\n        display: none;\\n      }\\n    }\\n  }\\n}\\n\\n.fk-d-menu.post-language-selector-content {\\n  z-index: z(\\"composer\\", \\"dropdown\\");\\n\\n  // eventho mobile composer shouldnt be used in conjuction with fk-d-menu (floating version), on tablets the possibility unfortunately exists\\n  .discourse-touch & {\\n    z-index: z(\\"mobile-composer\\");\\n  }\\n}\\n\\n.fk-d-tooltip__content[data-identifier=\\"post-language\\"]\\n  .fk-d-tooltip__inner-content {\\n  flex-direction: column;\\n  align-items: flex-start;\\n\\n  .post-language__original-language {\\n    appearance: none;\\n    border: 0;\\n    background: transparent;\\n    color: inherit;\\n    font: inherit;\\n    padding: 0;\\n    text-align: start;\\n  }\\n\\n  .post-language__disclaimer {\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-2);\\n    margin-top: var(--space-1);\\n  }\\n}\\n\\n.post-language-selector-trigger {\\n  .toolbar-popup-menu-options__trigger-label {\\n    margin-left: var(--space-1);\\n    font-size: var(--font-down-2);\\n    text-transform: uppercase;\\n    color: var(--primary-high);\\n  }\\n}\\n",".relative-time-picker {\\n  display: flex;\\n\\n  input[type=\\"text\\"] {\\n    flex: 1;\\n  }\\n\\n  .relative-time-duration {\\n    margin-bottom: 0;\\n  }\\n\\n  .select-kit {\\n    flex: 1;\\n    width: auto;\\n    margin-left: 5px;\\n  }\\n\\n  &:last-child {\\n    margin-right: auto;\\n  }\\n}\\n",".d-modal.add-pm-participants {\\n  .d-modal__body {\\n    overflow-y: visible;\\n  }\\n}\\n\\n.add-pm-participants.d-modal .share.modal-panel {\\n  .header {\\n    display: flex;\\n    flex-direction: row;\\n    align-items: center;\\n\\n    .title {\\n      font-size: var(--font-0);\\n      font-weight: normal;\\n      margin-bottom: 8px;\\n\\n      .post-date {\\n        color: var(--primary-medium);\\n        font-size: var(--font-down-1);\\n      }\\n    }\\n  }\\n\\n  .body {\\n    display: flex;\\n    flex-direction: column;\\n\\n    .topic-share-url {\\n      width: 100%;\\n      height: auto;\\n      box-sizing: border-box;\\n      margin-bottom: 8px;\\n    }\\n\\n    .sources {\\n      display: flex;\\n      align-items: center;\\n      flex-wrap: wrap;\\n      flex-direction: row;\\n\\n      .social-link {\\n        font-size: var(--font-up-6);\\n        margin-right: 8px;\\n      }\\n    }\\n  }\\n}\\n\\n.add-pm-participants.d-modal .invite.modal-panel,\\n.invite-link.modal-panel {\\n  .error-message,\\n  .success-message {\\n    margin-bottom: 8px;\\n  }\\n\\n  .body {\\n    .invite-user-control,\\n    .group-access-control,\\n    .show-custom-message-control {\\n      margin-bottom: 8px;\\n    }\\n\\n    .group-access-control {\\n      .select-kit.multi-select input.filter-input {\\n        padding-left: 8px;\\n      }\\n\\n      .group-chooser {\\n        width: 100%;\\n      }\\n    }\\n\\n    .instructions {\\n      margin-bottom: 8px;\\n    }\\n\\n    .instructions.approval-notice {\\n      color: var(--secondary-medium);\\n    }\\n\\n    .invite-user-input {\\n      width: 100%;\\n\\n      .input-wrapper {\\n        width: 100%;\\n\\n        .filter-input {\\n          width: 100%;\\n        }\\n      }\\n    }\\n\\n    .invite-user-input-wrapper {\\n      display: flex;\\n    }\\n\\n    .invite-link-input {\\n      width: 100%;\\n    }\\n  }\\n\\n  .footer {\\n    display: flex;\\n    align-items: center;\\n\\n    .btn-primary {\\n      margin-right: 8px;\\n\\n      &:last-child {\\n        margin-right: 0;\\n      }\\n    }\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n@import \\"common/foundation/mixins\\";\\n\\n.admin-onboarding-banner {\\n  padding-block: var(--d-main-content-gap);\\n\\n  @include viewport.until(sm) {\\n    padding-block: 0;\\n    padding-block-end: var(--space-4);\\n  }\\n\\n  &__wrap {\\n    box-sizing: border-box;\\n    position: relative;\\n    border-radius: var(--d-border-radius);\\n    border: 1px solid var(--content-border-color);\\n    overflow: hidden;\\n  }\\n\\n  &__title {\\n    font-weight: 600;\\n  }\\n\\n  &__title-icon {\\n    margin-right: var(--space-2);\\n    font-size: var(--font-down-1);\\n  }\\n\\n  &__header {\\n    display: flex;\\n    align-items: center;\\n    justify-content: space-between;\\n    height: min-content;\\n    padding-inline-start: var(--space-4);\\n    background: var(--background-color, var(--primary-100));\\n  }\\n\\n  &__header-text {\\n    display: flex;\\n    flex-direction: row;\\n    gap: var(--space-4);\\n    align-items: center;\\n  }\\n\\n  &__subtitle {\\n    font-size: var(--font-down-2);\\n    color: var(--primary-700);\\n  }\\n\\n  &__content {\\n    text-align: center;\\n  }\\n\\n  &__steps {\\n    display: flex;\\n    flex-direction: column;\\n  }\\n\\n  .onboarding-step {\\n    display: flex;\\n    flex-direction: row;\\n    padding: var(--space-2) var(--space-4);\\n    border-bottom: 1px solid var(--content-border-color);\\n    gap: var(--space-4);\\n    align-items: center;\\n\\n    @include viewport.until(sm) {\\n      display: grid;\\n      gap: 0;\\n      grid-template-columns: 1fr auto;\\n      grid-template-areas: \\"text action\\" \\"description action\\";\\n      padding: var(--space-2);\\n    }\\n  }\\n\\n  .onboarding-step:last-child {\\n    border-bottom: none;\\n  }\\n\\n  .onboarding-step:first-child {\\n    border-top: 1px solid var(--content-border-color);\\n  }\\n\\n  .onboarding-step__checkbox {\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    gap: var(--space-2);\\n\\n    @include viewport.until(sm) {\\n      display: block;\\n      justify-self: baseline;\\n    }\\n  }\\n\\n  .onboarding-step__checkbox-icon {\\n    font-size: var(--font-down-1);\\n\\n    &.--completed {\\n      color: var(--success);\\n    }\\n  }\\n\\n  .onboarding-step__title {\\n    font-weight: 600;\\n    font-size: var(--font-down-1);\\n\\n    @include viewport.until(sm) {\\n      grid-area: text;\\n    }\\n  }\\n\\n  .onboarding-step__description {\\n    font-size: var(--font-down-1);\\n    color: var(--primary-700);\\n\\n    @include viewport.until(sm) {\\n      grid-area: description;\\n      justify-self: baseline;\\n    }\\n  }\\n\\n  .onboarding-step__action {\\n    margin-left: auto;\\n\\n    @include viewport.until(sm) {\\n      grid-area: action;\\n      margin-left: 0;\\n    }\\n\\n    --d-button-transparent-text-color: var(--tertiary);\\n  }\\n\\n  .onboarding-step__action .btn-link {\\n    font-weight: 600;\\n\\n    &.--completed {\\n      --d-button-transparent-text-color: var(--primary-medium);\\n      font-weight: 400;\\n    }\\n\\n    &.--completed:hover {\\n      --d-button-transparent-text-color--hover: var(--primary-high);\\n    }\\n  }\\n}\\n\\n.start-posting-options-modal {\\n  .modal-options {\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-4);\\n  }\\n\\n  &__card {\\n    display: flex;\\n    flex-direction: column;\\n    align-items: start;\\n    text-align: left;\\n    width: 100%;\\n    padding: var(--space-4);\\n    border: 1px solid var(--content-border-color);\\n    border-radius: var(--d-border-radius);\\n    background: var(--secondary);\\n\\n    &:focus-visible,\\n    &:hover {\\n      outline: 2px solid var(--tertiary);\\n\\n      .start-posting-options-modal__title {\\n        color: var(--tertiary);\\n      }\\n    }\\n\\n    &:disabled {\\n      opacity: 0.5;\\n      pointer-events: none;\\n    }\\n  }\\n\\n  &__title {\\n    display: block;\\n    font-weight: bold;\\n  }\\n\\n  &__body {\\n    max-width: var(--modal-max-width);\\n  }\\n}\\n\\n.predefined-topic-options-modal {\\n  &__list {\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-4);\\n  }\\n\\n  &__card {\\n    display: flex;\\n    flex-direction: column;\\n    align-items: start;\\n    text-align: left;\\n    width: 100%;\\n    padding: var(--space-4);\\n    border: 1px solid var(--content-border-color);\\n    border-radius: var(--d-border-radius);\\n    background: var(--secondary);\\n\\n    &:disabled {\\n      opacity: 0.5;\\n      cursor: not-allowed;\\n    }\\n\\n    &:focus-visible,\\n    &:hover:not(:disabled) {\\n      outline: 2px solid var(--tertiary);\\n\\n      .predefined-topic-options-modal__title {\\n        color: var(--tertiary);\\n      }\\n    }\\n  }\\n\\n  &__heading {\\n    display: flex;\\n    flex-wrap: wrap;\\n    align-items: center;\\n    gap: var(--space-2);\\n  }\\n\\n  &__title {\\n    display: block;\\n    font-weight: bold;\\n  }\\n\\n  &__body {\\n    max-width: var(--modal-max-width);\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n@import \\"common/foundation/mixins\\";\\n\\n// Common stylesheets compile with the active scheme injected into\\n// $primary/$secondary/$tertiary, so referencing those (or their derived shades)\\n// would let the previewed palette restyle the tool. Pin base-light instead.\\n$dw-primary: #222;\\n$dw-secondary: #fff;\\n$dw-tertiary: #08c;\\n$dw-tertiary-hover: #069;\\n$dw-tertiary-high: #0aadff;\\n$dw-selected: #d1f0ff;\\n$dw-hover: #f2f2f2;\\n$dw-primary-very-low: #f8f8f8;\\n$dw-primary-low: #e9e9e9;\\n$dw-primary-low-mid: #bdbdbd;\\n$dw-primary-medium: #919191;\\n$dw-primary-high: #646464;\\n$dw-primary-very-high: #434343;\\n$dw-button-default-border: #d3d3d3;\\n\\n.design-wizard,\\n.design-wizard__font-select-content {\\n  --primary: #{$dw-primary};\\n  --secondary: #{$dw-secondary};\\n  --d-content-background: #{$dw-secondary};\\n  --tertiary: #{$dw-tertiary};\\n  --tertiary-hover: #{$dw-tertiary-hover};\\n  --tertiary-low: #{$dw-selected};\\n  --primary-very-low: #{$dw-primary-very-low};\\n  --primary-low: #{$dw-primary-low};\\n  --primary-low-mid: #{$dw-primary-low-mid};\\n  --primary-medium: #{$dw-primary-medium};\\n  --primary-high: #{$dw-primary-high};\\n  --primary-very-high: #{$dw-primary-very-high};\\n  --d-hover: #{$dw-hover};\\n  --d-link-color: #{$dw-tertiary};\\n  --primary-100: #{$dw-hover};\\n  --primary-200: #{$dw-primary-low};\\n  --tertiary-300: #{$dw-selected};\\n  --tertiary-high: #{$dw-tertiary-high};\\n\\n  // Theme-defined button accents, including Horizon's button overrides.\\n  --accent-color: #{$dw-tertiary};\\n  --accent-text-color: #{$dw-secondary};\\n  --button-box-shadow: #{$dw-selected};\\n  --content-border-color: #{$dw-primary-low};\\n\\n  // Default buttons keep the modernized Foundation treatment.\\n  --d-button-default-text-color: #{$dw-primary-very-high};\\n  --d-button-default-text-color--hover: #{$dw-primary};\\n  --d-button-default-bg-color: #{$dw-secondary};\\n  --d-button-default-bg-color--hover: #{$dw-primary-low};\\n  --d-button-default-icon-color: #{$dw-primary-very-high};\\n  --d-button-default-icon-color--hover: #{$dw-primary};\\n  --d-button-default-border: 1px solid #{$dw-button-default-border};\\n  --d-button-default-border--hover: 1px solid #{$dw-primary-low-mid};\\n  --d-button-primary-text-color: #{$dw-secondary};\\n  --d-button-primary-text-color--hover: #{$dw-secondary};\\n  --d-button-primary-bg-color: #{$dw-tertiary};\\n  --d-button-primary-bg-color--hover: #{$dw-tertiary-hover};\\n  --d-button-primary-icon-color: #{$dw-secondary};\\n  --d-button-primary-icon-color--hover: #{$dw-secondary};\\n  --d-button-flat-text-color: #{$dw-tertiary};\\n  --d-button-flat-text-color--hover: #{$dw-primary};\\n  --d-button-flat-icon-color: #{$dw-primary-low-mid};\\n  --d-button-flat-icon-color--hover: #{$dw-primary};\\n  --d-button-flat-bg-color: transparent;\\n  --d-button-flat-bg-color--hover: #{$dw-hover};\\n  --d-button-flat-bg-color--focus: #{$dw-hover};\\n  --d-button-flat-text-color--disabled: #{$dw-primary};\\n  --d-button-flat-close-text-color: #{$dw-primary-high};\\n  --d-button-flat-close-bg-color: transparent;\\n  --d-button-flat-close-icon-color: #{$dw-primary-high};\\n  --d-button-flat-close-icon-color--hover: #{$dw-primary};\\n  --d-button-transparent-text-color: #{$dw-primary};\\n  --d-button-transparent-text-color--hover: #{$dw-tertiary-hover};\\n  --d-button-transparent-icon-color: #{$dw-primary-high};\\n  --d-button-transparent-icon-color--hover: #{$dw-tertiary-hover};\\n\\n  // rem-based, so the previewed theme's root font size would otherwise rescale\\n  // the tool's spacing despite the pinned font-size below\\n  --space: 4px;\\n  color: var(--primary);\\n  color-scheme: light;\\n  font-family:\\n    system-ui,\\n    -apple-system,\\n    \\"Segoe UI\\",\\n    Roboto,\\n    Helvetica,\\n    Arial,\\n    sans-serif;\\n\\n  // pinned so the previewed theme's root font size cannot resize the tool\\n  font-size: 16px;\\n\\n  h1,\\n  h2,\\n  h3,\\n  h4,\\n  h5,\\n  h6 {\\n    font-family: inherit;\\n  }\\n}\\n\\n.design-wizard {\\n  // also read by the panel component, for its closing animation\\n  --design-wizard-slide-out: translateX(100%);\\n  --design-wizard-category-1: #25aae2;\\n  --design-wizard-category-2: #9eb83b;\\n  --design-wizard-category-3: #e45735;\\n  --design-wizard-category-4: #7159c1;\\n  position: fixed;\\n  z-index: z(\\"design-wizard\\");\\n  inset-block: calc(var(--header-offset) - var(--space-2)) 0;\\n  inset-inline-end: 0;\\n  display: flex;\\n  flex-direction: column;\\n  box-sizing: border-box;\\n  width: min(27em, 100vw);\\n  background: var(--secondary);\\n  border: 1px solid var(--content-border-color);\\n  border-inline-end: none;\\n  border-start-start-radius: var(--d-border-radius-large);\\n  box-shadow: var(--shadow-card);\\n\\n  @include d-animation(design-wizard-slide-in, 0.25s, ease-out);\\n\\n  html[dir=\\"rtl\\"] & {\\n    --design-wizard-slide-out: translateX(-100%);\\n  }\\n\\n  // a full-height rail would cover the page it previews\\n  @include viewport.until(sm) {\\n    --design-wizard-slide-out: translateY(100%);\\n    inset-block: auto 0;\\n    inset-inline: 0;\\n    width: 100%;\\n    max-height: 65vh;\\n    border-inline-end: 1px solid var(--content-border-color);\\n    border-start-end-radius: var(--d-border-radius-large);\\n\\n    html[dir=\\"rtl\\"] & {\\n      --design-wizard-slide-out: translateY(100%);\\n    }\\n  }\\n\\n  &.--no-entrance {\\n    animation: none;\\n  }\\n\\n  // a theme preview replaces the page; the panel is waiting for that to land\\n  &.--busy .design-wizard__sections {\\n    opacity: 0.6;\\n    pointer-events: none;\\n  }\\n\\n  &__close {\\n    position: absolute;\\n    inset-block-start: var(--space-2);\\n    inset-inline-end: var(--space-2);\\n  }\\n\\n  &__content {\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-5);\\n    height: 100%;\\n\\n    // so the sections scroll rather than pushing the footer actions out\\n    min-height: 0;\\n    padding: var(--space-5);\\n  }\\n\\n  &__header {\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-1);\\n\\n    h2 {\\n      margin: 0;\\n    }\\n  }\\n\\n  &__subtitle {\\n    font-size: var(--font-down-1);\\n    color: var(--primary-medium);\\n  }\\n\\n  &__intro {\\n    display: flex;\\n    flex: 1 1 auto;\\n    flex-direction: column;\\n    gap: var(--space-4);\\n    align-items: flex-start;\\n    min-height: 0;\\n    overflow-y: auto;\\n  }\\n\\n  &__intro-description,\\n  &__intro-note {\\n    margin: 0;\\n  }\\n\\n  &__intro-note {\\n    display: flex;\\n    gap: var(--space-1);\\n    padding: var(--space-2);\\n    font-size: var(--font-down-1);\\n    color: var(--primary-medium);\\n    background: var(--primary-100);\\n    border-radius: var(--d-border-radius);\\n  }\\n\\n  &__sections {\\n    display: flex;\\n    flex: 1 1 auto;\\n    flex-direction: column;\\n    gap: var(--space-6);\\n    min-height: 0;\\n\\n    // so a selected control's box-shadow isn't clipped by the scroll container\\n    padding: 2px;\\n    margin: -2px;\\n    overflow-y: auto;\\n    overscroll-behavior: contain;\\n    scrollbar-width: thin;\\n    scrollbar-color: var(--primary-low-mid) transparent;\\n  }\\n\\n  &__section {\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-3);\\n  }\\n\\n  &__section-title {\\n    font-weight: 600;\\n    color: var(--primary);\\n  }\\n\\n  &__section-body {\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-3);\\n  }\\n\\n  &__custom-theme-notice {\\n    margin: 0;\\n    padding: var(--space-1) var(--space-2);\\n    font-size: var(--font-down-2);\\n    color: var(--primary-medium);\\n    background: var(--primary-100);\\n    border-radius: var(--d-border-radius);\\n  }\\n\\n  &__theme-cards {\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-3);\\n    min-width: 0;\\n    padding: 0;\\n    margin: 0;\\n    border: 0;\\n  }\\n\\n  &__theme-card-wrapper {\\n    position: relative;\\n  }\\n\\n  &__theme-card {\\n    position: relative;\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-1);\\n    width: 100%;\\n    font-size: var(--font-down-1);\\n    color: inherit;\\n    cursor: pointer;\\n\\n    &.--selected .design-wizard__theme-screenshot {\\n      border-color: var(--tertiary);\\n      box-shadow: 0 0 0 1px var(--tertiary);\\n    }\\n\\n    &:focus-within .design-wizard__theme-screenshot,\\n    html.discourse-no-touch &:hover .design-wizard__theme-screenshot {\\n      border-color: var(--tertiary);\\n      box-shadow: 0 0 0 1px var(--tertiary);\\n    }\\n  }\\n\\n  &__theme-screenshot {\\n    position: relative;\\n    display: flex;\\n    align-items: center;\\n\\n    // matches the serialized screenshot size, so the box is reserved at the\\n    // right shape before the image lands and the card never reflows\\n    aspect-ratio: 16 / 9;\\n    overflow: hidden;\\n    background: var(--primary-very-low);\\n    border: 1px solid var(--content-border-color);\\n    border-radius: var(--d-border-radius);\\n\\n    &.--loading::after {\\n      position: absolute;\\n      inset: 0;\\n      content: \\"\\";\\n      background: linear-gradient(\\n        90deg,\\n        var(--primary-very-low) 25%,\\n        var(--primary-low) 37%,\\n        var(--primary-very-low) 63%\\n      );\\n      background-size: 400% 100%;\\n      animation: design-wizard-shimmer 1.4s ease infinite;\\n\\n      @media (prefers-reduced-motion: reduce) {\\n        animation: none;\\n      }\\n    }\\n  }\\n\\n  &__theme-screenshot-image {\\n    display: block;\\n    width: 100%;\\n    height: 100%;\\n    object-fit: cover;\\n\\n    /*! rtl:ignore */\\n    object-position: top left;\\n    image-rendering: -webkit-optimize-contrast;\\n    image-rendering: crisp-edges;\\n  }\\n\\n  &__theme-name {\\n    font-weight: 600;\\n  }\\n\\n  &__theme-description {\\n    display: block;\\n    margin: 0;\\n    font-weight: normal;\\n  }\\n\\n  &__theme-spinner.spinner {\\n    margin: 0;\\n    border-width: 2px;\\n    border-color: currentcolor;\\n    border-right-color: transparent;\\n  }\\n\\n  &__theme-enabled-badge {\\n    position: absolute;\\n    z-index: z(\\"base\\");\\n    inset-block-start: var(--space-2);\\n    inset-inline-end: var(--space-2);\\n    display: inline-flex;\\n    align-items: center;\\n    gap: var(--space-1);\\n    padding: var(--space-1) var(--space-2);\\n    font-size: var(--font-down-1);\\n    font-weight: 700;\\n    color: var(--secondary);\\n    background: var(--tertiary);\\n    border-radius: var(--d-border-radius);\\n\\n    .d-icon {\\n      color: currentcolor;\\n    }\\n  }\\n\\n  &__color {\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-2);\\n  }\\n\\n  &__color-modes {\\n    display: flex;\\n    justify-content: flex-end;\\n  }\\n\\n  &__color-mode {\\n    padding: var(--space-2);\\n    font-size: var(--font-down-2);\\n    font-weight: 600;\\n    background: none;\\n    border: 1px solid var(--content-border-color);\\n    cursor: pointer;\\n\\n    &:first-child {\\n      border-start-start-radius: var(--d-border-radius);\\n      border-end-start-radius: var(--d-border-radius);\\n    }\\n\\n    &:last-child {\\n      border-start-end-radius: var(--d-border-radius);\\n      border-end-end-radius: var(--d-border-radius);\\n      border-inline-start: none;\\n    }\\n\\n    &.--active {\\n      color: var(--tertiary);\\n      background: var(--tertiary-low);\\n    }\\n\\n    &:disabled {\\n      cursor: default;\\n      opacity: 0.4;\\n    }\\n  }\\n\\n  &__swatches {\\n    display: grid;\\n    grid-template-columns: repeat(3, 1fr);\\n    gap: var(--space-2);\\n  }\\n\\n  &__homepage-card,\\n  &__style-block,\\n  &__swatch {\\n    background: none;\\n    border: 1px solid var(--content-border-color);\\n    border-radius: var(--d-border-radius);\\n    cursor: pointer;\\n\\n    &.--selected {\\n      font-weight: 600;\\n      color: var(--tertiary);\\n      border-color: var(--tertiary);\\n      box-shadow: 0 0 0 1px var(--tertiary);\\n    }\\n\\n    html.discourse-no-touch &:hover {\\n      border-color: var(--tertiary);\\n      box-shadow: 0 0 0 1px var(--tertiary);\\n    }\\n  }\\n\\n  &__swatch {\\n    padding: var(--space-2);\\n    text-align: center;\\n  }\\n\\n  &__swatch-preview {\\n    display: block;\\n    height: 2.5em;\\n    border-radius: var(--token-radius-small);\\n  }\\n\\n  &__swatch-name {\\n    display: inline-flex;\\n    align-items: center;\\n    gap: var(--space-1);\\n    margin-block-start: var(--space-2);\\n    font-size: var(--font-down-1);\\n\\n    .d-icon {\\n      font-size: var(--font-down-3);\\n      color: var(--primary-medium);\\n    }\\n  }\\n\\n  &__color-note {\\n    margin: 0;\\n    font-size: var(--font-down-2);\\n    color: var(--primary-medium);\\n  }\\n\\n  &__switch-row {\\n    display: flex;\\n    gap: var(--space-3);\\n    align-items: center;\\n    padding: var(--space-3);\\n    border: 1px solid var(--content-border-color);\\n    border-radius: var(--d-border-radius);\\n  }\\n\\n  &__switch-row-title {\\n    display: block;\\n    font-size: var(--font-down-1);\\n    font-weight: 600;\\n  }\\n\\n  &__switch-row-description {\\n    display: block;\\n    font-size: var(--font-down-2);\\n    color: var(--primary-medium);\\n  }\\n\\n  &__font-group {\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-2);\\n  }\\n\\n  &__label {\\n    display: block;\\n    font-size: var(--font-down-1);\\n    font-weight: 600;\\n    color: var(--primary);\\n  }\\n\\n  &__font-select.btn-default.btn {\\n    justify-content: space-between;\\n    width: 100%;\\n    padding-block: var(--space-2);\\n    border-radius: var(--d-border-radius);\\n    background: var(--content-background);\\n\\n    &:hover {\\n      background: var(--content-background);\\n    }\\n  }\\n\\n  &__font-select-caret.d-icon.d-icon-angle-down.svg-icon {\\n    margin-inline-start: var(--space-1);\\n    color: var(--primary-medium);\\n  }\\n\\n  &__homepage-cards {\\n    display: grid;\\n    grid-template-columns: 1fr 1fr;\\n    gap: var(--space-3);\\n  }\\n\\n  &__homepage-card {\\n    display: flex;\\n    flex-direction: column;\\n    align-items: stretch;\\n    gap: var(--space-1);\\n    padding: var(--space-2);\\n    font-size: var(--font-down-1);\\n  }\\n\\n  &__homepage-thumbnail {\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-1);\\n    height: 5.5em;\\n    padding: var(--space-1);\\n    overflow: hidden;\\n    background: var(--secondary);\\n    border: 1px solid var(--content-border-color);\\n    border-radius: var(--token-radius-small);\\n\\n    &.--topics.--horizon {\\n      background: var(--primary-very-low);\\n    }\\n\\n    &.--categories {\\n      display: grid;\\n      grid-template-columns: 1fr 1fr;\\n      grid-auto-rows: 1fr;\\n    }\\n  }\\n\\n  &__detail-group {\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-2);\\n  }\\n\\n  &__style-blocks,\\n  &__option-rows {\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-2);\\n  }\\n\\n  &__style-block {\\n    display: flex;\\n    flex-direction: column;\\n    align-items: stretch;\\n    gap: var(--space-1);\\n    padding: var(--space-2);\\n    font-size: var(--font-down-1);\\n  }\\n\\n  &__homepage-style-preview {\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-1);\\n    height: 5.5em;\\n    padding: var(--space-2);\\n    overflow: hidden;\\n    background: var(--secondary);\\n    border: 1px solid var(--content-border-color);\\n    border-radius: var(--token-radius-small);\\n\\n    &.--boxes {\\n      display: grid;\\n      grid-template-columns: 1fr 1fr;\\n      grid-auto-rows: 1fr;\\n    }\\n  }\\n\\n  &__mock-card {\\n    position: relative;\\n    display: block;\\n    flex: 1;\\n    padding-block: var(--space-1);\\n    padding-inline: var(--space-5) var(--space-1);\\n    background: var(--secondary);\\n    border: 1px solid var(--content-border-color);\\n    border-radius: var(--d-border-radius);\\n\\n    .design-wizard__mock-avatar {\\n      position: absolute;\\n      inset-block-start: var(--space-1);\\n      inset-inline-start: var(--space-1);\\n    }\\n\\n    .design-wizard__mock-badge {\\n      display: block;\\n      width: 1.125em;\\n      height: 0.25em;\\n      margin-block-start: var(--space-1);\\n      background: var(--tertiary-low);\\n      border-radius: var(--token-radius-small);\\n    }\\n  }\\n\\n  &__mock-row {\\n    display: flex;\\n    flex: 1;\\n    align-items: center;\\n    gap: var(--space-1);\\n\\n    + .design-wizard__mock-row {\\n      border-block-start: 1px solid var(--primary-very-low);\\n    }\\n\\n    .design-wizard__mock-line.--title {\\n      margin-inline-end: auto;\\n    }\\n  }\\n\\n  &__mock-avatar {\\n    display: block;\\n    flex: none;\\n    width: 0.5em;\\n    height: 0.5em;\\n    background: var(--primary-low-mid);\\n    border-radius: 50%;\\n  }\\n\\n  &__mock-line {\\n    display: block;\\n    height: 0.25em;\\n    border-radius: var(--token-radius-small);\\n\\n    &.--title {\\n      width: 55%;\\n      margin-block-end: var(--space-1);\\n      background: var(--primary-low-mid);\\n    }\\n\\n    &.--text {\\n      width: 80%;\\n      margin-block-end: var(--space-1);\\n      background: var(--primary-low);\\n    }\\n\\n    &.--count {\\n      flex: none;\\n      width: 0.625em;\\n      background: var(--primary-low);\\n    }\\n  }\\n\\n  &__mock-cat-badge {\\n    display: block;\\n    flex: none;\\n    width: 0.5em;\\n    height: 0.5em;\\n    border-radius: var(--token-radius-small);\\n\\n    &.--c1 {\\n      background: var(--design-wizard-category-1);\\n    }\\n\\n    &.--c2 {\\n      background: var(--design-wizard-category-2);\\n    }\\n\\n    &.--c3 {\\n      background: var(--design-wizard-category-3);\\n    }\\n\\n    &.--c4 {\\n      background: var(--design-wizard-category-4);\\n    }\\n  }\\n\\n  &__mock-columns {\\n    display: flex;\\n    flex: 1;\\n    gap: var(--space-2);\\n    min-height: 0;\\n  }\\n\\n  &__mock-column {\\n    display: flex;\\n    flex: 1;\\n    flex-direction: column;\\n    gap: var(--space-1);\\n\\n    + .design-wizard__mock-column {\\n      padding-inline-start: var(--space-2);\\n      border-inline-start: 1px solid var(--primary-very-low);\\n    }\\n  }\\n\\n  &__mock-box {\\n    display: flex;\\n    flex-direction: column;\\n    justify-content: center;\\n    padding: var(--space-1);\\n    margin: 1px;\\n    background: var(--secondary);\\n    border: 1px solid var(--content-border-color);\\n    border-inline-start-width: 3px;\\n    border-radius: var(--token-radius-small);\\n\\n    .design-wizard__mock-line.--title {\\n      width: 65%;\\n    }\\n\\n    .design-wizard__mock-line.--text {\\n      width: 90%;\\n      margin-block-end: 2px;\\n    }\\n\\n    &.--c1 {\\n      border-inline-start-color: var(--design-wizard-category-1);\\n    }\\n\\n    &.--c2 {\\n      border-inline-start-color: var(--design-wizard-category-2);\\n    }\\n\\n    &.--c3 {\\n      border-inline-start-color: var(--design-wizard-category-3);\\n    }\\n\\n    &.--c4 {\\n      border-inline-start-color: var(--design-wizard-category-4);\\n    }\\n  }\\n\\n  // Rendered inline like the notification tracking menu's selectable rows.\\n  &__option-row {\\n    display: flex;\\n    box-sizing: border-box;\\n    align-items: center;\\n    gap: var(--space-2);\\n    padding: var(--space-2);\\n    background: none;\\n    border: 1px solid var(--content-border-color);\\n    border-radius: var(--d-border-radius);\\n    cursor: pointer;\\n\\n    &.--selected {\\n      border-color: var(--tertiary);\\n      box-shadow: 0 0 0 1px var(--tertiary);\\n    }\\n\\n    html.discourse-no-touch &:hover {\\n      border-color: var(--tertiary);\\n      box-shadow: 0 0 0 1px var(--tertiary);\\n    }\\n  }\\n\\n  &__option-row-texts {\\n    display: flex;\\n    flex: 1 1 0%;\\n    flex-direction: column;\\n    flex-wrap: wrap;\\n    align-items: flex-start;\\n    line-height: var(--line-height-medium);\\n  }\\n\\n  &__option-row-label {\\n    flex: 1 1 auto;\\n    max-width: 100%;\\n    font-size: var(--font-0);\\n    font-weight: bold;\\n    color: var(--primary);\\n\\n    @include ellipsis;\\n  }\\n\\n  &__option-row-description {\\n    flex: 1 1 auto;\\n    font-size: var(--font-down-1);\\n    color: var(--primary-medium);\\n    text-align: start;\\n    white-space: normal;\\n  }\\n\\n  &__actions {\\n    display: flex;\\n    align-items: center;\\n    justify-content: flex-end;\\n    gap: var(--space-2);\\n    padding-block-start: var(--space-4);\\n    border-block-start: 1px solid var(--content-border-color);\\n  }\\n\\n  &__step-dots {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-2);\\n    margin-inline-end: auto;\\n  }\\n\\n  &__step-dot {\\n    box-sizing: border-box;\\n    width: 0.5em;\\n    height: 0.5em;\\n    padding: 0;\\n    background: var(--primary-low-mid);\\n    border: none;\\n    border-radius: 50%;\\n    cursor: pointer;\\n\\n    &.--active {\\n      background: var(--tertiary);\\n    }\\n\\n    html.discourse-no-touch &:hover {\\n      background: var(--primary-medium);\\n    }\\n\\n    html.discourse-no-touch &.--active:hover {\\n      background: var(--tertiary-hover);\\n    }\\n  }\\n}\\n\\n.design-wizard__font-select-content {\\n  z-index: z(\\"modal\\", \\"popover\\");\\n}\\n\\n.design-wizard__font-list {\\n  max-height: 40vh;\\n  overflow-y: auto;\\n  overscroll-behavior: contain;\\n  scrollbar-width: thin;\\n  scrollbar-color: var(--primary-low-mid) transparent;\\n}\\n\\n@keyframes design-wizard-shimmer {\\n  from {\\n    background-position: 100% 50%;\\n  }\\n\\n  to {\\n    background-position: 0 50%;\\n  }\\n}\\n\\n@keyframes design-wizard-slide-in {\\n  from {\\n    transform: var(--design-wizard-slide-out);\\n  }\\n\\n  to {\\n    transform: translate(0, 0);\\n  }\\n}\\n\\n.admin-config-area-themes__design-wizard {\\n  display: flex;\\n  gap: var(--space-3);\\n  align-items: center;\\n  padding-block: var(--space-4);\\n  margin-top: var(--space-4);\\n  border-block: 1px solid var(--content-border-color);\\n}\\n\\n.admin-config-area-themes__design-wizard-description {\\n  font-size: var(--font-down-1);\\n  color: var(--primary-medium);\\n}\\n",".download-calendar {\\n  color: var(--primary-med-or-secondary-med);\\n}\\n\\n.user-preferences {\\n  #user-default-calendar {\\n    min-width: 175px;\\n  }\\n}\\n",".sidebar-categories-form {\\n  .sidebar-categories-form__row {\\n    display: flex;\\n    flex-direction: column;\\n    border-left: 4px solid;\\n    margin-bottom: var(--space-6);\\n    padding-inline: var(--space-4);\\n    background: var(--primary-50);\\n  }\\n\\n  .sidebar-categories-form__category-row[data-category-level=\\"0\\"]:not(\\n      :only-child\\n    ) {\\n    border-bottom: 1px solid var(--content-border-color);\\n  }\\n\\n  .sidebar-categories-form__category-row:first-of-type {\\n    .badge-category {\\n      font-weight: 600;\\n    }\\n  }\\n\\n  .sidebar-categories-form__category-row[data-category-level=\\"1\\"] {\\n    padding-left: var(--space-4);\\n  }\\n\\n  .sidebar-categories-form__category-row[data-category-level=\\"1\\"]:not(\\n      :nth-of-type(2)\\n    ) {\\n    border-top: 1px solid var(--content-border-color);\\n  }\\n\\n  .sidebar-categories-form__category-row[data-category-level=\\"2\\"] {\\n    padding-left: var(--space-8);\\n    border-top: 1px solid var(--content-border-color);\\n  }\\n\\n  .sidebar-categories-form__category-label {\\n    display: flex;\\n    justify-content: space-between;\\n    padding: 0.75em 0;\\n    margin: 0;\\n    flex-grow: 1;\\n    font-weight: normal;\\n\\n    input[type=\\"checkbox\\"] {\\n      margin-right: 0;\\n    }\\n  }\\n\\n  .sidebar-categories-form__category-wrapper {\\n    min-width: 0;\\n  }\\n\\n  .badge-category__wrapper {\\n    font-size: var(--font-0); // reset generic component\\n  }\\n\\n  .sidebar-categories-form__category-badge {\\n    .badge-wrapper {\\n      width: 100%;\\n    }\\n\\n    .badge-category {\\n      @include ellipsis;\\n      white-space: normal;\\n      overflow-wrap: break-word;\\n    }\\n  }\\n\\n  .sidebar-categories-form__category-description {\\n    color: var(--primary-high);\\n    font-size: var(--font-down-1);\\n    margin: 0.25em 0;\\n\\n    // avoids long words (like urls) from breaking the layou\\n    word-break: break-word;\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.d-modal {\\n  &__container {\\n    width: 100%;\\n  }\\n}\\n\\n.sidebar__edit-navigation-menu__filter {\\n  display: flex;\\n  gap: 0.5em;\\n  padding: 1rem 0.66em 0;\\n\\n  @include viewport.from(md) {\\n    padding: 1rem 1.5rem 0;\\n  }\\n\\n  .sidebar__edit-navigation-menu__filter-dropdown {\\n    .select-kit-header {\\n      background: var(--secondary);\\n      color: var(--primary);\\n      border: 1px solid var(--primary-low-mid);\\n      font-size: var(--font-0);\\n\\n      &:hover,\\n      &:focus {\\n        background: var(--secondary);\\n        color: var(--primary);\\n\\n        .d-icon {\\n          color: var(--primary);\\n        }\\n      }\\n    }\\n  }\\n\\n  .sidebar__edit-navigation-menu__filter-input {\\n    display: flex;\\n    flex-direction: row;\\n    margin-right: auto;\\n    width: 100%;\\n    position: relative;\\n    flex: 1 1 70%;\\n\\n    input {\\n      margin: 0;\\n    }\\n  }\\n\\n  .sidebar__edit-navigation-menu__filter-dropdown-wrapper {\\n    flex: 1 1 30%;\\n    display: flex;\\n\\n    .select-kit {\\n      width: 100%;\\n\\n      summary {\\n        height: 100%;\\n      }\\n    }\\n  }\\n\\n  .sidebar__edit-navigation-menu__filter-input-icon {\\n    position: absolute;\\n    left: 0.5em;\\n    top: 0.65em;\\n    color: var(--primary-low-mid);\\n  }\\n\\n  .sidebar__edit-navigation-menu__filter-input-field {\\n    border-color: var(--primary-low-mid);\\n    padding-left: 1.75em;\\n    width: 100%;\\n\\n    &:focus {\\n      border-color: var(--tertiary);\\n      outline: none;\\n      outline-offset: 0;\\n      box-shadow: inset 0 0 0 1px var(--tertiary);\\n    }\\n  }\\n}\\n\\n.sidebar__edit-navigation-menu__footer {\\n  display: flex;\\n  width: 100%;\\n  margin-top: 0.25em;\\n\\n  .btn.sidebar__edit-navigation-menu__reset-defaults-button {\\n    margin-left: auto;\\n    margin-right: 0;\\n\\n    .d-icon {\\n      font-size: var(--font-down-1);\\n      color: var(--tertiary);\\n    }\\n\\n    &:focus,\\n    &:active {\\n      background: none;\\n    }\\n  }\\n}\\n\\n.sidebar__edit-navigation-menu__deselect-wrapper {\\n  margin: 0 1em 0 0;\\n  line-height: var(--line-height-medium);\\n\\n  .btn-flat.sidebar__edit-navigation-menu__deselect-button {\\n    margin-left: auto;\\n    padding: 0;\\n\\n    &:focus,\\n    &:active {\\n      background: none;\\n    }\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.sidebar-tags-form {\\n  height: 100%;\\n  display: grid;\\n  gap: 0 0.5em;\\n  margin: 0;\\n  grid-template-columns: repeat(auto-fill, minmax(12em, 1fr));\\n  align-items: flex-start;\\n  grid-auto-rows: min-content;\\n\\n  &__no-tags {\\n    grid-column-start: 1;\\n    grid-column-end: -1;\\n  }\\n\\n  .sidebar-tags-form__tag {\\n    display: flex;\\n    align-items: center;\\n    margin-bottom: 0.5rem;\\n\\n    .sidebar-tags-form__tag-label {\\n      margin-bottom: 0;\\n      min-width: 0;\\n      padding: 0.33em 0;\\n      font-weight: normal;\\n\\n      @include viewport.until(md) {\\n        // extra tappable space\\n        padding: 0.5em 0;\\n      }\\n\\n      p {\\n        overflow: hidden;\\n        margin: 0;\\n      }\\n\\n      &-name {\\n        // avoid long tags breaking the layou\\n        word-break: break-all;\\n      }\\n    }\\n\\n    .sidebar-tags-form__input {\\n      margin-top: 0;\\n    }\\n  }\\n\\n  .sidebar-tags-form__tag-label-count {\\n    color: var(--primary-medium);\\n  }\\n}\\n\\n@include viewport.from(sm) {\\n  .sidebar__edit-navigation-menu__tags-modal {\\n    .d-modal__body {\\n      max-height: 30vh;\\n    }\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n:root {\\n  --progress-bar-line-width: 1px;\\n  --progress-bar-circle-size: 0.5rem;\\n  --progress-bar-icon-size: 0.25rem;\\n}\\n\\n.signup-progress-bar {\\n  width: auto;\\n  display: flex;\\n  box-sizing: border-box;\\n  margin-bottom: 1.2rem;\\n  gap: 1rem;\\n\\n  @include viewport.until(sm) {\\n    margin: 1.5rem 0.85rem;\\n  }\\n\\n  .account-created &,\\n  .activate-account & {\\n    margin-inline: 0;\\n  }\\n\\n  &__segment {\\n    width: auto;\\n    display: flex;\\n    flex-direction: column;\\n    gap: 0.5rem;\\n    color: var(--primary-low-mid);\\n\\n    &:first-child .signup-progress-bar__circle {\\n      transform: translateX(50%);\\n      z-index: 1;\\n    }\\n\\n    &:last-child {\\n      width: var(--progress-bar-circle-size);\\n\\n      .signup-progress-bar__circle {\\n        transform: translateX(-50%);\\n        z-index: 1;\\n      }\\n    }\\n  }\\n\\n  &__step {\\n    display: flex;\\n  }\\n\\n  &__circle {\\n    flex-shrink: 0;\\n    font-size: var(--progress-bar-icon-size);\\n    color: var(--secondary);\\n    display: flex;\\n    justify-content: center;\\n    align-items: center;\\n    height: var(--progress-bar-circle-size);\\n    width: var(--progress-bar-circle-size);\\n    transform: none;\\n    border-radius: 50%;\\n    border: var(--progress-bar-line-width) solid var(--primary-low-mid);\\n    background-color: var(--secondary);\\n\\n    .--active & {\\n      background-color: var(--success);\\n      border-color: var(--success);\\n      box-shadow: 0 0 1px calc(var(--progress-bar-circle-size) / 2)\\n        var(--success-low);\\n    }\\n\\n    .--completed & {\\n      background-color: var(--success);\\n      border-color: var(--success);\\n    }\\n  }\\n}\\n",".site-skeleton {\\n  // Derived from the active color scheme so the skeleton matches any theme.\\n  --site-skeleton-accent: var(--tertiary);\\n  --site-skeleton-accent-soft: var(--tertiary-hover);\\n  --site-skeleton-bg: var(--tertiary-low);\\n  --site-skeleton-content-bg: var(--secondary);\\n  --site-skeleton-muted: var(--primary-medium);\\n  --site-skeleton-border: var(--primary-low);\\n  --site-skeleton-sidebar-border: var(--primary-low);\\n  --site-skeleton-sidebar-active: var(--tertiary-medium);\\n  --site-skeleton-search-bg: var(--secondary);\\n\\n  // Fixed lavender-grey placeholder tone (reads as neutral \\"text\\", so it\\n  // intentionally doesn't track the theme accent). Light/dark variants keep the\\n  // bars legible against the surface in either color mode.\\n  --site-skeleton-line: light-dark(#c3cbe0, #7b7f88);\\n  --site-skeleton-line-strong: light-dark(#aab4d2, #969aa3);\\n  --site-skeleton-scrim: rgb(var(--secondary-rgb), 0.18);\\n  --site-skeleton-sweep: rgb(var(--primary-rgb), 0.06);\\n  position: fixed;\\n  inset: 0;\\n  z-index: 0;\\n  background: var(--site-skeleton-bg);\\n  filter: saturate(0.72);\\n  opacity: 0.78;\\n  pointer-events: none;\\n  user-select: none;\\n}\\n\\n.site-skeleton::after {\\n  content: \\"\\";\\n  position: absolute;\\n  inset: 0;\\n  z-index: 2;\\n  background: var(--site-skeleton-scrim);\\n  backdrop-filter: blur(1.5px);\\n}\\n\\n// Sweeping highlight that gives every placeholder bar its shimmer.\\n.site-skeleton::before {\\n  content: \\"\\";\\n  position: absolute;\\n  inset: 0;\\n  z-index: 1;\\n  background: linear-gradient(\\n    110deg,\\n    transparent 0%,\\n    transparent 28%,\\n    var(--site-skeleton-sweep) 45%,\\n    transparent 62%,\\n    transparent 100%\\n  );\\n  animation: siteSkeletonSweep 3.8s ease-in-out infinite;\\n}\\n\\n// Generic placeholder bar that stands in for any line of text.\\n.site-skeleton__bar {\\n  display: block;\\n  width: 55%;\\n  height: 0.62rem;\\n  border-radius: 999px;\\n  background: var(--site-skeleton-line);\\n\\n  &.--xs {\\n    width: 22%;\\n  }\\n\\n  &.--sm {\\n    width: 38%;\\n  }\\n\\n  &.--md {\\n    width: 55%;\\n  }\\n\\n  &.--lg {\\n    width: 78%;\\n  }\\n\\n  &.--full {\\n    width: 100%;\\n  }\\n\\n  &.--title {\\n    width: 34%;\\n    height: 0.46rem;\\n  }\\n\\n  &.--strong {\\n    height: 0.85rem;\\n    background: var(--site-skeleton-line-strong);\\n  }\\n\\n  &.--heading {\\n    height: 1rem;\\n    border-radius: 6px;\\n    background: var(--site-skeleton-line-strong);\\n  }\\n\\n  &.--brand {\\n    width: 92px;\\n    height: 0.7rem;\\n  }\\n\\n  &.--accent {\\n    background: var(--site-skeleton-accent);\\n    opacity: 0.85;\\n  }\\n}\\n\\n.site-skeleton__header {\\n  position: fixed;\\n  top: 0;\\n  left: 0;\\n  right: 0;\\n  z-index: 1;\\n  display: grid;\\n  grid-template-columns: 300px minmax(0, 1fr) max-content max-content;\\n  column-gap: 0.85rem;\\n  align-items: center;\\n  height: 48px;\\n  background: var(--site-skeleton-bg);\\n}\\n\\n.site-skeleton__brand {\\n  display: flex;\\n  align-items: center;\\n  gap: 1.25rem;\\n  padding: 0 1.65rem;\\n}\\n\\n.site-skeleton__menu {\\n  display: flex;\\n  align-items: center;\\n  color: var(--site-skeleton-accent-soft);\\n  font-size: 1.35rem;\\n  line-height: 1;\\n}\\n\\n.site-skeleton__chat {\\n  display: flex;\\n  align-items: center;\\n  grid-column: 3;\\n  justify-self: end;\\n  color: var(--site-skeleton-accent-soft);\\n  font-size: 1.35rem;\\n  line-height: 1;\\n}\\n\\n.site-skeleton__avatar {\\n  grid-column: 4;\\n  width: 2.25rem;\\n  height: 2.25rem;\\n  border-radius: 50%;\\n  margin-right: 1.25rem;\\n  background: var(--site-skeleton-line-strong);\\n}\\n\\n.site-skeleton__body {\\n  display: grid;\\n  grid-template-columns: 300px minmax(720px, 1fr);\\n  min-height: 100%;\\n  padding-top: 48px;\\n  background: var(--site-skeleton-bg);\\n}\\n\\n.site-skeleton__sidebar,\\n.site-skeleton__content {\\n  min-width: 0;\\n}\\n\\n.site-skeleton__sidebar {\\n  display: flex;\\n  flex-direction: column;\\n  gap: 0.35rem;\\n  padding: 0.25rem 1.3rem 1rem;\\n}\\n\\n.site-skeleton__new-topic {\\n  display: flex;\\n  align-items: center;\\n  justify-content: center;\\n  height: 36px;\\n  margin: 0.1rem 0 1.45rem;\\n  border-radius: 999px;\\n  background: var(--site-skeleton-accent);\\n}\\n\\n.site-skeleton__nav-item,\\n.site-skeleton__category {\\n  display: flex;\\n  align-items: center;\\n  gap: 0.75rem;\\n  min-height: 2rem;\\n  padding: 0.3rem 0.55rem;\\n  border-radius: 7px;\\n  line-height: 1.2;\\n}\\n\\n.site-skeleton__nav-item.--active {\\n  background: var(--site-skeleton-sidebar-active);\\n}\\n\\n.site-skeleton__nav-icon {\\n  display: inline-flex;\\n  align-items: center;\\n  justify-content: center;\\n  width: 1rem;\\n  color: var(--site-skeleton-muted);\\n  flex: 0 0 auto;\\n  font-size: 0.95rem;\\n  line-height: 1;\\n}\\n\\n.site-skeleton__sidebar-section {\\n  margin-top: 1rem;\\n  padding-top: 0.65rem;\\n  border-top: 1px solid var(--site-skeleton-sidebar-border);\\n}\\n\\n.site-skeleton__sidebar-title {\\n  padding: 0 0.55rem 0.7rem;\\n}\\n\\n.site-skeleton__category-dot {\\n  width: 0.75rem;\\n  height: 0.75rem;\\n  border-radius: 50%;\\n  flex: 0 0 auto;\\n}\\n\\n// Fixed swatches standing in for real category/channel colors (these mimic\\n// arbitrary per-category colors, not the theme palette).\\n.site-skeleton__category-dot.--blue {\\n  background: #2da8e8;\\n}\\n\\n.site-skeleton__category-dot.--light-blue {\\n  background: #bfe8fb;\\n}\\n\\n.site-skeleton__category-dot.--staff {\\n  background: linear-gradient(90deg, #2c95d3 0 50%, #4961bf 50% 100%);\\n}\\n\\n.site-skeleton__channel {\\n  width: 14px;\\n  height: 12px;\\n  border-radius: 999px;\\n  flex: 0 0 auto;\\n}\\n\\n.site-skeleton__channel.--blue {\\n  background: #2ca8e0;\\n}\\n\\n.site-skeleton__channel.--red {\\n  background: #df4a32;\\n}\\n\\n.site-skeleton__content {\\n  padding: 0 1rem 1rem 0;\\n}\\n\\n.site-skeleton__card {\\n  min-height: calc(100vh - 7rem);\\n  padding: 1.05rem 0 3rem;\\n  border-radius: 14px;\\n  background: var(--site-skeleton-content-bg);\\n}\\n\\n.site-skeleton__welcome-row {\\n  display: grid;\\n  grid-template-columns: 1fr 1.25fr;\\n  align-items: center;\\n  gap: 3rem;\\n  width: min(72%, 954px);\\n  margin: 0 auto 3.35rem;\\n  padding-bottom: 2rem;\\n  border-bottom: 1px solid var(--site-skeleton-border);\\n}\\n\\n.site-skeleton__welcome-greeting {\\n  display: flex;\\n  flex-direction: column;\\n  align-items: center;\\n  gap: 0.7rem;\\n}\\n\\n.site-skeleton__search {\\n  display: flex;\\n  align-items: center;\\n  gap: 0.75rem;\\n  width: min(42vw, 600px);\\n  height: 38px;\\n  box-sizing: border-box;\\n  padding: 0 0.95rem;\\n  border: 1px solid var(--site-skeleton-border);\\n  border-radius: 7px;\\n  background: var(--site-skeleton-search-bg);\\n}\\n\\n.site-skeleton__search-icon {\\n  display: inline-flex;\\n  align-items: center;\\n  justify-content: center;\\n  width: 1rem;\\n  color: var(--site-skeleton-muted);\\n  flex: 0 0 auto;\\n  font-size: 0.95rem;\\n  line-height: 1;\\n}\\n\\n.site-skeleton__search-icon.--filters {\\n  margin-left: auto;\\n}\\n\\n.site-skeleton__tabs {\\n  display: flex;\\n  align-items: center;\\n  gap: 1.55rem;\\n  width: min(72%, 954px);\\n  margin: 0 auto 1.2rem;\\n}\\n\\n.site-skeleton__tabs > span {\\n  padding: 0.8rem 0;\\n}\\n\\n.site-skeleton__tabs > .--active {\\n  border-bottom: 2px solid var(--site-skeleton-accent-soft);\\n}\\n\\n.site-skeleton__tabs button {\\n  width: 6rem;\\n  height: 2.1rem;\\n  margin-left: auto;\\n  border: 1px solid var(--site-skeleton-border);\\n  border-radius: 7px;\\n  background: var(--site-skeleton-content-bg);\\n}\\n\\n.site-skeleton__topic-list {\\n  display: flex;\\n  flex-direction: column;\\n  gap: 1rem;\\n  width: min(72%, 954px);\\n  margin: 0 auto;\\n}\\n\\n.site-skeleton__topic {\\n  position: relative;\\n  display: grid;\\n  grid-template-columns: 2.4rem minmax(0, 1fr) auto;\\n  gap: 0.85rem;\\n  min-height: 9.5rem;\\n  padding: 1.25rem 1rem 1rem;\\n  border: 1px solid var(--site-skeleton-border);\\n  border-radius: 18px;\\n  background: var(--site-skeleton-content-bg);\\n}\\n\\n.site-skeleton__topic-avatar {\\n  width: 2rem;\\n  height: 2rem;\\n  border-radius: 50%;\\n  background: var(--site-skeleton-line-strong);\\n}\\n\\n.site-skeleton__topic-avatar.--system {\\n  position: relative;\\n  background:\\n    radial-gradient(\\n      circle at 50% 50%,\\n      transparent 0 38%,\\n      var(--site-skeleton-line-strong) 39% 60%,\\n      transparent 61%\\n    ),\\n    conic-gradient(\\n      from 0deg,\\n      var(--site-skeleton-line-strong) 0deg 20deg,\\n      transparent 20deg 40deg,\\n      var(--site-skeleton-line-strong) 40deg 60deg,\\n      transparent 60deg 80deg,\\n      var(--site-skeleton-line-strong) 80deg 100deg,\\n      transparent 100deg 120deg,\\n      var(--site-skeleton-line-strong) 120deg 140deg,\\n      transparent 140deg 160deg,\\n      var(--site-skeleton-line-strong) 160deg 180deg,\\n      transparent 180deg 200deg,\\n      var(--site-skeleton-line-strong) 200deg 220deg,\\n      transparent 220deg 240deg,\\n      var(--site-skeleton-line-strong) 240deg 260deg,\\n      transparent 260deg 280deg,\\n      var(--site-skeleton-line-strong) 280deg 300deg,\\n      transparent 300deg 320deg,\\n      var(--site-skeleton-line-strong) 320deg 340deg,\\n      transparent 340deg 360deg\\n    );\\n}\\n\\n.site-skeleton__topic-main {\\n  display: flex;\\n  flex-direction: column;\\n  gap: 0.35rem;\\n  min-width: 0;\\n}\\n\\n.site-skeleton__topic-excerpt {\\n  display: flex;\\n  flex-direction: column;\\n  gap: 0.5rem;\\n  margin: 0.7rem 0 0;\\n  padding-bottom: 0.85rem;\\n  border-bottom: 1px solid var(--site-skeleton-border);\\n}\\n\\n.site-skeleton__topic-tag {\\n  align-self: flex-start;\\n  width: 3.4rem;\\n  height: 1.15rem;\\n  margin-top: 0.65rem;\\n  border-radius: 4px;\\n  background: var(--tertiary-low);\\n}\\n\\n.site-skeleton__topic-tag.--staff {\\n  background: var(--danger-low);\\n}\\n\\n.site-skeleton__topic-pin {\\n  align-self: start;\\n  width: 3.2rem;\\n  height: 1.5rem;\\n  border: 1px solid var(--site-skeleton-border);\\n  border-radius: 7px;\\n}\\n\\n@keyframes siteSkeletonSweep {\\n  0% {\\n    transform: translateX(-100%);\\n  }\\n\\n  100% {\\n    transform: translateX(100%);\\n  }\\n}\\n\\n@media screen and (prefers-reduced-motion: reduce) {\\n  .site-skeleton::before {\\n    animation: none;\\n  }\\n}\\n\\n@media screen and (width <= 40rem) {\\n  .site-skeleton__header {\\n    padding: 0 1rem;\\n  }\\n\\n  .site-skeleton__body {\\n    grid-template-columns: 1fr;\\n    margin-top: 1rem;\\n    padding: 0 1rem;\\n  }\\n\\n  .site-skeleton__sidebar,\\n  .site-skeleton__search {\\n    display: none;\\n  }\\n\\n  .site-skeleton__brand {\\n    min-width: 0;\\n  }\\n\\n  .site-skeleton__tabs {\\n    gap: 0.9rem;\\n  }\\n\\n  .site-skeleton__tabs button {\\n    display: none;\\n  }\\n\\n  .site-skeleton__topic {\\n    grid-template-columns: 2rem minmax(8rem, 1fr) 2.5rem;\\n    gap: 0.75rem;\\n    min-height: 4rem;\\n    padding: 0.65rem 0.75rem;\\n  }\\n\\n  .site-skeleton__topic-avatar {\\n    width: 2rem;\\n    height: 2rem;\\n  }\\n}\\n",".svg-icon,\\n.svg-icon-title {\\n  height: 1em;\\n  width: 1em;\\n  line-height: 1;\\n  display: inline-flex;\\n  position: relative;\\n  vertical-align: -0.125em;\\n  fill: currentcolor;\\n  flex-shrink: 0; // Prevent the icon from shrinking if it's in a flexbox\\n  overflow: visible;\\n}\\n\\n// Fixes Edge bug with SVG elements not triggering click event\\nsvg > use {\\n  pointer-events: none;\\n}\\n\\n// Stacked Icons\\n// Usage:\\n// <span class=\\"fa-stack\\">\\n//    <svg class=\\"... d-icon-icon1 fa-stack-1x ...\\" xmlns=\\"http://www.w3.org/2000/svg\\"><use href=\\"#icon1\\"></use></svg>\\n//    <svg class=\\"... d-icon-icon2 fa-stack-2x ...\\" xmlns=\\"http://www.w3.org/2000/svg\\"><use href=\\"#icon2\\"></use></svg>\\n// </span>\\n// -------------------------\\n.fa-stack {\\n  position: relative;\\n  width: 1em;\\n  height: 1em;\\n  display: inline-block;\\n\\n  .fa-stack-1x,\\n  .fa-stack-2x {\\n    left: 0;\\n    top: 0;\\n    position: absolute;\\n  }\\n\\n  .fa-stack-2x {\\n    height: 1.5em;\\n    width: 1.5em;\\n    margin-top: -0.25em;\\n    margin-left: -0.25em;\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.d-table {\\n  width: 100%;\\n\\n  @include viewport.until(md) {\\n    border-collapse: collapse;\\n    margin-bottom: var(--space-12);\\n  }\\n\\n  th,\\n  td {\\n    padding: var(--space-2);\\n  }\\n\\n  // Badges/statuses\\n  // Default\\n  .status-label {\\n    --d-border-radius: var(--space-4);\\n    --status-icon-diameter: 8px;\\n    display: flex;\\n    flex-wrap: nowrap;\\n    width: fit-content;\\n    background-color: var(--primary-low);\\n    padding: var(--space-half) var(--space-2);\\n    border-radius: var(--d-border-radius);\\n\\n    .status-label-indicator {\\n      display: inline-block;\\n      width: var(--status-icon-diameter);\\n      height: var(--status-icon-diameter);\\n      border-radius: 50%;\\n      background-color: var(--primary-high);\\n      flex-shrink: 0;\\n      margin-right: var(--space-1);\\n      margin-top: 0.35rem;\\n    }\\n\\n    .status-label-text {\\n      color: var(--primary-high);\\n      font-size: var(--font-down-1);\\n    }\\n  }\\n\\n  // Success badge\\n  .status-label.--success {\\n    background-color: var(--success-low);\\n\\n    .status-label-indicator {\\n      background-color: var(--success);\\n    }\\n\\n    .status-label-text {\\n      color: var(--success-hover);\\n    }\\n  }\\n\\n  // Critical badge\\n  .status-label.--critical {\\n    background-color: var(--danger-low);\\n\\n    .status-label-indicator {\\n      background-color: var(--danger);\\n    }\\n\\n    .status-label-text {\\n      color: var(--danger-hover);\\n    }\\n  }\\n\\n  // Inactive badge\\n  .status-label.--inactive {\\n    background-color: var(--primary-low);\\n\\n    .status-label-indicator {\\n      background-color: var(--primary-high);\\n    }\\n\\n    .status-label-text {\\n      color: var(--primary-high);\\n    }\\n  }\\n}\\n\\n.d-table__header {\\n  @include viewport.until(md) {\\n    display: none;\\n  }\\n}\\n\\n.d-table__header-cell {\\n  text-align: left;\\n  font-weight: normal;\\n  color: var(--primary-high);\\n  vertical-align: bottom;\\n}\\n\\n.d-table__row {\\n  position: relative;\\n  padding: var(--space-1) 0;\\n\\n  @include viewport.until(md) {\\n    display: block;\\n    margin-bottom: var(--space-3);\\n    border: 1px solid var(--content-border-color);\\n  }\\n\\n  &.has-update {\\n    background-color: var(--tertiary-very-low);\\n    border-left: solid 3px var(--tertiary);\\n  }\\n}\\n\\n.d-table__cell {\\n  vertical-align: middle;\\n\\n  @include viewport.until(md) {\\n    display: block;\\n    border-top: 1px solid var(--content-border-color);\\n  }\\n\\n  &:first-child {\\n    @include viewport.until(md) {\\n      border-top: 0;\\n    }\\n  }\\n}\\n\\n.d-table__cell.--overview {\\n  @include viewport.until(md) {\\n    width: auto;\\n    border-top: 0;\\n  }\\n\\n  .d-table__overview-name {\\n    font-weight: 700;\\n    max-width: 80%;\\n    margin-bottom: var(--space-1);\\n    color: var(--primary);\\n  }\\n\\n  .d-table__overview-link {\\n    color: var(--primary);\\n\\n    .d-table__overview-name {\\n      &:hover,\\n      &:focus {\\n        color: var(--tertiary);\\n      }\\n    }\\n  }\\n\\n  a.d-table__overview-name {\\n    &:visited {\\n      color: currentcolor;\\n    }\\n\\n    &:hover,\\n    &:focus {\\n      color: var(--tertiary);\\n    }\\n  }\\n\\n  .d-table__overview-author {\\n    font-size: var(--font-down-1);\\n    margin-bottom: var(--space-1);\\n  }\\n\\n  .d-table__overview-about {\\n    padding-right: var(--space-4);\\n\\n    @include viewport.until(md) {\\n      padding-top: var(--space-1);\\n    }\\n\\n    .d-icon {\\n      font-size: var(--font-down-3);\\n      margin-bottom: 0.1em;\\n    }\\n  }\\n\\n  .d-table__overview-flags {\\n    color: var(--primary-high);\\n    font-size: var(--font-down-1);\\n    text-transform: lowercase;\\n\\n    &::first-letter {\\n      text-transform: uppercase;\\n    }\\n  }\\n}\\n\\n.d-table__cell.--detail {\\n  @include viewport.until(md) {\\n    display: flex;\\n    justify-content: space-between;\\n  }\\n}\\n\\n.d-table__mobile-label {\\n  display: none;\\n\\n  @include viewport.until(md) {\\n    display: inline-flex;\\n    color: var(--primary-high);\\n  }\\n}\\n\\n.d-table__cell.--controls {\\n  text-align: right;\\n  width: auto;\\n\\n  @include viewport.until(md) {\\n    position: absolute;\\n    top: -3px;\\n    right: 0;\\n    border-top: 0;\\n    width: auto;\\n  }\\n}\\n\\n// Wraps and aligns button group like main action + icon only button\\n.d-table__cell-actions {\\n  display: flex;\\n  flex-direction: row;\\n  gap: 0.5em;\\n  justify-content: flex-end;\\n\\n  .fk-d-menu__trigger {\\n    font-size: var(--font-down-1);\\n  }\\n}\\n\\n// Wraps and aligns cell content like icons and text\\n.d-table__value-wrapper {\\n  display: flex;\\n  align-items: center;\\n  gap: var(--space-1);\\n}\\n\\n.d-table__badges {\\n  display: flex;\\n  flex-wrap: wrap;\\n  gap: var(--space-1);\\n  align-items: center;\\n  min-height: var(--space-8);\\n}\\n\\n.d-table-badge {\\n  display: flex;\\n  font-size: var(--font-down-2);\\n  border-radius: var(--d-button-border-radius);\\n  color: var(--primary-very-high);\\n  background: var(--tertiary-very-low);\\n  letter-spacing: 0.25px;\\n\\n  span {\\n    display: flex;\\n    align-items: center;\\n    gap: 0 var(--space-1);\\n  }\\n\\n  &__content {\\n    padding: var(--space-half) var(--space-2);\\n  }\\n\\n  &__info {\\n    border-left: 1px solid var(--secondary);\\n    border-radius: 0 var(--d-button-border-radius) var(--d-button-border-radius)\\n      0;\\n    padding: var(--space-half) var(--space-1);\\n  }\\n\\n  svg {\\n    font-size: var(--font-down-2);\\n    color: var(--primary-high);\\n  }\\n}\\n",".tap-tile-grid {\\n  justify-content: space-between;\\n  margin: 0.5em 0 1em 0;\\n\\n  .tap-tile {\\n    color: var(--primary-high);\\n    padding: 0.75em 0.25em;\\n    display: flex;\\n    flex-wrap: wrap;\\n    align-items: center;\\n    border-bottom: 1px solid var(--content-border-color);\\n    cursor: pointer;\\n\\n    &:first-child {\\n      border-top: 1px solid var(--content-border-color);\\n    }\\n\\n    &:hover {\\n      background-color: var(--d-hover);\\n    }\\n\\n    &.active {\\n      background-color: var(--d-selected);\\n    }\\n\\n    .d-icon {\\n      color: var(--primary-high);\\n      margin: 0 0.5em 0 0;\\n    }\\n\\n    .tap-tile-title {\\n      color: var(--primary);\\n      margin-right: auto;\\n    }\\n\\n    .tap-tile-date {\\n      margin-left: 1em;\\n    }\\n  }\\n}\\n","@mixin theme-card-border($color) {\\n  border-color: var(--#{$color}-medium);\\n  box-shadow: 0 0 0 3px var(--#{$color}-low);\\n}\\n\\n.themes-cards-container {\\n  display: grid;\\n  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));\\n  gap: 1em;\\n  align-items: stretch;\\n  margin-top: var(--space-4);\\n}\\n\\n.theme-card {\\n  display: flex;\\n  flex-direction: column;\\n  position: relative;\\n  box-shadow: 0 0 0 3px transparent;\\n  transition: box-shadow 0.3s ease-in-out;\\n  height: 100%;\\n\\n  &.--updating {\\n    animation:\\n      updating 3s ease-in-out 1,\\n      updatingInfinite 3s ease-in-out 3s infinite;\\n\\n    @keyframes updating {\\n      0% {\\n        box-shadow: 0 0 0 3px transparent;\\n        border: 1px solid var(--success);\\n      }\\n\\n      50% {\\n        box-shadow: 0 0 0 6px var(--success-low);\\n        border: 1px solid var(--success);\\n      }\\n\\n      100% {\\n        box-shadow: 0 0 0 3px var(--success-low);\\n        border: 1px solid var(--success);\\n      }\\n    }\\n\\n    @keyframes updatingInfinite {\\n      0% {\\n        box-shadow: 0 0 0 3px var(--success-low);\\n        border: 1px solid var(--success);\\n      }\\n\\n      50% {\\n        box-shadow: 0 0 0 6px var(--success-low);\\n        border: 1px solid var(--success);\\n      }\\n\\n      100% {\\n        box-shadow: 0 0 0 3px var(--success-low);\\n        border: 1px solid var(--success);\\n      }\\n    }\\n  }\\n\\n  &.--updating .d-icon-arrows-rotate {\\n    animation: rotate 3s linear infinite;\\n    margin-right: 0.45em;\\n\\n    @keyframes rotate {\\n      0% {\\n        transform: rotate(0deg);\\n      }\\n\\n      100% {\\n        transform: rotate(360deg);\\n      }\\n    }\\n  }\\n\\n  .admin-config-area-card__content {\\n    display: flex;\\n    flex-direction: column;\\n    flex-grow: 1;\\n  }\\n\\n  &.--default {\\n    @include theme-card-border(tertiary);\\n  }\\n\\n  &__icons {\\n    display: flex;\\n  }\\n\\n  .ember-checkbox {\\n    margin: 0 5px 0 0;\\n  }\\n\\n  &__checkbox-label {\\n    margin: 0;\\n    font-weight: 400;\\n  }\\n\\n  &__title {\\n    font-size: var(--font-up-0);\\n    font-weight: 700;\\n    display: flex;\\n    gap: 0.5rem;\\n    align-items: center;\\n    overflow-wrap: anywhere;\\n    color: var(--primary);\\n\\n    &:visited {\\n      color: currentcolor;\\n    }\\n\\n    &:hover,\\n    &:focus {\\n      color: var(--tertiary);\\n    }\\n  }\\n\\n  &__content {\\n    padding-inline: 1rem;\\n    padding-top: 1rem;\\n    display: flex;\\n    flex-direction: column;\\n    flex-grow: 1;\\n  }\\n\\n  &__description {\\n    margin: 0 0 10px 0;\\n  }\\n\\n  &__components {\\n    display: -webkit-box;\\n    font-size: var(--font-down-1);\\n    color: var(--primary-high);\\n    -webkit-box-orient: vertical;\\n    overflow: hidden;\\n    -webkit-line-clamp: 3;\\n  }\\n\\n  &__install-button {\\n    margin-top: auto;\\n  }\\n\\n  &__install-more-icon {\\n    height: 160px;\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    border-bottom: 1px solid var(--content-border-color);\\n    background: var(--primary-very-low);\\n    color: var(--primary-medium);\\n\\n    .d-icon {\\n      width: 3rem;\\n      height: 3rem;\\n    }\\n  }\\n\\n  &__button.--set-default {\\n    position: absolute;\\n    top: 4px;\\n    right: 4px;\\n  }\\n\\n  &__footer {\\n    flex-direction: column;\\n    padding-inline: 1rem;\\n    padding-bottom: 1rem;\\n  }\\n\\n  &__controls {\\n    display: flex;\\n    justify-content: space-between;\\n    align-items: center;\\n    margin-top: 0.5rem;\\n  }\\n\\n  &__footer-actions {\\n    margin-left: auto;\\n  }\\n\\n  &__badges {\\n    display: flex;\\n    flex-wrap: wrap;\\n    gap: 0.5rem;\\n    align-items: flex-start;\\n    min-height: 2rem;\\n  }\\n\\n  &__badge {\\n    font-size: var(--font-down-2);\\n    padding: 0.15rem 0.3rem;\\n    border-radius: 4px;\\n    color: var(--primary-very-high);\\n    background: var(--tertiary-low);\\n    letter-spacing: 0.25px;\\n    align-items: center;\\n    display: inline-flex;\\n    gap: 0.25rem;\\n\\n    svg {\\n      height: 0.75em;\\n      color: var(--primary-high);\\n    }\\n  }\\n\\n  .admin-config-area-card__header-action {\\n    display: flex;\\n    justify-content: center;\\n    align-items: center;\\n    background-color: var(--secondary);\\n    right: 20px;\\n    top: 22px;\\n  }\\n}\\n\\n.admin-config-area-card.theme-card\\n  .admin-config-area-card__content\\n  .external-resources {\\n  display: flex;\\n  justify-content: space-between;\\n  flex-direction: column;\\n  font-size: var(--font-down-1);\\n  margin-bottom: 10px;\\n\\n  .external-link {\\n    margin-bottom: 0.25em;\\n    color: var(--primary);\\n    text-decoration: underline;\\n  }\\n}\\n\\n.admin-config-area-card.theme-card {\\n  padding: 0;\\n  height: 100%;\\n  display: flex;\\n  flex-direction: column;\\n  overflow: hidden;\\n\\n  .admin-config-area-card__content {\\n    margin: 0;\\n    padding-right: 0;\\n  }\\n\\n  .admin-config-area-card__header-wrapper {\\n    flex: none;\\n  }\\n}\\n\\n.admin-config-area-card.theme-card.--install-more {\\n  border-style: dashed;\\n}\\n\\n.admin-config-area-card.theme-install-card {\\n  .theme-install-card__external-links {\\n    svg {\\n      font-size: var(--font-down-3);\\n      margin-bottom: 0.1em;\\n    }\\n  }\\n}\\n",".theme-card-preview {\\n  &__image-wrapper {\\n    width: 100%;\\n    height: 160px;\\n    overflow: hidden;\\n    display: flex;\\n    align-items: center;\\n    position: relative;\\n    border-bottom: 1px solid var(--content-border-color);\\n\\n    svg {\\n      width: 100%;\\n      top: 0;\\n      left: 0;\\n    }\\n\\n    &:hover .theme-card-preview__screenshot-toggle {\\n      opacity: 1;\\n    }\\n  }\\n\\n  &__image {\\n    width: 100%;\\n    height: 100%;\\n    flex-shrink: 0;\\n    object-fit: cover;\\n    object-position: top left;\\n  }\\n\\n  &__screenshot-toggle {\\n    position: absolute;\\n    bottom: 0.5rem;\\n    right: 0.5rem;\\n    opacity: 0;\\n    transition: opacity 0.2s ease-in-out;\\n  }\\n\\n  &__content {\\n    padding-inline: 1rem;\\n    padding-top: 1rem;\\n    display: flex;\\n    flex-direction: column;\\n    flex-grow: 1;\\n  }\\n\\n  &__name {\\n    font-size: var(--font-up-0);\\n    font-weight: 700;\\n    overflow-wrap: anywhere;\\n    color: var(--primary);\\n  }\\n\\n  &__description {\\n    margin: 0 0 10px 0;\\n  }\\n}\\n",".d-time-input {\\n  display: inline-flex;\\n\\n  .combo-box {\\n    min-width: 7em;\\n\\n    &:not(.has-selection) {\\n      .select-kit-selected-name .name {\\n        color: var(--primary-medium);\\n      }\\n    }\\n\\n    .select-kit-header {\\n      .d-icon {\\n        padding-left: 0;\\n      }\\n\\n      &:focus {\\n        outline: 1px solid var(--tertiary);\\n      }\\n    }\\n\\n    .select-kit-collection {\\n      min-width: auto;\\n    }\\n\\n    .select-kit-filter {\\n      width: auto;\\n      overflow: hidden;\\n\\n      .filter-input {\\n        min-width: 0;\\n      }\\n    }\\n\\n    .selected-name {\\n      white-space: nowrap;\\n      overflow: hidden;\\n      text-overflow: ellipsis;\\n\\n      small {\\n        display: none;\\n      }\\n    }\\n  }\\n}\\n",".custom-date-time-wrap {\\n  padding: 1em 1em 0.5em;\\n  border: 1px solid var(--content-border-color);\\n  border-top: none;\\n  background: var(--primary-very-low);\\n\\n  .d-icon {\\n    padding: 0 0.75em 0 0;\\n    color: var(--primary-high);\\n    margin-top: -0.5em;\\n  }\\n\\n  .angle-icon {\\n    margin-top: 0;\\n    padding: 0 0 0 5px;\\n  }\\n\\n  .tap-tile-date-input,\\n  .tap-tile-time-input {\\n    display: flex;\\n    align-items: center;\\n  }\\n\\n  .date-picker,\\n  .time-input {\\n    text-align: left;\\n  }\\n\\n  .time-input,\\n  .date-picker-wrapper {\\n    flex: 1 1 auto;\\n  }\\n\\n  &.custom-input-wrap {\\n    border-bottom: 0;\\n    margin-bottom: 0;\\n  }\\n\\n  &.custom-relative-wrap {\\n    .relative-time-picker {\\n      display: flex;\\n    }\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.topic-map.--op {\\n  // topic map under OP\\n  border-top: 1px solid var(--content-border-color);\\n  border-bottom: none;\\n  padding-left: calc(\\n    var(--topic-body-width-padding) + var(--topic-avatar-width)\\n  );\\n}\\n\\n.topic-map.--bottom {\\n  // topic map at bottom of topic\\n  grid-area: posts;\\n  grid-row: 2;\\n  max-width: calc(\\n    var(--topic-avatar-width) + var(--topic-body-width) +\\n      (var(--topic-body-width-padding) * 2)\\n  );\\n}\\n\\n.topic-map {\\n  --chart-line-color: var(--tertiary);\\n  --chart-point-color: var(--tertiary-medium);\\n  --chart-prediction-color: var(--primary-low-mid);\\n  display: flex;\\n  flex-direction: row;\\n  align-items: center;\\n  justify-content: space-between;\\n  flex-wrap: wrap;\\n  column-gap: 0.75em;\\n  border-bottom: 1px solid var(--content-border-color);\\n  box-sizing: border-box;\\n  max-width: calc(\\n    var(--topic-avatar-width) + var(--topic-body-width) +\\n      (var(--topic-body-width-padding) * 2)\\n  );\\n  padding-block: 0.5em;\\n  overflow-anchor: none;\\n\\n  @include viewport.until(sm) {\\n    font-size: var(--font-down-1);\\n  }\\n\\n  &.--op,\\n  &.--bottom {\\n    @media screen and (width <= 500px) {\\n      padding-left: 0;\\n    }\\n  }\\n\\n  .--users-summary {\\n    display: flex;\\n    flex-wrap: wrap;\\n    align-items: center;\\n    overflow: hidden;\\n    height: 2em;\\n    align-self: center;\\n    flex: 1 2 0;\\n    gap: 0.25em;\\n    min-width: 2em;\\n    width: 0;\\n\\n    .avatar {\\n      width: 2em;\\n      height: 2em;\\n      margin-right: 0;\\n    }\\n\\n    .avatar-flair,\\n    .post-count {\\n      display: none;\\n    }\\n  }\\n\\n  &__stats {\\n    display: flex;\\n    flex-wrap: wrap;\\n    margin: 0;\\n    list-style: none;\\n  }\\n\\n  a {\\n    overflow-wrap: anywhere;\\n  }\\n\\n  &__contents {\\n    flex-grow: 1;\\n\\n    .number {\\n      font-size: var(--font-up-1);\\n      line-height: 1.2;\\n    }\\n\\n    .topic-map__stats {\\n      gap: 0.75em;\\n\\n      &.--single-stat {\\n        .fk-d-menu__trigger {\\n          flex-direction: row;\\n          gap: 0.25em;\\n\\n          span {\\n            font-size: var(--font-0);\\n            color: var(--primary-700);\\n            min-width: unset;\\n            overflow: visible;\\n          }\\n        }\\n      }\\n\\n      .fk-d-menu__trigger,\\n      .topic-map__stat {\\n        display: flex;\\n        flex-direction: column;\\n        justify-content: center;\\n        align-items: center;\\n        padding: 0;\\n        background: transparent;\\n        min-width: 0;\\n\\n        .number {\\n          color: var(--tertiary);\\n          white-space: nowrap;\\n        }\\n\\n        .topic-map__stat-label {\\n          display: block;\\n          min-width: 0;\\n          font-size: var(--font-down-1);\\n          color: var(--primary-medium);\\n          width: 100%;\\n\\n          @include ellipsis;\\n        }\\n      }\\n    }\\n  }\\n\\n  .controls {\\n    display: flex;\\n    align-items: center;\\n\\n    .btn {\\n      margin-right: 0.5em;\\n\\n      &:last-child {\\n        margin: 0;\\n      }\\n    }\\n  }\\n\\n  &__buttons {\\n    margin-left: auto;\\n    display: flex;\\n    align-items: center;\\n    gap: 0.75em;\\n  }\\n\\n  .view-explainer {\\n    color: var(--primary-700);\\n    font-size: var(--font-down-1);\\n  }\\n\\n  .estimated-read-time {\\n    display: flex;\\n    flex-direction: column-reverse;\\n    align-items: end;\\n    line-height: 1.2;\\n    color: var(--primary-high);\\n    white-space: nowrap;\\n\\n    span:first-child {\\n      font-size: var(--font-down-1);\\n      color: var(--primary-medium);\\n    }\\n\\n    @media screen and (width <= 475px) {\\n      display: none;\\n    }\\n  }\\n}\\n\\n.mobile-view {\\n  .d-modal[class*=\\"topic-map__\\"] {\\n    h3 {\\n      font-size: var(--font-up-2);\\n      padding-inline: 1rem;\\n    }\\n\\n    p {\\n      overflow-wrap: break-word;\\n    }\\n  }\\n\\n  .topic-owner .onscreen-post {\\n    padding-bottom: 0;\\n  }\\n}\\n\\n// DMenu popups\\n.fk-d-menu,\\n.fk-d-menu-modal {\\n  // shared\\n  &__inner-content {\\n    .topic-map__likes-content &,\\n    .topic-map__links-content &,\\n    .topic-map__users-content &,\\n    .topic-map__views-content & {\\n      flex-direction: column;\\n      padding-block: 0.75em;\\n    }\\n  }\\n\\n  &.topic-map__likes-content,\\n  &.topic-map__links-content,\\n  &.topic-map__users-content,\\n  &.topic-map__views-content {\\n    h3 {\\n      padding-inline: 1rem;\\n      padding-bottom: 0.5em;\\n      font-size: var(--font-up-1);\\n      border-bottom: 1px solid var(--content-border-color);\\n    }\\n\\n    .loading-container {\\n      width: 100%;\\n    }\\n  }\\n\\n  &.topic-map__likes-content,\\n  &.topic-map__links-content {\\n    ul {\\n      margin: 0;\\n      padding: 0;\\n      list-style-type: none;\\n      max-height: 80dvh;\\n    }\\n  }\\n\\n  // per type\\n  &.topic-map__likes-content {\\n    li > a {\\n      display: grid;\\n      grid-template-areas: \\"user likes\\" \\"post post\\";\\n      grid-template-columns: auto 1fr;\\n      gap: 0.25em;\\n      padding: 0.75em 1rem;\\n\\n      .discourse-no-touch & {\\n        &:hover,\\n        &:focus-visible {\\n          outline: 0;\\n          background: var(--d-hover);\\n        }\\n      }\\n    }\\n\\n    li:not(:last-of-type) {\\n      a {\\n        border-bottom: 1px solid var(--content-border-color);\\n      }\\n    }\\n\\n    .like-section {\\n      &__user {\\n        grid-area: user;\\n        color: var(--primary-high);\\n        display: flex;\\n        align-items: center;\\n        font-weight: bold;\\n        gap: 0.5em;\\n      }\\n\\n      &__likes {\\n        grid-area: likes;\\n        display: flex;\\n        gap: 0.25em;\\n        color: var(--primary-medium);\\n        justify-content: end;\\n        align-items: center;\\n\\n        .d-icon {\\n          font-size: var(--font-down-1);\\n          color: var(--love);\\n          position: relative;\\n        }\\n      }\\n    }\\n\\n    p {\\n      grid-area: post;\\n      overflow-wrap: anywhere;\\n      color: var(--primary-high);\\n      text-align: left;\\n      margin: 0;\\n      padding-left: 2em;\\n    }\\n  }\\n\\n  &.topic-map__links-content {\\n    li {\\n      display: grid;\\n      grid-template-columns: auto 1fr;\\n      grid-template-areas:\\n        \\"counter link\\"\\n        \\"counter domain\\";\\n      padding: 0.75em 1rem;\\n      gap: 0.25em;\\n\\n      &:not(:last-of-type) {\\n        border-bottom: 1px solid var(--content-border-color);\\n      }\\n\\n      .discourse-no-touch & {\\n        &:hover,\\n        &:focus-within {\\n          background: var(--d-hover);\\n\\n          a {\\n            outline: 0;\\n          }\\n        }\\n      }\\n    }\\n\\n    .topic-link {\\n      display: grid;\\n      grid-template-columns: subgrid;\\n      grid-row: 1;\\n      grid-column: 1 / -1;\\n\\n      .content {\\n        grid-row: 1;\\n        grid-column: 2;\\n      }\\n    }\\n\\n    .topic-link[data-clicks]::before {\\n      @include click-counter-badge;\\n      grid-row: 1;\\n      grid-column: 1;\\n      align-self: start;\\n      margin-top: 0.35em;\\n    }\\n\\n    .topic-link[data-clicks]::after {\\n      display: none;\\n    }\\n\\n    .domain {\\n      grid-row: 2;\\n      grid-column: 2;\\n      font-size: var(--font-down-2);\\n      color: var(--primary-medium);\\n    }\\n\\n    .link-summary {\\n      width: 100%;\\n\\n      .d-icon {\\n        color: var(--primary-high);\\n      }\\n    }\\n  }\\n\\n  &.topic-map__users-content {\\n    .topic-map__users-list {\\n      display: flex;\\n      flex-wrap: wrap;\\n      gap: 0.5em;\\n      padding: 0.75em 1rem;\\n    }\\n\\n    .poster {\\n      display: block;\\n      position: relative;\\n\\n      img {\\n        width: 2.25em;\\n        height: 2.25em;\\n      }\\n    }\\n\\n    .post-count,\\n    .avatar-flair {\\n      position: absolute;\\n      border-radius: 1em;\\n      display: flex;\\n      align-items: center;\\n      justify-content: center;\\n    }\\n\\n    .post-count {\\n      top: -0.15em;\\n      right: -0.25em;\\n      padding: 0.15em 0.4em 0.2em;\\n      font-size: var(--font-down-2);\\n      line-height: var(--line-height-small);\\n    }\\n\\n    .avatar-flair {\\n      right: -0.25em;\\n      bottom: -0.15em;\\n      font-size: var(--font-down-3);\\n      width: 1.5em;\\n      height: 1.5em;\\n      background-size: contain;\\n    }\\n  }\\n\\n  &.topic-map__views-content {\\n    .topic-views {\\n      display: flex;\\n      flex-direction: column;\\n      align-items: center;\\n\\n      &__wrapper {\\n        display: flex;\\n        justify-content: space-evenly;\\n        padding: 0 1rem;\\n      }\\n\\n      &__count {\\n        font-size: var(--font-up-4);\\n        color: var(--primary-high);\\n      }\\n\\n      &__date {\\n        font-size: var(--font-down-1);\\n        color: var(--primary-medium);\\n      }\\n    }\\n\\n    canvas {\\n      padding: 0.75em 1rem;\\n    }\\n\\n    .view-explainer {\\n      padding: 0 1rem;\\n    }\\n\\n    &:has(.topic-views) {\\n      min-width: unset;\\n    }\\n  }\\n}\\n",".topic-query-filter {\\n  display: flex;\\n  flex-direction: row;\\n  margin-right: auto;\\n  margin-bottom: var(--nav-space);\\n  width: 100%;\\n  gap: var(--space-2);\\n\\n  &__query {\\n    @include form-item-sizing;\\n    position: relative;\\n    display: flex;\\n    align-items: center;\\n    flex: 1;\\n    min-width: 0;\\n    gap: var(--space-3);\\n    padding-inline: 2.25em 0.75em;\\n    color: var(--primary);\\n    background: var(--d-input-bg-color);\\n    border: var(--d-input-border);\\n    border-color: var(--primary-low-mid);\\n    border-radius: var(--d-input-border-radius);\\n    transition:\\n      border-color 0.15s,\\n      box-shadow 0.15s;\\n\\n    &:hover {\\n      color: var(--primary);\\n    }\\n\\n    &:focus-visible {\\n      border-color: var(--tertiary);\\n      outline: 2px solid var(--tertiary);\\n      outline-offset: 1px;\\n      box-shadow: inset 0 0 0 1px var(--tertiary);\\n    }\\n  }\\n\\n  &__query-text {\\n    overflow-wrap: anywhere;\\n  }\\n\\n  &__reset {\\n    margin-inline-start: auto;\\n    flex-shrink: 0;\\n    color: var(--primary-medium);\\n  }\\n\\n  &__label {\\n    background-color: var(--primary-low);\\n    display: flex;\\n    align-items: center;\\n    padding: 0.25em 0.65em;\\n    border: 1px solid var(--primary-low-mid);\\n    border-right: 0;\\n  }\\n\\n  &__input {\\n    position: relative;\\n    flex: 1 1 auto;\\n  }\\n\\n  &__icon {\\n    position: absolute;\\n    left: 0.75em;\\n    top: 50%;\\n    transform: translateY(-50%);\\n    color: var(--primary-medium);\\n    font-size: 0.9em;\\n    pointer-events: none;\\n    opacity: 0.7;\\n    transition:\\n      opacity 0.15s,\\n      color 0.15s;\\n    z-index: 1;\\n  }\\n\\n  &__bulk-action-btn {\\n    margin-right: 0.5em;\\n  }\\n\\n  &__clear-btn {\\n    position: absolute;\\n    right: 0.5em;\\n    top: 50%;\\n    transform: translateY(-50%);\\n    padding: 0.25em;\\n    min-width: unset;\\n    background: transparent;\\n    border: none;\\n    color: var(--primary-medium);\\n    transition: all 0.15s;\\n    z-index: 1;\\n\\n    &:hover {\\n      background: var(--primary-low);\\n      color: var(--primary);\\n    }\\n  }\\n\\n  input.topic-query-filter__filter-term {\\n    margin: 0;\\n    border-color: var(--primary-low-mid);\\n    padding-left: 2.25em;\\n    padding-right: 2.5em;\\n    color: var(--primary);\\n    width: 100%;\\n    transition:\\n      border-color 0.15s,\\n      box-shadow 0.15s;\\n\\n    &:focus {\\n      border-color: var(--tertiary);\\n      outline: none;\\n      outline-offset: 0;\\n      box-shadow: inset 0 0 0 1px var(--tertiary);\\n\\n      ~ .topic-query-filter__icon {\\n        opacity: 1;\\n        color: var(--tertiary);\\n      }\\n    }\\n\\n    &::placeholder {\\n      color: var(--primary-low-mid);\\n      font-style: italic;\\n    }\\n  }\\n}\\n","@use \\"sass:math\\";\\n@use \\"lib/viewport\\";\\n\\n.fk-d-menu[data-identifier=\\"usercard\\"],\\n.fk-d-menu[data-identifier=\\"category-card\\"] {\\n  max-width: calc(100vw - 2em);\\n  width: auto;\\n\\n  .fk-d-menu__inner-content {\\n    min-width: 0;\\n    overflow: visible;\\n  }\\n\\n  @include viewport.until(sm) {\\n    &[data-content] {\\n      z-index: z(\\"max\\");\\n    }\\n  }\\n}\\n\\n.animated-placeholder {\\n  height: 20px;\\n  position: relative;\\n}\\n\\n.card-avatar-placeholder {\\n  width: var(--avatar-width);\\n  height: var(--avatar-width);\\n  border-radius: 100%;\\n  position: relative;\\n  overflow: hidden;\\n\\n  &::before {\\n    position: absolute;\\n    left: 0;\\n    content: \\"\\";\\n    background: linear-gradient(\\n      to right,\\n      var(--primary-very-low) 10%,\\n      var(--primary-low) 18%,\\n      var(--primary-very-low) 33%\\n    );\\n    height: var(--avatar-width);\\n    width: var(--card-width);\\n\\n    @media (prefers-reduced-motion: no-preference) {\\n      animation: placeHolderShimmer 4s linear infinite forwards;\\n    }\\n  }\\n}\\n\\n// shared styles for user, group, and category cards\\n.user-card,\\n.group-card,\\n.category-card {\\n  --card-width: 39em;\\n  --avatar-width: 8em;\\n  --avatar-margin: -3.3em; // extends the avatar above the card\\n  min-width: 0;\\n  width: var(--card-width);\\n  color: var(--primary);\\n  background: var(--secondary) center center;\\n  background-size: cover;\\n  position: unset !important;\\n  margin: 0 !important;\\n  border-radius: var(--d-border-radius) !important;\\n  box-shadow: unset !important;\\n  z-index: unset !important;\\n\\n  @include viewport.until(sm) {\\n    box-sizing: border-box;\\n    max-width: 95vw;\\n    max-height: 85vh; // 2.5vh margin-top and margin-bottom. 10vh top\\n  }\\n\\n  .card-content {\\n    padding: 10px;\\n    background: rgb(var(--secondary-rgb), 0.85);\\n    border-radius: var(--d-border-radius);\\n\\n    &::after {\\n      content: \\"\\";\\n      display: block;\\n      clear: both;\\n    }\\n\\n    a.card-huge-avatar {\\n      border-radius: 50%;\\n      display: block;\\n    }\\n\\n    .bio {\\n      @include line-clamp(2);\\n    }\\n  }\\n\\n  .card-row:not(.first-row) {\\n    margin-top: 0.5em;\\n  }\\n\\n  // avatar - names - controls\\n  .first-row {\\n    display: flex;\\n\\n    @include viewport.until(sm) {\\n      flex-wrap: wrap;\\n    }\\n\\n    .names {\\n      padding-left: 1.25em;\\n      flex: 1 1 auto;\\n\\n      @include viewport.until(sm) {\\n        box-sizing: border-box;\\n        flex: 1 1 0;\\n      }\\n\\n      .user-profile-link {\\n        display: flex;\\n        align-items: center;\\n        outline: none;\\n\\n        &:focus-visible {\\n          border: 1px solid;\\n\\n          @include default-focus;\\n        }\\n      }\\n\\n      .d-icon {\\n        margin: 0 0.25em;\\n      }\\n\\n      .name-username-wrapper {\\n        margin-right: 0;\\n        flex: 0 1 auto;\\n\\n        @include ellipsis;\\n      }\\n\\n      span {\\n        display: block;\\n      }\\n    }\\n\\n    .usercard-controls {\\n      list-style-type: none;\\n      margin: 0;\\n\\n      @include viewport.until(sm) {\\n        width: 100%; // always wraps to next line\\n        display: flex;\\n        flex-wrap: wrap;\\n        margin-top: 1em;\\n        gap: 0.5em;\\n\\n        li {\\n          flex: 1 0 45%;\\n          min-width: 8em;\\n\\n          &:empty {\\n            display: none;\\n          }\\n\\n          button {\\n            margin: 0;\\n\\n            .d-button-label {\\n              @include ellipsis;\\n            }\\n          }\\n        }\\n      }\\n\\n      @include viewport.from(sm) {\\n        max-width: 225px;\\n      }\\n\\n      button {\\n        width: 100%;\\n\\n        @include viewport.from(sm) {\\n          min-width: 150px;\\n        }\\n      }\\n    }\\n  }\\n\\n  .btn {\\n    margin-bottom: 5px;\\n  }\\n\\n  .names__primary {\\n    @include ellipsis;\\n    line-height: var(--line-height-medium);\\n    font-size: var(--font-up-3);\\n    font-weight: bold;\\n\\n    @include viewport.from(sm) {\\n      font-size: var(--font-up-5);\\n    }\\n\\n    .d-icon {\\n      color: var(--primary);\\n      font-size: var(--font-down-1);\\n\\n      @include viewport.until(sm) {\\n        font-size: var(--font-down-2);\\n      }\\n    }\\n  }\\n\\n  .names__secondary {\\n    font-size: var(--font-up-1);\\n\\n    @include viewport.until(sm) {\\n      font-size: var(--font-0);\\n    }\\n  }\\n\\n  .metadata {\\n    display: flex;\\n    flex-wrap: wrap;\\n    gap: 0.15em 0.5em;\\n    color: var(--primary);\\n\\n    &.email,\\n    .desc {\\n      color: var(--primary-high);\\n    }\\n  }\\n\\n  .names__secondary,\\n  [class*=\\"metadata__\\"] {\\n    margin: 0;\\n\\n    @include ellipsis;\\n  }\\n\\n  .names__primary,\\n  .names__secondary {\\n    a {\\n      color: var(--primary);\\n    }\\n  }\\n\\n  p {\\n    margin: 0 0 5px 0;\\n  }\\n}\\n\\n// styles for user cards only\\n.user-card {\\n  &:focus-visible {\\n    // we move focus to the card, but the outline isn't necessary until keyboard nav starts within\\n    outline: none;\\n  }\\n\\n  // avatar - names - controls\\n  .first-row {\\n    .avatar-placeholder {\\n      width: var(--avatar-width);\\n      height: var(--avatar-width);\\n    }\\n\\n    .user-card-avatar {\\n      margin-top: var(--avatar-margin);\\n      max-height: var(--avatar-width);\\n      position: relative;\\n\\n      @include viewport.until(sm) {\\n        flex: 0 0 auto;\\n      }\\n\\n      .own-avatar-pencil {\\n        opacity: 0;\\n        position: absolute;\\n        width: 80%;\\n        height: 85%;\\n        right: 0%;\\n        bottom: 0%;\\n        display: flex;\\n        justify-content: center;\\n        align-items: center;\\n        transition: opacity 0.2s;\\n        z-index: 1;\\n\\n        &--icon {\\n          position: absolute;\\n          bottom: -4px;\\n          right: -6px;\\n          display: flex;\\n          justify-content: center;\\n          align-items: center;\\n          background-color: rgb(var(--secondary-rgb), 1);\\n          border-radius: 50%;\\n          padding: 0.75rem;\\n          font-size: 1.25rem;\\n          color: var(--primary);\\n          box-shadow: var(--shadow-dropdown);\\n          box-sizing: border-box;\\n        }\\n\\n        &:hover {\\n          opacity: 1;\\n        }\\n      }\\n    }\\n\\n    .avatar {\\n      width: var(--avatar-width);\\n      height: var(--avatar-width);\\n    }\\n\\n    .new-user a {\\n      color: var(--primary-low-mid);\\n    }\\n  }\\n\\n  // user bio - suspension reason\\n  .second-row {\\n    max-height: 150px;\\n    overflow: auto;\\n\\n    .bio {\\n      a:not(.mention) {\\n        color: var(--tertiary);\\n      }\\n\\n      .overflow {\\n        max-height: 60px;\\n        overflow: hidden;\\n      }\\n    }\\n\\n    .suspended {\\n      color: var(--danger);\\n\\n      .suspension-reason-title,\\n      .suspension-date {\\n        font-weight: bold;\\n      }\\n    }\\n\\n    .silenced {\\n      color: var(--danger);\\n\\n      .silence-reason-title,\\n      .silence-date {\\n        font-weight: bold;\\n      }\\n    }\\n\\n    .profile-hidden,\\n    .inactive-user {\\n      font-size: var(--font-up-1);\\n      margin-top: 0.5em;\\n    }\\n  }\\n\\n  .featured-topic {\\n    text-align: left;\\n\\n    .desc {\\n      color: var(--primary-high);\\n    }\\n\\n    a {\\n      color: var(--primary);\\n      text-decoration: underline;\\n    }\\n  }\\n\\n  // location and website\\n  .location-and-website {\\n    display: flex;\\n    flex-wrap: wrap;\\n    width: 100%;\\n    align-items: center;\\n\\n    .location,\\n    .website-name {\\n      display: flex;\\n      overflow: hidden;\\n      align-items: center;\\n\\n      .d-icon {\\n        margin-right: 0.25em;\\n      }\\n    }\\n\\n    .website-name a,\\n    .location span {\\n      @include ellipsis;\\n      color: var(--primary);\\n    }\\n\\n    .location,\\n    .local-time,\\n    .website-name {\\n      margin-right: 0.5em;\\n    }\\n\\n    .website-name a {\\n      text-decoration: underline;\\n    }\\n  }\\n\\n  // custom user fields\\n  .public-user-fields {\\n    margin: 0;\\n    text-align: left;\\n\\n    @include viewport.until(sm) {\\n      max-height: 40vh;\\n      overflow-y: auto;\\n\\n      .public-user-field {\\n        @include line-clamp(3);\\n      }\\n    }\\n\\n    @media screen and (height <= 550px) {\\n      max-height: 12vh;\\n    }\\n\\n    .user-field-value-list-item:not(:last-of-type) {\\n      &::after {\\n        // create comma separated list\\n        content: \\",\\";\\n      }\\n    }\\n  }\\n\\n  // badges\\n  .badge-section {\\n    line-height: 0;\\n    display: flex;\\n    flex-wrap: wrap;\\n    gap: var(--space-1);\\n\\n    @include viewport.until(sm) {\\n      display: grid;\\n      grid-template-columns: repeat(2, 1fr);\\n    }\\n\\n    .user-badge {\\n      @include ellipsis;\\n      background: var(--primary-very-low);\\n      border: 1px solid var(--content-border-color);\\n      color: var(--primary);\\n      border-radius: var(--d-border-radius);\\n\\n      @include viewport.until(sm) {\\n        display: flex;\\n        margin: 0;\\n        width: 100%;\\n\\n        .badge-display-name {\\n          overflow: hidden;\\n          text-overflow: ellipsis;\\n        }\\n      }\\n\\n      @include viewport.from(sm) {\\n        display: block;\\n        max-width: 185px;\\n      }\\n    }\\n\\n    .user-card-badge-link {\\n      overflow: hidden;\\n    }\\n\\n    .user-card-badge-link,\\n    .more-user-badges {\\n      vertical-align: top;\\n      display: inline-block;\\n\\n      @include viewport.until(sm) {\\n        display: flex;\\n        box-sizing: border-box;\\n\\n        a {\\n          width: 100%;\\n          display: flex;\\n        }\\n      }\\n    }\\n\\n    .more-user-badges {\\n      @include viewport.from(sm) {\\n        max-width: 125px;\\n      }\\n\\n      a {\\n        @extend .user-badge;\\n      }\\n    }\\n  }\\n\\n  .user-status {\\n    display: flex;\\n    align-items: center;\\n\\n    @include viewport.until(sm) {\\n      font-size: var(--font-down-1);\\n    }\\n\\n    img.emoji {\\n      margin-right: 0.3em;\\n    }\\n\\n    .relative-date {\\n      flex: 1 0 auto;\\n      text-align: left;\\n      font-size: var(--font-down-3);\\n      padding-top: 0.5em;\\n      margin-left: 0.6em;\\n      color: var(--primary-medium);\\n    }\\n\\n    &__description {\\n      @include ellipsis;\\n    }\\n  }\\n}\\n\\n// styles for group cards only\\n.group-card {\\n  // avatar - names and controls\\n  .first-row {\\n    .group-card-avatar {\\n      margin-top: var(--avatar-margin);\\n    }\\n\\n    .avatar-flair {\\n      display: flex;\\n      background-size: contain;\\n      background-repeat: no-repeat;\\n      width: var(--avatar-width);\\n      height: var(--avatar-width);\\n      color: var(--primary);\\n\\n      .d-icon {\\n        margin: auto;\\n        font-size: calc(var(--avatar-width) / 1.5);\\n      }\\n\\n      &.rounded {\\n        border-radius: 50%;\\n      }\\n    }\\n  }\\n\\n  // group bio\\n  .second-row {\\n    max-height: 150px;\\n    overflow: auto;\\n\\n    .bio {\\n      a:not(.mention) {\\n        color: var(--tertiary);\\n      }\\n\\n      img {\\n        max-width: 100%;\\n        height: auto;\\n      }\\n\\n      .overflow {\\n        max-height: 60px;\\n        overflow: hidden;\\n      }\\n    }\\n  }\\n}\\n\\n@include viewport.until(sm) {\\n  .card-cloak {\\n    position: fixed;\\n    top: 0;\\n    left: 0;\\n    z-index: z(\\"mobile-composer\\") + 1; // 1101\\n    height: 100vh;\\n    width: 100vw;\\n    background-color: #000;\\n    opacity: 0;\\n    visibility: hidden;\\n    transition:\\n      opacity 0.3s,\\n      visibility 0s 0.3s;\\n\\n    &.--visible {\\n      pointer-events: all;\\n      opacity: 0.6;\\n      visibility: visible;\\n      transition:\\n        opacity 0.3s,\\n        visibility 0s;\\n    }\\n\\n    @media (prefers-reduced-motion) {\\n      transition-duration: 0s;\\n    }\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n// shared card layout lives in user-card.scss\\n.category-card {\\n  &__avatar {\\n    display: flex;\\n    flex: 0 0 auto;\\n    width: var(--avatar-width);\\n    height: var(--avatar-width);\\n    margin-top: var(--avatar-margin);\\n    border-radius: var(--d-border-radius);\\n    overflow: hidden;\\n\\n    .category-logo.aspect-image {\\n      width: 100%;\\n      height: 100%;\\n      margin: 0;\\n\\n      img {\\n        width: 100%;\\n        height: 100%;\\n        object-fit: contain;\\n      }\\n    }\\n  }\\n\\n  .first-row .names {\\n    // the avatar only renders for uploaded logos\\n    &:first-child {\\n      padding-left: 0;\\n\\n      // without the avatar, the zero flex-basis lets the controls share this line and squeeze the name out\\n      @include viewport.until(sm) {\\n        flex-basis: 100%;\\n      }\\n    }\\n\\n    .category-card__link {\\n      display: flex;\\n      align-items: center;\\n      gap: 0.25em;\\n    }\\n\\n    .category-card__ancestors {\\n      display: flex;\\n      gap: var(--space-2);\\n      font-size: var(--font-down-1);\\n\\n      .category-card__link {\\n        color: var(--primary-high);\\n      }\\n    }\\n\\n    .category-card__name {\\n      min-width: 0;\\n\\n      @include ellipsis;\\n    }\\n\\n    .category-card__style {\\n      display: flex;\\n      flex: 0 0 auto;\\n\\n      &.--style-square {\\n        width: var(--category-badge-size);\\n        height: var(--category-badge-size);\\n        border-radius: var(--category-badge-border-radius);\\n        background: var(--category-badge-color);\\n      }\\n\\n      .d-icon,\\n      .emoji {\\n        width: var(--category-badge-size);\\n        height: var(--category-badge-size);\\n        margin: 0;\\n        font-size: inherit;\\n        color: var(--category-badge-color);\\n      }\\n    }\\n  }\\n\\n  &__edit-description {\\n    display: inline-flex;\\n    align-items: center;\\n    gap: var(--space-half);\\n    font-size: var(--font-down-1);\\n\\n    .d-icon {\\n      font-size: var(--font-down-1);\\n    }\\n\\n    .bio + & {\\n      margin-top: var(--space-1);\\n    }\\n  }\\n\\n  .card-content {\\n    .category-card__latest {\\n      margin-top: var(--space-3);\\n    }\\n  }\\n\\n  &__latest-title {\\n    margin-bottom: var(--space-1);\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1);\\n  }\\n\\n  &__view-all {\\n    display: block;\\n    padding-top: var(--space-1);\\n    border-top: 1px solid var(--content-border-color);\\n    font-size: var(--font-down-1);\\n  }\\n\\n  &__topics {\\n    display: flex;\\n    flex-direction: column;\\n\\n    @include unstyled-list;\\n  }\\n\\n  &__topics .featured-topic {\\n    display: flex;\\n    align-items: baseline;\\n    min-width: 0;\\n    padding-block: var(--space-1);\\n    border-top: 1px solid var(--content-border-color);\\n\\n    .title {\\n      min-width: 0;\\n      color: var(--primary);\\n\\n      @include ellipsis;\\n    }\\n\\n    .topic-statuses {\\n      display: flex;\\n    }\\n\\n    button.-trigger {\\n      padding: 0;\\n      border: none;\\n      background: transparent;\\n    }\\n\\n    .last-posted-at {\\n      flex: 0 0 auto;\\n      margin-inline-start: auto;\\n      padding-inline-start: var(--space-2);\\n      color: var(--primary-medium);\\n      font-size: var(--font-down-1);\\n    }\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n// Common styles for \\"user-info\\" component\\n.user-info {\\n  display: flex;\\n  gap: 1em;\\n  margin-bottom: 0.75rem;\\n\\n  .user-image-inner {\\n    position: relative;\\n    display: inline-block;\\n  }\\n\\n  .user-detail {\\n    min-width: 0;\\n\\n    @include viewport.until(sm) {\\n      font-size: var(--font-down-1);\\n    }\\n\\n    .name-line {\\n      display: flex;\\n      flex-wrap: wrap;\\n      gap: 0 0.5em;\\n\\n      a {\\n        color: var(--primary-high);\\n      }\\n\\n      .username-wrapper {\\n        display: flex;\\n        align-items: baseline;\\n        gap: 0.35em;\\n\\n        .username {\\n          font-weight: bold;\\n\\n          @include ellipsis;\\n        }\\n      }\\n\\n      .name-wrapper {\\n        @include ellipsis;\\n        min-width: 0;\\n      }\\n\\n      // When name should appear first (site setting)\\n      &--name-first:not(&--show-status) {\\n        .username-wrapper {\\n          order: 1;\\n        }\\n\\n        .name-wrapper .name {\\n          font-weight: bold;\\n        }\\n\\n        .username-wrapper .username {\\n          font-weight: normal;\\n        }\\n      }\\n\\n      // When showing status: username+status on first line, name on second\\n      &--show-status {\\n        .username-wrapper {\\n          width: 100%;\\n        }\\n\\n        .name-wrapper {\\n          width: 100%;\\n        }\\n      }\\n    }\\n\\n    .details {\\n      color: var(--primary);\\n\\n      .d-icon-reply {\\n        color: var(--primary-medium);\\n      }\\n    }\\n\\n    .title {\\n      color: var(--primary-medium);\\n\\n      @include ellipsis;\\n    }\\n  }\\n\\n  &.medium {\\n    min-height: 60px;\\n\\n    @include viewport.from(sm) {\\n      display: flex;\\n\\n      .user-image {\\n        width: 55px;\\n        margin-right: 0;\\n      }\\n    }\\n\\n    .username,\\n    .name {\\n      display: block;\\n    }\\n\\n    .margin a {\\n      margin-left: 0;\\n    }\\n\\n    &.badge-info {\\n      min-height: 80px;\\n      min-width: 250px;\\n\\n      .granted-on {\\n        color: var(--primary-med-or-secondary-med);\\n      }\\n\\n      .post-link {\\n        display: block;\\n        margin-top: 0.2em;\\n      }\\n    }\\n  }\\n}\\n",".user-status-message {\\n  .fk-d-tooltip__trigger-container {\\n    align-items: center;\\n  }\\n\\n  .user-status-message-description {\\n    margin-left: 0.35em;\\n  }\\n}\\n\\n[data-content][data-identifier=\\"user-status-message-tooltip\\"] {\\n  .fk-d-tooltip__inner-content {\\n    gap: 0.65em;\\n  }\\n\\n  .emoji {\\n    width: 1em;\\n    height: 1em;\\n  }\\n\\n  .user-status-message-description {\\n    color: var(--primary-800);\\n  }\\n\\n  .user-status-tooltip-until {\\n    color: var(--primary-medium);\\n    white-space: nowrap;\\n    margin-left: 0.15em;\\n  }\\n}\\n",".user-status-picker-wrap {\\n  display: inline-flex;\\n  width: 100%;\\n  align-items: end;\\n\\n  .user-status-picker {\\n    display: flex;\\n    width: 100%;\\n    border: 1px solid var(--primary-medium);\\n\\n    .emoji-picker-trigger {\\n      margin: 3px;\\n      width: 38px;\\n      height: 38px;\\n      text-align: center;\\n    }\\n\\n    .user-status-description {\\n      width: 100%;\\n      margin-bottom: 0;\\n      border: none;\\n      outline: none;\\n      padding-left: 0;\\n    }\\n  }\\n\\n  .user-status-picker.focused {\\n    border: 1px solid var(--tertiary);\\n    outline: 1px solid var(--tertiary);\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.user-stream {\\n  // DEPRECATED:\\n  // The \\".item\\" class should be removed because it's too generic.\\n  // Once \\".item\\" has been removed, \\".user-stream-item\\" can replace\\n  // \\".user-stream\\" as the top-level selector on this file as all other\\n  // selectors below are its children\\n  .item,\\n  .user-stream-item {\\n    background: var(--d-content-background, var(--secondary));\\n    border-bottom: 1px solid var(--content-border-color);\\n    padding: 1em 0.53em;\\n    list-style: none;\\n\\n    &.moderator-action {\\n      background-color: var(--highlight-bg);\\n    }\\n\\n    &.deleted {\\n      background-color: var(--danger-low-mid);\\n    }\\n\\n    &.hidden {\\n      display: block;\\n      opacity: 0.4;\\n    }\\n\\n    .post-list-item__header,\\n    .user-stream-item__header {\\n      display: flex;\\n      align-items: flex-start;\\n    }\\n\\n    .post-list-item__details,\\n    .user-stream-item__details {\\n      flex-grow: 1;\\n      min-width: 0;\\n      margin-right: var(--space-2);\\n\\n      .badge-category__wrapper {\\n        width: auto;\\n        max-width: 100%;\\n      }\\n    }\\n\\n    .post-list-item__metadata,\\n    .user-stream-item__metadata {\\n      display: flex;\\n      align-items: center;\\n      justify-content: flex-start;\\n      flex-wrap: wrap;\\n      gap: 0 0.5em;\\n\\n      .category {\\n        overflow: hidden;\\n      }\\n\\n      span + span {\\n        &::before {\\n          content: \\"•\\";\\n          color: var(--primary-medium);\\n        }\\n      }\\n    }\\n  }\\n\\n  .draft-icon {\\n    color: var(--primary-high);\\n    font-size: var(--font-up-4);\\n    margin-right: 0.5rem;\\n    text-align: center;\\n\\n    @include viewport.from(sm) {\\n      width: 3rem;\\n    }\\n  }\\n\\n  .stream-topic-title {\\n    overflow-wrap: anywhere;\\n  }\\n\\n  .draft-title {\\n    color: var(--tertiary);\\n    padding: 0;\\n  }\\n\\n  .user-stream-item__metadata ul {\\n    display: inline-block;\\n    margin: 0;\\n    padding: 0;\\n    color: var(--primary-medium);\\n\\n    li {\\n      display: inline-flex;\\n      margin-left: 0.5em;\\n    }\\n  }\\n\\n  .type,\\n  span.name {\\n    color: var(--primary);\\n  }\\n\\n  .relative-date,\\n  .delete-info,\\n  .draft-type {\\n    line-height: var(--line-height-small);\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-2);\\n    padding-top: unset !important;\\n    margin-right: 0.5rem;\\n  }\\n\\n  .delete-info {\\n    align-items: center;\\n    display: flex;\\n\\n    .d-icon {\\n      font-size: var(--font-0);\\n      margin-right: 0.5rem;\\n    }\\n\\n    .avatar {\\n      margin-right: 0.25rem;\\n    }\\n  }\\n\\n  .user-notifications-list {\\n    padding-top: 0;\\n\\n    li.notification {\\n      padding: var(--space-3);\\n      border-bottom: 1px solid var(--content-border-color);\\n\\n      a {\\n        align-items: center;\\n      }\\n\\n      .d-icon {\\n        color: var(--primary-medium);\\n        padding-top: 0;\\n        font-size: var(--font-up-2);\\n      }\\n\\n      .relative-date {\\n        margin-left: auto;\\n        padding-top: 0;\\n        float: none;\\n      }\\n    }\\n  }\\n\\n  .expand-item,\\n  .collapse-item {\\n    margin-right: 0.5em;\\n    margin-left: 0.25em;\\n    line-height: var(--line-height-small);\\n    padding-top: 3px;\\n    color: var(--primary-medium);\\n  }\\n\\n  .avatar-link {\\n    margin-right: 0.5em;\\n  }\\n\\n  .name {\\n    font-size: var(--font-0);\\n    max-width: 400px;\\n\\n    @include ellipsis;\\n\\n    @include viewport.until(sm) {\\n      vertical-align: middle;\\n    }\\n  }\\n\\n  .edit-reason {\\n    background-color: var(--highlight-bg);\\n    padding: 3px 5px 5px 5px;\\n  }\\n\\n  .excerpt {\\n    margin: 1em 0 0 0;\\n    font-size: var(--font-0);\\n    overflow-wrap: break-word;\\n    color: var(--primary);\\n\\n    &:empty {\\n      display: none;\\n    }\\n\\n    details.disabled {\\n      color: var(--primary-medium);\\n    }\\n\\n    .emoji.only-emoji {\\n      // oversized emoji break excerpt layout\\n      // so we match inline emoji size\\n      width: 20px;\\n      height: 20px;\\n      margin: 0;\\n    }\\n  }\\n\\n  @include viewport.from(sm) {\\n    .user-stream-item .excerpt,\\n    .user-stream-item-actions {\\n      margin: 0.75em 0 0 3.5em;\\n    }\\n  }\\n\\n  .group-member-info {\\n    display: flex;\\n\\n    @include viewport.until(sm) {\\n      .name {\\n        vertical-align: inherit;\\n      }\\n    }\\n  }\\n\\n  .user-stream-item .user-stream-item-draft-actions {\\n    display: flex;\\n    align-items: end;\\n    flex-direction: row;\\n    gap: 0.75em;\\n  }\\n}\\n\\n.user-stream .child-actions, /* DEPRECATED: '.user-stream .child-actions' selector*/\\n.user-stream-item-actions,\\n.user-stream-item-draft-actions {\\n  margin-top: 8px;\\n\\n  .avatar-link {\\n    float: none;\\n    margin-right: 3px;\\n  }\\n\\n  .fa {\\n    width: 15px;\\n    display: inline-block;\\n    color: var(--primary);\\n\\n    &.d-icon-heart {\\n      color: var(--love);\\n    }\\n\\n    &.d-icon-trash-can {\\n      color: var(--secondary);\\n    }\\n  }\\n}\\n",".user-stream {\\n  margin: 0;\\n\\n  &.filter-deleted {\\n    grid-column-start: 1;\\n    grid-column-end: 3;\\n    grid-row-start: 2;\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.post-list {\\n  margin: 0;\\n\\n  &--bulk-select {\\n    .post-list-item {\\n      &--selected {\\n        background: var(--d-selected);\\n        border-left: 3px solid var(--tertiary);\\n      }\\n\\n      &__bulk-select {\\n        margin-right: 0.75rem;\\n        align-self: flex-start;\\n        margin-top: 0.2rem;\\n\\n        .bulk-select-checkbox {\\n          margin: 0;\\n        }\\n      }\\n    }\\n  }\\n\\n  .post-list-item {\\n    background: var(--d-content-background, var(--secondary));\\n    border-bottom: 1px solid var(--content-border-color);\\n    padding: 1em 0.53em;\\n    list-style: none;\\n\\n    &.moderator-action {\\n      background-color: var(--highlight-bg);\\n    }\\n\\n    &.deleted {\\n      background-color: var(--danger-low-mid);\\n    }\\n\\n