ems: center;\\n    gap: 0.5rem;\\n    flex-wrap: wrap;\\n\\n    .btn {\\n      margin: 0;\\n    }\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.login-welcome-header {\\n  box-sizing: border-box;\\n  display: grid;\\n  grid-template-columns: auto 1fr;\\n  grid-template-rows: auto 1fr;\\n  overflow-wrap: anywhere;\\n\\n  .login-title {\\n    font-size: var(--font-up-5);\\n    margin: 0;\\n    line-height: var(--line-height-medium);\\n\\n    @include viewport.from(sm) {\\n      font-size: var(--font-up-6);\\n    }\\n  }\\n\\n  .login-subheader {\\n    font-size: var(--font-0);\\n    margin: 0;\\n\\n    @include viewport.from(sm) {\\n      font-size: var(--font-up-1);\\n    }\\n  }\\n\\n  .waving-hand {\\n    width: 30px;\\n    height: 30px;\\n    margin-left: 0.5em;\\n    align-self: center;\\n\\n    @include viewport.from(sm) {\\n      .waving-hand {\\n        width: 35px;\\n        height: 35px;\\n      }\\n    }\\n  }\\n}\\n",".pinned-options-btn,\\n.notifications-tracking-btn,\\n.composer-actions-btn,\\n.composer-toggle-item {\\n  display: flex;\\n  flex: 1 0 auto;\\n  box-sizing: border-box;\\n  align-items: center;\\n\\n  &__icons {\\n    display: flex;\\n    align-self: flex-start;\\n  }\\n\\n  &__texts {\\n    line-height: var(--line-height-medium);\\n    flex: 1 1 0%;\\n    align-items: flex-start;\\n    display: flex;\\n    flex-wrap: wrap;\\n    flex-direction: column;\\n  }\\n\\n  &__label {\\n    flex: 1 1 auto;\\n    font-weight: bold;\\n    font-size: var(--font-0);\\n    color: var(--primary);\\n    max-width: 100%;\\n\\n    @include ellipsis;\\n  }\\n\\n  &__description {\\n    flex: 1 1 auto;\\n    font-size: var(--font-down-1);\\n    color: var(--primary-medium);\\n    white-space: normal;\\n    text-align: left;\\n  }\\n}\\n\\n.topic-timeline-notifications-tracking-content {\\n  z-index: z(\\"fullscreen\\") + 1;\\n}\\n","@use \\"lib/viewport\\";\\n\\n.fk-d-menu[data-content][data-identifier=\\"emoji-picker\\"] {\\n  z-index: z(\\"modal\\", \\"dialog\\");\\n\\n  .emoji-picker {\\n    max-width: 95vw;\\n  }\\n}\\n\\n.fk-d-menu-modal {\\n  .emoji-picker {\\n    max-width: 100vw;\\n  }\\n}\\n\\n.emoji-picker-trigger {\\n  gap: var(--space-1);\\n\\n  .d-icon + .d-button-label {\\n    margin-left: 0.25em;\\n  }\\n\\n  .d-icon.emoji-picker__caret {\\n    font-size: var(--font-down-2);\\n    margin-left: 0;\\n  }\\n}\\n\\n.emoji-picker {\\n  display: flex;\\n  flex-direction: column;\\n  height: 300px;\\n  width: 500px;\\n\\n  @include viewport.until(sm) {\\n    height: auto;\\n  }\\n\\n  .spinner-container {\\n    height: 100%;\\n    width: 100%;\\n  }\\n\\n  &__diversity-menu.fk-d-menu {\\n    z-index: z(\\"modal\\", \\"dialog\\");\\n\\n    .dropdown-menu {\\n      min-width: auto;\\n    }\\n  }\\n\\n  .emoji {\\n    padding: 6px;\\n    width: 24px;\\n    height: 24px;\\n    image-rendering: -webkit-optimize-contrast;\\n    cursor: pointer;\\n\\n    &:hover,\\n    &:focus {\\n      background: var(--primary-very-low);\\n      border-radius: var(--d-border-radius);\\n      transform: scale(1.25);\\n    }\\n  }\\n\\n  &__filter-container {\\n    background: var(--primary-very-low);\\n    display: flex;\\n    height: 50px;\\n\\n    @include viewport.until(sm) {\\n      padding-top: 0.25rem;\\n    }\\n  }\\n\\n  &__filter {\\n    width: 100%;\\n    margin: 0.5rem;\\n    border-radius: var(--d-border-radius);\\n    box-sizing: border-box;\\n\\n    input {\\n      background-color: transparent !important;\\n      width: 100%;\\n    }\\n\\n    .d-icon {\\n      color: var(--primary-medium);\\n    }\\n\\n    &.filter-input-container {\\n      border-color: transparent;\\n      background: var(--secondary);\\n    }\\n  }\\n\\n  &__content {\\n    display: flex;\\n    flex-direction: row;\\n    height: 250px;\\n\\n    @include viewport.until(sm) {\\n      flex-direction: column;\\n      padding-top: 1em;\\n      box-sizing: border-box;\\n    }\\n  }\\n\\n  &__scrollable-content {\\n    width: 100%;\\n    overflow-y: scroll;\\n    overscroll-behavior: contain;\\n    height: 100%;\\n  }\\n\\n  &__no-results {\\n    margin: 0;\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    flex-direction: column;\\n    font-weight: 700;\\n    padding: 2em;\\n  }\\n\\n  &__sections-nav-wrap {\\n    --fade-color: var(--primary-low);\\n    background: var(--primary-low);\\n    flex: 0 0 auto;\\n\\n    @include viewport.until(sm) {\\n      order: 1;\\n      width: 100%;\\n    }\\n  }\\n\\n  &__sections-nav {\\n    display: flex;\\n    flex-direction: column;\\n    min-width: 40px;\\n    overflow-y: auto;\\n    overflow-x: hidden;\\n    height: 250px;\\n    overscroll-behavior: contain;\\n\\n    @include viewport.until(sm) {\\n      height: 50px;\\n      width: 100%;\\n      flex-direction: row;\\n      display: flex;\\n      box-sizing: border-box;\\n      overflow-y: hidden;\\n      overflow-x: auto;\\n    }\\n  }\\n\\n  &__section-btn {\\n    padding: 0.25rem;\\n\\n    &:hover {\\n      .emoji {\\n        background: none;\\n      }\\n    }\\n\\n    &:focus,\\n    &.active {\\n      background: none;\\n    }\\n\\n    &.active {\\n      scale: 1.4;\\n    }\\n\\n    .emoji {\\n      width: 21px;\\n      height: 21px;\\n    }\\n  }\\n\\n  &__section-emojis,\\n  &__section.filtered {\\n    padding: 0.5rem;\\n  }\\n\\n  &__backdrop {\\n    height: 100%;\\n    background: rgb(0, 0, 0, 0.75);\\n    bottom: 0;\\n    top: 0;\\n    left: 0;\\n    right: 0;\\n  }\\n\\n  &__section-title-container {\\n    display: flex;\\n    position: sticky;\\n    top: -1px; // to avoid an ugly sub 1px gap on retina\\n    background: rgb(var(--secondary-rgb), 0.95);\\n    z-index: 2;\\n  }\\n\\n  &__section-title {\\n    margin: 0;\\n    padding: 0.5rem;\\n    color: var(--primary-high);\\n    font-size: var(--font-down-2);\\n    font-weight: 700;\\n    width: 100%;\\n    box-sizing: border-box;\\n    text-transform: uppercase;\\n  }\\n\\n  &__fitzpatrick-modifier-btn {\\n    min-width: 21px;\\n    width: 21px;\\n    height: 21px;\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    padding: 0;\\n    background: none;\\n    margin-right: 0.5rem;\\n    border: 0;\\n    border-radius: var(--d-border-radius);\\n\\n    .d-icon {\\n      visibility: hidden;\\n    }\\n\\n    &.current {\\n      min-width: 25px;\\n      width: 25px;\\n      height: 25px;\\n    }\\n\\n    &:not(.current):hover,\\n    &:not(.current):focus {\\n      .d-icon {\\n        visibility: visible;\\n        color: white;\\n        filter: drop-shadow(0.5px 1.5px 0 rgb(0, 0, 0, 0.3));\\n      }\\n    }\\n\\n    &:last-child {\\n      margin-right: 0;\\n    }\\n\\n    &.t1 {\\n      background: #ffcc4d;\\n    }\\n\\n    &.t2 {\\n      background: #f7dece;\\n    }\\n\\n    &.t3 {\\n      background: #f3d2a2;\\n    }\\n\\n    &.t4 {\\n      background: #d5ab88;\\n    }\\n\\n    &.t5 {\\n      background: #af7e57;\\n    }\\n\\n    &.t6 {\\n      background: #7c533e;\\n    }\\n\\n    @media (forced-colors: active) {\\n      forced-color-adjust: none;\\n    }\\n  }\\n\\n  &__fitzpatrick-scale {\\n    display: flex;\\n    align-items: center;\\n  }\\n}\\n\\n@include viewport.until(sm) {\\n  .fk-d-menu-modal.emoji-picker-content {\\n    // specificity is important for the styles in this container\\n    html:not(.keyboard-visible.mobile-view) & .d-modal__container {\\n      height: calc(var(--composer-vh, 1dvh) * 100);\\n      max-height: 100%;\\n\\n      .emoji-picker__content {\\n        height: calc(\\n          var(--composer-vh, 1dvh) * 100 - 50px - env(safe-area-inset-bottom)\\n        );\\n      }\\n    }\\n\\n    html.keyboard-visible.mobile-view & .d-modal__container {\\n      .emoji-picker__content {\\n        height: calc(var(--composer-vh, 1dvh) * 100 - 50px);\\n      }\\n    }\\n\\n    .d-modal__body {\\n      padding: 0;\\n    }\\n\\n    .d-modal__container {\\n      align-self: flex-start;\\n    }\\n\\n    .emoji-picker__close-btn {\\n      margin-left: 0.25em;\\n      padding-left: 0.75em;\\n    }\\n  }\\n}\\n",".gifs-modal {\\n  .d-modal__container {\\n    --modal-max-width: 920px;\\n  }\\n\\n  &__input {\\n    position: relative;\\n\\n    > input[type=\\"text\\"] {\\n      width: 100%;\\n      margin-bottom: 0;\\n    }\\n  }\\n\\n  &__input-spinner {\\n    position: absolute;\\n    right: 1.2em;\\n    inset-block: 0;\\n    display: flex;\\n    align-items: center;\\n  }\\n\\n  &__content {\\n    min-width: 320px;\\n    max-height: 65vh;\\n    margin-top: 0.5em;\\n    flex-shrink: 0;\\n\\n    @media screen and (width >= 768px) {\\n      min-width: 650px;\\n    }\\n\\n    @media screen and (width >= 1200px) {\\n      min-width: 850px;\\n    }\\n  }\\n\\n  &__box {\\n    .gifs-result-list {\\n      position: relative;\\n\\n      .gifs-result {\\n        position: absolute;\\n      }\\n    }\\n\\n    div.loading-container {\\n      display: block;\\n      height: 10px;\\n    }\\n  }\\n\\n  &__categories-header {\\n    margin: 0.5em 0;\\n    font-size: var(--font-0);\\n    color: var(--primary-medium);\\n    font-weight: normal;\\n  }\\n\\n  &__loading {\\n    display: flex;\\n    flex: 1;\\n    justify-content: center;\\n    align-items: center;\\n  }\\n\\n  &__no-results {\\n    padding: 3em 1em;\\n    font-size: var(--font-up-2);\\n    color: var(--primary-low-mid);\\n    background: var(--primary-very-low);\\n    font-weight: bold;\\n    text-align: center;\\n  }\\n\\n  .d-modal__body {\\n    display: flex;\\n    flex-direction: column;\\n    overflow-x: hidden;\\n    height: 65vh;\\n  }\\n\\n  .d-modal__footer {\\n    display: flex;\\n    flex-flow: row-reverse;\\n  }\\n\\n  &__branding {\\n    height: 30px;\\n  }\\n}\\n\\n.gifs-result {\\n  &__img {\\n    width: 100%;\\n    height: auto;\\n    cursor: pointer;\\n  }\\n\\n  &--category {\\n    .gifs-result__img {\\n      object-fit: cover;\\n    }\\n  }\\n\\n  &__category-label {\\n    position: absolute;\\n    bottom: 0;\\n    left: 0;\\n    right: 0;\\n    padding: 0.5em;\\n    background: linear-gradient(transparent, rgb(0, 0, 0, 0.7));\\n    color: white;\\n    font-weight: bold;\\n    font-size: var(--font-down-1);\\n    text-align: center;\\n    cursor: pointer;\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n// Custom properties for the grid layout, set on the DMenu/modal container.\\n// The DMenu identifier generates `.fk-d-menu.d-icon-grid-picker-content`\\n// which doesn't follow the BEM `__` pattern, so it stays outside the block.\\n.fk-d-menu.d-icon-grid-picker-content,\\n.fk-d-menu-modal.d-icon-grid-picker-content {\\n  z-index: z(\\"modal\\", \\"dialog\\");\\n\\n  --icon-grid-columns: 12;\\n  --icon-grid-cell: 36px;\\n  --icon-grid-gap: 2px;\\n  --icon-grid-h-padding: 0.5rem;\\n}\\n\\n.d-icon-grid-picker {\\n  /* Apply icon color to the trigger icon when --icon-color is set */\\n  .fk-d-menu__trigger > .d-icon:not(.d-icon-grid-picker__caret) {\\n    color: var(--icon-color, currentColor);\\n  }\\n\\n  .d-icon-grid-picker-trigger {\\n    gap: var(--space-1);\\n  }\\n\\n  /* Split-button layout: DMenu trigger + clear button side by side */\\n  &.--has-clear {\\n    display: inline-flex;\\n\\n    .fk-d-menu__trigger {\\n      border-top-right-radius: 0;\\n      border-bottom-right-radius: 0;\\n      border-right-color: transparent;\\n    }\\n\\n    .d-icon-grid-picker__clear {\\n      border-top-left-radius: 0;\\n      border-bottom-left-radius: 0;\\n      border-left-color: transparent;\\n      margin-left: 0.1em;\\n      padding: 0.25em;\\n      min-width: 0;\\n\\n      .d-icon {\\n        font-size: var(--font-down-2);\\n      }\\n    }\\n  }\\n\\n  &__caret {\\n    font-size: var(--font-down-2);\\n  }\\n\\n  &__content {\\n    display: flex;\\n    flex-direction: column;\\n    width: calc(\\n      var(--icon-grid-columns) * var(--icon-grid-cell) +\\n        (var(--icon-grid-columns) - 1) * var(--icon-grid-gap) +\\n        var(--icon-grid-h-padding) * 2 + 8px\\n    );\\n    max-height: 380px;\\n  }\\n\\n  // Mirrors emoji-picker__filter-container\\n  &__filter-container {\\n    background: var(--primary-very-low);\\n    display: flex;\\n    height: 50px;\\n  }\\n\\n  // Mirrors emoji-picker__filter\\n  &__filter {\\n    width: 100%;\\n    margin: 0.5rem;\\n    border-radius: var(--d-border-radius);\\n    box-sizing: border-box;\\n\\n    input {\\n      background-color: transparent !important;\\n      width: 100%;\\n    }\\n\\n    .d-icon {\\n      color: var(--primary-medium);\\n    }\\n\\n    &.filter-input-container {\\n      border-color: transparent;\\n      background: var(--secondary);\\n    }\\n  }\\n\\n  // Parent grid that both favorites and icon grid share\\n  &__grid-wrapper {\\n    display: grid;\\n    grid-template-columns: repeat(\\n      var(--icon-grid-columns),\\n      var(--icon-grid-cell)\\n    );\\n    gap: var(--icon-grid-gap);\\n    padding: var(--icon-grid-h-padding);\\n    overflow-x: hidden;\\n    overflow-y: auto;\\n    max-height: 300px;\\n    scrollbar-width: thin;\\n    box-sizing: border-box;\\n  }\\n\\n  &__sentinel {\\n    grid-column: 1 / -1;\\n  }\\n\\n  // Favorites row inherits parent columns via subgrid\\n  &__favorites {\\n    display: grid;\\n    grid-template-columns: subgrid;\\n    grid-column: 1 / -1;\\n    padding-bottom: 0.25rem;\\n  }\\n\\n  &__selected-name {\\n    font-size: var(--font-down-1);\\n    white-space: nowrap;\\n    padding-left: 0.3em;\\n    padding-right: 0.5em;\\n  }\\n\\n  // Main icon grid inherits parent columns via subgrid\\n  &__grid {\\n    display: grid;\\n    grid-template-columns: subgrid;\\n    grid-column: 1 / -1;\\n  }\\n\\n  &__icon {\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    width: var(--icon-grid-cell);\\n    height: var(--icon-grid-cell);\\n    cursor: pointer;\\n    color: var(--icon-color, var(--primary-high));\\n    border: none;\\n    background: none;\\n    padding: 0;\\n    font: inherit;\\n\\n    @media (prefers-reduced-motion: no-preference) {\\n      transition: transform 0.15s ease;\\n    }\\n\\n    &:hover,\\n    &:focus {\\n      background: var(--primary-very-low);\\n      border-radius: var(--d-border-radius);\\n\\n      @media (prefers-reduced-motion: no-preference) {\\n        transform: scale(1.25);\\n      }\\n    }\\n\\n    &.--selected {\\n      background: var(--tertiary-low);\\n      color: var(--tertiary);\\n      border-radius: var(--d-border-radius);\\n    }\\n\\n    // Inner grid so the chip icon aligns with the first grid column\\n    &.d-icon-grid-picker__selected-chip {\\n      display: grid;\\n      grid-template-columns: var(--icon-grid-cell) 1fr;\\n      align-items: center;\\n      text-align: left;\\n      padding: 0;\\n\\n      // The chip spans multiple columns, so transform: scale() on the\\n      // whole element would overlap neighbouring cells without triggering\\n      // a grid reflow. Scale only the inner icon instead.\\n      &:hover,\\n      &:focus {\\n        transform: none;\\n\\n        @media (prefers-reduced-motion: no-preference) {\\n          .d-icon {\\n            transform: scale(1.25);\\n          }\\n        }\\n      }\\n\\n      .d-icon {\\n        justify-self: center;\\n\\n        @media (prefers-reduced-motion: no-preference) {\\n          transition: transform 0.15s ease;\\n        }\\n      }\\n    }\\n\\n    .d-icon {\\n      font-size: var(--font-up-2);\\n    }\\n  }\\n\\n  &__loading {\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    min-height: 150px;\\n    grid-column: 1 / -1;\\n  }\\n\\n  &__empty {\\n    padding: 1em;\\n    text-align: center;\\n    color: var(--primary-medium);\\n    grid-column: 1 / -1;\\n  }\\n\\n  &__loading-more {\\n    display: flex;\\n    justify-content: center;\\n    padding: 0.5em;\\n    grid-column: 1 / -1;\\n  }\\n}\\n\\n// Mobile overrides\\n@include viewport.until(md) {\\n  .fk-d-menu-modal.d-icon-grid-picker-content {\\n    .d-modal__body {\\n      padding: 0;\\n    }\\n\\n    .d-icon-grid-picker {\\n      &__content {\\n        width: 100%;\\n      }\\n\\n      &__filter-container {\\n        width: 100%;\\n      }\\n\\n      &__grid-wrapper {\\n        width: 100%;\\n        grid-template-columns: repeat(auto-fill, var(--icon-grid-cell));\\n        justify-content: center;\\n        max-height: calc(\\n          var(--composer-vh, 1dvh) * 100 - 50px - env(safe-area-inset-bottom)\\n        );\\n      }\\n    }\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.filter-input-container {\\n  display: flex;\\n  align-items: center;\\n  justify-content: space-between;\\n  border: var(--d-input-border);\\n  border-radius: var(--d-input-border-radius);\\n  background-color: var(--token-color-background-input);\\n  box-sizing: border-box;\\n\\n  &.is-focused {\\n    @include default-focus;\\n  }\\n\\n  .filter-input,\\n  .filter-input:focus {\\n    width: 100%;\\n    margin: 0;\\n    border: none;\\n    outline: none;\\n\\n    @include viewport.from(md) {\\n      .chat-browse-view__actions & {\\n        width: 210px;\\n      }\\n    }\\n  }\\n\\n  .d-icon {\\n    color: var(--primary-medium);\\n    margin: 0 0.5rem;\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.fk-d-menu[data-identifier=\\"filter-navigation-menu-list\\"] {\\n  max-height: 300px;\\n\\n  @include viewport.until(md) {\\n    text-size-adjust: 100%;\\n  }\\n\\n  .fk-d-menu__inner-content,\\n  .dropdown-menu {\\n    width: 100%;\\n  }\\n}\\n\\n.filter-navigation {\\n  &__tip-item {\\n    padding: var(--space-2) var(--space-4);\\n    cursor: pointer;\\n    color: var(--primary);\\n    transition: background-color 0.15s;\\n\\n    &:hover,\\n    &.--selected {\\n      background-color: var(--d-hover);\\n    }\\n  }\\n\\n  &__tip-name {\\n    font-weight: 600;\\n    color: var(--primary);\\n  }\\n\\n  &__tip-description {\\n    color: var(--primary-high);\\n  }\\n\\n  &__tip-item .badge-category__wrapper {\\n    font-size: var(--font-0);\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n@import \\"common/foundation/mixins\\";\\n\\n:root {\\n  --d-welcome-banner-text-alignment: center;\\n  --d-welcome-banner-header-size: var(--font-up-6);\\n  --d-welcome-banner-padding-top: var(--space-6);\\n  --d-welcome-banner-padding-right: 0;\\n  --d-welcome-banner-padding-bottom: var(--space-12);\\n  --d-welcome-banner-padding-left: 0;\\n  --d-welcome-banner-title-margin-bottom: var(--space-4);\\n}\\n\\n.display-welcome-banner {\\n  #main-outlet {\\n    padding-top: 0;\\n  }\\n}\\n\\n.welcome-banner--visible.header-search--enabled {\\n  .floating-search-input-wrapper {\\n    display: none;\\n  }\\n}\\n\\n.welcome-banner {\\n  border-radius: var(--d-border-radius-large);\\n\\n  @include viewport.until(sm) {\\n    display: none;\\n  }\\n\\n  &__wrap {\\n    box-sizing: border-box;\\n    position: relative;\\n    padding: var(--d-welcome-banner-padding-top)\\n      var(--d-welcome-banner-padding-right)\\n      var(--d-welcome-banner-padding-bottom);\\n\\n    .--with-bg-img & {\\n      --d-welcome-banner-padding-right: var(--space-4);\\n      --d-welcome-banner-padding-left: var(--space-4);\\n      border-radius: var(--d-border-radius);\\n      background-size: cover;\\n      background-position: center;\\n      background-repeat: no-repeat;\\n      margin-bottom: var(--space-2);\\n    }\\n\\n    @include viewport.until(md) {\\n      --d-welcome-banner-padding-top: var(--space-4);\\n      --d-welcome-banner-padding-right: 8px;\\n      --d-welcome-banner-padding-bottom: var(--space-5);\\n      margin-top: var(--space-2);\\n    }\\n\\n    @include viewport.until(sm) {\\n      margin-top: 0;\\n    }\\n\\n    .search-menu {\\n      display: flex;\\n      position: relative;\\n      margin-inline: auto;\\n      max-width: 600px;\\n\\n      .search-menu-container {\\n        width: 100%;\\n        min-width: 0;\\n      }\\n    }\\n\\n    .search-input {\\n      .search-term__input {\\n        min-width: 0;\\n        flex: 1 1;\\n      }\\n    }\\n\\n    .btn.search-icon {\\n      z-index: 2;\\n      background: transparent;\\n      line-height: 1;\\n      color: var(--primary-medium);\\n      height: 100%;\\n      position: absolute;\\n      left: calc(\\n        1rem - 0.65em\\n      ); // to align with result panel, minus padding of search icon btn\\n\\n      .rtl & {\\n        right: 0;\\n        left: unset;\\n      }\\n\\n      .discourse-no-touch & {\\n        &:hover {\\n          background: transparent;\\n          color: var(--primary);\\n\\n          .d-icon {\\n            color: currentcolor;\\n          }\\n        }\\n      }\\n\\n      + .search-menu-container .search-input {\\n        padding-left: var(--space-8);\\n\\n        .rtl & {\\n          padding-left: unset;\\n          padding-right: var(--space-8);\\n        }\\n      }\\n\\n      + .search-menu-container .search-input .search-context {\\n        margin-left: 4px;\\n      }\\n    }\\n\\n    .search-menu-container .results {\\n      @include d-animation(float-down, 0.25s, ease);\\n      box-sizing: border-box;\\n      border-radius: var(--d-border-radius);\\n      background: var(--secondary);\\n      z-index: 9;\\n      left: 0;\\n      top: 100%;\\n      right: 0;\\n      padding-top: 0;\\n\\n      @include viewport.until(sm) {\\n        width: 100%;\\n      }\\n\\n      .search-random-quick-tip {\\n        padding-top: var(--space-3);\\n      }\\n\\n      ul,\\n      ol {\\n        list-style-type: none;\\n        margin: 0;\\n      }\\n\\n      .no-results {\\n        padding-top: var(--space-3);\\n      }\\n    }\\n\\n    .search-link .d-icon {\\n      color: var(--primary-medium);\\n    }\\n\\n    span.keyword {\\n      color: var(--primary);\\n    }\\n  }\\n\\n  .search-menu-panel {\\n    // hacky but best guestimate we can do\\n    // 4em is roughly the input height\\n    --d-welcome-banner-height: calc(\\n      var(--font-up-6) + var(--d-welcome-banner-padding-top) +\\n        var(--d-welcome-banner-padding-bottom) +\\n        var(--d-welcome-banner-title-margin-bottom) + 4em\\n    );\\n    max-height: calc(\\n      100vh - var(--header-offset) - var(--d-welcome-banner-height)\\n    );\\n  }\\n}\\n\\n.welcome-banner__title {\\n  font-size: var(--font-up-6);\\n  line-height: var(--line-height-medium);\\n  font-family: var(--heading-font-family);\\n  font-weight: var(--heading-font-weight);\\n  margin-bottom: var(--d-welcome-banner-title-margin-bottom);\\n  text-align: var(--d-welcome-banner-text-alignment);\\n  margin-inline: auto;\\n  max-width: 70ch;\\n\\n  @include viewport.until(md) {\\n    font-size: var(--font-up-4);\\n  }\\n\\n  @include viewport.until(sm) {\\n    font-size: var(--font-up-1);\\n  }\\n}\\n\\n.welcome-banner__subheader {\\n  font-size: var(--font-up-1-rem);\\n  font-weight: normal;\\n  margin: 0;\\n  padding: 0.25rem 0;\\n}\\n\\n// hide search icon from default search menu\\n.search-menu.glimmer-search-menu .search-icon {\\n  display: none;\\n}\\n",".d-multi-select-trigger {\\n  @include form-item-sizing;\\n  display: inline-flex;\\n  border-radius: var(--d-input-border-radius);\\n  cursor: pointer;\\n  align-items: center;\\n  gap: 0.25em;\\n  line-height: normal;\\n  box-sizing: border-box;\\n  width: 200px;\\n  border: var(--d-input-border);\\n  justify-content: space-between;\\n\\n  &.-expanded {\\n    @include default-focus;\\n  }\\n}\\n\\n.d-multi-select-trigger__selection {\\n  display: flex;\\n  flex-wrap: wrap;\\n  gap: 0.25em;\\n  height: 100%;\\n}\\n\\n.d-multi-select-trigger__label {\\n  font-size: var(--font-0);\\n  line-height: normal;\\n  color: var(--primary-medium);\\n}\\n\\n.d-multi-select__search-no-result,\\n.d-multi-select__error {\\n  padding: 0.25em 0.5em;\\n}\\n\\n.d-multi-select__search-input {\\n  border: 0 !important;\\n  margin: 0 !important;\\n  outline: none !important;\\n  padding: 0 !important;\\n}\\n\\n.d-multi-select__search-container {\\n  display: flex;\\n  align-items: center;\\n  padding: 0.5em;\\n  gap: 0.5em;\\n\\n  .d-icon-magnifying-glass {\\n    color: var(-