n    .btn {\\n      align-self: end;\\n    }\\n  }\\n\\n  &__unwrap {\\n    margin-left: auto;\\n  }\\n}\\n\\n.permanently-delete-confirm-modal {\\n  .d-modal__footer .btn-danger {\\n    white-space: normal;\\n    text-align: left;\\n  }\\n\\n  &.--fire-easter-egg-modal {\\n    .d-modal__container {\\n      background-color: transparent;\\n      color: white;\\n\\n      .confirmation-phrase {\\n        z-index: 100000;\\n      }\\n    }\\n  }\\n\\n  &__message {\\n    margin-bottom: var(--space-4);\\n  }\\n\\n  &__instruction {\\n    display: flex;\\n    flex-direction: column;\\n    gap: 0.5em;\\n\\n    .confirmation-phrase {\\n      width: 100%;\\n      margin: 0;\\n    }\\n  }\\n\\n  --glitter: url(\\"/images/firenoise.png\\");\\n\\n  .fire-easter-egg::before,\\n  .fire-easter-egg::after {\\n    content: \\"\\";\\n    position: absolute;\\n    inset: 0;\\n  }\\n\\n  .fire-easter-egg::before {\\n    content: \\"\\";\\n    background-image:\\n      var(--glitter), var(--glitter),\\n      linear-gradient(\\n        0deg,\\n        white 0,\\n        #ff8951 5px,\\n        #dcbc169c 30%,\\n        transparent 70%\\n      ),\\n      radial-gradient(ellipse at bottom, transparent 30%, black 60%);\\n    background-size:\\n      350px 500px,\\n      400px 650px,\\n      100% 100%,\\n      100% 100%;\\n    background-blend-mode: hard-light, color-dodge, multiply;\\n    background-position:\\n      0 0,\\n      0 0,\\n      var(--gradientPos);\\n    background-repeat: repeat, repeat, repeat, no-repeat;\\n    mix-blend-mode: color-dodge;\\n    filter: brightness(3.7) blur(7px) contrast(6);\\n    animation: fire-easter-egg 1.75s linear infinite;\\n    box-shadow: inset 0 -40px 50px -60px #63bbc5;\\n  }\\n\\n  @keyframes fire-easter-egg {\\n    0% {\\n      background-position:\\n        center 0,\\n        center 0,\\n        50% 100%,\\n        center center;\\n    }\\n\\n    100% {\\n      background-position:\\n        center -500px,\\n        center -650px,\\n        50%