;\\n\\n    @include viewport.until(sm) {\\n      padding-top: var(--space-3);\\n      padding-bottom: var(--space-3);\\n    }\\n  }\\n\\n  &__sticky-header {\\n    position: sticky;\\n    top: 0;\\n    background: var(--secondary);\\n    z-index: z(\\"base\\");\\n  }\\n\\n  &__header {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-1);\\n    padding: var(--space-2) var(--space-4);\\n    overflow-x: auto;\\n    -webkit-overflow-scrolling: touch;\\n\\n    // signals that the row continues past its edges; the ramps sit over the\\n    // padding, so a row too short to scroll has nothing under them to fade\\n    mask-image: linear-gradient(\\n      to right,\\n      transparent 0,\\n      black var(--space-4),\\n      black calc(100% - var(--space-6)),\\n      transparent 100%\\n    );\\n\\n    @include viewport.from(sm) {\\n      padding: var(--space-2) var(--space-3);\\n      border-bottom: 1px solid var(--primary-low);\\n    }\\n\\n    &::-webkit-scrollbar {\\n      display: none;\\n    }\\n  }\\n\\n  &__filter {\\n    display: inline-flex;\\n    align-items: center;\\n    gap: var(--space-1);\\n    padding: var(--space-2) var(--space-3);\\n\\n    @include viewport.from(sm) {\\n      padding: var(--space-1) var(--space-2);\\n    }\\n    border: none;\\n    border-radius: var(--d-border-radius);\\n    background: transparent;\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1);\\n    cursor: pointer;\\n    white-space: nowrap;\\n    transition: background 0.15s;\\n\\n    .emoji {\\n      width: 1.15em;\\n      height: 1.15em;\\n\\n      @include viewport.until(sm) {\\n        width: 1.25em;\\n        height: 1.25em;\\n      }\\n    }\\n\\n    &:hover {\\n      .discourse-no-touch & {\\n        background: var(--primary-very-low);\\n      }\\n\\n      .discourse-touch & {\\n        background: transparent;\\n      }\\n    }\\n\\n    &.is-active {\\n      background: var(--tertiary-low);\\n      color: var(--primary);\\n    }\\n  }\\n\\n  &__body {\\n    overflow-y: auto;\\n\\n    @include viewport.from(sm) {\\n      overscroll-behavior: contain;\\n      height: auto;\\n      max-height: 320px;\\n    }\\n  }\\n\\n  &__item {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-3);\\n    padding: var(--space-2) var(--space-4);\\n\\n    @include viewport.from(sm) {\\n      padding: var(--space-2) var(--space-3);\\n      font-size: var(--font-down-1-rem);\\n    }\\n\\n    &:hover {\\n      .discourse-no-touch & {\\n        background: var(--primary-very-low);\\n      }\\n\\n      .discourse-touch & {\\n        background: transparent;\\n      }\\n    }\\n  }\\n\\n  .avatar {\\n    background: var(--primary-low);\\n\\n    @include viewport.until(sm) {\\n      width: 32px;\\n      height: 32px;\\n    }\\n  }\\n\\n  &__user-info {\\n    flex: 1;\\n    min-width: 0;\\n    display: flex;\\n    flex-direction: column;\\n    align-items: flex-start;\\n  }\\n\\n  &__name {\\n    @include ellipsis;\\n    color: var(--primary) !important;\\n    max-width: 100%;\\n  }\\n\\n  &__username {\\n    color: var(--primary-medium) !important;\\n    font-size: var(--font-down-1);\\n    text-decoration: none;\\n    overflow: hidden;\\n    text-overflow: ellipsis;\\n    white-space: nowrap;\\n\\n    &:hover {\\n      text-decoration: underline;\\n    }\\n  }\\n\\n  &__reaction {\\n    color: var(--danger);\\n    flex-shrink: 0;\\n    margin-left: auto;\\n\\n    &.emoji {\\n      width: 1.15em;\\n      height: 1.15em;\\n\\n      @include viewport.until(sm) {\\n        width: 1.25em;\\n        height: 1.25em;\\n      }\\n    }\\n  }\\n\\n  &__skeleton-item {\\n    pointer-events: none;\\n  }\\n\\n  &__skeleton-avatar,\\n  &__skeleton-name,\\n  &__skeleton-username,\\n  &__skeleton-reaction {\\n    background: var(--primary-low);\\n    border-radius: var(--d-border-radius);\\n    position: relative;\\n    overflow: hidden;\\n\\n    &::after {\\n      content: \\"\\";\\n      position: absolute;\\n      inset: 0;\\n      transform: translateX(-100%);\\n      background: linear-gradient(\\n        90deg,\\n        rgb(var(--skeleton-shimmer-rgb), 0) 0,\\n        rgb(var(--skeleton-shimmer-rgb), 0.3) 50%,\\n        rgb(var(--skeleton-shimmer-rgb), 0.5) 100%\\n      );\\n\\n      @media (prefers-reduced-motion: no-preference) {\\n        animation: users-popup-shimmer 1.25s infinite;\\n      }\\n    }\\n  }\\n\\n  &__skeleton-avatar {\\n    width: 24px;\\n    height: 24px;\\n    border-radius: 50%;\\n    flex-shrink: 0;\\n\\n    @include viewport.until(sm) {\\n      width: 32px;\\n      height: 32px;\\n    }\\n  }\\n\\n  &__skeleton-name {\\n    height: 12px;\\n    width: 60%;\\n    margin-top: 2px;\\n  }\\n\\n  &__skeleton-username {\\n    height: 10px;\\n    width: 40%;\\n    margin-top: var(--space-2);\\n  }\\n\\n  &__skeleton-reaction {\\n    width: 1.15em;\\n    height: 1.15em;\\n    flex-shrink: 0;\\n    margin-left: auto;\\n\\n    @include viewport.until(sm) {\\n      width: 1.25em;\\n      height: 1.25em;\\n    }\\n  }\\n\\n  @keyframes users-popup-shimmer {\\n    100% {\\n      transform: translateX(100%);\\n    }\\n  }\\n}\\n",".change-reply-to-modal {\\n  .d-modal__container {\\n    max-width: 720px;\\n    width: 100%;\\n  }\\n\\n  .d-modal__body {\\n    padding-bottom: 0;\\n  }\\n\\n  .change-reply-to-modal__hint,\\n  .change-reply-to-modal__selection {\\n    margin: 0 0 var(--space-2) 0;\\n    color: var(--primary-medium);\\n  }\\n\\n  // Re-flow the fullscreen timeline inline inside the modal body.\\n  .timeline-container.timeline-fullscreen {\\n    position: static;\\n    max-height: none;\\n    padding: var(--space-2) 0 0 0;\\n    margin: 0;\\n    box-shadow: none;\\n    border-top: none;\\n    background-color: transparent;\\n    z-index: auto;\\n\\n    &.show {\\n      max-height: none;\\n    }\\n\\n    .topic-timeline {\\n      display: block;\\n      width: auto;\\n      table-layout: auto;\\n    }\\n\\n    // The timeline footer has \\"jump to post\\" and notification controls that\\n    // are irrelevant inside this picker; hide them.\\n    .timeline-footer-controls {\\n      display: none;\\n    }\\n\\n    // Keep the excerpt readable; the fullscreen styles line-clamp to 8 which\\n    // is fine here too.\\n    .post-excerpt {\\n      margin-bottom: var(--space-2);\\n    }\\n  }\\n}\\n",".create-invite-with-roles-modal {\\n  .d-modal__container {\\n    width: 100%;\\n    max-width: 32em;\\n  }\\n\\n  &__role {\\n    margin-bottom: 1em;\\n  }\\n\\n  &__staff-role-description {\\n    margin: 0;\\n    font-size: var(--font-down-1);\\n    color: var(--primary-high);\\n  }\\n\\n  &__sent-to {\\n    margin-top: 0;\\n  }\\n\\n  &__link-share {\\n    display: flex;\\n    gap: 0.5em;\\n    margin-bottom: 1em;\\n\\n    input.invite-link {\\n      flex: 1;\\n      margin-bottom: 0;\\n    }\\n  }\\n\\n  &__summary-rows {\\n    margin: 0;\\n  }\\n\\n  &__summary-row {\\n    display: flex;\\n    justify-content: space-between;\\n    gap: 1em;\\n    padding: 0.5em 0;\\n\\n    &:not(:last-child) {\\n      border-bottom: 1px solid var(--content-border-color);\\n    }\\n\\n    dt {\\n      color: var(--primary-medium);\\n      font-weight: normal;\\n    }\\n\\n    dd {\\n      margin: 0;\\n      text-align: right;\\n      overflow-wrap: anywhere;\\n    }\\n  }\\n\\n  &__email-sent {\\n    h3 {\\n      margin-top: 0;\\n    }\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.manageable-row-list {\\n  .d-modal__body {\\n    padding-inline: 0;\\n    padding-block: var(--space-3);\\n  }\\n\\n  &__search-wrapper {\\n    padding: var(--space-2) 1.5rem;\\n    border-bottom: 1px solid var(--primary-low);\\n    background: var(--secondary);\\n  }\\n\\n  &__counter {\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-2-rem);\\n  }\\n\\n  &__list {\\n    display: flex;\\n    flex-direction: column;\\n\\n    @include unstyled-list;\\n  }\\n\\n  &__row {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-3);\\n    padding: var(--space-3) var(--space-6);\\n    background: var(--secondary);\\n    box-shadow:\\n      inset 0 2px 0 0 transparent,\\n      inset 0 -2px 0 0 transparent;\\n\\n    .manageable-row-list__list.--dragging & {\\n      transition: box-shadow 0.1s ease;\\n    }\\n\\n    &:not(:last-child) {\\n      border-bottom: 1px solid var(--primary-low);\\n    }\\n\\n    &[draggable=\\"true\\"] {\\n      cursor: grab;\\n    }\\n\\n    &.dragging {\\n      opacity: 0.5;\\n    }\\n\\n    &.drag-below,\\n    &:not(.dragging):has(+ .manageable-row-list__row.drag-above) {\\n      box-shadow:\\n        inset 0 2px 0 0 transparent,\\n        inset 0 -2px 0 0 var(--tertiary);\\n    }\\n\\n    &:first-child.drag-above,\\n    .manageable-row-list__row.dragging + &.drag-above {\\n      box-shadow:\\n        inset 0 2px 0 0 var(--tertiary),\\n        inset 0 -2px 0 0 transparent;\\n    }\\n\\n    @include viewport.until(sm) {\\n      padding: var(--space-2) var(--space-3) var(--space-2) var(--space-6);\\n    }\\n  }\\n\\n  &__grip {\\n    align-self: flex-start;\\n    color: var(--primary-low-mid);\\n    visibility: hidden;\\n\\n    .manageable-row-list__list.--reorderable\\n      .manageable-row-list__row.--enabled\\n      & {\\n      visibility: visible;\\n    }\\n  }\\n\\n  &__order-mobile {\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-2);\\n    visibility: hidden;\\n\\n    .manageable-row-list__list.--reorderable\\n      .manageable-row-list__row.--enabled\\n      & {\\n      visibility: visible;\\n    }\\n  }\\n\\n  &__row-text {\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-half);\\n    flex: 1 1 auto;\\n    min-width: 0;\\n  }\\n\\n  &__row-heading {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-2);\\n    min-width: 0;\\n  }\\n\\n  &__title {\\n    font-weight: 600;\\n    overflow: hidden;\\n    text-overflow: ellipsis;\\n    white-space: nowrap;\\n    min-width: 0;\\n  }\\n\\n  &__description {\\n    margin: 0;\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1);\\n  }\\n\\n  &__arrow {\\n    flex: 0 0 auto;\\n  }\\n\\n  .d-modal__footer {\\n    justify-content: flex-end;\\n\\n    @include viewport.until(sm) {\\n      flex-direction: column;\\n      align-items: flex-end;\\n      gap: var(--space-2);\\n    }\\n  }\\n\\n  &__footer-note {\\n    margin: 0;\\n    margin-right: auto;\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1);\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.manage-reports {\\n  .manageable-row-list__description {\\n    text-transform: capitalize;\\n  }\\n\\n  .de-cta__description {\\n    @include viewport.until(sm) {\\n      display: none;\\n    }\\n  }\\n}\\n",".share-target-modal {\\n  &__intro {\\n    margin-top: 0;\\n  }\\n\\n  &__preview-text {\\n    padding: 0.5em 0.75em;\\n    background: var(--primary-very-low);\\n    border-radius: var(--d-border-radius);\\n    white-space: pre-wrap;\\n    word-break: break-word;\\n    max-height: 8em;\\n    overflow-y: auto;\\n  }\\n\\n  &__files {\\n    display: flex;\\n    flex-wrap: wrap;\\n    gap: 0.5em;\\n    margin-top: 0.75em;\\n  }\\n\\n  &__thumbnail {\\n    width: 80px;\\n    height: 80px;\\n    object-fit: cover;\\n    border-radius: var(--d-border-radius);\\n    border: 1px solid var(--primary-low);\\n  }\\n\\n  &__file-name {\\n    padding: 0.25em 0.5em;\\n    background: var(--primary-very-low);\\n    border-radius: var(--d-border-radius);\\n    font-size: var(--font-down-1);\\n    word-break: break-all;\\n  }\\n\\n  .d-modal__footer {\\n    flex-wrap: wrap;\\n  }\\n}\\n","@keyframes slidein {\\n  0% {\\n    transform: translateX(0);\\n  }\\n\\n  50% {\\n    transform: translateX(5px);\\n  }\\n\\n  100% {\\n    transform: translateX(0);\\n  }\\n}\\n\\n.popup-tip {\\n  @include form-item-sizing;\\n  position: absolute;\\n  left: 0;\\n  z-index: z(\\"composer\\", \\"dropdown\\") + 1;\\n  cursor: pointer;\\n\\n  @media (prefers-reduced-motion: no-preference) {\\n    animation: 0.15s slidein 3;\\n  }\\n\\n  &.bad {\\n    background: var(--danger-medium);\\n    color: white;\\n    box-shadow: var(--shadow-dropdown);\\n  }\\n\\n  &.hide,\\n  &.good {\\n    display: none;\\n  }\\n\\n  .d-icon {\\n    color: var(--primary);\\n    opacity: 0.5;\\n    font-size: var(--font-0);\\n\\n    &:hover {\\n      opacity: 1;\\n    }\\n  }\\n}\\n","#topic-entrance {\\n  border: 1px solid var(--content-border-color);\\n  padding: 5px;\\n  background: var(--secondary);\\n  box-shadow: var(--shadow-card);\\n  width: 133px;\\n\\n  @include unselectable;\\n\\n  &:not(.--glimmer) {\\n    z-index: z(\\"dropdown\\");\\n    position: absolute;\\n\\n    button.full .d-icon {\\n      display: block;\\n      width: 100%;\\n    }\\n  }\\n\\n  &.--glimmer {\\n    button.full {\\n      display: flex;\\n      flex-direction: column;\\n    }\\n  }\\n\\n  button.full {\\n    width: 100%;\\n    margin-bottom: 5px;\\n    flex-wrap: wrap;\\n\\n    .d-icon {\\n      margin: 2px auto;\\n      transform: rotate(90deg);\\n    }\\n  }\\n\\n  button.btn.jump-bottom {\\n    margin: 5px 0 0 0;\\n  }\\n}\\n","@media print {\\n  /* remove items N/A for print\\n  ** visual clutter etc. */\\n\\n  .avatar,\\n  .topic-avatar,\\n  header,\\n  .topic-above-post-stream-outlet.topic-above-post-stream,\\n  .topic-map,\\n  .post-menu-area.clearfix,\\n  div#topic-footer-buttons,\\n  div.suggested-topics,\\n  div#progress-topic-wrapper,\\n  #topic-progress-wrapper,\\n  div.nums,\\n  ._flyout,\\n  #topic-progress,\\n  .quote-controls,\\n  .topic-timer-info,\\n  div.lazy-video-container,\\n  .post-info.edits,\\n  .post-action,\\n  .saving-text,\\n  .draft-text,\\n  .discourse-modal,\\n  div.read-state,\\n  div.read-state.read,\\n  .edit-topic,\\n  a.reply-to-tab,\\n  a.reply-new,\\n  div.time-gap,\\n  #bottom,\\n  #footer,\\n  .alert-info,\\n  .badge-category,\\n  a[data-clicks]::after,\\n  .crawler-nav,\\n  .powered-by-link,\\n  .timeline-container,\\n  .poll-info {\\n    display: none !important;\\n  }\\n\\n  /* For readability */\\n  a,\\n  a:visited {\\n    color: #08c !important;\\n    font-weight: bold;\\n  }\\n\\n  /* bottom border to help separate posts */\\n  div.row {\\n    border-top: 1px solid #aaa;\\n  }\\n\\n  .cooked pre code {\\n    max-height: none;\\n  }\\n\\n  #main-outlet {\\n    padding: 0 !important;\\n  }\\n\\n  html,\\n  body {\\n    min-width: 0;\\n    height: auto;\\n  }\\n\\n  .lightbox-wrapper img {\\n    max-width: 500px !important;\\n    height: auto !important;\\n  }\\n\\n  .topic-body {\\n    width: auto;\\n    margin: 0;\\n    padding: 0;\\n    float: none;\\n  }\\n\\n  .topic-post > article.boxed .select-posts {\\n    width: auto;\\n    left: auto;\\n    right: 0;\\n  }\\n\\n  .gap {\\n    width: auto;\\n  }\\n\\n  /* restyle div#topic-title */\\n  #topic-title {\\n    margin: 0;\\n    padding: 0;\\n  }\\n\\n  #topic-title div div h1 {\\n    margin: 2.5em 0 0 0;\\n    padding: 0;\\n    float: left;\\n    font-weight: normal;\\n    font-size: normal;\\n  }\\n\\n  /* localhost  - MOOT for production */\\n  .topic-category-outlet.show-topic-category-location,\\n  div.alert.alert-info.alert-emails-disabled,\\n  div.profiler-results.profiler-left.profiler-no-controls {\\n    display: none;\\n  }\\n}\\n",".bulk-select-bookmarks-dropdown {\\n  .select-kit.single-select.dropdown-select-box .select-kit-row {\\n    .texts .name {\\n      font-weight: normal;\\n    }\\n\\n    .icons {\\n      font-size: var(--font-down-2);\\n      margin-right: 0.75em;\\n      position: relative;\\n      top: 0.15em;\\n    }\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n:root {\\n  --category-header-logo-size: 3rem;\\n  --category-description-width: 760px;\\n  --category-header-border: 1px solid var(--content-border-color);\\n  --discovery-heading-description-color: var(--primary-800);\\n}\\n\\n// shared banner treatment used above the discovery topic list\\n// .category-heading, .tag-info\\n.discovery-heading {\\n  gap: 0 var(--space-4);\\n  margin-bottom: var(--space-6);\\n  padding: var(--space-4);\\n  border: var(--category-header-border);\\n  border-radius: var(--d-border-radius);\\n}\\n\\n.category-heading {\\n  max-width: 100%;\\n\\n  &.--has-logo {\\n    display: flex;\\n  }\\n\\n  &__logo.category-logo.aspect-image {\\n    height: var(--category-header-logo-size);\\n    width: var(--category-header-logo-size);\\n    margin-top: calc(1rem - 1cap);\\n    flex-shrink: 0;\\n  }\\n\\n  &__description {\\n    margin: 0;\\n    line-height: var(--line-height-large);\\n    font-size: var(--font-0);\\n    color: var(--discovery-heading-description-color);\\n    max-width: var(--category-description-width);\\n  }\\n\\n  &__content {\\n    flex-grow: 1;\\n  }\\n\\n  &__content .badge-category__wrapper {\\n    font-size: var(--font-up-3);\\n  }\\n\\n  &__content .badge-category__name {\\n    font-weight: bold;\\n    color: var(--primary);\\n  }\\n\\n  @include viewport.until(sm) {\\n    p {\\n      font-size: var(--font-up-1);\\n      margin-bottom: 0.75em;\\n    }\\n  }\\n}\\n\\n.category-logo.aspect-image {\\n  --max-height: 150px;\\n  width: auto;\\n  max-height: var(--max-height);\\n  max-width: 100%;\\n  height: auto;\\n\\n  img {\\n    width: calc(var(--max-height) * var(--aspect-ratio));\\n    max-width: 100%;\\n    height: inherit;\\n    max-height: var(--max-height);\\n  }\\n}\\n\\n.topic-list.shared-drafts {\\n  margin-bottom: var(--space-6);\\n}\\n\\n#header-list-area {\\n  background: var(--d-content-background);\\n}\\n\\n// Topic list body\\n.topic-list-item.visited,\\n.latest-topic-list-item.visited,\\n.category-topic-link.visited {\\n  background-color: var(--topic-list-item-background-color--visited);\\n\\n  a.title:not(.badge-notification) {\\n    color: var(--title-color--read);\\n    font-weight: var(--topic-title-font-weight--visited);\\n  }\\n}\\n\\n.topic-list-item {\\n  background-color: var(--topic-list-item-background-color);\\n\\n  .post-exce