\n        }\\n      }\\n\\n      p {\\n        margin-top: 0;\\n        color: var(--primary-high);\\n      }\\n\\n      &.--has-description {\\n        h3 {\\n          margin-bottom: 0;\\n        }\\n      }\\n    }\\n  }\\n\\n  &__header {\\n    max-width: 1100px;\\n\\n    h1 {\\n      font-size: var(--font-up-1);\\n    }\\n  }\\n\\n  &__left-side {\\n    flex: 1 1 650px;\\n  }\\n\\n  &__right-side {\\n    flex: 1 2 200px;\\n  }\\n\\n  &__stats {\\n    display: flex;\\n    border-top: 1px solid var(--content-border-color);\\n    border-bottom: 1px solid var(--content-border-color);\\n    padding: 1em 1em;\\n    margin-bottom: 1em;\\n\\n    @include viewport.until(md) {\\n      flex-direction: column;\\n    }\\n\\n    .d-icon {\\n      margin-right: 3px;\\n    }\\n  }\\n\\n  &__stats-item {\\n    flex: 1 0 fit-content;\\n\\n    @include viewport.until(md) {\\n      margin-bottom: 1em;\\n\\n      &:last-child {\\n        margin-bottom: 0;\\n      }\\n    }\\n  }\\n\\n  &__banner {\\n    margin-bottom: 1em;\\n    width: 100%;\\n    height: auto; // Let the height scale with the width\\n    position: relative; // Ensure the container can handle absolute positioning for the image\\n    padding-top: 27.27%; // Maintain the aspect ratio (300px/1100px * 100)\\n\\n    &-img {\\n      position: absolute; // Allow to fill the full space\\n      top: 0;\\n      left: 0;\\n      width: 100%;\\n      height: 100%;\\n      object-fit: cover; // Ensures the image fills the container while preserving aspect ratio\\n    }\\n  }\\n\\n  &__activities-item {\\n    display: flex;\\n    align-items: center;\\n    margin-bottom: 1.5em;\\n  }\\n\\n  &__activities-item-icon {\\n    margin-right: 1em;\\n  }\\n\\n  &__activities-item-period {\\n    font-size: var(--font-down-2);\\n  }\\n\\n  &__admins,\\n  &__moderators {\\n    margin-top: 3em;\\n\\n    h2 {\\n      margin-bottom: 1em;\\n    }\\n  }\\n}\\n\\n.about-page-users-list {\\n  display: grid;\\n  gap: 1em;\\n  grid-template-columns: repeat(auto-fill, minmax(14em, 1fr));\\n\\n  &__expand-button {\\n    width: 100%;\\n  }\\n}\\n","// Styles used before the user is logged into discourse. For example, activating their\\n// account or changing their email.\\n.account-created-page,\\n.activate-account-page {\\n  background: var(--secondary);\\n\\n  #main-outlet {\\n    padding: 0;\\n    height: 100%;\\n  }\\n\\n  .above-main-container-outlet {\\n    display: none;\\n  }\\n}\\n\\n.activate-account-page .alert-error {\\n  margin: 1em;\\n}\\n\\n.account-created,\\n.activate-account {\\n  max-width: 500px;\\n  padding: 2rem 3rem;\\n  background: var(--secondary);\\n  margin: 10vh auto 1em auto;\\n\\n  @media screen and (height <= 700px) {\\n    margin: 1em auto 1em auto;\\n  }\\n}\\n\\n.account-created {\\n  .ac-message {\\n    font-size: var(--font-up-1);\\n    line-height: var(--line-height-large);\\n  }\\n\\n  .activation-controls {\\n    display: flex;\\n    flex-wrap: wrap;\\n    gap: 0.5em;\\n    margin-top: 1em;\\n  }\\n\\n  .edit-cancel {\\n    text-transform: capitalize;\\n  }\\n\\n  .success-info p:last-child {\\n    margin-bottom: 0;\\n  }\\n}\\n\\n.activate-account {\\n  .activate-account-button,\\n  .continue-button {\\n    margin-top: 1em;\\n    display: block;\\n    width: fit-content;\\n  }\\n\\n  .login-welcome-header {\\n    width: fit-content;\\n  }\\n\\n  .tada-image {\\n    width: 150px;\\n    padding-bottom: 1em;\\n  }\\n}\\n",".alert {\\n  padding: 0.5em 2.5em 0.5em 1em;\\n  background-color: var(--danger-low);\\n  color: var(--primary);\\n  position: relative;\\n  margin-bottom: 1em;\\n\\n  .close {\\n    font-size: var(--font-up-3);\\n    position: absolute;\\n    top: 0.265em;\\n    right: 0.66em;\\n    padding: 0;\\n\\n    .d-icon {\\n      color: var(--primary-medium);\\n    }\\n  }\\n\\n  &.alert-success {\\n    background-color: var(--success-low);\\n    color: var(--primary);\\n  }\\n\\n  &.alert-error {\\n    background-color: var(--danger-low);\\n    color: var(--primary);\\n  }\\n\\n  &.alert-warning {\\n    background-color: var(--highlight-bg);\\n    color: var(--primary);\\n  }\\n\\n  &.alert-info {\\n    background-color: var(--tertiary-low);\\n    color: var(--primary);\\n\\n    &.clickable {\\n      color: var(--tertiary);\\n      z-index: z(\\"base\\");\\n\\n      .mobile-view & {\\n        margin: 0;\\n        padding: 1em;\\n      }\\n    }\\n  }\\n}\\n\\na.alert.clickable {\\n  display: flex;\\n}\\n",".authorize-api-key {\\n  max-width: 42rem;\\n  margin: 0 auto;\\n  padding: 3rem 1rem;\\n\\n  h1 {\\n    margin: 0 0 0.75rem;\\n    font-size: var(--font-up-5);\\n    line-height: var(--line-height-small);\\n  }\\n\\n  .alert {\\n    border: 0;\\n    border-radius: var(--d-border-radius-large);\\n    margin: 1rem 0;\\n    padding: 1rem 1.25rem;\\n\\n    p {\\n      margin: 0;\\n    }\\n  }\\n\\n  &__user {\\n    display: flex;\\n    align-items: center;\\n    gap: 0.4rem;\\n    color: var(--primary-medium);\\n    margin-bottom: 1.5rem;\\n  }\\n\\n  &__username {\\n    color: var(--primary);\\n    font-weight: 600;\\n  }\\n\\n  &__summary {\\n    background: var(--primary-very-low);\\n    border: 1px solid var(--primary-low);\\n    border-radius: var(--d-border-radius-large);\\n    margin-bottom: 1.5rem;\\n    padding: 1.25rem;\\n  }\\n\\n  &__permissions,\\n  &__summary-detail,\\n  &__summary-notice {\\n    padding: 0;\\n  }\\n\\n  &__permissions {\\n    margin-bottom: 1rem;\\n  }\\n\\n  &__permissions-header {\\n    margin: 0 0 0.75rem;\\n  }\\n\\n  &__scopes {\\n    margin: 0;\\n    padding-left: 1.25rem;\\n  }\\n\\n  &__summary-detail,\\n  &__summary-notice {\\n    color: var(--primary-high);\\n    font-size: var(--font-down-1-rem);\\n\\n    p {\\n      margin: 0;\\n    }\\n  }\\n\\n  &__summary-notice {\\n    margin-bottom: 1rem;\\n  }\\n\\n  &__redirect {\\n    background: var(--highlight-bg);\\n    border-radius: var(--d-border-radius-large);\\n    padding: 1rem 1.25rem;\\n    margin-bottom: 1.5rem;\\n  }\\n\\n  &__redirect-url {\\n    margin: 0;\\n    word-break: break-word;\\n  }\\n\\n  &__buttons {\\n    display: flex;\\n    align-items: center;\\n    gap: 0.5rem;\\n    margin-top: 1.25rem;\\n  }\\n\\n  &__code-form {\\n    margin-top: 1.5rem;\\n\\n    .d-otp-slot {\\n      font-size: var(--font-up-1);\\n      padding: 0.625em 0.8em;\\n    }\\n  }\\n\\n  &__code-input {\\n    margin-top: 0.75rem;\\n  }\\n}\\n","// Support for BBCode styles like colors and font sizes\\nspan {\\n  &.bbcode-b {\\n    font-weight: bold;\\n  }\\n\\n  &.bbcode-i {\\n    font-style: italic;\\n  }\\n\\n  &.bbcode-u {\\n    text-decoration: underline;\\n  }\\n\\n  &.bbcode-s {\\n    text-decoration: line-through;\\n  }\\n}\\n","@use \\"common/foundation/mixins\\";\\n\\n.latest-topic-list,\\n.top-topic-list {\\n  @include mixins.topic-list-icons;\\n\\n  .table-heading {\\n    padding: var(--space-2) var(--space-1);\\n    color: var(--d-topic-list-header-text-color);\\n    font-size: var(--d-topic-list-data-font-size);\\n  }\\n\\n  .no-topics,\\n  .more-topics {\\n    margin-top: 1em;\\n  }\\n\\n  .posts-map {\\n    font-size: var(--font-up-1);\\n    font-weight: bold;\\n    color: var(--primary-medium);\\n  }\\n}\\n\\n.latest-topic-list-item {\\n  padding: 1em;\\n  border-bottom: 1px solid var(--content-border-color);\\n  display: flex;\\n  align-items: center;\\n  gap: var(--space-4);\\n\\n  .topic-poster {\\n    position: relative;\\n\\n    .avatar-flair {\\n      position: absolute;\\n      bottom: 0;\\n    }\\n  }\\n\\n  .main-link {\\n    flex: 0 1 auto;\\n    max-width: 65%;\\n    font-size: var(--font-0);\\n\\n    a.title {\\n      padding: 15px 0;\\n      word-break: break-word;\\n      color: var(--primary);\\n    }\\n\\n    .anon & {\\n      a.title:visited:not(.badge-notification) {\\n        color: var(--primary-medium);\\n      }\\n    }\\n\\n    a.title.visited:not(.badge-notification) {\\n      color: var(--primary-medium);\\n    }\\n\\n    .top-row {\\n      margin-bottom: 0.1em;\\n      font-size: var(--font-up-1);\\n    }\\n\\n    .bottom-row {\\n      display: flex;\\n      flex-wrap: wrap;\\n      align-items: baseline;\\n      gap: 0 0.5em;\\n    }\\n  }\\n\\n  .topic-stats {\\n    flex: 1 0 0px;\\n    text-align: right;\\n    color: var(--primary-med-or-secondary-high);\\n  }\\n\\n  .topic-last-activity a {\\n    color: var(--primary-low-mid-or-secondary-high);\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n:root {\\n  --category-boxes-min-width: 15em;\\n  --category-boxes-max-width: 1fr;\\n}\\n\\n.category-list {\\n  table-layout: fixed;\\n\\n  @include viewport.from(sm) {\\n    margin-bottom: 10px;\\n    width: 100%;\\n\\n    td,\\n    th {\\n      color: var(--d-topic-list-header-text-color);\\n\\n      &:first-of-type {\\n        padding-inline-start: var(--d-topic-list-data-padding-inline-start);\\n      }\\n\\n      &:last-of-type {\\n        padding-inline-end: var(--d-topic-list-data-padding-inline-end);\\n      }\\n    }\\n\\n    td {\\n      padding: var(--d-topic-list-data-padding-y)\\n        var(--d-topic-list-data-padding-x);\\n      vertical-align: top;\\n    }\\n\\n    th {\\n      vertical-align: middle;\\n      font-size: var(--d-topic-list-data-font-size);\\n    }\\n\\n    .topics .badge-notification,\\n    .category .badge-notification {\\n      background-color: transparent;\\n      color: var(--primary-med-or-secondary-high);\\n    }\\n\\n    .topics {\\n      width: 80px;\\n      text-align: right;\\n\\n      .value {\\n        font-size: var(--font-up-1);\\n        font-weight: bold;\\n      }\\n\\n      .unit {\\n        font-size: var(--font-down-1);\\n      }\\n\\n      .badge-notification {\\n        display: block;\\n        text-align: right;\\n        padding-right: 0;\\n\\n        &:first-child {\\n          margin-top: 0.75em;\\n        }\\n      }\\n    }\\n\\n    .subcategories {\\n      display: flex;\\n      flex-wrap: wrap;\\n      gap: 0.15em 0.75em;\\n      margin-top: 0.5em;\\n\\n      .subcategory {\\n        display: inline-flex;\\n        align-items: baseline;\\n        gap: 0.25em;\\n\\n        @include ellipsis;\\n\\n        .badge-category {\\n          min-width: 0;\\n        }\\n      }\\n\\n      .category__badges {\\n        display: flex;\\n        gap: 0.25em;\\n\\n        .badge-notification {\\n          top: 0;\\n          padding: 0;\\n        }\\n      }\\n\\n      .badge-notification.unread-posts {\\n        display: block;\\n        padding: 0;\\n      }\\n\\n      &__more-subcategories {\\n        font-size: var(--font-down-1);\\n\\n        a {\\n          color: var(--primary-high);\\n        }\\n      }\\n    }\\n\\n    .featured-topic {\\n      display: flex;\\n      align-items: baseline;\\n\\n      a.last-posted-at,\\n      a.last-posted-at:visited {\\n        font-size: var(--font-down-1);\\n        color: var(--primary-med-or-secondary-high);\\n      }\\n\\n      .title {\\n        @include ellipsis;\\n        flex: 0 1 auto;\\n      }\\n\\n      .topic-post-badges .badge.unread-posts,\\n      .title {\\n        margin-right: 5px;\\n      }\\n\\n      &.--glimmer button.-trigger {\\n        background: transparent;\\n        border: none;\\n        padding: 0;\\n      }\\n\\n      .topic-statuses {\\n        display: flex;\\n      }\\n    }\\n  }\\n\\n  tbody {\\n    .category {\\n      @include viewport.from(sm) {\\n        border-left: 6px solid var(--category-badge-color, var(--primary-low));\\n\\n        h3,\\n        h4 {\\n          line-height: var(--line-height-medium);\\n\\n          a[href] {\\n            color: var(--primary);\\n          }\\n        }\\n\\n        h3 {\\n          font-size: var(--font-up-2);\\n        }\\n\\n        h4 {\\n          font-size: var(--font-up-1);\\n        }\\n\\n        .latest {\\n          padding: 0 0 10px 10px;\\n        }\\n      }\\n\\n      &.no-category-style {\\n        border-color: transparent;\\n        border-left: 0;\\n        padding-left: 0;\\n      }\\n    }\\n  }\\n\\n  .category-text-title {\\n    display: flex;\\n    align-items: baseline;\\n  }\\n\\n  .category-name {\\n    display: inline-block;\\n    max-width: 100%;\\n\\n    @include ellipsis;\\n    vertical-align: text-top;\\n    line-height: var(--line-height-medium);\\n  }\\n\\n  &.with-topics {\\n    @include viewport.from(sm) {\\n      margin-left: 3px;\\n\\n      .category {\\n        width: 45%;\\n      }\\n    }\\n\\n    .subcategories-with-subcategories {\\n      .category-description {\\n        display: none;\\n      }\\n    }\\n  }\\n\\n  &.hidden {\\n    display: none;\\n  }\\n}\\n\\n.navigation-categories .category-list.subcategory-list {\\n  margin-bottom: 1em;\\n}\\n\\n.subcategory-list {\\n  .parent-category {\\n    h3 {\\n      display: inline;\\n    }\\n\\n    .category-text-title {\\n      display: inline-flex;\\n    }\\n\\n    .stat {\\n      margin-left: 0.5em;\\n    }\\n  }\\n}\\n\\n.category-boxes,\\n.category-boxes-with-topics {\\n  display: grid;\\n  gap: var(--d-category-boxes-gap);\\n  margin-top: var(--d-category-boxes-margin-top);\\n  margin-bottom: 1em;\\n  width: 100%;\\n\\n  .category-box {\\n    position: relative;\\n    display: flex;\\n    flex-direction: row;\\n    align-content: flex-start;\\n    box-sizing: border-box;\\n    border-width: 0;\\n    border-radius: var(--d-border-radius);\\n    background-color: var(--d-category-box-background-color);\\n    border-left-width: var(--d-category-border-accent-width);\\n    border-style: solid;\\n    border-color: var(--category-badge-color, var(--primary-low));\\n\\n    .mobile-view & {\\n      width: 100%;\\n    }\\n\\n    .category-box-heading {\\n      margin-bottom: 0.5em;\\n\\n      a[href] {\\n        width: 100%;\\n        color: var(--primary);\\n      }\\n    }\\n\\n    h3 .d-icon {\\n      margin-right: 0;\\n    }\\n\\n    .parent-box-link {\\n      // This avoids an issue with nested links by layering links instead\\n      &::before {\\n        content: \\"\\";\\n        position: absolute;\\n        z-index: 0;\\n        top: 0;\\n        left: 0;\\n        right: 0;\\n        bottom: 0;\\n      }\\n    }\\n\\n    .category-logo.aspect-image img {\\n      --height: 40px;\\n      display: block;\\n      margin: 0 auto 1em auto;\\n      height: var(--height);\\n      width: calc(var(--height) * var(--aspect-ratio));\\n      max-width: 100%;\\n    }\\n  }\\n\\n  .category-box-inner {\\n    box-sizing: border-box;\\n    width: 100%;\\n    padding: 1em;\\n    display: flex;\\n    flex-direction: column;\\n    border-width: var(--d-category-border-box-width);\\n    border-left-width: 0;\\n    border-style: solid;\\n    border-color: var(--primary-low);\\n    border-top-right-radius: var(--d-border-radius);\\n    border-bottom-right-radius: var(--d-border-radius);\\n  }\\n\\n  &.no-logos {\\n    .category-logo {\\n      display: none;\\n    }\\n  }\\n\\n  .badge-category__wrapper {\\n    max-width: 100%;\\n  }\\n}\\n\\n.category-boxes {\\n  grid-template-columns: repeat(\\n    auto-fit,\\n    minmax(var(--category-boxes-min-width), var(--category-boxes-max-width))\\n  );\\n\\n  .category-box {\\n    > a {\\n      width: 100%;\\n      padding: 0;\\n    }\\n\\n    .category-box-inner {\\n      padding: var(--space-4);\\n\\n      .category-logo {\\n        float: none;\\n        margin: 0;\\n      }\\n    }\\n  }\\n\\n  &.no-logos {\\n    .category-box .category-box-inner > a {\\n      padding: var(--space-12) var(--space-4);\\n    }\\n  }\\n\\n  .description {\\n    margin-bottom: var(--space-4);\\n    text-align: var(--category-boxes-text-alignment);\\n    font-size: var(--font-0);\\n    color: var(--category-boxes-description-text-color);\\n    position: relative;\\n\\n    @include line-clamp(4);\\n\\n    //  allow clicks to fall through the description text to the category below...\\n    pointer-events: none;\\n\\n    .overflow {\\n      max-height: 6em;\\n\\n      div a {\\n        //  ...but links in description should still be clickable\\n        pointer-events: auto;\\n      }\\n    }\\n  }\\n\\n  h3 {\\n    font-size: var(--category-boxes-title-font-size);\\n    line-height: var(--line-height-medium);\\n    text-align: var(--category-boxes-text-alignment);\\n    color: var(--primary);\\n    overflow: hidden;\\n\\n    @include viewport.until(sm) {\\n      margin: 0 0 0.5em 0;\\n    }\\n  }\\n\\n  h4 a {\\n    color: var(--primary);\\n  }\\n\\n  .subcategory.with-subcategories {\\n    position: relative;\\n    border: none;\\n    border-left-width: 4px;\\n    border-left-style: solid;\\n    margin-bottom: 0.25em;\\n\\n    .category-title-link {\\n      display: flex;\\n\\n      .category-logo {\\n        flex: 1 0 auto;\\n        margin: 0.25em 0.5em 0.5em 0;\\n\\n        --max-height: 40px;\\n      }\\n\\n      .category-text-title {\\n        order: 2;\\n        line-height: var(--line-height-medium);\\n        overflow: hidden;\\n        margin-bottom: 0.25em;\\n        overflow-wrap: break-word;\\n      }\\n\\n      &::before {\\n        // This avoids an issue with nested links by layering links instead\\n        content: \\"\\";\\n        position: absolute;\\n        z-index: 0;\\n        top: 0;\\n        left: 0;\\n        right: 0;\\n        bottom: 0;\\n      }\\n    }\\n\\n    .subcategory-box-inner {\\n      border: 1px solid var(--content-border-color);\\n      border-left: none;\\n      padding: 0.5em 0.5em 0.4em 0.5em;\\n    }\\n\\n    &:not(:last-of-type) {\\n      margin-bottom: 0.75em;\\n    }\\n\\n    .subcategory {\\n      margin-bottom: 0.25em;\\n    }\\n  }\\n\\n  .subcategories {\\n    display: flex;\\n    flex-flow: wrap;\\n    gap: var(--space-2);\\n\\n    .subcategory {\\n      display: flex;\\n      align-items: center;\\n\\n      @include ellipsis;\\n\\n      .badge-category__wrapper {\\n        overflow: hidden;\\n      }\\n\\n      .subcategory-image-placeholder {\\n        display: inline-block;\\n        flex: 1 0 auto;\\n\\n        .category-logo.aspect-image {\\n          