om: 15px;\\n    }\\n\\n    .subcategories-list {\\n      border-bottom: none;\\n\\n      td {\\n        padding-top: 15px;\\n      }\\n    }\\n\\n    .category-topic-link {\\n      .num {\\n        white-space: nowrap;\\n      }\\n\\n      .topic-excerpt {\\n        width: 110%;\\n      }\\n    }\\n\\n    .posters {\\n      float: left;\\n    }\\n\\n    > footer {\\n      border-top: 1px solid var(--content-border-color);\\n      padding: 7px 10px;\\n\\n      .category-stat {\\n        float: left;\\n        margin: 3px 1em 0 0;\\n        font-weight: normal;\\n        font-size: var(--font-down-1);\\n\\n        .value {\\n          font-weight: bold;\\n        }\\n      }\\n\\n      .btn {\\n        float: right;\\n        margin-left: 7px;\\n      }\\n    }\\n  }\\n\\n  .category-list-item {\\n    padding: 0.5em 0 0.25em;\\n    border-top: 1px solid var(--content-border-color) !important;\\n    border-bottom: 1px solid var(--content-border-color) !important;\\n    margin: 1em 0 2em;\\n  }\\n\\n  .category-topics-count a {\\n    color: var(--primary);\\n  }\\n}\\n\\n@include viewport.from(sm) {\\n  .categories-and-latest,\\n  .categories-and-top {\\n    display: flex;\\n    flex-flow: row wrap;\\n\\n    div.column {\\n      flex: 1 0 0px;\\n      flex-direction: row;\\n      min-width: 300px;\\n    }\\n\\n    div.column.categories {\\n      margin-right: 1em;\\n\\n      @media all and (width >= 700px) {\\n        margin-right: 2em;\\n      }\\n    }\\n\\n    .discourse-tags {\\n      .discourse-tag {\\n        font-size: var(--font-down-1);\\n      }\\n    }\\n\\n    .subcategories-with-subcategories {\\n      .category-description {\\n        display: none;\\n      }\\n    }\\n  }\\n}\\n","code {\\n  padding: 2px 4px;\\n  background: var(--inline-code-bg);\\n  white-space: pre-wrap;\\n  color: var(--primary);\\n  border-radius: var(--d-border-radius);\\n  font-size: 0.875rem;\\n  line-height: calc((13 + 4) / 13);\\n}\\n\\na > code {\\n  color: var(--tertiary);\\n}