ection: column;\\n    padding: 0.5em;\\n\\n    @include viewport.until(sm) {\\n      padding-bottom: max(env(safe-area-inset-bottom), 6px);\\n      flex-grow: 1;\\n      min-height: 0;\\n    }\\n\\n    @include viewport.from(sm) {\\n      margin: 0 auto;\\n      height: calc(100% - 11px);\\n      width: 100%;\\n    }\\n  }\\n\\n  .with-form-template {\\n    overflow: auto;\\n    flex: 1;\\n\\n    #mobile-file-upload {\\n      display: none;\\n    }\\n  }\\n\\n  .saving-text,\\n  .draft-text {\\n    display: none;\\n    padding-left: 8px;\\n\\n    .spinner {\\n      margin-left: 8px;\\n      border-color: var(--secondary);\\n      border-right-color: transparent;\\n    }\\n\\n    .d-icon {\\n      color: var(--secondary);\\n    }\\n  }\\n\\n  &.open {\\n    --min-height: 255px;\\n    border: 1px solid var(--content-border-color);\\n    box-sizing: border-box;\\n    height: var(--composer-height);\\n    min-height: var(--min-height);\\n    max-height: calc(100vh - var(--header-offset, 4em));\\n    padding-bottom: var(--composer-ipad-padding);\\n\\n    @include viewport.until(sm) {\\n      z-index: z(\\"mobile-composer\\");\\n      top: 0;\\n      transform: none;\\n      height: 100dvh;\\n      max-height: unset;\\n      border-top-left-radius: 0;\\n      border-top-right-radius: 0;\\n      border: none;\\n    }\\n  }\\n\\n  &.draft,\\n  &.saving {\\n    height: 45px !important;\\n    align-items: center;\\n    background: var(--tertiary);\\n    color: var(--secondary);\\n    flex-direction: row;\\n    justify-content: space-between;\\n\\n    .grippie {\\n      display: none;\\n    }\\n\\n    .composer-controls {\\n      display: flex;\\n      gap: 8px;\\n      padding-right: 8px;\\n\\n      .toggle-toolbar {\\n        display: none;\\n      }\\n\\n      .d-icon {\\n        color: var(--secondary);\\n      }\\n    }\\n  }\\n\\n  &.draft {\\n    cursor: pointer;\\n    display: flex;\\n\\n    .draft-text {\\n      display: block;\\n\\n      @include ellipsis;\\n    }\\n\\n    .grippie,\\n    .saving-text {\\n      display: none;\\n    }\\n  }\\n\\n  &.saving .saving-text {\\n    display: flex;\\n    align-items: center;\\n  }\\n\\n  .reply-to {\\n    color: var(--primary-high);\\n    margin-bottom: 0.5em;\\n    display: flex;\\n    align-items: center;\\n    justify-content: flex-end;\\n\\n    @include viewport.until(sm) {\\n      justify-content: space-between;\\n    }\\n\\n    .composer-actions-trigger {\\n      border-color: var(--input-border-color);\\n    }\\n\\n    .composer-actions-trigger .d-button-label {\\n      @include ellipsis;\\n    }\\n\\n    .composer-whisper-indicator {\\n      margin-left: auto;\\n\\n      @include viewport.until(sm) {\\n        .d-button-label {\\n          display: none;\\n        }\\n\\n        .d-icon {\\n          margin-right: 0;\\n        }\\n      }\\n      font-size: var(--font-down-1);\\n      border-radius: var(--d-border-radius);\\n\\n      &.--public {\\n        --d-button-default-text-color: var(--primary-high);\\n        --d-button-flat-icon-color: var(--primary-high);\\n      }\\n\\n      &.--whispering {\\n        --d-button-default-text-color: var(--tertiary);\\n        --d-button-flat-icon-color: var(--tertiary);\\n\\n        &:hover {\\n          background-color: var(--tertiary-200);\\n        }\\n      }\\n    }\\n\\n    .composer-actions-reply-target-link {\\n      --d-button-default-text-color: var(--primary-high);\\n      --d-button-flat-icon-color: var(--primary-high);\\n      overflow: hidden;\\n\\n      &__label {\\n        @include ellipsis;\\n      }\\n    }\\n\\n    .composer-action-title {\\n      display: flex;\\n      gap: var(--space-1);\\n      align-items: center;\\n      width: 100%;\\n      max-width: 100%;\\n      min-width: 0; // allows shrinking when needed\\n\\n      img.avatar {\\n        margin-right: 3px;\\n      }\\n    }\\n\\n    .action-title {\\n      display: flex;\\n      gap: var(--space-1);\\n      align-items: center;\\n      width: 100%;\\n      max-width: 100%;\\n      overflow: hidden;\\n\\n      .topic-link {\\n        @include ellipsis;\\n      }\\n    }\\n\\n    .composer-controls {\\n      display: flex;\\n    }\\n\\n    // Protection for languages with long strings on very small screens. This\\n    // has no effect on most users but we need it for some cases. If this is\\n    // not added, \\"add edit reason\\" will overlap with the composer controls\\n    @include viewport.until(sm) {\\n      .composer-actions-reply-target-link {\\n        .d-icon {\\n          margin-right: none;\\n        }\\n      }\\n\\n      #edit-reason {\\n        width: 100%;\\n        margin-left: 0;\\n        margin-top: var(--space-2);\\n      }\\n    }\\n  }\\n\\n  #edit-reason {\\n    margin: 0 4px;\\n  }\\n\\n  .user-selector,\\n  .title-and-category {\\n    display: flex;\\n    width: 100%;\\n    align-items: center;\\n    position: relative;\\n    gap: 0 var(--space-2);\\n  }\\n\\n  .user-selector {\\n    @include viewport.until(sm) {\\n      flex-wrap: wrap;\\n    }\\n\\n    @include viewport.from(sm) {\\n      margin-bottom: 0.5em;\\n    }\\n  }\\n\\n  .title-input {\\n    position: relative;\\n    display: flex;\\n    flex: 1 1 50%;\\n\\n    input {\\n      flex-grow: 1;\\n    }\\n  }\\n\\n  .with-tags {\\n    .title-input {\\n      flex: 1 1 100%;\\n    }\\n\\n    @include viewport.until(sm) {\\n      .mini-tag-chooser,\\n      .category-chooser {\\n        z-index: z(\\"base\\");\\n      }\\n    }\\n\\n    .archetype-private_message & {\\n      // PMs don't have categories, so we need a wider tag input\\n      .mini-tag-chooser {\\n        width: 100%;\\n        max-width: 100%;\\n      }\\n    }\\n  }\\n\\n  .category-input {\\n    position: relative;\\n    display: flex;\\n    flex: 1 1 auto;\\n    max-width: 40%;\\n    margin: 0 0 8px 0;\\n    min-width: 0;\\n\\n    .category-chooser {\\n      display: flex;\\n      flex: 1 0 auto;\\n      max-width: 100%;\\n      width: auto;\\n\\n      &.has-selection {\\n        .selected-name .name {\\n          font-size: var(--font-up-1);\\n        }\\n      }\\n\\n      .select-kit-header {\\n        color: var(--primary-high);\\n        white-space: nowrap;\\n        text-overflow: ellipsis;\\n      }\\n\\n      .select-kit-body {\\n        max-width: 450px;\\n      }\\n\\n      .selected-name {\\n        max-width: 100%;\\n        overflow: hidden;\\n\\n        .name {\\n          display: flex;\\n          max-width: 100%;\\n          gap: 0 0.5em;\\n\\n          .badge-category {\\n            overflow: hidden;\\n          }\\n\\n          // This prevents the first category from being too-truncated at the expense of a long subcategory\\n          > span:last-of-type:not(:first-of-type) {\\n            flex-shrink: 10;\\n          }\\n        }\\n      }\\n    }\\n  }\\n\\n  .with-tags.with-category {\\n    .title-and-category {\\n      flex-wrap: wrap;\\n    }\\n\\n    .category-input {\\n      margin-left: 0;\\n      margin-bottom: 8px;\\n      min-width: 0; // allows flex to shrink\\n      flex-wrap: wrap;\\n      max-width: calc(50% - 4px);\\n    }\\n  }\\n\\n  .add-warning {\\n    color: var(--primary-high);\\n    padding: 0.5em;\\n    display: flex;\\n    line-height: var(--line-height-medium);\\n    margin: 0;\\n\\n    @include viewport.until(sm) {\\n      margin-bottom: 0.15em;\\n    }\\n\\n    input {\\n      margin-right: 8px;\\n    }\\n  }\\n\\n  @include viewport.until(sm) {\\n    .users-input,\\n    .add-warning {\\n      width: 100%;\\n    }\\n\\n    .users-input .select-kit.multi-select {\\n      width: 100%;\\n    }\\n  }\\n\\n  #reply-title {\\n    margin-bottom: 0.5em;\\n    flex-basis: 50%;\\n    width: unset;\\n\\n    &:focus {\\n      box-shadow: none;\\n    }\\n  }\\n\\n  .category-input + .tags-input {\\n    width: auto;\\n    max-width: calc(50% - 0.25em);\\n  }\\n\\n  .tags-input {\\n    position: relative;\\n    margin: 0 0 0.5em 0;\\n    flex-grow: 1;\\n\\n    @include viewport.until(sm) {\\n      width: 100%;\\n      max-width: 50%;\\n    }\\n\\n    .mini-tag-chooser {\\n      z-index: z(\\"composer\\", \\"dropdown\\");\\n      width: 100%;\\n\\n      .select-kit-header {\\n        color: var(--primary-high);\\n      }\\n    }\\n  }\\n\\n  .wmd-controls {\\n    position: relative;\\n    display: flex;\\n    flex-direction: column;\\n    flex-grow: 1;\\n    min-height: 0;\\n\\n    .mobile-view & {\\n      &:not(.toolbar-visible) {\\n        .d-editor-button-bar {\\n          display: none;\\n        }\\n      }\\n    }\\n  }\\n\\n  .submit-panel {\\n    align-items: center;\\n    display: flex;\\n    flex-shrink: 0;\\n    margin-top: 0.5em;\\n\\n    @include viewport.until(sm) {\\n      flex-wrap: wrap;\\n      gap: 0.25em 0;\\n\\n      .create {\\n        max-width: 50vw;\\n\\n        span {\\n          @include ellipsis;\\n        }\\n      }\\n    }\\n\\n    .mobile-file-upload {\\n      &.hidden + .mobile-preview {\\n        // Hide preview button while file is uploading to make room for upload progress\\n        display: none;\\n      }\\n    }\\n\\n    .mobile-preview {\\n      margin-left: 0.25em;\\n    }\\n  }\\n\\n  .save-or-cancel {\\n    align-items: center;\\n    display: flex;\\n    flex: 0 1 auto;\\n    gap: var(--space-2);\\n\\n    @include viewport.until(sm) {\\n      margin-right: 0.5em;\\n      flex: 1 1 auto;\\n    }\\n\\n    .d-combo-button-button .d-icon {\\n      margin-right: 0.45em;\\n    }\\n\\n    .d-c .cancel {\\n      align-items: center;\\n      display: flex;\\n      margin-left: 1em;\\n      line-height: normal;\\n      color: var(--accent-color);\\n      transition: color 250ms;\\n      padding: 0;\\n\\n      &:hover,\\n      &:focus {\\n        outline: none;\\n        color: var(--danger);\\n      }\\n\\n      &:active {\\n        background-color: transparent;\\n        background-image: none;\\n      }\\n\\n      @include viewport.until(sm) {\\n        .d-icon {\\n          font-size: var(--font-up-2);\\n          color: var(--primary-medium);\\n          padding: 0.35em;\\n        }\\n      }\\n    }\\n\\n    .preview-template {\\n      margin-left: 0.5rem;\\n    }\\n  }\\n\\n  .discard-button {\\n    &:hover {\\n      color: var(--danger);\\n    }\\n\\n    @include viewport.until(sm) {\\n      .d-icon {\\n        color: var(--primary-medium);\\n      }\\n    }\\n  }\\n\\n  #draft-status,\\n  #file-uploading {\\n    color: var(--primary-high);\\n    margin-right: 0.5em;\\n\\n    @include viewport.until(sm) {\\n      margin-left: 0.5em;\\n    }\\n\\n    @include viewport.from(sm) {\\n      text-align: right;\\n    }\\n  }\\n\\n  #file-uploading {\\n    display: flex;\\n    align-items: center;\\n    margin-right: auto;\\n\\n    a {\\n      margin-left: 0.33em;\\n      color: var(--primary-high);\\n    }\\n\\n    .spinner {\\n      margin-right: 0.33em;\\n    }\\n  }\\n\\n  #draft-status {\\n    margin-left: auto;\\n\\n    .d-icon-user-pen {\\n      color: var(--danger);\\n      font-size: 20px;\\n      vertical-align: -5.5px;\\n    }\\n  }\\n\\n  .composer-select-form-template {\\n    margin-bottom: 8px;\\n    width: 100%;\\n\\n    .name,\\n    .formatted-selection,\\n    .d-icon {\\n      color: var(--primary-high);\\n    }\\n  }\\n\\n  .select-kit.is-expanded {\\n    z-index: z(\\"composer\\", \\"dropdown\\") + 1;\\n\\n    &.user-chooser {\\n      // keeps user chooser a layer above AI autocomplete\\n      z-index: z(\\"composer\\", \\"dropdown\\") + 2;\\n    }\\n  }\\n\\n  @include viewport.from(sm) {\\n    &.private-message {\\n      .with-tags {\\n        .title-and-category {\\n          flex-wrap: nowrap;\\n          gap: var(--space-2);\\n\\n          .tags-input {\\n            max-width: 50%;\\n            flex: 1 1 auto;\\n          }\\n        }\\n\\n        .title-input {\\n          max-width: 50%;\\n          min-width: 0;\\n\\n          input {\\n            min-width: 0;\\n          }\\n        }\\n      }\\n\\n      #private-message-users,\\n      .users-input {\\n        width: 100%;\\n        flex: 0 0 auto;\\n\\n        &.can-warn {\\n          // space for warning, inverse of mini-tag-chooser width\\n          width: 60%;\\n        }\\n      }\\n\\n      .add-warning {\\n        flex: 1 1 auto;\\n        overflow: hidden;\\n\\n        span {\\n          // protects the space of the user input in case there's a very long translation\\n          @include ellipsis;\\n        }\\n      }\\n    }\\n  }\\n\\n  &.closed {\\n    .grippie {\\n      display: none;\\n    }\\n  }\\n}\\n\\n.md-table {\\n  overflow-y: auto;\\n  margin: 1em 0;\\n\\n  .mobile-view & {\\n    table {\\n      width: 100%;\\n    }\\n  }\\n}\\n\\n.toggle-preview {\\n  margin-left: auto;\\n  transition: all 0.33s ease-out;\\n\\n  &.active {\\n    transform: rotate(180deg);\\n  }\\n\\n  .d-icon {\\n    color: var(--primary-medium);\\n  }\\n}\\n\\n.draft-error {\\n  color: var(--danger);\\n}\\n\\n@keyframes blink_input_opacity_to_prevent_scrolling_when_focus {\\n  0% {\\n    opacity: 0;\\n  }\\n\\n  100% {\\n    opacity: 1;\\n  }\\n}\\n\\n// Limiting to hover: none ensures we don't target touch-enabled desktops here\\n@media (hover: none) {\\n  // This targets mobile/iPad/tablets and it goes together with\\n  // the interactive-widget=resizes-content in the viewport meta tag\\n  // for maximum browser compatibility (including Firefox on Android)\\n  // see https://developer.chrome.com/blog/viewport-resize-behavior for context\\n  .discourse-touch,\\n  .mobile-device {\\n    #reply-control {\\n      // this might be overkill\\n      // but on iPad with a physical keyboard the composer is shifted up on scroll\\n      // this adds a solid box shadow below, looks cleaner\\n      box-shadow: 0 150px 0 0 var(--secondary);\\n\\n      &.open {\\n        z-index: z(\\"mobile-composer\\");\\n      }\\n\\n      &.draft,\\n      &.saving {\\n        padding-bottom: env(safe-area-inset-bottom);\\n      }\\n\\n      .toggle-fullscreen {\\n        display: none;\\n      }\\n\\n      .submit-panel,\\n      .composer-fields {\\n        // prevents accidental scroll-panning from bubbling up while still\\n        // allowing the browser's pinch-zoom gesture\\n        touch-action: pinch-zoom;\\n      }\\n    }\\n\\n    &.keyboard-visible #reply-control.open {\\n      height: calc(var(--composer-vh, 1vh) * 100);\\n\\n      .grippie {\\n        display: none;\\n      }\\n\\n      .reply-area {\\n        padding-bottom: 0.375em;\\n      }\\n    }\\n\\n    &.composer-open .with-topic-progress {\\n      bottom: calc(var(--composer-height));\\n    }\\n  }\\n}\\n\\n.mobile-device {\\n  #reply-control {\\n    .grippie {\\n      display: none;\\n    }\\n\\n    &.show-preview {\\n      .submit-panel {\\n        padding-top: 0.5em;\\n        z-index: z(\\"fullscreen\\") + 1;\\n        background-color: var(--secondary);\\n\\n        .cancel,\\n        .mobile-file-upload,\\n        .mobile-preview {\\n          display: none;\\n        }\\n      }\\n\\n      .d-editor-preview-wrapper {\\n        position: absolute;\\n        z-index: z(\\"fullscreen\\");\\n        top: 0;\\n        bottom: 0;\\n        left: 0;\\n        right: 0;\\n        background-color: var(--secondary);\\n        border-bottom: 40px solid var(--secondary);\\n        max-width: 100%;\\n        margin: 0;\\n        padding: 0.5em;\\n        overflow: auto;\\n\\n        .d-editor-preview {\\n          margin-bottom: 40px;\\n        }\\n      }\\n\\n      .composer-controls {\\n        display: none;\\n      }\\n    }\\n  }\\n}\\n\\n// Safari in iOS/iPad does not handle well a bottom:0 fixed-positioned element,\\n// especially while the software keyboard is visible, so we top-anchor it here\\n// and shift it using transform\\n.ipados-device {\\n  body:not(.peek-mode-active) {\\n    #reply-control {\\n      // the two properties below are equivalent to bottom: 0\\n      top: calc(var(--composer-vh, 1vh) * 100);\\n      transform: translateY(-100%);\\n      bottom: unset;\\n    }\\n  }\\n}\\n\\n.ios-device {\\n  &.footer-nav-visible {\\n    #reply-control {\\n      bottom: calc(var(--footer-nav-height, 0px) + env(safe-area-inset-bottom));\\n    }\\n\\n    #reply-control.draft,\\n    #reply-control.saving {\\n      margin-top: calc(\\n        (var(--footer-nav-height) + env(safe-area-inset-bottom)) * -1\\n      );\\n      padding-bottom: 0;\\n    }\\n  }\\n\\n  // When an element (input, textearea) gets focus, iOS Safari tries to put it in the center\\n  // by scrolling and zooming. We handle zooming with a meta tag. We used to handle scrolling\\n  // using a complicated JS hack.\\n  //\\n  // However, iOS Safari doesn't scroll when the input has opacity of 0 or is clipped.\\n  // We use this quirk and temporarily hide the element on focus\\n  //\\n  // Source https://gist.github.com/kiding/72721a0553fa93198ae2bb6eefaa3299\\n  input:focus,\\n  textarea:focus,\\n  [contenteditable=\\"true\\"]:focus-within {\\n    animation: blink_input_opacity_to_prevent_scrolling_when_focus 0.01s;\\n  }\\n}\\n\\n.composer-popup {\\n  box-sizing: border-box;\\n  position: absolute;\\n  width: calc(60%);\\n  max-height: 50%;\\n  bottom: 4.2rem;\\n  right: 1rem;\\n  overflow-y: auto;\\n  z-index: z(\\"composer\\", \\"dropdown\\") + 1;\\n  box-shadow: var(--shadow-dropdown);\\n  border-radius: var(--d-border-radius-large);\\n  background: var(--composer-popup-background);\\n  display: flex;\\n  flex-direction: column;\\n\\n  &__content {\\n    padding: 0 2rem 2rem;\\n  }\\n\\n  .show-preview & {\\n    right: 1.5rem;\\n    bottom: 4.2rem;\\n    width: calc(50% - 2rem);\\n  }\\n\\n  .blurb {\\n    display: none;\\n  }\\n\\n  p,\\n  h3 {\\n    &:first-of-type {\\n      margin-top: 0;\\n      margin-right: 3rem;\\n    }\\n\\n    &:last-child {\\n      margin-bottom: 0;\\n    }\\n  }\\n\\n  &.urgent {\\n    --composer-popup-background: var(--danger-low);\\n  }\\n\\n  &.education-message {\\n    --composer-popup-background: var(--tertiary-low);\\n  }\\n\\n  &.dominating-topic-message,\\n  &.get-a-room {\\n    bottom: unset;\\n    top: 4rem;\\n\\n    p {\\n      font-size: var(--font-up-1);\\n    }\\n\\n    button:not(.close) {\\n      margin-top: 0.5em;\\n    }\\n  }\\n\\n  h3 {\\n    margin-bottom: 10px;\\n  }\\n\\n  .btn.close {\\n    flex-direction: row-reverse;\\n    align-items: center;\\n    position: sticky;\\n    top: 0;\\n    color: var(--primary-medium);\\n    font-size: var(--font-0);\\n    align-self: end;\\n    background: var(--composer-popup-background);\\n    border-radius: 0 0 0 var(--d-button-border-radius);\\n\\n    .d-icon {\\n      color: currentcolor;\\n      font-size: var(--font-up-1);\\n      margin: 0 0 0 0.25em;\\n    }\\n\\n    .discourse-no-touch & {\\n      &:active,\\n      &:focus {\\n        .d-icon {\\n          color: var(--primary);\\n        }\\n      }\\n    }\\n  }\\n\\n  ul {\\n    margin: 0;\\n    padding: 0 0 0 var(--space-6);\\n\\n    &.list,\\n    &.topics {\\n      list-style: none;\\n      padding: 0;\\n    }\\n\\n    li {\\n      font-weight: normal;\\n      margin-top: var(--space-2);\\n    }\\n  }\\n\\n  .discourse-tags {\\n    font-size: var(--font-down-1);\\n    padding: 0;\\n\\n    li {\\n      margin: 0;\\n    }\\n  }\\n}\\n\\n.custom-body {\\n  background-color: var(--tertiary-low);\\n\\n  p {\\n    max-width: 98%;\\n  }\\n}\\n\\n.similar-topics {\\n  .similar-topic {\\n    &:not(:last-child) {\\n      margin-bottom: 0.5em;\\n    }\\n  }\\n\\n  .topic {\\n    display: flex;\\n    flex-wrap: wrap;\\n\\n    .first-line {\\n      width: 100%;\\n      line-height: var(--line-height-medium);\\n    }\\n\\n    .second-line {\\n      display: flex;\\n      flex-wrap: wrap;\\n      gap: 0 var(--space-2);\\n    }\\n  }\\n\\n  .topic-title {\\n    margin-bottom: 0.5em;\\n    flex: 0 1 auto;\\n    margin-right: 0.5em;\\n\\n    .d-icon {\\n      color: var(--primary-high);\\n    }\\n  }\\n}\\n\\n.fullscreen-composer {\\n  overflow: hidden;\\n\\n  .profiler-results {\\n    display: none;\\n  }\\n\\n  #reply-control {\\n    &.fullscreen {\\n      // important needed because of inline styles when height is changed manually with grippie\\n      height: calc(var(--composer-vh, 1vh) * 100) !important;\\n      max-height: 100%; // prevents devices from miscalculating using vh\\n      z-index: z(\\"header\\") + 1;\\n\\n      .grippie {\\n        display: none;\\n      }\\n\\n      .d-editor-preview-wrapper {\\n        margin-top: 1%;\\n      }\\n\\n      .reply-to {\\n        border-bottom: 1px solid var(--content-border-color);\\n        margin-bottom: 0;\\n        padding-bottom: 8px;\\n      }\\n\\n      .d-editor-textarea-wrapper {\\n        border: none;\\n      }\\n\\n      &.show-preview .d-editor-textarea-wrapper {\\n        border-right: 1px solid var(--content-border-color);\\n      }\\n\\n      #draft-status,\\n      #file-uploading {\\n        margin-left: 0;\\n        text-align: initial;\\n      }\\n\\n      &::before {\\n        content: \\"\\";\\n        background: var(--secondary);\\n        width: 100%;\\n        height: 100%;\\n        position: fixed;\\n        z-index: -1;\\n        left: 0;\\n      }\\n    }\\n  }\\n}\\n\\n.composer-fullscreen-prompt {\\n  animation: fadeIn 1s ease-in-out;\\n  animation-delay: 1.5s;\\n  animation-direction: reverse;\\n  animation-fill-mode: forwards;\\n  position: fixed;\\n  left: 50%;\\n  top: 10%;\\n  transform: translate(-50%, 0);\\n  z-index: z(\\"header\\") + 1;\\n  background: var(--primary-very-high);\\n  color: var(--secondary);\\n  padding: 0.5em 0.75em;\\n  pointer-events: none;\\n  border-radius: 2px;\\n\\n  @media (prefers-reduced-motion) {\\n    animation-duration: 0s;\\n  }\\n\\n  .rtl & {\\n    // R2 is not smart enough to support this swap\\n    transform: translate(50%, 0);\\n  }\\n\\n  kbd {\\n    background: none;\\n  }\\n}\\n\\n// align the previewless composer with the topic content\\n#reply-control:not(.fullscreen).hide-preview {\\n  --composer-internal-padding: 1em;\\n  --layout-gap: 2em;\\n  --topic-width: calc(\\n    var(--topic-body-width) + (var(--topic-body-width-padding) * 2)\\n  );\\n  width: 100%;\\n  max-width: calc(var(--topic-width) + var(--topic-avatar-width));\\n}\\n\\nbody:not(.has-sidebar-page) {\\n  #reply-control:not(.fullscreen).hide-preview {\\n    margin-left: 0.67em;\\n\\n    // 1100px is equivalent to --d-max-width\\n    @media screen and (width >= 1110px) {\\n      margin-left: calc(((100% - var(--d-max-width)) / 2) + 0.67em);\\n    }\\n\\n    // 790px is equivalent to --topic-width\\n    @media screen and (width < 790px) {\\n      max-width: calc(100% - calc(0.67em * 2));\\n      margin-left: 0.67em;\\n    }\\n\\n    @include viewport.until(sm) {\\n      max-width: unset;\\n      margin-inline: unset;\\n    }\\n  }\\n}\\n\\nbody.has-sidebar-page {\\n  #reply-control:not(.fullscreen).hide-preview {\\n    margin-left: calc(var(--d-sidebar-width) + var(--layout-gap));\\n\\n    // 1390px is equivalent to --d-max-width + --d-sidebar-width\\n    @media screen and (width >= 1390px) {\\n      left: calc(\\n        (100% - var(--d-max-width) + var(--d-sidebar-width)) / 2\\n      ); // 50% of the whitespace\\n      margin-left: var(--layout-gap);\\n    }\\n\\n    // This is when the topic width starts to shrink\\n    @media screen and (width <= 1180px) {\\n      width: calc(100% - var(--d-sidebar-width) - var(--layout-gap) - 0.67em);\\n    }\\n\\n    // sidebar shrinks\\n    @media screen and (width <= 1000px) {\\n      --layout-gap: 1em;\\n      margin-left: calc(var(--d-sidebar-width) + var(--layout-gap));\\n    }\\n  }\\n}\\n\\n.composer-toggle-item {\\n  cursor: pointer;\\n\\n  @include menu-item;\\n\\n  &__icons .d-toggle-switch {\\n    --toggle-switch-width: var(--d-sidebar-section-link-prefix-width);\\n    --toggle-switch-height: 16px;\\n  }\\n\\n  &__icons .d-toggle-switch__checkbox-slider .d-icon {\\n    display: none;\\n  }\\n}\\n","// --------------------------------------------------\\n// Variables used throughout the theme\\n// this file is injected into every theme CSS file\\n// --------------------------------------------------\\n\\n// Layout dimensions\\n// --------------------------------------------------\\n\\n@use \\"sass:color\\";\\n@use \\"sass:math\\";\\n@use \\"sass:meta\\";\\n@use \\"math\\" as discourse-math;\\n\\n$small-width: 800px !default;\\n$medium-width: 995px !default;\\n$large-width: 1110px !default;\\n$topic-body-width: 690px;\\n$topic-body-width-padding: 11px;\\n$topic-avatar-width: 45px;\\n$reply-area-max-width: 1475px !default;\\n$d-sidebar-width: 17em !default;\\n$d-sidebar-narrow-width: 14em !default;\\n\\n// Brand color variables\\n// --------------------------------------------------\\n\\n$google: #fff !default;\\n$google-hover: color.adjust($google, $lightness: -5%) !default;\\n$instagram: #e1306c !default;\\n$instagram-hover: color.adjust($instagram, $lightness: -15%) !default;\\n$facebook: #0866ff !default;\\n$facebook-hover: color.adjust($facebook, $lightness: -15%) !default;\\n$cas: #70ba61 !default;\\n$twitter: #000 !default;\\n$github: #100e0f !default;\\n$github-hover: color.adjust($github, $lightness: 20%) !default;\\n$discord: #7289da !default;\\n$discord-hover: color.adjust($discord, $lightness: -10%) !default;\\n\\n// Discourse brand colors (used in wizard, omniauth confirm, etc.)\\n$discourse-brand: #7b5fe2 !default;\\n$discourse-brand-100: #f4f2fc !default;\\n$discourse-brand-300: #b8a4ff !default;\\n$discourse-brand-400: #8b6df8 !default;\\n$discourse-brand-800: #3a275e !default;\\n$discourse-brand-light: #e1d5ff !default;\\n$discourse-bg-light: #f9f8fc !default;\\n$discourse-bg-dark: #02030a !default;\\n\\n// Badge color variables\\n// --------------------------------------------------\\n\\n$gold: rgb(231, 195, 0) !default;\\n$silver: #c0c0c0 !default;\\n$bronze: #cd7f32 !default;\\n\\n// Fonts\\n// --------------------------------------------------\\n\\n$base-font-family: var(--font-family) !default;\\n$base-font-size-smallest: var(--base-font-size-smallest) !default;\\n$base-font-size-smaller: var(--base-font-size-smaller) !default;\\n$base-font-size: var(--base-font-size) !default;\\n$base-font-size-larger: var(--base-font-size-larger) !default;\\n$base-font-size-largest: var(--base-font-size-largest) !default;\\n$heading-font-family: var(--heading-font-family) !default;\\n\\n// Font-size definitions, multiplier ^ (step / interval)\\n$font-up-6: var(--font-up-6) !default;\\n$font-up-5: var(--font-up-5) !default;\\n$font-up-4: var(--font-up-4) !default;\\n$font-up-3: var(--font-up-3) !default;\\n$font-up-2: var(--font-up-2) !default;\\n$font-up-1: var(--font-up-1) !default;\\n$font-0: var(--font-0);\\n$font-down-1: var(--font-down-1) !default;\\n$font-down-2: var(--font-down-2) !default;\\n$font-down-3: var(--font-down-3) !default;\\n$font-down-4: var(--font-down-4) !default;\\n$font-down-5: var(--font-down-5) !default;\\n$font-down-6: var(--font-down-6) !default;\\n\\n// Common line-heights\\n$line-height-small: var(--line-height-small) !default;\\n$line-height-medium: var(--line-height-medium) !default;\\n$line-height-large: var(--line-height-large) !default;\\n\\n// Z-index\\n// --------------------------------------------------\\n\\n$z-layers: (\\n  \\"max\\": 9999,\\n  \\"modal\\": (\\n    \\"dialog\\": 1700,\\n    \\"tooltip\\": 1600,\\n    \\"popover\\": 1500,\\n    \\"dropdown\\": 1400,\\n    \\"content\\": 1300,\\n    \\"overlay\\": 1200,\\n  ),\\n  // below modals, so dialogs opened from the page behind it stay reachable\\n  \\"design-wizard\\": 1160,\\n  \\"fullscreen\\": 1150,\\n  \\"mobile-header\\": 1150,\\n  \\"mobile-composer\\": 1100,\\n  \\"ipad-header-nav\\": 1020,\\n  \\"header\\": 1000,\\n  \\"footer-nav\\": 900,\\n  \\"tooltip\\": 600,\\n  \\"usercard\\": 500,\\n  \\"composer\\": (\\n    \\"dropdown\\": 700,\\n    \\"tooltip\\": 600,\\n    \\"popover\\": 500,\\n    \\"content\\": 400,\\n  ),\\n  \\"dropdown\\": 300,\\n  \\"chat-drawer\\": 200,\\n  \\"timeline\\": 100,\\n  \\"base\\": 1,\\n);\\n\\n@function map-has-nested-keys($map, $keys...) {\\n  @each $key in $keys {\\n    /* stylelint-disable-next-line scss/no-global-function-names */\\n    @if not map-has-key($map, $key) {\\n      @return false;\\n    }\\n\\n    /* stylelint-disable-next-line scss/no-global-function-names */\\n    $map: map-get($map, $key);\\n  }\\n\\n  @return true;\\n}\\n\\n@function map-deep-get($map, $keys...) {\\n  @each $key in $keys {\\n    /* stylelint-disable-next-line scss/no-global-function-names */\\n    $map: map-get($map, $key);\\n  }\\n\\n  @return $map;\\n}\\n\\n@function z($layers...) {\\n  @if not map-has-nested-keys($z-layers, $layers...) {\\n    @warn \\"No layer defined for `#{meta.inspect($layers...)}` in $z-layers map- Check variables.scss, property omitted.\\";\\n  }\\n\\n  @return map-deep-get($z-layers, $layers...);\\n}\\n\\n// Color utilities\\n// --------------------------------------------------\\n\\n// w3c definition of color brightness https://www.w3.org/TR/AERT#color-contrast\\n@function dc-color-brightness($color) {\\n  @return (\\n    (color.red($color) * 0.299) + (color.green($color) * 0.587) +\\n      (color.blue($color) * 0.114)\\n  );\\n}\\n\\n// Uses an approximation of sRGB blending, GAMMA=2 instead of GAMMA=2.2\\n@function srgb-scale($foreground, $background, $percent) {\\n  $ratio: math.div($percent, 100%);\\n  $iratio: 1 - $ratio;\\n  $f_r2: color.red($foreground) * color.red($foreground);\\n  $f_g2: color.green($foreground) * color.green($foreground);\\n  $f_b2: color.blue($foreground) * color.blue($foreground);\\n  $b_r2: color.red($background) * color.red($background);\\n  $b_g2: color.green($background) * color.green($background);\\n  $b_b2: color.blue($background) * color.blue($background);\\n  $r_r2: $f_r2 * $ratio + $b_r2 * $iratio;\\n  $r_g2: $f_g2 * $ratio + $b_g2 * $iratio;\\n  $r_b2: $f_b2 * $ratio + $b_b2 * $iratio;\\n  $r_r: discourse-math.sqrt($r_r2);\\n  $r_g: discourse-math.sqrt($r_g2);\\n  $r_b: discourse-math.sqrt($r_b2);\\n\\n  @return rgb($r_r, $r_g, $r_b);\\n}\\n\\n// Replaces dark-light-diff($primary,50%)\\n@function blend-two-colors($color1, $color2, $percent) {\\n  @return srgb-scale($color1, $color2, $percent);\\n}\\n\\n@function blend-header-primary-background($percent) {\\n  @return srgb-scale($header_primary, $header_background, $percent);\\n}\\n\\n@function dark-light-diff(\\n  $adjusted-color,\\n  $comparison-color,\\n  $lightness,\\n  $darkness\\n) {\\n  @if dc-color-brightness($adjusted-color) <\\n    dc-color-brightness($comparison-color)\\n  {\\n    @return color.scale($adjusted-color, $lightness: $lightness);\\n  } @else {\\n    @return color.scale($adjusted-color, $lightness: $darkness);\\n  }\\n}\\n\\n@function dark-light-choose($light-theme-result, $dark-theme-result) {\\n  @if is-light-color-scheme() {\\n    @return $light-theme-result;\\n  } @else {\\n    @return $dark-theme-result;\\n  }\\n}\\n\\n@function is-light-color-scheme() {\\n  @if dc-color-brightness($primary) < dc-color-brightness($secondary) {\\n    @return true;\\n  } @else {\\n    @return false;\\n  }\\n}\\n\\n@function is-dark-color-scheme() {\\n  @return not is-light-color-scheme();\\n}\\n\\n@import \\"color_transformations\\";\\n","@use \\"lib/viewport\\";\\n\\n// IMPORTANT: This stylesheet needs to work for super old browsers, including those\\n// without support for `var()`. Therefore every color definition needs to define a simple\\n// value first, as a fallback\\nbody.crawler,\\nbody > noscript {\\n  font-family: serif;\\n\\n  h1,\\n  h2,\\n  h3,\\n  h4,\\n  h5,\\n  h6 {\\n    font-family: serif;\\n  }\\n\\n  &.browser-update {\\n    header {\\n      height: 50px;\\n      margin-bottom: 1em;\\n    }\\n\\n    .buorg {\\n      position: absolute;\\n      top: 50px;\\n      width: 100%;\\n      background: #fdf2ab;\\n      text-align: center;\\n      font-family: sans-serif;\\n      color: #000;\\n      font-size: 14px;\\n      margin-bottom: 10px;\\n    }\\n\\n    #topic-title {\\n      margin-top: 2em;\\n    }\\n  }\\n\\n  &::after,\\n  &::before {\\n    // common way to show fixed background images\\n    display: none;\\n  }\\n\\n  a {\\n    // we want all links to look like links\\n    color: var(--tertiary) !important;\\n    text-decoration: underline !important;\\n  }\\n\\n  > header {\\n    // site header\\n    box-sizing: border-box;\\n    width: 100%;\\n    top: 0;\\n    background-color: var(--header_background);\\n    padding: 10px;\\n    box-shadow: none;\\n    border-bottom: 1px solid var(--header_primary-medium);\\n  }\\n\\n  .header-buttons {\\n    display: none;\\n  }\\n\\n  // topic list\\n  div#main-outlet {\\n    padding: 10px;\\n\\n    div.post {\\n      overflow: auto;\\n      max-width: 100%;\\n      word-break: break-word;\\n\\n      img {\\n        max-width: 100%;\\n        height: auto;\\n      }\\n    }\\n\\n    .topic-body {\\n      float: unset;\\n    }\\n  }\\n\\n  .topic-list {\\n    table-layout: fixed;\\n    overflow: hidden;\\n    margin: 2em 0;\\n\\n    thead {\\n      border-bottom: 1px solid var(--primary_low);\\n\\n      th {\\n        padding: 0 0 0.5em;\\n      }\\n\\n      th:nth-child(2) {\\n        display: none;\\n      }\\n\\n      th:first-of-type {\\n        width: 60%;\\n        padding-left: 0;\\n      }\\n\\n      th:last-of-type,\\n      th.replies,\\n      th.views {\\n        text-align: center;\\n      }\\n\\n      th:last-of-type,\\n      th.replies {\\n        width: 20%;\\n      }\\n\\n      th.posters {\\n        display: none;\\n      }\\n    }\\n\\n    td {\\n      padding: 10px 0;\\n    }\\n\\n    td.posters {\\n      display: none;\\n    }\\n\\n    td:last-of-type,\\n    td.replies,\\n    td.views {\\n      text-align: center;\\n    }\\n\\n    td:first-of-type {\\n      width: 60%;\\n    }\\n\\n    td:last-of-type,\\n    td.replies {\\n      width: 20%;\\n    }\\n\\n    @media (width <= 850px) {\\n      table-layout: auto;\\n      margin: 0;\\n\\n      td {\\n        word-break: break-word;\\n\\n        &.posters {\\n          a:not(:last-of-type) {\\n            display: none;\\n          }\\n\\n          a:last-of-type {\\n            display: block;\\n          }\\n        }\\n      }\\n\\n      td,\\n      th {\\n        &.views {\\n          display: none;\\n        }\\n      }\\n\\n      .link-top-line {\\n        a.title {\\n          padding: 0;\\n        }\\n      }\\n\\n      .link-bottom-line {\\n        margin-top: 0.25em;\\n      }\\n    }\\n\\n    .topic-list-item {\\n      border-bottom: 1px solid var(--content-border-color);\\n\\n      > * {\\n        padding: 0.75em 0;\\n      }\\n\\n      td.main-link {\\n        padding-right: 1em;\\n      }\\n\\n      p.excerpt {\\n        font-size: var(--font-down-1);\\n      }\\n    }\\n  }\\n\\n  .topic-category {\\n    display: inline;\\n  }\\n\\n  .topic-list-main-link a.title,\\n  .topic-list .main-link a.title,\\n  .latest-topic-list-item .main-link a.title {\\n    padding: 0;\\n  }\\n\\n  .topic-list .link-bottom-line {\\n    margin-top: 0.25em;\\n  }\\n\\n  .crawler-post {\\n    margin-top: 1em;\\n    margin-bottom: 2em;\\n    padding-top: 1.5em;\\n    border-top: 1px solid var(--content-border-color);\\n  }\\n\\n  .crawler-post-meta {\\n    margin-bottom: 1em;\\n\\n    .creator {\\n      word-break: break-all;\\n\\n      a {\\n        font-weight: bold;\\n      }\\n\\n      @include viewport.until(md) {\\n        display: inline-block;\\n        margin-bottom: 0.25em;\\n      }\\n    }\\n  }\\n\\n  .crawler-post-infos {\\n    color: #666;\\n    display: inline-block;\\n\\n    @include viewport.from(md) {\\n      float: right;\\n    }\\n\\n    [itemprop=\\"position\\"] {\\n      float: left;\\n      margin-right: 0.5em;\\n    }\\n  }\\n\\n  .crawler-linkback-list {\\n    margin-top: 1em;\\n\\n    a {\\n      display: block;\\n      padding: 0.5em 0;\\n      border-top: 1px solid var(--content-border-color);\\n    }\\n  }\\n\\n  .tag-crawler {\\n    .tag-box {\\n      margin-bottom: 0.5em;\\n    }\\n  }\\n\\n  #topic-title {\\n    > * {\\n      display: block;\\n    }\\n\\n    h1 {\\n      margin-bottom: 0.25em;\\n    }\\n  }\\n\\n  .poll-info {\\n    // crawler vote count always shows 0\\n    display: none;\\n  }\\n\\n  pre,\\n  code,\\n  blockquote,\\n  aside.quote .title {\\n    background: var(--primary-low);\\n  }\\n\\n  .md-table {\\n    tr {\\n      border: 1px solid var(--content-border-color);\\n    }\\n\\n    th {\\n      font-weight: bold;\\n    }\\n\\n    td,\\n    th {\\n      padding: 0.25em;\\n      border-right: 1px solid var(--content-border-color);\\n    }\\n  }\\n\\n  // footer\\n  footer {\\n    margin-top: 2em;\\n  }\\n\\n  .noscript-footer-nav {\\n    margin-top: 4em;\\n\\n    a {\\n      margin-right: 0.25em;\\n      white-space: nowrap;\\n    }\\n  }\\n\\n  #noscript-footer {\\n    padding: 0 10px;\\n    text-align: center;\\n  }\\n\\n  .crawler-nav {\\n    margin: 1em 0;\\n\\n    ul {\\n      margin: 0;\\n      list-style-type: none;\\n    }\\n\\n    li {\\n      display: inline-block;\\n    }\\n\\n    a {\\n      display: inline-block;\\n      padding: 0.5em 1em 0.5em 0;\\n    }\\n  }\\n}\\n\\n.buorg div {\\n  padding: 8px;\\n}\\n\\n.buorg a,\\n.buorg a:visited {\\n  color: #e25600;\\n  text-decoration: underline;\\n}\\n\\n@media print {\\n  .buorg {\\n    display: none !important;\\n  }\\n}\\n\\n.user-crawler {\\n  .username {\\n    margin-left: 5px;\\n    display: inline-block;\\n  }\\n}\\n",".d-icon.d-icon-d-regular,\\n.d-icon.d-icon-d-muted,\\n.d-icon.d-icon-d-watching-first,\\n.d-icon.d-icon-d-watching-first-post {\\n  color: var(--primary-high);\\n}\\n\\n.d-icon.d-icon-d-tracking,\\n.d-icon.d-icon-d-unread,\\n.d-icon.d-icon-d-watching {\\n  color: var(--tertiary);\\n}\\n",".d-image-grid:not([data-disabled]) {\\n  $grid-column-gap: 6px;\\n\\n  &[data-columns] {\\n    display: flex;\\n    flex-wrap: wrap;\\n  }\\n\\n  &[data-columns=\\"2\\"] > * {\\n    flex-basis: calc(50% - ($grid-column-gap / 2));\\n    margin-right: $grid-column-gap;\\n  }\\n\\n  &[data-columns=\\"3\\"] > * {\\n    flex-basis: calc(33.33% - ($grid-column-gap * 0.667));\\n    margin-right: $grid-column-gap;\\n  }\\n\\n  .d-image-grid-column {\\n    box-sizing: border-box;\\n\\n    // use flex layout, flex-grow and object-fit: cover\\n    // to better have the images fill their containers\\n    // and line up vertically (it's not perfect!)\\n    display: flex;\\n    flex-direction: column;\\n    justify-content: flex-start;\\n\\n    .button-wrapper {\\n      bottom: 0;\\n      min-width: unset;\\n    }\\n\\n    > div,\\n    > span {\\n      flex-grow: 1;\\n      overflow: hidden;\\n\\n      // hardcoded max-height here prevents extra tall images\\n      // from having an outsized effect on the grid\\n      max-height: 1200px;\\n\\n      img:not(.thumbnail, .ytp-thumbnail-image, .emoji) {\\n        height: 100%;\\n        object-fit: cover;\\n      }\\n    }\\n\\n    &:last-child {\\n      margin-right: 0;\\n    }\\n\\n    > img,\\n    > div {\\n      margin-bottom: $grid-column-gap;\\n    }\\n\\n    // Forces images in the grid to fill each column width-wise\\n    img,\\n    > .lightbox-wrapper,\\n    > .lightbox-wrapper > .lightbox {\\n      width: 100%;\\n    }\\n\\n    .lightbox-wrapper {\\n      .meta .informations {\\n        display: none;\\n      }\\n\\n      .meta .filename {\\n        flex-grow: 3;\\n      }\\n\\n      // full-height lightbox element in container\\n      > .lightbox {\\n        height: 100%;\\n      }\\n    }\\n\\n    // when staging edits\\n    .image-wrapper {\\n      display: block;\\n      margin-bottom: $grid-column-gap;\\n      padding-bottom: 0;\\n    }\\n  }\\n\\n  .d-editor-preview & {\\n    .image-wrapper {\\n      margin-bottom: $grid-column-gap;\\n      padding-bottom: 0;\\n\\n      .button-wrapper {\\n        .scale-btn-container,\\n        &[editing] .wrap-image-grid-button {\\n          display: none;\\n        }\\n      }\\n    }\\n  }\\n}\\n\\n.d-image-carousel {\\n  position: relative;\\n  width: 100%;\\n  display: flex;\\n  flex-direction: column;\\n  gap: var(--space-1);\\n\\n  &__track {\\n    display: flex;\\n    width: 100%;\\n    height: 400px;\\n    overflow-x: auto;\\n    overflow-y: hidden;\\n    scroll-snap-type: x mandatory;\\n    scroll-behavior: smooth;\\n    -webkit-overflow-scrolling: touch;\\n    scrollbar-width: none;\\n\\n    &::-webkit-scrollbar {\\n      display: none;\\n    }\\n  }\\n\\n  &__slide {\\n    .d-image-carousel--carousel & {\\n      flex: 0 0 100%;\\n      width: 100%;\\n      height: 100%;\\n      max-height: inherit;\\n      scroll-snap-align: center;\\n      scroll-snap-stop: always;\\n      display: flex;\\n      align-items: center;\\n      justify-content: center;\\n\\n      img:not(.thumbnail, .ytp-thumbnail-image, .emoji) {\\n        max-width: 100% !important;\\n        max-height: 100% !important;\\n        width: auto !important;\\n        height: auto !important;\\n        object-fit: contain !important;\\n        border-radius: var(--d-border-radius);\\n      }\\n    }\\n\\n    .lightbox-wrapper {\\n      position: relative;\\n      display: flex;\\n      flex-direction: column;\\n      align-items: center;\\n      justify-content: center;\\n      max-width: 100%;\\n      max-height: 100%;\\n      height: 100%;\\n\\n      // Ensure the lightbox link itself doesn't force a crop\\n      .lightbox {\\n        display: flex;\\n        align-items: center;\\n        justify-content: center;\\n        max-width: 100%;\\n        max-height: 100%;\\n      }\\n    }\\n  }\\n\\n  &__controls {\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    gap: var(--space-2);\\n    padding-block: var(--space-2);\\n  }\\n\\n  &__nav {\\n    display: inline-flex;\\n    align-items: center;\\n    justify-content: center;\\n    width: 2rem;\\n    height: 2rem;\\n    border: 0;\\n    padding: 0;\\n    background: none;\\n    color: var(--primary-medium);\\n    cursor: pointer;\\n    font-size: var(--font-down-1);\\n    touch-action: manipulation;\\n\\n    &:hover {\\n      background: none;\\n      color: var(--primary);\\n    }\\n\\n    &:disabled {\\n      cursor: default;\\n      opacity: 0.6;\\n    }\\n  }\\n\\n  &__dots {\\n    display: flex;\\n    align-items: center;\\n    gap: 0.75rem;\\n    padding: 0.5rem 0.75rem;\\n    background: var(--primary-very-low);\\n    border-radius: 1rem;\\n  }\\n\\n  &__dot {\\n    height: 0.6rem;\\n    width: 0.6rem;\\n    padding: 0;\\n    background: var(--primary-low-mid);\\n    border: none;\\n    border-radius: 1rem;\\n    cursor: pointer;\\n    transition:\\n      width 0.25s cubic-bezier(0.4, 0, 0.2, 1),\\n      background-color 0.25s cubic-bezier(0.4, 0, 0.2, 1),\\n      transform 0.15s ease-out;\\n    touch-action: manipulation;\\n\\n    &:hover {\\n      transform: scale(1.2);\\n    }\\n\\n    &.active {\\n      background: var(--primary-medium);\\n      width: 1.4rem;\\n    }\\n  }\\n\\n  &__counter {\\n    padding: 0.5rem 0.75rem;\\n    background: var(--primary-very-low);\\n    border-radius: 1rem;\\n    font-size: var(--font-down-1);\\n    color: var(--primary-medium);\\n    font-variant-numeric: tabular-nums;\\n    text-align: center;\\n  }\\n\\n  &--single {\\n    .d-image-carousel__controls {\\n      display: none;\\n    }\\n  }\\n\\n  @media (prefers-reduced-motion: reduce) {\\n    .d-image-carousel__track {\\n      scroll-behavior: auto;\\n    }\\n  }\\n}\\n",".dialog-container,\\n.dialog-overlay {\\n  position: fixed;\\n  top: 0;\\n  right: 0;\\n  bottom: 0;\\n  left: 0;\\n}\\n\\n.dialog-container {\\n  z-index: z(\\"modal\\", \\"dialog\\");\\n  display: flex;\\n\\n  // fixes modal placement on Android when keyboard is visible\\n  html.keyboard-visible:not(.ios-device) & {\\n    height: calc(100% - env(keyboard-inset-height));\\n  }\\n}\\n\\n/**\\n * Ensures the dialog container and all its descendants are not\\n * visible and not focusable when it is hidden.\\n */\\n\\n.dialog-container[aria-hidden=\\"true\\"] {\\n  display: none;\\n}\\n\\n@keyframes fade-in {\\n  from {\\n    opacity: 0;\\n  }\\n}\\n\\n.dialog-overlay {\\n  background: rgb(var(--always-black-rgb), 0.65);\\n  animation: fade-in 250ms both;\\n\\n  @media (prefers-reduced-motion) {\\n    animation-duration: 0s;\\n  }\\n}\\n\\n.dialog-content {\\n  margin: auto;\\n  z-index: z(\\"modal\\", \\"content\\");\\n  position: relative;\\n  background-color: var(--secondary);\\n  box-shadow: var(--shadow-card);\\n  min-width: 40vw;\\n  animation: fade-in 250ms both;\\n\\n  @media (prefers-reduced-motion) {\\n    animation-duration: 0s;\\n  }\\n}\\n\\n.dialog-body {\\n  overflow-y: auto;\\n  max-height: 400px;\\n  max-width: 800px;\\n  padding: 1em;\\n}\\n\\n.dialog-header {\\n  display: flex;\\n  padding: 10px 15px;\\n  border-bottom: 1px solid var(--content-border-color);\\n  align-items: start;\\n\\n  h3 {\\n    font-size: var(--font-up-3);\\n    margin-bottom: 0;\\n  }\\n\\n  .dialog-close {\\n    margin-left: auto;\\n    flex-basis: content;\\n    padding-left: 15px;\\n\\n    .d-icon {\\n      color: var(--primary-high);\\n    }\\n  }\\n}\\n\\n.dialog-footer {\\n  display: flex;\\n  flex-wrap: wrap;\\n  align-items: center;\\n  padding: 14px 15px 10px;\\n  border-top: 1px solid var(--content-border-color);\\n\\n  --btn-bottom-margin: 0.3em;\\n\\n  .btn {\\n    margin: 0 0.75em var(--btn-bottom-margin) 0;\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.horizontal-scroll-sync {\\n  &__container {\\n    width: 100%;\\n  }\\n\\n  &__top-scroll {\\n    width: 100%;\\n    overflow-x: auto;\\n  }\\n\\n  &__fake-content {\\n    pointer-events: auto;\\n  }\\n\\n  &__content {\\n    overflow-x: auto;\\n  }\\n}\\n\\n.directory {\\n  margin-bottom: 100px;\\n  background: var(--d-content-background);\\n\\n  .directory-value-list-item:not(:empty)\\n    ~ .directory-value-list-item:not(:empty)::before {\\n    content: \\"| \\";\\n  }\\n\\n  &.users-directory {\\n    .directory-group-selector {\\n      vertical-align: top;\\n    }\\n\\n    @include viewport.until(sm) {\\n      .filter-name {\\n        width: 100%;\\n      }\\n    }\\n  }\\n\\n  .user-info {\\n    margin-bottom: 0;\\n  }\\n\\n  .spinner {\\n    clear: both;\\n  }\\n\\n  .directory-controls {\\n    display: flex;\\n    justify-content: space-between;\\n\\n    @include viewport.until(sm) {\\n      display: block;\\n    }\\n\\n    .total-rows {\\n      color: var(--primary-medium);\\n      font-weight: normal;\\n\\n      @include viewport.until(sm) {\\n        display: block;\\n      }\\n    }\\n  }\\n\\n  .directory-last-updated {\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1);\\n    margin-bottom: var(--space-2);\\n\\n    @include viewport.until(sm) {\\n      margin-bottom: var(--space-1);\\n    }\\n  }\\n\\n  @include viewport.until(md) {\\n    .period-chooser .period-chooser-header h2.selected-name {\\n      font-size: var(--font-up-1);\\n    }\\n  }\\n}\\n\\n.edit-user-directory-columns-modal {\\n  .edit-directory-columns-container {\\n    .edit-directory-column {\\n      display: flex;\\n      justify-content: space-between;\\n      padding: 12px 0;\\n      border-bottom: 1px solid var(--table-border-color);\\n\\n      .column-name {\\n        display: flex;\\n        align-items: center;\\n        margin-bottom: 0;\\n      }\\n\\n      .d-icon-heart {\\n        color: var(--love);\\n        margin: 0 var(--space-1) 0 0;\\n      }\\n\\n      .move-column-up {\\n        margin-right: 5px;\\n      }\\n\\n      .left-content,\\n      .right-content {\\n        display: flex;\\n        align-items: center;\\n      }\\n\\n      &:last-of-type {\\n        border-bottom: none;\\n      }\\n    }\\n  }\\n\\n  .d-modal__footer {\\n    justify-content: space-between;\\n  }\\n}\\n\\n@container (min-width: 47em) {\\n  .users-directory {\\n    .directory-table {\\n      &__value {\\n        white-space: nowrap;\\n        font-size: var(--font-up-2);\\n\\n        &,\\n        &--user-field {\\n          color: var(--primary-medium);\\n        }\\n      }\\n    }\\n  }\\n}\\n\\n.directory-table-container {\\n  container-type: inline-size;\\n  container-name: directory-table;\\n  transform: translateX(0);\\n\\n  // transform here creates a containing blocks which\\n  // is used by fixed-positioned dropdowns\\n  // if omitted, `overflow-x: auto;` below will clip them\\n}\\n\\n.directory-table {\\n  display: grid;\\n  gap: 0;\\n  width: 100%;\\n  margin-top: var(--space-1);\\n\\n  .me {\\n    .directory-table__cell {\\n      &,\\n      &--user-field {\\n        background-color: var(--highlight-low-or-medium);\\n      }\\n    }\\n  }\\n\\n  &__header,\\n  &__body,\\n  &__row {\\n    display: grid;\\n    grid-column: 1 / -1;\\n    grid-template-columns: subgrid;\\n  }\\n\\n  &__column-header,\\n  &__cell,\\n  &__cell--empty,\\n  &__cell--user-field {\\n    display: flex;\\n    border-bottom: 1px solid var(--table-border-color);\\n    justify-content: center;\\n    align-items: center;\\n    box-sizing: border-box;\\n  }\\n\\n  &__column-header {\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    white-space: nowrap;\\n    color: var(--primary-medium);\\n    padding: var(--space-2);\\n\\n    .d-icon {\\n      margin-right: var(--space-1);\\n    }\\n\\n    &:first-child {\\n      .header-contents {\\n        text-align: left;\\n      }\\n    }\\n  }\\n\\n  &__cell {\\n    min-width: 0;\\n\\n    &,\\n    &--user-field {\\n      padding: var(--space-3) var(--space-2);\\n    }\\n  }\\n\\n  &__value {\\n    white-space: nowrap;\\n\\n    &--user-field {\\n      max-width: 30em;\\n    }\\n  }\\n\\n  &__label {\\n    display: none;\\n  }\\n\\n  .d-icon-heart {\\n    font-size: var(--font-down-1);\\n    color: var(--love);\\n  }\\n\\n  .user-detail {\\n    display: flex;\\n    flex-direction: column;\\n    min-width: 0; // allow content to shrink and hide overflow\\n  }\\n\\n  .user-info {\\n    display: flex;\\n    min-width: 0;\\n    width: 100%;\\n\\n    .user-detail {\\n      padding: 0;\\n      width: 100%;\\n\\n      @include viewport.until(md) {\\n        // overrides existing media query\\n        font-size: var(--font-0);\\n      }\\n\\n      @include viewport.until(sm) {\\n        font-size: var(--font-down-1);\\n      }\\n    }\\n\\n    .title {\\n      margin: 0;\\n    }\\n  }\\n\\n  .header-contents {\\n    width: 100%;\\n    text-align: center;\\n  }\\n}\\n\\n// using a container query to switch to a flex-based layout\\n// browsers without support for container queries\\n// fallback to big horizontal scrolling table\\n\\n@container (max-width: 47em) {\\n  .directory-table {\\n    display: flex;\\n    flex-direction: column;\\n\\n    .me {\\n      background-color: var(--highlight-low-or-medium);\\n    }\\n\\n    &__label {\\n      display: inline-flex;\\n      color: var(--primary-medium);\\n      padding-right: var(--space-2);\\n      align-items: baseline;\\n      align-self: start;\\n      white-space: nowrap;\\n      overflow: hidden;\\n      flex: 1 0 calc(50% - var(--space-2) + 5%); // 50% - padding + half the gap\\n\\n      span {\\n        // caution: display flex here can interfere with overflow hiding\\n        flex: 0 1 auto; // can shrink if needed\\n        margin-right: var(--space-1);\\n\\n        @include ellipsis;\\n      }\\n\\n      // flexible divider between the label and value\\n      &::after {\\n        flex: 1 1 0; // can grow or shrink, but should be 0 width if needed\\n        color: var(--primary-300);\\n        min-width: 0;\\n        overflow: hidden;\\n\\n        // this needs to be long to account for all possible widths\\n        content: \\"................................................................................................................................................................\\";\\n      }\\n\\n      .d-icon {\\n        font-size: 0.8em;\\n        vertical-align: baseline;\\n      }\\n    }\\n\\n    &__value {\\n      font-size: var(--font-0);\\n      color: var(--primary);\\n      align-self: start;\\n\\n      &--user-field {\\n        overflow: hidden;\\n        text-overflow: ellipsis;\\n        min-width: 0;\\n      }\\n    }\\n\\n    &__row {\\n      display: grid;\\n      grid-template-columns: repeat(auto-fill, minmax(11em, 1fr));\\n      border-bottom: 1px solid var(--table-border-color);\\n      padding: var(--space-3) var(--space-2) var(--space-4);\\n      gap: 0 10%;\\n\\n      &:first-child {\\n        border-top: 1px solid var(--table-border-color);\\n      }\\n    }\\n\\n    &__header {\\n      display: none;\\n    }\\n\\n    &__cell {\\n      &,\\n      &--user-field {\\n        padding: var(--space-1);\\n        border: none;\\n\\n        &:first-child {\\n          width: 100%;\\n          padding: var(--space-2) var(--space-1) var(--space-1);\\n          justify-content: start;\\n\\n          // force full width of the cell\\n          grid-column-start: 1;\\n          grid-column-end: -1;\\n        }\\n      }\\n\\n      &--user-field {\\n        display: flex;\\n        order: 2;\\n\\n        // force full width of the cell\\n        // because we don't know how much content there is\\n        grid-column-start: 1;\\n        grid-column-end: -1;\\n\\n        .directory-table__label {\\n          margin-right: var(--space-1);\\n        }\\n      }\\n    }\\n\\n    .--empty {\\n      display: none;\\n    }\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n// Common\\n// global styles that apply to the Discourse application specifically\\n// BEWARE: changing these styles implies they take effect anywhere they are seen\\n// throughout the Discourse application\\n:root {\\n  --d-max-width: 1110px;\\n  --d-input-bg-color: var(--secondary);\\n  --d-input-text-color: var(--primary);\\n  --d-input-border: 1px solid var(--input-border-color);\\n  --d-input-bg-color--disabled: var(--primary-very-low);\\n  --d-input-text-color--disabled: var(--primary-medium);\\n  --d-input-border--disabled: 1px solid var(--primary-low);\\n  --d-nav-color: var(--primary);\\n  --d-nav-bg-color: transparent;\\n  --d-nav-color--hover: var(--tertiary);\\n  --d-nav-bg-color--hover: transparent;\\n  --d-nav-color--active: var(--tertiary);\\n  --d-nav-bg-color--active: transparent;\\n  --d-nav-border-color--active: var(--d-nav-color--active);\\n  --d-nav-underline-height: 0.125em;\\n  --d-nav-font-size: initial;\\n  --d-input-focused-color: var(--tertiary);\\n  --d-category-border-box-width: 2px;\\n  --d-category-box-background-color: var(--secondary);\\n  --d-category-border-accent-width: 6px;\\n  --safe-area-inset-bottom: env(safe-area-inset-bottom);\\n  --nav-space: var(--space-3);\\n  --nav-horizontal-padding: 0em;\\n  --d-main-content-gap: var(--space-8);\\n  --main-outlet-padding-top: var(--space-4);\\n  --main-outlet-padding-x: 0em;\\n  --main-outlet-padding-bottom: 0em;\\n  --table-border-width: 1px;\\n  --d-topic-list-avatar-size: 24px;\\n  --d-topic-list-title-font-size: var(--font-up-1);\\n  --d-topic-list-metadata-top-space: var(--space-1);\\n  --d-topic-list-data-padding-y: var(--space-3);\\n  --d-topic-list-data-padding-x: var(--space-1);\\n  --d-topic-list-header-data-padding-y: var(--space-3);\\n  --d-topic-list-header-data-padding-x: var(--space-1);\\n  --d-topic-list-likes-views-posts-width: 4.3em;\\n  --d-topic-list-data-padding-inline-start: var(--space-3);\\n  --d-topic-list-data-padding-inline-end: var(--space-3);\\n  --d-topic-list-data-font-size: var(--font-0);\\n  --category-boxes-text-alignment: center;\\n  --d-topic-list-header-background-color: var(--secondary);\\n  --d-topic-list-header-text-color: var(--primary-medium);\\n  --d-topic-list-margin-y: 0em;\\n  --d-topic-list-margin-x: 0em;\\n  --d-topic-list-margin-bottom: 10px;\\n  --d-tag-horizontal-padding: 0em;\\n  --d-tag-font-weight: initial;\\n  --d-tag-font-size: var(--font-0);\\n  --d-tag-border-radius: 0px;\\n  --d-tag-background-color: transparent;\\n  --category-badge-title-color: currentcolor;\\n  --category-boxes-description-text-color: var(--primary-med-or-secondary-high);\\n  --d-category-boxes-gap: var(--space-6);\\n  --category-boxes-title-font-size: var(--font-up-2);\\n  --d-category-boxes-margin-top: var(--space-4);\\n  --d-categories-list-title-margin-bottom: 0em;\\n  --d-header-padding-x: 0.67em;\\n  --d-table-border-top-height: 3px;\\n  --d-wrap-padding-x: 0.67em;\\n  --d-post-aside-background: var(--blend-primary-secondary-5);\\n  --d-post-aside-border-left: 5px solid var(--primary-300);\\n  --topic-title-font-weight: 400;\\n  --topic-title-font-weight--visited: 400;\\n  --topic-list-item-background-color: var(--secondary);\\n  --topic-list-item-background-color--visited: var(--secondary);\\n  --list-container-padding-x: 0em;\\n  --d-topic-list-header-font-size: initial;\\n  --skip-links-offset: -75px;\\n  --heading-font-weight: bold;\\n}\\n\\n// Animation Keyframes\\n@keyframes rotate-forever {\\n  0% {\\n    transform: rotate(0deg);\\n  }\\n\\n  100% {\\n    transform: rotate(360deg);\\n  }\\n}\\n\\n@keyframes float-down {\\n  0% {\\n    opacity: 0;\\n    transform: translateY(-10px);\\n  }\\n\\n  100% {\\n    opacity: 1;\\n    transform: translateY(0);\\n  }\\n}\\n\\n@keyframes float-up {\\n  0% {\\n    opacity: 0;\\n    transform: translateY(10px);\\n  }\\n\\n  100% {\\n    opacity: 1;\\n    transform: translateY(0);\\n  }\\n}\\n\\n@keyframes dissolve-up {\\n  0% {\\n    opacity: 1;\\n    transform: translateY(0);\\n  }\\n\\n  100% {\\n    opacity: 0;\\n    transform: translateY(-10px);\\n  }\\n}\\n\\n@keyframes dissolve-down {\\n  0% {\\n    opacity: 1;\\n    transform: translateY(0);\\n  }\\n\\n  100% {\\n    opacity: 0;\\n    transform: translateY(10px);\\n  }\\n}\\n\\n@keyframes float-left {\\n  0% {\\n    opacity: 0;\\n    transform: translateX(-20px);\\n  }\\n\\n  100% {\\n    opacity: 1;\\n    transform: translateX(0);\\n  }\\n}\\n\\n@keyframes float-right {\\n  0% {\\n    opacity: 0;\\n    transform: translateX(20px);\\n  }\\n\\n  100% {\\n    opacity: 1;\\n    transform: translateX(0);\\n  }\\n}\\n\\n@keyframes float-out-left {\\n  0% {\\n    opacity: 1;\\n    transform: translateX(0);\\n  }\\n\\n  100% {\\n    opacity: 0;\\n    transform: translateX(-20px);\\n  }\\n}\\n\\n@keyframes float-out-right {\\n  0% {\\n    opacity: 1;\\n    transform: translateX(0);\\n  }\\n\\n  100% {\\n    opacity: 0;\\n    transform: translateX(20px);\\n  }\\n}\\n\\n@keyframes background-fade-highlight {\\n  0% {\\n    background-color: var(--tertiary-low);\\n  }\\n\\n  100% {\\n    background-color: transparent;\\n  }\\n}\\n\\n// placeholder\\n@keyframes placeHolderShimmer {\\n  0% {\\n    background-position: -1000px 0;\\n  }\\n\\n  100% {\\n    background-position: 1100px 0;\\n  }\\n}\\n\\n@media (prefers-reduced-motion: no-preference) {\\n  .placeholder-animation {\\n    animation-duration: 4s;\\n    animation-fill-mode: forwards;\\n    animation-iteration-count: infinite;\\n    animation-name: placeHolderShimmer;\\n    animation-timing-function: linear;\\n    background: linear-gradient(\\n      to right,\\n      var(--primary-very-low) 10%,\\n      var(--primary-low) 18%,\\n      var(--primary-very-low) 33%\\n    );\\n  }\\n}\\n\\n// Base Elements\\nhtml {\\n  height: 100%;\\n}\\n\\nbody {\\n  background-attachment: fixed;\\n  background-size: cover;\\n  min-height: 100%;\\n  box-sizing: border-box;\\n\\n  &.dragging {\\n    cursor: ns-resize;\\n  }\\n\\n  @include clearfix;\\n\\n  @include viewport.until(sm) {\\n    body {\\n      min-width: 0;\\n    }\\n  }\\n}\\n\\n// setting a static limit on big and small prevents nesting abuse\\nbig {\\n  font-size: var(--font-up-5);\\n}\\n\\nsmall {\\n  font-size: var(--font-down-2);\\n}\\n\\nblockquote {\\n  background: var(--d-post-aside-background);\\n  border-left: var(--d-post-aside-border-left);\\n\\n  @include viewport.until(sm) {\\n    clear: both;\\n    margin-left: 0;\\n    margin-right: 0;\\n  }\\n}\\n\\ncode,\\npre,\\nkbd {\\n  font-family: var(--d-font-family--monospace);\\n}\\n\\nh1,\\nh2,\\nh3,\\nh4,\\nh5,\\nh6 {\\n  font-family: var(--heading-font-family);\\n  margin-top: 0;\\n  margin-bottom: 0.5rem;\\n  font-weight: var(--heading-font-weight);\\n}\\n\\na.cancel {\\n  margin-left: var(--space-5);\\n  line-height: normal;\\n  color: var(--primary-high);\\n  transition: var(--d-button-transition);\\n\\n  &:hover {\\n    color: var(--danger);\\n  }\\n}\\n\\nul.breadcrumb {\\n  margin: 0 10px 0 10px;\\n}\\n\\na.no-href {\\n  cursor: pointer;\\n}\\n\\nimg.avatar {\\n  border-radius: 50%;\\n}\\n\\n// don't wrap relative dates; we want Jul 26, '15, not: Jul\\n//                                                      26,\\n//                                                      '15\\nspan.relative-date {\\n  white-space: nowrap;\\n}\\n\\nlegend {\\n  color: var(--primary-high);\\n  font-weight: bold;\\n  font-size: var(--font-down-1-rem);\\n}\\n\\nlabel {\\n  display: flex;\\n  margin-bottom: 5px;\\n  align-items: flex-start;\\n  color: var(--primary-high);\\n\\n  &:not(.checkbox-label, .d-segmented-control__label) {\\n    font-weight: bold;\\n  }\\n\\n  > .d-icon {\\n    align-self: center;\\n    margin-right: 4px;\\n  }\\n\\n  a {\\n    // flex removes whitespace characters between text nodes and elements\\n    // so we need to add it back\\n    margin: 0 var(--space-1);\\n  }\\n}\\n\\ninput {\\n  @include viewport.from(sm) {\\n    width: 210px;\\n    margin-left: 0;\\n  }\\n\\n  &[type=\\"radio\\"],\\n  &[type=\\"checkbox\\"] {\\n    margin-top: 0.17em;\\n    margin-right: 0.43em;\\n    margin-left: 0.1em;\\n    line-height: var(--line-height-small);\\n    cursor: pointer;\\n    flex-shrink: 0; // Adding for safety, Safari will shrink checkboxes\\n  }\\n\\n  &[type=\\"submit\\"],\\n  &[type=\\"reset\\"],\\n  &[type=\\"button\\"],\\n  &[type=\\"radio\\"],\\n  &[type=\\"checkbox\\"] {\\n    width: auto;\\n  }\\n\\n  &.invalid {\\n    background-color: var(--danger-low);\\n  }\\n\\n  .radio &[type=\\"radio\\"],\\n  .checkbox &[type=\\"checkbox\\"] {\\n    float: left;\\n    margin-left: -18px;\\n  }\\n\\n  &[type=\\"text\\"],\\n  &[type=\\"password\\"],\\n  &[type=\\"datetime\\"],\\n  &[type=\\"datetime-local\\"],\\n  &[type=\\"date\\"],\\n  &[type=\\"month\\"],\\n  &[type=\\"time\\"],\\n  &[type=\\"week\\"],\\n  &[type=\\"number\\"],\\n  &[type=\\"email\\"],\\n  &[type=\\"url\\"],\\n  &[type=\\"search\\"],\\n  &[type=\\"tel\\"],\\n  &[type=\\"color\\"] {\\n    @include form-item-sizing;\\n    appearance: none;\\n    display: inline-block;\\n    margin-bottom: 9px;\\n    color: var(--d-input-text-color);\\n    background-color: var(--d-input-bg-color);\\n    border: var(--d-input-border);\\n    border-radius: var(--d-input-border-radius);\\n    color-scheme: var(--scheme-type);\\n\\n    &:focus {\\n      @include default-focus;\\n    }\\n  }\\n\\n  &[type=\\"color\\"] {\\n    border: var(--d-input-border);\\n    border-radius: var(--d-input-border-radius);\\n    cursor: pointer;\\n    padding: 0;\\n    margin-bottom: 0;\\n\\n    &::-webkit-color-swatch-wrapper {\\n      padding: 0;\\n    }\\n\\n    &::-webkit-color-swatch {\\n      border: none;\\n    }\\n  }\\n\\n  &[type=\\"time\\"] {\\n    max-width: 140px;\\n  }\\n}\\n\\ninput[type=\\"search\\"] {\\n  &::-webkit-search-cancel-button,\\n  &::-webkit-search-decoration {\\n    appearance: none;\\n  }\\n}\\n\\n// Fixes Safari height inconsistency\\n::-webkit-datetime-edit {\\n  display: inline;\\n}\\n\\n// Fixes Webkit inconsistencies (Safari/Chrome)\\n::-webkit-datetime-edit-fields-wrapper,\\n::-webkit-datetime-edit-text,\\n::-webkit-datetime-edit-month-field,\\n::-webkit-datetime-edit-day-field,\\n::-webkit-datetime-edit-year-field {\\n  padding-top: 0;\\n  padding-bottom: 0;\\n}\\n\\n::placeholder {\\n  text-overflow: ellipsis;\\n}\\n\\ntextarea {\\n  padding: $vpad $hpad;\\n  box-sizing: border-box;\\n  height: auto;\\n  background-color: var(--secondary);\\n  border: 1px solid var(-