\n.radio,\\n.checkbox {\\n  min-height: 18px;\\n  padding-left: 18px;\\n\\n  .controls > &:first-child {\\n    padding-top: 5px;\\n  }\\n\\n  &.inline {\\n    display: inline-block;\\n    padding-top: 5px;\\n    margin-bottom: 0;\\n    vertical-align: middle;\\n  }\\n}\\n\\n.radio.inline .radio.inline,\\n.checkbox.inline .checkbox.inline {\\n  margin-left: 0.67em;\\n}\\n\\n.dropdown,\\n.multiselect {\\n  position: relative;\\n}\\n\\n.container {\\n  @extend .clearfix;\\n}\\n\\n.wrap {\\n  max-width: var(--d-max-width);\\n  margin-right: auto;\\n  margin-left: auto;\\n  padding: 0 var(--d-wrap-padding-x);\\n\\n  @include viewport.until(sm) {\\n    min-width: 0;\\n  }\\n\\n  .contents {\\n    position: relative;\\n  }\\n}\\n\\n.boxed {\\n  height: 100%;\\n\\n  &.white {\\n    background-color: var(--secondary);\\n  }\\n}\\n\\n.full-width {\\n  margin-left: 0;\\n\\n  @include viewport.until(sm) {\\n    min-width: 0;\\n  }\\n}\\n\\n.clear-transitions {\\n  transition: none !important;\\n}\\n\\n.tip {\\n  display: inline-block;\\n\\n  &.good {\\n    color: var(--success);\\n  }\\n\\n  &.bad {\\n    color: var(--danger);\\n  }\\n}\\n\\n.avatar-wrapper {\\n  background-color: var(--secondary);\\n  display: inline-block;\\n  border-radius: 50%;\\n}\\n\\n.unread-high-priority-notifications {\\n  color: var(--secondary);\\n  background: var(--success);\\n\\n  &.badge-notification[href] {\\n    color: var(--secondary);\\n  }\\n}\\n\\n.d-header .header-dropdown-toggle .do-not-disturb-background {\\n  position: absolute;\\n  left: 0;\\n  bottom: -1px;\\n}\\n\\n.do-not-disturb-background {\\n  display: flex;\\n  align-items: center;\\n  justify-content: center;\\n  width: 1em;\\n  background-color: var(--secondary);\\n  border-radius: 50%;\\n  height: 1em;\\n  box-shadow: 0 0 0 2px var(--secondary);\\n\\n  .d-icon.d-icon-discourse-dnd {\\n    color: var(--header_primary-medium) !important;\\n    font-size: 1em;\\n    height: 1em;\\n    width: 1em;\\n  }\\n}\\n\\n.d-header .header-dropdown-toggle .user-status-background {\\n  position: absolute;\\n  right: -3px;\\n  bottom: -1px;\\n}\\n\\n.user-status-background {\\n  display: flex;\\n  align-items: center;\\n  justify-content: center;\\n  width: 1.25em;\\n  height: 1.25em;\\n  background-color: var(--secondary);\\n  border-radius: 50%;\\n\\n  .emoji {\\n    width: 14px;\\n    height: 14px;\\n    display: block;\\n  }\\n}\\n\\n.fade {\\n  opacity: 0;\\n  transition: opacity 0.15s linear;\\n\\n  &.in {\\n    opacity: 1;\\n  }\\n}\\n\\n.inline-spinner {\\n  display: inline-block;\\n  margin: 0;\\n}\\n\\n.spinner {\\n  margin: 20px auto 20px auto;\\n  position: relative;\\n  animation: rotate-forever 1s infinite linear;\\n  height: 30px;\\n  width: 30px;\\n  border: 4px solid var(--primary-low-mid);\\n  border-right-color: transparent;\\n  border-radius: 50%;\\n\\n  &.small {\\n    width: 10px;\\n    height: 10px;\\n    margin: 0;\\n    display: inline-block;\\n  }\\n}\\n\\n.content-list {\\n  h3 {\\n    color: var(--primary-medium);\\n    font-size: var(--font-up-1);\\n    padding-left: 5px;\\n    margin-bottom: 10px;\\n  }\\n\\n  ul {\\n    list-style: none;\\n    margin: 0;\\n\\n    li {\\n      border-bottom: 1px solid var(--content-border-color);\\n\\n      &:first-of-type {\\n        border-top: 1px solid var(--content-border-color);\\n      }\\n\\n      a {\\n        display: block;\\n        padding: 10px;\\n        color: var(--primary);\\n\\n        &:hover {\\n          background-color: var(--primary-low);\\n          color: var(--primary);\\n        }\\n\\n        &.active {\\n          font-weight: bold;\\n          color: var(--d-selected-text-color);\\n          background: var(--d-selected);\\n        }\\n      }\\n    }\\n  }\\n}\\n\\nform {\\n  margin: 0;\\n}\\n\\n.control-group {\\n  margin-bottom: 9px;\\n}\\n\\n.controls-dropdown {\\n  margin-bottom: 10px;\\n}\\n\\n.control-instructions {\\n  color: var(--primary-medium);\\n  font-size: 0.875rem;\\n}\\n\\n.form-vertical {\\n  input,\\n  textarea,\\n  select {\\n    display: inline-block;\\n    margin-bottom: 0;\\n    flex: 0 0 auto;\\n    max-width: 100%;\\n  }\\n\\n  .control-label:not(.checkbox-label) {\\n    font-family: var(--heading-font-family);\\n    font-weight: bold;\\n    font-size: var(--font-up-2);\\n    line-height: var(--line-height-large);\\n  }\\n\\n  .control-group,\\n  .controls {\\n    margin-left: 0;\\n\\n    label {\\n      font-weight: normal;\\n    }\\n  }\\n\\n  .control-group {\\n    margin-bottom: var(--space-5);\\n  }\\n\\n  .radio-group {\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-2);\\n  }\\n\\n  .controls:not(.controls-dropdown) + .controls {\\n    margin-top: var(--space-2);\\n  }\\n}\\n\\n.form-horizontal {\\n  input[type=\\"text\\"],\\n  input[type=\\"password\\"],\\n  textarea {\\n    margin-bottom: 0;\\n  }\\n\\n  .control-group {\\n    margin-bottom: 18px;\\n\\n    @include clearfix;\\n  }\\n\\n  .control-indent {\\n    margin-left: 20px;\\n    margin-bottom: 10px;\\n  }\\n\\n  .control-label {\\n    margin: 6.5px;\\n    float: left;\\n    width: 140px;\\n    text-align: right;\\n    font-weight: bold;\\n  }\\n\\n  .controls {\\n    margin-left: 160px;\\n  }\\n}\\n\\n// Special elements\\n#main-outlet-wrapper {\\n  box-sizing: border-box;\\n  width: 100%;\\n  display: grid;\\n  grid-template-areas:\\n    \\"sidebar content\\"\\n    \\"sidebar below-content\\";\\n  grid-template-rows: 1fr auto;\\n  grid-template-columns: 0 minmax(0, 1fr); // 0 column width needs to be set for CSS transitions\\n  gap: 0;\\n\\n  @include viewport.until(md) {\\n    grid-template-areas:\\n      \\"content\\"\\n      \\"below-content\\";\\n    grid-template-columns: minmax(0, 1fr);\\n  }\\n\\n  #main-outlet {\\n    grid-area: content;\\n  }\\n}\\n\\n#main-outlet {\\n  padding: var(--main-outlet-padding-top) var(--main-outlet-padding-x)\\n    var(--main-outlet-padding-bottom);\\n\\n  .mobile-view & {\\n    padding-top: var(--space-5); // notc