fo-wrapper {\\n  --tag-text-color: var(--header_primary-high);\\n  flex: 1 0 0;\\n  display: flex;\\n  align-items: center;\\n  height: 100%;\\n  line-height: var(--line-height-medium);\\n  padding: 0 1.5em 0 0.5em;\\n\\n  // we need to hide overflow in both to truncate the title in a flexbox\\n  overflow: hidden;\\n\\n  .extra-info {\\n    overflow: hidden;\\n    width: 100%;\\n    animation: fadein 0.5s;\\n\\n    @media (prefers-reduced-motion) {\\n      animation-duration: 0s;\\n    }\\n  }\\n\\n  .title-wrapper {\\n    display: grid;\\n    grid-template-areas:\\n      \\"title title\\"\\n      \\"categories extra\\";\\n    grid-template-columns: auto minmax(2em, 1fr); // min must be as wide as ellipsis\\n    gap: 0 0.5em;\\n\\n    .header-title {\\n      grid-area: title;\\n    }\\n\\n    .categories-wrapper {\\n      grid-area: categories;\\n    }\\n\\n    .topic-header-extra {\\n      grid-area: extra;\\n\\n      .archetype-private_message & {\\n        grid-area: categories;\\n      }\\n    }\\n  }\\n\\n  .topic-link {\\n    color: var(--title-color--header);\\n    display: block;\\n\\n    @include ellipsis;\\n  }\\n\\n  .topic-statuses {\\n    .d-icon {\\n      color: var(--header_primary-medium);\\n    }\\n\\n    .d-icon-envelope {\\n      color: var(--danger);\\n    }\\n  }\\n\\n  .header-title {\\n    padding: 0;\\n    margin: 0;\\n    width: 100%;\\n    font-size: var(--font-0);\\n\\n    @include viewport.from(sm) {\\n      font-size: var(--font-up-3);\\n    }\\n  }\\n\\n  .categories-wrapper {\\n    display: inline-flex;\\n    flex: 0 1 auto;\\n    gap: 0 0.5em;\\n\\n    @include ellipsis;\\n  }\\n\\n  .badge-category__wrapper {\\n    min-width: 2.75em; // min needed for ellipsis\\n\\n    @include ellipsis;\\n\\n    .badge-category {\\n      color: var(--header_primary-high);\\n    }\\n  }\\n\\n  .topic-header-extra {\\n    display: inline-flex;\\n    align-items: center;\\n    max-width: 100%;\\n    gap: 0.5em;\\n\\n    .discourse-tags {\\n      displa