 width: 100%;\\n\\n    @include viewport.until(md) {\\n      padding: 1rem;\\n    }\\n  }\\n\\n  .btn-social-title {\\n    @include ellipsis;\\n  }\\n\\n  .tip {\\n    font-size: var(--font-down-1);\\n    display: block;\\n\\n    &.bad {\\n      color: var(--danger);\\n    }\\n  }\\n\\n  .toggle-password-mask span {\\n    font-size: var(--font-down-1-rem);\\n  }\\n\\n  .more-info,\\n  .instructions {\\n    font-size: var(--font-down-1);\\n    color: var(--primary-medium);\\n    overflow-wrap: anywhere;\\n  }\\n\\n  .caps-lock-warning {\\n    color: var(--danger);\\n    font-size: var(--font-down-1);\\n\\n    @include viewport.until(md) {\\n      display: none;\\n    }\\n  }\\n\\n  .create-account__password-info {\\n    display: flex;\\n    justify-content: space-between;\\n\\n    .create-account__password-tip-validation {\\n      display: flex;\\n    }\\n  }\\n\\n  .inline-spinner {\\n    display: inline-flex;\\n  }\\n\\n  .invitation-cta {\\n    display: flex;\\n    flex-direction: column;\\n    gap: 1rem;\\n\\n    &__accept {\\n      width: 100%;\\n    }\\n\\n    &__info {\\n      display: flex;\\n      align-items: center;\\n      justify-content: center;\\n      width: 100%;\\n      gap: 0.5rem;\\n      line-height: 1rem;\\n      color: var(--primary-medium);\\n    }\\n\\n    &__sign-in {\\n      padding: 0;\\n      height: 100%;\\n      font-size: 1rem;\\n    }\\n  }\\n\\n  @include viewport.from(sm) {\\n    &:not(:has(.has-alt-auth)) .alert {\\n      max-width: 500px;\\n    }\\n  }\\n\\n  @include viewport.until(md) {\\n    .login-or-separator {\\n      border-top: 1px solid var(--content-border-color);\\n      position: relative;\\n      margin-block: 1rem;\\n\\n      span {\\n        transform: translate(-50%, -50%);\\n        position: absolute;\\n        left: 50%;\\n        top: 50%;\\n        background: var(--secondary);\\n        padding-inline: 0.5rem;\\n        color: var(--primary-medium);\\n        font-size: var(--font-down-1-rem);\\n        text-transform: uppercase;\\n      }\\n    }\\n  }\\n\\n  @include viewport.between(sm, md) {\\n    .has-alt-auth {\\n      flex-direction: column;\\n      overflow: auto;\\n      gap: 0;\\n\\n      .login-page-cta,\\n      .signup-page-cta,\\n      .btn-social {\\n        font-size: var(--font-down-1);\\n      }\\n\\n      .login-left-side {\\n        overflow: unset;\\n        padding: 1em;\\n        max-width: unset;\\n      }\\n\\n      .login-right-side {\\n        padding: 1em;\\n        max-width: unset;\\n\\n        &::before {\\n          height: 1px;\\n          width: calc(100% - 2em);\\n          left: 1em;\\n          top: 0;\\n        }\\n      }\\n    }\\n\\n    .signup-progress-bar {\\n      font-size: var(--font-down-1);\\n    }\\n  }\\n}\\n\\n// Signup, invite, and code login pages share the user-fields step\\n.invite-page,\\n.signup-fullpage,\\n.login-fullpage {\\n  .password-confirmation {\\n    display: none;\\n  }\\n\\n  .user-fields .input-group {\\n    .user-field {\\n      &.text,\\n      &.textarea {\\n        &.value-entered label.alt-placeholder.control-label,\\n        input:focus + label.alt-placeholder.control-label,\\n        textarea:focus + label.alt-placeholder.control-label {\\n          top: -8px;\\n          left: calc(1em - 0.25em);\\n          background-color: var(--secondary);\\n          padding: 0 0.25em 0 0.25em;\\n          font-size: 14px;\\n          color: var(--primary-medium);\\n        }\\n\\n        label.alt-placeholder.control-label {\\n          color: var(--primary-medium);\\n          font-size: 16px;\\n          position: absolute;\\n          pointer-events: none;\\n          top: 12px;\\n          transition: 0.2s ease all;\\n          max-width: calc(100% - 2em);\\n          white-space: nowrap;\\n          display: inline-block;\\n          overflow: hidden;\\n          text-overflow: ellipsis;\\n        }\\n      }\\n\\n      details:not(.has-selection) span.name,\\n      details:not(.has-selection) span.formatted-selection {\\n        color: var(--primary-medium);\\n      }\\n\\n      .select-kit-row span.name {\\n        color: var(--primary);\\n      }\\n\\n      .select-kit.combo-box.is-expanded summary {\\n        outline: none;\\n        border: 1px solid var(--tertiary);\\n        box-shadow: 0 0 0 2px rgb(var(--tertiary-rgb), 0.25);\\n      }\\n\\n      .controls .checkbox-label {\\n        display: flex;\\n        align-items: center;\\n\\n        input[type=\\"checkbox\\"].ember-checkbox {\\n          width: 1em !important;\\n          min-width: unset;\\n          margin-block: 0;\\n        }\\n      }\\n    }\\n  }\\n}\\n\\n@include viewport.until(md) {\\n  .login-page,\\n  .signup-page,\\n  .invite-page {\\n    #main-outlet,\\n    #main-outlet-wrapper {\\n      padding: 0;\\n    }\\n  }\\n\\n  .login-right-side::before {\\n    display: none;\\n  }\\n\\n  .invites-show {\\n    .login-welcome-header {\\n      padding-inline: 0;\\n    }\\n\\n    .signup-progress-bar {\\n      margin-inline: 0;\\n    }\\n  }\\n\\n  .login-fullpage .login-body {\\n    .login-page-cta {\\n      &__buttons {\\n        .login-page-cta__login {\\n          width: 100%;\\n          margin-bottom: 0.5rem;\\n        }\\n      }\\n\\n      &__signup {\\n        background: none !important;\\n        font-size: var(--font-up-1);\\n        padding: 0;\\n      }\\n\\n      &__no-account-yet {\\n        font-size: var(--font-up-1);\\n      }\\n    }\\n  }\\n\\n  .signup-fullpage .signup-body {\\n    .signup-page-cta {\\n      &__buttons {\\n        .signup-page-cta__signup {\\n          width: 100%;\\n          margin-bottom: 0.5rem;\\n        }\\n      }\\n\\n      &__login {\\n        background: none !important;\\n        font-size: var(--font-up-1);\\n        padding: 0;\\n      }\\n\\n      &__existing-account {\\n        font-size: var(--font-up-1);\\n      }\\n    }\\n\\n    .login-welcome-header {\\n      padding-bottom: 0.25rem;\\n      padding-top: 0;\\n    }\\n\\n    #login-form {\\n      padding-bottom: 0;\\n    }\\n  }\\n}\\n\\n@include viewport.from(sm) {\\n  .invites-show.container {\\n    box-sizing: border-box;\\n    box-shadow: none;\\n    max-width: 550px;\\n  }\\n}\\n","/*! PhotoSwipe main CSS by Dmytro Semenov | photoswipe.com */\\n.pswp {\\n  --pswp-bg: #000;\\n  --pswp-placeholder-bg: #222;\\n  --pswp-root-z-index: 100000;\\n  --pswp-preloader-color: rgb(79, 79, 79, 0.4);\\n  --pswp-preloader-color-secondary: rgb(255, 255, 255, 0.9);\\n\\n  /* defined via js:\\n  --pswp-transition-duration: 333ms; */\\n\\n  --pswp-icon-color: #fff;\\n  --pswp-icon-color-secondary: #4f4f4f;\\n  --pswp-icon-stroke-color: #4f4f4f;\\n  --pswp-icon-stroke-width: 2px;\\n  --pswp-error-text-color: var(--pswp-icon-color);\\n\\n  /*\\n\\tStyles for basic PhotoSwipe (pswp) functionality (sliding area, open/close transitions)\\n*/\\n  position: fixed;\\n  top: 0;\\n  left: 0;\\n  width: 100%;\\n  height: 100%;\\n  z-index: var(--pswp-root-z-index);\\n  display: none;\\n  touch-action: none;\\n  outline: 0;\\n  opacity: 0.003;\\n  contain: layout style size;\\n  -webkit-tap-highlight-color: rgb(0, 0, 0, 0);\\n}\\n\\n/* Prevents focus outline on the root element,\\n  (it may be focused initially) */\\n\\n.pswp:focus {\\n  outline: 0;\\n}\\n\\n.pswp * {\\n  box-sizing: border-box;\\n}\\n\\n.pswp img {\\n  max-width: none;\\n}\\n\\n.pswp--open {\\n  display: block;\\n}\\n\\n.pswp,\\n.pswp__bg {\\n  transform: translateZ(0);\\n  will-change: opacity;\\n}\\n\\n.pswp__bg {\\n  opacity: 0.005;\\n  background: var(--pswp-bg);\\n}\\n\\n.pswp,\\n.pswp__scroll-wrap {\\n  overflow: hidden;\\n}\\n\\n.pswp__scroll-wrap,\\n.pswp__bg,\\n.pswp__container,\\n.pswp__item,\\n.pswp__content,\\n.pswp__img,\\n.pswp__zoom-wrap {\\n  position: absolute;\\n  top: 0;\\n  left: 0;\\n  width: 100%;\\n  height: 100%;\\n}\\n\\n.pswp__img,\\n.pswp__zoom-wrap {\\n  width: auto;\\n  height: auto;\\n}\\n\\n.pswp--click-to-zoom.pswp--zoom-allowed .pswp__img {\\n  cursor: zoom-in;\\n}\\n\\n.pswp--click-to-zoom.pswp--zoomed-in .pswp__img {\\n  cursor: move;\\n  cursor: grab;\\n  cursor: grab;\\n  cursor: grab;\\n}\\n\\n.pswp--click-to-zoom.pswp--zoomed-in .pswp__img:active {\\n  cursor: grabbing;\\n}\\n\\n/* :active to override grabbing cursor */\\n.pswp--no-mouse-drag.pswp--zoomed-in .pswp__img,\\n.pswp--no-mouse-drag.pswp--zoomed-in .pswp__img:active,\\n.pswp__img {\\n  cursor: zoom-out;\\n}\\n\\n/* Prevent selection and tap highlights */\\n.pswp__container,\\n.pswp__img,\\n.pswp__button,\\n.pswp__counter {\\n  user-select: none;\\n}\\n\\n.pswp__item {\\n  /* z-index for fade transition */\\n  z-index: 1;\\n  overflow: hidden;\\n}\\n\\n.pswp__hidden {\\n  display: none !important;\\n}\\n\\n/* Allow to click through pswp__content element, but not its children */\\n.pswp__content {\\n  pointer-events: none;\\n}\\n\\n.pswp__content > * {\\n  pointer-events: auto;\\n}\\n\\n/*\\n\\n  PhotoSwipe UI\\n\\n*/\\n\\n/*\\n\\tError message appears when image is not loaded\\n\\t(JS option errorMsg controls markup)\\n*/\\n\\n.pswp__error-msg-container {\\n  display: grid;\\n}\\n\\n.pswp__error-msg {\\n  margin: auto;\\n  font-size: 1em;\\n  line-height: 1;\\n  color: var(--pswp-error-text-color);\\n}\\n\\n/*\\nclass pswp__hide-on-close is applied to elements that\\nshould hide (for example fade out) when PhotoSwipe is closed\\nand show (for example fade in) when PhotoSwipe is opened\\n */\\n\\n.pswp .pswp__hide-on-close {\\n  opacity: 0.005;\\n  will-change: opacity;\\n  transition: opacity var(--pswp-transition-duration)\\n    cubic-bezier(0.4, 0, 0.22, 1);\\n  z-index: 10; /* always overlap slide content */\\n  pointer-events: none; /* hidden elements should not be clickable */\\n}\\n\\n/* class pswp--ui-visible is added when opening or closing transition starts */\\n.pswp--ui-visible .pswp__hide-on-close {\\n  opacity: 1;\\n  pointer-events: auto;\\n}\\n\\n/* <button> styles, including css reset */\\n.pswp__button {\\n  position: relative;\\n  display: block;\\n  width: 50px;\\n  height: 60px;\\n  padding: 0;\\n  margin: 0;\\n  overflow: hidden;\\n  cursor: pointer;\\n  background: none;\\n  border: 0;\\n  box-shadow: none;\\n  opacity: 0.85;\\n  appearance: none;\\n  -webkit-touch-callout: none;\\n}\\n\\n.pswp__button:hover,\\n.pswp__button:active,\\n.pswp__button:focus {\\n  transition: none;\\n  padding: 0;\\n  background: none;\\n  border: 0;\\n  box-shadow: none;\\n  opacity: 1;\\n}\\n\\n.pswp__button:disabled {\\n  opacity: 0.3;\\n  cursor: auto;\\n}\\n\\n.pswp__icn {\\n  fill: var(--pswp-icon-color);\\n  color: var(--pswp-icon-color-secondary);\\n  position: absolute;\\n  top: 14px;\\n  left: 9px;\\n  width: 32px;\\n  height: 32px;\\n  overflow: hidden;\\n  pointer-events: none;\\n}\\n\\n.pswp__icn-shadow {\\n  stroke: var(--pswp-icon-stroke-color);\\n  stroke-width: var(--pswp-icon-stroke-width);\\n  fill: none;\\n}\\n\\n.pswp__icn:focus {\\n  outline: 0;\\n}\\n\\n/*\\n\\tdiv element that matches size of large image,\\n\\tlarge image loads on top of it,\\n\\tused when msrc is not provided\\n*/\\n\\ndiv.pswp__img--placeholder,\\n.pswp__img--with-bg {\\n  background: var(--pswp-placeholder-bg);\\n}\\n\\n.pswp__top-bar {\\n  position: absolute;\\n  left: 0;\\n  top: 0;\\n  width: 100%;\\n  height: 60px;\\n  display: flex;\\n  flex-direction: row;\\n  justify-content: flex-end;\\n  z-index: 10;\\n\\n  /* allow events to pass through top bar itself */\\n  pointer-events: none !important;\\n}\\n\\n.pswp__top-bar > * {\\n  pointer-events: auto;\\n\\n  /* this makes transition significantly more smooth,\\n     even though inner elements are not animated */\\n  will-change: opacity;\\n}\\n\\n/*\\n\\n  Close button\\n\\n*/\\n\\n.pswp__button--close {\\n  margin-right: 6px;\\n}\\n\\n/*\\n\\n  Arrow buttons\\n\\n*/\\n\\n.pswp__button--arrow {\\n  position: absolute;\\n  width: 75px;\\n  height: 100px;\\n  top: 50%;\\n  margin-top: -50px;\\n}\\n\\n.pswp__button--arrow:disabled {\\n  display: none;\\n  cursor: default;\\n}\\n\\n.pswp__button--arrow .pswp__icn {\\n  top: 50%;\\n  margin-top: -30px;\\n  width: 60px;\\n  height: 60px;\\n  background: none;\\n  border-radius: 0;\\n}\\n\\n.pswp--one-slide .pswp__button--arrow {\\n  display: none;\\n}\\n\\n/* hide arrows on touch screens */\\n.pswp--touch .pswp__button--arrow {\\n  visibility: hidden;\\n}\\n\\n/* show arrows only after mouse was used */\\n.pswp--has_mouse .pswp__button--arrow {\\n  visibility: visible;\\n}\\n\\n.pswp__button--arrow--prev {\\n  right: auto;\\n  left: 0;\\n}\\n\\n.pswp__button--arrow--next {\\n  right: 0;\\n}\\n\\n.pswp__button--arrow--next .pswp__icn {\\n  left: auto;\\n  right: 9px;\\n\\n  /* flip horizontally */\\n  transform: scale(-1, 1);\\n}\\n\\n/*\\n\\n  Zoom button\\n\\n*/\\n\\n.pswp__button--zoom {\\n  display: none;\\n}\\n\\n.pswp--zoom-allowed .pswp__button--zoom {\\n  display: block;\\n}\\n\\n/* \\"+\\" => \\"-\\" */\\n.pswp--zoomed-in .pswp__zoom-icn-bar-v {\\n  display: none;\\n}\\n\\n/*\\n\\n  Loading indicator\\n\\n*/\\n\\n.pswp__preloader {\\n  position: relative;\\n  overflow: hidden;\\n  width: 50px;\\n  height: 60px;\\n  margin-right: auto;\\n}\\n\\n.pswp__preloader .pswp__icn {\\n  opacity: 0;\\n  transition: opacity 0.2s linear;\\n  animation: pswp-clockwise 600ms linear infinite;\\n}\\n\\n.pswp__preloader--active .pswp__icn {\\n  opacity: 0.85;\\n}\\n\\n@keyframes pswp-clockwise {\\n  0% {\\n    transform: rotate(0deg);\\n  }\\n\\n  100% {\\n    transform: rotate(360deg);\\n  }\\n}\\n\\n/*\\n  \\"1 of 10\\" counter\\n*/\\n\\n.pswp__counter {\\n  height: 30px;\\n  margin-top: 15px;\\n  margin-inline-start: 20px;\\n  font-size: 14px;\\n  line-height: 30px;\\n  color: var(--pswp-icon-color);\\n  text-shadow: 1px 1px 3px var(--pswp-icon-color-secondary);\\n  opacity: 0.85;\\n}\\n\\n.pswp--one-slide .pswp__counter {\\n  display: none;\\n}\\n","@use \\"lib/viewport\\";\\n\\n:root {\\n  --d-unread-notification-background: light-dark(\\n    var(--tertiary-25),\\n    var(--tertiary-200)\\n  );\\n  --active-shadow: 0 0 0 0.5rem var(--d-sidebar-active-background);\\n  --hover-shadow: 0 0 0 0.5rem var(--d-sidebar-highlight-background);\\n}\\n\\n.menu-panel.slide-in {\\n  position: fixed;\\n  right: 0;\\n  top: 0;\\n  box-sizing: border-box;\\n\\n  // ensure there's always space to click outside on tiny devices\\n  max-width: 90vw;\\n  box-shadow: 0 0 30px -2px rgb(0, 0, 0, 0.5);\\n  height: 100dvh;\\n\\n  .panel-body {\\n    width: 100%;\\n  }\\n}\\n\\n.header-cloak {\\n  height: 100%;\\n  width: 100%;\\n  position: fixed;\\n  background-color: rgb(0, 0, 0, 0.3);\\n  top: 0;\\n  left: 0;\\n  display: none;\\n  touch-action: pan-y pinch-zoom;\\n}\\n\\n.menu-panel.drop-down {\\n  position: absolute;\\n\\n  // positions are relative to the .d-header .panel div\\n  top: 100%; // directly underneath .panel\\n  right: 5px;\\n  max-height: calc(100dvh - var(--header-offset) - 1em);\\n  border-radius: var(--d-border-radius);\\n\\n  .panel-body {\\n    // improves usability on high zoom levels\\n    max-width: calc(100vw - 2em);\\n  }\\n\\n  @include d-animation(float-down, 250ms, ease);\\n}\\n\\n.menu-panel {\\n  --shadow-dropdown: 0 4px 6px -1px #0000001a, 0 2px 4px -2px #0000001a;\\n  --list-item-padding: 0.5em 1rem;\\n  border: 1px solid var(--content-border-color);\\n  box-shadow: var(--shadow-dropdown);\\n  background-color: var(--secondary);\\n  z-index: z(\\"header\\");\\n  padding: 0.5em;\\n  width: 320px;\\n  overflow: hidden;\\n  display: flex;\\n  flex-direction: column;\\n  box-sizing: border-box;\\n  max-height: 100vh;\\n\\n  // remove once glimmer search menu in place\\n  .widget-link,\\n  .categories-link {\\n    padding: 0.25em 0.5em;\\n    display: block;\\n    color: var(--primary);\\n\\n    &:hover,\\n    &:focus {\\n      background-color: var(--d-hover);\\n      outline: none;\\n    }\\n\\n    .d-icon {\\n      color: var(--primary-medium);\\n    }\\n\\n    .new {\\n      font-size: var(--font-down-1);\\n      margin-left: 0.5em;\\n      color: var(--primary-med-or-secondary-med);\\n    }\\n\\n    &.show-help,\\n    &.filter {\\n      color: var(--tertiary);\\n    }\\n  }\\n\\n  .search-link,\\n  .categories-link {\\n    padding: 0.25em 0.5em;\\n    display: block;\\n    color: var(--primary);\\n\\n    &:hover,\\n    &:focus {\\n      background-color: var(--d-hover);\\n      outline: none;\\n    }\\n\\n    .d-icon {\\n      color: var(--primary-medium);\\n    }\\n\\n    .new {\\n      font-size: var(--font-down-1);\\n      margin-left: 0.5em;\\n      color: var(--primary-med-or-secondary-med);\\n    }\\n\\n    &.show-help,\\n    &.filter {\\n      color: var(--tertiary);\\n    }\\n  }\\n\\n  li.category-link {\\n    float: left;\\n    background-color: transparent;\\n    display: inline-flex;\\n    align-items: center;\\n    padding: 0.25em 0.5em;\\n    width: 50%;\\n    box-sizing: border-box;\\n\\n    a {\\n      display: inline-flex;\\n\\n      &:hover,\\n      &:focus {\\n        background: transparent;\\n\\n        .category-name {\\n          color: var(--primary);\\n        }\\n      }\\n    }\\n\\n    .badge-notification {\\n      color: var(--primary-med-or-secondary-med);\\n      background-color: transparent;\\n      display: inline;\\n      padding: 0;\\n      font-size: var(--font-down-1);\\n      line-height: var(--line-height-large);\\n    }\\n  }\\n\\n  // note these topic counts only appear for anons in the category hamburger drop down\\n  b.topics-count {\\n    color: var(--primary-med-or-secondary-med);\\n    font-weight: normal;\\n    font-size: var(--font-down-1);\\n  }\\n\\n  .discourse-tags {\\n    font-size: var(--font-down-1);\\n  }\\n\\n  .sidebar-panel-header__row {\\n    width: 100%;\\n  }\\n\\n  .sidebar-sections {\\n    &__back-to-forum {\\n      color: var(--d-sidebar-link-color);\\n      display: flex;\\n      align-items: center;\\n\\n      svg {\\n        margin-right: var(--d-sidebar-section-link-prefix-margin-right);\\n        height: 0.75em;\\n        width: 0.75em;\\n        color: var(--d-sidebar-link-icon-color);\\n      }\\n    }\\n  }\\n\\n  hr {\\n    margin: 0;\\n    height: auto;\\n  }\\n\\n  .panel-header {\\n    position: absolute;\\n    right: 20px;\\n  }\\n\\n  ul {\\n    @include unstyled-list;\\n  }\\n\\n  .panel-body {\\n    display: flex;\\n    touch-action: pan-y pinch-zoom;\\n    overflow: hidden;\\n    height: 100%;\\n  }\\n\\n  .panel-body-contents {\\n    max-height: 100%;\\n    width: 100%;\\n    display: flex;\\n    flex-direction: column;\\n\\n    // 2em padding very useful for iOS Safari's overlayed bottom nav\\n    // padding-bottom: calc(env(safe-area-inset-bottom) + 2em);\\n  }\\n\\n  .panel-body-bottom {\\n    display: flex;\\n    flex: 1 0 0;\\n    flex-wrap: wrap;\\n    padding: 0.75em 0.75em max(env(safe-area-inset-bottom), 0.75em);\\n\\n    .show-all {\\n      display: flex;\\n      flex: 1 1 auto;\\n\\n      button {\\n        width: 100%;\\n      }\\n    }\\n\\n    .notifications-dismiss {\\n      margin-left: 0.5em;\\n    }\\n  }\\n\\n  .badge-notification {\\n    vertical-align: text-bottom;\\n  }\\n\\n  .sidebar-filter {\\n    width: 100%;\\n  }\\n\\n  .sidebar-search {\\n    width: 100%;\\n  }\\n\\n  .empty-state {\\n    padding: 0.5em 1em;\\n  }\\n}\\n\\n.search-menu .menu-panel {\\n  width: 500px;\\n}\\n\\n.user-menu.revamped {\\n  --user-menu-border-width: 1px;\\n  right: 0;\\n  padding: 0;\\n  width: unset;\\n\\n  @include viewport.until(sm) {\\n    width: 320px;\\n  }\\n\\n  .panel-body-bottom {\\n    flex: 0;\\n  }\\n\\n  .menu-tabs-container {\\n    display: flex;\\n    flex-direction: column;\\n    overflow-y: auto;\\n    overscroll-behavior: contain;\\n  }\\n\\n  .tabs-list {\\n    display: flex;\\n    flex-direction: column;\\n\\n    .btn {\\n      display: flex;\\n      position: relative;\\n      border-radius: 0;\\n      padding: 0.375em; // 6px\\n\\n      @include viewport.until(sm) {\\n        padding: 0.75em 0.875em; // 12px 14px\\n      }\\n\\n      @media screen and (height <= 400px) {\\n        // helps with 400% zoom level\\n        font-size: var(--font-down-1);\\n        padding: 0.125em 0.375em; // 2px 6px\\n      }\\n\\n      .d-icon {\\n        border-radius: var(--d-border-radius);\\n        color: var(--primary-medium);\\n        padding: 0.5em; // 8px\\n      }\\n\\n      .badge-notification {\\n        background-color: var(--tertiary-med-or-tertiary);\\n        position: absolute;\\n        right: 6px;\\n        top: 6px;\\n        font-size: var(--font-down-3);\\n\\n        @media screen and (height <= 400px) {\\n          // helps with 400% zoom level\\n          right: 3px;\\n          top: 0;\\n        }\\n      }\\n\\n      &.active {\\n        .d-icon {\\n          color: var(--d-sidebar-active-color);\\n          background-color: var(--d-sidebar-active-background);\\n        }\\n      }\\n\\n      &:not(.active):hover,\\n      &:not(.active):focus-visible {\\n        background: none;\\n\\n        .d-icon {\\n          background-color: var(--d-hover);\\n        }\\n      }\\n    }\\n  }\\n\\n  .bottom-tabs {\\n    border-top: var(--user-menu-border-width) solid var(--content-border-color);\\n  }\\n\\n  .panel-body-contents {\\n    display: flex;\\n    flex-direction: row-reverse;\\n\\n    @include viewport.until(sm) {\\n      .quick-access-panel li {\\n        padding-block: 0.15em;\\n      }\\n    }\\n  }\\n\\n  .quick-access-panel {\\n    width: 320px;\\n    justify-content: space-between;\\n    box-sizing: border-box;\\n    border-right: var(--user-menu-border-width) solid\\n      var(--content-border-color);\\n    min-width: 0; // makes sure menu tabs don't go off screen\\n  }\\n\\n  #quick-access-profile {\\n    display: inline;\\n\\n    ul {\\n      flex-wrap: nowrap;\\n      height: 100%;\\n      align-items: center;\\n      overflow-y: auto; // really short viewports\\n    }\\n\\n    li {\\n      flex: 1 1 auto;\\n      display: flex;\\n      flex-direction: column;\\n      max-height: 3.25em;\\n\\n      > * {\\n        // button, a, and everything else\\n        align-items: center;\\n        margin: 0;\\n        padding: var(--list-item-padding);\\n        flex: 1 1 auto;\\n      }\\n\\n      img.emoji {\\n        height: 1em;\\n        width: 1em;\\n        padding-top: 0.2em;\\n        margin-right: 0.5em;\\n      }\\n\\n      .d-icon {\\n        padding-top: 0;\\n      }\\n\\n      &.enabled .d-icon {\\n        color: var(--tertiary);\\n      }\\n    }\\n\\n    .set-user-status {\\n      .emoji {\\n        padding-top: 0;\\n      }\\n    }\\n\\n    .profile-tab-btn {\\n      justify-content: unset;\\n      line-height: var(--line-height-large);\\n      width: 100%;\\n\\n      .relative-date {\\n        font-size: var(--font-down-3);\\n        color: var(--primary-medium);\\n      }\\n\\n      .d-icon {\\n        padding: 0;\\n      }\\n    }\\n\\n    .do-not-disturb {\\n      .d-icon-toggle-on {\\n        color: var(--tertiary);\\n      }\\n    }\\n\\n    hr {\\n      border-top: var(--user-menu-border-width) solid\\n        var(--content-border-color);\\n      width: 100%;\\n    }\\n  }\\n}\\n\\n.hamburger-panel {\\n  .panel-body {\\n    overflow-y: auto;\\n  }\\n\\n  @include viewport.until(sm) {\\n    .sidebar-section-wrapper {\\n      margin-bottom: 1.2em;\\n    }\\n  }\\n\\n  @include viewport.from(sm) {\\n    // sidebar-hamburger hybrid\\n    .revamped {\\n      --d-sidebar-row-height: 1.875rem;\\n      width: 22.5rem;\\n\\n      .panel-body-content {\\n        width: 100%;\\n        min-width: 0; // prevent content blowing out width\\n      }\\n\\n      .sidebar-section-wrapper {\\n        .sidebar-section-header-button {\\n          opacity: 1;\\n        }\\n\\n        .sidebar-section-link.active {\\n          font-weight: normal;\\n          background: var(--d-hover);\\n        }\\n\\n        .sidebar-section-header-wrapper .select-kit .btn:hover {\\n          background: transparent;\\n        }\\n\\n        &.sidebar-section {\\n          padding-top: 0.5em;\\n\\n          .sidebar-section-header-wrapper {\\n            margin: 0 0 0.5em;\\n            padding-bottom: 0.25em;\\n          }\\n\\n          .sidebar-section-content {\\n            display: grid;\\n            grid-template-columns: 1fr 1fr;\\n\\n            li {\\n              min-width: 0;\\n            }\\n          }\\n        }\\n      }\\n\\n      .sidebar-section-link-wrapper\\n        .sidebar-section-link-hover:hover\\n        .sidebar-section-hover-button {\\n        background: transparent;\\n      }\\n\\n      .sidebar-footer-wrapper {\\n        padding: 0;\\n        margin-top: 1em;\\n\\n        .sidebar-footer-container {\\n          padding: 0;\\n          border: none;\\n          background: var(--secondary);\\n\\n          &::before {\\n            top: -1.5em;\\n            background: linear-gradient(\\n              to bottom,\\n              transparent,\\n              rgb(var(--secondary-rgb), 1)\\n            );\\n          }\\n        }\\n      }\\n    }\\n  }\\n}\\n\\n.menu-links.columned {\\n  li {\\n    width: 50%;\\n    float: left;\\n  }\\n}\\n\\n// Panel / user-notification-list styles. **not** menu panel sizing styles\\n.user-menu .quick-access-panel,\\n.user-notifications-list {\\n  width: 100%;\\n  display: flex;\\n  flex-direction: column;\\n  min-height: 0;\\n  max-height: 100%;\\n\\n  /* as a big ol' click target, don't let text inside be selected */\\n  @include unselectable;\\n\\n  &:focus {\\n    outline: none;\\n  }\\n\\n  .double-user,\\n  .multi-user {\\n    white-space: unset;\\n  }\\n\\n  .item-label {\\n    overflow: hidden;\\n    white-space: nowrap;\\n    text-overflow: ellipsis;\\n    color: var(--primary);\\n  }\\n\\n  h3 {\\n    padding: 0 0.4em;\\n    font-weight: bold;\\n    margin: 0.5em 0;\\n  }\\n\\n  ul {\\n    display: flex;\\n    flex-flow: column wrap;\\n    overflow: hidden;\\n    max-height: 100%;\\n  }\\n\\n  .user-menu-button-profile {\\n    .item-label {\\n      font-weight: normal;\\n    }\\n\\n    .d-icon {\\n      color: var(--primary-500);\\n    }\\n  }\\n\\n  li {\\n    box-sizing: border-box;\\n    list-style-type: none;\\n\\n    &.unread,\\n    &.pending {\\n      background-color: var(--d-unread-notification-background);\\n    }\\n\\n    &:hover {\\n      background-color: var(--d-hover);\\n      outline: none;\\n    }\\n\\n    &:focus-within {\\n      background: var(--d-hover);\\n\\n      a {\\n        // we don't need the link focus because we're styling the parent\\n        outline: 0;\\n      }\\n\\n      .btn-flat:focus {\\n        // undo default btn-flat style\\n        background: transparent;\\n      }\\n    }\\n\\n    // This is until other languages remove the HTML from within\\n    // notifications. It can then be removed\\n    div .fa {\\n      display: none;\\n    }\\n\\n    span.double-user,\\n    // e.g., \\"username, username2\\"\\n    span.multi-user\\n    // e.g., \\"username and n others\\"\\n    {\\n      display: inline;\\n      max-width: 100%;\\n      align-items: baseline;\\n      white-space: nowrap;\\n    }\\n\\n    span.multi-user\\n    // e.g., \\"username, username2, and n others\\"\\n    {\\n      span.multi-username:nth-of-type(2) {\\n        // margin between username2 and \\"and n others\\"\\n        margin-right: 0.25em;\\n      }\\n    }\\n\\n    // truncate when usernames are very long\\n    span.multi-username {\\n      @include ellipsis;\\n      flex: 0 1 auto;\\n      min-width: 1.2em;\\n      max-width: 10em;\\n\\n      &:nth-of-type(2) {\\n        // margin for comma between username and username2\\n        margin-left: 0.25em;\\n      }\\n    }\\n\\n    a {\\n      display: flex;\\n      padding: var(--list-item-padding);\\n\\n      .item-label {\\n        font-weight: bold;\\n      }\\n\\n      .item-description {\\n        color: var(--primary);\\n        overflow: hidden; // clears the text from wrapping below icons\\n        overflow-wrap: break-word;\\n\\n        @include line-clamp(3);\\n      }\\n    }\\n\\n    a,\\n    button {\\n      > div {\\n        display: flex;\\n        flex-direction: column;\\n        overflow: hidden;\\n      }\\n    }\\n\\n    p {\\n      margin: 0;\\n      overflow: hidden;\\n    }\\n  }\\n\\n  li:not(.show-all) {\\n    padding: 0;\\n    align-self: flex-start;\\n    width: 100%;\\n\\n    .d-icon {\\n      padding-top: 0.2em;\\n      margin-right: 0.5em;\\n    }\\n  }\\n\\n  .is-warning {\\n    .d-icon-envelope {\\n      color: var(--danger);\\n    }\\n  }\\n\\n  .read,\\n  .bookmark {\\n    background-color: var(--secondary);\\n\\n    a .d-icon {\\n      color: var(--primary-medium);\\n    }\\n  }\\n\\n  .none {\\n    padding-top: 5px;\\n  }\\n\\n  .spinner-container {\\n    min-height: 2em;\\n    margin: auto;\\n  }\\n\\n  .spinner {\\n    width: 20px;\\n    height: 20px;\\n    border-width: 2px;\\n    margin: 0 auto;\\n  }\\n\\n  .show-all a {\\n    width: 100%;\\n    display: flex;\\n    justify-content: center;\\n    align-items: center;\\n    min-height: 30px;\\n    color: var(--primary-med-or-secondary-high);\\n    background: var(--blend-primary-secondary-5);\\n\\n    &:hover {\\n      color: var(--primary);\\n      background: var(--primary-low);\\n    }\\n  }\\n}\\n\\n// Styles to have user avatar positioned and sized correctly\\n.user-menu.show-avatars,\\n.user-notifications-list.show-avatars {\\n  li.notification,\\n  li.bookmark,\\n  li.reviewable,\\n  li.message {\\n    a {\\n      color: var(--primary);\\n      align-items: center;\\n\\n      .item-label {\\n        font-weight: bold;\\n      }\\n\\n      .item-description {\\n        color: var(--primary);\\n\\n        @include line-clamp(3);\\n      }\\n\\n      .icon-avatar {\\n        display: flex;\\n        position: relative;\\n        overflow: visible;\\n        flex-shrink: 0;\\n        width: 2em;\\n        height: 2em;\\n        margin: 0.3em 1em auto 0;\\n\\n        .avatar {\\n          width: 100%;\\n          height: 100%;\\n        }\\n\\n        &__icon-wrapper {\\n          position: absolute;\\n          right: -0.65em;\\n          top: -0.45em;\\n          display: flex;\\n          justify-content: center;\\n          align-items: center;\\n          width: 22px;\\n          height: 22px;\\n          border-radius: 100%;\\n          background: var(--secondary);\\n\\n          .d-icon {\\n            display: block;\\n            margin: 0;\\n            padding: 0;\\n            font-size: var(--font-down-1);\\n            color: var(--primary);\\n          }\\n        }\\n      }\\n\\n      & + div {\\n        padding: 0.25em 0;\\n      }\\n    }\\n\\n    &.unread,\\n    &.pending {\\n      .icon-avatar__icon-wrapper {\\n        background: var(--tertiary);\\n\\n        .d-icon {\\n          color: var(--secondary);\\n        }\\n      }\\n    }\\n  }\\n}\\n\\n.hamburger-panel .menu-panel.slide-in {\\n  left: 0;\\n\\n  .panel-body {\\n    display: block;\\n  }\\n\\n  .panel-body-contents {\\n    max-height: unset;\\n    min-height: 100%;\\n  }\\n}\\n\\n.sidebar-section-header {\\n  .sidebar-section-header-global-indicator {\\n    .d-icon {\\n      color: var(--d-sidebar-header-icon-color);\\n    }\\n  }\\n}\\n\\n.sidebar-hamburger-dropdown {\\n  .discourse-no-touch & {\\n    .sidebar-section-wrapper .sidebar-section-header-wrapper:hover,\\n    .sidebar-section-wrapper .sidebar-section-header-wrapper:focus-within {\\n      background: transparent;\\n    }\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\nhtml.modal-open {\\n  // prevents bg scrolling when modal is open\\n  overflow: hidden;\\n  scrollbar-gutter: stable;\\n}\\n\\nhtml.keyboard-visible.mobile-view {\\n  .d-modal {\\n    max-height: calc(var(--composer-vh, 1dvh) * 100);\\n    height: calc(var(--composer-vh, 1dvh) * 100);\\n    bottom: 0;\\n  }\\n\\n  .d-modal__container {\\n    max-height: calc(var(--composer-vh, 1dvh) * 100);\\n    height: calc(var(--composer-vh, 1dvh) * 100);\\n  }\\n}\\n\\nhtml:not(.keyboard-visible).mobile-device {\\n  .d-modal__container {\\n    padding-bottom: env(safe-area-inset-bottom, 1rem);\\n  }\\n}\\n\\n.d-modal {\\n  pointer-events: none; // Allow clicks through wrappers so they hit the adjacent backdrop element\\n  display: flex;\\n  align-items: center;\\n  width: 100%;\\n  height: 100%;\\n  position: fixed;\\n  top: 0;\\n  z-index: z(\\"modal\\", \\"content\\");\\n  overflow: auto;\\n\\n  @include viewport.until(sm) {\\n    align-items: flex-end;\\n  }\\n\\n  @include viewport.from(sm) {\\n    --modal-max-width: 600px;\\n    --modal-width: 30em; // set in ems to scale with user font-size\\n    --modal-min-width: 400px;\\n  }\\n\\n  &__container {\\n    display: flex;\\n    flex-direction: column;\\n    pointer-events: auto;\\n    box-sizing: border-box;\\n    border-radius: var(--d-border-radius);\\n    margin: 0 auto;\\n    background-color: var(--secondary);\\n    box-shadow: var(--shadow-modal);\\n    max-height: var(--modal-max-height, 80vh); // unset, optional theme utility\\n\\n    @include viewport.until(sm) {\\n      // this is a hack to prevent issues on safari with transforms\\n      position: fixed;\\n      width: 100%;\\n      max-width: 100%;\\n      max-height: calc(var(--composer-vh, 1dvh) * 85);\\n\\n      &.is-entering {\\n        @include d-animation(modal-enter-mobile, 250ms, ease);\\n      }\\n\\n      &.is-exiting {\\n        @include d-animation(modal-exit-mobile, 250ms, ease);\\n      }\\n    }\\n\\n    @include viewport.from(sm) {\\n      max-width: var(--modal-max-width);\\n      min-width: var(--modal-min-width);\\n      min-height: var(--modal-min-height); // unset, optional theme utility\\n\\n      .d-modal.--large & {\\n        max-width: 800px;\\n      }\\n\\n      .d-modal.--max & {\\n        max-width: 90vw;\\n      }\\n\\n      .d-modal.has-search & {\\n        height: 80vh; // fixed height so the modal doesnt jump when the search results appear/filter\\n      }\\n\\n      &.is-entering {\\n        @include d-animation(\\n          modal-enter-desktop,\\n          250ms,\\n          cubic-bezier(0.4, 0, 0.2, 1)\\n        );\\n      }\\n\\n      &.is-exiting {\\n        @include d-animation(\\n          modal-exit-desktop,\\n          250ms,\\n          cubic-bezier(0.4, 0, 0.2, 1)\\n        );\\n      }\\n    }\\n  }\\n\\n  &__header {\\n    display: flex;\\n    justify-content: space-between;\\n    align-items: center;\\n    padding: 0.5rem;\\n    border-bottom: 1px solid var(--content-border-color);\\n\\n    &:not(.--has-primary-action) {\\n      padding: 0.5rem 0.5rem 0.5rem 1.5rem; // offset for close button padding\\n    }\\n\\n    .modal-close {\\n      margin-left: auto;\\n      align-self: start;\\n\\n      .d-icon {\\n        font-size: var(--font-up-2);\\n        color: var(--primary-high);\\n      }\\n\\n      &:focus-visible {\\n        .d-icon {\\n          color: var(--primary);\\n        }\\n      }\\n    }\\n  }\\n\\n  .d-modal__primary-action,\\n  .d-modal__dismiss-action {\\n    .btn {\\n      text-transform: capitalize;\\n    }\\n  }\\n\\n  &__title-text {\\n    font-size: var(--font-up-1-rem);\\n    line-height: var(--line-height-medium);\\n\\n    @include viewport.from(sm) {\\n      font-size: var(--font-up-3);\\n    }\\n  }\\n\\n  &__title-text,\\n  &__subtitle-text {\\n    margin: 0;\\n  }\\n\\n  &__body {\\n    overflow-y: auto;\\n    padding: 1rem 1.5rem;\\n    box-sizing: border-box;\\n\\n    &.empty {\\n      display: none;\\n    }\\n\\n    input:where(:not(.form-kit__control-input)) {\\n      width: auto;\\n\\n      &[type=\\"text\\"],\\n      &[type=\\"password\\"],\\n      &[type=\\"number\\"],\\n      &[type=\\"email\\"] {\\n        width: 100%;\\n      }\\n    }\\n\\n    textarea {\\n      width: 100%;\\n\\n      &:not(.--expandable) {\\n        height: 80px;\\n      }\\n    }\\n\\n    .password-confirmation {\\n      display: none;\\n    }\\n\\n    section.field {\\n      padding: 0.25em 0;\\n      margin-bottom: 5px;\\n\\n      &.with-items {\\n        display: flex;\\n        align-items: flex-start;\\n      }\\n\\n      .field-item {\\n        display: inline-block;\\n        margin-right: 10px;\\n      }\\n    }\\n  }\\n\\n  &__footer {\\n    display: flex;\\n    flex-wrap: wrap;\\n    align-items: center;\\n    padding: 1rem 1.5rem;\\n    border-top: 1px solid var(--content-border-color);\\n    gap: 0.5rem;\\n\\n    @include viewport.until(sm) {\\n      &__footer {\\n        margin-top: auto;\\n\\n        .--stacked & {\\n          flex-direction: column;\\n          align-items: stretch;\\n        }\\n      }\\n    }\\n  }\\n\\n  &__backdrop {\\n    user-select: none;\\n    position: fixed;\\n    top: 0;\\n    right: 0;\\n    bottom: 0;\\n    left: 0;\\n    z-index: z(\\"modal\\", \\"overlay\\");\\n    background-color: #000;\\n    animation: fade 0.3s forwards;\\n\\n    &.fade {\\n      opacity: 0;\\n    }\\n\\n    @media (prefers-reduced-motion) {\\n      animation-duration: 0s;\\n    }\\n\\n    &.is-exiting {\\n      @include d-animation(\\n        backdrop-fade-out,\\n        250ms,\\n        cubic-bezier(0.4, 0, 0.2, 1)\\n      );\\n    }\\n  }\\n\\n  #modal-alert {\\n    padding-left: 1.5rem;\\n  }\\n\\n  .ios-device & {\\n    &__footer {\\n      margin-top: auto;\\n    }\\n  }\\n\\n  // fixes modal placement on Android when keyboard is visible\\n  html.keyboard-visible:not(.ios-device) & {\\n    height: calc(100% - env(keyboard-inset-height));\\n\\n    .d-modal__container {\\n      max-height: 100%;\\n      min-height: 100%;\\n      height: 100%;\\n    }\\n  }\\n\\n  pre code {\\n    white-space: pre-wrap;\\n    max-width: var(--modal-max-width);\\n  }\\n\\n  @include viewport.from(sm) {\\n    .category-chooser {\\n      width: 50%;\\n    }\\n  }\\n\\n  .input-hint-text {\\n    margin-left: 0.5em;\\n    color: var(--secondary-high);\\n  }\\n}\\n\\n// fade in\\n@keyframes fade {\\n  from {\\n    opacity: 0;\\n  }\\n\\n  to {\\n    opacity: 0.6;\\n  }\\n}\\n\\n// Modal animations\\n@keyframes modal-enter-desktop {\\n  from {\\n    transform: scale(0.7);\\n    opacity: 0;\\n  }\\n\\n  to {\\n    transform: scale(1);\\n    opacity: 1;\\n  }\\n}\\n\\n@keyframes modal-exit-desktop {\\n  from {\\n    transform: scale(1);\\n    opacity: 1;\\n  }\\n\\n  to {\\n    transform: scale(0.7);\\n    opacity: 0;\\n  }\\n}\\n\\n@keyframes modal-enter-mobile {\\n  from {\\n    transform: translateY(100%);\\n  }\\n\\n  to {\\n    transform: translateY(0);\\n  }\\n}\\n\\n@keyframes modal-exit-mobile {\\n  from {\\n    transform: translateY(0);\\n  }\\n\\n  to {\\n    transform: translateY(100%);\\n  }\\n}\\n\\n@keyframes backdrop-fade-out {\\n  from {\\n    opacity: 0.6;\\n  }\\n\\n  to {\\n    opacity: 0;\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n@mixin bordered-horizontal-nav($border-width) {\\n  li {\\n    flex: 1 1 auto;\\n    margin: 0;\\n    display: flex;\\n\\n    a {\\n      box-sizing: border-box;\\n      width: 100%;\\n      display: flex;\\n      justify-content: center;\\n      align-items: center;\\n      position: relative;\\n\\n      @include viewport.until(xl) {\\n        font-size: var(--font-0);\\n      }\\n\\n      span {\\n        line-height: normal;\\n\\n        @include ellipsis;\\n      }\\n    }\\n  }\\n}\\n\\n@mixin bordered-nav-pills {\\n  width: 100%;\\n  margin: 0;\\n\\n  .d-icon {\\n    font-size: var(--font-down-1);\\n  }\\n\\n  &.main-nav {\\n    @include viewport.until(lg) {\\n      li {\\n        .d-icon {\\n          font-size: var(--font-up-1);\\n          margin: 0;\\n        }\\n\\n        span {\\n          display: none;\\n        }\\n      }\\n    }\\n\\n    .has-sidebar-page & {\\n      @include viewport.until(lg) {\\n        span {\\n          display: none;\\n        }\\n      }\\n    }\\n  }\\n}\\n\\n.new-user-wrapper {\\n  .user-navigation {\\n    --user-navigation__border-width: 4px;\\n    border-bottom: 1px solid var(--content-border-color);\\n\\n    .nav-pills {\\n      @include bordered-nav-pills;\\n      @include bordered-horizontal-nav(var(--user-navigation__border-width));\\n    }\\n  }\\n\\n  .user-navigation-primary {\\n    [class*=\\"horizontal-overflow-nav__scroll\\"] {\\n      font-size: var(--font-up-1);\\n\\n      .d-icon {\\n        margin-top: 0.15em; // minor alignment\\n      }\\n    }\\n  }\\n\\n  [class*=\\"horizontal-overflow-nav__scroll-\\"] {\\n    --fade-color: var(--d-content-background, var(--secondary));\\n    background-color: var(--d-content-background, var(--secondary));\\n  }\\n\\n  .user-navigation-secondary {\\n    position: relative;\\n    display: flex;\\n    min-width: 0;\\n    gap: 0 0.5em;\\n    font-size: var(--font-down-1);\\n\\n    .select-kit .select-kit-header {\\n      height: 100%;\\n      padding: 0.5em 1em;\\n    }\\n\\n    .select-kit-collection {\\n      font-size: var(--font-up-1);\\n    }\\n\\n    .messages-dropdown-trigger {\\n      @include viewport.from(sm) {\\n        max-width: clamp(100px, 20vw, 200px);\\n      }\\n      box-sizing: border-box;\\n\\n      .d-button-label {\\n        @include ellipsis;\\n      }\\n    }\\n\\n    .category-breadcrumb {\\n      width: auto;\\n      margin: calc(var(--nav-space) / 2) 0;\\n\\n      @include viewport.until(xl) {\\n        font-size: var(--font-down-1);\\n      }\\n\\n      > li {\\n        margin: 0;\\n      }\\n    }\\n\\n    .navigation-controls {\\n      margin: calc(var(--nav-space) / 2) 0;\\n      flex-wrap: nowrap;\\n\\n      @include viewport.until(xl) {\\n        font-size: var(--font-down-1);\\n      }\\n    }\\n\\n    .nav-pills {\\n      flex: 1 1 auto;\\n      justify-content: flex-start;\\n      height: 100%;\\n\\n      li {\\n        flex: 1 0 auto;\\n\\n        a {\\n          span {\\n            text-overflow: unset;\\n          }\\n        }\\n      }\\n    }\\n  }\\n\\n  .empty-state {\\n    margin: 1em 0;\\n  }\\n\\n  .solo-preference {\\n    grid-column-start: 1;\\n    grid-column-end: -1;\\n  }\\n}\\n\\n.user-preferences-tracking-page {\\n  .user-preferences .form-vertical {\\n   