   }\\n  }\\n}\\n\\naside.onebox.preview-error .site-icon {\\n  width: 16px;\\n  height: 16px;\\n  margin-right: 0.5em;\\n}\\n\\n.onebox.threadsstatus .onebox-body {\\n  .thumbnail,\\n  .thumbnail.onebox-avatar {\\n    width: 36px;\\n    height: 36px;\\n    margin-right: 12px;\\n  }\\n\\n  .threads-screen-name {\\n    font-size: var(--font-down-1);\\n  }\\n\\n  h4 {\\n    margin-bottom: 0;\\n  }\\n\\n  .thread-contents .thread-description {\\n    white-space: pre-line;\\n  }\\n\\n  p,\\n  .thread-contents {\\n    clear: left;\\n    padding: 1em 0;\\n\\n    .quoted {\\n      border: 1px solid var(--content-border-color);\\n      padding: 0.5em 1em;\\n      margin-top: 1em;\\n      white-space: normal;\\n\\n      .quoted-link {\\n        color: inherit;\\n      }\\n\\n      .quoted-title {\\n        font-weight: bold;\\n        margin: 0.5em 0;\\n        padding: 0;\\n\\n        span {\\n          font-weight: lighter;\\n          color: var(--primary-medium);\\n        }\\n      }\\n\\n      div {\\n        margin-bottom: 5px;\\n      }\\n    }\\n  }\\n\\n  .date {\\n    display: flex;\\n    line-height: var(--line-height-small);\\n\\n    .timestamp {\\n      color: var(--primary-medium);\\n    }\\n  }\\n\\n  .like,\\n  .replies {\\n    align-items: center;\\n    color: var(--primary-medium);\\n    display: flex;\\n    margin-left: 0.75em;\\n\\n    svg {\\n      fill: currentcolor;\\n      margin-right: 0.25em;\\n    }\\n  }\\n\\n  .is-reply {\\n    color: var(--primary-medium);\\n    margin-right: 0.25em;\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.archetype-private_message {\\n  --pm-padding: var(--space-5);\\n  --pm-content-width: calc(\\n    var(--topic-body-width) + var(--topic-body-width-padding) * 2 +\\n      var(--pm-padding)\\n  );\\n\\n  .topic-post {\\n    margin-bottom: var(--space-4);\\n\\n    @include viewport.until(sm) {\\n      article {\\n        border-top: none;\\n      }\\n    }\\n\\n    &:last-child {\\n      margin-bottom: var(--space-6);\\n    }\\n  }\\n\\n  .small-action {\\n    margin-bottom: var(--space-4);\\n\\n    @include viewport.until(sm) {\\n      border-radius: var(--d-border-radius);\\n      border: 1px solid var(--content-border-color);\\n    }\\n\\n    .topic-avatar {\\n      border-top: none;\\n      padding-top: 1.1em;\\n\\n      @include viewport.until(sm) {\\n        display: none;\\n      }\\n\\n      .d-icon {\\n        margin-right: -0.25em;\\n        background: var(--secondary);\\n      }\\n    }\\n\\n    .small-action-desc {\\n      margin-left: calc(var(--pm-padding) * -1);\\n      padding-left: var(--space-8);\\n      border-radius: var(--d-border-radius);\\n      width: var(--pm-content-width);\\n\\n      @include viewport.until(sm) {\\n        border: 0;\\n      }\\n\\n      @include viewport.from(sm) {\\n        border: 1px solid var(--content-border-color);\\n      }\\n    }\\n\\n    .small-action-buttons {\\n      margin-right: var(--space-4);\\n    }\\n\\n    &.topic-post-visited {\\n      max-width: var(--pm-content-width);\\n\\n      @include viewport.from(sm) {\\n        margin-left: 1.6em;\\n        margin-bottom: var(--space-6);\\n      }\\n    }\\n  }\\n\\n  .regular.contents {\\n    border-radius: var(--d-border-radius);\\n    border: 1px solid var(--content-border-color);\\n    padding-left: var(--pm-padding);\\n    margin-left: calc(var(--pm-padding) * -1);\\n\\n    @include viewport.until(sm) {\\n      margin-left: 0;\\n      padding: var(--space-6) var(--space-4) 0;\\n    }\\n  }\\n\\n  .topic-timer-info,\\n  .topic-avatar,\\n  .topic-body {\\n    border: none;\\n  }\\n\\n  .topic-avatar {\\n    .avatar {\\n      background: var(--secondary);\\n    }\\n\\n    @include viewport.until(sm) {\\n      margin-bottom: -1em; // intentional overlap\\n    }\\n  }\\n\\n  .topic-body {\\n    @include viewport.until(sm) {\\n      .topic-body {\\n        flex: 1 1 auto;\\n      }\\n    }\\n\\n    .cooked {\\n      box-sizing: border-box;\\n      margin-top: var(--space-1);\\n      padding-right: calc(var(--topic-body-width-padding) * 2);\\n\\n      @include viewport.until(sm) {\\n        padding: 0;\\n        margin: 0;\\n      }\\n    }\\n  }\\n\\n  .post-menu-area {\\n    margin: var(--space-2) 0 var(--topic-body-width-padding);\\n\\n    @include viewport.from(sm) {\\n      padding-right: var(--topic-body-width-padding);\\n    }\\n  }\\n\\n  .who-liked {\\n    box-sizing: border-box;\\n    padding-right: var(--topic-body-width-padding);\\n  }\\n\\n  .post-notice {\\n    box-sizing: border-box;\\n    border-radius: var(--d-border-radius);\\n    background-color: var(--tertiary-very-low);\\n    border-color: var(--tertiary-very-low);\\n    margin-bottom: var(--space-4);\\n    padding: var(--pm-padding) var(--space-4);\\n    width: 100%;\\n    max-width: calc(\\n      var(--topic-body-width) + var(--topic-body-width-padding) * 2 +\\n        var(--topic-avatar-width) - 1.65em\\n    );\\n\\n    @include viewport.from(sm) {\\n      margin-left: 1.65em;\\n      padding-inline: var(--space-8);\\n    }\\n\\n    &.old {\\n      border: 1px solid var(--content-border-color);\\n\\n      @include viewport.until(sm) {\\n        padding-top: var(--pm-padding);\\n      }\\n    }\\n  }\\n\\n  .topic-map {\\n    margin-top: var(--space-2);\\n    padding: var(--space-3);\\n    display: grid;\\n    grid-template-areas: \\"contents additional\\" \\"pm-map pm-map\\";\\n    grid-template-columns: 1fr auto;\\n    border-radius: var(--d-border-radius);\\n    border: 1px solid var(--content-border-color);\\n    max-width: calc(\\n      var(--topic-body-width) + (var(--topic-body-width-padding) * 2) + 1.3em\\n    );\\n\\n    @include viewport.from(sm) {\\n      padding-left: var(--space-8);\\n      margin-left: calc(var(--pm-padding) + var(--space-1));\\n    }\\n\\n    .map {\\n      padding-top: var(--pm-padding);\\n    }\\n\\n    &__contents {\\n      grid-area: contents;\\n    }\\n\\n    &__additional-contents {\\n      grid-area: additional;\\n    }\\n\\n    &__private-message-map {\\n      grid-area: pm-map;\\n      padding: var(--space-2) var(--pm-padding) 0 0;\\n    }\\n\\n    .participants {\\n      display: flex;\\n      flex-wrap: wrap;\\n      align-items: center;\\n      gap: var(--space-2);\\n\\n      & + .controls {\\n        margin-top: var(--space-2);\\n      }\\n\\n      &.hide-names .user {\\n        .username,\\n        .group-name {\\n          display: none;\\n        }\\n      }\\n\\n      .user {\\n        @include ellipsis;\\n        display: flex;\\n        align-items: center;\\n        border-radius: var(--d-border-radius);\\n\\n        .user-link,\\n        .group-link {\\n          @include ellipsis;\\n          display: flex;\\n          align-items: center;\\n          color: var(--primary-high);\\n\\n          &:hover {\\n            color: var(--primary);\\n          }\\n        }\\n\\n        .group-link {\\n          .d-icon {\\n            margin-left: var(--space-2);\\n          }\\n        }\\n\\n        .avatar,\\n        .d-icon-users {\\n          margin-left: var(--space-1);\\n          margin-right: var(--space-1);\\n        }\\n\\n        .username,\\n        .group-name {\\n          margin-right: var(--space-1);\\n          padding-block: var(--space-1);\\n        }\\n\\n        &:last-child {\\n          margin-right: 0;\\n        }\\n\\n        .remove-invited {\\n          display: flex;\\n          flex: 1 0 0px;\\n          align-items: center;\\n          justify-content: center;\\n          align-self: stretch;\\n          box-sizing: border-box;\\n          border-radius: 0;\\n        }\\n      }\\n    }\\n  }\\n\\n  .map:first-of-type .buttons .btn {\\n    border: none;\\n    border-radius: var(--d-border-radius);\\n  }\\n\\n  .embedded-posts {\\n    border: none;\\n\\n    .topic-body {\\n      overflow: visible;\\n      width: 100%;\\n    }\\n\\n    .topic-avatar {\\n      padding-left: 0;\\n    }\\n\\n    .collapse-down,\\n    .collapse-up {\\n      display: none;\\n    }\\n\\n    &.bottom {\\n      margin-bottom: 0;\\n      margin-right: calc(var(--topic-body-width-padding) * 2);\\n    }\\n\\n    &.top {\\n      .cooked {\\n        border: 1px solid var(--content-border-color);\\n        border-radius: var(--d-border-radius);\\n        margin-left: calc(var(--pm-padding) * -1);\\n        padding-left: 2.15em;\\n      }\\n\\n      .row {\\n        .topic-body,\\n        .topic-avatar {\\n          border: none;\\n        }\\n      }\\n    }\\n  }\\n\\n  .timeline-replies {\\n    display: flex;\\n    align-items: baseline;\\n    margin-right: 0.15em;\\n  }\\n\\n  // special post type colors\\n  .current-user-post {\\n    .regular.contents {\\n      background: var(--tertiary-very-low);\\n      border-color: var(--tertiary-very-low);\\n    }\\n\\n    .embedded-posts {\\n      .topic-body .cooked {\\n        background: transparent;\\n      }\\n    }\\n  }\\n\\n  .moderator {\\n    .topic-body.highlighted {\\n      .regular.contents {\\n        animation: none;\\n      }\\n    }\\n\\n    .regular.contents {\\n      background: var(--highlight-low);\\n      border-color: var(--highlight-low);\\n\\n      .cooked {\\n        background: transparent;\\n      }\\n    }\\n  }\\n\\n  .whisper {\\n    .topic-body .regular.contents {\\n      background: transparent;\\n      border: 2px dashed var(--primary-low);\\n    }\\n\\n    &.current-user-post .topic-body .regular.contents {\\n      border: 2px dashed var(--tertiary-low);\\n    }\\n  }\\n\\n  .deleted {\\n    .topic-body .regular.contents {\\n      background: var(--danger-low);\\n      border-color: transparent;\\n\\n      .cooked {\\n        background: transparent;\\n      }\\n    }\\n\\n    &.whisper {\\n      .topic-body .regular.contents {\\n        border-color: var(--danger-low-mid);\\n      }\\n    }\\n  }\\n\\n  @include viewport.from(sm) {\\n    #topic-footer-buttons {\\n      padding-left: var(--space-6);\\n    }\\n  }\\n}\\n","// LEGACY STYLES\\n// some plugins rely on these (discourse-topic-voting is one)\\n.popup-menu {\\n  background-color: var(--secondary);\\n  width: 14em;\\n  border: 1px solid var(--content-border-color);\\n  z-index: z(\\"dropdown\\");\\n  box-shadow: var(--shadow-card);\\n\\n  ul {\\n    margin: 0;\\n    list-style: none;\\n\\n    li {\\n      border-bottom: 1px solid rgb(var(--primary-low-rgb), 0.5);\\n\\n      &:last-child {\\n        border: none;\\n      }\\n    }\\n  }\\n\\n  .btn {\\n    justify-content: left;\\n    text-align: left;\\n    background: none;\\n    width: 100%;\\n    padding: 0.5em;\\n    border-radius: 0;\\n    margin: 0;\\n\\n    .d-icon {\\n      color: var(--primary-medium);\\n      align-self: flex-start;\\n      margin-right: 0.75em;\\n      margin-top: 0.1em; // vertical alignment\\n    }\\n\\n    &:focus,\\n    &:hover {\\n      color: var(--primary);\\n      background: var(--d-hover);\\n\\n      .d-icon {\\n        color: var(--primary-medium);\\n      }\\n    }\\n\\n    &.popup-menu-btn-danger {\\n      .d-icon {\\n        color: var(--danger);\\n      }\\n\\n      .d-button-label {\\n        color: var(--primary);\\n      }\\n\\n      &:focus,\\n      &:hover {\\n        background: var(--danger-low);\\n\\n        .d-icon,\\n        .d-button-label {\\n          color: var(--danger);\\n        }\\n      }\\n    }\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.reorder-categories {\\n  thead {\\n    th {\\n      padding-bottom: 0.5em;\\n    }\\n  }\\n\\n  input[type=\\"number\\"] {\\n    margin: 0;\\n    max-width: 4em;\\n  }\\n\\n  table {\\n    width: 100%;\\n    padding-bottom: 150px;\\n    margin: 0 0.667em;\\n\\n    td {\\n      padding: 0.5em 0.5em 0.5em 0;\\n      min-width: 10em;\\n    }\\n  }\\n\\n  .badge-category__wrapper .badge-category {\\n    max-width: 20em;\\n\\n    @include viewport.until(sm) {\\n      max-width: 30vw;\\n    }\\n  }\\n\\n  &__header-position {\\n    text-align: right;\\n  }\\n}\\n\\n.reorder-categories-actions {\\n  display: flex;\\n  justify-content: end;\\n  gap: 0.5rem;\\n}\\n\\n.reorder-categories-depth-1 {\\n  margin-left: 20px;\\n}\\n\\n.reorder-categories-depth-2 {\\n  margin-left: 40px;\\n}\\n","@use \\"lib/viewport\\";\\n\\n.review-item {\\n  --review-item-padding: var(--space-4);\\n  display: flex;\\n  flex-wrap: nowrap;\\n  gap: var(--space-4) 0;\\n  align-items: flex-start;\\n  margin-bottom: var(--space-8);\\n  position: relative;\\n  z-index: z(\\"base\\");\\n  border-radius: var(--d-border-radius);\\n\\n  &:has(.select-kit.is-expanded) {\\n    z-index: z(\\"dropdown\\");\\n  }\\n\\n  @include viewport.until(sm) {\\n    --review-item-padding: var(--space-2);\\n    border: 1px solid var(--content-border-color);\\n    flex-direction: column;\\n  }\\n\\n  &__primary-content {\\n    position: relative;\\n    flex: 0 1 75%;\\n    min-width: 0;\\n\\n    @include viewport.from(sm) {\\n      border: 1px solid var(--content-border-color);\\n    }\\n\\n    @include viewport.until(sm) {\\n      width: 100%;\\n    }\\n  }\\n\\n  .reviewable-created-date {\\n    font-size: var(--font-down-1);\\n    color: var(--secondary-high);\\n    white-space: nowrap;\\n    align-self: baseline;\\n    padding-block: var(--space-1);\\n    line-height: var(--line-height-small);\\n\\n    @include viewport.until(sm) {\\n      justify-self: end;\\n      padding-inline: 0.15em;\\n    }\\n  }\\n\\n  .reviewable-permalink-copy {\\n    position: relative;\\n    right: calc(var(--space-2) * -1);\\n    padding-block: 0.15em;\\n\\n    @include viewport.until(sm) {\\n      justify-self: end;\\n    }\\n\\n    .post-action-feedback-alert {\\n      top: -0.95rem;\\n      left: 0;\\n    }\\n\\n    .d-icon {\\n      color: var(--secondary-high);\\n      margin-right: 0;\\n    }\\n\\n    .post-action-feedback-svg {\\n      fill: var(--success-medium);\\n      right: unset;\\n      left: -0.5em;\\n      top: 0.05em;\\n    }\\n  }\\n\\n  &__aside {\\n    flex: 0 1 25%;\\n    min-width: 0;\\n    position: sticky;\\n    top: var(--header-offset);\\n\\n    @include viewport.until(sm) {\\n      box-sizing: border-box;\\n      width: 100%;\\n      padding-inline: var(--space-4);\\n    }\\n\\n    .reviewable-action,\\n    .reject-post summary {\\n      background-color: var(--d-button-default-bg-color);\\n      color: var(--d-button-default-text-color);\\n\\n      .d-icon {\\n        color: var(--d-button-default-icon-color);\\n      }\\n\\n      &:hover {\\n        background-color: var(--d-button-default-bg-color--hover);\\n        color: var(--d-button-default-text-color--hover);\\n\\n        .d-icon {\\n          color: var(--d-button-default-icon-color--hover);\\n        }\\n      }\\n    }\\n\\n    @include viewport.from(sm) {\\n      padding: var(--space-4);\\n    }\\n\\n    > * {\\n      padding-bottom: var(--space-4);\\n      margin-bottom: var(--space-3);\\n\\n      &:not(:last-child) {\\n        border-bottom: 1px solid var(--content-border-color);\\n      }\\n    }\\n\\n    .dropdown-select-box.reviewable-action-dropdown {\\n      white-space: wrap;\\n      text-wrap: pretty;\\n    }\\n\\n    &-title {\\n      line-height: var(--line-height-medium);\\n      text-wrap: pretty;\\n    }\\n  }\\n\\n  &__flag-summary {\\n    border-radius: var(--d-border-radius);\\n  }\\n\\n  &__header {\\n    display: grid;\\n    grid-template-columns: 1fr auto auto auto;\\n    gap: var(--space-2);\\n    align-items: start;\\n    background-color: var(--primary);\\n    padding: var(--space-3) var(--review-item-padding);\\n    color: var(--secondary);\\n    border-radius: calc(var(--d-border-radius) - 1px)\\n      calc(var(--d-border-radius) - 1px) 0 0;\\n\\n    @include viewport.until(sm) {\\n      display: grid;\\n      grid-template-columns: auto auto;\\n      grid-template-rows: auto auto;\\n\\n      .post-action-feedback-button {\\n        height: auto;\\n      }\\n    }\\n  }\\n\\n  &__label-badges {\\n    display: flex;\\n    gap: var(--space-1);\\n    align-items: baseline;\\n    flex-wrap: wrap;\\n    line-height: var(--line-height-small);\\n  }\\n\\n  &__flag-label,\\n  &__meta-label {\\n    white-space: nowrap;\\n    text-align: left;\\n  }\\n\\n  &__meta-label {\\n    font-weight: bold;\\n  }\\n\\n  &__flag-badges {\\n    display: flex;\\n    flex-wrap: wrap;\\n    gap: 0;\\n\\n    .review-item__flag-reason:not(:last-child)::after {\\n      content: \\",\\";\\n      margin-right: var(--space-1);\\n    }\\n  }\\n\\n  &__meta {\\n    display: grid;\\n    grid-template-columns: 10ch 1fr;\\n    column-gap: var(--space-3);\\n    row-gap: var(--space-3);\\n    align-items: start;\\n    padding: var(--space-5) var(--space-4);\\n    border-bottom: 1px solid var(--content-border-color);\\n  }\\n\\n  .reviewable-penalty-icon {\\n    color: var(--danger);\\n  }\\n\\n  &__meta-content {\\n    display: grid;\\n    gap: var(--space-4);\\n    padding: var(--review-item-padding);\\n    grid-template-columns: auto 1fr;\\n\\n    @include viewport.until(sm) {\\n      gap: var(--space-2);\\n      grid-template-columns: auto;\\n    }\\n\\n    .reviewable-user & {\\n      grid-template-columns: 1fr;\\n    }\\n\\n    .badge-category__wrapper {\\n      display: block;\\n    }\\n\\n    .created-by {\\n      display: flex;\\n      gap: var(--space-2);\\n\\n      .deleted-user {\\n        display: flex;\\n        align-items: center;\\n        gap: var(--space-2);\\n\\n        .d-icon {\\n          font-size: var(--font-down-2);\\n          color: var(--primary-high);\\n        }\\n      }\\n\\n      .names {\\n        display: inline-block;\\n\\n        span a {\\n          color: var(--tertiary);\\n        }\\n      }\\n    }\\n  }\\n\\n  &__post {\\n    display: flex;\\n    padding: var(--review-item-padding);\\n\\n    &-content-wrapper {\\n      width: 100%;\\n\\n      .review-item__post-content .transcript {\\n        margin: var(--space-2) 0 0;\\n      }\\n    }\\n\\n    &-content {\\n      box-sizing: border-box;\\n      width: 100%;\\n      max-height: 300px;\\n      overflow: auto;\\n      scrollbar-color: var(--primary-low) transparent;\\n      transition: scrollbar-color 0.25s ease-in-out;\\n      transition-delay: 0.5s;\\n      background: var(--primary-very-low);\\n      padding: var(--review-item-padding);\\n      border-radius: var(--d-border-radius);\\n\\n      img:not(.avatar, .emoji) {\\n        max-width: 100%;\\n        height: auto;\\n      }\\n\\n      .lightbox-wrapper img {\\n        display: block;\\n      }\\n\\n      pre,\\n      code {\\n        white-space: pre-wrap;\\n      }\\n\\n      --scrollbarWidth: 0.5em;\\n\\n      &::-webkit-scrollbar {\\n        width: var(--scrollbarWidth);\\n      }\\n\\n      &::-webkit-scrollbar-thumb {\\n        background-color: transparent;\\n        border-radius: calc(var(--scrollbarWidth) / 2);\\n      }\\n\\n      &::-webkit-scrollbar-track {\\n        background-color: transparent;\\n      }\\n\\n      p:first-of-type {\\n        margin-top: 0;\\n      }\\n\\n      p:last-of-type {\\n        margin-bottom: 0;\\n      }\\n    }\\n  }\\n\\n  &__toggle-post {\\n    margin-top: 0.5em;\\n    background: none;\\n    border: none;\\n    color: var(--primary);\\n    cursor: pointer;\\n  }\\n\\n  &__meta-topic-title {\\n    display: flex;\\n    gap: 0 var(--space-2);\\n\\n    .edits {\\n      .btn .d-icon {\\n        font-size: var(--font-down-2);\\n      }\\n    }\\n  }\\n\\n  &__insights {\\n    padding-inline: var(--review-item-padding);\\n\\n    // The border goes on the nav, not the ul: the ul is the strip's scroller\\n    // and its edge fade would mask a border painted there.\\n    .horizontal-overflow-nav {\\n      border-bottom: 1px solid var(--content-border-color);\\n    }\\n\\n    .nav-pills.action-list {\\n      margin-bottom: 0;\\n    }\\n  }\\n\\n  .reviewable-claimed-topic {\\n    flex-direction: column;\\n    align-items: stretch;\\n    white-space: nowrap;\\n\\n    .d-button-label {\\n      @include ellipsis;\\n    }\\n  }\\n\\n  .reviewable-ip-lookup {\\n    display: flex;\\n    flex-direction: column;\\n    align-items: stretch;\\n    white-space: nowrap;\\n\\n    .d-button-label {\\n      @include ellipsis;\\n    }\\n\\n    button {\\n      justify-content: left;\\n    }\\n  }\\n\\n  &__assigned {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-2);\\n\\n    .d-icon {\\n      color: var(--primary-high);\\n    }\\n\\n    .created-by {\\n      @include ellipsis;\\n    }\\n  }\\n\\n  .editable-fields {\\n    box-sizing: border-box;\\n    padding: var(--review-item-padding);\\n\\n    .d-editor-button-bar {\\n      flex: 1 0 auto;\\n      font-size: var(--font-down-1);\\n      flex-wrap: nowrap;\\n      overflow: scroll;\\n    }\\n\\n    .d-editor-textarea-wrapper {\\n      min-height: 10em;\\n    }\\n  }\\n}\\n\\n.review-item__status {\\n  white-space: nowrap;\\n  align-self: start;\\n  display: inline-flex;\\n  align-items: center;\\n  justify-content: center;\\n  border-radius: 999px;\\n  padding: var(--space-1) var(--space-2);\\n  font-size: var(--font-down-1);\\n  line-height: 1;\\n  background-color: var(--secondary-high);\\n  color: var(--primary);\\n\\n  @include viewport.until(sm) {\\n    justify-self: start;\\n  }\\n\\n  &.--pending {\\n    background: var(--secondary-low);\\n    color: var(--primary-low);\\n  }\\n\\n  &.--rejected {\\n    background-color: var(--danger);\\n    color: var(--secondary);\\n  }\\n\\n  &.--approved,\\n  &.--resolved {\\n    background-color: var(--success);\\n    color: var(--secondary);\\n  }\\n}\\n\\n.review-item__flag-reason {\\n  display: inline-flex;\\n  align-items: center;\\n  line-height: 1;\\n}\\n\\n.review-item__flag-count {\\n  display: inline-flex;\\n  margin-left: var(--space-1);\\n}\\n\\n.review-insight {\\n  display: flex;\\n  flex-direction: column;\\n  gap: var(--space-3);\\n  margin-top: var(--space-2);\\n\\n  &__item,\\n  .loading-container {\\n    padding-inline: var(--space-4);\\n    padding-bottom: var(--space-3);\\n  }\\n\\n  &__item {\\n    display: grid;\\n    grid-template-columns: auto 1fr;\\n    column-gap: var(--space-2);\\n    align-items: start;\\n\\n    &:not(:last-child) {\\n      border-bottom: 1px solid var(--content-border-color);\\n    }\\n  }\\n\\n  &__content {\\n    display: flex;\\n    flex-direction: column;\\n    gap: 0.25rem;\\n  }\\n\\n  &__label {\\n    font-weight: bold;\\n  }\\n\\n  &__description {\\n    font-size: var(--font-down-1);\\n    color: var(--primary-high);\\n    overflow-wrap: anywhere;\\n  }\\n\\n  .reviewable-ip-lookup {\\n    white-space: normal;\\n  }\\n}\\n\\n.review-item__moderator-actions {\\n  display: flex;\\n  flex-direction: column;\\n  gap: var(--space-2);\\n\\n  label {\\n    display: block;\\n  }\\n\\n  button {\\n    justify-content: left;\\n    text-align: left;\\n  }\\n}\\n\\n.review-item__secondary-actions {\\n  display: flex;\\n  flex-direction: column;\\n  gap: var(--space-2);\\n  padding-top: var(--space-2);\\n  border-top: 1px solid var(--content-border-color);\\n}\\n\\n.review-resources {\\n  &__list {\\n    @include unstyled-list;\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-2);\\n  }\\n\\n  &__item {\\n    display: flex;\\n    align-items: flex-start;\\n    gap: var(--space-1);\\n  }\\n\\n  &__icon {\\n    font-size: 1rem;\\n    color: var(--primary-medium);\\n    flex-shrink: 0;\\n    line-height: 1.2;\\n  }\\n}\\n\\n// Timeline Component Styles\\n.reviewable-timeline {\\n  .timeline-events {\\n    display: flex;\\n    flex-direction: column;\\n  }\\n\\n  .timeline-event {\\n    position: relative;\\n    display: flex;\\n    align-items: flex-start;\\n    gap: var(--space-3);\\n    background: var(--secondary);\\n    padding-block: var(--space-4);\\n\\n    &:not(:last-child) {\\n      border-bottom: 1px solid var(--content-border-color);\\n    }\\n\\n    @include viewport.until(sm) {\\n      padding: var(--space-2) 0;\\n\\n      &:last-child {\\n        border-bottom: 1px solid var(--content-border-color);\\n      }\\n    }\