le,\\n    .search-bar {\\n      margin-bottom: 1em;\\n    }\\n\\n    .search-results {\\n      @include search-page-spacing;\\n\\n      @include viewport.until(md) {\\n        padding: 1rem 0.5rem 1rem 0.25rem;\\n      }\\n    }\\n\\n    .result-count {\\n      margin: 0 10%;\\n      padding-block-start: var(--space-4);\\n      font-size: var(--font-up-2);\\n      font-weight: var(--token-font-weight-semibold);\\n\\n      @include viewport.until(lg) {\\n        margin: 0;\\n        padding-inline: 0;\\n      }\\n\\n      // spans can be in different orders depending of locale\\n      span + span {\\n        margin-left: 0.25em;\\n      }\\n\\n      span.term {\\n        background: var(--tertiary-low);\\n      }\\n    }\\n\\n    .search-info {\\n      display: flex;\\n      flex-wrap: wrap;\\n      align-items: center;\\n      margin: 0 10%;\\n      padding-block: var(--space-4);\\n      background: var(--secondary); // needs background for bulk select sticky\\n      border-top: 1px solid var(--content-border-color);\\n\\n      @include viewport.until(lg) {\\n        padding: 1rem 0 0 0;\\n        margin: 0;\\n      }\\n\\n      &.bulk-select-visible {\\n        position: sticky;\\n        top: 60px;\\n        z-index: 10;\\n      }\\n\\n      .sort-by {\\n        margin-left: auto;\\n      }\\n\\n      button {\\n        margin: 0 0.5em 0 0;\\n\\n        @include viewport.until(lg) {\\n          margin: 0 0.5em 0.5em 0;\\n        }\\n      }\\n\\n      #bulk-select {\\n        position: relative;\\n        right: unset;\\n        margin: 0;\\n        padding: 0;\\n        display: inline;\\n\\n        button {\\n          margin-right: 0.5em;\\n        }\\n      }\\n\\n      .sort-by.inline-form label {\\n        margin-bottom: 0;\\n      }\\n\\n      #search-sort-by {\\n        margin-bottom: 0;\\n      }\\n    }\\n  }\\n\\n  .search-notice .fps-invalid {\\n    padding: 0.5em;\\n    background-color: var(--danger-low);\\n    border: 1px solid var(--danger-medium);