 }\\n\\n  .sidebar-section-translations__caption {\\n    margin-bottom: 0.25em;\\n    color: var(--token-color-text-subtle);\\n    font-size: var(--font-down-1);\\n    font-weight: var(--token-font-weight-bold);\\n  }\\n\\n  .sidebar-section-translations__row {\\n    display: grid;\\n    grid-template-columns: minmax(6em, 1fr) 2fr;\\n    align-items: center;\\n    gap: 0.5em;\\n    margin-bottom: 0.5em;\\n\\n    @include viewport.until(sm) {\\n      grid-template-columns: 1fr;\\n      gap: 0.25em;\\n    }\\n\\n    .sidebar-section-translations__source {\\n      overflow-wrap: anywhere;\\n      font-weight: var(--token-font-weight-regular);\\n    }\\n\\n    .sidebar-section-translations__value {\\n      width: 100%;\\n      margin-bottom: 0;\\n\\n      &.--untranslated {\\n        border-style: dashed;\\n      }\\n    }\\n\\n    .warning {\\n      grid-column: 1 / -1;\\n    }\\n  }\\n\\n  .row-wrapper {\\n    display: grid;\\n    grid-template-columns: 2em 4.5em repeat(2, 1fr) 2em;\\n    padding: 0.55em 0 0.7em;\\n    cursor: default;\\n    border-top: 2px solid transparent;\\n    border-bottom: 2px solid transparent;\\n    margin-bottom: -2px;\\n\\n    @include viewport.until(sm) {\\n      grid-template-columns: 4em auto auto min-content;\\n    }\\n\\n    &.header {\\n      padding-bottom: 0;\\n\\n      label {\\n        margin-bottom: 0;\\n      }\\n    }\\n\\n    &.drag-above {\\n      border-top: 2px solid var(--token-color-border-accent);\\n    }\\n\\n    &.drag-below {\\n      border-bottom: 2px solid var(--token-color-border-accent);\\n    }\\n\\n    .link-icon {\\n      grid-column: 2;\\n\\n      @include viewport.until(sm) {\\n        grid-column: 1;\\n      }\\n    }\\n\\n    .input-group {\\n      margin: 0 0.5em;\\n\\n      @include viewport.until(sm) {\\n        margin: 0 0.25em;\\n      }\\n    }\\n  }\\n\\n  .always-public-tooltip {\\n    padding-right: 0.5rem;\\n\\n    .fk-d-tooltip__trigger-container {\\n      align-items: center;\\n      gap: var(--space-1);\\n    }\\n  }\\n\\n  .d-modal__footer {\\n    display: grid;\\n    grid-template-columns: auto 1fr auto;\\n    gap: 0.5em 1em;\\n\\n    @include viewport.until(sm) {\\n      grid-template-columns: auto 1fr;\\n      justify-items: left;\\n\\n      .mark-public-wrapper {\\n        grid-row: 1;\\n        grid-column: 1 / span 2;\\n      }\\n\\n      .checkbox-label {\\n        padding: 0 0 0.5em 0;\\n      }\\n    }\\n\\n    .reset-link,\\n    .delete {\\n      margin: 0;\\n      justify-self: right;\\n    }\\n\\n    .mark-public-wrapper {\\n      &.-disabled label {\\n        cursor: not-allowed;\\n      }\\n\\n      .checkbox-label {\\n        margin: 0;\\n      }\\n    }\\n  }\\n\\n  .select-kit.multi-select .multi-select-header .formatted-selection {\\n    display: none;\\n  }\\n\\n  .select-kit.is-expanded .select-kit-body {\\n    min-width: 220px;\\n  }\\n\\n  .delete-link {\\n    .d-icon {\\n      color: var(--token-color-text-subtle);\\n    }\\n\\n    .discourse-no-touch & {\\n      &:hover {\\n        .d-icon {\\n          color: var(--token-color-icon-danger);\\n        }\\n      }\\n    }\\n  }\\n}\\n\\n.sidebar__panel-switch-button {\\n  margin: 1em 1.3em 0 1.3em;\\n\\n  &:last-of-type {\\n    margin-bottom: 1em;\\n  }\\n}\\n\\n.sidebar-filter {\\n  width: 100%;\\n\\n  &__input-container {\\n    position: relative;\\n    display: flex;\\n    align-items: center;\\n  }\\n\\n  &__input[type=\\"text\\"] {\\n    width: 100%;\\n    margin: 1em 0;\\n  }\\n\\n  &__clear {\\n    width: 2em;\\n    height: 2em;\\n    position: absolute;\\n    right: 0;\\n  }\\n}\\n\\n.sidebar-no-results {\\n  display: block;\\n  margin: 0.5em var(--d-sidebar-row-horizontal-padding) 0\\n    var(--d-sidebar-row-horizontal-padding);\\n\\n  &__title {\\n    font-weight: var(--token-font-weight-bold);\\n  }\\n}\\n\\n.sidebar-search {\\n  width: 100%;\\n\\n  &__input-container {\\n    display: flex;\\n    align-items: center;\\n    border: var(--token-border-width) solid var(--token-color-border-input);\\n    background: var(--token-color-background-input);\\n    box-sizing: border-box;\\n    margin-top: 0.5em;\\n    margin-bottom: 0.5em;\\n    border-radius: var(--token-radius-normal);\\n    overflow: hidden;\\n    padding-inline: var(--d-sidebar-row-horizontal-padding);\\n    gap: var(--d-sidebar-section-link-prefix-margin-right);\\n  }\\n\\n  &__icon.btn.btn-transparent {\\n    flex-shrink: 0;\\n    font-size: var(--d-sidebar-section-link-icon-size);\\n    border: 0;\\n    background: var(--token-color-background-input);\\n    width: var(--d-sidebar-section-link-prefix-width);\\n    padding: 0;\\n\\n    &:hover {\\n      background: transparent !important;\\n    }\\n  }\\n\\n  &__input[type=\\"text\\"] {\\n    margin-bottom: 0;\\n    border: 0;\\n    padding: 0;\\n    width: 100%;\\n    height: var(--d-sidebar-row-height);\\n    cursor: pointer;\\n\\n    &:focus {\\n      outline: none;\\n    }\\n  }\\n\\n  &__shortcut-hint {\\n    margin-right: var(--space-2);\\n  }\\n}\\n\\n.sidebar-panel-header__row {\\n  display: flex;\\n  justify-content: space-between;\\n  align-items: baseline;\\n  color: var(--d-sidebar-link-color);\\n  width: calc(\\n    var(--d-sidebar-width) * var(--d-sidebar-row-horizontal-padding) + 2px\\n  );\\n}\\n\\n.sidebar-toggle-all-sections.btn-transparent {\\n  padding-right: 0;\\n  color: var(--d-sidebar-link-color);\\n\\n  svg {\\n    width: 0.75em;\\n    height: 0.85em;\\n  }\\n}\\n",".sidebar-custom-sections {\\n  .sidebar-section-header {\\n    display: flex;\\n  }\\n\\n  .sidebar-section[data-section-name=\\"community\\"]\\n    .sidebar-section-link-prefix.icon {\\n    cursor: pointer;\\n  }\\n\\n  a {\\n    -webkit-touch-callout: none !important;\\n\\n    @include unselectable;\\n    cursor: pointer;\\n  }\\n}\\n\\n.discourse-touch {\\n  .sidebar-custom-sections {\\n    a:hover {\\n      background: none !important;\\n    }\\n  }\\n}\\n",".sidebar-footer-wrapper {\\n  box-sizing: border-box;\\n  background: va