-size: var(--font-down-4);\\n      flex-shrink: 0;\\n\\n      &.icon {\\n        &.urgent svg {\\n          color: var(--success);\\n        }\\n\\n        &.unread svg {\\n          color: var(--d-sidebar-suffix-color);\\n        }\\n      }\\n    }\\n\\n    .sidebar-section-link-content-text {\\n      @include ellipsis;\\n      min-width: 0;\\n      flex: 0 1 auto;\\n\\n      .user-status-message {\\n        vertical-align: -0.125em;\\n      }\\n\\n      .emoji {\\n        width: 1em;\\n        height: 1em;\\n        vertical-align: baseline;\\n      }\\n\\n      .badge-category__wrapper {\\n        font-size: 100%;\\n        width: 100%;\\n\\n        .badge-category__name {\\n          white-space: nowrap;\\n          overflow: hidden;\\n          text-overflow: ellipsis;\\n        }\\n      }\\n    }\\n  }\\n\\n  &.dropdown-menu__item .sidebar-section-link,\\n  .dropdown-menu__item .sidebar-section-link {\\n    height: var(--d-sidebar-row-height);\\n    padding-inline: var(--d-sidebar-row-horizontal-padding);\\n    border-radius: var(--token-radius-normal);\\n  }\\n\\n  .--link-button {\\n    border: none;\\n    background: inherit;\\n  }\\n\\n  .sidebar-section-link-review {\\n    .sidebar-section-link-content-badge {\\n      color: var(--danger);\\n    }\\n  }\\n\\n  .sidebar-section-link-prefix {\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    flex-shrink: 0;\\n    width: var(--d-sidebar-section-link-prefix-width);\\n\\n    #sidebar-section-content-chat-dms & {\\n      @include viewport.from(sm) {\\n        .prefix-text {\\n          font-size: var(--font-0);\\n        }\\n      }\\n    }\\n\\n    .prefix-image {\\n      border: 1px solid transparent;\\n    }\\n\\n    &.active .prefix-image {\\n      box-shadow: 0 0 0 1px var(--success);\\n    }\\n\\n    &.image {\\n      img {\\n        border-radius: var(--token-radius-full);\\n        aspect-ratio: auto 20 / 20;\\n        width: calc(var(--d-sidebar-section-link-prefix-