ked HTML content in posts (and preview)\\n.cooked,\\n.d-editor-preview {\\n  overflow-wrap: break-word;\\n  line-height: var(--cooked-line-height);\\n\\n  video {\\n    max-width: 100%;\\n\\n    @include viewport.from(sm) {\\n      max-height: 500px;\\n    }\\n  }\\n\\n  img:not(.thumbnail, .ytp-thumbnail-image, .emoji) {\\n    max-width: 100%;\\n    height: auto;\\n    display: inline-block; // Ensure dimensions are maintained even after load error\\n  }\\n\\n  svg {\\n    max-height: 2000px;\\n  }\\n\\n  > *:first-child {\\n    margin-top: 0;\\n  }\\n\\n  h1,\\n  h2,\\n  h3,\\n  h4,\\n  h5,\\n  h6 {\\n    margin: 2rem 0 0.67rem;\\n    line-height: var(--line-height-medium);\\n\\n    @extend %heading-anchor;\\n  }\\n\\n  h1 {\\n    font-size: var(--font-up-3-rem);\\n  }\\n\\n  h2 {\\n    font-size: var(--font-up-2-rem);\\n  }\\n\\n  h3 {\\n    font-size: var(--font-up-1-rem);\\n  }\\n\\n  h4 {\\n    font-size: var(--font-0-rem);\\n  }\\n\\n  h5 {\\n    font-size: var(--font-down-1-rem);\\n  }\\n\\n  h6 {\\n    font-size: var(--font-down-2-rem);\\n  }\\n\\n  a {\\n    overflow-wrap: break-word;\\n  }\\n\\n  mark {\\n    text-decoration: none;\\n    background-color: var(--highlight);\\n  }\\n\\n  ins {\\n    background-color: var(--success-low);\\n    text-decoration: underline;\\n  }\\n\\n  del {\\n    background-color: var(--danger-low);\\n    text-decoration: line-through;\\n  }\\n\\n  // Prevents users from breaking posts with tag nesting\\n  big {\\n    font-size: 1.5rem;\\n  }\\n\\n  small {\\n    font-size: 0.75rem;\\n  }\\n\\n  small small {\\n    font-size: 0.75em;\\n  }\\n\\n  big big {\\n    font-size: 1em;\\n  }\\n\\n  sup sup,\\n  sub sup,\\n  sup sub,\\n  sub sub {\\n    top: 0;\\n  }\\n\\n  sub sub sub {\\n    bottom: 0;\\n  }\\n}\\n\\n.cooked-selection-barrier {\\n  height: 0;\\n  margin: 0;\\n  padding: 0;\\n  border: none;\\n  overflow: hidden;\\n  opacity: 0;\\n}\\n\\n// add staff color\\n.moderator {\\n  .regular > .cooked {\\n    background-colo