ap;\\n\\n    .btn,\\n    .ai-post-helper {\\n      border-radius: 0;\\n    }\\n\\n    @media screen and (width <= 420px) {\\n      flex-direction: column;\\n      align-items: flex-start;\\n\\n      .btn,\\n      .ai-post-helper {\\n        width: 100%;\\n        justify-content: flex-start;\\n      }\\n    }\\n  }\\n\\n  .extra {\\n    display: flex;\\n    flex-direction: column;\\n    width: 100%;\\n  }\\n\\n  .btn-flat {\\n    &:hover {\\n      .d-icon {\\n        color: var(--tertiary);\\n      }\\n    }\\n\\n    .d-button-label {\\n      white-space: nowrap;\\n    }\\n  }\\n}\\n\\n#fast-edit-input {\\n  resize: block;\\n}\\n\\n.post-avatar,\\n.topic-avatar,\\n.user-card-avatar {\\n  position: relative;\\n}\\n\\n.topic-avatar,\\n.avatar-flair-preview,\\n.user-card-avatar,\\n.user-profile-avatar,\\n.user-image,\\n.latest-topic-list-item {\\n  .avatar-flair {\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    background-repeat: no-repeat;\\n    background-position: center;\\n    position: absolute;\\n    bottom: 0;\\n    right: -6px;\\n  }\\n}\\n\\n.topic-avatar .avatar-flair,\\n.avatar-flair-preview .avatar-flair,\\n.collapsed-info .user-profile-avatar .avatar-flair,\\n.user-image .avatar-flair,\\n.latest-topic-list-item .avatar-flair {\\n  background-size: 20px 20px;\\n  width: 20px;\\n  height: 20px;\\n\\n  &.rounded {\\n    background-size: 18px 18px;\\n    border-radius: 12px;\\n    width: 24px;\\n    height: 24px;\\n    bottom: -2px;\\n    right: -8px;\\n  }\\n}\\n\\n.user-card-avatar .avatar-flair,\\n.user-profile-avatar .avatar-flair {\\n  background-size: 40px 40px;\\n  width: 40px;\\n  height: 40px;\\n\\n  &.rounded {\\n    background-size: 30px 30px;\\n    border-radius: 24px;\\n    width: 40px;\\n    height: 40px;\\n    bottom: -2px;\\n    right: -4px;\\n  }\\n\\n  .fa {\\n    font-size: var(--font-up-4);\\n  }\\n}\\n\\n.topic-body {\\n  @include viewport.from(sm) {\\n    width: calc(\\n      var(--topic-body-width) + 