play: flex;\\n      align-items: center;\\n\\n      .d-button-label {\\n        order: 0;\\n        padding-right: 0.25em;\\n        color: var(--primary-med-or-secondary-med);\\n      }\\n\\n      .d-icon {\\n        margin-right: 0;\\n        order: 1;\\n        color: var(--primary-med-or-secondary-med);\\n      }\\n\\n      .discourse-no-touch & {\\n        &:hover {\\n          .d-button-label {\\n            color: var(--primary-high);\\n          }\\n\\n          .d-icon {\\n            color: var(--primary-high);\\n          }\\n        }\\n      }\\n\\n      &:focus {\\n        @include default-focus;\\n        background: transparent;\\n      }\\n    }\\n  }\\n}\\n\\npre {\\n  // safety cap; also covers a `pre` with no `code` child\\n  max-height: 2000px;\\n\\n  .bidi-warning,\\n  .bidi-warning span {\\n    font-style: normal;\\n    background-color: var(--highlight);\\n    color: var(--danger);\\n    cursor: help;\\n  }\\n}\\n\\n.codeblock-buttons {\\n  display: block;\\n  position: relative;\\n  overflow: visible;\\n\\n  .codeblock-button-wrapper {\\n    position: absolute;\\n    display: flex;\\n  }\\n\\n  .copy-cmd,\\n  .fullscreen-cmd {\\n    @include unselectable;\\n    top: 0;\\n    min-height: 0;\\n    font-size: var(--font-down-2);\\n    opacity: 0.7;\\n    cursor: pointer;\\n\\n    &.action-complete {\\n      cursor: auto;\\n\\n      .d-icon {\\n        color: var(--tertiary);\\n      }\\n    }\\n\\n    .d-icon {\\n      pointer-events: none;\\n      margin-right: 0;\\n    }\\n  }\\n\\n  @include viewport.until(sm) {\\n    > code {\\n      padding-right: 2.75em;\\n    }\\n  }\\n\\n  @include viewport.from(sm) {\\n    .copy-cmd:not(.action-complete),\\n    .fullscreen-cmd:not(.action-complete) {\\n      opacity: 0;\\n      transition: 0.2s;\\n      visibility: hidden;\\n    }\\n\\n    &:hover {\\n      .copy-cmd,\\n      .fullscreen-cmd {\\n        opacity: 0.7;\\n        visibility: visible;\\n\\n        &:hover {\\n          opacity: 1;\\n        }\\n      }\\n    }\\n  }\\n}\\n\\nkbd {\\n  align-items: center;\\n  border: 1px solid var(--primary-low-mid);\\n  background: var(--primary-very-low);\\n  border-bottom-width: 2px;\\n  border-radius: 3px;\\n  box-sizing: border-box;\\n  display: inline-flex;\\n  gap: 0 0.5em; // space between text and images/emoji\\n  font-size: var(--font-down-1);\\n  justify-content: center;\\n  line-height: var(--line-height-large);\\n  margin: 0 0.15em;\\n  min-width: 24px;\\n  padding: 0.15em 0.6em;\\n\\n  // don't allow more than 3 nested elements to prevent FF from crashing\\n  // cf. http://what.thedailywtf.com/t/nested-elements/7927\\n  // 3 levels are needed to prevent highlighted words being hidden\\n  // cf. https://meta.discourse.org/t/word-disappears-when-searched-and-in-details-summary-kbd-b/25741\\n  * * * {\\n    display: none;\\n  }\\n}\\n\\n// we assume blockquotes have their own margins, so all blockquotes\\n// will remove margins from first (top) and last (bottom) child elements\\nblockquote,\\nblockquote .post__contents-cooked-quote {\\n  overflow-wrap: break-word;\\n\\n  > *:first-child {\\n    margin-top: 0 !important;\\n  }\\n\\n  > *:last-child {\\n    margin-bottom: 0 !important;\\n  }\\n\\n  table {\\n    table-layout: fixed; // prevents table from expanding past the post body width\\n    width: 100%;\\n  }\\n}\\n\\n.gap {\\n  box-sizing: border-box;\\n  color: var(--primary-med-or-secondary-high);\\n  cursor: pointer;\\n  text-transform: uppercase;\\n  font-weight: bold;\\n  font-size: var(--font-down-1);\\n  padding: 0.25em 0 0.5em\\n    calc(var(--topic-avatar-width) + var(--topic-body-width-padding));\\n\\n  @include viewport.until(sm) {\\n    padding: 0.25em 0;\\n  }\\n}\\n\\n.who-liked,\\n.who-read {\\n  transition: height 0.5s;\\n\\n  @include viewport.from(sm) {\\n    margin-bottom: 0;\\n    width: 100%;\\n    text-align: right;\\n\\n    &.--expanded {\\n      margin-top: var(--space-5);\\n    }\\n  }\\n\\n  a {\\n    margin: 0 0.25em 0.5em 0;\\n    display: inline-block;\\n  }\\n}\\n\\n.reviewable .post-body,\\n.cooked table,\\n.d-editor-preview table {\\n  thead {\\n    th {\\n      text-align: left;\\n      padding-bottom: 2px;\\n      font-weight: bold;\\n      color: var(--primary);\\n    }\\n  }\\n\\n  td {\\n    padding: 3px 3px 3px 0.5em;\\n  }\\n}\\n\\n.small-action {\\n  display: flex;\\n  align-items: center;\\n\\n  &.deleted {\\n    .topic-avatar,\\n    .small-action-desc {\\n      background-color: var(--danger-low-mid);\\n    }\\n  }\\n\\n  .topic-avatar,\\n  .small-action-desc {\\n    border-top: 1px solid var(--content-border-color);\\n  }\\n\\n  .topic-avatar {\\n    display: flex;\\n    align-self: stretch;\\n    flex: 0 0 auto;\\n    margin: 0;\\n    padding-top: var(--space-4);\\n    width: var(--topic-avatar-width);\\n    justify-content: center;\\n    height: auto;\\n\\n    .d-icon {\\n      font-size: var(--font-up-3);\\n      color: var(--primary-low-mid);\\n    }\\n  }\\n\\n  .small-action-desc {\\n    box-sizing: border-box;\\n    display: grid;\\n    grid-template-columns: 1fr auto;\\n    gap: 0 var(--space-2);\\n    color: var(--primary-700);\\n    padding: 0 0 var(--space-3) var(--topic-body-width-padding);\\n    width: calc(\\n      var(--topic-body-width) + (var(--topic-body-width-padding) * 2)\\n    );\\n    min-width: 0; // Allows container to shrink\\n  }\\n\\n  .small-action-contents {\\n    display: flex;\\n    gap: var(--space-1);\\n    align-items: start;\\n    padding-top: 1.15em;\\n\\n    [data-user-card] {\\n      margin-top: calc(var(--space-half) * -1);\\n    }\\n\\n    p {\\n      margin: 0;\\n    }\\n  }\\n\\n  .small-action-buttons {\\n    display: flex;\\n    padding-top: var(--space-3);\\n  }\\n\\n  .small-action-custom-message {\\n    grid-column: 1 / -1;\\n    flex: 1 1 100%;\\n    font-weight: normal;\\n    margin-top: var(--space-2);\\n    word-break: break-word;\\n    min-width: 0; // Allows content like oneboxes to shrink\\n    color: var(--primary);\