\\n  }\\n\\n  article.boxed {\\n    position: relative;\\n\\n    .select-posts {\\n      position: absolute;\\n      right: 7em;\\n      z-index: z(\\"dropdown\\");\\n      top: 0.5em;\\n      height: 100px;\\n\\n      button {\\n        margin-left: 8px;\\n        background-color: var(--primary-low);\\n        color: var(--primary);\\n        box-shadow: var(--shadow-dropdown);\\n      }\\n    }\\n  }\\n}\\n\\n.selected-posts {\\n  @include viewport.until(sm) {\\n    padding: 0.1em 0.7em;\\n  }\\n\\n  @include viewport.from(sm) {\\n    width: 200px;\\n    position: fixed;\\n    z-index: z(\\"dropdown\\") + 1; // 1 higher than .select-posts\\n    box-shadow: var(--shadow-card);\\n    padding: var(--space-3);\\n    margin-bottom: var(--space-1);\\n    right: 10px;\\n\\n    @include viewport.from(xl) {\\n      right: auto;\\n      margin-left: 330px;\\n      left: 50%;\\n    }\\n\\n    button {\\n      width: 100%;\\n      margin: 4px auto;\\n      display: inline-block;\\n      text-align: left;\\n    }\\n\\n    &.hidden {\\n      display: none;\\n    }\\n\\n    .controls {\\n      margin-top: 10px;\\n    }\\n\\n    p {\\n      font-size: var(--font-down-1);\\n      margin: 0 0 10px 0;\\n    }\\n\\n    p.cancel {\\n      margin: 10px 0 0 0;\\n    }\\n\\n    h3 {\\n      font-size: var(--font-up-4);\\n      color: var(--primary);\\n      margin-bottom: 5px;\\n\\n      .d-icon {\\n        margin-right: 7px;\\n      }\\n    }\\n  }\\n}\\n\\n@media all and (width <= 767px) {\\n  .reply-to-tab {\\n    span {\\n      display: none;\\n    }\\n  }\\n\\n  .user-title {\\n    float: left;\\n    clear: left;\\n  }\\n}\\n\\n.signup-cta {\\n  box-sizing: border-box;\\n  max-width: calc(var(--topic-body-width) + 4.5em);\\n  padding: 3em 5em 2em\\n    calc(var(--topic-avatar-width) + var(--topic-body-width-padding));\\n\\n  @include viewport.until(sm) {\\n    padding: 1.5em 1.5em 0.25em;\\n  }\\n\\n  h3 {\\n    margin-bottom: 0.5em;\\n  }\\n\\n  a {\\n    text-decoration: underline;\\n  }\\n\\n  .buttons {\\n    display: flex;\\n    flex-wrap: wrap;\\n    align-items: center;\\n    margin: 1.5em 0 1em;\\n\\n    > * {\\n      margin-bottom: 0.5em;\\n    }\\n\\n    .btn {\\n      margin-right: 0.5em;\\n      white-space: nowrap;\\n\\n      .d-icon {\\n        color: inherit;\\n      }\\n\\n      &.btn-remind {\\n        background: var(--primary-very-low);\\n        margin-right: auto;\\n\\n        @include hover {\\n          background: var(--primary-medium);\\n        }\\n      }\\n\\n      @include viewport.until(sm) {\\n        &.btn-primary {\\n          margin-right: 100%;\\n        }\\n      }\\n    }\\n  }\\n}\\n\\n.post-notice {\\n  align-items: center;\\n  background-color: var(--tertiary-very-low);\\n  border-top: 1px solid var(--content-border-color);\\n  display: flex;\\n  width: 100%;\\n  max-width: calc(\\n    var(--topic-body-width) + (var(--topic-body-width-padding) * 2) +\\n      var(--topic-avatar-width)\\n  );\\n  padding: var(--space-2) var(--space-4);\\n  font-size: var(--font-down-1-rem);\\n  gap: var(--space-2);\\n  box-sizing: border-box;\\n\\n  @include viewport.until(sm) {\\n    margin-bottom: var(--space-4);\\n  }\\n\\n  &.custom {\\n    background: var(--danger-low);\\n  }\\n\\n  .emoji {\\n    width: 1.5em;\\n    height: 1.5em;\\n  }\\n\\n  .d-icon {\\n    width: 1.25em;\\n    height: 1.25em;\\n    color: var(--primary-high);\\n  }\\n\\n  .post-notice-message {\\n    flex: 1;\\n    min-width: 0;\\n\\n    img:not(.emoji) {\\n      max-width: 100%;\\n      height: auto;\\n      display: inline-block;\\n    }\\n  }\\n\\n  p {\\n    display: inline;\\n    margin: 0;\\n  }\\n\\n  .custom_created_by {\\n    display: inline-block;\\n  }\\n}\\n\\niframe {\\n  max-width: 100%;\\n  max-height: #{\\"min(1000px, 200vh)\\"};\\n}\\n\\n.post-admin-menu {\\n  display: inline-flex;\\n  flex-direction: column;\\n  box-sizing: border-box;\\n  width: auto;\\n  max-width: 320px;\\n  position: absolute;\\n  text-align: left;\\n  botto