n-right: 1em;\\n  }\\n\\n  .user-profile-location,\\n  .user-profile-website {\\n    @include ellipsis;\\n  }\\n\\n  @include viewport.until(md) {\\n    justify-content: center;\\n  }\\n}\\n\\n.selectable-avatars {\\n  max-height: 350px;\\n  margin-bottom: 1em;\\n  text-align: justify;\\n  overflow-y: auto;\\n\\n  .selectable-avatar {\\n    margin: 5px;\\n    display: inline-block;\\n    position: relative;\\n\\n    .avatar {\\n      cursor: pointer;\\n      width: 60px;\\n      height: 60px;\\n    }\\n\\n    &:hover {\\n      .selectable-avatar__remove {\\n        visibility: visible;\\n      }\\n    }\\n\\n    &__remove {\\n      visibility: hidden;\\n      color: var(--primary-high);\\n      position: absolute;\\n      bottom: 0;\\n      width: 100%;\\n      left: 0;\\n      text-align: center;\\n      font-size: var(--font-up-2);\\n    }\\n  }\\n}\\n\\n.timezone-input {\\n  margin-bottom: 0.5em;\\n}\\n\\n.user-invites-page {\\n  .invite-error {\\n    grid-column: 1 / span 2;\\n  }\\n\\n  .d-table.user-invite-list {\\n    margin-top: var(--space-4);\\n\\n    .invite-link-target {\\n      display: none;\\n    }\\n\\n    .d-table__cell {\\n      &.--overview {\\n        .d-icon {\\n          color: var(--primary-medium);\\n          font-size: var(--font-down-1);\\n          margin-right: var(--space-1);\\n        }\\n      }\\n\\n      &.--controls {\\n        width: 10%;\\n      }\\n\\n      &.invite-updated-at {\\n        width: 18%;\\n\\n        @include viewport.until(md) {\\n          width: auto;\\n        }\\n      }\\n\\n      &.invite-expires-at {\\n        width: 20%;\\n\\n        @include viewport.until(md) {\\n          width: auto;\\n        }\\n      }\\n\\n      .invite-shortkey {\\n        @include viewport.until(md) {\\n          max-width: 70%;\\n        }\\n      }\\n\\n      .invite-description {\\n        color: var(--primary-high);\\n        margin-top: var(--space-1);\\n      }\\n\\n      .invite-details {\\n        margin-left: var(--space-5);\\n      }\\n\\n      .invite-groups {\\n        display: flex;\\n        flex-wrap: wrap;\\n        gap: var(--space-2);\\n        row-gap: 0;\\n        margin-top: var(--space-2);\\n      }\\n\\n      .invite-topic {\\n        margin-top: var(--space-2);\\n      }\\n\\n      .invite-extra {\\n        font-size: var(--font-down-1);\\n\\n        a {\\n          color: var(--primary-very-high);\\n        }\\n      }\\n\\n      .invite-extra-item-link {\\n        display: inline-flex;\\n        align-items: center;\\n        color: var(--primary-high);\\n      }\\n    }\\n  }\\n}\\n\\n.user-additional-controls {\\n  display: flex;\\n  gap: var(--space-2);\\n  flex-wrap: wrap;\\n}\\n\\n.user-invite-buttons {\\n  display: flex;\\n  flex-wrap: wrap;\\n  gap: 0.5em;\\n}\\n\\n.notification-schedule {\\n  .instruction {\\n    margin-top: 12px;\\n    margin-bottom: 10px;\\n  }\\n\\n  .notification-schedule-table {\\n    .notification-schedule-tbody {\\n      border-top-width: 1px;\\n\\n      .day {\\n        .day-label {\\n          padding: 1em 1em 1em 0;\\n        }\\n\\n        .to {\\n          padding: 0 0.5em;\\n        }\\n      }\\n    }\\n  }\\n}\\n\\n// Due to special login animations, the order here needs to be changed\\n.control-group[data-setting-name=\\"user-user-fields\\"] {\\n  .user-field.text,\\n  .user-field.textarea,\\n  .user-field.date {\\n    .controls {\\n      display: flex;\\n      flex-direction: column;\\n\\n      .control-label.alt-placeholder {\\n        order: 1;\\n      }\\n\\n      .ember-text-field,\\n      .ember-text-area {\\n        order: 2;\\n      }\\n\\n      .tip {\\n        order: 3;\\n      }\\n\\n      .instructions {\\n        order: 4;\\n      }\\n    }\\n  }\\n}\\n\\n.user-profile-hidden {\\n  font-size: var(--font-up-2);\\n  text-align: center;\\n}\\n\\n.pref-avatar {\\n  .avatar {\\n    max-width: 90px;\\n    max-height: 90px;\\n  }\\n}\\n\\n.user-invite-search {\\n  min-width: 0;\\n  margin-right: auto;\\n\\n  input {\\n 