line-flex;\\n  align-items: center;\\n  background-color: var(--secondary);\\n\\n  img {\\n    height: 16px;\\n    width: 16px;\\n  }\\n\\n  .badge-display-name {\\n    margin-left: 0.25em;\\n  }\\n\\n  &.badge-type-gold .fa {\\n    color: var(--gold) !important;\\n  }\\n\\n  &.badge-type-silver .fa {\\n    color: var(--silver) !important;\\n  }\\n\\n  &.badge-type-bronze .fa {\\n    color: var(--bronze) !important;\\n  }\\n\\n  &.disabled {\\n    color: var(--primary-medium);\\n    background-color: var(--primary-very-low);\\n\\n    .fa {\\n      opacity: 0.4;\\n    }\\n  }\\n}\\n\\n@media all and (width <= 750px) {\\n  .show-badge .user-badge-with-posts .badge-user a.post-link {\\n    width: auto;\\n  }\\n\\n  .show-badge div.badge-user {\\n    padding: 0;\\n  }\\n\\n  .badges-listing {\\n    display: block;\\n\\n    .info,\\n    .grant-count {\\n      text-align: left;\\n    }\\n\\n    .row > div.info {\\n      display: none;\\n    }\\n\\n    .row {\\n      display: block;\\n\\n      > div {\\n        display: block;\\n        margin-top: 10px;\\n      }\\n    }\\n  }\\n}\\n\\n.show-badge .badge-user-info {\\n  .earned {\\n    font-size: var(--font-up-2);\\n    margin-bottom: 1em;\\n  }\\n}\\n\\n.show-badge .single-user {\\n  margin-left: 2%;\\n  padding-bottom: 20px;\\n\\n  .load-more {\\n    padding-top: 30px;\\n    display: block;\\n    font-size: var(--font-up-2);\\n  }\\n}\\n\\n.show-badge .single-user .badge-user {\\n  padding-left: 0;\\n  text-align: left;\\n  display: block;\\n  margin: 20px 0;\\n  width: 800px;\\n\\n  .badge-info {\\n    display: none;\\n  }\\n\\n  .date {\\n    display: inline-block;\\n    font-size: var(--font-up-1);\\n    margin-left: 10px;\\n  }\\n\\n  .post-link {\\n    font-size: var(--font-up-2);\\n    width: 500px;\\n    margin: 0;\\n    padding: 0;\\n  }\\n\\n  &::after {\\n    content: \\"\\";\\n    clear: both;\\n    display: table;\\n  }\\n}\\n\\n.long-description.banner {\\n  width: 88%;\\n  margin-bottom: 15px;\\n  margin-top: 15px;\\n}\\n\\n.badge-card {\\n  background-color: var(--d-badge-card-background-color);\\n  border: 1px solid var(--content-border-color);\\n  position: relative;\\n  border-radius: var(--d-border-radius);\\n\\n  .check-display {\\n    position: absolute;\\n    right: 5px;\\n    top: 5px;\\n  }\\n\\n  .badge-granted {\\n    display: block;\\n    margin-top: 0.5em;\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1);\\n  }\\n\\n  .grant-count {\\n    font-weight: bold;\\n    color: var(--primary-medium);\\n    line-height: 1;\\n  }\\n\\n  .grant-text {\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1);\\n  }\\n\\n  .favorite-btn {\\n    position: absolute;\\n    right: 0;\\n    bottom: 0;\\n    z-index: 1;\\n    border-radius: var(--d-button-border-radius) 0 var(--d-button-border-radius)\\n      0;\\n  }\\n\\n  .badge-contents {\\n    display: flex;\\n    align-items: flex-start;\\n    gap: 1rem;\\n    padding: 1.5em 1.5em;\\n\\n    .badge-link {\\n      color: var(--primary);\\n      display: inline-block;\\n      line-height: var(--line-height-medium);\\n\\n      &::after {\\n        content: \\"\\";\\n        position: absolute;\\n        left: 0;\\n        right: 0;\\n        top: 0;\\n        bottom: 0;\\n      }\\n    }\\n\\n    .badge-summary {\\n      overflow-wrap: break-word;\\n\\n      &:has(a) {\\n        // for summary links to be reachable\\n        // they must be positioned above .badge-link:after\\n        position: relative;\\n        z-index: 1;\\n      }\\n    }\\n\\n    .badge-icon {\\n      --badge-icon-size: 3.5em;\\n      display: flex;\\n      flex-shrink: 0;\\n      align-items: center;\\n      justify-content: center;\\n\\n      svg {\\n        font-size: var(--badge-icon-size);\\n      }\\n\\n      img {\\n        width: var(--badge-icon-size);\\n        height: var(--badge-icon-size);\\n        object-fit: contain;\\n      }\\n\\n      &.badge-type-gold .fa {\\n        color: rgb(231, 195, 0) !important;\\n      }\\n\\n      &.badge-type-silver .fa {\\n        color: #c0c0c0 !important;\\n      }\\n\\n      &.badge-type-bronze .fa {\\n        color: #cd7f32 !important;\\n      }\\n    }\\n\\n    .badge-info {\\n      min-width: 0;\\n      color: var(--primary);\\n\\n      h3 {\\n        margin-bottom: 0.25em;\\n        font-size: var(--font-up-1);\\n\\n        @media screen and (width >= 900px) {\\n          font-size: var(--font-up-2);\\n        }\\n      }\\n    }\\n  }\\n\\n  &.--badge-large {\\n    width: 100%;\\n    align-self: flex-start;\\n\\n    @media screen and (width >= 767px) {\\n      max-width: calc(var(--d-max-width) / 2);\\n    }\\n\\n    .badge-contents {\\n      h3 {\\n        font-size: var(--font-up-3);\\n      }\\n    }\\n  }\\n\\n  &.--can-favorite {\\n    // helps description text avoid favorite button overlap\\n    .badge-summary {\\n      width: 100%;\\n      padding-right: var(--space-6);\\n      box-sizing: border-box;\\n    }\\n  }\\n}\\n\\n.badges-granted {\\n  display: grid;\\n  grid-template-columns: repeat(auto-fit, minmax(18em, 1fr));\\n  gap: 3em 2em;\\n}\\n\\n.container.badges {\\n  background: var(--d-content-background);\\n}\\n\\n.badge-groups {\\n  margin: 20px 0;\\n  color: var(--primary-med-or-secondary-med);\\n\\n  h3 {\\n    margin-bottom: 1em;\\n  }\\n}\\n\\n.badge-title {\\n  .user-content {\\n    padding: 0;\\n  }\\n}\\n\\n.badge-group-list {\\n  display: grid;\\n  grid-template-columns: repeat(auto-fit, minmax(18em, 1fr));\\n  gap: 1em;\\n  width: 100%;\\n  margin-bottom: 1.5em;\\n\\n  .title {\\n    font-size: var(--font-up-1);\\n  }\\n}\\n\\n.show-badge-details {\\n  display: flex;\\n  flex-wrap: wrap;\\n  flex-direction: row;\\n  margin-bottom: 2em;\\n  margin-top: 1em;\\n  gap: 1em;\\n\\n  .badge-grant-info {\\n    &.hidden {\\n      display: none;\\n    }\\n  }\\n\\n  .grant-info-item {\\n    margin-bottom: 1em;\\n    color: var(--primary-med-or-secondary-med);\\n\\n    &:first-of-type {\\n      margin-right: 10px;\\n    }\\n  }\\n\\n  .badge-set-title {\\n    flex: 0 1 auto;\\n    padding: 1.5em;\\n    border: 1px solid var(--content-border-color);\\n\\n    .badge-title {\\n      height: 100%;\\n\\n      &__saved {\\n        color: var(--success);\\n      }\\n    }\\n\\n    .control-group:last-child {\\n      margin: auto 0 0;\\n    }\\n\\n    .form-horizontal {\\n      display: flex;\\n      flex-direction: column;\\n      height: 100%;\\n      margin: 0;\\n    }\\n\\n    .controls {\\n      display: flex;\\n      flex-wrap: wrap;\\n      align-items: baseline;\\n      gap: 0.5em;\\n      margin: 0;\\n\\n      button:last-of-type {\\n        margin-right: auto;\\n      }\\n    }\\n\\n    .combobox {\\n      width: 100%;\\n    }\\n  }\\n}\\n\\n.check-display {\\n  display: flex;\\n  width: 1.5em;\\n  height: 1.5em;\\n  border-radius: 100%;\\n  align-items: center;\\n  justify-content: center;\\n\\n  .d-icon {\\n    font-size: var(--font-down-2);\\n    color: var(--secondary);\\n  }\\n}\\n\\n.check-display.status-checked {\\n  background-color: var(--success);\\n}\\n\\n.check-display.status-unchecked {\\n  background-color: var(--danger);\\n}\\n\\n.hyperlink {\\n  cursor: pointer;\\n}\\n","[data-content][data-identifier=\\"user-tip\\"] {\\n  min-width: 300px;\\n  background-color: var(--tertiary);\\n  border: none;\\n  color: var(--secondary);\\n\\n  --float-kit-arrow-stroke-color: var(--tertiary);\\n  --float-kit-arrow-fill-color: var(--tertiary);\\n\\n  .user-tip__container {\\n    font-weight: normal;\\n    padding: 0.5em;\\n    text-align: left;\\n  }\\n\\n  .user-tip__title {\\n    font-size: var(--font-up-2);\\n    font-weight: bold;\\n  }\\n\\n  .user-tip__content {\\n    margin-top: 0.25em;\\n\\n    a {\\n      color: var(--secondary);\\n      text-decoration: underline;\\n    }\\n  }\\n\\n  .user-tip__buttons {\\n    margin-top: 1em;\\n    display: flex;\\n    justify-content: space-between;\\n  }\\n\\n  .btn-primary {\\n    background: var(--secondary);\\n    color: var(--tertiary);\\n  }\\n\\n  .btn-flat.btn-text {\\n    background-color: transparent;\\n    color: var(--secondary);\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n// Styles for the full Ember app when rendered in embed mode (iframe)\\n// Activated when ?embed_mode=true is in the URL\\nbody.embed-mode {\\n  // Remove top padding since header is hidden\\n  #main-outlet {\\n    padding-top: 0;\\n  }\\n\\n  #main-outlet-wrapper {\\n    grid-template-columns: 1fr;\\n    gap: 0;\\n    padding: 0;\\n  }\\n\\n  // Hide elements that don't make sense in embed context\\n  .signup-cta,\\n  .suggested-topics,\\n  .more-topics__container,\\n  #topic-title,\\n  .nested-view__header,\\n  .nested-view__topic-map,\\n  .topic-above-footer-buttons-outlet.presence,\\n  .above-main-container-outlet,\\n  .topic-footer-main-buttons__actions .toggle-admin-menu,\\n  .topic-footer-main-buttons__actions .bookmark,\\n  .topic-footer-main-buttons__actions .flag-topic,\\n  .topic-footer-main-buttons__actions .assign,\\n  .topic-notifications-button,\\n  nav.post-controls .actions .show-more-actions,\\n  .software-update-prompt,\\n  .time-gap,\\n  .post-stream .gap,\\n  .container.posts:not(:has(.post-stream .topic-post ~ .topic-post))\\n    ~ #topic-footer-buttons,\\n  .topic-post .post-notice.new-user {\\n    display: none !important;\\n  }\\n\\n  // Ensure content fills the width\\n  #main-outlet-wrapper {\\n    max-width: 100%;\\n  }\\n\\n  // Hide the standard composer in embed mode — the docked composer replaces it.\\n  // Allow it to show when editing a post (composer-action-edit class).\\n  #reply-control:not(.composer-action-edit) {\\n    display: none !important;\\n  }\\n\\n  .embed-topic-footer {\\n    margin-top: 1.5em;\\n    text-align: center;\\n\\n    &__first-reply {\\n      display: flex;\\n      flex-direction: column;\\n      align-items: center;\\n      gap: 0.5em;\\n      padding: 2em 1em;\\n      color: var(--primary-medium);\\n      font-size: var(--font-up-1);\\n\\n      .d-icon {\\n        font-size: var(--font-up-4);\\n      }\\n    }\\n\\n    &__powered-by {\\n      display: flex;\\n      justify-content: center;\\n      padding: 1em 0;\\n    }\\n\\n    .powered-by-discourse {\\n      grid-area: unset;\\n      justify-self: unset;\\n    }\\n  }\\n\\n  .topic-timer-info,\\n  .post-stream .topic-post:nth-child(2) article .topic-body,\\n  .post-stream .topic-post:nth-child(2) article .topic-avatar {\\n    border-top: none;\\n  }\\n\\n  .topic-area .posts-wrapper:has(.post-stream .topic-post + .topic-post) {\\n    border-bottom: 1px solid var(--content-border-color);\\n  }\\n\\n  // Single-column grid for embed mode (no timeline sidebar)\\n  .container.posts {\\n    grid-template-areas: \\"posts\\";\\n    grid-template-columns: auto;\\n  }\\n\\n  // Position the topic-navigation in the grid so progress bar appears after posts\\n  .container.posts .topic-navigation {\\n    grid-area: posts;\\n    grid-row: 3;\\n    display: flex;\\n    justify-content: flex-end;\\n\\n    // Don't use sticky positioning — floating buttons handle the scrolling UX\\n    &.with-topic-progress {\\n      position: static;\\n    }\\n  }\\n\\n  // prevent horizontal overflow\\n  .topic-meta-data {\\n    @include viewport.until(sm) {\\n      .post-infos {\\n        position: relative;\\n        overflow: hidden;\\n        padding-right: 6px;\\n      }\\n\\n      .read-state {\\n        right: 1px;\\n\\n        svg {\\n          right: 0;\\n        }\\n      }\\n    }\\n  }\\n\\n  // Hide the docked timeline sidebar (fullscreen timeline still works)\\n  .timeline-container:not(.timeline-fullscreen) {\\n    display: none !important;\\n  }\\n\\n  // Hide admin menu in the progress bar for embed context\\n  #topic-progress-wrapper .topic-admin-menu-trigger,\\n  #topic-progress-wrapper .topic-content-language-preferences {\\n    display: none;\\n  }\\n\\n  // Floating timeline button in the bottom-right\\n  .embed-floating-buttons {\\n    position: fixed;\\n    bottom: calc(env(safe-area-inset-bottom) + 1em);\\n    right: var(--space-4);\\n    z-index: z(\\"timeline\\");\\n\\n    .embed-floating-timeline-button {\\n      width: 2.75em;\\n      height: 2.75em;\\n      border-radius: 50%;\\n      padding: 0;\\n      display: flex;\\n      align-items: center;\\n      justify-content: center;\\n      box-shadow: var(--shadow-dropdown);\\n\\n      .d-button-label {\\n        display: none;\\n      }\\n\\n      .d-icon {\\n        margin: 0;\\n      }\\n    }\\n  }\\n\\n  // Hide OP\\n  // Use visibility hidden to prevent issues with jumpy behavior\\n  .post-stream .topic-post.topic-owner:first-child,\\n  .nested-view__op {\\n    opacity: 0;\\n    height: 0;\\n    visibility: hidden;\\n    position: absolute;\\n    pointer-events: none;\\n  }\\n\\n  // Drop the nested-view's outer framing so it sits flush in the iframe\\n  .nested-view {\\n    padding: 0;\\n    background: transparent;\\n    border-radius: 0;\\n  }\\n\\n  .embed-mode-composer {\\n    position: sticky;\\n    bottom: 0;\\n    z-index: z(\\"composer\\", \\"content\\");\\n    background: var(--secondary);\\n    padding-inline: 0.5em;\\n\\n    &::before {\\n      content: \\"\\";\\n      position: absolute;\\n      left: 0;\\n      right: 0;\\n      top: -2.5em;\\n      height: 2.5em;\\n      background: linear-gradient(to bottom, transparent, var(--secondary));\\n      pointer-events: none;\\n    }\\n\\n    .docked-composer {\\n      --docked-composer-input-min-height: 10em;\\n      margin-top: 0;\\n\\n      &::before {\\n        display: none;\\n      }\\n    }\\n\\n    .embed-floating-buttons {\\n      position: absolute;\\n      bottom: 100%;\\n      right: var(--space-4);\\n      z-index: z(\\"timeline\\");\\n      padding-bottom: 0.5em;\\n    }\\n\\n    &__replying-to {\\n      display: flex;\\n      align-items: center;\\n      justify-content: space-between;\\n      padding: 0.35em 0.75em;\\n      font-size: var(--font-down-1);\\n      color: var(--primary-medium);\\n      border-top: 1px solid var(--primary-low);\\n    }\\n\\n    &__replying-to-text {\\n      display: flex;\\n      align-items: center;\\n      gap: 0.35em;\\n    }\\n\\n    &__replying-to-dismiss {\\n      padding: 0.25em;\\n    }\\n\\n    &__editing {\\n      display: flex;\\n      align-items: center;\\n      justify-content: space-between;\\n      padding: 0.35em 0.75em;\\n      font-size: var(--font-down-1);\\n      color: var(--primary-medium);\\n      border-top: 1px solid var(--primary-low);\\n    }\\n\\n    &__editing-text {\\n      display: flex;\\n      align-items: center;\\n      gap: 0.35em;\\n    }\\n\\n    &__editing-dismiss {\\n      padding: 0.25em;\\n    }\\n  }\\n}\\n\\n.embed-auth-flow-modal {\\n  &__waiting {\\n    display: flex;\\n    flex-direction: column;\\n    align-items: center;\\n    gap: 1em;\\n    padding: 1em 0;\\n    text-align: center;\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.admin-mcp {\\n  &__overview-grid {\\n    display: grid;\\n    grid-template-columns: repeat(auto-fit, minmax(min(100%, 20rem), 1fr));\\n    gap: var(--space-4);\\n  }\\n\\n  &__endpoint {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-2);\\n    margin-bottom: var(--space-4);\\n\\n    code {\\n      overflow-wrap: anywhere;\\n    }\\n  }\\n\\n  &__summary-list,\\n  &__detail-list {\\n    display: grid;\\n    gap: var(--space-2);\\n    margin: 0;\\n\\n    div {\\n      display: flex;\\n      justify-content: space-between;\\n      gap: var(--space-4);\\n    }\\n\\n    dt {\\n      color: var(--primary-medium);\\n    }\\n\\n    dd {\\n      margin: 0;\\n      text-align: end;\\n    }\\n  }\\n\\n  &__metric-grid {\\n    display: grid;\\n    grid-template-columns: repeat(auto-fit, minmax(8rem, 1fr));\\n    gap: var(--space-4);\\n    margin: 0;\\n\\n    dt {\\n      color: var(--primary-medium);\\n      font-size: var(--font-down-1);\\n    }\\n\\n    dd {\\n      margin: 0.25rem 0 0;\\n      font-size: var(--font-up-2);\\n      font-weight: bold;\\n    }\\n  }\\n\\n  &__checklist {\\n    display: grid;\\n    gap: var(--space-2);\\n    margin: 0;\\n    padding-inline-start: 0;\\n    list-style: none;\\n\\n    li {\\n      display: flex;\\n      align-items: center;\\n      gap: var(--space-2);\\n    }\\n\\n    .is-complete {\\n      color: var(--success);\\n    }\\n  }\\n\\n  &__warnings {\\n    margin-top: var(--space-4);\\n    padding: var(--space-4);\\n    border: 1px solid var(--danger);\\n    background: var(--danger-low);\\n\\n    h2 {\\n      margin-top: 0;\\n      font-size: var(--font-up-1);\\n    }\\n  }\\n\\n  &__scope-select {\\n    width: min(100%, 50rem);\\n\\n    .d-multi-select-trigger__selection-label {\\n      max-width: none;\\n    }\\n  }\\n\\n  &__scope-select-content {\\n    width: min(22rem, calc(100vw - 2rem));\\n  }\\n\\n  &__scope-option {\\n    display: flex;\\n    flex-direction: column;\\n\\n    small {\\n      color: var(--primary-medium);\\n    }\\n  }\\n\\n  &__access-table {\\n    width: 100%;\\n    margin-bottom: var(--space-4);\\n\\n    .--overview {\\n      width: 30%;\\n    }\\n\\n    .--controls {\\n      width: 1%;\\n      white-space: nowrap;\\n    }\\n\\n    .d-table__overview-name {\\n      display: block;\\n    }\\n\\n    small {\\n      color: var(--primary-medium);\\n    }\\n  }\\n\\n  &__access-scopes {\\n    display: flex;\\n    flex-wrap: wrap;\\n    gap: var(--space-1);\\n    margin: 0;\\n    padding: 0;\\n    list-style: none;\\n  }\\n\\n  &__access-form {\\n    max-width: 50rem;\\n    padding-top: var(--space-4);\\n    border-top: 1px solid var(--primary-low);\\n  }\\n\\n  &__access-form-actions {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-2);\\n  }\\n\\n  &__primitive-filters {\\n    display: grid;\\n    grid-template-columns: repeat(auto-fit, minmax(min(100%, 12rem), 1fr));\\n    gap: var(--space-2);\\n    margin-bottom: var(--space-4);\\n\\n    .form-kit__field {\\n      min-width: 0;\\n      margin: 0;\\n    }\\n\\n    .form-kit__control-select {\\n      width: 100%;\\n    }\\n  }\\n\\n  &__activity-filters {\\n    display: flex;\\n    flex-flow: row wrap;\\n    align-items: end;\\n    gap: var(--space-2);\\n    margin-bottom: var(--space-2);\\n\\n    .form-kit__field {\\n      flex: 0 1 auto;\\n      margin: 0;\\n    }\\n\\n    .admin-mcp__filter-search {\\n      flex: 1 1 24rem;\\n      min-width: 0;\\n    }\\n\\n    .form-kit__field-select {\\n      flex: 0 1 10rem;\\n      min-width: 0;\\n    }\\n\\n    .form-kit__control-input,\\n    .form-kit__control-select {\\n      width: 100%;\\n    }\\n  }\\n\\n  &__uri-list {\\n    display: grid;\\n    gap: var(--space-1);\\n    margin: 0;\\n    padding: 0;\\n    list-style: none;\\n\\n    code {\\n      overflow-wrap: anywhere;\\n    }\\n  }\\n\\n  &__results-count {\\n    margin: var(--space-1) 0 0;\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1);\\n  }\\n\\n  &__primitive-selection-form {\\n    --mcp-primitive-actions-offset: var(--space-3);\\n\\n    &.has-floating-actions {\\n      padding-block-end: calc(\\n        var(--mcp-primitive-actions-height, 4em) +\\n          var(--mcp-primitive-actions-offset) + var(--space-4)\\n      );\\n    }\\n\\n    .footer-nav-visible & {\\n      --mcp-primitive-actions-offset: calc(\\n        var(--footer-nav-height) + env(safe-area-inset-bottom) + var(--space-4)\\n      );\\n    }\\n\\n    .form-kit__actions.is-floating {\\n      box-sizing: border-box;\\n      position: fixed;\\n      inset-block-end: var(--mcp-primitive-actions-offset);\\n      z-index: z(\\"base\\");\\n      flex-wrap: wrap;\\n      padding: var(--space-3);\\n      border: 1px solid var(--primary-300);\\n      border-radius: var(--d-border-radius);\\n      background-color: var(--secondary);\\n      box-shadow: var(--shadow-card);\\n    }\\n  }\\n\\n  &__primitive-browser {\\n    display: grid;\\n    width: 100%;\\n    gap: var(--space-4);\\n    margin-bottom: var(--space-4);\\n\\n    @include viewport.from(md) {\\n      grid-template-columns: minmax(12rem, 16rem) minmax(0, 1fr);\\n      align-items: start;\\n    }\\n  }\\n\\n  &__primitive-groups {\\n    padding: var(--space-1);\\n    border: 1px solid var(--token-color-border-default);\\n    border-radius: var(--d-border-radius);\\n  }\\n\\n  &__primitive-group-list {\\n    display: grid;\\n    grid-template-columns: repeat(auto-fit, minmax(min(100%, 10rem), 1fr));\\n    gap: var(--space-1);\\n    margin: 0;\\n    padding: 0;\\n    list-style: none;\\n\\n    @include viewport.from(md) {\\n      grid-template-columns: minmax(0, 1fr);\\n    }\\n  }\\n\\n  &__primitive-group {\\n    box-sizing: border-box;\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-1);\\n    width: 100%;\\n    min-width: 0;\\n    padding: var(--space-2);\\n    border: 0;\\n    border-radius: var(--d-border-radius);\\n    background: transparent;\\n    color: var(--token-color-text-default);\\n    text-align: start;\\n    overflow-wrap: anywhere;\\n    cursor: pointer;\\n\\n    small {\\n      color: var(--token-color-text-subtle);\\n      font-weight: normal;\\n    }\\n\\n    &.is-selected {\\n      background: var(--token-color-surface-selected);\\n      font-weight: var(--token-font-weight-semibold);\\n    }\\n\\n    &:focus-visible {\\n      outline: 2px solid var(--token-color-border-focused);\\n      outline-offset: -2px;\\n    }\\n  }\\n\\n  &__primitive-panel {\\n    min-width: 0;\\n  }\\n\\n  &__primitive-panel-header {\\n    padding-block: var(--space-3);\\n\\n    h3 {\\n      margin: 0;\\n      font-size: var(--font-up-1);\\n    }\\n  }\\n\\n  &__primitive-group-actions {\\n    display: flex;\\n    flex-wrap: wrap;\\n    gap: var(--space-2);\\n    margin-top: var(--space-3);\\n\\n    @include viewport.until(sm) {\\n      .btn {\\n        flex: 1 1 auto;\\n      }\\n    }\\n  }\\n\\n  &__primitive-list {\\n    display: grid;\\n    width: 100%;\\n    gap: var(--space-2);\\n    margin-top: var(--space-4);\\n    margin-bottom: var(--space-4);\\n  }\\n\\n  &__primitive {\\n    position: relative;\\n    padding: var(--space-3);\\n    padding-inline-end: calc(var(--space-3) + 2.5rem);\\n    border: 1px solid var(--content-border-color);\\n    border-radius: var(--d-border-radius);\\n\\n    .form-kit__container-content,\\n    .form-kit__control-checkbox-label {\\n      width: 100%;\\n      max-width: none;\\n    }\\n\\n    .form-kit__control-checkbox-content {\\n      flex: 1 1 auto;\\n      min-width: 0;\\n    }\\n  }\\n\\n  &__primitive-meta {\\n    display: flex;\\n    flex-wrap: wrap;\\n    gap: var(--space-2) var(--space-4);\\n    margin-block: var(--space-2) 0;\\n    margin-inline: 2rem 0;\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1);\\n\\n    div {\\n      display: flex;\\n      gap: 0.25rem;\\n    }\\n\\n    dt::after {\\n      content: \\":\\";\\n    }\\n\\n    dd {\\n      margin: 0;\\n    }\\n  }\\n\\n  &__primitive-actions {\\n    position: absolute;\\n    inset-block-start: var(--space-2);\\n    inset-inline-end: var(--space-2);\\n  }\\n\\n  &__status {\\n    display: inline-block;\\n    padding: 0.15em 0.55em;\\n    border-radius: 1em;\\n    background: var(--primary-low);\\n    color: var(--primary-high);\\n    font-size: var(--font-down-1);\\n    font-weight: 600;\\n    white-space: nowrap;\\n\\n    &[data-state=\\"approved\\"],\\n    &[data-state=\\"active\\"],\\n    &[data-state=\\"success\\"] {\\n      background: var(--success-low);\\n      color: var(--success);\\n    }\\n\\n    &[data-state=\\"pending\\"],\\n    &[data-state=\\"server_disabled\\"],\\n    &[data-state=\\"client_not_approved\\"],\\n    &[data-state=\\"consent_required\\"],\\n    &[data-state=\\"rate_limited\\"] {\\n      background: var(--tertiary-low);\\n      color: var(--tertiary-high);\\n    }\\n\\n    &[data-state=\\"blocked\\"],\\n    &[data-state=\\"client_blocked\\"],\\n    &[data-state=\\"access_removed\\"],\\n    &[data-state=\\