      }\\n\\n      .timeline-date-wrapper {\\n        text-align: right;\\n\\n        @include ellipsis;\\n      }\\n\\n      .post-excerpt {\\n        max-width: 650px;\\n        line-height: var(--line-height-large);\\n        display: block;\\n\\n        @include line-clamp(8);\\n\\n        @media screen and (height <= 425px) {\\n          @include line-clamp(5);\\n        }\\n      }\\n\\n      .username {\\n        color: var(--primary-high-or-secondary-low);\\n        overflow-wrap: break-word;\\n        font-weight: bold;\\n      }\\n\\n      .title {\\n        margin-top: 0;\\n        padding-left: 1em;\\n        display: table-cell;\\n        vertical-align: top;\\n        width: 100%;\\n\\n        h2 {\\n          margin-top: 0;\\n          display: block;\\n          line-height: var(--line-height-medium);\\n          font-size: var(--font-up-2);\\n\\n          @include line-clamp(4);\\n        }\\n\\n        a {\\n          color: var(--primary);\\n        }\\n      }\\n\\n      .timeline-last-read {\\n        right: 0;\\n        margin-left: 0;\\n\\n        .progress {\\n          display: none;\\n        }\\n      }\\n\\n      .timeline-footer-controls {\\n        display: none;\\n        position: absolute;\\n        bottom: 20px;\\n        left: 10px;\\n\\n        .topic-admin-menu {\\n          display: flex;\\n        }\\n      }\\n\\n      .timeline-scrollarea-wrapper {\\n        display: table-cell;\\n        padding-right: 1.5em;\\n        width: 7em;\\n      }\\n\\n      .timeline-scrollarea {\\n        border-right: 1px solid var(--tertiary-low-or-tertiary-high);\\n        border-left: none;\\n        max-width: 120px;\\n\\n        .timeline-scroller {\\n          position: relative;\\n          margin-right: -1.5em;\\n          padding-right: 1.5em;\\n          justify-content: flex-end;\\n\\n          .timeline-scroller-content {\\n            box-sizing: border-box;\\n            max-width: 100%;\\n            overflow: hidden;\\n            text-align: right;\\n            padding-left: 0;\\n            padding-right: 1em;\\n          }\\n\\n          .timeline-handle {\\n            float: none;\\n            width: 11px;\\n            position: relative;\\n            right: -6px;\\n          }\\n        }\\n\\n        .timeline-padding {\\n          margin-left: 0;\\n          margin-right: -1em;\\n        }\\n      }\\n    }\\n\\n    .timeline-scrollarea-wrapper::after {\\n      content: \\"\\";\\n      display: table;\\n      clear: both;\\n    }\\n\\n    .start-date,\\n    .now-date {\\n      padding: 0.5em 0;\\n    }\\n  }\\n\\n  .topic-timeline {\\n    transition: opacity 0.2s ease-in;\\n    touch-action: none;\\n    min-width: 6em;\\n\\n    .topic-admin-menu .btn {\\n      height: 100%;\\n    }\\n\\n    .timeline-controls {\\n      display: flex;\\n      gap: var(--space-2);\\n      margin-bottom: var(--space-4);\\n    }\\n\\n    .timeline-date-wrapper {\\n      max-width: 9em;\\n      overflow-wrap: anywhere;\\n    }\\n\\n    .timeline-footer-controls {\\n      // this is absolutely positioned to avoid\\n      // adding extra height below short topics\\n      // above the topic-footer-controls\\n      position: absolute;\\n      margin-top: 1em;\\n      display: flex;\\n      gap: var(--space-2);\\n      flex-wrap: wrap;\\n\\n      @media (prefers-reduced-motion: no-preference) {\\n        transition: opacity 0.2s ease-in;\\n      }\\n\\n      button:last-child {\\n        margin-right: 0;\\n      }\\n    }\\n\\n    .start-date {\\n      color: var(--primary-med-or-secondary-med);\\n    }\\n\\n    .timeline-scrollarea {\\n      margin-top: 0.5em;\\n      margin-left: 0.5em;\\n      border-left: 1px solid var(--topic-timeline-border-color);\\n      position: relative;\\n      max-width: 100%;\\n      transform: translateZ(0);\\n\\n      // The padding is a sibling of the scroller, so the drag state is read from\\n      // the parent the two share. Easing during a drag leaves the timeline\\n      // trailing the pointer for the length of the transition.\\n      &.--dragging .timeline-padding {\\n        transition: none;\\n      }\\n    }\\n\\n    .timeline-padding {\\n      transition: height 0.15s ease-out;\\n      cursor: pointer;\\n\\n      // this element has a click event\\n      // the negative margin lets this element overlap\\n      // the scrollarea's vertical track and thus it\\n      // enables taps on the track to work\\n      margin-left: -1em;\\n    }\\n\\n    .timeline-handle {\\n      border-radius: 0.8em;\\n      width: 0.35em;\\n      background-color: var(--topic-timeline-handle-color);\\n      height: 100%;\\n      float: left;\\n      flex-shrink: 0;\\n      z-index: z(\\"base\\") + 1;\\n      outline: 1px solid transparent;\\n      margin-left: 0.5px;\\n    }\\n\\n    .timeline-scroller-content {\\n      box-sizing: border-box;\\n      max-width: 100%;\\n      overflow: hidden;\\n      padding-left: var(--space-4);\\n      position: absolute; // prevents text length from impacting width\\n      max-height: 3em; // this hides the date when the count + date would wrap to more than 2 lines\\n    }\\n\\n    .timeline-ago {\\n      color: var(--primary-med-or-secondary-med);\\n      max-width: 100%;\\n      white-space: nowrap;\\n      overflow: hidden;\\n      text-overflow: ellipsis;\\n    }\\n\\n    .timeline-scroller {\\n      @include unselectable;\\n      margin-left: -0.22em;\\n      cursor: ns-resize;\\n      display: flex;\\n      align-items: center;\\n\\n      .back-button {\\n        margin-top: var(--space-4);\\n      }\\n    }\\n\\n    .timeline-replies {\\n      overflow: hidden;\\n      overflow-wrap: break-word;\\n      font-weight: bold;\\n    }\\n\\n    .timeline-last-read {\\n      position: absolute;\\n      margin-left: -0.35em;\\n      z-index: z(\\"base\\") + 2; // above timeline-handle\\n\\n      .progress {\\n        font-size: 0.8em;\\n        color: var(--tertiary);\\n        margin-right: var(--space-4);\\n      }\\n    }\\n\\n    .back-button {\\n      min-height: unset;\\n      padding: 2px 5px;\\n    }\\n\\n    .now-date {\\n      display: inline-block;\\n      color: var(--primary-med-or-secondary-med);\\n      margin-top: var(--space-2);\\n    }\\n  }\\n}\\n",".loading-indicator-container {\\n  --loading-width: 0.8;\\n  --still-loading-width: 0.9;\\n  --still-loading-duration: 10s;\\n  --done-duration: 0.4s;\\n  --fade-out-duration: 0.4s;\\n  position: fixed;\\n  top: 0;\\n  left: 0;\\n  z-index: z(\\"header\\") + 1;\\n  height: 3px;\\n  width: 100%;\\n  opacity: 0;\\n  transition: opacity var(--fade-out-duration) ease var(--done-duration);\\n  background-color: var(--primary-low);\\n\\n  .loading-indicator {\\n    height: 100%;\\n    width: 100%;\\n    transform: scaleX(0);\\n    transform-origin: left;\\n    background-color: var(--tertiary);\\n  }\\n\\n  &.loading,\\n  &.still-loading {\\n    opacity: 1;\\n    transition: opacity 0s;\\n  }\\n\\n  &.loading .loading-indicator {\\n    transition: transform var(--loading-duration) ease-in;\\n    transform: scaleX(var(--loading-width));\\n  }\\n\\n  &.still-loading .loading-indicator {\\n    transition: transform var(--still-loading-duration) linear;\\n    transform: scaleX(var(--still-loading-width));\\n  }\\n\\n  &.done .loading-indicator {\\n    transition: transform var(--done-duration) ease-out;\\n    transform: scaleX(1);\\n  }\\n\\n  &.discourse-hub-webview {\\n    // DiscourseHub obscures the top 1px to work around an iOS bug\\n    top: 1px;\\n  }\\n\\n  html.footer-nav-ipad & {\\n    top: var(--footer-nav-height);\\n  }\\n}\\n\\n.route-loading-spinner {\\n  grid-area: content;\\n  padding-top: 1.8em;\\n}\\n\\nbody.has-route-loading-spinner #main-outlet {\\n  display: none;\\n}\\n","@use \\"lib/viewport\\";\\n\\n.ProseMirror-container {\\n  margin: 0;\\n  overscroll-behavior: contain;\\n  overflow-anchor: none;\\n  flex-direction: column;\\n  overflow-y: auto;\\n  overflow-x: hidden;\\n  display: flex;\\n  height: 100%;\\n}\\n\\n.ProseMirror {\\n  outline: 0;\\n  padding: 0 0.625rem;\\n\\n  > div:first-child,\\n  > details:first-child {\\n    margin-top: var(--space-4);\\n\\n    // This is hacky, but helps having the leading gapcursor at the right position\\n    &.ProseMirror-gapcursor {\\n      position: relative;\\n      display: block;\\n    }\\n  }\\n\\n  h1,\\n  h2,\\n  h3,\\n  h4,\\n  h5,\\n  h6 {\\n    margin: 30px 0 10px;\\n\\n    &:first-child {\\n      margin-top: 10px;\\n    }\\n  }\\n\\n  h1 {\\n    font-size: var(--font-up-3-rem);\\n  }\\n\\n  h2 {\\n    font-size: var(--font-up-2-rem);\\n  }\\n\\n  h3 {\\n    font-size: var(--font-up-1-rem);\\n  }\\n\\n  .upload-placeholder {\\n    &.--image {\\n      position: relative;\\n      display: inline-block;\\n      vertical-align: bottom;\\n\\n      img {\\n        max-width: 350px;\\n\\n        @include viewport.until(sm) {\\n          max-width: 100%;\\n        }\\n        height: auto;\\n        border-radius: var(--d-border-radius);\\n        display: block;\\n        animation: placeholder 1.5s infinite;\\n      }\\n    }\\n\\n    &.--file {\\n      display: inline-flex;\\n      align-items: center;\\n      gap: var(--space-2);\\n      padding: 0 var(--space-1) 0 0.65em;\\n      border: 1px solid var(--primary-low-mid);\\n      border-radius: var(--d-border-radius);\\n      color: var(--primary-high);\\n      font-size: var(--font-down-1-rem);\\n\\n      .d-icon {\\n        fill: currentcolor;\\n      }\\n    }\\n\\n    &__overlay {\\n      position: absolute;\\n      bottom: var(--space-2);\\n      right: var(--space-2);\\n      display: flex;\\n      align-items: center;\\n      gap: var(--space-2);\\n      padding: 0 var(--space-1) 0 0.65em;\\n      background: var(--primary-very-low);\\n      border: 1px solid var(--primary-low-mid);\\n      border-radius: var(--d-border-radius);\\n      color: var(--primary-high);\\n      font-size: var(--font-down-1-rem);\\n    }\\n\\n    &__progress {\\n      color: var(--tertiary);\\n      font-weight: bold;\\n    }\\n\\n    &__filename,\\n    &__icon {\\n      animation: placeholder 1.5s infinite;\\n    }\\n\\n    &__cancel {\\n      padding: 0.5em 0.65em;\\n    }\\n  }\\n\\n  @keyframes placeholder {\\n    0% {\\n      opacity: 0.6;\\n    }\\n\\n    50% {\\n      opacity: 0.4;\\n    }\\n\\n    100% {\\n      opacity: 0.6;\\n    }\\n  }\\n\\n  ul,\\n  ol {\\n    padding-left: 1.25em;\\n\\n    &[data-tight=\\"true\\"] > li > p {\\n      margin-top: 0;\\n      margin-bottom: 0;\\n    }\\n  }\\n\\n  p {\\n    line-height: 1.5;\\n\\n    &:first-child {\\n      margin-top: 0.59rem;\\n    }\\n  }\\n\\n  p[data-placeholder] {\\n    overflow: hidden;\\n\\n    &::before {\\n      pointer-events: none;\\n      position: absolute;\\n      padding-top: 2px;\\n      padding-right: 0.5rem;\\n      content: attr(data-placeholder);\\n      color: var(--primary-400);\\n      line-height: 1.1;\\n    }\\n  }\\n\\n  del {\\n    background-color: var(--danger-low);\\n  }\\n\\n  ins {\\n    background-color: var(--success-low);\\n  }\\n\\n  mark {\\n    background-color: var(--highlight);\\n  }\\n\\n  td {\\n    padding: 3px 3px 3px 0.5em;\\n  }\\n\\n  th {\\n    padding-bottom: 2px;\\n    font-weight: bold;\\n    color: var(--primary);\\n  }\\n\\n  a:not([contenteditable=\\"false\\"] a) {\\n    cursor: inherit;\\n  }\\n\\n  kbd {\\n    // I believe this shouldn't be `inline-flex` in posts either (test with emojis before/after text to see why),\\n    // but overriding just for the editor for now\\n    display: inline;\\n    padding-top: 0.2rem;\\n  }\\n\\n  .onebox-wrapper {\\n    white-space: normal;\\n  }\\n\\n  .code-language-select {\\n    position: absolute;\\n    right: 0.25rem;\\n    top: -0.6rem;\\n    border: 1px solid var(--content-border-color);\\n    border-radius: var(--d-border-radius);\\n    background-color: var(--primary-very-low);\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1-rem);\\n  }\\n\\n  pre {\\n    position: relative;\\n  }\\n\\n  .html-block {\\n    border: 2px dashed var(--primary-low-mid);\\n    border-radius: var(--d-border-radius);\\n\\n    &.ProseMirror-selectednode {\\n      outline-offset: -2px;\\n      border-radius: calc(var(--d-border-radius) + 2px);\\n    }\\n\\n    &::after {\\n      position: absolute;\\n      right: 0;\\n      top: 0;\\n      content: \\"HTML\\";\\n      font-size: var(--font-down-2-rem);\\n      color: var(--primary-medium);\\n      z-index: 1;\\n      background: var(--secondary-very-high);\\n      padding: 0 var(--space-1);\\n      border-bottom-left-radius: var(--d-border-radius);\\n      border-top-right-radius: var(--d-border-radius);\\n    }\\n  }\\n\\n  .composer-image-grid {\\n    position: relative;\\n\\n    // Portal whitespace should not create anonymous line boxes in the grid.\\n    display: flex;\\n    flex-direction: column;\\n    min-block-size: var(--composer-image-grid-controls-min-block-size, 0);\\n    border: 2px dashed var(--primary-low-mid);\\n    border-radius: var(--d-border-radius);\\n    padding: var(--space-half) var(--space-2) 0 var(--space-2);\\n    margin-block: var(--space-4);\\n\\n    &__content {\\n      display: flex;\\n      flex-wrap: wrap;\\n      gap: var(--space-2);\\n      padding-block: var(--space-2);\\n\\n      p {\\n        margin: 0;\\n      }\\n    }\\n\\n    &__remove-btn {\\n      color: var(--primary-medium);\\n      padding: var(--space-1) var(--space-2);\\n      background: var(--secondary);\\n      border: 0;\\n      border-radius: var(--d-border-radius);\\n      font-size: var(--font-down-1-rem);\\n      white-space: nowrap;\\n      display: flex;\\n      align-items: center;\\n      gap: var(--space-1);\\n      cursor: pointer;\\n\\n      @include viewport.until(sm) {\\n        padding: var(--space-2) var(--space-4);\\n      }\\n\\n      html.discourse-no-touch &:hover:not(:disabled) {\\n        color: var(--primary);\\n        background: var(--d-hover);\\n      }\\n\\n      &:active:not(:disabled) {\\n        background: var(--secondary);\\n      }\\n\\n      &:focus-visible {\\n        @include default-focus;\\n      }\\n    }\\n\\n    img:not(.ProseMirror-separator) {\\n      @include viewport.until(md) {\\n        width: 150px !important;\\n        height: 150px !important;\\n      }\\n\\n      @include viewport.from(md) {\\n        width: 200px !important;\\n        height: 200px !important;\\n      }\\n      object-fit: cover;\\n    }\\n\\n    &.ProseMirror-selectednode {\\n      outline-offset: -2px;\\n      border-radius: calc(var(--d-border-radius) + 2px);\\n    }\\n  }\\n\\n  .composer-wrap-node {\\n    position: relative;\\n    white-space: normal;\\n    border: 2px dashed var(--primary-low-mid);\\n    border-radius: var(--d-border-radius);\\n    padding-inline: var(--space-2);\\n    margin-block: var(--space-4);\\n\\n    &.ProseMirror-selectednode {\\n      outline-offset: -2px;\\n      border-radius: calc(var(--d-border-radius) + 2px);\\n    }\\n\\n    .d-wrap-indicator {\\n      color: var(--primary-medium);\\n      background-color: var(--secondary);\\n      border: none;\\n      cursor: pointer;\\n\\n      &:hover {\\n        color: var(--primary);\\n      }\\n\\n      &.--inline {\\n        font-size: var(--font-down-2);\\n        padding: var(--space-half) 0;\\n        margin-left: calc(-1 * var(--space-1));\\n        margin-right: var(--space-2);\\n        vertical-align: text-top;\\n        display: inline-block;\\n      }\\n\\n      &.--block {\\n        position: absolute;\\n        z-index: 1;\\n        font-size: var(--font-down-1);\\n        left: var(--space-2);\\n        top: calc(-1 * var(--space-3) + 1px);\\n        padding: 0 var(--space-1);\\n      }\\n    }\\n  }\\n\\n  // both faces share one grid cell, so swapping them does not move the document\\n  .composer-preview-node {\\n    position: relative;\\n    display: grid;\\n    border: 1px solid var(--primary-low);\\n    border-radius: var(--d-border-radius);\\n    margin-block: var(--space-4);\\n    overflow: hidden;\\n\\n    > * {\\n      grid-area: 1 / 1;\\n\\n      // a face fits the block and scrolls its own overflow, rather than\\n      // sizing the shared cell to fit its content\\n      min-width: 0;\\n      min-height: 0;\\n    }\\n\\n    &.ProseMirror-selectednode {\\n      outline: 2px solid var(--tertiary);\\n      outline-offset: 2px;\\n    }\\n\\n    // hidden, but still holding its space. `&` is a complex selector here, so\\n    // the hidden face is named in full rather than suffixed onto a second `&`\\n    &:not(.--source) .composer-preview-node__source,\\n    &.--source .composer-preview-node__preview {\\n      visibility: hidden;\\n    }\\n\\n    // a long source scrolls within a bounded face instead of growing the block.\\n    // A preview that frames itself overrides the bound to match that frame.\\n    &__source {\\n      max-height: var(--composer-preview-node-source-max-height, 14lh);\\n    }\\n\\n    &__source pre {\\n      margin: 0;\\n      height: 100%;\\n      overflow: auto;\\n\\n      // the code element paints the backdrop, so it must fill the taller face's row\\n      code {\\n        box-sizing: border-box;\\n        min-height: 100%;\\n        max-height: none;\\n      }\\n    }\\n\\n    &__preview {\\n      user-select: none;\\n      cursor: pointer;\\n\\n      // the editor's display rules would otherwise override a renderer's [hidden]\\n      [hidden] {\\n        display: none;\\n      }\\n    }\\n  }\\n\\n  .onebox-loading {\\n    border-radius: var(--d-border-radius);\\n    padding: 0 0.125rem;\\n    background: linear-gradient(\\n      90deg,\\n      var(--primary-very-low) 0%,\\n      var(--primary-low) 50%,\\n      var(--primary-very-low) 100%\\n    );\\n    background-size: 200% 100%;\\n    animation: loading-pulse 1.5s ease-in-out infinite;\\n  }\\n\\n  @keyframes loading-pulse {\\n    0% {\\n      background-position: 200% 0;\\n    }\\n\\n    100% {\\n      background-position: -200% 0;\\n    }\\n  }\\n}\\n\\n.fk-d-menu[data-identifier=\\"composer-link-toolbar\\"],\\n.fk-d-menu[data-identifier=\\"composer-image-toolbar\\"],\\n.fk-d-menu[data-identifier=\\"composer-image-alt-text\\"],\\n.fk-d-menu[data-identifier^=\\"composer-image-grid-mode-\\"],\\n.fk-d-menu[data-identifier^=\\"composer-image-grid-remove-\\"],\\n.fk-d-menu[data-identifier=\\"composer-preview-toolbar\\"],\\n.fk-d-menu[data-identifier=\\"composer-onebox-toolbar\\"] {\\n  user-select: none;\\n  z-index: z(\\"composer\\", \\"dropdown\\");\\n\\n  .fk-d-menu__inner-content {\\n    overflow: visible;\\n  }\\n\\n  .toolbar__button {\\n    background-color: var(--secondary);\\n    color: var(--primary-medium);\\n    border-radius: var(--d-border-radius);\\n\\n    .d-icon {\\n      color: var(--primary-medium);\\n    }\\n\\n    &:hover:not(:disabled) {\\n      color: var(--primary);\\n\\n      .d-icon {\\n        color: var(--primary);\\n      }\\n    }\\n\\n    &:active {\\n      background: var(--secondary);\\n    }\\n\\n    &:focus-visible {\\n      @include default-focus;\\n    }\\n\\n    &.--active {\\n      background: var(--d-selected);\\n      color: var(--d-selected-text-color);\\n    }\\n  }\\n\\n  .composer-link-toolbar__visit {\\n    .d-button-label {\\n      max-width: 12rem;\\n    }\\n  }\\n}\\n\\n.composer-link-toolbar__visit {\\n  min-width: 0;\\n  align-items: center;\\n\\n  // visit link has a right-side icon\\n  flex-direction: row-reverse;\\n\\n  .d-icon {\\n    // overrides the default from d-button.scss\\n    margin-right: 0;\\n  }\\n\\n  .d-button-label {\\n    font-size: var(--font-down-1-rem);\\n    overflow: hidden;\\n    text-overflow: ellipsis;\\n    white-space: nowrap;\\n  }\\n\\n  &:not(:disabled) .d-button-label {\\n    margin-right: 0.5rem;\\n  }\\n}\\n\\n.fk-d-menu[data-identifier=\\"composer-image-alt-text\\"] {\\n  width: calc(100% - 1rem);\\n  min-width: calc(max(100% - 1rem, 7.25rem));\\n  background-color: rgb(var(--secondary-rgb), 0.65);\\n  backdrop-filter: blur(4px);\\n  color: var(--primary);\\n  isolation: auto;\\n  border-radius: var(--d-border-radius);\\n  font-size: var(--font-down-1);\\n  box-shadow: var(--shadow-dropdown);\\n\\n  .fk-d-menu__inner-content {\\n    width: 100%;\\n    box-sizing: border-box;\\n    border: none;\\n    box-shadow: none;\\n    background-color: transparent;\\n    min-width: 100%;\\n    padding: 0.25rem 0.5rem;\\n  }\\n\\n  &:focus-within {\\n    box-shadow: 0 0 0 2px var(--tertiary-high);\\n  }\\n\\n  &:has(.image-alt-text-input.--expanded) {\\n    min-width: calc(max(100% - 1rem, 15rem));\\n  }\\n  transition: min-width 0.15s ease;\\n}\\n\\n.composer-image-node {\\n  display: inline-block;\\n  white-space: normal;\\n  position: relative;\\n\\n  // This makes the editor less pixel perfect with cooked, but it helps with some\\n  // hard positions (like between images), and makes the blinking cursor more visible\\n  // The vertical offset increases the drop area between image paragraphs\\n  margin: -2px 1px;\\n  padding: 2px 1px;\\n\\n  img {\\n    display: inline-block;\\n    height: auto;\\n    max-width: 100%;\\n    border-radius: var(--d-border-radius);\\n    transition:\\n      width 0.2s ease,\\n      height 0.2s ease;\\n\\n    &:not(.ProseMirror-selectednode):hover {\\n      cursor: pointer;\\n    }\\n\\n    &.ProseMirror-selectednode {\\n      user-select: none;\\n      cursor: zoom-in;\\n    }\\n  }\\n\\n  &:has(.image-alt-text-input:focus-within) img.ProseMirror-selectednode {\\n    cursor: default;\\n  }\\n}\\n\\n.composer-video-node {\\n  aspect-ratio: 16 / 9;\\n  background-color: rgb(var(--always-black-rgb));\\n  border-radius: var(--d-border-radius);\\n  display: grid;\\n  overflow: hidden;\\n  place-items: center;\\n  position: relative;\\n  width: 100%;\\n\\n  &__error {\\n    background-color: var(--danger-low);\\n    color: var(--primary);\\n    inset-block-start: 0;\\n    inset-inline: 0;\\n    padding: var(--space-2);\\n    position: absolute;\\n    z-index: 1;\\n  }\\n\\n  &__play.btn-flat {\\n    --d-button-flat-bg-color: color-mix(\\n      in srgb,\\n      var(--primary) 75%,\\n      transparent\\n    );\\n    --d-button-flat-bg-color--focus: color-mix(\\n      in srgb,\\n      var(--primary) 85%,\\n      transparent\\n    );\\n    --d-button-flat-bg-color--hover: color-mix(\\n      in srgb,\\n      var(--primary) 85%,\\n      transparent\\n    );\\n    --d-button-flat-icon-color: var(--secondary);\\n    --d-button-flat-icon-color--hover: var(--secondary);\\n    padding: 1rem;\\n    z-index: 2;\\n\\n    .d-icon {\\n      filter: drop-shadow(3px 3px 2px rgb(var(--always-black-rgb), 0.25));\\n      height: 2.3rem;\\n      transition: transform 0.15s;\\n      width: 2.3rem;\\n\\n      @media (prefers-reduced-motion) {\\n        transition: transform 0s;\\n      }\\n    }\\n\\n    @include hover {\\n      .d-icon {\\n        transform: scale(1.2);\\n      }\\n    }\\n  }\\n\\n  &__video {\\n    display: block;\\n    height: 100%;\\n    border-radius: var(--d-border-radius);\\n    inset: 0;\\n    object-fit: contain;\\n    position: absolute;\\n    width: 100%;\\n\\n    &.is-inactive {\\n      pointer-events: none;\\n    }\\n  }\\n}\\n\\n.image-alt-text-input {\\n  min-width: 100%;\\n  display: flex;\\n  position: relative;\\n  transition: height 0.15s ease;\\n  height: 1.5em;\\n\\n  @media (prefers-reduced-motion: reduce) {\\n    transition: none;\\n  }\\n\\n  &.--expanded {\\n    height: 4.25em;\\n  }\\n\\n  &__field {\\n    flex: 1;\\n    border: none;\\n    outline: none;\\n    padding: 0;\\n    background: transparent;\\n    resize: none;\\n    margin: 0;\\n    scrollbar-color: rgb(var(--primary-rgb), 0.3) transparent;\\n    scrollbar-width: thin;\\n    overflow-y: auto;\\n    scrollbar-gutter: stable;\\n    line-height: var(--line-height-large);\\n\\n    &::placeholder {\\n      color: var(--primary);\\n    }\\n\\n    &:focus {\\n      outline: none;\\n    }\\n  }\\n\\n  &__display {\\n    cursor: pointer;\\n    overflow: hidden;\\n    text-overflow: ellipsis;\\n    white-space: nowrap;\\n    flex: 1;\\n  }\\n}\\n\\n/*********************************************************\\n Section below from prosemirror-view/style/prosemirror.css\\n ********************************************************/\\n\\n// stylelint-disable-next-line no-duplicate-selectors\\n.ProseMirror {\\n  overflow-wrap: break-word;\\n  white-space: break-spaces;\\n\\n  // Any children with position fixed will be relative to this element (eg. footnotes)\\n  // see https://developer.mozilla.org/en-US/docs/Web/CSS/Guides/Display/Containing_block#identifying_the_containing_block\\n  contain: layout;\\n}\\n\\n// stylelint-disable-next-line no-duplicate-selectors\\n.ProseMirror pre {\\n  white-space: pre-wrap;\\n}\\n\\n.ProseMirror li {\\n  position: relative;\\n}\\n\\n.ProseMirror-hideselection *::selection {\\n  background: transparent;\\n}\\n\\n.ProseMirror-hideselection {\\n  caret-color: transparent;\\n}\\n\\n/* See https://github.com/ProseMirror/prosemirror/issues/1421#issuecomment-1759320191 */\\n.ProseMirror [draggable][contenteditable=\\"false\\"] {\\n  user-select: text;\\n}\\n\\n.ProseMirror-selectednode {\\n  outline: 2px solid var(--tertiary-high);\\n  border-radius: var(--d-border-radius);\\n}\\n\\n/* Make sure li selections wrap around markers */\\nli.ProseMirror-selectednode {\\n  outline: none;\\n}\\n\\nli.ProseMirror-selectednode::after {\\n  content: \\"\\";\\n  position: absolute;\\n  left: -32px;\\n  right: -2px;\\n  top: -2px;\\n  bottom: -2px;\\n  border: 2px solid var(--tertiary-high);\\n  border-radius: var(--d-border-radius);\\n  pointer-events: none;\\n}\\n\\n/* Protect against generic img rules */\\n.ProseMirror-separator {\\n  display: inline !important;\\n  border: none !important;\\n  margin: 0 !important;\\n}\\n\\n/************************************************************\\n Section below from prosemirror-gapcursor/style/gapcursor.css\\n ***********************************************************/\\n\\n.ProseMirror-gapcursor {\\n  display: none;\\n  pointer-events: none;\\n  position: sticky;\\n}\\n\\n.ProseMirror-gapcursor::after {\\n  content: \\"\\";\\n  display: block;\\n  position: absolute;\\n  top: -2px;\\n  width: 20px;\\n  border-top: 1px solid var(--primary);\\n  animation: ProseMirror-cursor-blink 1.1s steps(2, start) infinite;\\n}\\n\\n@keyframes ProseMirror-cursor-blink {\\n  to {\\n    visibility: hidden;\\n  }\\n}\\n\\n.ProseMirror-focused .ProseMirror-gapcursor {\\n  display: block;\\n}\\n\\n/************************************************************\\n Section below from prosemirror-codemark/src/codemark.css\\n ***********************************************************/\\n@keyframes fake-cursor-blink {\\n  49% {\\n    border-color: unset;\\n  }\\n\\n  50% {\\n    border-color: transparent;\\n  }\\n\\n  99% {\\n    border-color: transparent;\\n  }\\n}\\n\\n.no-cursor {\\n  caret-color: transparent;\\n}\\n\\ndiv:focus .fake-cursor,\\nspan:focus .fake-cursor {\\n  margin-right: -1px;\\n  border-left-width: 1px;\\n  border-left-style: solid;\\n  animation: fake-cursor-blink 1s;\\n  animation-iteration-count: infinite;\\n  position: relative;\\n  z-index: 1;\\n}\\n","@use \\"lib/viewport\\";\\n\\n.composer-image-gallery {\\n  &__mode-buttons {\\n    display: flex;\\n\\n    @include viewport.until(sm) {\\n      flex-direction: column;\\n      gap: var(--space-2);\\n    }\\n  }\\n\\n  &__mode-btn {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-2);\\n    border: 0;\\n    border-radius: var(--d-border-radius);\\n    background: var(--secondary);\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1-rem);\\n    padding: var(--space-1) var(--space-2);\\n    cursor: pointer;\\n\\n    @include viewport.until(sm) {\\n      padding: var(--space-2) var(--space-4);\\n    }\\n\\n    @include viewport.from(sm) {\\n      &:first-child {\\n        border-start-end-radius: 0;\\n        border-end-end-radius: 0;\\n      }\\n\\n      &:last-child {\\n        border-start-start-radius: 0;\\n        border-end-start-radius: 0;\\n      }\\n\\n      &:not(:first-child) {\\n        border-inline-start: 1px solid var(--content-border-color);\\n      }\\n    }\\n\\n    html.discourse-no-touch &:hover:not(:disabled, .is-active) {\\n      color: var(--primary);\\n      background-color: var(--d-hover);\\n    }\\n\\n    &:active:not(:disabled) {\\n      background: var(--secondary);\\n    }\\n\\n    &.is-active {\\n      background-color: var(--tertiary-low);\\n      color: var(--tertiary);\\n    }\\n\\n    &:focus-visible {\\n      @include default-focus;\\n    }\\n  }\\n}\\n",".ProseMirror {\\n  .composer-table {\\n    --handle-length: 1.375rem;\\n    --handle-thickness: 0.375rem;\\n    --append-thickness: 0.875rem;\\n    --grip-lane: 1.125rem;\\n\\n    @media (hover: none) {\\n      --handle-length: 1.75rem;\\n      --handle-thickness: 0.5rem;\\n      --append-thickness: 1.125rem;\\n      --grip-lane: 1.375rem;\\n    }\\n    position: relative;\\n    overflow-x: auto;\\n    overflow-y: hidden;\\n\\n    &.is-panning table {\\n      user-select: none;\\n    }\\n\\n    // Reserve space for controls inside the scroll container.\\n    padding: var(--grip-lane);\\n\\n    // Keep the negative margin within the editor padding to avoid clipping.\\n    margin: 1em -0.625rem;\\n\\n    &__inner {\\n      position: relative;\\n      width: max-content;\\n    }\\n\\n    // Use an outline to avoid layout shifts when controls appear.\\n    table {\\n      outline: 1px solid transparent;\\n      touch-action: pan-y pinch-zoom;\\n      transition: outline-color 0.12s ease;\\n    }\\n\\n    th,\\n    td {\\n      position: relative;\\n\\n      // Keep empty cells wide enough to place the caret.\\n      min-width: 5em;\\n\\n      // Compose shadows so corner cells can display both highlighted edges.\\n      &.is-structural-target {\\n        --edge-top: 0 0 0 0 transparent;\\n        --edge-right: 0 0 0 0 transparent;\\n        --edge-bottom: 0 0 0 0 transparent;\\n        --edge-left: 0 0 0 0 transparent;\\n        background-color: var(--token-color-background-accent-subtlest);\\n        box-shadow:\\n          var(--edge-top), var(--edge-right), var(--edge-bottom),\\n          var(--edge-left);\\n\\n        &.--axis-row {\\n          --edge-top: inset 0 2px 0 0 var(--token-color-border-focused);\\n          --edge-bottom: inset 0 -2px 0 0 var(--token-color-border-focused);\\n\\n          &.--edge-start {\\n            --edge-left: inset 2px 0 0 0 var(--token-color-border-focused);\\n          }\\n\\n          &.--edge-end {\\n            --edge-right: inset -2px 0 0 0 var(--token-color-border-focused);\\n          }\\n        }\\n\\n        &.--axis-column {\\n          --edge-left: inset 2px 0 0 0 var(--token-color-border-focused);\\n          --edge-right: inset -2px 0 0 0 var(--token-color-border-focused);\\n\\n          &.--edge-start {\\n            --edge-top: inset 0 2px 0 0 var(--token-color-border-focused);\\n          }\\n\\n          &.--edge-end {\\n            --edge-bottom: inset 0 -2px 0 0 var(--token-color-border-focused);\\n          }\\n        }\\n      }\\n    }\\n\\n    // Swap physical shadow offsets in RTL; box-shadow has no logical equivalent.\\n    html[dir=\\"rtl\\"] & {\\n      th,\\n      td {\\n        &.is-structural-target.--axis-row {\\n          &.--edge-start {\\n            --edge-left: 0 0 0 0 transparent;\\n            --edge-right: inset -2px 0 0 0 var(--token-color-border-focused);\\n          }\\n\\n          &.--edge-end {\\n            --edge-right: 0 0 0 0 transparent;\\n            --edge-left: inset 2px 0 0 0 var(--token-color-border-focused);\\n          }\\n        }\\n      }\\n    }\\n\\n    &__grip,\\n    &__append {\\n      position: absolute;\\n      z-index: 1;\\n      padding: 0;\\n      border: var(--token-border-width) solid transparent;\\n      background-color: var(--token-color-surface-pressed);\\n      cursor: pointer;\\n      opacity: 0;\\n      pointer-events: none;\\n      transition:\\n        opacity 0.12s ease,\\n        background-color 0.12s ease;\\n\\n      &:focus-visible {\\n        opacity: 1;\\n        pointer-events: auto;\\n        outline: 2px solid var(--token-color-border-focused);\\n        outline-offset: 2px;\\n      }\\n    }\\n\\n    &__grip {\\n      border-radius: var(--token-radius-normal);\\n      cursor: grab;\\n\\n      &::after {\\n        content: \\"\\";\\n        position: absolute;\\n        inset: -0.5rem;\\n      }\\n\\n      @media (hover: hover) {\\n        &:hover {\\n          background-color: var(--token-color-icon-default);\\n        }\\n      }\\n\\n      &.--column {\\n        top: 0;\\n        left: 50%;\\n        translate: -50% -50%;\\n        width: var(--handle-length);\\n        height: var(--handle-thickness);\\n        touch-action: none;\\n      }\\n\\n      &.--row {\\n        inset-inline-start: 0;\\n        top: 50%;\\n        translate: -50% -50%;\\n        width: var(--handle-thickness);\\n        height: var(--handle-length);\\n        touch-action: none;\\n\\n        &:dir(rtl) {\\n          translate: 50% -50%;\\n        }\\n      }\\n\\n      &.is-visible {\\n        opacity: 1;\\n        pointer-events: auto;\\n      }\\n    }\\n\\n    // The axis class prevents a highlighted header row from activating every column grip.\\n    .is-structural-target.--axis-column .composer-table__grip.--column,\\n    .is-structural-target.--axis-row .composer-table__grip.--row {\\n      opacity: 1;\\n      pointer-events: auto;\\n      border-color: transparent;\\n      background-color: var(--token-color-background-accent-bolder);\\n\\n      &::before {\\n        content: \\"\\";\\n        position: absolute;\\n        top: 50%;\\n        left: 50%;\\n        translate: -50% -50%;\\n        background-image: radial-gradient(\\n          circle,\\n          var(--token-color-text-inverse) 0.75px,\\n          transparent 0.75px\\n        );\\n        background-size: 0.25rem 0.25rem;\\n      }\\n    }\\n\\n    .is-structural-target.--axis-column .composer-table__grip.--column {\\n      height: calc(var(--handle-thickness) * 2);\\n\\n      &::before {\\n        width: 0.75rem;\\n        height: 0.5rem;\\n      }\\n    }\\n\\n    .is-structural-target.--axis-row .composer-table__grip.--row {\\n      width: calc(var(--handle-thickness) * 2);\\n\\n      &::before {\\n        width: 0.5rem;\\n        height: 0.75rem;\\n      }\\n    }\\n\\n    &__append {\\n      border-radius: var(--token-radius-normal);\\n\\n      .d-icon {\\n        position: absolute;\\n        top: 50%;\\n        left: 50%;\\n        width: 0.625rem;\\n        height: 0.625rem;\\n        translate: -50% -50%;\\n        color: var(--token-color-icon-default);\\n        transition: color 0.12s ease;\\n      }\\n\\n      &:focus-visible {\\n        background-color: var(--token-color-background-accent-bolder);\\n\\n        .d-icon {\\n          color: var(--token-color-text-inverse);\\n        }\\n      }\\n\\n      @media (hover: hover) {\\n        &:hover {\\n          background-color: var(--token-color-background-accent-bolder);\\n\\n          .d-icon {\\n            color: var(--token-color-text-inverse);\\n          }\\n        }\\n      }\\n\\n      &.is-appending,\\n      &.is-removing {\\n        opacity: 1;\\n        pointer-events: auto;\\n\\n        .d-icon {\\n          opacity: 0;\\n        }\\n\\n        .composer-table__append-count {\\n          display: block;\\n        }\\n      }\\n\\n      &.is-appending {\\n        background-color: var(--token-color-background-accent-bolder);\\n      }\\n\\n      &.is-removing {\\n        background-color: var(--danger);\\n      }\\n\\n      &.--column {\\n        top: 0;\\n        bottom: 0;\\n        inset-inline-end: calc(var(--grip-lane) * -1);\\n        width: var(--append-thickness);\\n        touch-action: pan-y pinch-zoom;\\n        cursor: ew-resize;\\n\\n        &::after {\\n          content: \\"\\";\\n          position: absolute;\\n          inset-block: 0;\\n          inset-inline: -0.375rem;\\n        }\\n      }\\n\\n      &.--row {\\n        left: 0;\\n        right: 0;\\n        bottom: calc(var(--grip-lane) * -1);\\n        height: var(--append-thickness);\\n        touch-action: pan-x pinch-zoom;\\n        cursor: ns-resize;\\n\\n        &::after {\\n          content: \\"\\";\\n          position: absolute;\\n          inset-block: -0.375rem;\\n          inset-inline: 0;\\n        }\\n      }\\n    }\\n\\n    &__append-count {\\n      position: absolute;\\n      top: 50%;\\n      left: 50%;\\n      display: none;\\n      min-width: 1.25rem;\\n      padding: var(--space-half) var(--space-1);\\n      border: var(--token-border-width) solid var(--token-color-border-default);\\n      border-radius: var(--token-radius-full);\\n      translate: -50% -50%;\\n      background-color: var(--token-color-surface);\\n      box-shadow: 0 2px 5px rgb(var(--primary-rgb), 0.18);\\n      color: var(--token-color-text-default);\\n      font-size: var(--font-down-2);\\n      font-weight: var(--token-font-weight-semibold);\\n      line-height: 1;\\n      text-align: center;\\n      white-space: nowrap;\\n    }\\n\\n    // The node view adds padding to prevent the drag preview from being clipped.\\n    &__ghost {\\n      --ghost-step: 0px;\\n      --ghost-flow: to right;\\n      position: absolute;\\n      z-index: 1;\\n      display: none;\\n      border: 1px dashed var(--token-color-border-focused);\\n      border-radius: var(--token-radius-normal);\\n      background-color: var(--token-color-background-accent-subtlest);\\n      background-image: repeating-linear-gradient(\\n        var(--ghost-flow),\\n        transparent 0 calc(var(--ghost-step) - 1px),\\n        currentcolor calc(var(--ghost-step) - 1px) var(--ghost-step)\\n      );\\n      pointer-events: none;\\n\\n      &.--visible {\\n        display: block;\\n      }\\n\\n      &.--column {\\n        --ghost-flow: to right;\\n      }\\n\\n      &.--row {\\n        --ghost-flow: to bottom;\\n      }\\n\\n      &.--add {\\n        border-color: var(--token-color-border-focused);\\n        background-color: var(--token-color-background-accent-subtlest);\\n        color: var(--token-color-border-focused);\\n      }\\n\\n      &.--remove {\\n        border-color: var(--danger);\\n        background-color: var(--danger-low);\\n        color: var(--danger);\\n      }\\n    }\\n\\n    &__drop-indicator {\\n      position: absolute;\\n      z-index: 2;\\n      display: none;\\n      border-radius: 1px;\\n      background-color: var(--token-color-border-focused);\\n      pointer-events: none;\\n\\n      &.--row {\\n        display: block;\\n        left: 0;\\n        right: 0;\\n        height: 2px;\\n        translate: 0 -1px;\\n      }\\n\\n      &.--column {\\n        display: block;\\n        top: 0;\\n        bottom: 0;\\n        width: 2px;\\n        translate: -1px 0;\\n      }\\n    }\\n\\n    @media (hover: hover) {\\n      &:hover {\\n        .composer-table__append {\\n          opacity: 1;\\n          pointer-events: auto;\\n        }\\n\\n        table {\\n          outline-color: var(--token-color-border-default);\\n        }\\n      }\\n    }\\n\\n    @media (hover: none) {\\n      &.is-active {\\n        .composer-table__append {\\n          opacity: 1;\\n          pointer-events: auto;\\n        }\\n\\n        table {\\n          outline-color: var(--token-color-border-default);\\n        }\\n      }\\n\\n      .is-current-row .composer-table__grip.--row,\\n      .is-current-column .composer-table__grip.--column {\\n        opacity: 1;\\n        pointer-events: auto;\\n      }\\n\\n      .composer-table__grip.--column::after {\\n        inset-block: -1.125rem;\\n        inset-inline: -0.5rem;\\n      }\\n\\n      .composer-table__grip.--row::after {\\n        inset-block: -0.5rem;\\n        inset-inline: -1.125rem;\\n      }\\n\\n      .composer-table__append.--column::after {\\n        inset-inline: -0.8125rem;\\n      }\\n\\n      .composer-table__append.--row::after {\\n        inset-block: -0.8125rem;\\n      }\\n    }\\n\\n    .is-reordering {\\n      .composer-table__grip.is-visible {\\n        cursor: grabbing;\\n      }\\n\\n      th.is-moving,\\n      td.is-moving {\\n        z-index: 1;\\n        opacity: 0.55;\\n        background-color: var(--token-color-background-accent-subtlest);\\n      }\\n    }\\n\\n    @media (prefers-reduced-motion: reduce) {\\n      table,\\n      .composer-table__grip,\\n      .composer-table__append,\\n      .composer-table__append .d-icon {\\n        transition: none;\\n      }\\n    }\\n\\n    @media (forced-colors: active) {\\n      th.is-structural-target,\\n      td.is-structural-target {\\n        outline: 2px solid Highlight;\\n        outline-offset: -2px;\\n      }\\n\\n      .composer-table__grip,\\n      .composer-table__append {\\n        border-color: ButtonText;\\n      }\\n\\n      .is-structural-target.--axis-column .composer-table__grip.--column,\\n      .is-structural-target.--axis-row .composer-table__grip.--row {\\n        outline: 2px solid Highlight;\\n        background: Highlight;\\n        color: HighlightText;\\n        forced-color-adjust: none;\\n      }\\n    }\\n  }\\n}\\n\\n.composer-table__drag-avatar {\\n  position: fixed;\\n  z-index: z(\\"composer\\", \\"dropdown\\");\\n  border-radius: var(--token-radius-normal);\\n  background-color: var(--token-color-background-accent-bolder);\\n  pointer-events: none;\\n\\n  &::before {\\n    content: \\"\\";\\n    position: absolute;\\n    top: 50%;\\n    left: 50%;\\n    width: 0.75rem;\\n    height: 0.5rem;\\n    translate: -50% -50%;\\n    background-image: radial-gradient(\\n      circle,\\n      var(--token-color-text-inverse) 0.75px,\\n      transparent 0.75px\\n    );\\n    background-size: 0.25rem 0.25rem;\\n  }\\n\\n  &.--row::before {\\n    width: 0.5rem;\\n    height: 0.75rem;\\n  }\\n}\\n\\n.composer-table__grip.is-drag-origin {\\n  opacity: 0;\\n}\\n\\n.fk-d-menu[data-identifier=\\"composer-table-menu\\"] {\\n  // The composer sits above the default dropdown layer.\\n  z-index: z(\\"composer\\", \\"dropdown\\");\\n  user-select: none;\\n\\n  .fk-d-menu__inner-content {\\n    overflow: hidden;\\n    border-color: var(--token-color-border-default);\\n    border-radius: var(--token-radius-large);\\n  }\\n}\\n\\n.composer-table-menu {\\n  min-width: 15rem;\\n  gap: 0;\\n  padding: var(--space-1);\\n\\n  .dropdown-menu__divider {\\n    margin-block: var(--space-1);\\n    border-color: var(--token-color-border-default);\\n  }\\n\\n  .btn {\\n    min-height: 2.125rem;\\n    height: auto;\\n    gap: var(--space-2);\\n    padding: var(--space-2);\\n    border: 0;\\n    color: var(--token-color-text-default);\\n    font-size: var(--font-down-1);\\n    line-height: var(--line-height-medium);\\n\\n    .d-icon {\\n      width: 1rem;\\n      color: var(--token-color-icon-subtle);\\n      font-size: var(--font-down-1);\\n    }\\n\\n    &:hover,\\n    &:focus-visible {\\n      background-color: var(--token-color-surface-hovered);\\n    }\\n\\n    &.--active {\\n      background-color: var(--token-color-surface-selected);\\n\\n      .d-icon {\\n        color: var(--token-color-text-accent);\\n      }\\n    }\\n\\n    &.--dangerous:hover,\\n    &.--dangerous:focus-visible {\\n      background-color: var(--danger-low);\\n      color: var(--danger);\\n\\n      .d-icon {\\n        color: var(--token-color-icon-danger);\\n      }\\n    }\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n@keyframes code-login-form-dice-roll {\\n  0% {\\n    transform: rotate(0deg) scale(1);\\n  }\\n\\n  50% {\\n    transform: rotate(180deg) scale(1.2);\\n  }\\n\\n  100% {\\n    transform: rotate(360deg) scale(1);\\n  }\\n}\\n\\n@keyframes code-login-form-step-in {\\n  from {\\n    opacity: 0;\\n    transform: translateY(0.5rem);\\n  }\\n\\n  to {\\n    opacity: 1;\\n    transform: translateY(0);\\n  }\\n}\\n\\n.code-login-form {\\n  display: flex;\\n  flex-direction: column;\\n  gap: 1em;\\n\\n  // No waving-hand icon here, so drop the welcome header's icon grid.\\n  .login-welcome-header {\\n    display: block;\\n\\n    // Keep a trailing emoji/short word from orphaning onto its own line.\\n    .login-title {\\n      text-wrap: pretty;\\n    }\\n  }\\n\\n  &__email-step {\\n    display: flex;\\n    flex-direction: column;\\n    gap: 1em;\\n  }\\n\\n  &__code-step,\\n  &__second-factor-step,\\n  &__account-details-step,\\n  &__user-fields-step,\\n  &__signup-details-step,\\n  &__pending-approval-step {\\n    display: flex;\\n    flex-direction: column;\\n    align-items: flex-start;\\n    gap: 1em;\\n\\n    // Ease each step in so advancing through the flow doesn't snap abruptly.\\n    @media (prefers-reduced-motion: no-preference) {\\n      animation: code-login-form-step-in 0.25s ease;\\n    }\\n  }\\n\\n  &__account-details-step,\\n  &__user-fields-step {\\n    .user-fields {\\n      align-self: stretch;\\n      margin-top: 0.5em;\\n    }\\n  }\\n\\n  &__account-fields {\\n    display: grid;\\n    grid-template-columns: minmax(0, 1fr);\\n    align-self: stretch;\\n    gap: 1em 0.5em;\\n\\n    &.--with-username-generator {\\n      grid-template-columns: minmax(0, 1fr) auto;\\n    }\\n\\n    .code-login-form__username-field {\\n      display: grid;\\n      grid-template-columns: subgrid;\\n      grid-column: 1 / -1;\\n      gap: 0.25em 0.5em;\\n\\n      > label,\\n      > .code-login-form__error {\\n        grid-column: 1 / -1;\\n      }\\n    }\\n\\n    .code-login-form__username-input {\\n      display: contents;\\n    }\\n\\n    .code-login-form__name-field {\\n      grid-column: 1 / -1;\\n    }\\n\\n    .code-login-form__password-field,\\n    .code-login-form__create-password {\\n      grid-column: 1;\\n    }\\n\\n    .code-login-form__password-field input {\\n      width: 100%;\\n      min-width: 0;\\n    }\\n  }\\n\\n  &__name-field {\\n    display: flex;\\n    flex-direction: column;\\n    align-self: stretch;\\n    gap: 0.25em;\\n  }\\n\\n  &__name {\\n    width: 100%;\\n    margin: 0;\\n  }\\n\\n  &__password-field {\\n    align-self: stretch;\\n    width: 100%;\\n    margin: 0;\\n  }\\n\\n  &__new-account {\\n    display: flex;\\n    flex-direction: column;\\n    align-items: center;\\n    align-self: stretch;\\n    gap: 1em;\\n    padding: 1em 0;\\n  }\\n\\n  &__avatar {\\n    position: relative;\\n    padding: 0;\\n    border: none;\\n    background: none;\\n    cursor: pointer;\\n    line-height: 0;\\n\\n    .avatar {\\n      display: block;\\n    }\\n  }\\n\\n  &__avatar-placeholder {\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    width: 144px;\\n    height: 144px;\\n    border-radius: 50%;\\n    background: var(--primary-low);\\n    color: var(--primary-medium);\\n\\n    .d-icon {\\n      width: 50%;\\n      height: 50%;\\n    }\\n  }\\n\\n  &__avatar-edit {\\n    position: absolute;\\n    right: 0;\\n    bottom: 0;\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    width: 2em;\\n    height: 2em;\\n    border-radius: 50%;\\n    background: var(--tertiary);\\n    color: var(--secondary);\\n\\n    .d-icon {\\n      margin: 0;\\n    }\\n  }\\n\\n  &__username-field {\\n    display: flex;\\n    flex-direction: column;\\n    align-self: stretch;\\n    gap: 0.25em;\\n  }\\n\\n  &__username-input {\\n    // The regenerate button sits beside the input rather than inside it, so it\\n    // doesn't compete with password managers for the field's trailing edge.\\n    display: flex;\\n    align-self: stretch;\\n    gap: 0.5em;\\n\\n    // Outweigh the base input[type=\\"text\\"] margin-bottom so the input and the\\n    // regenerate button beside it stay the same height.\\n    input[type=\\"text\\"] {\\n      flex: 1 1 auto;\\n      min-width: 0;\\n      width: auto;\\n      margin: 0;\\n    }\\n  }\\n\\n  &__new-account-username {\\n    width: 100%;\\n\\n    // Crossfade the text while a regenerated username is on its way, so the\\n    // new name fades in rather than snapping into place.\\n    @media (prefers-reduced-motion: no-preference) {\\n      transition: color 0.2s ease;\\n\\n      &.--swapping {\\n        color: transparent;\\n      }\\n    }\\n  }\\n\\n  &__username-regen {\\n    display: flex;\\n    flex: 0 0 auto;\\n    align-items: center;\\n    justify-content: center;\\n\\n    // The dice glyph is wider than it is tall, so at the default 1em it\\n    // renders visually smaller than square icons.\\n    .d-icon {\\n      font-size: var(--font-up-2);\\n    }\\n\\n    // One cycle matches the minimum rolling duration the component holds, so\\n    // the spin completes cleanly on fast responses and keeps going on slow\\n    // ones instead of freezing mid-roll.\\n    @media (prefers-reduced-motion: no-preference) {\\n      &.--rolling .d-icon {\\n        animation: code-login-form-dice-roll 0.4s ease infinite;\\n      }\\n    }\\n  }\\n\\n  &__continue-to-site {\\n    align-self: stretch;\\n  }\\n\\n  &__title {\\n    margin: 0;\\n  }\\n\\n  &__instructions {\\n    margin: 0;\\n    color: var(--primary-high);\\n  }\\n\\n  &__error {\\n    color: var(--danger);\\n\\n    &:empty {\\n      display: none;\\n    }\\n  }\\n\\n  &__notice {\\n    margin: 0;\\n    color: var(--success);\\n  }\\n\\n  &__actions {\\n    display: flex;\\n    flex-wrap: wrap;\\n    gap: 0.5em;\\n  }\\n\\n  &__email-actions {\\n    display: flex;\\n    flex-wrap: wrap;\\n    align-items: center;\\n    gap: 0.5em;\\n  }\\n}\\n\\n// Keep the disclaimer from hugging the continue button it follows.\\n.code-login-form + .signup-page-cta__disclaimer {\\n  margin-top: 1.5em;\\n}\\n\\n// Scoped to the passwordless signup flow so login and regular signup are untouched.\\n@include viewport.until(md) {\\n  .signup-page .signup-body.passwordless-signup {\\n    padding: 1.5rem;\\n\\n    // Drop the heading's own padding so it lines up with the form below it.\\n    .login-welcome-header {\\n      padding: 0;\\n      margin-bottom: 1rem;\\n    }\\n\\n    .code-login-form__email-actions {\\n      align-self: stretch;\\n    }\\n\\n    .code-login-form__continue,\\n    .code-login-form__verify {\\n      width: 100%;\\n    }\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.invites-show {\\n  box-sizing: border-box;\\n  background: var(--secondary);\\n  padding: 1em;\\n\\n  @include viewport.from(sm) {\\n    padding: 2rem 3rem;\\n  }\\n\\n  .success-info p:last-child {\\n    margin-bottom: 0;\\n  }\\n\\n  .invited-by {\\n    display: flex;\\n    align-items: center;\\n    gap: 0.5em;\\n    margin: 1em 0;\\n    font-size: var(--font-down-1);\\n  }\\n\\n  .invited-by p {\\n    margin: 0;\\n  }\\n\\n  .user-info {\\n    align-items: center;\\n    gap: 0.5em;\\n    margin: 0;\\n  }\\n\\n  .invited-by .avatar {\\n    width: 30px;\\n    height: 30px;\\n  }\\n\\n  .create-account__password {\\n    &-info {\\n      display: flex;\\n      justify-content: space-between;\\n    }\\n\\n    &-tip-validation {\\n      display: flex;\\n      flex-direction: column;\\n    }\\n  }\\n\\n  .invitation-cta {\\n    display: flex;\\n    align-items: center;\\n    gap: 1rem;\\n    margin-top: 1rem;\\n\\n    @include viewport.until(sm) {\\n      flex-direction: column;\\n      align-items: flex-start;\\n      margin-top: 2rem;\\n    }\\n  }\\n\\n  .instructions {\\n    color: var(--primary-medium);\\n  }\\n\\n  .disclaimer {\\n    color: var(--primary-medium);\\n    margin-top: 0.5em;\\n  }\\n\\n  .invite-form form {\\n    display: flex;\\n    flex-direction: column;\\n\\n    .input-group {\\n      &.email-input,\\n      &.username-input,\\n      &.name-input.name-required {\\n        order: -1;\\n      }\\n    }\\n  }\\n\\n  @include viewport.until(sm) {\\n    .signup-progress-bar {\\n      margin: 0;\\n    }\\n  }\\n}\\n\\n.invite-page {\\n  background: var(--secondary);\\n}\\n\\n.invites-show,\\n#simple-container .invite-error {\\n  max-width: 500px;\\n  padding: 2rem 3rem;\\n  background: var(--secondary);\\n  margin: 0 auto;\\n\\n  @include viewport.until(md) {\\n    margin: 1em auto 1em auto;\\n    padding: 1rem;\\n  }\\n}\\n\\n#simple-container .invite-error {\\n  .error-info {\\n    text-align: center;\\n  }\\n\\n  .error-image {\\n    text-align: center;\\n    padding-bottom: 1em;\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n// Page-level styles for no_ember layout\\nbody.no-ember:has(.omniauth-confirm) {\\n  --omniauth-bg: light-dark(#{$discourse-bg-light}, #{$discourse-bg-dark});\\n  --omniauth-bg-2: light-dark(\\n    #{$discourse-brand-light},\\n    #{$discourse-brand-800}\\n  );\\n  background: linear-gradient(\\n    180deg,\\n    var(--omniauth-bg-2) 0%,\\n    var(--omniauth-bg) 100%\\n  );\\n  min-height: 100vh;\\n\\n  .d-header {\\n    display: none;\\n  }\\n\\n  #main {\\n    padding: 0;\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    min-height: 100vh;\\n  }\\n\\n  #main-outlet {\\n    padding: 0;\\n    max-width: none;\\n    width: 100%;\\n  }\\n}\\n\\n.omniauth-confirm {\\n  --omniauth-primary: #{$discourse-brand};\\n  --omniauth-primary-hover: #{$discourse-brand-400};\\n  --omniauth-bg: light-dark(#{$discourse-bg-light}, #{$discourse-bg-dark});\\n  --omniauth-bg-2: light-dark(\\n    #{$discourse-brand-light},\\n    #{$discourse-brand-800}\\n  );\\n  --omniauth-card-shadow: 0 10px 30px\\n    light-dark(rgb(123 95 226 / 15%), transparent);\\n  --omniauth-card-radius: 12px;\\n  --omniauth-element-radius: 8px;\\n  --omniauth-button-radius: 6.25em;\\n  --omniauth-text-color: light-dark(var(--primary), #fff);\\n  --omniauth-text-muted: light-dark(var(--primary-medium), #a0a0a0);\\n  display: flex;\\n  flex-direction: column;\\n  align-items: center;\\n  justify-content: center;\\n  text-align: center;\\n  width: 100%;\\n  max-width: 420px;\\n  margin: 0 auto;\\n  padding: var(--space-4);\\n  box-sizing: border-box;\\n\\n  // Vertically center in the viewport\\n  min-height: calc(100vh - 100px);\\n\\n  &__logo {\\n    margin-bottom: var(--space-4);\\n\\n    svg {\\n      width: 56px;\\n      height: 56px;\\n    }\\n  }\\n\\n  &__title {\\n    font-size: var(--font-up-3);\\n    font-weight: 600;\\n    color: var(--omniauth-text-color);\\n    margin: 0 0 var(--space-2) 0;\\n    line-height: var(--line-height-small);\\n  }\\n\\n  &__subtitle {\\n    font-size: var(--font-0);\\n    color: var(--omniauth-text-muted);\\n    margin: 0 0 var(--space-5) 0;\\n    line-height: var(--line-height-large);\\n  }\\n\\n  &__card {\\n    background: var(--secondary);\\n    border-radius: var(--omniauth-card-radius);\\n    box-shadow: var(--omniauth-card-shadow);\\n    padding: var(--space-5);\\n    width: 100%;\\n    box-sizing: border-box;\\n\\n    @include viewport.until(sm) {\\n      padding: var(--space-4);\\n    }\\n  }\\n\\n  &__provider-info {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-3);\\n    padding: var(--space-3);\\n    background: var(--primary-very-low);\\n    border-radius: var(--omniauth-element-radius);\\n    margin-bottom: var(--space-4);\\n    text-align: left;\\n  }\\n\\n  &__provider-icon {\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    width: 44px;\\n    height: 44px;\\n    border-radius: 50%;\\n    background: var(--omniauth-primary);\\n    color: #fff;\\n    flex-shrink: 0;\\n\\n    svg {\\n      width: 22px;\\n      height: 22px;\\n    }\\n  }\\n\\n  &__provider-details {\\n    display: flex;\\n    flex-direction: column;\\n    gap: 2px;\\n    min-width: 0;\\n  }\\n\\n  &__provider-name {\\n    font-weight: 600;\\n    color: var(--primary);\\n    font-size: var(--font-0);\\n  }\\n\\n  &__provider-description {\\n    font-size: var(--font-down-1);\\n    color: var(--primary-medium);\\n  }\\n\\n  &__actions {\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-2);\\n  }\\n\\n  &__continue-btn {\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    gap: var(--space-2);\\n    width: 100%;\\n    padding: 12px var(--space-4);\\n    font-size: var(--font-0);\\n    font-weight: 600;\\n    border-radius: var(--omniauth-button-radius);\\n    cursor: pointer;\\n    transition: background-color 0.15s ease;\\n    box-sizing: border-box;\\n\\n    &.btn-primary {\\n      background: var(--omniauth-primary);\\n      color: #fff;\\n      border: var(--d-button-primary-border);\\n\\n      &:hover,\\n      &:focus {\\n        background: var(--omniauth-primary-hover);\\n      }\\n    }\\n\\n    svg {\\n      width: 16px;\\n      height: 16px;\\n    }\\n  }\\n\\n  &__footer {\\n    margin-top: var(--space-4);\\n    font-size: var(--font-down-1);\\n    color: var(--omniauth-text-muted);\\n\\n    strong {\\n      color: var(--omniauth-text-color);\\n      font-weight: 600;\\n    }\\n  }\\n}\\n",":root {\\n  --jss_header_color: var(--primary-high);\\n  --jss_header_color_highlighted: var(--primary-high);\\n  --jss_header_background: var(--primary-very-low);\\n  --jss_header_background_highlighted: var(--primary-low);\\n  --jss_content_color: var(--primary);\\n  --jss_content_color_highlighted: var(--primary-high);\\n  --jss_content_background: var(--secondary);\\n  --jss_content_background_highlighted: var(--tertiary-very-low);\\n  --jss_menu_background: var(--secondary);\\n  --jss_menu_background_highlighted: var(--secondary-very-high);\\n  --jss_menu_color: var(--primary-medium);\\n  --jss_menu_color_highlighted: var(--primary);\\n  --jss_border_color: var(--primary-low-mid);\\n  --jss_border_color_highlighted: var(--tertiary-high);\\n  --active_color: var(--primary-very-low);\\n  --active-color: var(--active_color);\\n}\\n\\n.jss_worksheet {\\n  border-top: none;\\n  border-left: none;\\n  border-bottom: 1px solid var(--jss_border_color);\\n  border-right: transparent;\\n  background-color: transparent;\\n}\\n\\ntable.jss_worksheet > thead > tr > td {\\n  border-left: 1px solid transparent;\\n  padding: 10px;\\n  font-weight: bold;\\n  border-top: none;\\n  border-right: 1px solid var(--jss_border_color);\\n  border-bottom: 1px solid var(--jss_border_color);\\n  background-color: var(--jss_header_background);\\n\\n  &:first-child {\\n    border-left: none;\\n  }\\n}\\n\\ntable.jss_worksheet > tbody > tr > td {\\n  padding: 8px;\\n  border-left: 1px solid transparent;\\n  border-right: 1px solid var(--jss_border_color);\\n\\n  &:first-child {\\n    border-left: none;\\n    background-color: var(--jss_header_background);\\n  }\\n}\\n\\ntable.jss_worksheet {\\n  border-bottom: 1px solid var(--jss_border_color);\\n}\\n\\n.jcontextmenu.jss_contextmenu hr {\\n  border-color: var(--jss_border_color);\\n}\\n\\n.jss_container .jcontextmenu > div a {\\n  color: var(--jss_menu_color);\\n}\\n\\n.jss_corner {\\n  background-color: var(--tertiary);\\n}\\n\\n.jss_worksheet > tbody > tr > td,\\n.jss_worksheet > thead > tr > td {\\n  border-top: 1px solid var(--jss_border_color);\\n  border-left: 1px solid var(--jss_border_color);\\n  background-color: var(--jss_content_background);\\n  color: var(--jss_content_color);\\n\\n  &:first-child {\\n    border-left: none;\\n  }\\n}\\n\\n.jss_worksheet > thead > tr > td {\\n  border-top: none;\\n}\\n\\n.jss_worksheet > tbody > tr > td:first-child,\\n.jss_worksheet > thead > tr > td {\\n  background-color: var(--jss_header_background);\\n  color: var(--jss_header_color);\\n}\\n\\n.jss_worksheet > thead > tr > td.selected,\\n.jss_worksheet > tbody > tr.selected > td:first-child {\\n  background-color: var(--jss_header_background_highlighted);\\n  color: var(--jss_header_color_highlighted);\\n}\\n\\ntable.jss_worksheet > tbody > tr.selected > td:first-child {\\n  background-color: var(--jss_header_background_highlighted);\\n}\\n\\n.jss_worksheet > tbody > tr > td.jss_cursor a {\\n  color: var(--active-color);\\n}\\n\\n.jss_pagination > div > div {\\n  color: var(--jss_header_color);\\n  background: var(--jss_header_background);\\n  border: 1px solid var(--jss_border_color);\\n}\\n\\n.jss_page,\\n.jss_container input,\\n.jss_container select {\\n  color: var(--jss_header_color);\\n  background: var(--jss_header_background);\\n  border: 1px solid var(--jss_border_color);\\n}\\n\\n.jss_contextmenu.jcontextmenu {\\n  border: 1px solid var(--jss_border_color);\\n  background: var(--jss_menu_background);\\n  color: var(--jss_menu_color);\\n  box-shadow: 0 12px 12px rgb(0, 0, 0, 0.15);\\n}\\n\\n.jcontextmenu > div a {\\n  color: var(--jss_menu_color);\\n}\\n\\n.jcontextmenu > div:not(.contextmenu-line):hover a {\\n  color: var(--jss_menu_color_highlighted);\\n}\\n\\n.jcontextmenu > div:not(.contextmenu-line):hover {\\n  background: var(--jss_menu_background_highlighted);\\n}\\n\\n.jss_dropdown .jdropdown-container,\\n.jss_dropdown .jdropdown-content {\\n  background-color: var(--jss_content_background);\\n  color: var(--jss_content_color);\\n}\\n\\n.jss_dropdown .jdropdown-item {\\n  color: var(--jss_content_color);\\n}\\n\\n.jss_dropdown .jdropdown-item:hover,\\n.jss_dropdown .jdropdown-selected,\\n.jss_dropdown .jdropdown-cursor {\\n  background-color: var(--jss_content_background_highlighted);\\n  color: var(--jss_content_color_highlighted);\\n}\\n\\n.jss_worksheet .jcalendar-content {\\n  background-color: var(--jss_header_background);\\n  color: var(--jss_header_color);\\n}\\n\\n.jss_worksheet .jcalendar-content > table {\\n  background-color: var(--jss_content_background);\\n  color: var(--jss_content_color);\\n}\\n\\n.jss_worksheet .jcalendar-weekday {\\n  background-color: var(--jss_content_background_highlighted);\\n  color: var(--jss_content_color_highlighted);\\n}\\n\\n.jss_worksheet .jcalendar-sunday {\\n  color: var(--jss_header_color);\\n}\\n\\n.jss_worksheet .jcalendar-selected {\\n  background-color: var(--jss_content_background_highlighted);\\n  color: var(--jss_content_color_highlighted);\\n}\\n\\n.jss_toolbar i.jss_toolbar_item {\\n  color: var(--jss_content_color);\\n}\\n\\n.jss_toolbar i.jss_toolbar_item:hover {\\n  background: var(--jss_content_background_highlighted);\\n  color: var(--jss_content_color_highlighted);\\n}\\n\\n.jss_toolbar {\\n  background: var(--jss_header_background);\\n}\\n\\n.jss_content::-webkit-scrollbar-track {\\n  background: var(--jss_background_head);\\n}\\n\\n.jss_content::-webkit-scrollbar-thumb {\\n  background: var(--jss_background_head_highlighted);\\n}\\n\\n.jss_border_main {\\n  border: 1px solid #000;\\n  border-color: var(--jss_border_color_highlighted);\\n}\\n\\n.jss_worksheet .highlight {\\n  background-color: var(--jss_content_background_highlighted);\\n}\\n\\n.jss_worksheet .highlight-bottom {\\n  border-bottom: 1px solid var(--jss_border_color_highlighted);\\n}\\n\\n.jss_worksheet .highlight-right {\\n  border-right: 1px solid var(--jss_border_color_highlighted);\\n}\\n\\n.jss_worksheet .highlight-left {\\n  border-left: 1px solid var(--jss_border_color_highlighted);\\n}\\n\\n.jss_worksheet .highlight-top {\\n  border-top: 1px solid var(--jss_border_color_highlighted);\\n}\\n\\n.jss_worksheet .copying-top {\\n  border-top-color: var(--jss_border_color_highlighted);\\n}\\n\\n.jss_worksheet .copying-right {\\n  border-right-color: var(--jss_border_color_highlighted);\\n}\\n\\n.jss_worksheet .copying-left {\\n  border-left-color: var(--jss_border_color_highlighted);\\n}\\n\\n.jss_worksheet .copying-bottom {\\n  border-bottom-color: var(--jss_border_color_highlighted);\\n}\\n\\n.jss_border_main,\\n.jss_worksheet .highlight-top.highlight-left,\\n.jss_worksheet .highlight-top,\\n.jss_worksheet .highlight-left {\\n  box-shadow: unset;\\n}\\n\\ntable.jss_worksheet > thead > tr > td.selected {\\n  background-color: var(--jss_header_background_highlighted);\\n  color: var(--jss_header_color_highlighted);\\n}\\n\\n// Hides about item in context menu\\n.jcontextmenu > div:not(.contextmenu-line):last-child {\\n  display: none;\\n}\\n\\n.jss_container {\\n  min-width: 100%;\\n  padding: 0;\\n\\n  .jss_content {\\n    min-width: 100%;\\n    padding: 0;\\n\\n    table.jss_worksheet {\\n      min-width: 100%;\\n    }\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.btn-edit-table {\\n  -webkit-touch-callout: none;\\n  user-select: none;\\n}\\n\\n.fullscreen-table-wrapper:hover .fullscreen-table-wrapper__buttons button {\\n  opacity: 100%;\\n}\\n\\n.fullscreen-table-wrapper {\\n  .discourse-no-touch & {\\n    &__buttons {\\n      position: absolute;\\n      top: 0.5rem;\\n      right: 0.5rem;\\n    }\\n  }\\n\\n  .discourse-touch & {\\n    @include viewport.until(xl) {\\n      display: flex;\\n      flex-direction: column-reverse;\\n      padding-bottom: 0.5em;\\n\\n      .open-popup-link {\\n        opacity: 100%;\\n        left: 0;\\n        margin: var(--space-2) 0 0;\\n      }\\n    }\\n  }\\n}\\n",".btn-insert-table {\\n  background: var(--tertiary);\\n  color: var(--secondary);\\n\\n  .d-icon {\\n    color: var(--secondary);\\n  }\\n\\n  .discourse-no-touch & {\\n    &:hover {\\n      background-color: var(--tertiary-hover);\\n      color: var(--secondary);\\n\\n      .d-icon {\\n        color: var(--secondary);\\n      }\\n    }\\n  }\\n}\\n\\n.insert-table-modal {\\n  display: flex;\\n  flex-direction: column;\\n  align-items: flex-start;\\n\\n  .d-modal__container {\\n    --modal-max-width: #{$reply-area-max-width};\\n    width: 100%;\\n    height: 100%;\\n    max-height: unset;\\n    display: grid;\\n    grid-template-rows: auto 1fr auto;\\n    border-radius: 0;\\n  }\\n\\n  .d-modal__body {\\n    padding: 0 4px 0 0;\\n  }\\n\\n  .d-modal__footer {\\n    justify-content: space-between;\\n\\n    .primary-actions {\\n      display: flex;\\n      align-items: center;\\n      gap: 0.5rem;\\n    }\\n\\n    .secondary-actions {\\n      display: flex;\\n      align-items: center;\\n      gap: 0.5rem;\\n\\n      .edit-reason {\\n        display: flex;\\n        align-items: center;\\n        gap: 0.5rem;\\n      }\\n\\n      .btn {\\n        margin-right: 0;\\n      }\\n\\n      input {\\n        margin: 0;\\n      }\\n    }\\n\\n    .secondary-actions .tippy-content {\\n      h4 {\\n        color: var(--primary);\\n      }\\n\\n      li {\\n        margin-block: 0.25rem;\\n        color: var(--primary-high);\\n      }\\n    }\\n  }\\n}\\n","@keyframes draw {\\n  to {\\n    stroke-dashoffset: 0;\\n  }\\n}\\n\\n.post-action-feedback-button {\\n  position: relative;\\n  height: 100%;\\n\\n  &.--activated,\\n  &.--activated:hover {\\n    .d-icon-d-post-share {\\n      color: var(--success);\\n    }\\n  }\\n}\\n\\n.post-action-feedback-svg {\\n  position: absolute;\\n  bottom: 0;\\n  right: 0;\\n  width: 20px;\\n  height: 20px;\\n  display: block;\\n  stroke: var(--success);\\n  opacity: 0;\\n\\n  path {\\n    stroke: var(--success);\\n    stroke-width: 4;\\n    stroke-dasharray: 100;\\n    stroke-dashoffset: 100;\\n    animation: draw 1s forwards;\\n  }\\n}\\n\\n.post-action-feedback-alert {\\n  position: absolute;\\n  top: -1.5rem;\\n  left: 60%;\\n  transform: translateX(-50%);\\n  color: var(--success);\\n  padding: 0.25rem 0.5rem;\\n  white-space: nowrap;\\n  font-size: var(--font-down-2);\\n  opacity: 0;\\n  z-index: calc(z(\\"timeline\\") + 1);\\n}\\n\\n.--transition {\\n  .post-action-feedback-alert,\\n  .post-action-feedback-svg {\\n    transition:\\n      opacity 0.25s,\\n      color 0.25s;\\n  }\\n}\\n\\n.--activated {\\n  .post-action-feedback-alert,\\n  .post-action-feedback-svg {\\n    opacity: 1;\\n  }\\n\\n  .post-action-feedback-alert {\\n    &.-success {\\n      color: var(--success);\\n    }\\n\\n    &.-fail {\\n      color: var(--danger);\\n    }\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.fk-d-menu[class*=\\"toolbar-menu\\"] {\\n  z-index: z(\\"composer\\", \\"dropdown\\");\\n\\n  @include viewport.from(sm) {\\n    // making sure it's only limited in height on floating menu, not mobile menu\\n    &.fk-d-menu {\\n      max-height: 30vh;\\n    }\\n  }\\n\\n  .fk-d-menu__inner-content {\\n    flex-direction: column;\\n\\n    --fade-height: 2.5em;\\n\\n    &::before,\\n    &::after {\\n      content: \\"\\";\\n      position: sticky;\\n      display: block;\\n      flex-shrink: 0;\\n      height: var(--fade-height);\\n      pointer-events: none;\\n      opacity: 0;\\n      z-index: 1;\\n    }\\n\\n    &::before {\\n      top: 0;\\n      margin-bottom: calc(var(--fade-height) * -1);\\n      background: linear-gradient(to top, transparent, var(--secondary));\\n    }\\n\\n    &::after {\\n      bottom: 0;\\n      margin-top: calc(var(--fade-height) * -1);\\n      background: linear-gradient(to bottom, transparent, var(--secondary));\\n    }\\n  }\\n\\n  &.--scroll-top .fk-d-menu__inner-content::before,\\n  &.--scroll-bottom .fk-d-menu__inner-content::after {\\n    opacity: 1;\\n  }\\n\\n  .fullscreen-composer & {\\n    z-index: z(\\"header\\") + 1;\\n  }\\n\\n  // eventho mobile composer shouldnt be used in conjuction with fk-d-menu (floating version), on tablets the possibility unfortunately exists\\n  .discourse-touch & {\\n    z-index: z(\\"mobile-composer\\");\\n  }\\n}\\n\\n.fk-d-menu[class*=\\"toolbar-menu\\"] .dropdown-menu__header {\\n  padding: var(--space-2) 0.35em;\\n  color: var(--primary-medium);\\n  font-size: var(--font-down-1-rem);\\n}\\n\\n.toolbar-menu__options-content,\\n.toolbar-menu__heading-content,\\n.toolbar-menu__list-content {\\n  .dropdown-menu {\\n    .btn {\\n      // The label is block content, so the button counts as icon-only and\\n      // drops the gap after its icon; restore the labelled-button gap.\\n      &.no-text .d-icon {\\n        margin-right: 0.45em;\\n      }\\n\\n      &.--active {\\n        .d-button-label__active-icon {\\n          visibility: visible;\\n        }\\n\\n        // The check owns the trailing slot at rest, even for a shortcut that\\n        // is otherwise always shown.\\n        &:not(:hover, :focus, :focus-visible) .shortcut {\\n          visibility: hidden;\\n        }\\n      }\\n\\n      &:hover,\\n      &:focus,\\n      &:focus-visible {\\n        .shortcut {\\n          visibility: visible;\\n        }\\n\\n        .d-button-label__active-icon {\\n          visibility: hidden;\\n        }\\n      }\\n    }\\n\\n    // The shortcut and the active check share one trailing cell: both are\\n    // laid out so the row reserves their width, and only one is shown.\\n    .d-button-label {\\n      flex: 1;\\n      display: grid;\\n      grid-template-columns: minmax(0, 1fr) auto;\\n      align-items: center;\\n      column-gap: var(--space-4);\\n      min-width: 0;\\n\\n      &__text {\\n        text-align: start;\\n      }\\n\\n      &__active-icon,\\n      .shortcut {\\n        grid-area: 1 / 2;\\n        justify-self: end;\\n        visibility: hidden;\\n      }\\n\\n      .shortcut.--always-visible {\\n        visibility: visible;\\n      }\\n    }\\n  }\\n}\\n\\n.toolbar-menu__heading-content {\\n  .dropdown-menu {\\n    .btn[data-name=\\"heading-1\\"] {\\n      .d-button-label__text,\\n      .d-icon[class*=\\"d-icon-discourse\\"] {\\n        font-size: var(--font-up-2-rem);\\n        font-weight: bold;\\n      }\\n    }\\n\\n    .btn[data-name=\\"heading-2\\"] {\\n      .d-button-label__text,\\n      .d-icon {\\n        font-size: var(--font-up-1-rem);\\n        font-weight: bold;\\n      }\\n    }\\n\\n    .btn[data-name=\\"heading-3\\"] {\\n      .d-button-label__text,\\n      .d-icon {\\n        font-size: var(--font-0);\\n        font-weight: bold;\\n      }\\n    }\\n\\n    .btn[data-name=\\"heading-4\\"] {\\n      .d-button-label__text,\\n      .d-icon {\\n        font-weight: bold;\\n        font-size: var(--font-down-1-rem);\\n      }\\n    }\\n\\n    .btn[data-name=\\"heading-paragraph\\"] {\\n      .d-button-label__text,\\n      .d-icon {\\n        font-size: var(--font-down-1-rem);\\n      }\\n    }\\n\\n    .btn[data-name=\\"heading-small\\"] {\\n      .d-button-label__text,\\n      .d-icon {\\n        font-size: var(--font-down-2-rem);\\n      }\\n    }\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.selected-posts.nested-view__selected-posts {\\n  @include viewport.from(sm) {\\n    width: min(18rem, calc(100vw - 2rem));\\n  }\\n}\\n\\n// PostCookedHtml appends a selection barrier after the final block, so\\n// `:last-child` does not usually match the final cooked paragraph.\\n.nested-view__op-content,\\n.nested-post__content {\\n  .cooked > p {\\n    &:last-child,\\n    &:has(+ .cooked-selection-barrier:last-child) {\\n      margin-bottom: 0;\\n    }\\n  }\\n}\\n\\n// ── Top-level nested view ──────────────────────────────────────────\\n.nested-view {\\n  // Avatar size for the \\"small\\" PostAvatar used in nested posts.\\n  // Also anchors the sticky controls/avatar spacing.\\n  --nested-avatar-size: 24px;\\n  --nested-controls-height: calc(\\n    var(--nested-avatar-size) + var(--space-2) + var(--space-2)\\n  );\\n  --nested-sticky-avatar-top-gap: var(--space-1);\\n  --nested-sticky-avatar-bottom-offset: calc(var(--space-2) + var(--space-1));\\n  background: var(--secondary);\\n  margin: 0 auto;\\n  padding: var(--space-4);\\n  border-radius: var(--d-border-radius-large);\\n  max-width: calc(\\n    var(--topic-body-width) + (var(--topic-body-width-padding) * 2) +\\n      var(--topic-avatar-width)\\n  );\\n\\n  &__header {\\n    margin-bottom: 1em;\\n    padding-bottom: 0.75em;\\n  }\\n\\n  &__title {\\n    margin: 0;\\n    font-size: var(--font-up-4);\\n    line-height: var(--line-height-medium);\\n    overflow-wrap: break-word;\\n\\n    a {\\n      color: var(--primary);\\n    }\\n\\n    .edit-topic__wrapper {\\n      white-space: nowrap;\\n      font-size: var(--font-down-3);\\n      vertical-align: 0.125em;\\n      margin-left: var(--space-1);\\n    }\\n\\n    html.discourse-no-touch & {\\n      .fancy-title {\\n        .edit-topic {\\n          opacity: 0;\\n          transition: opacity 0.15s linear;\\n          background: none;\\n        }\\n\\n        &:hover,\\n        &:focus-visible {\\n          .edit-topic {\\n            opacity: 1;\\n          }\\n        }\\n      }\\n    }\\n  }\\n\\n  .edit-topic-title {\\n    display: flex;\\n    flex-wrap: wrap;\\n    box-sizing: border-box;\\n    gap: 0.5em;\\n    width: 100%;\\n\\n    .edit-title__wrapper {\\n      flex: 1 1 100%;\\n\\n      #edit-title {\\n        width: 100%;\\n        margin: 0;\\n      }\\n    }\\n\\n    .edit-category__wrapper {\\n      flex: 1 1 5%;\\n\\n      .select-kit.combo-box.category-chooser {\\n        width: 100%;\\n        height: 100%;\\n      }\\n    }\\n\\n    .edit-tags__wrapper {\\n      flex: 1 1 33%;\\n\\n      .mini-tag-chooser {\\n        width: 100%;\\n      }\\n    }\\n\\n    .edit-controls {\\n      display: flex;\\n      width: 100%;\\n      gap: 0.5em;\\n    }\\n  }\\n\\n  &__topic-map {\\n    margin-bottom: 0.25em;\\n    padding-bottom: 0.25em;\\n    border-bottom: 0;\\n    max-width: none;\\n\\n    .top-replies {\\n      display: none;\\n    }\\n  }\\n\\n  &__op > &__topic-map {\\n    margin: 0.75em 0 0;\\n    padding: 0.75em 0 0;\\n    border-top: 1px solid var(--primary-low);\\n  }\\n\\n  #topic-footer-buttons.nested-view__topic-actions {\\n    flex-flow: row wrap;\\n    align-items: center;\\n    gap: 0.5em;\\n    max-width: none;\\n    margin-bottom: 0.75em;\\n\\n    .topic-footer-main-buttons {\\n      flex-wrap: wrap;\\n      justify-content: flex-start;\\n    }\\n  }\\n\\n  &__controls {\\n    display: flex;\\n    align-items: center;\\n    justify-content: space-between;\\n    gap: 1em;\\n    margin-bottom: 1em;\\n  }\\n\\n  &:not(.nested-context-view) > &__controls {\\n    position: sticky;\\n    top: var(--header-offset, 0);\\n    z-index: z(\\"timeline\\");\\n    box-sizing: border-box;\\n    min-height: var(--nested-controls-height);\\n    padding: 0.25em 0;\\n    background: var(--secondary);\\n    border-bottom: 1px solid var(--primary-low);\\n  }\\n\\n  &__controls-left {\\n    display: flex;\\n    align-items: center;\\n    gap: 0.85em;\\n    min-width: 0;\\n  }\\n\\n  &__controls-right {\\n    display: flex;\\n    align-items: center;\\n    gap: 1em;\\n    margin-left: auto;\\n  }\\n\\n  &__activity-link.btn {\\n    font-size: var(--font-down-1);\\n    padding: 0.35em 0.55em;\\n    min-height: auto;\\n    line-height: var(--line-height-small);\\n    white-space: nowrap;\\n  }\\n\\n  .nested-sort-selector {\\n    display: flex;\\n    align-items: center;\\n    gap: 0.35em;\\n    margin: 0;\\n    font-size: var(--font-down-1);\\n\\n    &__label {\\n      color: var(--primary-high);\\n    }\\n\\n    &__trigger.btn {\\n      padding: 0.35em 0.55em;\\n      min-height: auto;\\n      line-height: var(--line-height-small);\\n    }\\n\\n    .d-icon {\\n      margin-left: 0.15em;\\n    }\\n  }\\n\\n  &__op {\\n    margin-bottom: 1.5em;\\n    padding: 1em;\\n    border: 1px solid var(--primary-low);\\n    border-radius: var(--d-border-radius);\\n\\n    // Establish a containing block for the absolutely-positioned\\n    // .read-state dot so it anchors to the post-infos right edge\\n    // instead of climbing to a distant ancestor.\\n    .post-infos {\\n      position: relative;\\n\\n      .read-state {\\n        right: -10px;\\n      }\\n    }\\n  }\\n\\n  &__op-article {\\n    .select-posts {\\n      display: flex;\\n      align-items: center;\\n      gap: var(--space-2);\\n      white-space: nowrap;\\n\\n      button {\\n        background-color: var(--primary-low);\\n        color: var(--primary);\\n        box-shadow: var(--shadow-dropdown);\\n      }\\n    }\\n\\n    &.selected .select-posts button.select-post {\\n      background-color: var(--tertiary);\\n      color: var(--secondary);\\n      border-color: var(--tertiary);\\n    }\\n  }\\n\\n  &__op-row {\\n    display: flex;\\n    gap: 0.75em;\\n\\n    .topic-avatar {\\n      border-top: none;\\n      float: none;\\n      width: auto;\\n      padding-top: 0;\\n      height: auto;\\n    }\\n\\n    .topic-meta-data {\\n      padding: 0;\\n      margin-left: 0;\\n      font-size: var(--font-down-1);\\n    }\\n\\n    @include viewport.from(sm) {\\n      > .topic-avatar {\\n        position: sticky;\\n        top: calc(var(--header-offset) + var(--space-3));\\n        align-self: flex-start;\\n        margin-bottom: 25px;\\n      }\\n    }\\n\\n    @include viewport.until(sm) {\\n      display: grid;\\n      grid-template-columns: auto minmax(0, 1fr);\\n      align-items: start;\\n      column-gap: 0.75em;\\n      row-gap: 0.5em;\\n\\n      .nested-view__op-body {\\n        display: contents;\\n      }\\n\\n      .topic-meta-data {\\n        align-self: center;\\n      }\\n\\n      .nested-view__op-content,\\n      .nested-view__op-menu,\\n      .post-links-container {\\n        grid-column: 1 / -1;\\n      }\\n    }\\n  }\\n\\n  &__op-body {\\n    flex: 1;\\n    min-width: 0;\\n  }\\n\\n  &__op-article.is-deleted {\\n    .nested-view__op-content > .cooked {\\n      background-color: var(--danger-low-mid);\\n    }\\n  }\\n\\n  &__op-content {\\n    margin-top: 0.5em;\\n  }\\n\\n  &__op-menu {\\n    margin: 0.25em 0;\\n\\n    .post-action-menu__show-replies {\\n      display: none;\\n    }\\n\\n    // Left-align the post menu in nested view on desktop (mobile keeps the\\n    // Core right-aligned layout). Compounded with .post-menu-area to beat\\n    // the Core `.post-menu-area { padding-left: ... }` rule from\\n    // desktop/topic.scss, which has equal specificity but loads later.\\n    @include viewport.from(sm) {\\n      &.post-menu-area {\\n        padding-left: 0;\\n        margin-top: 1em;\\n      }\\n\\n      nav.post-controls {\\n        justify-content: flex-start;\\n\\n        .actions {\\n          margin-left: 0;\\n        }\\n      }\\n    }\\n  }\\n\\n  &__roots {\\n    display: flex;\\n    flex-direction: column;\\n  }\\n\\n  &__empty {\\n    padding: 2em;\\n    text-align: center;\\n    color: var(--primary-medium);\\n    font-size: var(--font-up-1);\\n  }\\n\\n  &__new-replies {\\n    display: flex;\\n    justify-content: center;\\n    margin-bottom: 1em;\\n  }\\n\\n  &__floating-actions {\\n    position: sticky;\\n    bottom: 0;\\n    z-index: z(\\"header\\") - 2; // below header, above page content and footer-nav\\n    display: flex;\\n    align-items: center;\\n    justify-content: flex-end;\\n    padding-bottom: 1em;\\n    gap: 0.5em;\\n    transition:\\n      transform 0.3s ease,\\n      opacity 0.3s ease,\\n      bottom 0.3s ease;\\n\\n    &.--hidden {\\n      opacity: 0;\\n      pointer-events: none;\\n      transform: translateY(2em);\\n    }\\n\\n    .select-kit.topic-notifications-button .select-kit-header {\\n      box-shadow: var(--shadow-dropdown);\\n      border-radius: 2em;\\n      background: var(--secondary);\\n    }\\n\\n    .topic-admin-menu-button-container .fk-d-menu__trigger {\\n      box-shadow: var(--shadow-dropdown);\\n      border-radius: 2em;\\n      background: var(--secondary);\\n    }\\n  }\\n\\n  &__floating-reply {\\n    box-shadow: var(--shadow-dropdown);\\n  }\\n}\\n\\n// ── Context view ──────────────────────────────────────────────────\\n.nested-context-view {\\n  &__banner {\\n    display: flex;\\n    flex-wrap: wrap;\\n    align-items: center;\\n    gap: 0.5em;\\n    padding: 0.75em 1em;\\n    margin-bottom: 1em;\\n    background: var(--tertiary-very-low);\\n    border: 1px solid var(--tertiary-low);\\n    border-radius: var(--d-border-radius);\\n    font-size: var(--font-down-1);\\n    position: sticky;\\n    top: var(--header-offset, 0);\\n    z-index: 9;\\n  }\\n\\n  &__banner-icon {\\n    color: var(--tertiary);\\n\\n    .d-icon {\\n      width: 1em;\\n      height: 1em;\\n    }\\n  }\\n\\n  &__banner-text {\\n    color: var(--primary-high);\\n    margin-right: auto;\\n  }\\n\\n  &__nav {\\n    display: flex;\\n    gap: 0.5em;\\n    align-items: center;\\n  }\\n}\\n\\n// ── Nested post (single comment in tree) ───────────────────────────\\n.nested-post {\\n  --nested-column-gap: var(--space-2);\\n  --nested-connector-offset: var(--space-2);\\n  --nested-vertical-gap: 0.5em;\\n  --nested-hook-width: calc(var(--nested-avatar-size) / 2);\\n  --nested-line-offset: calc(\\n    var(--nested-connector-offset) + var(--nested-avatar-size) / 2\\n  );\\n  --nested-line-width: 1px;\\n  --nested-line-center-adjust: 0.5px;\\n  --nested-load-more-left-adjust: var(--nested-line-width);\\n  --nested-sticky-avatar-top: calc(\\n    var(--header-offset, 0px) + var(--nested-controls-height) +\\n      var(--nested-sticky-avatar-top-gap)\\n  );\\n\\n  // Grid splits article (row 1) from children (row 2) so the sticky avatar is\\n  // bounded by the post itself and does not continue past the post menu into\\n  // the reply subtree.\\n  display: grid;\\n  grid-template-columns: var(--nested-avatar-size) 1fr;\\n  column-gap: var(--nested-column-gap);\\n  position: relative;\\n\\n  &:not(.--depth-0) {\\n    padding-top: var(--nested-vertical-gap);\\n\\n    // L-shaped connector from parent's depth-line to this post's avatar.\\n    // Extends 4px above the element to bridge the gap between the parent's\\n    // depth-line (grid row 1) and this child (grid row 2).\\n    &::before {\\n      content: \\"\\";\\n      position: absolute;\\n      top: -4px; // overlap parent grid row by 4px to bridge gap\\n      left: calc(-1 * var(--nested-line-offset));\\n      width: var(--nested-hook-width);\\n      height: calc(\\n        var(--nested-vertical-gap) + var(--nested-avatar-size) / 2 + 5px // +5px visually centers the hook on the avatar\\n      );\\n      border-left: var(--nested-line-width) solid var(--primary-low);\\n      border-bottom: var(--nested-line-width) solid var(--primary-low);\\n      border-radius: 0 0 0 12px;\\n      transition: border-color 0.15s ease;\\n    }\\n\\n    // Vertical continuation line connecting to the next sibling.\\n    // Only drawn for non-last children; last child stops at its connector.\\n    // Overlaps the L-connector curve by 4px to prevent thin-line rendering\\n    // caused by border-radius anti-aliasing.\\n    &:not(:last-child)::after {\\n      content: \\"\\";\\n      position: absolute;\\n      left: calc(-1 * var(--nested-line-offset));\\n\\n      // +1px aligns with L-connector bottom; -10px overlaps its border-radius\\n      // curve to prevent subpixel gaps from anti-aliasing\\n      top: calc(\\n        var(--nested-vertical-gap) + var(--nested-avatar-size) / 2 + 1px - 10px\\n      );\\n      bottom: 0;\\n      width: var(--nested-line-width);\\n      background: var(--primary-low);\\n      transition: background-color 0.15s ease;\\n    }\\n  }\\n\\n  // When the parent's depth-line is hovered, highlight child connectors\\n  &:not(.--depth-0).--parent-line-highlighted {\\n    &::before {\\n      border-color: var(--tertiary);\\n    }\\n\\n    &:not(:last-child)::after {\\n      background: var(--tertiary);\\n    }\\n  }\\n\\n  // Transparent overlay covering the parent's line area through this child.\\n  // Provides click-to-collapse and hover-to-highlight for the parent line.\\n  &__parent-line-btn {\\n    position: absolute;\\n    left: calc(-1 * var(--nested-line-offset) - 10px);\\n    top: 0;\\n    bottom: 0;\\n    width: 22px;\\n    background: none;\\n    border: none;\\n    cursor: pointer;\\n    padding: 0;\\n\\n    // Visual feedback is provided by --parent-line-highlighted class (JS).\\n    // Transparent outline ensures visibility in Windows High Contrast Mode.\\n    &:focus-visible {\\n      outline: 2px solid transparent;\\n    }\\n  }\\n\\n  &.--depth-0 {\\n    padding-bottom: 0.75em;\\n    margin-top: 0.5em;\\n\\n    &:first-child {\\n      margin-top: 0;\\n    }\\n  }\\n\\n  // Left column: sticky avatar on top, clickable depth line below.\\n  &__gutter {\\n    grid-column: 1;\\n    grid-row: 1;\\n    margin-bottom: var(--nested-sticky-avatar-bottom-offset);\\n    display: flex;\\n    flex-direction: column;\\n    align-items: center;\\n\\n    .topic-avatar {\\n      position: sticky;\\n      top: var(--nested-sticky-avatar-top);\\n      z-index: 2;\\n      border-top: none;\\n      float: none;\\n      width: auto;\\n      padding-top: 0;\\n      height: auto;\\n\\n      .avatar-flair {\\n        background-size: 12px 12px;\\n        width: 12px;\\n        height: 12px;\\n        right: -3px;\\n        bottom: -2px;\\n      }\\n    }\\n  }\\n\\n  // Depth line sits below the avatar. Extends 1em below the gutter so it\\n  // overlaps the first child's L-connector, masking any subpixel rounding\\n  // offset between grid column 1 (gutter) and column 2 (children).\\n  &__depth-line {\\n    flex: 1;\\n    width: 100%;\\n    position: relative;\\n    padding: 0;\\n    background: none;\\n    border: none;\\n    cursor: pointer;\\n    min-height: var(--space-2);\\n\\n    &::after {\\n      content: \\"\\";\\n      position: absolute;\\n      left: calc(var(--nested-avatar-size) / 2);\\n      top: 6px;\\n      bottom: 0;\\n      width: var(--nested-line-width);\\n      border-radius: var(--nested-line-center-adjust);\\n      background: var(--primary-low);\\n      transition: background-color 0.15s ease;\\n    }\\n\\n    // Transparent outline preserves WHCM focus visibility while\\n    // letting the tertiary line color serve as the primary indicator.\\n    &:focus-visible,\\n    &--highlighted {\\n      outline: 2px solid transparent;\\n\\n      &::after {\\n        background: var(--tertiary);\\n      }\\n\\n      .nested-post__depth-line-icon .d-icon {\\n        color: var(--tertiary);\\n      }\\n    }\\n\\n    @media (hover: hover) {\\n      &:hover {\\n        &::after {\\n          background: var(--tertiary);\\n        }\\n\\n        .nested-post__depth-line-icon .d-icon {\\n          color: var(--tertiary);\\n        }\\n      }\\n    }\\n\\n    &--leaf {\\n      &::after {\\n        opacity: 0.18;\\n        transition:\\n          background-color 0.15s ease,\\n          opacity 0.15s ease;\\n      }\\n\\n      .nested-post__depth-line-icon .d-icon {\\n        opacity: 0.45;\\n        transition:\\n          color 0.15s ease,\\n          opacity 0.15s ease;\\n      }\\n\\n      &:focus-visible,\\n      &.nested-post__depth-line--highlighted {\\n        &::after {\\n          opacity: 1;\\n        }\\n\\n        .nested-post__depth-line-icon .d-icon {\\n          opacity: 1;\\n        }\\n      }\\n    }\\n\\n    // When children are collapsed, turn the vertical line into an L-shape\\n    // that bends toward the \\"N replies\\" expand button\\n    &--collapsed {\\n      &::after {\\n        left: calc(var(--nested-avatar-size) / 2);\\n        bottom: 14px; // aligns L-bend with the \\"N replies\\" expand button\\n        width: calc(var(--nested-avatar-size) / 2);\\n        transform: none;\\n        background: none;\\n        border-left: var(--nested-line-width) solid var(--primary-low);\\n        border-bottom: var(--nested-line-width) solid var(--primary-low);\\n        border-radius: 0 0 0 12px;\\n        transition: border-color 0.15s ease;\\n      }\\n\\n      @media (hover: hover) {\\n        &:hover {\\n          &::after {\\n            background: none;\\n            border-color: var(--tertiary);\\n          }\\n        }\\n      }\\n\\n      &:focus-visible {\\n        outline: 2px solid transparent;\\n\\n        &::after {\\n          background: none;\\n          border-color: var(--tertiary);\\n        }\\n      }\\n    }\\n  }\\n\\n  @media (hover: hover) {\\n    &:hover > .nested-post__gutter .nested-post__depth-line--leaf {\\n      &::after {\\n        opacity: 1;\\n      }\\n\\n      .nested-post__depth-line-icon .d-icon {\\n        opacity: 1;\\n      }\\n    }\\n  }\\n\\n  &__depth-line-icon {\\n    position: absolute;\\n    bottom: 0;\\n    left: calc(50% + var(--nested-line-center-adjust));\\n    transform: translateX(-50%);\\n    z-index: 1;\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    width: 14px;\\n    height: 14px;\\n    padding: 1px;\\n    border-radius: 50%;\\n    background: var(--secondary);\\n\\n    .d-icon {\\n      width: 100%;\\n      height: 100%;\\n      color: var(--primary-low);\\n      transition: color 0.15s ease;\\n    }\\n  }\\n\\n  // display: contents dissolves __main from the grid so its children\\n  // (article + nested-post-children) become grid items directly.\\n  &__main {\\n    display: contents;\\n  }\\n\\n  &__article {\\n    grid-column: 2;\\n    grid-row: 1;\\n    min-width: 0;\\n\\n    .topic-meta-data {\\n      padding: 0;\\n    }\\n\\n    .select-posts {\\n      display: flex;\\n      align-items: center;\\n      gap: var(--space-2);\\n      white-space: nowrap;\\n\\n      button {\\n        background-color: var(--primary-low);\\n        color: var(--primary);\\n        box-shadow: var(--shadow-dropdown);\\n      }\\n    }\\n  }\\n\\n  &.selected &__article .select-posts button.select-post {\\n    background-color: var(--tertiary);\\n    color: var(--secondary);\\n    border-color: var(--tertiary);\\n  }\\n\\n  &__header {\\n    display: flex;\\n    align-items: flex-start;\\n    gap: 0.25em;\\n\\n    // Hide the reply-to line, as the lines between posts already visually indicate the reply structure\\n    .reply-to-tab {\\n      display: none;\\n    }\\n\\n    .topic-meta-data {\\n      display: contents;\\n\\n      .names {\\n        flex: none;\\n        margin-right: 0;\\n      }\\n    }\\n\\n    .post-infos {\\n      order: 1;\\n      margin-inline-start: auto;\\n      font-size: var(--font-down-2);\\n      color: var(--primary-medium);\\n      transform: translateY(1px); // optical alignment with username baseline\\n    }\\n\\n    // Read state was all whacky, this makes it nice.\\n    .read-state {\\n      position: relative;\\n      right: -5px;\\n    }\\n  }\\n\\n  &__op-badge {\\n    display: flex;\\n    align-items: center;\\n    font-size: var(--font-down-2);\\n    line-height: var(--line-height-small);\\n    font-weight: bold;\\n    color: var(--tertiary);\\n    background: var(--tertiary-very-low);\\n    border: 1px solid var(--tertiary-low);\\n    border-radius: var(--d-border-radius);\\n    padding: 0.1em 0.4em;\\n    margin: 0.25em 0.25em 0.25em 0;\\n    transform: translateY(1px);\\n  }\\n\\n  &__pinned-badge {\\n    font-size: var(--font-down-2);\\n    font-weight: bold;\\n    color: var(--success);\\n    background: var(--success-low);\\n    border: 1px solid var(--success-medium);\\n    border-radius: var(--d-border-radius);\\n    padding: 0.1em 0.4em;\\n    line-height: 1;\\n  }\\n\\n  &__content {\\n    margin-top: 0.25em;\\n    margin-bottom: 0.25em;\\n  }\\n\\n  &__menu {\\n    margin: 0.25em 0;\\n\\n    .post-action-menu__show-replies {\\n      display: none;\\n    }\\n\\n    // Left-align the post menu in nested view on desktop (mobile keeps the\\n    // Core right-aligned layout). Compounded with .post-menu-area to beat\\n    // the Core `.post-menu-area { padding-left: ... }` rule from\\n    // desktop/topic.scss, which has equal specificity but loads later.\\n    @include viewport.from(sm) {\\n      &.post-menu-area {\\n        padding-left: 0;\\n        margin-top: 0;\\n      }\\n\\n      nav.post-controls {\\n        justify-content: flex-start;\\n\\n        .actions {\\n          margin-left: 0;\\n        }\\n      }\\n    }\\n  }\\n\\n  &__expand-replies.btn {\\n    color: var(--tertiary);\\n    font-size: var(--font-down-1);\\n\\n    .d-icon {\\n      color: var(--tertiary);\\n    }\\n  }\\n\\n  &__controls {\\n    display: flex;\\n    align-items: center;\\n    gap: 0.75em;\\n    font-size: var(--font-down-1);\\n  }\\n\\n  &__collapsed-bar {\\n    grid-column: 2;\\n    grid-row: 1;\\n    display: flex;\\n    align-items: center;\\n    gap: 0.35em;\\n    padding: 0.15em 0.25em;\\n    border: none;\\n    background: none;\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1);\\n    cursor: pointer;\\n    border-radius: var(--d-border-radius);\\n    white-space: nowrap;\\n    align-self: center;\\n\\n    &:hover {\\n      color: var(--tertiary);\\n    }\\n  }\\n\\n  &__collapsed-separator {\\n    color: var(--primary-low-mid);\\n  }\\n\\n  &__collapsed-username {\\n    color: var(--primary-high-or-secondary-low);\\n  }\\n\\n  &__collapsed-reply-count {\\n    color: var(--tertiary);\\n  }\\n\\n  &__placeholder {\\n    grid-column: 2;\\n    grid-row: 1;\\n\\n    &--deleted {\\n      padding: 0 0 2em;\\n      margin-top: -0.35em;\\n    }\\n\\n    &--ignored {\\n      min-height: var(--nested-avatar-size);\\n      display: flex;\\n      align-items: center;\\n      padding-bottom: 1em;\\n    }\\n  }\\n\\n  &__placeholder-actions {\\n    display: flex;\\n    align-items: center;\\n    gap: 0.25em;\\n  }\\n\\n  &__placeholder-label {\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1);\\n    font-style: italic;\\n  }\\n\\n  &__placeholder-reveal {\\n    background-color: var(--danger-low-mid);\\n    padding: 0.5em;\\n    width: 100%;\\n  }\\n\\n  &__placeholder-reveal-header {\\n    display: flex;\\n    align-items: center;\\n    gap: 0.5em;\\n    margin-bottom: 0.5em;\\n\\n    .topic-meta-data {\\n      display: contents;\\n    }\\n\\n    .post-infos {\\n      margin-left: auto;\\n      order: 1;\\n    }\\n  }\\n\\n  &--whisper {\\n    .nested-post__content .cooked {\\n      font-style: italic;\\n      color: var(--primary-medium);\\n    }\\n  }\\n\\n  &__placeholder-avatar {\\n    position: sticky;\\n    top: var(--nested-sticky-avatar-top);\\n    z-index: 2;\\n    width: var(--nested-avatar-size);\\n    height: var(--nested-avatar-size);\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    color: var(--primary-low-mid);\\n\\n    .d-icon {\\n      width: 14px;\\n      height: 14px;\\n    }\\n\\n    &--reveal {\\n      background: transparent;\\n      border: none;\\n      padding: 0;\\n      cursor: pointer;\\n      border-radius: 50%;\\n      transition:\\n        background-color 0.15s ease,\\n        color 0.15s ease;\\n\\n      &:hover:not(:disabled),\\n      &:focus-visible {\\n        background-color: var(--primary-low);\\n        color: var(--primary);\\n      }\\n\\n      &:disabled {\\n        cursor: default;\\n      }\\n    }\\n  }\\n\\n  &__continue-link {\\n    color: var(--tertiary);\\n    font-weight: bold;\\n  }\\n}\\n\\n// ── Children container ─────────────────────────────────────────────\\n.nested-post-children {\\n  grid-column: 2;\\n  grid-row: 2;\\n\\n  &__load-more {\\n    margin: 0.5em 0;\\n    color: var(--tertiary);\\n    font-size: var(--font-down-1);\\n    position: relative;\\n\\n    // L-shaped hook connecting the sibling continuation line to this button\\n    &::before {\\n      content: \\"\\";\\n      position: absolute;\\n      left: calc(\\n        -1 * var(--nested-line-offset) - var(--nested-load-more-left-adjust) +\\n          1px\\n      );\\n      top: -1em;\\n      height: calc(50% + 1em);\\n      width: var(--nested-line-offset);\\n      border-left: var(--nested-line-width) solid var(--primary-low);\\n      border-bottom: var(--nested-line-width) solid var(--primary-low);\\n      border-radius: 0 0 0 12px;\\n      transition: border-color 0.15s ease;\\n    }\\n\\n    // When the parent's depth-line is hovered, highlight this hook to match\\n    // the sibling continuation lines above it.\\n    &.--parent-line-highlighted::before {\\n      border-color: var(--tertiary);\\n    }\\n  }\\n}\\n\\n// ── Deep-link highlight animation ──────────────────────────────────\\n.nested-post--highlighted {\\n  animation: nested-post-highlight 2s ease-out;\\n}\\n\\n@keyframes nested-post-highlight {\\n  0% {\\n    background-color: var(--tertiary-low);\\n  }\\n\\n  100% {\\n    background-color: transparent;\\n  }\\n}\\n\\n// ── Activity log modal ────────────────────────────────────────────\\n.nested-activity-log-modal {\\n  --activity-log-row-padding-block: var(--space-3);\\n  --activity-log-row-gap: var(--space-2);\\n  --activity-log-icon-color: var(--primary-medium);\\n  --activity-log-description-color: var(--primary-700);\\n\\n  &__list {\\n    @include unstyled-list;\\n  }\\n\\n  &__item {\\n    &:not(:last-child) {\\n      border-bottom: 1px solid var(--primary-low);\\n    }\\n\\n    &.--synthetic {\\n      display: flex;\\n      align-items: flex-start;\\n      gap: var(--activity-log-row-gap);\\n      padding-block: var(--activity-log-row-padding-block);\\n      color: var(--activity-log-description-color);\\n    }\\n  }\\n\\n  &__post {\\n    .small-action {\\n      align-items: stretch;\\n    }\\n\\n    .small-action .topic-avatar {\\n      align-items: flex-start;\\n      width: auto;\\n      padding: var(--activity-log-row-padding-block) 0 0;\\n      border-top: 0;\\n\\n      .d-icon {\\n        font-size: var(--font-0);\\n        color: var(--activity-log-icon-color);\\n      }\\n    }\\n\\n    .small-action .small-action-desc {\\n      flex: 1;\\n      width: auto;\\n      padding: 0 0 var(--activity-log-row-padding-block)\\n        var(--activity-log-row-gap);\\n      border-top: 0;\\n      color: var(--activity-log-description-color);\\n    }\\n\\n    .small-action .small-action-contents,\\n    .small-action .small-action-buttons {\\n      padding-top: var(--activity-log-row-padding-block);\\n    }\\n\\n    .small-action .small-action-custom-message {\\n      font-size: var(--font-down-1);\\n    }\\n  }\\n\\n  &__icon {\\n    flex-shrink: 0;\\n    color: var(--activity-log-icon-color);\\n    margin-top: 0.15em;\\n  }\\n\\n  &__content {\\n    flex: 1;\\n    min-width: 0;\\n  }\\n\\n  &__desc {\\n    display: flex;\\n    align-items: center;\\n    gap: 0.35em;\\n    flex-wrap: wrap;\\n  }\\n\\n  &__message {\\n    margin-top: 0.35em;\\n    font-size: var(--font-down-1);\\n    color: var(--primary-high);\\n  }\\n\\n  &__empty {\\n    color: var(--primary-medium);\\n    text-align: center;\\n    padding: 1em 0;\\n  }\\n\\n  &__load-more {\\n    display: flex;\\n    justify-content: center;\\n    padding-top: var(--space-3);\\n  }\\n}\\n\\n// ── Mobile layout ─────────────────────────────────────────────────\\n// Reddit-style mobile redesign: avatars move inline into the post\\n// header (handled via JS template conditional), the gutter becomes a\\n// narrow column holding only vertical depth-lines that run the full\\n// height of each subtree for continuous visual hierarchy.\\n@include viewport.until(sm) {\\n  // ── View-level overrides ──\\n  .nested-view {\\n    padding: 0.5em;\\n    border-radius: 0;\\n  }\\n\\n  .nested-view.-mobile-focused {\\n    .nested-view__header {\\n      margin-bottom: 0;\\n    }\\n  }\\n\\n  .nested-view__title {\\n    font-size: var(--font-up-3);\\n  }\\n\\n  .nested-view__controls {\\n    flex-wrap: wrap;\\n    background: var(--secondary);\\n    margin-left: -0.5em;\\n    margin-right: -0.5em;\\n    padding: 0.5em;\\n    margin-bottom: 0;\\n  }\\n\\n  .nested-view__controls-left {\\n    flex-wrap: wrap;\\n  }\\n\\n  // Full-width cards: break out of container side padding\\n  .nested-view__op,\\n  .nested-view__roots {\\n    margin-left: -0.5em;\\n    margin-right: -0.5em;\\n  }\\n\\n  .nested-view__topic-map {\\n    background: var(--secondary);\\n    margin-left: -0.5em;\\n    margin-right: -0.5em;\\n    padding: 0.5em;\\n    margin-bottom: 0;\\n  }\\n\\n  // OP rendered as a full-width white card\\n  .nested-view__op {\\n    padding: 0.5em;\\n    background: var(--secondary);\\n    border: none;\\n    border-radius: 0;\\n    margin-bottom: 0;\\n  }\\n\\n  .nested-view__op-row {\\n    gap: 0.5em;\\n  }\\n\\n  // Grey gap between root-level thread cards (and after OP)\\n  .nested-view__roots,\\n  .nested-view__mobile-focus {\\n    gap: 0.5em;\\n  }\\n\\n  .nested-view__mobile-focus {\\n    --nested-mobile-ancestor-avatar-size: 24px;\\n    display: flex;\\n    flex-direction: column;\\n    gap: 0;\\n    margin-left: -0.5em;\\n    margin-right: -0.5em;\\n  }\\n\\n  .nested-view__mobile-ancestors {\\n    display: flex;\\n    flex-direction: column;\\n    background: var(--secondary);\\n    border-bottom: 1px solid var(--primary-low);\\n  }\\n\\n  .nested-view__mobile-focus-back,\\n  .nested-view__mobile-ancestor {\\n    display: flex;\\n    align-items: center;\\n    gap: 0.5em;\\n    width: 100%;\\n    min-width: 0;\\n    min-height: calc(var(--nested-mobile-ancestor-avatar-size) + 1em);\\n    padding: 0.5em;\\n    color: var(--primary-medium);\\n    background: var(--secondary);\\n    border: 0;\\n    text-align: left;\\n    cursor: pointer;\\n\\n    .d-icon {\\n      flex: 0 0 auto;\\n      width: 0.75em;\\n      color: var(--primary-medium);\\n    }\\n\\n    .topic-avatar {\\n      flex: 0 0 auto;\\n      border-top: 0;\\n      padding: 0;\\n    }\\n\\n    &:focus-visible {\\n      outline: 2px solid var(--tertiary);\\n      outline-offset: -2px;\\n    }\\n  }\\n\\n  .nested-view__mobile-ancestor {\\n    border-top: 1px solid var(--primary-low);\\n    font-size: var(--font-down-1);\\n    min-height: calc(var(--nested-mobile-ancestor-avatar-size) + 0.75em);\\n    padding-block: 0.375em;\\n  }\\n\\n  .nested-view__mobile-ancestor-avatar {\\n    display: flex;\\n    flex: 0 0 var(--nested-mobile-ancestor-avatar-size);\\n    align-items: center;\\n    justify-content: center;\\n    width: var(--nested-mobile-ancestor-avatar-size);\\n    height: var(--nested-mobile-ancestor-avatar-size);\\n\\n    .avatar {\\n      width: var(--nested-mobile-ancestor-avatar-size);\\n      height: var(--nested-mobile-ancestor-avatar-size);\\n      max-width: var(--nested-mobile-ancestor-avatar-size);\\n      max-height: var(--nested-mobile-ancestor-avatar-size);\\n    }\\n  }\\n\\n  .nested-view__mobile-ancestor-meta {\\n    display: flex;\\n    align-items: baseline;\\n    gap: 0.5em;\\n    min-width: 0;\\n  }\\n\\n  .nested-view__mobile-ancestor-username {\\n    flex: 0 0 auto;\\n    color: var(--primary-high-or-secondary-low);\\n    font-weight: bold;\\n  }\\n\\n  .nested-view__mobile-ancestor-excerpt {\\n    min-width: 0;\\n    overflow: hidden;\\n    color: var(--primary-medium);\\n    text-overflow: ellipsis;\\n    white-space: nowrap;\\n  }\\n\\n  .nested-view__mobile-focused-branch {\\n    display: flex;\\n    flex-direction: column;\\n    margin-top: 0.5em;\\n  }\\n\\n  @media (prefers-reduced-motion: no-preference) {\\n    .nested-view__mobile-focus {\\n      overflow-x: clip;\\n\\n      &.--forward {\\n        .nested-view__mobile-focused-branch {\\n          animation: nested-mobile-slide-forward 180ms ease-out both;\\n        }\\n\\n        .nested-view__mobile-ancestors,\\n        .nested-view__mobile-focus-back {\\n          animation: nested-mobile-fade-in 160ms ease-out both;\\n        }\\n      }\\n\\n      &.--back {\\n        .nested-view__mobile-focused-branch {\\n          animation: nested-mobile-slide-back 180ms ease-out both;\\n        }\\n\\n        .nested-view__mobile-ancestors,\\n        .nested-view__mobile-focus-back {\\n          animation: nested-mobile-fade-in 140ms ease-out both;\\n        }\\n      }\\n    }\\n\\n    .nested-post-children {\\n      animation: nested-mobile-replies-in 160ms ease-out both;\\n    }\\n  }\\n\\n  // Strip L-hook connectors on load-more buttons\\n  .nested-post-children__load-more::before {\\n    content: none;\\n  }\\n\\n  // ── Individual nested post overrides ──\\n  // Gutter stays wide enough for the avatar so sticky avatars remain attached\\n  // to the mobile rail, while children remain indented in the content column.\\n  .nested-post {\\n    --nested-line-gutter: var(--nested-avatar-size);\\n    --nested-column-gap: var(--space-1);\\n    --nested-mobile-line-offset: calc(var(--nested-line-gutter) / 2);\\n    --nested-line-center-adjust: var(--nested-line-width);\\n    --nested-mobile-line-nudge: calc(-1 * var(--space-1));\\n    --nested-mobile-line-start: calc(var(--nested-avatar-size) + 6px);\\n    grid-template-columns: var(--nested-line-gutter) 1fr;\\n    column-gap: var(--nested-column-gap);\\n\\n    // Tighter vertical spacing between siblings\\n    --nested-vertical-gap: 0.25em;\\n\\n    // Keep the gutter bounded to the post row on mobile too. The depth-line\\n    // remains available as the collapse target for this post, but the sticky\\n    // avatar stops with the post instead of following the entire child subtree.\\n    > .nested-post__gutter {\\n      grid-row: 1;\\n      position: relative;\\n      z-index: 1;\\n      pointer-events: none;\\n\\n      .topic-avatar,\\n      .nested-post__placeholder-avatar {\\n        pointer-events: auto;\\n      }\\n    }\\n\\n    // Depth-line: vertical bar under the avatar, no decorative hooks.\\n    > .nested-post__gutter .nested-post__depth-line {\\n      position: absolute;\\n      top: var(--nested-mobile-line-start);\\n      bottom: 0;\\n      left: var(--nested-mobile-line-nudge);\\n      min-height: 0;\\n      pointer-events: auto;\\n\\n      &::after {\\n        left: calc(\\n          var(--nested-mobile-line-offset) - var(--nested-line-center-adjust)\\n        );\\n        top: 0;\\n        bottom: 0;\\n      }\\n\\n      // Override the desktop L-bend on collapsed lines — straight bar\\n      &--collapsed::after {\\n        border: none;\\n        background: var(--primary-low);\\n        width: var(--nested-line-width);\\n        border-radius: 0;\\n        left: calc(\\n          var(--nested-mobile-line-offset) - var(--nested-line-center-adjust)\\n        );\\n        bottom: 0;\\n      }\\n    }\\n\\n    // Hide the collapse icon — tapping the line itself collapses\\n    .nested-post__depth-line-icon {\\n      display: none;\\n    }\\n\\n    .nested-post__collapsed-bar {\\n      padding-inline: 0;\\n    }\\n\\n    // Mobile strips desktop connector hooks, so the desktop padding used to\\n    // make room for those hooks must not shift the post's internal grid math.\\n    &:not(.--depth-0) {\\n      padding-top: 0;\\n\\n      &::before,\\n      &:not(:last-child)::after {\\n        content: none;\\n      }\\n    }\\n\\n    &:not(.--depth-0) + &:not(.--depth-0) {\\n      margin-top: var(--nested-vertical-gap);\\n    }\\n\\n    // No hover interaction on touch — depth-line handles collapse\\n    > .nested-post__parent-line-btn {\\n      display: none;\\n    }\\n\\n    // Root threads rendered as full-width white cards.\\n    // padding-left: 0 so the gutter starts at the card edge (= viewport\\n    // edge after negative margins), giving consistent line spacing.\\n    &.--depth-0 {\\n      background: var(--secondary);\\n      border-radius: 0;\\n      padding: 0.5em 0.5em 0.5em 0;\\n      margin-top: 0;\\n    }\\n\\n    // Compact post headers\\n    .nested-post__header {\\n      flex-wrap: wrap;\\n      gap: var(--space-2);\\n\\n      .topic-meta-data {\\n        margin-left: 0;\\n      }\\n    }\\n\\n    .nested-post__content {\\n      overflow-x: auto;\\n    }\\n  }\\n}\\n\\n@keyframes nested-mobile-slide-forward {\\n  from {\\n    opacity: 0;\\n    transform: translateX(18px);\\n  }\\n\\n  to {\\n    opacity: 1;\\n    transform: translateX(0);\\n  }\\n}\\n\\n@keyframes nested-mobile-slide-back {\\n  from {\\n    opacity: 0;\\n    transform: translateX(-18px);\\n  }\\n\\n  to {\\n    opacity: 1;\\n    transform: translateX(0);\\n  }\\n}\\n\\n@keyframes nested-mobile-replies-in {\\n  from {\\n    opacity: 0;\\n    transform: translateY(-6px);\\n  }\\n\\n  to {\\n    opacity: 1;\\n    transform: translateY(0);\\n  }\\n}\\n\\n@keyframes nested-mobile-fade-in {\\n  from {\\n    opacity: 0;\\n  }\\n\\n  to {\\n    opacity: 1;\\n  }\\n}\\n\\nhtml.footer-nav-visible {\\n  .nested-view__floating-actions {\\n    bottom: calc(var(--footer-nav-height) + env(safe-area-inset-bottom) + 1em);\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n:where(.uc-enable-composer-redesign) {\\n  // flat to match the rest of the bar, aligned to the content gutter\\n  #reply-control .reply-to .composer-actions-trigger {\\n    padding-inline-start: 0;\\n    background: transparent;\\n    border-color: transparent;\\n\\n    .d-button-label {\\n      font-weight: 600;\\n    }\\n  }\\n\\n  #reply-control {\\n    // the redesigned grippie is taller than the height the default layout\\n    // reserves for it, so size the reply area with flex instead\\n    .grippie ~ .reply-area {\\n      flex: 1 1 auto;\\n      height: auto;\\n      min-height: 0;\\n    }\\n\\n    // structure properly when :where is gone\\n    &.hide-preview .d-editor-container {\\n      grid-template-columns: 1fr;\\n      grid-template-areas:\\n        \\"fields\\"\\n        \\"editor\\";\\n    }\\n  }\\n\\n  .grippie {\\n    padding-block: var(--space-1);\\n    border-top-left-radius: var(--d-border-radius-large);\\n    border-top-right-radius: var(--d-border-radius-large);\\n  }\\n\\n  .reply-to {\\n    padding: var(--space-2) var(--space-4);\\n    margin: 0 !important;\\n    border-bottom: 1px solid var(--primary-low);\\n  }\\n\\n  .reply-area {\\n    container-type: inline-size;\\n    padding: 0 !important;\\n  }\\n\\n  .composer-controls {\\n    .btn {\\n      font-size: var(--font-down-1-rem);\\n    }\\n  }\\n\\n  #reply-control .title-and-category {\\n    padding: 0 !important;\\n    width: 100% !important;\\n    gap: 0 !important;\\n    border-bottom: 1px solid var(--primary-low);\\n    flex-wrap: nowrap !important;\\n\\n    .user-selector {\\n      margin: 0 !important;\\n    }\\n  }\\n\\n  .category-input,\\n  .user-selector {\\n    border-right: 1px solid var(--primary-low);\\n\\n    @include viewport.until(sm) {\\n      flex-grow: 1;\\n    }\\n  }\\n\\n  .tags-input {\\n    &:not(:last-child) {\\n      border-right: 1px solid var(--primary-low);\\n    }\\n\\n    @include viewport.until(sm) {\\n      flex-grow: 0 !important;\\n    }\\n\\n    @include viewport.until(sm) {\\n      .select-kit {\\n        .formatted-selection {\\n          display: none !important;\\n        }\\n      }\\n    }\\n\\n    .select-kit-header-wrapper {\\n      gap: var(--space-1);\\n\\n      .formatted-selection {\\n        color: var(--primary-medium);\\n      }\\n\\n      .d-icon-plus {\\n        @include viewport.until(sm) {\\n          display: none;\\n        }\\n      }\\n\\n      .d-icon-tag {\\n        color: var(--primary-low-mid) !important;\\n      }\\n\\n      .multi-select-header__selected-count {\\n        @include viewport.from(sm) {\\n          display: none;\\n        }\\n      }\\n    }\\n\\n    .has-selection {\\n      .select-kit-header-wrapper {\\n        .formatted-selection {\\n          color: var(--primary-high);\\n        }\\n\\n        .d-icon-tag {\\n          color: var(--tertiary) !important;\\n        }\\n      }\\n    }\\n  }\\n\\n  .category-input,\\n  .tags-input,\\n  .user-selector {\\n    margin: 0 !important;\\n    max-width: unset !important;\\n    width: 50% !important;\\n    box-sizing: border-box;\\n\\n    @include viewport.until(sm) {\\n      width: auto !important;\\n    }\\n\\n    .category-chooser.is-expanded,\\n    .mini-tag-chooser.is-expanded,\\n    .user-chooser.is-expanded {\\n      .select-kit-header {\\n        outline: 0 !important;\\n      }\\n    }\\n\\n    .select-kit.combo-box .select-kit-header,\\n    .select-kit.multi-select .multi-select-header {\\n      border: 0;\\n      padding: var(--space-3) var(--space-4);\\n      border-radius: 0;\\n\\n      &:active {\\n        border: 0;\\n        outline: 0;\\n      }\\n\\n      .d-icon:not(.badge-category *) {\\n        font-size: var(--font-down-1-rem);\\n        color: var(--primary-medium);\\n      }\\n    }\\n  }\\n\\n  // TODO move to plugin css when UC is removed\\n  .showing-ai-suggestions #reply-title {\\n    padding-right: calc(var(--space-7) + 27px);\\n  }\\n\\n  .title-input {\\n    justify-content: space-between;\\n    align-items: center;\\n    border-bottom: 1px solid var(--primary-low);\\n\\n    #reply-title {\\n      border: 0;\\n      padding: var(--space-4);\\n      font-weight: 600;\\n      margin-bottom: 0 !important;\\n      padding-bottom: var(--space-3) !important;\\n      padding-right: var(--space-3) !important;\\n      flex-basis: unset !important;\\n\\n      &::placeholder {\\n        color: var(--primary-medium);\\n      }\\n\\n      &:focus {\\n        outline: 0;\\n      }\\n    }\\n\\n    // TODO move to plugin css when UC is removed\\n    .suggest-titles-button {\\n      position: relative;\\n      bottom: unset !important;\\n      right: unset !important;\\n      transform: none !important;\\n      margin-inline-end: var(--space-3);\\n    }\\n  }\\n\\n  #reply-control .d-editor-textarea-wrapper {\\n    --composer-slide-easing: cubic-bezier(0.2, 0, 0, 1);\\n    border: 0;\\n    border-radius: 0; // core overrule\\n\\n    // padding and border-radius must animate in lockstep with margin,\\n    // otherwise the text counter-jumps when the focus state toggles\\n    transition:\\n      margin 250ms var(--composer-slide-easing),\\n      padding 250ms var(--composer-slide-easing),\\n      border-radius 250ms var(--composer-slide-easing),\\n      box-shadow 250ms ease;\\n\\n    @media (prefers-reduced-motion: reduce) {\\n      transition: none;\\n    }\\n\\n    &:focus,\\n    &.in-focus {\\n      outline: none;\\n      border: 0;\\n    }\\n  }\\n\\n  #reply-control.has-composer-fields .d-editor-textarea-wrapper {\\n    &:focus,\\n    &:focus-within,\\n    &.in-focus {\\n      @include viewport.until(sm) {\\n        margin-top: calc(\\n          (\\n              var(--composer-fields-height, 0px) +\\n                (var(--header-offset, 0px) / 3)\\n            ) *\\n            -1\\n        );\\n        z-index: z(\\"composer\\", \\"dropdown\\") + 1;\\n        box-shadow: 0 -12px 12px 0 rgb(var(--primary-rgb), 0.15);\\n        border-top-left-radius: var(--d-border-radius-large);\\n        border-top-right-radius: var(--d-border-radius-large);\\n        padding-top: var(--space-4);\\n\\n        &::before {\\n          content: \\"\\";\\n          position: absolute;\\n          inset-block-start: var(--space-2);\\n          inset-inline-start: 50%;\\n          transform: translateX(-50%);\\n          width: 15vw;\\n          height: 5px;\\n          background: var(--primary-medium);\\n          border-radius: var(--d-border-radius-pill);\\n        }\\n      }\\n    }\\n  }\\n\\n  @include viewport.until(sm) {\\n    #reply-control.has-composer-fields\\n      .reply-area:has(.d-editor-textarea-wrapper.in-focus)\\n      .reply-to {\\n      pointer-events: none;\\n    }\\n  }\\n\\n  .d-editor-input {\\n    padding-inline: var(--space-4) !important;\\n\\n    &:focus-visible {\\n      outline: 0;\\n    }\\n  }\\n\\n  .wmd-controls:not(.toolbar-visible)\\n    ~ .composer-footer\\n    .d-editor-button-bar__wrap {\\n    display: none;\\n  }\\n\\n  #reply-control .d-editor-container {\\n    display: grid;\\n    grid-template-columns: 1fr 1fr;\\n    grid-template-rows: min-content 1fr;\\n    grid-template-areas:\\n      \\"fields fields\\"\\n      \\"editor preview\\";\\n\\n    &.--rich-editor-enabled {\\n      grid-template-columns: 1fr;\\n      grid-template-areas:\\n        \\"fields\\"\\n        \\"editor\\";\\n    }\\n\\n    .composer-fields {\\n      grid-area: fields;\\n      min-width: 0;\\n\\n      @include viewport.until(sm) {\\n        max-width: 100vw;\\n        box-sizing: border-box;\\n      }\\n    }\\n\\n    .d-editor-textarea-column {\\n      grid-area: editor;\\n      min-height: 0;\\n    }\\n\\n    .d-editor-preview-wrapper {\\n      grid-area: preview;\\n    }\\n  }\\n\\n  // clean up selector once the uc- body class is no longer in the way\\n  .show-preview .d-editor-container.--markdown-editor-enabled {\\n    .d-editor-preview-wrapper {\\n      border-left: 1px solid var(--primary-low);\\n      margin: 0;\\n      padding: var(--space-2) var(--space-4);\\n    }\\n  }\\n\\n  .composer-footer {\\n    display: flex;\\n    align-items: center;\\n    flex-wrap: no