ggle-switch__left-icon,\\n      .composer-toggle-switch__right-icon {\\n        font-size: var(--font-down-1-rem);\\n      }\\n    }\\n\\n    .composer-toggle-switch {\\n      margin-left: 0;\\n    }\\n  }\\n\\n  @include viewport.until(sm) {\\n    .reply-area {\\n      background: var(--secondary);\\n      padding: 0 0 max(env(safe-area-inset-bottom), var(--space-2)) !important;\\n\\n      html.keyboard-visible & {\\n        padding-bottom: var(--space-2) !important;\\n      }\\n    }\\n\\n    .reply-to {\\n      padding: var(--space-1) var(--space-3);\\n    }\\n  }\\n\\n  // PM specific removals/overrules\\n  #reply-control.private-message .with-tags .title-input {\\n    max-width: unset;\\n  }\\n}\\n",":where(.uc-modernize-foundation-theme) {\\n  // New Variables\\n  --webkit-font-smoothing: antialiased;\\n  --welcome-banner-text-align: center;\\n  --welcome-banner-search-menu-margin-inline: auto;\\n  -webkit-font-smoothing: var(--webkit-font-smoothing);\\n\\n  // Misc\\n  --d-nav-underline-height: var(--space-half);\\n  --d-input-border: 1px solid var(--primary-300);\\n  --input-border-color: var(--primary-300);\\n}\\n",":where(.uc-modernize-foundation-theme) .welcome-banner {\\n  &__wrap .search-menu {\\n    align-items: center;\\n    margin-inline: var(--welcome-banner-search-menu-margin-inline);\\n  }\\n\\n  &__subheader {\\n    font-size: var(--font-0-rem);\\n  }\\n\\n  &__title {\\n    font-size: var(--font-up-5);\\n    font-weight: 500;\\n    text-align: var(--welcome-banner-text-align);\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n:where(.uc-modernize-foundation-theme) {\\n  --d-button-default-bg-color: var(--secondary);\\n  --d-button-default-border: 1px solid var(--primary-300);\\n  --d-button-default-border--hover: 1px solid var(--primary-400);\\n  --d-button-default-bg-color--hover: var(--primary-200);\\n  --d-button-default-text-color--hover: var(--primary);\\n  --d-button-default-icon-color--hover: var(--primary);\\n  --d-button-default-text-color: 