btn,\\n    .shift-down-value-btn {\\n      .discourse-no-touch & {\\n        display: none;\\n      }\\n      margin-inline: 0.25em;\\n    }\\n\\n    &:hover {\\n      .shift-up-value-btn,\\n      .shift-down-value-btn {\\n        display: block;\\n      }\\n    }\\n  }\\n\\n  .values {\\n    margin-bottom: 0.5em;\\n  }\\n}\\n\\n.emoji-value-list {\\n  margin-left: 0;\\n\\n  .emoji-details {\\n    @include form-item-sizing;\\n    display: flex;\\n    align-items: center;\\n    min-height: 30px;\\n    color: var(--primary);\\n    border-color: var(--primary-low);\\n    padding-left: 10px;\\n    padding-right: 10px;\\n\\n    .emoji-name {\\n      margin-left: 0.5em;\\n\\n      @include ellipsis;\\n    }\\n\\n    &:not(.can-edit) {\\n      pointer-events: none;\\n      background-color: var(--primary-very-low);\\n    }\\n  }\\n\\n  .value-input {\\n    flex-direction: row;\\n  }\\n}\\n\\n.value .add-emoji-button {\\n  display: block;\\n  background-color: var(--primary-low);\\n  border: none;\\n}\\n\\n.value .add-value-btn,\\n.shift-up-value-btn,\\n.shift-down-value-btn {\\n  margin-right: 0 !important;\\n  margin-left: 0.25em;\\n\\n  @include value-btn;\\n}\\n\\n.secret-value-list {\\n  .value {\\n    flex-flow: row wrap;\\n    margin-left: -0.25em;\\n    margin-top: -0.125em;\\n\\n    .new-value-input {\\n      flex: 1 0 0px;\\n      margin-left: 0.25em;\\n    }\\n\\n    .value-input,\\n    .new-value-input {\\n      margin-top: 0.125em;\\n\\n      &:last-of-type {\\n        margin-left: 0.25em;\\n      }\\n    }\\n\\n    .remove-value-btn {\\n      margin-left: 0.25em;\\n      margin-top: 0.125em;\\n    }\\n\\n    .add-value-btn {\\n      margin-left: 0.25em;\\n      margin-top: 0.125em;\\n\\n      @include value-btn;\\n    }\\n  }\\n}\\n\\n.mobile-view .secret-value-list {\\n  .add-value-btn {\\n    margin-bottom: 9px;\\n  }\\n\\n  .value {\\n    .value-input:last-of-type {\\n      margin-left: 2.35em;\\n    }\\n\\n    .new-value-input:first-of-type {\\n      margin-right: 2.15em;\\n      margin-left: 0.25em;\\n    }\\n  }\\n}\\n\\n.simple-list-input {\\n  display: flex;\\n\\n  .add-value-input {\\n    margin: 0;\\n    box-sizing: border-box;\\n    flex: 1 0 0px;\\n  }\\n\\n  .add-value-btn {\\n    margin-left: 0.25em;\\n  }\\n}\\n\\n.mobile-view .full-width {\\n  margin: 0;\\n}\\n\\n// Mobile specific style for Admin IP Lookup box\\n.mobile-view .admin-contents .ip-lookup .location-box {\\n  width: 300px;\\n  left: -100%;\\n}\\n\\n.inline-edit label {\\n  display: inline-block;\\n  margin-right: 20px;\\n}\\n\\na.inline-editable-field {\\n  color: var(--primary);\\n  cursor: pointer;\\n}\\n\\n// Styles for subtabs in admin\\n@import \\"admin/dashboard\\";\\n@import \\"admin/sidebar\\";\\n@import \\"admin/settings\\";\\n@import \\"admin/users\\";\\n@import \\"admin/penalty\\";\\n@import \\"admin/badges\\";\\n@import \\"admin/emails\\";\\n@import \\"admin/flags\\";\\n@import \\"admin/json_schema_editor\\";\\n@import \\"admin/schema_field\\";\\n@import \\"admin/staff_logs\\";\\n@import \\"admin/color_palettes\\";\\n@import \\"admin/customize\\";\\n@import \\"admin/customize-install-theme\\";\\n@import \\"admin/api\\";\\n@import \\"admin/backups\\";\\n@import \\"admin/plugins\\";\\n@import \\"admin/site-settings\\";\\n@import \\"admin/admin_config_area\\";\\n@import \\"admin/search\\";\\n@import \\"admin/admin_dashboard\\";\\n@import \\"admin/admin-dashboard-skeleton\\";\\n@import \\"admin/admin_filter\\";\\n@import \\"admin/admin_reports\\";\\n@import \\"admin/admin_report\\";\\n@import \\"admin/admin_report_counters\\";\\n@import \\"admin/admin_report_chart\\";\\n@import \\"admin/admin_report_radar\\";\\n@import \\"admin/admin_report_stacked_line_chart\\";\\n@import \\"admin/admin_report_table\\";\\n@import \\"admin/admin_report_related_items\\";\\n@import \\"admin/admin_report_inline_table\\";\\n@import \\"admin/posters_by_member_type_report\\";\\n@import \\"admin/admin_section_landing_page\\";\\n@import \\"admin/admin_user_fields\\";\\n@import \\"admin/mini_profiler\\";\\n@import \\"admin/schema_setting_editor\\";\\n@import \\"admin/customize_show_schema\\";\\n@import \\"admin/admin_bulk_users_delete_modal\\";\\n@import \\"admin/admin_bulk_users_suspend_modal\\";\\n@import \\"admin/color-palette-editor\\";\\n@import \\"admin/admin_config_color_palettes\\";\\n@import \\"admin/admin_config_components\\";\\n@import \\"admin/admin_category_management\\";\\n@import \\"admin/upcoming-changes\\";\\n@import \\"admin/discourse_id\\";\\n@import \\"admin/admin_new_category_setup\\";\\n@import \\"admin/admin_emoji\\";\\n","@use \\"breakpoints\\";\\n\\n$breakpoints: breakpoints.$breakpoints;\\n\\n@mixin from($bp) {\\n  @media (width >= #{breakpoints.get($bp)}) {\\n    @content;\\n  }\\n}\\n\\n@mixin until($bp) {\\n  @media (width < #{breakpoints.get($bp)}) {\\n    @content;\\n  }\\n}\\n\\n@mixin between($from, $until) {\\n  @media (#{breakpoints.get($from)} <= width < #{breakpoints.get($until)}) {\\n    @content;\\n  }\\n}\\n","// --------------------------------------------------\\n// Mixins used throughout the theme\\n// --------------------------------------------------\\n\\n// Media queries\\n// --------------------------------------------------\\n\\n@use \\"sass:color\\";\\n@use \\"sass:math\\";\\n@use \\"sass:string\\";\\n@use \\"sass:map\\";\\n@use \\"lib/viewport\\";\\n\\n$breakpoints: (\\n  mobile-small: map.get(viewport.$breakpoints, sm),\\n  mobile-medium: map.get(viewport.$breakpoints, sm),\\n  mobile-large: map.get(viewport.$breakpoints, sm),\\n  mobile-extra-large: map.get(viewport.$breakpoints, sm),\\n  tablet: map.get(viewport.$breakpoints, md),\\n  medium: map.get(viewport.$breakpoints, lg),\\n  large: map.get(viewport.$breakpoints, lg),\\n  extra-large: map.get(viewport.$breakpoints, xl),\\n);\\n\\n/* breakpoint is a legacy mixin. Use `@use \\"lib/viewport\\"` instead. */\\n@mixin breakpoint($bp, $rule: max-width, $type: screen, $sidebar: false) {\\n  /* stylelint-disable-next-line scss/no-global-function-names */\\n  $bp-value: map-get($breakpoints, $bp);\\n\\n  @if $rule == min-width {\\n    $bp-value: calc(#{$bp-value} + 1px);\\n  }\\n\\n  @media #{$type} and (#{$rule}: #{$bp-value}) {\\n    @content;\\n  }\\n\\n  // if you want to consider the sidebar in your breakpoint\\n  // you can pass in $sidebar: true\\n  // note that your breakpoint will need to be at the root level\\n  @if $sidebar {\\n    // when the sidebar is shown, we want to increase the breakpoints by the width of the sidebar\\n    /* stylelint-disable-next-line scss/no-global-function-names */\\n    @media #{$type} and (#{$rule}: calc(#{map-get($breakpoints, $bp)} + #{$d-sidebar-width})) {\\n      .has-sidebar-page {\\n        @content;\\n      }\\n    }\\n  }\\n}\\n\\n// CSS3 properties\\n// --------------------------------------------------\\n\\n// Clearfix\\n\\n@mixin clearfix() {\\n  &::before,\\n  &::after {\\n    content: \\"\\";\\n    display: table;\\n  }\\n\\n  &::after {\\n    clear: both;\\n  }\\n}\\n\\n@mixin linear-gradient($start-color, $end-color) {\\n  background-color: $start-color;\\n  background-image: linear-gradient(to bottom, $start-color, $end-color);\\n}\\n\\n@mixin darken-background($background-color, $amt) {\\n  $overlay: dark-light-choose(\\n    rgb(var(--primary-rgb), $amt),\\n    rgb(var(--secondary-rgb), $amt)\\n  );\\n  background-image: linear-gradient(to bottom, $overlay 100%, $overlay 100%);\\n}\\n\\n// Visibility\\n// --------------------------------------------------\\n\\n// Only shows hover on non-touch devices\\n@mixin hover {\\n  .discourse-no-touch &,\\n  .no-ember & {\\n    &:hover,\\n    &.btn-hover {\\n      @content;\\n    }\\n  }\\n}\\n\\n@mixin ellipsis {\\n  overflow: hidden;\\n  white-space: nowrap;\\n  text-overflow: ellipsis;\\n}\\n\\n@mixin line-clamp($lines) {\\n  display: -webkit-box;\\n  overflow: hidden;\\n  text-overflow: ellipsis;\\n  overflow-wrap: break-word;\\n  -webkit-line-clamp: $lines;\\n  -webkit-box-orient: vertical;\\n}\\n\\n//\\n// --------------------------------------------------\\n\\n$vpad: 0.5em;\\n$hpad: 0.65em;\\n\\n// for consistent sizing across inputs, buttons and dropdowns\\n@mixin form-item-sizing {\\n  border: 1px solid transparent;\\n  font-size: var(--font-0);\\n  line-height: normal;\\n  box-sizing: border-box;\\n  padding: $vpad $hpad;\\n}\\n\\n// Used to handle -webkit prefix, but now we have autoprefixer\\n// Keeping for backward-compat with plugins/themes only\\n@mixin user-select($mode) {\\n  user-select: $mode;\\n}\\n\\n// Unselectable (avoids unwanted selections with iPad, touch laptops, etc)\\n@mixin unselectable {\\n  cursor: default;\\n\\n  @include user-select(none);\\n}\\n\\n// Stuff we repeat\\n@mixin d-animation($name, $duration, $easing: ease) {\\n  animation: $name $duration $easing forwards;\\n\\n  @media (prefers-reduced-motion) {\\n    /* stylelint-disable-next-line no-invalid-position-declaration */\\n    animation-duration: 0s;\\n  }\\n}\\n\\n@mixin default-focus() {\\n  border-color: var(--d-input-focused-color);\\n  outline: 2px solid var(--d-input-focused-color);\\n  outline-offset: -2px;\\n}\\n\\n/// Helper function to easily use an SVG inline in CSS\\n/// without encoding it to base64, saving bytes.\\n/// It also helps with browser support, especially for IE11.\\n///\\n/// @author Jakob Eriksen\\n/// @link http://codepen.io/jakob-e/pen/doMoML\\n/// @param {String} $svg - SVG image to encode\\n/// @return {String} - Encoded SVG data uri\\n@function svg-uri($svg) {\\n  $encoded: \\"\\";\\n  $slice: 2000;\\n  $index: 0;\\n  $loops: math.ceil(math.div(string.length($svg), $slice));\\n\\n  @for $i from 1 through $loops {\\n    $chunk: string.slice($svg, $index, $index + $slice - 1);\\n    $chunk: str-replace($chunk, '\\"', \\"'\\");\\n    $chunk: str-replace($chunk, \\"<\\", \\"%3C\\");\\n    $chunk: str-replace($chunk, \\">\\", \\"%3E\\");\\n    $chunk: str-replace($chunk, \\"&\\", \\"%26\\");\\n    $chunk: str-replace($chunk, \\"#\\", \\"%23\\");\\n    $encoded: #{$encoded}#{$chunk};\\n    $index: $index + $slice;\\n  }\\n\\n  @return url(\\"data:image/svg+xml;charset=utf8,#{$encoded}\\");\\n}\\n\\n/// Replace `$search` with `$replace` in `$string`\\n/// @author Hugo Giraudel\\n/// @link http://sassmeister.com/gist/1b4f2da5527830088e4d\\n/// @param {String} $string - Initial string\\n/// @param {String} $search - Substring to replace\\n/// @param {String} $replace ('') - New value\\n/// @return {String} - Updated string\\n@function str-replace($string, $search, $replace: \\"\\") {\\n  $index: string.index($string, $search);\\n\\n  @if $index {\\n    @return string.slice($string, 1, $index - 1) + $replace +\\n      str-replace(\\n        string.slice($string, $index + string.length($search)),\\n        $search,\\n        $replace\\n      );\\n  }\\n\\n  @return $string;\\n}\\n\\n// SCSS accepts HEX or RGB colors for rgba($color, 0.5)\\n// CSS custom properties only accept RGB\\n// Example usage:\\n\\n// --primary-rgb: #{hexToRGB($primary)};\\n// ...\\n// rgba(var(--primary-low-rgb), 0.5)\\n\\n@function hexToRGB($hex) {\\n  @return color.red($hex), color.green($hex), color.blue($hex);\\n}\\n\\n@function schemeType() {\\n  @if is-light-color-scheme() {\\n    @return \\"light\\";\\n  } @else {\\n    @return \\"dark\\";\\n  }\\n}\\n\\n@function absolute-image-url($path) {\\n  // public_image_path is added by the stylesheet importer\\n  // it returns a CDN or subfolder path (if applicable).\\n  // SCSS will compile (and return the relative path) if public_image_path is missing.\\n  /* stylelint-disable-next-line scss/no-global-function-names */\\n  @if global-variable-exists(public_image_path) {\\n    @if string.index(\\"#{$path}\\", \\"/plugins\\") == 1 {\\n      $plugin_asset_path: str-replace($public_image_path, \\"/images\\", \\"\\");\\n\\n      @return url(\\"#{$plugin_asset_path}#{$path}\\");\\n    } @else {\\n      @return url(\\"#{$public_image_path}#{$path}\\");\\n    }\\n  } @else {\\n    @return url(\\"#{$path}\\");\\n  }\\n}\\n\\n@mixin mention() {\\n  // memo to self: do not make this inline-flex because it breaks text alignments and causes a whole avalance of unpleasant consequences\\n  display: inline-block;\\n  font-size: 0.93em;\\n  font-weight: normal;\\n  color: var(--primary);\\n  padding: 0.2em 0.34em;\\n  background: var(--mention-background-color);\\n  border-radius: 0.6em;\\n  text-decoration: none;\\n  text-wrap: nowrap;\\n  line-height: 1;\\n  unicode-bidi: plaintext;\\n\\n  &[data-valid=\\"false\\"] {\\n    background: unset;\\n    padding: 0;\\n  }\\n\\n  &.--bot {\\n    background: var(--success-low);\\n  }\\n\\n  &.--wide {\\n    background: var(--highlight-low-or-medium);\\n  }\\n}\\n\\n@mixin nav-active() {\\n  color: var(--d-nav-color--active);\\n  background: var(--d-nav-bg-color--active);\\n\\n  .d-icon {\\n    color: var(--d-nav-color--active);\\n  }\\n\\n  &::after {\\n    content: \\"\\";\\n    position: absolute;\\n    left: 0;\\n    bottom: 0;\\n    right: 0;\\n    height: var(--d-nav-underline-height);\\n    background: var(--d-nav-color--active);\\n\\n    // Forced colors drop backgrounds, which is the only thing that marks\\n    // the active item.\\n    @media (forced-colors: active) {\\n      background: Highlight;\\n      forced-color-adjust: none;\\n    }\\n  }\\n}\\n\\n@mixin nav-hover() {\\n  color: var(--d-nav-color--hover);\\n  background: var(--d-nav-bg-color--hover);\\n\\n  .d-icon {\\n    color: var(--d-nav-color--active);\\n  }\\n}\\n\\n// A strip that hides its scrollbar and fades the edge beyond which more\\n// content lies. The fade reads the data-d-scroll-* attributes stamped by\\n// the scroll-edges watcher, which DOverflowControls and the dScrollEdges\\n// modifier both run. The band starts fully transparent across --fade-inset\\n// so strip content never shows through a chevron parked on the edge, which\\n// assumes the chevron covers that band: a wrapper that pads the scroller's\\n// scrolling edge moves the chevron off it and hides content under nothing.\\n// #000 is deliberate: a mask reads only alpha, so a colour token would be\\n// wrong here.\\n@mixin scroll-strip() {\\n  // The bands are capped so the two ends cannot cross on a narrow strip.\\n  // Crossed bands leave no opaque middle.\\n  --scroll-strip-fade-start: min(var(--fade-inset, 0px), 15%);\\n  --scroll-strip-fade-end: min(\\n    calc(var(--fade-inset, 0px) + var(--fade-width, 2em)),\\n    40%\\n  );\\n  min-width: 0;\\n  min-height: 0;\\n  scrollbar-width: none;\\n  scroll-padding: calc(var(--fade-inset, 0px) + var(--fade-width, 2em));\\n\\n  &::-webkit-scrollbar {\\n    display: none;\\n  }\\n\\n  // Forced colors drop the mask, which would otherwise lower text contrast\\n  // for exactly the users who opted out of decoration.\\n  @media (forced-colors: none) {\\n    &[data-d-scroll-axis=\\"horizontal\\"][data-d-scroll-overflow] {\\n      mask-image: linear-gradient(\\n        to right,\\n        transparent var(--scroll-strip-fade-start),\\n        #000 var(--scroll-strip-fade-end),\\n        #000 calc(100% - var(--scroll-strip-fade-end)),\\n        transparent calc(100% - var(--scroll-strip-fade-start))\\n      );\\n\\n      // The edges are logical, the gradients physical, so RTL swaps them.\\n      &[data-d-scroll-at-start] {\\n        mask-image: linear-gradient(\\n          to right,\\n          #000 calc(100% - var(--scroll-strip-fade-end)),\\n          transparent calc(100% - var(--scroll-strip-fade-start))\\n        );\\n\\n        .rtl & {\\n          mask-image: linear-gradient(\\n            to left,\\n            #000 calc(100% - var(--scroll-strip-fade-end)),\\n            transparent calc(100% - var(--scroll-strip-fade-start))\\n          );\\n        }\\n      }\\n\\n      &[data-d-scroll-at-end] {\\n        mask-image: linear-gradient(\\n          to right,\\n          transparent var(--scroll-strip-fade-start),\\n          #000 var(--scroll-strip-fade-end)\\n        );\\n\\n        .rtl & {\\n          mask-image: linear-gradient(\\n            to left,\\n            transparent var(--scroll-strip-fade-start),\\n            #000 var(--scroll-strip-fade-end)\\n          );\\n        }\\n      }\\n    }\\n\\n    &[data-d-scroll-axis=\\"vertical\\"][data-d-scroll-overflow] {\\n      mask-image: linear-gradient(\\n        to bottom,\\n        transparent var(--scroll-strip-fade-start),\\n        #000 var(--scroll-strip-fade-end),\\n        #000 calc(100% - var(--scroll-strip-fade-end)),\\n        transparent calc(100% - var(--scroll-strip-fade-start))\\n      );\\n\\n      &[data-d-scroll-at-start] {\\n        mask-image: linear-gradient(\\n          to bottom,\\n          #000 calc(100% - var(--scroll-strip-fade-end)),\\n          transparent calc(100% - var(--scroll-strip-fade-start))\\n        );\\n      }\\n\\n      &[data-d-scroll-at-end] {\\n        mask-image: linear-gradient(\\n          to bottom,\\n          transparent var(--scroll-strip-fade-start),\\n          #000 var(--scroll-strip-fade-end)\\n        );\\n      }\\n    }\\n\\n    // The .rtl copy only exists to outrank the .rtl at-start/at-end rules\\n    // above, which score a class higher than the bare selector.\\n    &[data-d-scroll-overflow][data-d-scroll-at-start][data-d-scroll-at-end],\\n    .rtl\\n      &[data-d-scroll-overflow][data-d-scroll-at-start][data-d-scroll-at-end] {\\n      mask-image: none;\\n    }\\n  }\\n}\\n\\n// The scroll strip on the horizontal axis. The caller keeps its own items\\n// on one row; the mixin does not.\\n@mixin horizontal-scroll-strip() {\\n  @include scroll-strip;\\n  overflow-x: auto;\\n}\\n\\n@mixin click-counter-badge {\\n  content: attr(data-clicks);\\n  font-weight: normal;\\n  background-color: var(--primary-low);\\n  color: var(--primary-medium);\\n  position: relative;\\n  top: -1px;\\n  padding: 0.21em 0.42em;\\n  min-width: 0.5em;\\n  line-height: var(--line-height-small);\\n  font-size: var(--font-down-2);\\n  text-align: center;\\n  border-radius: 10px;\\n  white-space: nowrap;\\n  display: inline-block;\\n  margin: 0.15em;\\n}\\n\\n@mixin topic-list-icons {\\n  .d-icon-thumbtack {\\n    color: var(--primary-med-or-secondary-med);\\n  }\\n\\n  .d-icon-thumbtack.unpinned {\\n    color: var(--primary-med-or-secondary-med);\\n  }\\n\\n  a.title {\\n    color: var(--primary);\\n  }\\n\\n  .d-icon-bookmark {\\n    color: var(--primary-med-or-secondary-med);\\n  }\\n}\\n\\n@mixin hide-posters {\\n  width: 2em;\\n  text-align: center;\\n\\n  a:first-child .avatar.latest:not(.single) {\\n    top: 0;\\n    left: 0;\\n  }\\n\\n  a:not(.latest) {\\n    display: none;\\n  }\\n\\n  a.latest {\\n    width: 100%;\\n\\n    img {\\n      margin: 0 auto;\\n    }\\n  }\\n}\\n\\n@mixin dot-separator($size: 0.35em) {\\n  display: inline-block;\\n  width: $size;\\n  height: $size;\\n  margin-inline: var(--space-1);\\n  border-radius: 6.25em;\\n  background: var(--primary-low-mid);\\n  flex-shrink: 0;\\n}\\n\\n@mixin menu-item {\\n  display: inline-flex;\\n  gap: var(--d-sidebar-section-link-prefix-margin-right);\\n  padding: var(--space-2) var(--d-sidebar-row-horizontal-padding);\\n  width: 100%;\\n  justify-content: flex-start;\\n  background: rgb(0, 0, 0, 0);\\n  border-radius: var(--d-border-radius);\\n\\n  &:not(.notifications-tracking-btn, .--with-description, .pinned-options-btn) {\\n    height: var(--d-sidebar-row-height);\\n    padding-block: 0;\\n  }\\n\\n  &.-selected {\\n    background: var(--d-hover);\\n  }\\n\\n  &.btn-danger {\\n    color: var(--danger);\\n\\n    .d-icon {\\n      color: inherit;\\n    }\\n  }\\n\\n  .svg-icon {\\n    width: var(--d-sidebar-section-link-prefix-width);\\n    margin-right: 0;\\n  }\\n\\n  &:hover,\\n  &:focus-visible {\\n    .discourse-no-touch & {\\n      background: var(--d-hover);\\n      color: var(--primary);\\n\\n      .d-icon {\\n        color: inherit;\\n      }\\n\\n      &.btn-danger {\\n        background: var(--danger-low);\\n        color: var(--danger);\\n\\n        .d-icon {\\n          color: var(--danger-hover);\\n        }\\n      }\\n    }\\n  }\\n}\\n\\n@mixin unstyled-list {\\n  list-style: none;\\n  padding: 0;\\n  margin: 0;\\n}\\n","@use \\"lib/viewport\\";\\n\\n.admin-reports,\\n.dashboard-next {\\n  &.admin-contents {\\n    nav {\\n      position: relative;\\n      width: calc(100% + 10px);\\n      padding-left: 10px;\\n      margin-left: -10px;\\n      margin-right: -10px;\\n    }\\n  }\\n}\\n\\n.dashboard-next {\\n  .nav {\\n    display: flex;\\n    margin: 0 0 2em 0;\\n    border-bottom: 1px solid var(--content-border-color);\\n    font-size: var(--font-up-1);\\n    white-space: nowrap;\\n    flex-wrap: nowrap;\\n    overflow-x: auto;\\n\\n    // Fade-out for horizontal scroll nav\\n    &::before {\\n      content: \\"\\";\\n      position: absolute;\\n      width: 10px;\\n      margin-left: -10px;\\n      height: 100%;\\n      background: linear-gradient(\\n        to left,\\n        rgb(var(--secondary-rgb), 1),\\n        rgb(var(--secondary-rgb), 0)\\n      );\\n    }\\n\\n    &::after {\\n      content: \\"\\";\\n      position: absolute;\\n      right: 0;\\n      width: 30px;\\n      height: 100%;\\n      background: linear-gradient(\\n        to right,\\n        rgb(var(--secondary-rgb), 0),\\n        rgb(var(--secondary-rgb), 1)\\n      );\\n    }\\n\\n    .navigation-link {\\n      @include viewport.until(sm) {\\n        padding: 0.4em;\\n        font-size: var(--font-down-1);\\n      }\\n\\n      .emoji {\\n        margin-right: 0.5em;\\n\\n        @include viewport.until(sm) {\\n          width: 1.3em;\\n          height: 1.3em;\\n          margin-right: 0;\\n        }\\n      }\\n    }\\n  }\\n\\n  .sections {\\n    display: flex;\\n    flex-direction: column;\\n  }\\n\\n  .section-columns {\\n    display: flex;\\n    justify-content: space-between;\\n\\n    @include viewport.until(lg) {\\n      flex-direction: column;\\n    }\\n\\n    .section-column {\\n      min-width: calc(5