th: $mobile-breakpoint) {\\n          width: 100% !important; // !important overrides hard-coded mobile width of 68px\\n        }\\n      }\\n\\n      label a {\\n        margin: 0;\\n      }\\n    }\\n\\n    .inline-dependent-settings {\\n      margin-top: var(--space-3);\\n\\n      .setting.inline-dependent-setting {\\n        padding-bottom: var(--space-2);\\n\\n        .setting-label,\\n        .setting-value,\\n        .setting-controls {\\n          float: none;\\n          width: 100%;\\n          padding-right: 0;\\n        }\\n\\n        .setting-label h3 {\\n          margin-top: 0;\\n          margin-bottom: var(--space-1);\\n        }\\n      }\\n    }\\n\\n    .setting-override-warning {\\n      font-size: var(--font-down-1);\\n      color: var(--primary-medium);\\n\\n      .d-icon {\\n        font-size: var(--font-down-1);\\n        vertical-align: baseline;\\n      }\\n    }\\n\\n    .setting-controls {\\n      float: left;\\n    }\\n\\n    .input-setting-string,\\n    .input-setting-integer,\\n    .input-setting-textarea {\\n      width: 100%;\\n\\n      @media (max-width: $mobile-breakpoint) {\\n        width: 100%;\\n      }\\n    }\\n\\n    .input-setting-textarea {\\n      height: 150px;\\n    }\\n\\n    .input-setting-list {\\n      padding: 1px;\\n      background-color: var(--secondary);\\n      border: 1px solid var(--input-border-color);\\n      border-radius: 3px;\\n      transition:\\n        border linear 0.2s,\\n        box-shadow linear 0.2s;\\n\\n      @media (max-width: $mobile-breakpoint) {\\n        width: 100%;\\n      }\\n\\n      li.sortable-placeholder {\\n        @include unselectable;\\n        padding: 3px 5px 3px 18px;\\n        margin: 3px 0 3px 5px;\\n        position: relative;\\n        line-height: var(--line-height-small);\\n        cursor: default;\\n        border: 1px dashed var(--primary-low-mid);\\n        border-radius: 3px;\\n        background-clip: padding-box;\\n        background-color: transparent;\\n      