n: right;\\n\\n    a {\\n      color: var(--primary-high);\\n    }\\n  }\\n\\n  td {\\n    max-width: 20em;\\n    overflow-wrap: break-word;\\n  }\\n\\n  .incoming-email-link,\\n  .sent-email-post-link-with-smtp-response {\\n    min-width: 19em;\\n  }\\n}\\n\\n.incoming-emails {\\n  .control-group {\\n    margin: 8px 0;\\n  }\\n\\n  .controls {\\n    margin-left: 110px;\\n  }\\n\\n  p {\\n    margin: 5px 10px;\\n  }\\n\\n  .error-description {\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1);\\n  }\\n\\n  hr {\\n    margin: 0;\\n  }\\n\\n  label {\\n    font-weight: bold;\\n    float: left;\\n    width: 100px;\\n    text-align: right;\\n    margin: 0 10px;\\n  }\\n\\n  ul {\\n    list-style: none;\\n    margin: 0 10px;\\n  }\\n\\n  textarea {\\n    width: 95%;\\n    height: 150px;\\n    font-family: monospace;\\n    box-shadow: none;\\n  }\\n}\\n\\n.admin-list-item {\\n  width: 100%;\\n  border-top: 1px solid var(--content-border-color);\\n  padding: 0.25em 0;\\n}\\n\\n.email-preview-digest {\\n  .controls {\\n    margin: 1em 0.5em;\\n  }\\n\\n  .preview-output iframe {\\n    width: 100%;\\n    height: 600px;\\n    border-width: 1px;\\n  }\\n}\\n\\n.email-advanced-test {\\n  .admin-controls {\\n    display: block;\\n  }\\n\\n  .email-body {\\n    width: 95%;\\n    height: 150px;\\n    font-family: monospace;\\n  }\\n}\\n\\n.admin-email {\\n  .email-list {\\n    .sent-email-reply-key {\\n      .reply-key {\\n        word-break: break-word;\\n        white-space: nowrap;\\n        overflow: hidden;\\n        text-overflow: ellipsis;\\n        width: 125px;\\n      }\\n    }\\n\\n    .sent-email-post-link-with-smtp-response {\\n      width: 100%;\\n      display: inline-block;\\n      word-break: break-word;\\n\\n      code {\\n        font-size: var(--font-down-2);\\n      }\\n    }\\n  }\\n}\\n\\n// specific email admin modal styling\\n.admin-incoming-email-modal {\\n  .incoming-emails {\\n    label {\\n      float: none;\\n      margin: 0;\\n 