ext {\\n    display: flex;\\n    flex-direction: row;\\n    margin-top: 0.2em;\\n    width: 100%;\\n    gap: 0 0.5em;\\n\\n    .schema-field__input-count {\\n      margin-left: auto;\\n      font-size: var(--font-down-1);\\n\\n      &.--error {\\n        color: var(--danger);\\n      }\\n    }\\n\\n    .schema-field__input-error {\\n      font-size: var(--font-down-1);\\n      color: var(--danger);\\n    }\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n// Styles for /admin/logs\\n.log-details-modal {\\n  pre {\\n    white-space: pre-wrap;\\n    max-height: 250px;\\n  }\\n}\\n\\n.staff-actions {\\n  width: 100%;\\n  overflow-wrap: break-word;\\n\\n  @media screen and (width >= 550px) and (width <= 767px) {\\n    table.staff-logs tr {\\n      display: grid;\\n      grid-template-rows: auto auto;\\n      grid-template-columns: repeat(4, 1fr);\\n\\n      td {\\n        align-self: start;\\n        padding: 2px 4px;\\n      }\\n    }\\n\\n    td.created-at {\\n      grid-column-start: -1;\\n    }\\n\\n    td.subject {\\n      grid-row: 2;\\n      grid-column-start: 2;\\n\\n      div.subject {\\n        display: flex;\\n\\n        a {\\n          overflow-wrap: break-word;\\n          min-width: 25px;\\n        }\\n      }\\n    }\\n\\n    td.details {\\n      grid-row: 1;\\n      grid-row-start: 1;\\n      grid-row-end: 3;\\n      grid-column-start: 3;\\n    }\\n\\n    td.context {\\n      grid-row-start: 1;\\n      grid-row-end: 3;\\n      grid-column-start: 4;\\n    }\\n  }\\n\\n  @include viewport.until(sm) {\\n    table.staff-logs tr {\\n      grid-template-columns: 1fr 1fr 0.5fr;\\n\\n      td.staff-users {\\n        grid-column-start: 1;\\n        grid-column-end: 3;\\n      }\\n\\n      td.created-at {\\n        grid-row: 1;\\n        grid-column-start: -1;\\n        text-align: right;\\n      }\\n\\n      td.action {\\n        grid-row: 2;\\n        grid-column-start: 1;\\n      }\\n\\n      td.subject {\\n        grid-row: 2;\\n        grid-column-start: 2;\\n    