adding: var(--space-3);\\n  background-color: var(--secondary);\\n  border: 1px solid var(--primary-300);\\n  border-radius: var(--d-border-radius);\\n  box-shadow: var(--shadow-card);\\n  z-index: 1;\\n\\n  .footer-nav-visible & {\\n    bottom: calc(\\n      var(--footer-nav-height) + env(safe-area-inset-bottom) + var(--space-4)\\n    );\\n  }\\n\\n  @include viewport.until(sm) {\\n    flex-direction: column;\\n    justify-content: flex-start;\\n    align-items: flex-start;\\n    gap: var(--space-3);\\n  }\\n\\n  .controls {\\n    display: flex;\\n    gap: var(--space-3);\\n  }\\n\\n  em {\\n    font-style: normal;\\n    font-weight: 700;\\n  }\\n}\\n\\n.admin-theme-site-settings-row {\\n  &__setting {\\n    .setting-label {\\n      margin: 0;\\n    }\\n\\n    .setting-description {\\n      color: var(--primary-high);\\n      font-size: var(--font-down-1);\\n    }\\n  }\\n\\n  @include viewport.from(sm) {\\n    &__setting {\\n      width: 40%;\\n    }\\n\\n    &__default {\\n      width: 10%;\\n    }\\n\\n    &__overridden {\\n      width: 50%;\\n    }\\n  }\\n}\\n",".admin-config-area-card {\\n  padding: var(--space-4);\\n  border: 1px solid var(--content-border-color);\\n  border-radius: var(--d-border-radius);\\n  background-color: var(--secondary);\\n  min-width: 0;\\n\\n  &__label-optional {\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1);\\n    margin-left: 5px;\\n  }\\n\\n  &__additional-help {\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1);\\n  }\\n\\n  &__warning-banner {\\n    color: var(--primary-high);\\n    background-color: var(--danger-low);\\n    font-size: var(--font-down-1);\\n    padding: 10px 10px;\\n  }\\n\\n  &__control-group-horizontal {\\n    display: flex;\\n    margin-bottom: 18px;\\n\\n    label {\\n      margin-right: 1em;\\n    }\\n  }\\n\\n  &__title {\\n    flex: 2;\\n    margin-bottom: 0;\\n  }\\n\\n  &__header-wrapper {\\n    display: flex;\\n    align-items: center;\\n    flex: 1;\\n  }\\n\\n  &__content {\\n    margin-top: 0.5rem;\\n  }\\n}\\n\\n.admin-config-page {\\n  &__main-area {\\n    .admin-detail {\\n      padding-top: 15px;\\n      border-left: 0;\\n      padding-left: 0;\\n      width: 100%;\\n    }\\n  }\\n}\\n\\n.admin-config-area {\\n  display: flex;\\n  flex-wrap: nowrap;\\n  gap: var(--space-4);\\n  align-items: flex-start;\\n\\n  @media (max-width: $mobile-breakpoint) {\\n    flex-direction: column;\\n  }\\n\\n  &__full-width {\\n    flex: 1 0 100%;\\n  }\\n\\n  &__primary-content {\\n    flex: 0 1 100%;\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-4);\\n    max-width: var(--admin-content-max-width);\\n  }\\n\\n  &__aside {\\n    /* use for help inset */\\n    flex: 0 1 20%;\\n    padding: var(--space-2);\\n\\n    @media (max-width: $mobile-breakpoint) {\\n      flex: 0 1 auto;\\n    }\\n  }\\n\\n  &__settings {\\n    .setting-label {\\n      margin-left: 18px;\\n    }\\n  }\\n\\n  .btn-back {\\n    margin-bottom: 1em;\\n  }\\n}\\n\\n.admin-config-area-about {\\n  &__locale-form {\\n    margin: 0;\\n    width: 100%;\\n  }\\n\\n  &__locale-selector-dropdown {\\n    width: 100%;\\n  }\\n}\\n\\n.admin-site-settings-filter-controls {\\n  border-bottom: 1px solid var(--content-border-color);\\n}\\n\\n.admin-config-area-empty-list,\\n.admin-empty-list {\\n  padding: 1em;\\n  border: 1px solid var(--content-border-color);\\n  border-radius: var(--d-border-radius);\\n\\n  &__cta-button {\\n    display: flex;\\n    margin-top: 1em;\\n  }\\n}\\n\\n.admin-config-area-card-section {\\n  display: flex;\\n  flex-wrap: nowrap;\\n  gap: var(--space-4);\\n  flex-direction: column;\\n  width: calc(100% - 1em);\\n  border: 1px solid var(--content-border-color);\\n  padding: var(--space-4);\\n  border-radius: var(--d-border-radius);\\n\\n  @media (max-width: $mobile-breakpoint) {\\n    flex-direction: column;\\n  }\\n\\n  &__header-wrapper {\\n    display: flex;\\n    align-items: center;\\n    justify-content: space-between;\\n\\n    &.collapsable {\\n      cursor: pointer;\\n    }\\n  }\\n\\n  &__title {\\n    margin-bottom: 0;\\n  }\\n\\n  &__content {\\n    margin-top: 0.5rem;\\n    padding-right: 1em;\\n    padding-bottom: 1em;\\n    gap: 1.5em;\\n    display: flex;\\n    flex-direction: column;\\n  }\\n}\\n\\n.admin-logo-form {\\n  .form-kit__section {\\n    .form-kit__container {\\n      padding: 1em;\\n      width: calc(100% - 2em) !important;\\n      border: 1px solid var(--content-border-color);\\n    }\\n  }\\n\\n  #control-logo_dark .file-uploader.has-image .file-uploader__preview {\\n    background-color: #333;\\n    background-clip: border-box;\\n  }\\n\\n  .form-kit__field-toggle.--full .form-kit__container-content {\\n    // avoid label wrapping\\n    width: var(--form-kit-small-input) !important;\\n  }\\n}\\n\\n.og-image-preview {\\n  margin-top: var(--space-4);\\n\\n  &__header {\\n    margin-bottom: var(--space-1);\\n  }\\n\\n  &__title {\\n    font-weight: bold;\\n    font-size: var(--font-0-rem);\\n  }\\n\\n  &__description {\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1-rem);\\n    margin-bottom: var(--space-3);\\n  }\\n\\n  &__form {\\n    margin-bottom: var(--space-3);\\n  }\\n\\n  &__controls {\\n    display: flex;\\n    align-items: flex-end;\\n    gap: var(--space-2);\\n\\n    .form-kit__field {\\n      margin-bottom: 0;\\n    }\\n  }\\n\\n  &__frame {\\n    border: 1px solid var(--primary-low);\\n    border-radius: var(--d-border-radius-large);\\n    overflow: hidden;\\n    max-width: 600px;\\n    background: var(--secondary);\\n  }\\n\\n  &__image {\\n    display: block;\\n    width: 100%;\\n    height: auto;\\n  }\\n\\n  &__loading,\\n  &__error,\\n  &__placeholder {\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    aspect-ratio: 1200 / 630;\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1-rem);\\n  }\\n}\\n\\n.admin-fonts-form {\\n  &__more {\\n    font-size: var(--font-down-1-rem);\\n  }\\n\\n  .form-kit__field-custom {\\n    width: 100% !important;\\n\\n    .form-kit__control-custom {\\n      display: flex;\\n      flex-wrap: wrap;\\n      flex-direction: row;\\n      justify-content: space-between;\\n\\n      .admin-fonts-form__button-option {\\n        border: 1px solid var(--content-border-color);\\n        font-size: var(--font-down-1-rem);\\n        max-height: 4em;\\n        height: 50px;\\n        margin-bottom: 1em;\\n        padding: 0 0.65em;\\n\\n        &:hover {\\n          border-color: var(--primary-low-mid);\\n        }\\n\\n        &.active {\\n          position: relative;\\n          border: 2px solid var(--tertiary);\\n\\n          &::after {\\n            position: absolute;\\n            top: 35%;\\n            left: 0.5rem;\\n            font-family: \\"Segoe UI\\", Arial, sans-serif;\\n            content: \\"\\\\2714\\"; // ✔\\n            display: inline-flex;\\n            align-items: center;\\n            justify-content: center;\\n            width: 1rem;\\n            height: 1rem;\\n            background-color: var(--tertiary);\\n            color: var(--secondary);\\n            border-radius: 9999px;\\n            font-size: 0.5rem;\\n            margin-left: 0.25rem;\\n          }\\n\\n          &:hover {\\n            border-color: var(--tertiary);\\n          }\\n        }\\n\\n        &.font {\\n          flex: 0 0 32%;\\n          max-width: 32%;\\n\\n          @media (max-width: $mobile-breakpoint) {\\n            flex: 0 0 100%;\\n            max-width: 100%;\\n          }\\n        }\\n\\n        &.text-size {\\n          flex: 0 0 19%;\\n          max-width: 19%;\\n\\n          // px must be used because there is different font size inside each button\\n          height: 45px;\\n\\n          @media (max-width: $mobile-breakpoint) {\\n            flex: 0 0 100%;\\n            max-width: 100%;\\n          }\\n\\n          &.smallest {\\n            font-size: var(--base-font-size-smallest);\\n          }\\n\\n          &.smaller {\\n            font-size: var(--base-font-size-smaller);\\n          }\\n\\n          &.normal {\\n            font-size: var(--base-font-size-normal);\\n          }\\n\\n          &.larger {\\n            font-size: var(--base-font-size-larger);\\n          }\\n\\n          &.largest {\\n            font-size: var(--base-font-size-largest);\\n          }\\n        }\\n      }\\n    }\\n  }\\n}\\n\\n.admin-welcome-banner-form {\\n  #control-enabledThemes {\\n    .form-kit__field.--large .form-kit__container-content {\\n      .d-multi-select-trigger__selection-label {\\n        // show selection full names (overrides unnecessary truncation)\\n        max-width: unset;\\n      }\\n    }\\n  }\\n}\\n",".d-modal.admin-search-modal .d-modal__body {\\n  display: flex;\\n  flex-direction: column;\\n  gap: var(--space-2);\\n  padding: 0 var(--space-2) var(--space-2) var(--space-2);\\n}\\n\\n// Search field\\n.admin-search {\\n  &__input-container {\\n    display: flex;\\n  }\\n\\n  &__input-group {\\n    display: flex;\\n    align-items: center;\\n    border: 1px solid var(--primary-400);\\n    width: 100%;\\n    box-sizing: border-box;\\n    height: 42px;\\n    padding: 0 var(--space-2);\\n    border-radius: var(--d-input-border-radius);\\n\\n    &:focus,\\n    &:focus-within {\\n      border-color: var(--tertiary);\\n      outline: 2px solid var(--tertiary);\\n      outline-offset: -2px;\\n    }\\n  }\\n\\n  &__input-icon {\\n    background: none !important;\\n    color: var(--primary-medium);\\n  }\\n\\n  &__input-field {\\n    margin: 0 !important;\\n    border: 0 !important;\\n    appearance: none !important;\\n    outline: none !important;\\n    background: none !important;\\n    width: 100% !important;\\n  }\\n}\\n\\n// Results\\n.admin-search__result {\\n  border-top: 1px solid var(--content-border-color);\\n  display: block;\\n\\n  &:first-child {\\n    border-top: none;\\n  }\\n\\n  &:last-child {\\n    border-bottom: none;\\n  }\\n\\n  &:hover {\\n    background-color: var(--d-hover);\\n  }\\n\\n  &-name {\\n    color: var(--primary);\\n    display: flex;\\n    flex-wrap: wrap;\\n    justify-content: space-between;\\n    align-items: baseline;\\n    gap: var(--space-3);\\n\\n    .d-icon {\\n      color: var(--primary-high);\\n      font-size: var(--font-down-1);\\n    }\\n  }\\n\\n  &-name-label {\\n    flex: 1;\\n  }\\n\\n  &-description {\\n    font-size: var(--font-down-1);\\n    color: var(--primary-high);\\n    margin-top: var(--space-1);\\n  }\\n\\n  &-link {\\n    box-sizing: border-box;\\n    display: inline-block;\\n    width: 100%;\\n    padding: var(--space-3) var(--space-4);\\n\\n    &:focus-visible {\\n      outline: none;\\n    }\\n  }\\n\\n  &:focus-within {\\n    background: var(--d-hover);\\n  }\\n}\\n\\n.admin-search-modal {\\n  --modal-max-width: 700px;\\n\\n  .admin-search__no-results,\\n  .admin-search__input-container {\\n    padding-inline: var(--space-2);\\n  }\\n\\n  .admin-search__no-results {\\n    margin-bottom: 0;\\n  }\\n\\n  .admin-search__input-container {\\n    position: sticky;\\n    top: 0;\\n    background: var(--secondary);\\n    z-index: z(\\"modal\\", \\"content\\"); // above title icons\\n\\n    &.--has-results {\\n      padding-bottom: var(--space-2);\\n    }\\n  }\\n}\\n","@use \\"lib/container\\";\\n\\n.db-activity {\\n  display: flex;\\n  flex-direction: column;\\n  gap: var(--space-3);\\n  container-type: inline-size;\\n  container-name: db-activity;\\n\\n  .db-section__row-block-header {\\n    align-items: center;\\n    gap: var(--space-2);\\n\\n    @include container.until(sm, db-activity) {\\n      flex-direction: column;\\n      align-items: flex-start;\\n\\n      .select-kit.multi-select.multiple-categories-selector {\\n        max-width: none;\\n        width: 100%;\\n      }\\n    }\\n  }\\n\\n  th,\\n  td {\\n    white-space: nowrap;\\n  }\\n\\n  &__table-scroll-container {\\n    min-width: 0;\\n    overflow-x: auto;\\n  }\\n\\n  &__header {\\n    display: flex;\\n    justify-content: space-between;\\n    align-items: center;\\n    gap: var(--space-4);\\n  }\\n\\n  &__description {\\n    margin: 0;\\n    font-size: var(--font-down-1-rem);\\n    color: var(--primary-medium);\\n  }\\n\\n  &__empty {\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1-rem);\\n    margin: 0;\\n  }\\n}\\n\\n.db-activity-table {\\n  width: 100%;\\n  border-collapse: collapse;\\n\\n  thead th {\\n    color: var(--primary-high);\\n    font-size: var(--font-down-1-rem);\\n  }\\n\\n  tbody td:not(:first-child) {\\n    font-size: var(--font-down-1-rem);\\n  }\\n\\n  &__col-number,\\n  &__cell-number {\\n    text-align: center;\\n    font-variant-numeric: tabular-nums;\\n  }\\n\\n  &__sort-button {\\n    background: none;\\n    border: none;\\n    padding: 0;\\n    margin: 0;\\n    color: inherit;\\n    font: inherit;\\n    cursor: pointer;\\n    text-transform: inherit;\\n    letter-spacing: inherit;\\n\\n    .d-icon {\\n      &.is-hidden {\\n        visibility: hidden;\\n      }\\n    }\\n  }\\n\\n  &__cell-category {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-2);\\n    color: var(--primary);\\n  }\\n\\n  &__swatch {\\n    display: inline-block;\\n    width: 12px;\\n    height: 12px;\\n    border-radius: 2px;\\n    flex: 0 0 auto;\\n  }\\n}\\n\\n.db-whos-posting {\\n  display: flex;\\n  flex-direction: column;\\n  gap: var(--space-3);\\n  container-type: inline-size;\\n  container-name: db-whos-posting;\\n\\n  .db-section__row-block-header {\\n    align-items: center;\\n    gap: var(--space-2);\\n\\n    @include container.until(sm, db-whos-posting) {\\n      flex-direction: column;\\n      align-items: flex-start;\\n    }\\n  }\\n\\n  &__filter {\\n    display: flex;\\n    flex-direction: column;\\n    align-items: flex-end;\\n    gap: var(--space-1);\\n    flex-grow: 1;\\n    min-width: 0;\\n\\n    @include container.until(sm, db-whos-posting) {\\n      width: 100%;\\n      align-items: flex-start;\\n\\n      .select-kit.multi-select.multiple-categories-selector {\\n        max-width: none;\\n        width: 100%;\\n      }\\n    }\\n  }\\n\\n  &__bars {\\n    display: grid;\\n    grid-template-columns: minmax(0, auto) minmax(200px, 1fr) 2.5rem;\\n    gap: var(--space-2);\\n\\n    @container db-whos-posting (width < 22rem) {\\n      grid-template-columns: 1fr;\\n      gap: var(--space-3);\\n    }\\n  }\\n\\n  &__bar-row {\\n    display: grid;\\n    grid-column: 1 / -1;\\n    grid-template-columns: subgrid;\\n    align-items: center;\\n\\n    @container db-whos-posting (width < 22rem) {\\n      grid-template-columns: 1fr auto;\\n      gap: 0 var(--space-2);\\n    }\\n  }\\n\\n  &__bar-label {\\n    @include ellipsis;\\n\\n    @container db-whos-posting (width < 22rem) {\\n      grid-column: 1 / -1;\\n    }\\n  }\\n\\n  &__bar-track {\\n    height: $db-bar-height;\\n    border-radius: 1em;\\n    background: var(--primary-low);\\n  }\\n\\n  &__bar-fill {\\n    display: block;\\n    height: 100%;\\n    border-radius: 4px;\\n\\n    &.--new-members {\\n      background: var(--tertiary);\\n    }\\n\\n    &.--returning {\\n      background: var(--tertiary-medium);\\n    }\\n\\n    &.--staff {\\n      background: var(--primary-medium);\\n    }\\n\\n    &.--group-0 {\\n      background: var(--quaternary);\\n    }\\n\\n    &.--group-1 {\\n      background: var(--love);\\n    }\\n\\n    &.--group-2 {\\n      background: var(--success);\\n    }\\n\\n    &.--group-3 {\\n      background: var(--danger);\\n    }\\n\\n    &.--group-4 {\\n      background: var(--success-medium);\\n    }\\n\\n    &.--group-5 {\\n      background: var(--danger-medium);\\n    }\\n  }\\n\\n  &__bar-share {\\n    color: var(--primary-medium);\\n    font-variant-numeric: tabular-nums;\\n    text-align: right;\\n    line-height: 1;\\n  }\\n\\n  &__empty {\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1-rem);\\n    margin: 0;\\n  }\\n}\\n\\n.db-tl-pipeline {\\n  display: flex;\\n  flex-direction: column;\\n  gap: var(--space-2);\\n\\n  &__signups {\\n    margin-left: auto;\\n    font-size: var(--font-down-3);\\n    border-radius: var(--d-border-radius-pill);\\n    padding: var(--space-half) var(--space-2);\\n    background: var(--primary-low);\\n    white-space: nowrap;\\n  }\\n\\n  &__rows {\\n    list-style: none;\\n    padding: 0;\\n    margin: 0;\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-5);\\n  }\\n\\n  &__row {\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-2);\\n    padding-bottom: var(--space-3);\\n\\n    &:not(:last-child) {\\n      border-bottom: 1px solid var(--primary-low);\\n    }\\n  }\\n\\n  &__label {\\n    display: flex;\\n    align-items: baseline;\\n    gap: var(--space-2);\\n\\n    .db-pill {\\n      margin-left: auto;\\n      align-self: center;\\n    }\\n  }\\n\\n  &__name {\\n    color: var(--primary);\\n  }\\n\\n  &__count {\\n    font-size: var(--font-down-1-rem);\\n    color: var(--primary-medium);\\n  }\\n\\n  &__flow {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-2);\\n    min-height: 18px;\\n  }\\n\\n  &__bar-track {\\n    flex: 1 1 auto;\\n    min-width: 0;\\n    display: flex;\\n    justify-content: flex-start;\\n  }\\n\\n  &__bar {\\n    height: $db-bar-height;\\n    border-radius: 5px;\\n    flex: 0 0 auto;\\n    background: var(--success);\\n\\n    &.--demoted {\\n      background: var(--danger);\\n    }\\n  }\\n}\\n","@use \\"breakpoints\\";\\n\\n$breakpoints: breakpoints.$breakpoints;\\n\\n@function _container-name($name) {\\n  @if $name {\\n    @return \\"#{$name} \\";\\n  }\\n\\n  @return \\"\\";\\n}\\n\\n@mixin from($bp, $name: null) {\\n  @container #{_container-name($name)}(width >= #{breakpoints.get($bp)}) {\\n    @content;\\n  }\\n}\\n\\n@mixin until($bp, $name: null) {\\n  @container #{_container-name($name)}(width < #{breakpoints.get($bp)}) {\\n    @content;\\n  }\\n}\\n\\n@mixin between($from, $until, $name: null) {\\n  @container #{_container-name($name)}(#{breakpoints.get($from)} <= width < #{breakpoints.get($until)}) {\\n    @content;\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n$db-bar-height: var(--space-2);\\n\\n@import \\"admin/dashboard/engagement\\";\\n@import \\"admin/dashboard/highlights\\";\\n@import \\"admin/dashboard/reports\\";\\n@import \\"admin/dashboard/search\\";\\n@import \\"admin/dashboard/traffic\\";\\n@import \\"admin/dashboard/site-traffic-explorer\\";\\n\\n.db-site-advice {\\n  border: 1px solid var(--content-border-color);\\n  border-radius: var(--d-border-radius-large);\\n\\n  &__header {\\n    display: flex;\\n    align-items: center;\\n    justify-content: space-between;\\n    background: var(--primary-very-low);\\n    padding: var(--space-2) var(--space-4);\\n    border-top-left-radius: var(--d-border-radius-large);\\n    border-top-right-radius: var(--d-border-radius-large);\\n    border-bottom: 1px solid var(--content-border-color);\\n\\n    h3 {\\n      margin: 0;\\n      font-size: var(--font-0);\\n    }\\n  }\\n\\n  ul {\\n    list-style: none;\\n    padding: 0;\\n    margin: 0;\\n  }\\n\\n  &__list {\\n    display: flex;\\n    flex-direction: column;\\n  }\\n\\n  &__item {\\n    display: flex;\\n    align-items: center;\\n\\n    &:has(ul) {\\n      align-items: flex-start;\\n    }\\n\\n    @include viewport.until(sm) {\\n      align-items: flex-start;\\n    }\\n    gap: var(--space-3);\\n    padding: var(--space-4);\\n\\n    &:not(:last-child) {\\n      border-bottom: 1px solid var(--content-border-color);\\n    }\\n\\n    .btn {\\n      margin-left: auto;\\n    }\\n  }\\n\\n  &__icon {\\n    flex-shrink: 0;\\n    margin-top: 0.125rem;\\n\\n    &.--high {\\n      color: var(--danger);\\n    }\\n\\n    &.--low {\\n      color: var(--tertiary);\\n    }\\n  }\\n\\n  &__message {\\n    overflow-wrap: anywhere;\\n  }\\n}\\n\\n.db-main {\\n  display: flex;\\n  flex-direction: column;\\n  gap: var(--space-12);\\n  margin-bottom: var(--space-12);\\n}\\n\\n.db-delta {\\n  font-size: var(--font-down-2-rem);\\n  font-weight: bold;\\n\\n  table & {\\n    font-weight: normal;\\n  }\\n\\n  &.--pos {\\n    color: var(--success);\\n  }\\n\\n  &.--neg {\\n    color: var(--danger);\\n  }\\n}\\n\\n.dashboard-next .d-page-header__actions {\\n  @include viewport.until(md) {\\n    flex-direction: row;\\n    gap: var(--space-1);\\n    margin-block: var(--space-4);\\n  }\\n\\n  @include viewport.until(sm) {\\n    width: 100%;\\n  }\\n}\\n\\n.db-pill {\\n  font-size: var(--font-down-3);\\n  border-radius: 6.25rem;\\n  padding: var(--space-half) var(--space-2);\\n  background: var(--primary-low);\\n  white-space: nowrap;\\n\\n  &.--pos {\\n    background: var(--success);\\n    border: 1px solid var(--success);\\n    color: var(--secondary);\\n  }\\n\\n  &.--neg {\\n    background: var(--danger);\\n    border: 1px solid var(--danger);\\n    color: var(--secondary);\\n  }\\n}\\n\\n.db-bar-track {\\n  display: flex;\\n  height: $db-bar-height;\\n  border-radius: 1em;\\n  background: var(--primary-low);\\n  overflow: hidden;\\n}\\n\\n.db-bar-fill {\\n  display: block;\\n  height: 100%;\\n  border-radius: 4px;\\n  background: var(--tertiary);\\n  flex: 0 0 auto;\\n\\n  // a real but tiny segment would otherwise round away to nothing\\n  min-width: 2px;\\n\\n  &.--alt {\\n    background: var(--tertiary-medium);\\n  }\\n}\\n\\n.db-configure {\\n  padding: var(--space-4);\\n  max-width: 100%;\\n  box-sizing: border-box;\\n\\n  &__list {\\n    @include unstyled-list;\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-3);\\n\\n    @include viewport.until(sm) {\\n      gap: var(--space-5);\\n    }\\n  }\\n\\n  &__section-name {\\n    @include ellipsis;\\n  }\\n\\n  &__row {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-3);\\n    padding: var(--space-1) 0;\\n    border-top: 2px solid transparent;\\n    border-bottom: 2px solid transparent;\\n    cursor: grab;\\n\\n    &.dragging {\\n      opacity: 0.5;\\n    }\\n\\n    &.drag-above {\\n      border-top-color: var(--tertiary);\\n    }\\n\\n    &.drag-below {\\n      border-bottom-color: var(--tertiary);\\n    }\\n  }\\n\\n  &__section-name {\\n    margin-right: var(--space-2);\\n  }\\n\\n  &__drag-handle {\\n    color: var(--primary-low-mid);\\n    cursor: grab;\\n\\n    @include viewport.until(sm) {\\n      display: none;\\n    }\\n  }\\n\\n  &__arrows {\\n    display: flex;\\n    flex-direction: column;\\n  }\\n\\n  &__arrow.btn {\\n    padding: 0 var(--space-1);\\n    min-height: 0;\\n  }\\n\\n  .d-toggle-switch {\\n    margin-left: auto;\\n\\n    .d-icon-check {\\n      display: none;\\n    }\\n  }\\n}\\n\\n.db-main__empty {\\n  padding: var(--space-8);\\n  text-align: center;\\n  color: var(--primary-medium);\\n  background: var(--primary-very-low);\\n  border-radius: var(--d-border-radius);\\n}\\n\\n.db-main__error {\\n  padding: var(--space-8);\\n  text-align: center;\\n  color: var(--primary-medium);\\n  background: var(--primary-very-low);\\n  border-radius: var(--d-border-radius);\\n}\\n\\n.db-link-arrow {\\n  position: absolute;\\n  opacity: 0;\\n  font-size: var(--font-down-2-rem);\\n  transform: translateX(-4px);\\n  transition:\\n    opacity 0.15s,\\n    transform 0.15s;\\n  color: var(--tertiary);\\n}\\n\\n.db-section {\\n  display: flex;\\n  flex-direction: column;\\n  gap: var(--space-4);\\n\\n  &__info {\\n    font-size: var(--font-down-1-rem);\\n    color: var(--primary-low-mid);\\n  }\\n\\n  &__header-row {\\n    display: flex;\\n    justify-content: space-between;\\n    align-items: center;\\n  }\\n\\n  &__header {\\n    font-size: var(--font-down-2-rem);\\n    font-weight: 600;\\n    color: var(--primary-medium);\\n    text-transform: uppercase;\\n    margin: 0;\\n    letter-spacing: 1px;\\n  }\\n\\n  &__intro {\\n    max-width: 60ch;\\n    margin: 0;\\n  }\\n\\n  &__error {\\n    grid-column: 1 / -1;\\n    flex: 1;\\n    padding: var(--space-8);\\n    text-align: center;\\n    color: var(--primary-medium);\\n    background: var(--primary-very-low);\\n    border-radius: var(--d-border-radius);\\n    font-size: var(--font-down-1-rem);\\n  }\\n\\n  &__subheader {\\n    display: flex;\\n    justify-content: space-between;\\n    gap: var(--space-8);\\n\\n    @include viewport.until(sm) {\\n      flex-direction: column;\\n      gap: var(--space-4);\\n    }\\n  }\\n\\n  &__subintro {\\n    h3 {\\n      margin: 0;\\n    }\\n\\n    p {\\n      font-size: var(--font-down-1-rem);\\n      color: var(--primary-high);\\n      margin-bottom: 0;\\n    }\\n  }\\n\\n  &__metrics {\\n    display: flex;\\n    justify-content: flex-end;\\n    flex-grow: 1;\\n    gap: clamp(var(--space-2), var(--space-8), var(--space-8));\\n\\n    @include viewport.until(sm) {\\n      border-top: 1px solid var(--primary-low);\\n      padding-top: var(--space-2);\\n    }\\n  }\\n\\n  &__metric-number {\\n    white-space: nowrap;\\n    font-size: var(--font-up-3);\\n\\n    @include viewport.until(sm) {\\n      font-size: var(--font-up-2);\\n    }\\n  }\\n\\n  &__metric-label {\\n    white-space: nowrap;\\n    font-size: var(--font-down-2-rem);\\n    color: var(--primary-medium);\\n\\n    a {\\n      color: inherit;\\n    }\\n\\n    @include viewport.until(sm) {\\n      white-space: wrap;\\n    }\\n  }\\n\\n  &__callout {\\n    background: var(--primary-very-low);\\n    border: 1px solid var(--content-border-color);\\n    padding: var(--space-3) var(--space-4);\\n    border-radius: var(--d-border-radius-large);\\n    font-size: var(--font-down-1-rem);\\n  }\\n\\n  &__traffic-chart {\\n    min-height: 260px;\\n    height: 360px;\\n  }\\n\\n  &__traffic-chart-canvas,\\n  &__traffic-chart-canvas .chart-canvas,\\n  &__traffic-chart-canvas .chart-canvas-container {\\n    height: 100%;\\n  }\\n\\n  &__traffic-chart &__traffic-chart-canvas.admin-report-stacked-chart {\\n    height: 100%;\\n\\n    .chart-canvas-container {\\n      height: 100%;\\n    }\\n  }\\n\\n  &__traffic-chart-shell {\\n    height: 100%;\\n    border-radius: var(--d-border-radius-large);\\n    background: linear-gradient(\\n      135deg,\\n      var(--primary-very-low),\\n      var(--primary-low)\\n    );\\n  }\\n\\n  &__traffic-chart-message {\\n    min-height: 100%;\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    gap: var(--space-2);\\n    padding: var(--space-4);\\n    border-radius: var(--d-border-radius-large);\\n    background: var(--primary-very-low);\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1-rem);\\n  }\\n\\n  &__row {\\n    display: flex;\\n    flex-wrap: nowrap;\\n    gap: var(--space-4);\\n    border-top: 1px solid var(--primary-low);\\n    margin-inline: calc(var(--space-4) * -1);\\n\\n    @include viewport.until(sm) {\\n      flex-direction: column;\\n    }\\n  }\\n\\n  &__row-block {\\n    flex: 1;\\n    min-width: 0;\\n    padding: var(--space-4);\\n    box-sizing: border-box;\\n\\n    &:not(:last-child) {\\n      border-right: 1px solid var(--content-border-color);\\n    }\\n\\n    @include viewport.until(sm) {\\n      &:not(:last-child) {\\n        border-right: 0;\\n        border-bottom: 1px solid var(--content-border-color);\\n      }\\n    }\\n  }\\n\\n  &__row-block-header {\\n    display: flex;\\n    align-items: center;\\n    justify-content: space-between;\\n    margin-bottom: var(--space-2);\\n\\n    .select-kit.combo-box.category-chooser {\\n      width: 100%;\\n      max-width: 300px;\\n    }\\n  }\\n\\n  &__row-block-title,\\n  &__row-block-title > a {\\n    color: var(--primary);\\n    font-weight: bold;\\n    font-size: var(--font-down-1-rem);\\n    white-space: nowrap;\\n\\n    &:hover,\\n    &:focus,\\n    &:visited,\\n    &:active {\\n      color: var(--primary);\\n    }\\n\\n    .db-link-arrow {\\n      top: 0;\\n      inset-inline-end: calc(var(--space-6) * -1);\\n      margin-inline-start: var(--space-4);\\n    }\\n  }\\n\\n  &__wrapper {\\n    border-radius: var(--d-border-radius-large);\\n    border: 1px solid var(--content-border-color);\\n\\n    &.--no-border {\\n      border: none;\\n      border-radius: 0;\\n      padding: 0;\\n    }\\n\\n    &.--grid {\\n      display: grid;\\n      grid-template-columns: repeat(2, minmax(0, 1fr));\\n      grid-auto-rows: 320px;\\n      gap: var(--space-4);\\n\\n      @include viewport.until(sm) {\\n        grid-template-columns: minmax(0, 1fr);\\n      }\\n    }\\n\\n    &.--row {\\n      display: flex;\\n      flex-wrap: nowrap;\\n\\n      @include viewport.until(sm) {\\n        flex-wrap: wrap;\\n        gap: var(--space-1);\\n        border: none;\\n      }\\n    }\\n\\n    &.--column {\\n      display: flex;\\n      flex-direction: column;\\n      gap: var(--space-4);\\n      padding: var(--space-4);\\n\\n      &:has(.db-section__row-block) {\\n        padding-bottom: 0;\\n      }\\n    }\\n  }\\n\\n  &__footer {\\n    display: flex;\\n    justify-content: space-between;\\n  }\\n}\\n\\n.db-group {\\n  display: flex;\\n  align-items: center;\\n  gap: var(--space-2);\\n}\\n\\n.db-system {\\n  &__block {\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-2);\\n\\n    &:first-of-type {\\n      border-top-left-radius: var(--d-border-radius-large);\\n      border-bottom-left-radius: var(--d-border-radius-large);\\n    }\\n\\n    &:last-of-type {\\n      border-top-right-radius: var(--d-border-radius-large);\\n      border-bottom-right-radius: var(--d-border-radius-large);\\n    }\\n  }\\n\\n  &__value {\\n    font-size: var(--font-up-3-rem);\\n    font-weight: 500;\\n    color: var(--primary);\\n  }\\n\\n  &__label {\\n    font-size: var(--font-down-1-rem);\\n    color: var(--primary-medium);\\n  }\\n\\n  &__breakdown {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-1);\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1-rem);\\n  }\\n\\n  &__link {\\n    font-size: var(--font-down-1-rem);\\n  }\\n\\n  &__footer {\\n    display: flex;\\n    align-items: center;\\n    margin-top: auto;\\n\\n    &.--critical {\\n      .db-system__label {\\n        color: var(--danger);\\n      }\\n    }\\n\\n    .--storage & {\\n      justify-content: space-between;\\n    }\\n\\n    .--status & {\\n      justify-content: flex-end;\\n    }\\n  }\\n\\n  &__status-icon {\\n    .--ok & {\\n      color: var(--success);\\n    }\\n\\n    .--warning &,\\n    .--critical & {\\n      color: var(--danger);\\n    }\\n  }\\n}\\n\\n.--system {\\n  @include viewport.until(sm) {\\n    .db-section__row-block {\\n      border-radius: var(--d-border-radius-large);\\n      flex-basis: calc(50% - var(--space-1));\\n      border: 1px solid var(--content-border-color);\\n    }\\n  }\\n}\\n\\n.db-bar-track {\\n  .--system & {\\n    margin-block: var(--space-2);\\n  }\\n}\\n\\n.db-bar-fill {\\n  &:first-child {\\n    .--system & {\\n      border-top-right-radius: 0;\\n      border-bottom-right-radius: 0;\\n    }\\n  }\\n\\n  &:nth-child(2) {\\n    .--system & {\\n      border-top-left-radius: 0;\\n      border-bottom-left-radius: 0;\\n    }\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.db-kpi {\\n  position: relative;\\n  display: flex;\\n  flex-direction: column;\\n  gap: var(--space-2);\\n\\n  &:first-of-type {\\n    border-top-left-radius: var(--d-border-radius-large);\\n    border-bottom-left-radius: var(--d-border-radius-large);\\n  }\\n\\n  &:last-of-type {\\n    border-top-right-radius: var(--d-border-radius-large);\\n    border-bottom-right-radius: var(--d-border-radius-large);\\n  }\\n\\n  .db-link-arrow {\\n    top: var(--space-4);\\n    inset-inline-end: var(--space-4);\\n  }\\n\\n  &:hover {\\n    background: var(--primary-very-low);\\n\\n    .db-link-arrow {\\n      opacity: 1;\\n      transform: translateX(0);\\n    }\\n  }\\n\\n  &__value-row {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-2);\\n  }\\n\\n  &__value {\\n    font-size: var(--font-up-3-rem);\\n    font-weight: 500;\\n    color: var(--primary);\\n  }\\n\\n  &__label {\\n    font-size: var(--font-down-1-rem);\\n    color: var(--primary-medium);\\n  }\\n}\\n\\n.--kpi .db-section__intro {\\n  font-size: var(--font-up-1-rem);\\n}\\n\\n.--highlights {\\n  @include viewport.until(sm) {\\n    .db-section__row-block {\\n      border-radius: var(--d-border-radius-large);\\n      flex-basis: calc(50% - var(--space-1));\\n      border: 1px solid var(--content-border-color);\\n    }\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.db-report {\\n  &__card {\\n    position: relative;\\n    border: 1px solid var(--content-border-color);\\n    border-radius: var(--d-border-radius-large);\\n    padding: var(--space-4);\\n    box-sizing: border-box;\\n    background: var(--secondary);\\n    height: 320px;\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-2);\\n\\n    @include viewport.until(sm) {\\n      padding-inline: 0;\\n      padding-bottom: 0;\\n\\n      &::after {\\n        content: \\"\\";\\n        position: absolute;\\n        bottom: -1px;\\n        left: 0;\\n        right: 0;\\n        background: linear-gradient(\\n          to bottom,\\n          rgb(var(--secondary-rgb), 0),\\n          rgb(var(--secondary-rgb), 0.5)\\n        );\\n        height: var(--space-2);\\n      }\\n    }\\n\\n    &.--wide {\\n      grid-column: 1 / -1;\\n    }\\n\\n    &.--wide,\\n    &.--rows-2,\\n    &.--rows-3,\\n    &.--rows-4 {\\n      .db-report__chart {\\n        overflow-y: auto;\\n      }\\n    }\\n\\n    @for $rows from 2 through 4 {\\n      &.--rows-#{$rows} {\\n        grid-row: span #{$rows};\\n        height: auto;\\n      }\\n    }\\n\\n    &.--floating {\\n      position: fixed;\\n      z-index: 100;\\n    }\\n\\n    &.--resize-placeholder {\\n      margin: calc(var(--space-2) * -1);\\n      border-style: dashed;\\n      border-color: var(--tertiary);\\n      background: var(--tertiary-low);\\n\\n      &:not(.--rows-2, .--rows-3, .--rows-4) {\\n        height: calc(320px + var(--space-2) * 2);\\n      }\\n    }\\n\\n    &:hover .db-report__resize-handle,\\n    &:focus-within .db-report__resize-handle {\\n      opacity: 1;\\n    }\\n  }\\n\\n  &__resize-handle {\\n    position: absolute;\\n    bottom: 2px;\\n    width: 12px;\\n    height: 12px;\\n    opacity: 0.35;\\n\\n    @media (prefers-reduced-motion: no-preference) {\\n      transition: opacity 0.15s ease;\\n    }\\n\\n    &.--se {\\n      /*! rtl:ignore */\\n      right: 2px;\\n\\n      /*! rtl:ignore */\\n      cursor: nwse-resize;\\n\\n      /*! rtl:ignore */\\n      clip-path: polygon(100% 0, 100% 100%, 0 100%);\\n\\n      /*! rtl:ignore */\\n      background: repeating-linear-gradient(\\n        135deg,\\n        var(--primary-medium) 0,\\n        var(--primary-medium) 1px,\\n        transparent 1px,\\n        transparent 4px\\n      );\\n    }\\n\\n    &.--sw {\\n      /*! rtl:ignore */\\n      left: 2px;\\n\\n      /*! rtl:ignore */\\n      cursor: nesw-resize;\\n\\n      /*! rtl:ignore */\\n      clip-path: polygon(0 0, 100% 100%, 0 100%);\\n\\n      /*! rtl:ignore */\\n      background: repeating-linear-gradient(\\n        45deg,\\n        var(--primary-medium) 0,\\n        var(--primary-medium) 1px,\\n        transparent 1px,\\n        transparent 4px\\n      );\\n    }\\n\\n    &.--resizing {\\n      opacity: 1;\\n    }\\n\\n    @include viewport.until(sm) {\\n      display: none;\\n    }\\n  }\\n\\n  &__header {\\n    position: relative;\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-2);\\n    flex: 0 0 auto;\\n\\n    @include viewport.until(sm) {\\n      padding-inline: var(--space-4);\\n\\n      &::after {\\n        content: \\"\\";\\n        position: absolute;\\n        bottom: calc(var(--space-4) * -1);\\n        left: 0;\\n        right: 0;\\n        background: linear-gradient(\\n          to top,\\n          rgb(var(--secondary-rgb), 0),\\n          rgb(var(--secondary-rgb), 0.5)\\n        );\\n        height: var(--space-2);\\n        z-index: 1;\\n      }\\n    }\\n  }\\n\\n  &__name {\\n    display: flex;\\n    align-items: center;\\n    font-size: var(--font-down-1-rem);\\n    font-weight: 600;\\n    color: var(--primary);\\n\\n    &:visited,\\n    &:hover,\\n    &:active {\\n      color: var(--primary);\\n    }\\n  }\\n\\n  &__label {\\n    background: var(--tertiary-low);\\n    color: var(--tertiary);\\n    border-radius: 4px;\\n    font-size: var(--font-down-3);\\n    padding: var(--space-half) var(--space-2);\\n    font-weight: 400;\\n    white-space: nowrap;\\n\\n    @include viewport.until(sm) {\\n      position: absolute;\\n      top: 0;\\n      right: var(--space-3);\\n      transform: translateY(-40%);\\n    }\\n  }\\n\\n  &__remove {\\n    margin-left: auto;\\n  }\\n\\n  &__chart {\\n    overflow: auto;\\n    flex: 1 1 auto;\\n    min-height: 0;\\n\\n    .admin-report,\\n    .admin-report-chart,\\n    .chart-canvas-container,\\n    .chart-canvas {\\n      width: 100% !important; // no other way to overrule the JS inline styling\\n      height: 100% !important;\\n    }\\n\\n    .loading-container {\\n      display: flex;\\n      align-items: center;\\n      justify-content: center;\\n      height: 100%;\\n    }\\n  }\\n\\n  &__empty,\\n  &__error {\\n    display: flex;\\n    flex-direction: column;\\n    align-items: center;\\n    justify-content: center;\\n    gap: var(--space-2);\\n    height: 100%;\\n    color: var(--primary-medium);\\n\\n    .d-icon {\\n      font-size: var(--font-up-3);\\n    }\\n  }\\n\\n  &__error {\\n    color: var(--danger);\\n  }\\n\\n  &__add-report {\\n    border: 1px dashed var(--content-border-color);\\n    border-radius: var(--d-border-radius-large);\\n    background: var(--secondary);\\n    color: var(--primary-medium);\\n    padding: var(--space-2);\\n\\n    &:hover,\\n    &:focus {\\n      background: var(--tertiary-low);\\n      border-color: var(--tertiary);\\n      color: var(--tertiary);\\n    }\\n  }\\n}\\n\\n.db-reports {\\n  display: contents;\\n}\\n",".db-search-table {\\n  width: 100%;\\n  table-layout: fixed;\\n\\n  th,\\n  td {\\n    @include ellipsis;\\n  }\\n\\n  thead th {\\n    color: var(--primary-high);\\n    font-size: var(--font-down-1-rem);\\n  }\\n\\n  tbody td:not(:has(.db-pill)) {\\n    font-size: var(--font-down-1-rem);\\n  }\\n\\n  &__col-status,\\n  &__col-number {\\n    width: 20%;\\n  }\\n\\n  &__col-number,\\n  &__cell-number {\\n    text-align: center;\\n    font-variant-numeric: tabular-nums;\\n  }\\n\\n  &__empty {\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1-rem);\\n    margin: 0;\\n  }\\n}\\n",".db-traffic {\\n  --db-traffic-card-min-height: 12rem;\\n  display: flex;\\n  flex-direction: column;\\n  gap: var(--space-4);\\n  transition: opacity 0.15s ease;\\n\\n  &.is-loading {\\n    opacity: 0.55;\\n  }\\n\\n  &__trend {\\n    &.--up {\\n      color: var(--success);\\n    }\\n\\n    &.--down {\\n      color: var(--danger);\\n    }\\n  }\\n\\n  &__list {\\n    display: grid;\\n    grid-template-columns: minmax(0, 1fr) auto;\\n    column-gap: var(--space-4);\\n    row-gap: var(--space-2);\\n    list-style: none;\\n    margin: 0;\\n    padding: 0;\\n    font-size: var(--font-down-1-rem);\\n  }\\n\\n  &__list-row {\\n    display: contents;\\n  }\\n\\n  &__metric {\\n    display: inline-flex;\\n    align-items: baseline;\\n    gap: var(--space-1);\\n    justify-self: end;\\n  }\\n\\n  &__name,\\n  &__link {\\n    display: inline-flex;\\n    align-items: center;\\n    gap: 0.5em;\\n    min-width: 0;\\n  }\\n\\n  &__label {\\n    overflow: hidden;\\n    text-overflow: ellipsis;\\n    white-space: nowrap;\\n    min-width: 0;\\n  }\\n\\n  &__name {\\n    color: var(--primary-high);\\n  }\\n\\n  &__link {\\n    color: inherit;\\n    text-decoration: none;\\n\\n    &:visited {\\n      color: inherit;\\n    }\\n\\n    &:hover {\\n      text-decoration: underline;\\n    }\\n\\n    &:focus-visible {\\n      outline: 2px solid var(--tertiary);\\n      outline-offset: 2px;\\n    }\\n  }\\n\\n  &__list-shell {\\n    height: var(--db-traffic-card-min-height);\\n    border-radius: var(--d-border-radius-large);\\n    background: linear-gradient(\\n      135deg,\\n      var(--primary-very-low),\\n      var(--primary-low)\\n    );\\n  }\\n\\n  &__percent {\\n    color: var(--primary);\\n  }\\n\\n  &__count {\\n    color: var(--primary-medium);\\n  }\\n\\n  &__list-empty {\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1-rem);\\n  }\\n\\n  &__list-error {\\n    color: var(--danger);\\n    font-size: var(--font-down-1-rem);\\n  }\\n\\n  &__see-details,\\n  &__learn-more {\\n    align-self: flex-end;\\n    display: inline-flex;\\n    align-items: center;\\n    gap: var(--space-1);\\n    font-size: var(--font-down-1-rem);\\n  }\\n\\n  &__learn-more,\\n  &__learn-more:visited {\\n    color: var(--primary-medium);\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.site-traffic-explorer {\\n  display: flex;\\n  flex-direction: column;\\n  gap: var(--space-4);\\n  padding-bottom: var(--space-8);\\n\\n  .db-section__subheader {\\n    justify-content: flex-end;\\n  }\\n\\n  &__filters {\\n    display: flex;\\n    flex-wrap: wrap;\\n    align-items: center;\\n    min-width: 0;\\n    gap: var(--space-2);\\n  }\\n\\n  &__filter-dropdown {\\n    .d-button-label {\\n      @include ellipsis;\\n    }\\n  }\\n\\n  &__filter-controls {\\n    display: flex;\\n    align-items: flex-start;\\n    justify-content: space-between;\\n    gap: var(--space-2);\\n\\n    @include viewport.until(sm) {\\n      flex-wrap: wrap;\\n    }\\n  }\\n\\n  &__filter-actions {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-2);\\n    margin-inline-start: auto;\\n\\n    .btn {\\n      padding-block: var(--space-1);\\n    }\\n  }\\n\\n  &__filter-apply {\\n    gap: var(--space-2);\\n  }\\n\\n  &__filter-apply-pending-count {\\n    color: var(--tertiary);\\n    background: var(--secondary);\\n    padding: 0.21em 0.42em;\\n    min-width: 0.6em;\\n    border-radius: 1em;\\n    font-size: var(--font-down-2-rem);\\n    font-weight: 600;\\n  }\\n\\n  &__filter-pill {\\n    display: inline-flex;\\n    align-items: center;\\n    gap: var(--space-1);\\n    min-width: 0;\\n    max-width: 100%;\\n    white-space: nowrap;\\n    padding-inline-start: var(--space-3);\\n    border: 1px solid var(--primary-low);\\n    border-radius: var(--d-border-radius-pill);\\n    background: var(--primary-very-low);\\n    font-size: var(--font-down-1-rem);\\n\\n    &.is-pending {\\n      border-color: var(--tertiary);\\n      border-style: dashed;\\n      background: var(--tertiary-very-low);\\n    }\\n\\n    .site-traffic-explorer__filter-pill-remaining,\\n    .d-icon-angle-down {\\n      color: var(--primary-medium);\\n    }\\n\\n    .fk-d-menu__trigger {\\n      min-width: 0;\\n      gap: var(--space-1);\\n      border: 0;\\n      padding: 0;\\n      background: transparent;\\n      color: inherit;\\n\\n      &:hover,\\n      &.-expanded {\\n        border: 0;\\n        padding: 0;\\n        background: transparent;\\n        color: inherit;\\n\\n        .site-traffic-explorer__filter-pill-remaining,\\n        .d-icon-angle-down {\\n          color: var(--primary);\\n        }\\n      }\\n\\n      &.-expanded .d-icon-angle-down {\\n        transform: rotate(180deg);\\n      }\\n    }\\n  }\\n\\n  &__filter-remove {\\n    color: var(--primary-medium);\\n    border-top-right-radius: var(--d-border-radius-pill);\\n    border-bottom-right-radius: var(--d-border-radius-pill);\\n    border-top-left-radius: 0;\\n    border-bottom-left-radius: 0;\\n    border-left: 1px solid var(--primary-low);\\n  }\\n\\n  &__filter-pill-values {\\n    @include ellipsis;\\n    display: inline-flex;\\n  }\\n\\n  &__filter-pill-value {\\n    flex-grow: 1;\\n    overflow: hidden;\\n    text-overflow: ellipsis;\\n    font-weight: 600;\\n  }\\n\\n  &__partial-warning {\\n    margin: 0;\\n  }\\n\\n  &__empty {\\n    border-radius: var(--d-border-radius);\\n    padding: var(--space-3) var(--space-4);\\n    border: 1px dashed var(--content-border-color);\\n    background: var(--primary-very-low);\\n    text-align: center;\\n  }\\n\\n  &__skeleton {\\n    .db-skeleton__section-wrapper {\\n      overflow: hidden;\\n      padding-bottom: 0;\\n    }\\n\\n    .db-skeleton__heading-line {\\n      width: min(24rem, 100%);\\n      height: 1.625rem;\\n    }\\n\\n    .db-skeleton__metric {\\n      gap: var(--space-1);\\n    }\\n\\n    .db-skeleton__metric-number {\\n      height: 2.125rem;\\n    }\\n\\n    .db-skeleton__metric-label {\\n      height: 1.22rem;\\n    }\\n\\n    .db-skeleton__chart {\\n      height: 360px;\\n      min-height: 260px;\\n    }\\n\\n    .db-skeleton__row-block-title {\\n      height: 2.4rem;\\n    }\\n\\n    .db-skeleton__list {\\n      gap: 0;\\n    }\\n\\n    .db-skeleton__list-row {\\n      min-height: 1.72rem;\\n    }\\n\\n    @include viewport.until(md) {\\n      .db-skeleton__subheader {\\n        flex-direction: column;\\n        gap: var(--space-4);\\n      }\\n\\n      .db-skeleton__metric-row {\\n        display: grid;\\n        grid-template-columns: repeat(2, minmax(0, 1fr));\\n      }\\n\\n      .db-skeleton__row {\\n        flex-direction: column;\\n      }\\n\\n      .db-skeleton__row-block:not(:last-child) {\\n        border-right: 0;\\n        border-bottom: 1px solid var(--primary-low);\\n      }\\n    }\\n\\n    @include viewport.until(sm) {\\n      .db-skeleton__chart {\\n        height: 18rem;\\n      }\\n    }\\n  }\\n\\n  .db-section__metrics {\\n    @include viewport.until(sm) {\\n      flex-wrap: wrap;\\n    }\\n  }\\n\\n  .db-section__metric-label {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-1);\\n\\n    .db-section__info {\\n      font-size: inherit;\\n    }\\n  }\\n\\n  .db-section__row-block {\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-3);\\n  }\\n\\n  &__tabs {\\n    display: flex;\\n    flex-wrap: wrap;\\n    gap: 0 var(--space-4);\\n    min-width: 0;\\n    border-bottom: 1px solid var(--content-border-color);\\n\\n    button {\\n      border: 0;\\n      border-bottom: 2px solid transparent;\\n      padding-bottom: var(--space-2);\\n      padding-inline: 0;\\n      background: transparent;\\n      color: var(--primary-high);\\n      font-size: var(--font-down-1-rem);\\n      white-space: nowrap;\\n\\n      &.is-active {\\n        border-bottom-color: var(--tertiary);\\n        color: var(--tertiary);\\n      }\\n    }\\n  }\\n\\n  &__breakdown-list {\\n    @include unstyled-list;\\n    font-size: var(--font-down-1-rem);\\n    margin-block-end: var(--space-2);\\n  }\\n\\n  &__row {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-1);\\n    margin-inline: calc(-1 * var(--space-2));\\n    border-radius: var(--d-border-radius);\\n    padding-inline: var(--space-2);\\n    cursor: pointer;\\n\\n    html.discourse-no-touch &:hover:not(:has(a:hover)) {\\n      background: var(--token-color-surface-hovered);\\n    }\\n  }\\n\\n  &__row-count {\\n    flex-shrink: 0;\\n    margin-inline-start: auto;\\n    color: var(--primary-medium);\\n  }\\n\\n  &__row-link {\\n    @include ellipsis;\\n    flex: 0 1 auto;\\n    min-width: 0;\\n    color: inherit;\\n    text-decoration: none;\\n    margin: 0;\\n    margin-right: var(\\n      --space-4\\n    ); // leave extra space on purpose to click the row not the link\\n\\n    &:hover {\\n      .discourse-no-touch & {\\n        color: var(--tertiary);\\n        text-decoration: underline;\\n      }\\n    }\\n\\n    &:visited {\\n      color: inherit;\\n    }\\n\\n    &:focus-visible {\\n      color: var(--tertiary);\\n      text-decoration: underline;\\n    }\\n  }\\n\\n  &__dimension-label {\\n    display: flex;\\n    flex: 1 1 auto;\\n    align-items: center;\\n    min-width: 0;\\n    gap: var(--space-2);\\n    padding-block: var(--space-1);\\n  }\\n\\n  &__dimension-text {\\n    @include ellipsis;\\n    flex: 1 1 auto;\\n    min-width: 0;\\n  }\\n\\n  &__card-empty {\\n    padding-block: var(--space-3);\\n    color: var(--primary-medium);\\n  }\\n}\\n\\n// The global `label` rule in common/base/discourse.scss wins on specificity\\n// over the block class, so these resets have to match it at element level.\\nlabel.site-traffic-explorer__row {\\n  margin-block: 0;\\n  font-weight: inherit;\\n}\\n\\n.site-traffic-breakdown-modal {\\n  .site-traffic-explorer__breakdown-list {\\n    font-size: var(--font-0);\\n  }\\n\\n  .site-traffic-explorer__dimension-label {\\n    padding-block: var(--space-2);\\n  }\\n}\\n",".db-skeleton {\\n  --db-skeleton-animation-rgb: #{hexToRGB($primary-50)};\\n  display: flex;\\n  flex-direction: column;\\n  gap: var(--space-12);\\n\\n  &__section {\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-4);\\n  }\\n\\n  &__section-header {\\n    background: var(--primary-low);\\n    border-radius: var(--d-border-radius);\\n    height: 14px;\\n    width: 140px;\\n  }\\n\\n  &__section-wrapper {\\n    border: 1px solid var(--primary-low);\\n    border-radius: var(--d-border-radius-large);\\n    padding: var(--space-4);\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-4);\\n\\n    // negative margin offsets the wrapper padding so the row's top border spans full width\\n    .db-skeleton__row {\\n      margin-inline: calc(var(--space-4) * -1);\\n    }\\n  }\\n\\n  &__kpi-row {\\n    display: flex;\\n    flex-wrap: nowrap;\\n    gap: var(--space-4);\\n    border: 1px solid var(--primary-low);\\n    border-radius: var(--d-border-radius-large);\\n  }\\n\\n  &__kpi {\\n    flex: 1;\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-2);\\n    padding: var(--space-4);\\n\\n    &:not(:last-child) {\\n      border-right: 1px solid var(--primary-low);\\n    }\\n  }\\n\\n  &__kpi-value {\\n    background: var(--primary-200);\\n    border-radius: var(--d-border-radius);\\n    width: 60%;\\n    height: 28px;\\n  }\\n\\n  &__kpi-label {\\n    background: var(--primary-low);\\n    border-radius: var(--d-border-radius);\\n    width: 75%;\\n    height: 12px;\\n  }\\n\\n  &__kpi-delta {\\n    background: var(--primary-low);\\n    border-radius: var(--d-border-radius);\\n    width: 30%;\\n    height: 12px;\\n  }\\n\\n  &__report-grid {\\n    display: grid;\\n    grid-template-columns: 1fr 1fr;\\n    gap: var(--space-4);\\n  }\\n\\n  &__report-card {\\n    border: 1px solid var(--primary-low);\\n    border-radius: var(--d-border-radius-large);\\n    padding: var(--space-4);\\n    box-sizing: border-box;\\n    background: var(--secondary);\\n    height: 250px;\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-3);\\n  }\\n\\n  &__report-card-header {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-2);\\n  }\\n\\n  &__report-card-title {\\n    background: var(--primary-200);\\n    border-radius: var(--d-border-radius);\\n    width: 40%;\\n    height: 14px;\\n  }\\n\\n  &__report-card-label {\\n    background: var(--primary-low);\\n    border-radius: var(--d-border-radius);\\n    width: 64px;\\n    height: 14px;\\n  }\\n\\n  &__report-card-chart {\\n    background: var(--primary-low);\\n    border-radius: var(--d-border-radius);\\n    flex: 1;\\n  }\\n\\n  &__subheader {\\n    display: flex;\\n    justify-content: space-between;\\n    gap: var(--space-8);\\n  }\\n\\n  &__subintro {\\n    flex: 1;\\n    max-width: 60ch;\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-2);\\n  }\\n\\n  &__heading-line {\\n    background: var(--primary-200);\\n    border-radius: var(--d-border-radius);\\n    width: 70%;\\n    height: 16px;\\n  }\\n\\n  &__text-line {\\n    background: var(--primary-low);\\n    border-radius: var(--d-border-radius);\\n    width: 100%;\\n    height: 10px;\\n\\n    &.--short {\\n      width: 80%;\\n    }\\n  }\\n\\n  &__metric-row {\\n    display: flex;\\n    justify-content: flex-end;\\n    gap: var(--space-10);\\n  }\\n\\n  &__metric {\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-2);\\n    align-items: flex-start;\\n  }\\n\\n  &__metric-number {\\n    background: var(--primary-200);\\n    border-radius: var(--d-border-radius);\\n    width: 60px;\\n    height: 22px;\\n  }\\n\\n  &__metric-label {\\n    background: var(--primary-low);\\n    border-radius: var(--d-border-radius);\\n    width: 90px;\\n    height: 10px;\\n  }\\n\\n  &__chart {\\n    background: var(--primary-low);\\n    border-radius: var(--d-border-radius);\\n    height: 240px;\\n    width: 100%;\\n  }\\n\\n  &__row {\\n    display: flex;\\n    flex-wrap: nowrap;\\n    gap: var(--space-4);\\n    border-top: 1px solid var(--primary-low);\\n  }\\n\\n  &__row-block {\\n    flex: 1;\\n    padding: var(--space-4);\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-3);\\n\\n    &:not(:last-child) {\\n      border-right: 1px solid var(--primary-low);\\n    }\\n\\n    &.--full {\\n      flex: 1 1 100%;\\n    }\\n  }\\n\\n  &__row-block-title {\\n    background: var(--primary-200);\\n    border-radius: var(--d-border-radius);\\n    width: 35%;\\n    height: 14px;\\n  }\\n\\n  &__list {\\n    @include unstyled-list;\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-2);\\n  }\\n\\n  &__list-row {\\n    display: flex;\\n    justify-content: space-between;\\n    align-items: center;\\n    gap: var(--space-4);\\n  }\\n\\n  &__list-name {\\n    background: var(--primary-low);\\n    border-radius: var(--d-border-radius);\\n    height: 12px;\\n    flex: 0 1 60%;\\n  }\\n\\n  &__list-value {\\n    background: var(--primary-low);\\n    border-radius: var(--d-border-radius);\\n    height: 12px;\\n    width: 50px;\\n  }\\n\\n  &__pipeline {\\n    background: var(--primary-low);\\n    border-radius: var(--d-border-radius);\\n    height: 60px;\\n    width: 100%;\\n  }\\n\\n  *[class*=\\"db-skeleton__\\"]:not(\\n      .db-skeleto