ilter__input-container {\\n  min-width: 50%;\\n\\n  @media screen and (width <= 500px) {\\n    width: 100%;\\n  }\\n\\n  input {\\n    min-width: 15em;\\n    margin: 0;\\n\\n    @media screen and (width <= 500px) {\\n      box-sizing: border-box;\\n      width: 100%;\\n    }\\n  }\\n}\\n\\n.admin-filter__input {\\n  width: 100%;\\n}\\n",".admin-reports {\\n  .admin-report {\\n    width: 100%;\\n\\n    .report-header {\\n      padding-bottom: 0.5em;\\n      margin-bottom: 1em;\\n      border-bottom: 1px solid var(--content-border-color);\\n    }\\n  }\\n\\n  .admin-report-chart .chart-canvas-container {\\n    height: clamp(200px, 50vh, 350px);\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.admin-report {\\n  .select-kit {\\n    @include viewport.from(sm) {\\n      width: auto;\\n      max-width: 250px;\\n    }\\n\\n    @include viewport.until(sm) {\\n      width: 100% !important;\\n    }\\n  }\\n\\n  .conditional-loading-section {\\n    &.is-loading {\\n      margin: 0;\\n    }\\n  }\\n\\n  .header {\\n    display: flex;\\n    align-items: center;\\n    margin-bottom: 0.5em;\\n  }\\n\\n  .header .breadcrumb {\\n    margin: 0;\\n    list-style: none;\\n\\n    .item {\\n      display: inline;\\n      font-size: var(--font-up-1);\\n    }\\n\\n    .all-reports .report-url {\\n      font-weight: 700;\\n    }\\n\\n    .report {\\n      font-weight: 700;\\n\\n      .report-url {\\n        color: var(--primary);\\n      }\\n\\n      .info {\\n        cursor: pointer;\\n        margin-left: 0.25em;\\n        color: var(--primary-low-mid);\\n\\n        &:hover {\\n          color: var(--primary-medium);\\n        }\\n      }\\n    }\\n  }\\n\\n  .header .trend {\\n    margin-left: auto;\\n    margin-right: 8px;\\n\\n    &.trending-down,\\n    &.high-trending-down {\\n      color: var(--danger);\\n    }\\n\\n    &.trending-up,\\n    &.high-trending-up {\\n      color: var(--success);\\n    }\\n\\n    &.no-change {\\n      color: var(--primary-medium);\\n\\n      .d-icon {\\n        display: none;\\n      }\\n    }\\n\\n    .value {\\n      font-size: var(--font-up-1);\\n    }\\n\\n    .icon {\\n      font-size: var(--font-up-1);\\n      font-weight: 700;\\n    }\\n  }\\n\\n  .d-page-subheader__title a {\\n    color: var(--primary);\\n  }\\n\\n  .report-alert {\\n    margin: 0;\\n    text-align: center;\\n    padding: 3em;\\n    border: 1px solid transparent;\\n\\n    a {\\n      color: var(--primary-high);\\n    }\\n\\n    .d-icon {\\n      color: var(--primary-medium);\\n      font-size: var(--font-up-5);\\n      display: block;\\n      margin: 0.25em auto;\\n    }\\n\\n    &.no-data,\\n    &.rate-limited {\\n      background: var(--secondary);\\n      border-color: var(--primary-low);\\n      color: var(--primary);\\n    }\\n\\n    &.rate-limited .d-icon {\\n      color: var(--danger);\\n    }\\n\\n    &.timeout,\\n    &.exception {\\n      border-color: var(--danger-low);\\n      color: var(--danger);\\n    }\\n  }\\n}\\n\\n.rtl .admin-report {\\n  .trend {\\n    margin-left: unset;\\n    margin-right: auto;\\n  }\\n}\\n\\n.admin-reports-header {\\n  display: flex;\\n  align-items: center;\\n  justify-content: space-between;\\n  border-bottom: 1px solid var(--content-border-color);\\n  padding-bottom: 0.5em;\\n\\n  @media screen and (width <= 400px) {\\n    flex-wrap: wrap;\\n  }\\n\\n  h2 {\\n    margin: 0 0.5em 0 0;\\n\\n    a {\\n      color: var(--primary);\\n    }\\n  }\\n}\\n\\n.admin-reports-list {\\n  display: flex;\\n  flex-wrap: wrap;\\n  list-style-type: none;\\n\\n  &.admin-section-landing-wrapper {\\n    gap: 1em;\\n    padding-top: 0;\\n\\n    .admin-section-landing-item {\\n      border-radius: var(--d-border-radius);\\n      border: 1px solid var(--content-border-color);\\n      margin-bottom: 0;\\n\\n      @include viewport.from(sm) {\\n        margin-bottom: 0;\\n      }\\n\\n      &:hover {\\n        border: 1px solid var(--primary-low-mid);\\n      }\\n    }\\n  }\\n}\\n\\n.mobile-view {\\n  .admin-report.post-edits 