hart {\\n  animation: fadein 2s;\\n\\n  @media (prefers-reduced-motion) {\\n    animation-duration: 0s;\\n  }\\n}\\n\\n.admin-contents:not(.dashboard) .chart {\\n  &__wrapper {\\n    display: flex;\\n    flex-direction: column;\\n  }\\n\\n  &__body {\\n    margin-block: var(--space-4);\\n    flex: 1;\\n    min-width: 0; // allow chart.js to shrink below intrinsic width\\n\\n    .report-alert {\\n      margin: 0;\\n      text-align: center;\\n      padding: 3em;\\n      border: 1px solid transparent;\\n\\n      a {\\n        color: var(--primary-high);\\n      }\\n\\n      .d-icon {\\n        color: var(--primary-medium);\\n        font-size: var(--font-up-5);\\n        display: block;\\n        margin: 0.25em auto;\\n      }\\n\\n      &.no-data,\\n      &.rate-limited {\\n        background: var(--secondary);\\n        border-color: var(--primary-low);\\n        color: var(--primary);\\n      }\\n\\n      &.rate-limited .d-icon {\\n        color: var(--danger);\\n      }\\n\\n      &.timeout,\\n      &.exception {\\n        border-color: var(--danger-low);\\n        color: var(--danger);\\n      }\\n    }\\n\\n    .average-chart {\\n      font-style: italic;\\n      color: var(--primary-high);\\n      text-align: right;\\n    }\\n  }\\n\\n  &__filters {\\n    display: flex;\\n    flex-wrap: wrap;\\n    align-items: flex-start; // aligned to top to provide alignment when subcat checkbox is in play\\n    gap: var(--space-2);\\n    margin-bottom: var(--space-4);\\n\\n    @include viewport.until(sm) {\\n      flex-direction: column;\\n      align-items: stretch;\\n    }\\n\\n    .chart-groupings {\\n      @include viewport.from(sm) {\\n        margin-right: auto;\\n      }\\n    }\\n  }\\n\\n  &__filter-label {\\n    margin-top: var(--space-1);\\n  }\\n\\n  &__additional-filters {\\n    display: flex;\\n    gap: var(--space-2);\\n\\n    @include viewport.until(sm) {\\n      flex-direction: column;\\n    }\\n  }\\n\\n  &__filter {\\n    &.--include_subcategories {\\n      align-self: center;\\n    }\\n  }\\n\\n  &__dates {\\n    .d-date-time-input-range {\\n      display: flex;\\n      gap: var(--space-2);\\n\\n      > * {\\n        margin: 0;\\n      }\\n    }\\n\\n    .d-date-time-input {\\n      @include viewport.until(sm) {\\n        flex-grow: 1;\\n      }\\n    }\\n  }\\n\\n  &__actions {\\n    display: flex;\\n    gap: var(--space-4);\\n    justify-content: flex-end;\\n    margin-top: var(--space-4);\\n  }\\n\\n  &__modes {\\n    list-style: none;\\n    margin-right: auto;\\n\\n    .mode {\\n      display: inline-flex;\\n      flex: 1 0 0px;\\n\\n      .mode-btn.is-current {\\n        color: var(--tertiary);\\n      }\\n    }\\n  }\\n}\\n",".admin-report-radar {\\n  .chart-canvas-container {\\n    height: 250px;\\n  }\\n}\\n",".admin-report-stacked-line-chart {\\n  .chart-canvas-container {\\n    height: 250px;\\n  }\\n}\\n",".admin-report-table {\\n  &.two-columns {\\n    .table .admin-report-table-cell:first-child,\\n    .table .admin-report-table-header:first-child {\\n      text-align: left;\\n      width: 80%;\\n      overflow-wrap: break-word;\\n    }\\n\\n    .table .admin-report-table-cell:last-child,\\n    .table .admin-report-table-header:last-child {\\n      text-align: right;\\n    }\\n  }\\n\\n  .table {\\n    margin: 0;\\n    border: 1px solid var(--content-border-color);\\n    table-layout: fixed;\\n\\n    tbody {\\n      border-top: 0;\\n    }\\n  }\\n\\n  .table .admin-report-table-header {\\n    --header-caret-offset: calc(var(--space-4) * -1);\\n    overflow-wrap: break-word;\\n\\n    &.date {\\n      width: 6em;\\n    }\\n\\n    .sort-btn {\\n      padding: 0;\\n      flex-direction: row-reverse;\\n      gap: var(--space-1);\\n      position: relative;\\n\\n      .d-icon {\\n        // avoiding the appearance of the icon affecting alignment\\n        position: absolute;\\n        margin: 0;\\n        right: var(--header-caret-offset);\\n      }\\n    }\\n\\n    &:last-child {\\n      .sort-btn {\\n        .d-icon {\\n          left: var(--header-caret-offset);\\n        }\\n      }\\n    }\\n\\n    &.is-current-sort {\\n      .d-icon {\\n        color: var(--tertiary);\\n      }\\n    }\\n\\n    &:not(.is-current-sort) .sort-btn {\\n      .d-icon {\\n        // avoiding the appearance of the icon changing column size\\n        visibility: hidden;\\n      }\\n    }\\n  }\\n\\n  .admin-report-table-cell {\\n    &.user .username {\\n      margin-left: 0.25em;\\n    }\\n  }\\n\\n  .total-row {\\n    background: var(--primary-very-low);\\n\\n    td {\\n      font-weight: 700;\\n      text-align: left;\\n    }\\n  }\\n\\n  .pagination {\\n    display: flex;\\n    justify-content: flex-end;\\n    margin-top: 0.25em;\\n\\n    button {\\n      margin-left: 0.5em;\\n\\n      &.is-current {\\n        color: var(--tertiary);\\n      }\\n    }\\n  }\\n}\\n\\n.admin-report.top-referred-topics {\\n  .admin-report-table-header.topic_title {\\n    width: 80%;\\n  }\\n\\n  .admin-report-table-cell.number {\\n    width: 6ch;\\n  }\\n}\\n\\n.admin-report.trending-search {\\n  .admin-report-table-header.ctr,\\n  .admin-report-table-header.unique_searches,\\n  .admin-report-table-cell.ctr,\\n  .admin-report-table-cell.unique_searches {\\n    text-align: center;\\n    width: 20%;\\n  }\\n\\n  .admin-report-table-cell.term {\\n    @include ellipsis;\\n  }\\n\\n  .admin-report-table-cell.percent {\\n    width: 5ch;\\n    text-align: right;\\n  }\\n\\n  .admin-report-table-cell.number.searches {\\n    width: 6ch;\\n    text-align: right;\\n  }\\n}\\n\\n.admin-report.moderators-activity {\\n  .admin-report-table-header.seconds,\\n  .admin-report-table-header.number,\\n  .admin-report-table-cell.seconds,\\n  .admin-report-table-cell.number {\\n    text-align: center;\\n  }\\n\\n  .admin-report-table-header.user {\\n    width: 20%;\\n  }\\n}\\n\\n.admin-report.post-edits {\\n  .admin-report-table-header.user {\\n    width: 20%;\\n  }\\n\\n  .admin-report-table-cell.post,\\n  .admin-report-table-cell.edit_reason {\\n    @include ellipsis;\\n  }\\n}\\n\\n.admin-report.flags-status {\\n  .admin-report-table-header.response_time,\\n  .admin-report-table-cell.response_time {\\n    text-align: center;\\n  }\\n}\\n\\n.rtl {\\n  .admin-report-table {\\n    &.two-columns {\\n      .table .admin-report-table-cell:first-child,\\n      .table .admin-report-table-header:first-child {\\n        text-align: right;\\n      }\\n\\n      .table .admin-report-table-cell:last-child,\\n      .table .admin-report-table-header:last-child {\\n        text-align: left;\\n      }\\n    }\\n  }\\n\\n  .admin-report-table-cell {\\n    &.user .username {\\n      margin-left: 0;\\n      margin-right: 0.25em;\\n    }\\n  }\\n\\n  .admin-report.trending-search {\\n    .admin-report-table-header.term,\\n    .admin-report-table-cell.term {\\n      text-align: right;\\n    }\\n  }\\n\\n  .pagination {\\n    button {\\n      margin-left: 0;\\n      margin-right: 0.5em;\\n    }\\n  }\\n\\n  .admin-report.moderators-activity {\\n    .admin-report-table-header.user,\\n    .admin-report-table-cell.user {\\n      text-align: right;\\n    }\\n  }\\n}\\n\\n.mobile-view .admin-report-table {\\n  .table {\\n    font-size: var(--font-down-1);\\n  }\\n\\n  .table .admin-report-table-header {\\n    font-weight: 500;\\n    border-right: 1px solid var(--content-border-color);\\n    padding: auto;\\n\\n    .title {\\n      writing-mode: vertical-rl;\\n      text-orientation: mixed;\\n      text-align: right;\\n    }\\n  }\\n\\n  .table tbody tr td {\\n    &.user .username {\\n      display: none;\\n    }\\n  }\\n}\\n",".admin-report-related-items {\\n  margin-block-start: var(--space-8);\\n\\n  h2 {\\n    margin: 0;\\n    font-size: var(--font-up-2);\\n  }\\n\\n  &__description {\\n    margin-block: var(--space-1) var(--space-4);\\n    color: var(--token-color-text-subtle);\\n  }\\n\\n  &__limit {\\n    display: block;\\n    margin-block-start: var(--space-1);\\n  }\\n\\n  &__table {\\n    width: 100%;\\