lor: var(--primary);\\n\\n    @include viewport.from(sm) {\\n      margin-bottom: 2em;\\n    }\\n\\n    &.--has-icon {\\n      grid-template-columns: 1fr 8fr;\\n      gap: 0 var(--space-4);\\n\\n      .admin-section-landing-item__buttons {\\n        grid-column: 2;\\n      }\\n    }\\n\\n    &__content {\\n      grid-row: 1;\\n    }\\n\\n    &__tagline {\\n      font-size: var(--font-down-1);\\n      font-weight: normal;\\n      color: var(--primary-high);\\n      margin: 0;\\n      letter-spacing: 0.1px;\\n    }\\n\\n    &__title {\\n      margin: 0;\\n      line-height: var(--line-height-medium);\\n    }\\n\\n    &__description {\\n      color: var(--primary-high);\\n      margin: 0.25em 0 0.5em;\\n      line-height: var(--line-height-large);\\n      align-self: start;\\n\\n      @include viewport.from(sm) {\\n        max-width: 17em;\\n      }\\n    }\\n\\n    &__icon {\\n      font-size: var(--font-up-3);\\n      color: var(--primary-low-mid);\\n      grid-row: 1;\\n    }\\n\\n    &__buttons {\\n      grid-row: 2;\\n      grid-column: 1;\\n    }\\n\\n    button {\\n      justify-self: start;\\n    }\\n  }\\n}\\n",".user-field-preferences .form-kit__container-optional {\\n  display: none;\\n}\\n","// Some basic overrides to https://github.com/MiniProfiler/rack-mini-profiler/blob/master/lib/html/includes.scss\\n// which make the badge conform to the current site theme.\\n.profiler-queries-bg {\\n  z-index: z(\\"header\\") - 2;\\n}\\n\\ndiv.profiler-results.profiler-top {\\n  top: var(--header-offset);\\n  z-index: z(\\"header\\") - 1;\\n\\n  .profiler-result {\\n    font-size: var(--font-down-1);\\n  }\\n\\n  .profiler-button {\\n    background-color: var(--header_background);\\n    color: var(--header_primary);\\n    border-bottom: 1px solid var(--header_primary-low);\\n\\n    .profiler-number,\\n    .profiler-unit {\\n      color: var(--header_primary);\\n    }\\n\\n    .profiler-reqs {\\n      font-size: var(--font-down-1);\\n    }\\n  }\\n\\n  &.profiler-left .profiler-button {\\n    border-right: 1px solid var(--header_primary-low);\\n  }\\n\\n  &.profiler-right .profiler-button {\\n    border-left: 1px solid var(--header_primary-low);\\n    padding-right: 10px; // Make space for scrollbar\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.schema-setting-editor {\\n  .schema-setting-editor__wrapper {\\n    --schema-space: 0.5em;\\n    display: grid;\\n    grid-template-columns: minmax(14em, 0.3fr) 1fr;\\n    grid-template-rows: auto 1fr;\\n    gap: 0 2rem;\\n\\n    @include viewport.until(sm) {\\n      --schema-space: 0.33em;\\n      gap: 0 1em;\\n    }\\n\\n    .schema-setting-editor__navigation {\\n      overflow: hidden;\\n      align-self: start;\\n\\n      ul {\\n        list-style: none;\\n      }\\n\\n      .schema-setting-editor__tree {\\n        border: 1px solid var(--content-border-color);\\n        overflow: auto;\\n        margin: 0 0 2em 0;\\n\\n        ul {\\n          padding: 0 calc(var(--schema-space) * 2) 0 var(--schema-space);\\n          margin: 0 0 1em;\\n\\n          li:hover {\\n            background: var(--primary-very-low);\\n          }\\n\\n          &.--is-hidden {\\n            display: none;\\n          }\\n        }\\n\\n        .--heading {\\n          display: flex;\\n          align-items: center;\\n          padding: var(--schema-space) calc(var(--schema-space) * 3)\\n            var(--schema-space) calc(var(--schema-space) * 2);\\n          gap: 0.5em;\\n\\n          .d-icon {\\n            font-size: var(--font-down-3);\\n            margin-left: auto;\\n          }\\n        }\\n\\n        .schema-setting-editor__tree-node.--back-btn {\\n          cursor: pointer;\\n          width: 100%;\\n          border-bottom: 1px solid var(--content-border-color);\\n          color: var(--primary-700);\\n\\n          &:hover {\\n            color: var(--primary-800);\\n            background: var(--primary-very-low);\\n          }\\n\\n          .schema-setting-editor__tree-node-text {\\n            color: currentcolor;\\n\\n            .d-icon {\\n              color: currentcolor;\\n              margin-left: 0;\\n              margin-right: var(--schema-space);\\n            }\\n          }\\n        }\\n\\n        .schema-setting-editor__tree-node-text {\\n          padding: var(--schema-space);\\n          color: var(--primary);\\n          display: flex;\\n          align-items: center;\\n\\n          span {\\n            @include ellipsis;\\n          }\\n\\n          .d-icon {\\n            margin-left: auto;\\n            font-size: var(--font-down-3);\\n            color: var(--primary-500);\\n          }\\n        }\\n\\n        .schema-setting-editor__tree-node {\\n          cursor: pointer;\\n\\n          &.--active {\\n            > .schema-setting-editor__tree-node-text {\\n              background-color: var(--tertiary);\\n              color: var(--secondary);\\n\\n              .d-icon {\\n                color: var(--secondary);\\n              }\\n            }\\n          }\\n\\n          &.--parent {\\n            border: 2px solid transparent;\\n\\n            &:not(:has(ul)) {\\n              &:hover {\\n                background: var(--primary-very-low);\\n              }\\n            }\\n\\n            &.--active {\\n              border: 2px solid var(--tertiary);\\n            }\\n\\n            &.--add-button {\\n              border-top: 1px solid var(--content-border-color);\\n            }\\n          }\\n\\n          &.--heading {\\n            .d-icon {\\n              color: var(--primary-700);\\n            }\\n\\n            &:hover {\\n              background: var(--primary-very-low);\\n            }\\n          }\\n\\n          &.--child {\\n            margin-left: var(--schema-space);\\n            border-left: 1px solid var(--primary-200);\\n\\n            .schema-setting-editor__tree-node-text {\\n              color: var(--primary-800);\\n            }\\n          }\\n        }\\n      }\\n\\n      .schema-setting-editor__tree-add-button {\\n        color: var(--tertiary);\\n        width: 100%;\\n        line-height: 1.4; // match li height\\n        justify-content: start;\\n        padding: var(--schema-space);\\n\\n        .d-icon {\\n          color: currentcolor;\\n          font-size: var(--font-down-1);\\n        }\\n\\n        &:hover {\\n          background: var(--primary-very-low);\\n          color: var(--tertiary-hover);\\n\\n          .d-icon {\\n            color: currentcolor;\\n          }\\n        }\\n      }\\n    }\\n  }\\n}\\n",".customize-show-schema {\\n  &__header {\\n    margin-bottom: 1em;\\n  }\\n\\n  &__back {\\n    display: flex;\\n    align-items: center;\\n    gap: 0.25em;\\n    color: var(--tertiary);\\n\\n    .d-icon {\\n      font-size: var(--font-down-1);\\n      color: currentcolor;\\n    }\\n  }\\n}\\n",".bulk-user-delete-confirmation {\\n  &__progress {\\n    font-family: var(--d-font-family--monospace);\\n    max-height: 400px;\\n    background: var(--blend-primary-secondary-5);\\n    padding: 1em;\\n    overflow-y: auto;\\n  }\\n\\n  &__progress-line {\\n    overflow-anchor: none;\\n\\n    &.-success {\\n      color: var(--success);\\n    }\\n\\n    &.-error {\\n      color: var(--danger);\\n    }\\n  }\\n\\n  &__progress-anchor {\\n    overflow-anchor: auto;\\n    height: 1px;\\n  }\\n}\\n",".bulk-user-suspend-confirmation {\\n  &__progress {\\n    font-family: var(--d-font-family--monospace);\\n    max-height: 400px;\\n    background: var(--blend-primary-secondary-5);\\n    padding: 1em;\\n    overflow-y: auto;\\n  }\\n\\n  &__progress-line {\\n    overflow-anchor: none;\\n\\n    &.-success {\\n      color: var(--success);\\n    }\\n\\n    &.-error {\\n      color: var(--danger);\\n    }\\n  }\\n\\n  &__progress-anchor {\\n    overflow-anchor: auto;\\n    height: 1px;\\n  }\\n}\\n",".color-palette-editor {\\n  &__colors-list {\\n    display: flex;\\n    flex-direction: column;\\n    gap: 1em;\\n  }\\n\\n  &__colors-item {\\n    