iary-300);\\n    background-image: none;\\n\\n    .d-icon {\\n      color: var(--tertiary-high);\\n    }\\n  }\\n}\\n\\n.btn-primary,\\n.discourse-no-touch .btn-default.ai-new-question-button {\\n  background-color: var(--accent-color);\\n  color: var(--accent-text-color);\\n\\n  .d-icon {\\n    color: var(--accent-text-color);\\n  }\\n\\n  &:not([disabled]):focus-visible,\\n  &:not([disabled]):hover {\\n    .discourse-no-touch & {\\n      background-color: var(--accent-color);\\n      box-shadow: 0 0 0 4px var(--button-box-shadow);\\n      color: var(--accent-text-color);\\n\\n      .d-icon {\\n        color: var(--accent-text-color);\\n      }\\n    }\\n  }\\n\\n  &:active {\\n    background: light-dark(\\n      oklch(from var(--accent-color) 40% c h),\\n      oklch(from var(--accent-color) 50% c h)\\n    );\\n  }\\n\\n  &:visited {\\n    color: var(--accent-text-color);\\n  }\\n}\\n\\n.btn-danger {\\n  .discourse-no-touch & {\\n    &:not([disabled]):focus-visible,\\n    &:not([disabled]):hover {\\n      background-color: var(--danger);\\n      box-shadow: 0 0 0 4px var(--d-button-danger-bg-color--hover);\\n    }\\n  }\\n}\\n\\n// DiscoToc plugin\\n.d-toc-main,\\n.timeline-footer-controls {\\n  .btn.timeline-toggle {\\n    border-top-right-radius: 8px;\\n    border-top-left-radius: 8px;\\n    border-bottom-left-radius: 0;\\n    border-bottom-right-radius: 0;\\n    bottom: var(--main-grid-gap);\\n  }\\n}\\n\\n.d-combo-button:hover {\\n  border-radius: var(--d-button-border-radius);\\n  box-shadow: 0 0 0 4px var(--button-box-shadow);\\n\\n  button:hover {\\n    // remove duplicate shadow from child button\\n    box-shadow: none;\\n  }\\n}\\n\\n// Solved\\n.btn-default.post-action-menu__solved-shared-issue:not(.has-shared-issue) {\\n  .d-icon {\\n    color: var(--icon-color);\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.full-page-chat.full-page-chat-sidebar-enabled {\\n  border: none;\\n}\\n\\n.c-navbar-container {\\n  background-color: var(--d-content-background);\\n\\n  .full-page-chat & {\\n    @include viewport.from(sm) {\\n      padding: 0 1.5em;\\n    }\\n  }\\n\\n  .chat-drawer.is-collapsed & {\\n    background: var(--tertiary-low);\\n    opacity: 0.7;\\n  }\\n}\\n\\nbody.has-full-page-chat {\\n  background-color: var(--background-color);\\n\\n  #main-outlet-wrapper {\\n    @media screen and (width < 87rem) {\\n      // ideal width just slightly larger than our xl viewport variable\\n      padding-inline: 0;\\n    }\\n  }\\n}\\n\\n.chat-drawer-container {\\n  .is-expanded & {\\n    box-shadow: 0 0 0 2px var(--tertiary-medium);\\n  }\\n\\n  .chat-drawer.is-expanded & {\\n    border: none;\\n  }\\n\\n  .c-navbar__title {\\n    padding-left: 0.33em; // visual alignment for chat index, which does not have a back arrow\\n  }\\n}\\n\\n.chat-drawer-outlet-container {\\n  z-index: z(\\"composer\\", \\"content\\");\\n  padding-bottom: 0;\\n  right: var(--main-grid-gap);\\n\\n  &:has(.is-expanded) {\\n    z-index: calc(z(\\"composer\\", \\"dropdown\\") + 1);\\n  }\\n\\n  &.above-composer {\\n    padding-bottom: 0;\\n  }\\n}\\n\\n// the below are elements whose z-index needs to be adjusted due to the above change\\n.chat-message-actions-container {\\n  .has-drawer-chat & {\\n    z-index: calc(z(\\"composer\\", \\"dropdown\\") + 1);\\n  }\\n}\\n\\n.fk-d-menu[data-identifier=\\"usercard\\"],\\n.fk-d-menu[data-identifier=\\"chat-message-reaction-users\\"] {\\n  .has-drawer-chat & {\\n    z-index: z(\\"modal\\", \\"dialog\\");\\n  }\\n}\\n\\n.chat-drawer {\\n  .peek-mode-active & {\\n    max-width: 90vw;\\n  }\\n}\\n\\n.chat-drawer .channels-list-container .chat-channel-row {\\n  margin-bottom: var(--spacing-block-xs);\\n  font-size: var(--font-up-1);\\n  border-bottom: none;\\n\\n  &:hover {\\n    background-color: var(--d-sidebar-active-background);\\n  }\\n}\\n\\n.channel-title {\\n  font-weight: bold;\\n  text-transform: uppercase;\\n  font-size: var(--font-down-1);\\n}\\n\\n.chat-composer__wrapper {\\n  background: var(--d-content-background);\\n}\\n\\n.chat-message-actions .more-buttons .btn-icon-text {\\n  &:hover {\\n    background-color: var(--d-selected);\\n    box-shadow: none;\\n    color: var(--primary);\\n  }\\n}\\n\\n.chat-drawer-active.chat-drawer-expanded .chat-composer-dropdown__menu-content {\\n  z-index: z(\\"modal\\", \\"dialog\\");\\n}\\n\\n.chat-replying-indicator-container {\\n  @include viewport.from(sm) {\\n    margin-left: calc(0.65em + 0.2rem);\\n  }\\n}\\n","@use \\"breakpoints\\";\\n\\n$breakpoints: breakpoints.$breakpoints;\\n\\n@mixin from($bp) {\\n  @media (width >= #{breakpoints.get($bp)}) {\\n    @content;\\n  }\\n}\\n\\n@mixin until($bp) {\\n  @media (width < #{breakpoints.get($bp)}) {\\n    @content;\\n  }\\n}\\n\\n@mixin between($from, $until) {\\n  @media (#{breakpoints.get($from)} <= width < #{breakpoints.get($until)}) {\\n    @content;\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.list-container.--categories {\\n  .avatar-flair {\\n    display: none;\\n  }\\n}\\n\\n.categories-and-latest {\\n  .category-list {\\n    border-collapse: separate;\\n\\n    .category-list {\\n      // when category nesting is set to 3\\n      grid-column: 1/-1;\\n      border: none;\\n      margin: 0;\\n\\n      tbody {\\n        padding: 0;\\n      }\\n    }\\n\\n    th.topics,\\n    .category-logo {\\n      display: none;\\n    }\\n\\n    thead tr th {\\n      font-size: var(--font-up-1-rem);\\n      font-weight: bold;\\n    }\\n\\n    tbody {\\n      display: flex;\\n      flex-direction: column;\\n      gap: 1em;\\n      padding-top: 1em;\\n      border: 0;\\n    }\\n\\n    tbody tr {\\n      display: grid;\\n      grid-template-columns: 1fr auto;\\n      gap: var(--space-4);\\n      padding: var(--space-4) var(--space-6);\\n      border: 1px solid var(--primary-300);\\n      border-radius: var(--d-border-radius-large);\\n      box-shadow: 0 0 12px 1px var(--topic-card-shadow);\\n    }\\n\\n    td.category {\\n      display: contents;\\n      border-top-left-radius: var(--d-border-radius-large);\\n      border-bottom-left-radius: var(--d-border-radius-large);\\n      border-width: 2px;\\n      padding: 1em 1.5rem;\\n    }\\n\\n    tbody h3 {\\n      grid-column: 1;\\n      grid-row: 1;\\n      padding: 0;\\n      font-size: var(--font-up-1-rem);\\n\\n      .category-name {\\n        display: flex;\\n        align-self: center;\\n      }\\n\\n      .badge-category {\\n        gap: 0.25em;\\n        align-items: center;\\n        font-size: var(--font-up-1-rem);\\n\\n        .d-icon:first-of-type:not([class*=\\"d-icon-lock\\"]),\\n        &.--style-square::before,\\n        &.--style-emoji .emoji {\\n          width: 1.25em;\\n          height: 1.25em;\\n          margin-right: 0.25em;\\n        }\\n\\n        &.--style-square::before {\\n          border-radius: 6px;\\n        }\\n      }\\n\\n      [class*=\\"d-icon-lock\\"] {\\n        order: 1;\\n      }\\n    }\\n\\n    .topics {\\n      grid-column: 2;\\n      grid-row: 1;\\n      width: auto;\\n      padding: 0;\\n      display: flex;\\n      align-items: center;\\n      justify-content: end;\\n    }\\n\\n    .category-description {\\n      grid-column: 1 / -1;\\n      padding: 0;\\n      margin: 0;\\n      font-size: var(--font-down-1-rem);\\n    }\\n\\n    .subcategories {\\n      grid-column: 1 / -1;\\n      gap: 0.25em 0.5em;\\n      padding: 0;\\n      margin: 0;\\n\\n      .badge-category__wrapper {\\n        background-color: var(--badge-category-bg);\\n        padding: 0.25em 0.5rem;\\n        border-radius: var(--d-border-radius);\\n      }\\n\\n      .badge-category__name {\\n        color: var(--badge-category-text);\\n      }\\n\\n      .badge-category.--style-square::before {\\n        border-radius: 3px;\\n      }\\n    }\\n  }\\n\\n  .latest-topic-list {\\n    .table-heading {\\n      border: 0;\\n      font-size: var(--font-up-1-rem);\\n      font-weight: bold;\\n    }\\n\\n    &-item {\\n      display: grid;\\n      grid-template-columns: min-content min-content auto min-content;\\n      grid-template-areas:\\n        \\"creator title title status\\"\\n        \\". category activity activity\\";\\n      column-gap: 0.75rem;\\n      row-gap: 0.5rem;\\n      background: var(--d-content-background);\\n      box-shadow: 0 0 12px 1px var(--topic-card-shadow);\\n      text-overflow: ellipsis;\\n      padding: 0.75em 1rem;\\n      border: 1px solid var(--primary-300);\\n      border-radius: var(--d-border-radius-large);\\n      margin-top: 1em;\\n    }\\n\\n    .main-link,\\n    .topic-stats {\\n      display: contents;\\n    }\\n\\n    .top-row {\\n      grid-area: title;\\n    }\\n\\n    .bottom-row {\\n      grid-area: category;\\n\\n      .discourse-tags {\\n        display: none;\\n      }\\n    }\\n\\n    .badge-category__wrapper {\\n      border-radius: var(--d-border-radius);\\n      padding: 0.25em 0.5rem;\\n      background-color: var(--badge-category-bg);\\n\\n      @include viewport.until(md) {\\n        padding: 0.25em 0.5rem;\\n        font-size: var(--font-down-2);\\n      }\\n\\n      .badge-category__name {\\n        color: var(--badge-category-text);\\n      }\\n    }\\n\\n    .topic-list-data {\\n      grid-area: likes-replies;\\n    }\\n\\n    .num.posts-map {\\n      display: none;\\n    }\\n\\n    .topic-last-activity {\\n      grid-area: activity;\\n      display: flex;\\n      align-items: center;\\n      text-align: left;\\n      font-size: var(--font-down-1-rem);\\n\\n      &::before {\\n        content: \\"\\";\\n        display: inline-block;\\n        width: 0.25em;\\n        height: 0.25em;\\n        background-color: var(--primary-500);\\n        border-radius: 100%;\\n        margin-right: 0.5em;\\n      }\\n    }\\n\\n    .topic-poster {\\n      grid-area: creator;\\n      width: auto;\\n      align-self: flex-start;\\n\\n      .avatar {\\n        height: 24px;\\n        width: 24px;\\n        border-radius: var(--d-border-radius-small);\\n      }\\n    }\\n  }\\n}\\n\\n@include viewport.until(sm) {\\n  .category-list.with-topics {\\n    margin-inline: 1rem;\\n\\n    .num.posts,\\n    .category-topics-count,\\n    .category-logo {\\n      display: none;\\n    }\\n\\n    .category-list {\\n      &-item {\\n        padding-top: 0;\\n        padding-bottom: 0;\\n        border-top: 0 !important;\\n        border-bottom: 0 !important;\\n      }\\n    }\\n\\n    tbody {\\n      display: flex;\\n      flex-direction: column;\\n\\n      tr:first-of-type {\\n        order: -2;\\n      }\\n\\n      tr.subcategories-list {\\n        order: -1;\\n      }\\n\\n      tr:nth-last-of-type(2) {\\n        border-bottom: 0;\\n      }\\n    }\\n\\n    th.main-link {\\n      padding-top: 0;\\n    }\\n  }\\n}\\n\\n.category-boxes,\\n.category-boxes-with-topics {\\n  .category-logo {\\n    display: none;\\n  }\\n\\n  @include viewport.from(sm) {\\n    margin-top: 0;\\n  }\\n\\n  @include viewport.until(md) {\\n    padding-inline: 1rem;\\n    box-sizing: border-box;\\n  }\\n\\n  .category {\\n    border: 0;\\n\\n    &-box-inner {\\n      border-radius: var(--d-border-radius-large);\\n      border: 1px solid var(--primary-300);\\n      background: var(--d-content-background);\\n      box-shadow: 0 0 12px 1px var(--topic-card-shadow);\\n\\n      &:hover {\\n        .discourse-no-touch & {\\n          border-color: var(--accent-color);\\n          background: var(--d-content-background);\\n        }\\n      }\\n\\n      &.selected {\\n        box-shadow:\\n          0 0 0 2px var(--accent-color),\\n          0 0 12px 1px var(--topic-card-shadow);\\n      }\\n    }\\n\\n    &-details {\\n      display: flex;\\n      flex-direction: column;\\n      gap: 1rem;\\n      height: 100%;\\n    }\\n\\n    &-box-heading {\\n      h3 {\\n        text-align: left;\\n      }\\n\\n      .badge-category {\\n        display: flex;\\n        flex-wrap: wrap;\\n        align-items: flex-start;\\n        gap: 1em;\\n        justify-content: space-between;\\n        width: 100%;\\n\\n        &__wrapper {\\n          display: flex;\\n        }\\n\\n        &.--style-square::before {\\n          aspect-ratio: 1 / 1;\\n          height: auto;\\n          width: 13%;\\n          border-radius: var(--d-border-radius);\\n        }\\n\\n        &__name {\\n          flex-basis: 100%;\\n          font-size: var(--font-up-1-rem);\\n        }\\n\\n        .d-icon:not([class*=\\"d-icon-lock\\"]),\\n        img.emoji {\\n          aspect-ratio: 1 / 1;\\n          height: auto;\\n          width: 13%;\\n        }\\n      }\\n    }\\n\\n    .description {\\n      text-align: left;\\n      margin: 0;\\n      font-size: var(--font-down-1-rem);\\n    }\\n\\n    .subcategories {\\n      margin-top: auto;\\n\\n      .subcategory {\\n        margin-bottom: 0;\\n        font-size: var(--font-down-1);\\n      }\\n    }\\n  }\\n}\\n\\n// theme component: https://github.com/discourse/discourse-minimal-category-boxes\\n.custom-category-boxes-container {\\n  @include viewport.until(sm) {\\n    padding-inline: var(--space-4);\\n    box-sizing: border-box;\\n  }\\n}\\n",".user-color-palette-menu {\\n  &__item .btn-icon-text.btn-flat {\\n    background-color: var(--d-content-background);\\n    width: 100%;\\n    justify-content: flex-start;\\n  }\\n\\n  &__item .btn-icon-text.btn-flat:hover {\\n    background-color: var(--d-selected);\\n    box-shadow: none;\\n    color: var(--primary);\\n  }\\n\\n  &__item .btn-icon-text.btn-flat:hover svg {\\n    color: var(--icon-color);\\n  }\\n\\n  &__item .btn-icon-text.btn-flat svg {\\n    color: var(--icon-color);\\n  }\\n\\n  &__item-choice.active.btn-icon-text.btn-flat {\\n    background-color: var(--d-selected);\\n  }\\n}\\n\\n.user-color-palette-content .fk-d-menu__inner-content {\\n  border: none;\\n}\\n","@use \\"lib/viewport\\";\\n\\n.custom-homepage-columns {\\n  .header-wrapper {\\n    @include viewport.from(lg) {\\n      margin-bottom: 1.25em;\\n    }\\n  }\\n\\n  .topic-list .topic-list-item {\\n    height: auto;\\n\\n    &:nth-child(odd) {\\n      background: var(--topic-list-item-background-color);\\n    }\\n  }\\n}\\n\\n.b-header {\\n  .nav-pills > li > a:hover {\\n    .discourse-no-touch & {\\n      color: var(--secondary);\\n    }\\n  }\\n\\n  .nav-pills > li > a:hover::after {\\n    .discourse-no-touch & {\\n      background: var(--secondary);\\n    }\\n  }\\n}\\n\\n// theme component: https://github.com/discourse/discourse-minimal-category-boxes\\n.custom-category-boxes-container {\\n  @include viewport.until(sm) {\\n    padding-inline: var(--space-4);\\n    box-sizing: border-box;\\n  }\\n}\\n\\n@include viewport.from(md) {\\n  #main-outlet {\\n    div[class^=\\"category-title-header\\"] {\\n      width: calc(100% - (2 * var(--space-4)));\\n      border-radius: var(--d-border-radius-large);\\n      max-width: calc(1000px - 3rem) !important;\\n    }\\n\\n    .list-container div[class^=\\"category-title-header\\"] {\\n      width: 100%;\\n    }\\n  }\\n}\\n\\n// livestream plugin: https://github.com/discourse/discourse-livestream\\n.livestream-topic.chat-enabled.archetype-regular {\\n  #custom-chat-container {\\n    margin-left: 0;\\n    border-top-left-radius: var(--d-border-radius-large);\\n    border-top-right-radius: var(--d-border-radius-large);\\n    border: 0;\\n  }\\n\\n  .container.posts {\\n    grid-template-columns: auto auto;\\n  }\\n}\\n\\n// TC: Blog Style\\nbody:not(.d-toc-installed).blog-post .container.posts,\\nbody.d-toc-installed.blog-post .container.posts {\\n  grid-template-columns: var(--blog-width) 0;\\n}\\n","@use \\"lib/viewport\\";\\n\\n#reply-control.hide-preview:not(.draft) {\\n  @include viewport.from(sm) {\\n    .user-selector,\\n    .title-and-category {\\n      :where(body:not(.uc-enable-composer-redesign) &) {\\n        padding: 0 var(--space-2);\\n        width: calc(100% - var(--space-2) * 2) !important;\\n      }\\n    }\\n\\n    .reply-to,\\n    .submit-panel {\\n      :where(body:not(.uc-enable-composer-redesign) &) {\\n        padding-inline: var(--space-2);\