data-list-item-name=\\"New Topic\\"] {\\n  display: none;\\n}\\n\\n.has-full-page-chat {\\n  .sidebar-new-topic-button__wrapper {\\n    display: none;\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n:root {\\n  --d-post-control-background--hover: var(--d-hover);\\n}\\n\\n.post-stream {\\n  .contents {\\n    font-size: var(--font-up-1);\\n    line-height: 1.25;\\n    -webkit-font-smoothing: antialiased;\\n  }\\n}\\n\\n.timeline-container .topic-timeline {\\n  .timeline-scrollarea {\\n    border-left: 1px solid var(--accent-color);\\n\\n    .timeline-scroller {\\n      @include viewport.from(lg) {\\n        margin-left: -4.5px;\\n        height: 40px !important; // height is coming from element style have no other choice\\n      }\\n\\n      .timeline-replies,\\n      .timeline-ago {\\n        line-height: 1;\\n      }\\n    }\\n\\n    .timeline-handle {\\n      background-color: var(--accent-color);\\n      outline: 3px solid var(--d-content-background);\\n\\n      @include viewport.from(lg) {\\n        width: 8px;\\n        border-radius: 10px;\\n        height: calc(100% - 6px);\\n      }\\n    }\\n  }\\n}\\n\\n// should probably get rid of this extra specificity class in core?\\n.timeline-container.timeline-fullscreen {\\n  @include viewport.until(lg) {\\n    .topic-timeline\\n      .timeline-scrollarea\\n      .timeline-scroller\\n      .timeline-scroller-content {\\n      padding-right: 0.5em;\\n    }\\n  }\\n}\\n\\nbody:not(.d-toc-installed) {\\n  .container.posts {\\n    grid-template-columns: auto 8em;\\n\\n    @media screen and (width <= 924px) {\\n      grid-template-columns: auto;\\n    }\\n  }\\n\\n  .topic-navigation-popup {\\n    min-width: 250px;\\n    right: 0;\\n  }\\n}\\n\\n.container.posts {\\n  .post-notice {\\n    padding: var(--space-2);\\n    border-radius: var(--d-border-radius);\\n    font-size: var(--font-down-1-rem);\\n\\n    .d-icon {\\n      font-size: var(--font-up-1);\\n      width: 1em;\\n    }\\n  }\\n}\\n\\n.topic-post-badges {\\n  .badge-notification {\\n    font-size: var(--font-down-1);\\n    padding: 0.15em 0.35em;\\n    border-radius: 1em;\\n    min-width: 1.3em;\\n    box-sizing: border-box;\\n    color: var(--secondary);\\n  }\\n}\\n\\n.timeline-container .topic-timeline .timeline-scroller-content {\\n  overflow: unset;\\n}\\n\\n.more-topics__container\\n  .more-topics__list\\n  .topic-list-body\\n  .topic-list-item:last-of-type {\\n  border-bottom: 1px solid var(--primary-300);\\n}\\n\\n.discourse-post-event .discourse-post-event-widget {\\n  background: var(--d-content-background);\\n}\\n\\n.more-topics__container .nav {\\n  position: unset;\\n  margin-block: unset;\\n  margin-bottom: 1em;\\n}\\n\\nnav.post-controls .actions button {\\n  font-size: var(--font-0);\\n}\\n\\n.archetype-private_message {\\n  --pm-border-radius: var(--d-border-radius);\\n}\\n\\n.header-title {\\n  .event-date {\\n    font-size: var(--font-down-3);\\n    border: 1px solid var(--tertiary-low);\\n    background: var(--tertiary-low);\\n\\n    &.past {\\n      border-color: transparent;\\n      background-color: transparent;\\n    }\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n:root {\\n  --d-border-radius-small: calc(var(--d-border-radius) * 0.5);\\n  --topic-list-item-background-color: var(--d-content-background);\\n  --topic-list-item-background-color--visited: var(--d-content-background);\\n  --topic-card-shadow: rgb(var(--tertiary-rgb), 0.1);\\n}\\n\\n.badge-category__wrapper {\\n  --badge-category-bg: light-dark(\\n    oklch(from var(--category-badge-color) 97% calc(c * 0.3) h),\\n    oklch(from var(--category-badge-color) 45% calc(c * 0.5) h)\\n  );\\n  --badge-category-text: light-dark(\\n    oklch(from var(--category-badge-color) 20% calc(c * 1) h),\\n    oklch(from var(--category-badge-color) 100% calc(c * 0.9) h)\\n  );\\n}\\n\\n.topic-list.--d-topic-cards .topic-list-header .topic-list-data {\\n  max-width: unset;\\n}\\n\\n.topic-list .topic-list-item-separator {\\n  display: none;\\n}\\n\\n.topic-list > .topic-list-body > .topic-list-item.last-visit {\\n  border-bottom: 1px solid var(--primary-300);\\n\\n  &:hover {\\n    border-color: var(--accent-color);\\n  }\\n}\\n\\n.topic-list,\\n.category-boxes .subcategories {\\n  .badge-category__wrapper {\\n    border-radius: var(--d-border-radius);\\n    padding: 3px 6px;\\n    background-color: var(--badge-category-bg);\\n\\n    @include viewport.until(md) {\\n      padding: 2px 6px;\\n      font-size: var(--font-down-2);\\n    }\\n\\n    .badge-category__name {\\n      color: var(--badge-category-text);\\n    }\\n  }\\n}\\n\\n// undo all the above for the few instances that arent styled like traditional badges\\n.category-text-title {\\n  .badge-category__wrapper {\\n    border-radius: 0;\\n    padding: 0;\\n    background-color: transparent;\\n\\n    .badge-category__name {\\n      color: var(--primary);\\n    }\\n  }\\n}\\n\\n.topic-list.--d-topic-cards .topic-list-body {\\n  border: none;\\n  display: flex;\\n  flex-direction: column;\\n  gap: var(--space-4);\\n\\n  @include viewport.until(lg) {\\n    gap: var(--space-2);\\n  }\\n\\n  @include viewport.until(sm) {\\n    gap: 0;\\n    padding: 0;\\n  }\\n}\\n\\n.topic-list.--d-topic-cards .topic-list-body .topic-list-item {\\n  cursor: pointer;\\n}\\n\\n.topic-list.--d-topic-cards\\n  .topic-list-body\\n  .topic-list-item:not(.--high-context) {\\n  position: relative;\\n  text-overflow: ellipsis;\\n  padding: var(--space-3);\\n  border: 1px solid var(--primary-300);\\n  display: grid;\\n  grid-template-columns: min-content min-content min-content auto min-content;\\n  grid-template-areas:\\n    \\"creator title title title status\\"\\n    \\". category activity activity .\\";\\n  gap: var(--space-3);\\n  border-radius: var(--d-border-radius);\\n\\n  &.--has-replies {\\n    grid-template-areas:\\n      \\"creator title title title status\\"\\n      \\". category likes-replies activity .\\";\\n  }\\n\\n  &:not(.--has-replies) {\\n    .topic-likes-replies-data {\\n      display: none;\\n    }\\n  }\\n\\n  @include viewport.until(sm) {\\n    max-width: 100vw;\\n    box-sizing: border-box;\\n    grid-template-areas:\\n      \\"creator title title title status\\"\\n      \\". category activity activity . \\";\\n    border: none;\\n    border-bottom: 1px solid var(--primary-200);\\n    box-shadow: none;\\n    border-radius: 0;\\n    padding: var(--space-4) var(--space-3);\\n\\n    &.--has-replies {\\n      grid-template-areas:\\n        \\"creator title title title status\\"\\n        \\". category likes-replies activity . \\";\\n    }\\n  }\\n\\n  &.bulk-selecting {\\n    grid-template-columns: min-content min-content min-content min-content auto min-content;\\n    grid-template-areas:\\n      \\"bulk-select creator title title title status\\"\\n      \\"bulk-select category category activity activity .\\";\\n\\n    &.--has-replies {\\n      grid-template-areas:\\n        \\"bulk-select creator title title title status\\"\\n        \\"bulk-select category category activity likes-replies .\\";\\n\\n      @include viewport.until(sm) {\\n        grid-template-areas:\\n          \\"bulk-select creator title title title status\\"\\n          \\"bulk-select . category likes-replies activity . \\";\\n      }\\n    }\\n\\n    @include viewport.until(sm) {\\n      grid-template-columns: min-content min-content min-content min-content auto min-content;\\n      grid-template-areas:\\n        \\"bulk-select creator title title title status\\"\\n        \\"bulk-select . category activity activity . \\";\\n    }\\n  }\\n\\n  &:hover {\\n    .discourse-no-touch & {\\n      box-shadow: 1px 1px 12px 2px var(--topic-card-shadow);\\n      background: var(--d-content-background);\\n    }\\n  }\\n\\n  &.selected {\\n    border: 1px solid var(--accent-color);\\n    box-shadow: 0 0 12px 1px var(--topic-card-shadow);\\n  }\\n\\n  &.excerpt-expanded {\\n    @include viewport.until(sm) {\\n      .topic-excerpt,\\n      .link-bottom-line {\\n        display: none;\\n      }\\n    }\\n\\n    @include viewport.from(sm) {\\n      grid-template-areas:\\n        \\"creator title title title status\\"\\n        \\". category activity activity . \\"\\n        \\". excerpt excerpt excerpt excerpt\\";\\n\\n      &.has-replies {\\n        grid-template-areas:\\n          \\"creator title title title status\\"\\n          \\". category likes-replies activity .\\"\\n          \\". excerpt excerpt excerpt excerpt\\";\\n      }\\n\\n      .bulk-select-enabled & {\\n        grid-template-areas:\\n          \\"bulk-select creator title title title status\\"\\n          \\"bulk-select category category activity likes-replies likes-replies \\"\\n          \\" bulk-select excerpt excerpt excerpt excerpt excerpt\\";\\n      }\\n    }\\n  }\\n\\n  .link-top-line {\\n    grid-area: title;\\n    font-weight: 500;\\n    line-height: calc(var(--space-3) * 2); // avatar sizing\\n\\n    @include viewport.until(sm) {\\n      line-height: normal;\\n    }\\n\\n    .title {\\n      padding: 0;\\n    }\\n  }\\n\\n  // display contents\\n  td.main-link,\\n  td.posters,\\n  td.posts,\\n  td.views,\\n  td.activity,\\n  td.topic-category-status-data {\\n    display: contents;\\n  }\\n\\n  td.num.posts a {\\n    padding: 0;\\n  }\\n\\n  // display:nones\\n  td.main-link a.topic-status,\\n  .link-bottom-line,\\n  .badge-notification.new-topic::before {\\n    display: none;\\n  }\\n\\n  .topic-category-data {\\n    grid-area: category;\\n    display: flex;\\n  }\\n\\n  .badge-category__wrapper {\\n    border-radius: var(--d-border-radius);\\n\\n    @include viewport.until(sm) {\\n      border-radius: var(--d-border-radius-small);\\n      max-width: 125px;\\n    }\\n    padding: 0.25em 0.5rem;\\n    background-color: var(--badge-category-bg);\\n\\n    @include viewport.until(md) {\\n      padding: 0.25em 0.5rem;\\n    }\\n\\n    .badge-category {\\n      align-items: center;\\n    }\\n\\n    .badge-category__name {\\n      font-size: var(--font-down-1);\\n      color: var(--badge-category-text);\\n      min-width: 0;\\n      overflow: hidden;\\n      white-space: nowrap;\\n      text-overflow: ellipsis;\\n    }\\n\\n    .d-icon {\\n      width: var(--font-down-1);\\n      height: var(--font-down-1);\\n    }\\n  }\\n\\n  // OP avatar\\n  .topic-creator-data {\\n    grid-area: creator;\\n\\n    .avatar {\\n      height: calc(var(--space-3) * 2);\\n      width: calc(var(--space-3) * 2);\\n      border-radius: var(--d-border-radius);\\n\\n      @include viewport.until(sm) {\\n        border-radius: var(--d-border-radius-small);\\n      }\\n    }\\n  }\\n\\n  .dot-separator {\\n    width: 0.25em;\\n    height: 0.25em;\\n    background-color: var(--primary-500);\\n    border-radius: 100%;\\n    margin-inline: 0.25em;\\n  }\\n\\n  // topic activity, icon, text\\n  .topic-activity-data {\\n    @include ellipsis;\\n    grid-area: activity;\\n  }\\n\\n  .topic-activity {\\n    display: flex;\\n    font-size: var(--font-down-1);\\n    height: 100%;\\n    align-items: center;\\n    gap: 0.25em;\\n  }\\n\\n  .topic-activity__type {\\n    border-radius: 0.25rem;\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n  }\\n\\n  .topic-activity__username {\\n    @include ellipsis;\\n    margin-left: 0.25em;\\n  }\\n\\n  // timestamp\\n  td.activity .post-activity {\\n    grid-area: activity;\\n    font-size: var(--font-down-1);\\n    color: var(--primary-500);\\n    margin-left: auto;\\n    padding: 0;\\n  }\\n\\n  // status\\n  .topic-status-data {\\n    display: none;\\n  }\\n\\n  &.--has-status-card .topic-status-data {\\n    display: block;\\n    grid-area: status;\\n  }\\n\\n  .topic-status-card {\\n    height: min-content;\\n    margin-left: auto;\\n    display: flex;\\n    flex-direction: row;\\n    gap: 0.25em;\\n    align-items: center;\\n    padding: 0.2em 0.5rem;\\n    font-size: var(--font-down-2);\\n\\n    @include viewport.from(lg) {\\n      font-size: var(--font-down-3);\\n    }\\n    font-weight: 600;\\n    border-radius: var(--d-border-radius);\\n    border: 1px solid var(--status-color);\\n    color: var(--status-color);\\n\\n    @include viewport.until(sm) {\\n      border-radius: var(--d-border-radius-small);\\n      padding: 0.35em;\\n    }\\n\\n    &.--pinned {\\n      --status-color: var(--primary-500);\\n    }\\n\\n    &.--hot {\\n      --status-color: var(--danger);\\n    }\\n\\n    @include viewport.from(lg) {\\n      position: absolute;\\n      right: 1rem;\\n      top: 0;\\n      transform: translateY(-45%);\\n      background-color: var(--d-content-background);\\n    }\\n\\n    svg {\\n      color: var(--status-color);\\n\\n      @include viewport.from(lg) {\\n        font-size: var(--font-down-1);\\n      }\\n    }\\n\\n    &__name {\\n      margin: 0;\\n\\n      @include viewport.until(sm) {\\n        display: none;\\n      }\\n    }\\n  }\\n\\n  .topic-list-data {\\n    padding: 0;\\n  }\\n\\n  // metadata - excerpt\\n  .topic-excerpt {\\n    grid-area: excerpt;\\n    margin: 0;\\n    padding: 0;\\n    font-size: var(--font-down-2);\\n    width: 100%;\\n\\n    .excerpt__contents {\\n      color: var(--primary-high);\\n    }\\n\\n    .emoji {\\n      width: 1em;\\n      height: 1em;\\n    }\\n\\n    // default category position hidden\\n    .badge-category__wrapper {\\n      display: none;\\n    }\\n  }\\n\\n  td.main-link .discourse-tags {\\n    display: none;\\n  }\\n\\n  // metadata - likes and replies\\n  td.posts .badge-posts {\\n    grid-area: replies;\\n    align-self: center;\\n    font-weight: normal;\\n  }\\n\\n  td.topic-likes-replies-data {\\n    grid-area: likes-replies;\\n    display: flex;\\n    flex-direction: row;\\n    gap: var(--space-3);\\n    height: min-content;\\n    align-self: center;\\n\\n    .topic-likes {\\n      display: none;\\n    }\\n  }\\n\\n  .topic-likes-replies-data .topic-replies {\\n    display: flex;\\n    flex-direction: row;\\n    gap: 0.5em;\\n    align-items: center;\\n    color: var(--primary-500);\\n    font-size: var(--font-down-1-rem);\\n\\n    svg {\\n      color: var(--primary-600);\\n    }\\n\\n    .number {\\n      white-space: nowrap;\\n    }\\n  }\\n\\n  .bulk-select {\\n    grid-area: bulk-select;\\n    padding: 0;\\n    margin: 0;\\n    align-self: center;\\n    justify-self: center;\\n\\n    @include viewport.until(sm) {\\n      align-self: flex-start;\\n    }\\n\\n    label {\\n      margin: 0;\\n    }\\n\\n    &th {\\n      display: none;\\n    }\\n  }\\n\\n  // Assigned List\\n  &.assigned-list-item {\\n    .topic-status-data {\\n      display: none;\\n    }\\n    grid-template-areas:\\n      \\"creator title title title dropdown\\"\\n      \\". category activity activity .\\";\\n\\n    &.--has-replies {\\n      grid-template-areas:\\n        \\"creator title title title dropdown\\"\\n        \\"category category likes-replies activity .\\";\\n    }\\n\\n    .assign-topic-buttons {\\n      display: contents;\\n\\n      .assign-actions-dropdown {\\n        grid-area: dropdown;\\n        justify-content: flex-end;\\n        height: 1em;\\n\\n        .select-kit-header {\\n          padding-top: 0;\\n          margin-left: auto;\\n          align-items: center;\\n          background: transparent;\\n        }\\n\\n        .select-kit-header-wrapper {\\n          height: 1em;\\n          width: 1em;\\n        }\\n      }\\n    }\\n  }\\n\\n  // Bookmarks\\n  &.bookmark-list-item {\\n    grid-template-areas:\\n      \\"creator title title title dropdown\\"\\n      \\"category category activity . . \\";\\n\\n    @include viewport.until(sm) {\\n      grid-template-areas:\\n        \\"title title title title dropdown\\"\\n        \\"category category activity activity . \\";\\n\\n      .avatar {\\n        display: none;\\n      }\\n    }\\n\\n    &.has-metadata {\\n      grid-template-areas:\\n        \\"creator title title title dropdown\\"\\n        \\"category category activity metadata . \\";\\n\\n      @include viewport.until(sm) {\\n        grid-template-areas:\\n          \\"metadata metadata metadata metadata dropdown\\"\\n          \\"title title title title .\\"\\n          \\"category category activity activity . \\";\\n      }\\n    }\\n\\n    td.author-avatar {\\n      grid-area: creator;\\n    }\\n\\n    td.main-link .link-bottom-line {\\n      display: contents;\\n\\n      .badge-category__wrapper {\\n        grid-area: category;\\n        display: flex;\\n        align-items: center;\\n        width: min-content;\\n        justify-self: flex-end;\\n      }\\n    }\\n\\n    td.main-link .link-top-line {\\n      display: contents;\\n\\n      .bookmark-metadata {\\n        grid-area: metadata;\\n        margin: 0;\\n        display: flex;\\n        align-items: center;\\n        flex-wrap: wrap;\\n        gap: var(--space-2);\\n        white-space: nowrap;\\n      }\\n\\n      .bookmark-metadata-item {\\n        margin: 0;\\n        vertical-align: middle;\\n      }\\n\\n      .bookmark-status-with-link {\\n        grid-area: title;\\n      }\\n    }\\n\\n    .post-excerpt {\\n      grid-area: excerpt;\\n      margin: 0;\\n    }\\n\\n    .topic-list-data:last-of-type {\\n      display: contents;\\n\\n      .bookmark-actions-dropdown {\\n        grid-area: dropdown;\\n        align-self: flex-start;\\n        height: 1em;\\n\\n        .select-kit-header {\\n          padding-top: 0;\\n          margin-left: auto;\\n          align-items: center;\\n          background: transparent;\\n        }\\n\\n        .select-kit-header-wrapper {\\n          height: 1em;\\n          width: 1em;\\n        }\\n      }\\n    }\\n\\n    .post-metadata.topic-list-data.updated-at {\\n      grid-area: activity;\\n      display: flex;\\n      align-items: center;\\n      font-size: var(--font-down-1-rem);\\n    }\\n\\n    td.activity .post-activity {\\n      display: none;\\n    }\\n  }\\n}\\n\\n// for both types of context cards\\n.topic-list.--d-topic-cards {\\n  .event-date {\\n    margin-left: var(--space-2);\\n    font-size: var(--font-down-3);\\n    white-space: nowrap;\\n    font-weight: normal;\\n  }\\n\\n  .event-date-container {\\n    display: inline-flex;\\n    position: relative;\\n    top: -0.15rem;\\n    line-height: normal;\\n  }\\n}\\n\\n// bulk-select overrule for j/k nav\\n.topic-list tr.selected td:first-of-type,\\n.topic-list-item.selected td:first-of-type {\\n  box-shadow: none;\\n}\\n","// --------------------------------------------------\\n// Mixins used throughout the theme\\n// --------------------------------------------------\\n\\n// Media queries\\n// --------------------------------------------------\\n\\n@use \\"sass:color\\";\\n@use \\"sass:math\\";\\n@use \\"sass:string\\";\\n@use \\"sass:map\\";\\n@use \\"lib/viewport\\";\\n\\n$breakpoints: (\\n  mobile-small: map.get(viewport.$breakpoints, sm),\\n  mobile-medium: map.get(viewport.$breakpoints, sm),\\n  mobile-large: map.get(viewport.$breakpoints, sm),\\n  mobile-extra-large: map.get(viewport.$breakpoints, sm),\\n  tablet: map.get(viewport.$breakpoints, md),\\n  medium: map.get(viewport.$breakpoints, lg),\\n  large: map.get(viewport.$breakpoints, lg),\\n  extra-large: map.get(viewport.$breakpoints, xl),\\n);\\n\\n/* breakpoint is a legacy mixin. Use `@use \\"lib/viewport\\"` instead. */\\n@mixin breakpoint($bp, $rule: max-width, $type: screen, $sidebar: false) {\\n  /* stylelint-disable-next-line scss/no-global-function-names */\\n  $bp-value: map-get($breakpoints, $bp);\\n\\n  @if $rule == min-width {\\n    $bp-value: calc(#{$bp-value} + 1px);\\n  }\\n\\n  @media #{$type} and (#{$rule}: #{$bp-value}) {\\n    @content;\\n  }\\n\\n  // if you want to consider the sidebar in your breakpoint\\n  // you can pass in $sidebar: true\\n  // note that your breakpoint will need to be at the root level\\n  @if $sidebar {\\n    // when the sidebar is shown, we want to increase the breakpoints by the width of the sidebar\\n    /* stylelint-disable-next-line scss/no-global-function-names */\\n    @media #{$type} and (#{$rule}: calc(#{map-get($breakpoints, $bp)} + #{$d-sidebar-width})) {\\n      .has-sidebar-page {\\n        @content;\\n      }\\n    }\\n  }\\n}\\n\\n// CSS3 properties\\n// --------------------------------------------------\\n\\n// Clearfix\\n\\n@mixin clearfix() {\\n  &::before,\\n  &::after {\\n    content: \\"\\";\\n    display: table;\\n  }\\n\\n  &::after {\\n    clear: both;\\n  }\\n}\\n\\n@mixin linear-gradient($start-color, $end-color) {\\n  background-color: $start-color;\\n  background-image: linear-gradient(to bottom, $start-color, $end-color);\\n}\\n\\n@mixin darken-background($background-color, $amt) {\\n  $overlay: dark-light-choose(\\n    rgb(var(--primary-rgb), $amt),\\n    rgb(var(--secondary-rgb), $amt)\\n  );\\n  background-image: linear-gradient(to bottom, $overlay 100%, $overlay 100%);\\n}\\n\\n// Visibility\\n// --------------------------------------------------\\n\\n// Only shows hover on non-touch devices\\n@mixin hover {\\n  .discourse-no-touch &,\\n  .no-ember & {\\n    &:hover,\\n    &.btn-hover {\\n      @content;\\n    }\\n  }\\n}\\n\\n@mixin ellipsis {\\n  overflow: hidden;\\n  white-space: nowrap;\\n  text-overflow: ellipsis;\\n}\\n\\n@mixin line-clamp($lines) {\\n  display: -webkit-box;\\n  overflow: hidden;\\n  text-overflow: ellipsis;\\n  overflow-wrap: break-word;\\n  -webkit-line-clamp: $lines;\\n  -webkit-box-orient: vertical;\\n}\\n\\n//\\n// --------------------------------------------------\\n\\n$vpad: 0.5em;\\n$hpad: 0.65em;\\n\\n// for consistent sizing across inputs, buttons and dropdowns\\n@mixin form-item-sizing {\\n  border: 1px solid transparent;\\n  font-size: var(--font-0);\\n  line-height: normal;\\n  box-sizing: border-box;\\n  padding: $vpad $hpad;\\n}\\n\\n// Used to handle -webkit prefix, but now we have autoprefixer\\n// Keeping for backward-compat with plugins/themes only\\n@mixin user-select($mode) {\\n  user-select: $mode;\\n}\\n\\n// Unselectable (avoids unwanted selections with iPad, touch laptops, etc)\\n@mixin unselectable {\\n  cursor: default;\\n\\n  @include user-select(none);\\n}\\n\\n// Stuff we repeat\\n@mixin d-animation($name, $duration, $easing: ease) {\\n  animation: $name $duration $easing forwards;\\n\\n  @media (prefers-reduced-motion) {\\n    /* stylelint-disable-next-line no-invalid-position-declaration */\\n    animation-duration: 0s;\\n  }\\n}\\n\\n@mixin default-focus() {\\n  border-color: var(--d-input-focused-color);\\n  outline: 2px solid var(--d-input-focused-color);\\n  outline-offset: -2px;\\n}\\n\\n/// Helper function to easily use an SVG inline in CSS\\n/// without encoding it to base64, saving bytes.\\n/// It also helps with browser support, especially for IE11.\\n///\\n/// @author Jakob Eriksen\\n/// @link http://codepen.io/jakob-e/pen/doMoML\\n/// @param {String} $svg - SVG image to encode\\n/// @return {String} - Encoded SVG data uri\\n@function svg-uri($svg) {\\n  $encoded: \\"\\";\\n  $slice: 2000;\\n  $index: 0;\\n  $loops: math.ceil(math.div(string.length($svg), $slice));\\n\\n  @for $i from 1 through $loops {\\n    $chunk: string.slice($svg, $index, $index + $slice - 1);\\n    $chunk: str-replace($chunk, '\\"', \\"'\\");\\n    $chunk: str-replace($chunk, \\"<\\", \\"%3C\\");\\n    $chunk: str-replace($chunk, \\">\\", \\"%3E\\");\\n    $chunk: str-replace($chunk, \\"&\\", \\"%26\\");\\n    $chunk: str-replace($chunk, \\"#\\", \\"%23\\");\\n    $encoded: #{$encoded}#{$chunk};\\n    $index: $index + $slice;\\n  }\\n\\n  @return url(\\"data:image/svg+xml;charset=utf8,#{$encoded}\\");\\n}\\n\\n/// Replace `$search` with `$replace` in `$string`\\n/// @author Hugo Giraudel\\n/// @link http://sassmeister.com/gist/1b4f2da5527830088e4d\\n/// @param {String} $string - Initial string\\n/// @param {String} $search - Substring to replace\\n/// @param {String} $replace ('') - New value\\n/// @return {String} - Updated string\\n@function str-replace($string, $search, $replace: \\"\\") {\\n  $index: string.index($string, $search);\\n\\n  @if $index {\\n    @return string.slice($string, 1, $index - 1) + $replace +\\n      str-replace(\\n        string.slice($string, $index + string.length($search)),\\n        $search,\\n        $replace\\n      );\\n  }\\n\\n  @return $string;\\n}\\n\\n// SCSS accepts HEX or RGB colors for rgba($color, 0.5)\\n// CSS custom properties only accept RGB\\n// Example usage:\\n\\n// --primary-rgb: #{hexToRGB($primary)};\\n// ...\\n// rgba(var(--primary-low-rgb), 0.5)\\n\\n@function hexToRGB($hex) {\\n  @return color.red($hex), color.green($hex), color.blue($hex);\\n}\\n\\n@function schemeType() {\\n  @if is-light-color-scheme() {\\n    @return \\"light\\";\\n  } @else {\\n    @return \\"dark\\";\\n  }\\n}\\n\\n@function absolute-image-url($path) {\\n  // public_image_path is added by the stylesheet importer\\n  // it returns a CDN or subfolder path (if applicable).\\n  // SCSS will compile (and return the relative path) if public_image_path is missing.\\n  /* stylelint-disable-next-line scss/no-global-function-names */\\n  @if global-variable-exists(public_image_path) {\\n    @if string.index(\\"#{$path}\\", \\"/plugins\\") == 1 {\\n      $plugin_asset_path: str-replace($public_image_path, \\"/images\\", \\"\\");\\n\\n      @return url(\\"#{$plugin_asset_path}#{$path}\\");\\n    } @else {\\n      @return url(\\"#{$public_image_path}#{$path}\\");\\n    }\\n  } @else {\\n    @return url(\\"#{$path}\\");\\n  }\\n}\\n\\n@mixin mention() {\\n  // memo to self: do not make this inline-flex because it breaks text alignments and causes a whole avalance of unpleasant consequences\\n  display: inline-block;\\n  font-size: 0.93em;\\n  font-weight: normal;\\n  color: var(--primary);\\n  padding: 0.2em 0.34em;\\n  background: var(--mention-background-color);\\n  border-radius: 0.6em;\\n  text-decoration: none;\\n  text-wrap: nowrap;\\n  line-height: 1;\\n  unicode-bidi: plaintext;\\n\\n  &[data-valid=\\"false\\"] {\\n    background: unset;\\n    padding: 0;\\n  }\\n\\n  &.--bot {\\n    background: var(--success-low);\\n  }\\n\\n  &.--wide {\\n    background: var(--highlight-low-or-medium);\\n  }\\n}\\n\\n@mixin nav-active() {\\n  color: var(--d-nav-color--active);\\n  background: var(--d-nav-bg-color--active);\\n\\n  .d-icon {\\n    color: var(--d-nav-color--active);\\n  }\\n\\n  &::after {\\n    content: \\"\\";\\n    position: absolute;\\n    left: 0;\\n    bottom: 0;\\n    right: 0;\\n    height: var(--d-nav-underline-height);\\n    background: var(--d-nav-color--active);\\n\\n    // Forced colors drop backgrounds, which is the only thing that marks\\n    // the active item.\\n    @media (forced-colors: active) {\\n      background: Highlight;\\n      forced-color-adjust: none;\\n    }\\n  }\\n}\\n\\n@mixin nav-hover() {\\n  color: var(--d-nav-color--hover);\\n  background: var(--d-nav-bg-color--hover);\\n\\n  .d-icon {\\n    color: var(--d-nav-color--active);\\n  }\\n}\\n\\n// A strip that hides its scrollbar and fades the edge beyond which more\\n// content lies. The fade reads the data-d-scroll-* attributes stamped by\\n// the scroll-edges watcher, which DOverflowControls and the dScrollEdges\\n// modifier both run. The band starts fully transparent across --fade-inset\\n// so strip content never shows through a chevron parked on the edge, which\\n// assumes the chevron covers that band: a wrapper that pads the scroller's\\n// scrolling edge moves the chevron off it and hides content under nothing.\\n// #000 is deliberate: a mask reads only alpha, so a colour token would be\\n// wrong here.\\n@mixin scroll-strip() {\\n  // The bands are capped so the two ends cannot cross on a narrow strip.\\n  // Crossed bands leave no opaque middle.\\n  --scroll-strip-fade-start: min(var(--fade-inset, 0px), 15%);\\n  --scroll-strip-fade-end: min(\\n    calc(var(--fade-inset, 0px) + var(--fade-width, 2em)),\\n    40%\\n  );\\n  min-width: 0;\\n  min-height: 0;\\n  scrollbar-width: none;\\n  scroll-padding: calc(var(--fade-inset, 0px) + var(--fade-width, 2em));\\n\\n  &::-webkit-scrollbar {\\n    display: none;\\n  }\\n\\n  // Forced colors drop the mask, which would otherwise lower text contrast\\n  // for exactly the users who opted out of decoration.\\n  @media (forced-colors: none) {\\n    &[data-d-scroll-axis=\\"horizontal\\"][data-d-scroll-overflow] {\\n      mask-image: linear-gradient(\\n        to right,\\n        transparent var(--scroll-strip-fade-start),\\n        #000 var(--scroll-strip-fade-end),\\n        #000 calc(100% - var(--scroll-strip-fade-end)),\\n        transparent calc(100% - var(--scroll-strip-fade-start))\\n      );\\n\\n      // The edges are logical, the gradients physical, so RTL swaps them.\\n      &[data-d-scroll-at-start] {\\n        mask-image: linear-gradient(\\n          to right,\\n          #000 calc(100% - var(--scroll-strip-fade-end)),\\n          transparent calc(100% - var(--scroll-strip-fade-start))\\n        );\\n\\n        .rtl & {\\n          mask-image: linear-gradient(\\n            to left,\\n            #000 calc(100% - var(--scroll-strip-fade-end)),\\n            transparent calc(100% - var(--scroll-strip-fade-start))\\n          );\\n        }\\n      }\\n\\n      &[data-d-scroll-at-end] {\\n        mask-image: linear-gradient(\\n          to right,\\n          transparent var(--scroll-strip-fade-start),\\n          #000 var(--scroll-strip-fade-end)\\n        );\\n\\n        .rtl & {\\n          mask-image: linear-gradient(\\n            to left,\\n            transparent var(--scroll-strip-fade-start),\\n            #000 var(--scroll-strip-fade-end)\\n          );\\n        }\\n      }\\n    }\\n\\n    &[data-d-scroll-axis=\\"vertical\\"][data-d-scroll-overflow] {\\n      mask-image: linear-gradient(\\n        to bottom,\\n        transparent var(--scroll-strip-fade-start),\\n        #000 var(--scroll-strip-fade-end),\\n        #000 calc(100% - var(--scroll-strip-fade-end)),\\n        transparent calc(100% - var(--scroll-strip-fade-start))\\n      );\\n\\n      &[data-d-scroll-at-start] {\\n        mask-image: linear-gradient(\\n          to bottom,\\n          #000 calc(100% - var(--scroll-strip-fade-end)),\\n          transparent calc(100% - var(--scroll-strip-fade-start))\\n        );\\n      }\\n\\n      &[data-d-scroll-at-end] {\\n        mask-image: linear-gradient(\\n          to bottom,\\n          transparent var(--scroll-strip-fade-start),\\n          #000 var(--scroll-strip-fade-end)\\n        );\\n      }\\n    }\\n\\n    // The .rtl copy only exists to outrank the .rtl at-start/at-end rules\\n    // above, which score a class higher than the bare selector.\\n    &[data-d-scroll-overflow][data-d-scroll-at-start][data-d-scroll-at-end],\\n    .rtl\\n      &[data-d-scroll-overflow][data-d-scroll-at-start][data-d-scroll-at-end] {\\n      mask-image: none;\\n    }\\n  }\\n}\\n\\n// The scroll strip on the horizontal axis. The caller keeps its own items\\n// on one row; the mixin does not.\\n@mixin horizontal-scroll-strip() {\\n  @include scroll-strip;\\n  overflow-x: auto;\\n}\\n\\n@mixin click-counter-badge {\\n  content: attr(data-clicks);\\n  font-weight: normal;\\n  background-color: var(--primary-low);\\n  color: var(--primary-medium);\\n  position: relative;\\n  top: -1px;\\n  padding: 0.21em 0.42em;\\n  min-width: 0.5em;\\n  line-height: var(--line-height-small);\\n  font-size: var(--font-down-2);\\n  text-align: center;\\n  border-radius: 10px;\\n  white-space: nowrap;\\n  display: inline-block;\\n  margin: 0.15em;\\n}\\n\\n@mixin topic-list-icons {\\n  .d-icon-thumbtack {\\n    color: var(--primary-med-or-secondary-med);\\n  }\\n\\n  .d-icon-thumbtack.unpinned {\\n    color: var(--primary-med-or-secondary-med);\\n  }\\n\\n  a.title {\\n    color: var(--primary);\\n  }\\n\\n  .d-icon-bookmark {\\n    color: var(--primary-med-or-secondary-med);\\n  }\\n}\\n\\n@mixin hide-posters {\\n  width: 2em;\\n  text-align: center;\\n\\n  a:first-child .avatar.latest:not(.single) {\\n    top: 0;\\n    left: 0;\\n  }\\n\\n  a:not(.latest) {\\n    display: none;\\n  }\\n\\n  a.latest {\\n    width: 100%;\\n\\n    img {\\n      margin: 0 auto;\\n    }\\n  }\\n}\\n\\n@mixin dot-separator($size: 0.35em) {\\n  display: inline-block;\\n  width: $size;\\n  height: $size;\\n  margin-inline: var(--space-1);\\n  border-radius: 6.25em;\\n  background: var(--primary-low-mid);\\n  flex-shrink: 0;\\n}\\n\\n@mixin menu-item {\\n  display: inline-flex;\\n  gap: var(--d-sidebar-section-link-prefix-margin-right);\\n  padding: var(--space-2) var(--d-sidebar-row-horizontal-padding);\\n  width: 100%;\\n  justify-content: flex-start;\\n  background: rgb(0, 0, 0, 0);\\n  border-radius: var(--d-border-radius);\\n\\n  &:not(.notifications-tracking-btn, .--with-description, .pinned-options-btn) {\\n    height: var(--d-sidebar-row-height);\\n    padding-block: 0;\\n  }\\n\\n  &.-selected {\\n    background: var(--d-hover);\\n  }\\n\\n  &.btn-danger {\\n    color: var(--danger);\\n\\n    .d-icon {\\n      color: inherit;\\n    }\\n  }\\n\\n  .svg-icon {\\n    width: var(--d-sidebar-section-link-prefix-width);\\n    margin-right: 0;\\n  }\\n\\n  &:hover,\\n  &:focus-visible {\\n    .discourse-no-touch & {\\n      background: var(--d-hover);\\n      color: var(--primary);\\n\\n      .d-icon {\\n        color: inherit;\\n      }\\n\\n      &.btn-danger {\\n        background: var(--danger-low);\\n        color: var(--danger);\\n\\n        .d-icon {\\n          color: var(--danger-hover);\\n        }\\n      }\\n    }\\n  }\\n}\\n\\n@mixin unstyled-list {\\n  list-style: none;\\n  padding: 0;\\n  margin: 0;\\n}\\n","@use \\"lib/viewport\\";\\n\\n.voting .voting-wrapper {\\n  --d-button-border-radius: var(--d-border-radius-small);\\n  --primary-100: var(--d-selected);\\n  --primary-low: var(--d-selected);\\n\\n  &__button {\\n    background: var(--secondary);\\n  }\\n\\n  .discourse-no-touch & {\\n    button {\\n      &:focus-visible,\\n      &:hover {\\n        box-shadow: none;\\n      }\\n\\n      &:not(.btn-success) {\\n        .d-icon {\\n          color: var(--primary-high);\\n        }\\n      }\\n    }\\n  }\\n}\\n\\n.voting.header-title-voting .voting-wrapper {\\n  --primary-high: var(--header_primary-high);\\n\\n  @include viewport.from(lg) {\\n    --secondary: var(--background-color);\\n    --content-border-color: var(--d-sidebar-border-color);\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n$padding-pills-small: var(--space-half) var(--space-2);\\n\\n.topic-list-body:has(.--high-context) {\\n  --title-color--read: var(--primary-700);\\n  --topic-title-font-weight--visited: 600;\\n\\n  @include viewport.from(sm) {\\n    gap: var(--space-4);\\n  }\\n}\\n\\n.topic-list-item.--high-context {\\n  display: block;\\n  background: var(--secondary);\\n  padding: 0;\\n\\n  &.closed {\\n    opacity: 0.9;\\n  }\\n\\n  &.bulk-selecting {\\n    display: flex;\\n  }\\n\\n  &.bulk-selected {\\n    background: var(--tertiary-low);\\n    border-color: var(--tertiary);\\n\\n    &:hover {\\n      background: var(--tertiary-medium);\\n    }\\n  }\\n\\n  @include viewport.from(sm) {\\n    border: 1px solid var(--primary-low);\\n    border-radius: var(--d-border-radius-large);\\n  }\\n\\n  @include viewport.until(sm) {\\n    border-bottom: 1px solid var(--primary-low);\\n  }\\n\\n  &.selected {\\n    border-color: var(--accent-color);\\n    box-shadow: 0 0 12px 1px var(--topic-card-shadow);\\n  }\\n\\n  .bulk-select-enabled & {\\n    > .bulk-select {\\n      display: none;\\n    }\\n  }\\n}\\n\\n.hc-topic-card {\\n  display: flex;\\n  flex-direction: column;\\n  gap: var(--space-3);\\n  padding: var(--space-4) var(--space-5);\\n  width: 100%;\\n  box-sizing: border-box;\\n\\n  @include viewport.until(sm) {\\n    padding: var(--space-4) 0;\\n\\n    > *:not(.hc-topic-card__footer) {\\n      padding-inline: var(--space-4);\\n    }\\n  }\\n\\n  @include viewport.from(sm) {\\n    padding: var(--space-4);\\n  }\\n\\n  &__header {\\n    display: flex;\\n    justify-content: space-between;\\n    align-items: flex-start;\\n\\n    @include viewport.until(sm) {\\n      align-items: center;\\n    }\\n  }\\n\\n  &__op {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-2);\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1-rem);\\n  }\\n\\n  &__op-info {\\n    display: flex;\\n    flex-direction: column;\\n  }\\n\\n  &__avatar {\\n    flex-shrink: 0;\\n\\n    .avatar {\\n      border-radius: var(--d-border-radius);\\n      height: 32px;\\n      width: 32px;\\n    }\\n  }\\n\\n  &__status {\\n    position: relative;\\n    display: inline-flex;\\n    align-items: center;\\n    gap: var(--space-1);\\n    border-radius: var(--d-border-radius);\\n    white-space: nowrap;\\n    background: var(--secondary);\\n    border: 1px solid var(--primary-low-mid);\\n    font-weight: 700;\\n\\n    @include viewport.from(sm) {\\n      padding: $padding-pills-small;\\n    }\\n\\n    @include viewport.until(sm) {\\n      padding: var(--space-1);\\n      border-radius: calc(var(--d-border-radius) / 2);\\n    }\\n\\n    &.--solved {\\n      color: var(--success);\\n      font-weight: 700;\\n      border-color: var(--success);\\n    }\\n\\n    &.--pinned {\\n      font-weight: 700;\\n    }\\n\\n    &.--hot {\\n      border: 1px solid var(--danger);\\n      color: var(--danger);\\n    }\\n  }\\n\\n  &__category .badge-category__wrapper {\\n    padding: var(--space-half) var(--space-2) !important;\\n    font-size: var(--font-down-1-rem);\\n    border-radius: var(--d-border-radius-small) !important;\\n  }\\n\\n  &__status-tags {\\n    display: inline-flex;\\n    align-items: center;\\n    gap: var(--space-3);\\n\\n    @include viewport.from(sm) {\\n      font-size: var(--font-down-2-rem);\\n    }\\n\\n    @include viewport.until(sm) {\\n      font-size: var(--font-0);\\n    }\\n  }\\n\\n  &__content {\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-2);\\n  }\\n\\n  &__bulk-select {\\n    display: inline-flex;\\n    align-items: center;\\n    justify-content: center;\\n    padding-inline: var(--space-3) 0;\\n    cursor: pointer;\\n\\n    input {\\n      margin: 0;\\n    }\\n  }\\n\\n  &__title {\\n    font-weight: 700;\\n    font-size: var(--font-up-1-rem);\\n    color: var(--primary);\\n    text-decoration: none;\\n    line-height: 1.3;\\n\\n    a {\\n      color: var(--primary);\\n      word-break: break-word;\\n\\n      > * {\\n        pointer-events: none;\\n      }\\n    }\\n\\n    .topic-status.--pinned,\\n    .topic-status.--unpinned,\\n    .topic-status.--solved,\\n    .topic-status.--unsolved {\\n      display: none;\\n    }\\n  }\\n\\n  .topic-excerpt {\\n    overflow-wrap: anywhere;\\n\\n    .--high-context & {\\n      color: var(--primary-high);\\n      line-height: 1.25;\\n      display: -webkit-box;\\n      -webkit-line-clamp: 2;\\n      -webkit-box-orient: vertical;\\n      overflow: hidden;\\n      font-size: var(--font-0);\\n      width: 100%;\\n    }\\n  }\\n\\n  &__context {\\n    display: flex;\\n    gap: var(--space-3);\\n    flex-wrap: wrap;\\n  }\\n\\n  &__assigned {\\n    display: inline-flex;\\n    align-items: center;\\n    gap: var(--space-1);\\n    padding: $padding-pills-small;\\n    border-radius: var(--d-border-radius-small);\\n    background: var(--primary-very-low);\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-2-rem);\\n  }\\n\\n  &__tags {\\n    flex-shrink: 0;\\n    display: flex;\\n    gap: var(--space-2);\\n    flex-wrap: wrap;\\n\\n    .discourse-tags__tag-separator {\\n      display: none;\\n    }\\n\\n    .discourse-tag {\\n      padding: var(--space-half) var(--space-2);\\n      border-radius: var(--d-border-radius-small);\\n      border: 1px solid var(--primary-low);\\n      background: var(--secondary);\\n      color: var(--primary-high);\\n      white-space: nowrap;\\n      font-size: var(--font-down-2-rem);\\n\\n      &.assigned-to,\\n      &.list-vote-count {\\n        display: none;\\n      }\\n    }\\n  }\\n\\n  &__footer {\\n    position: relative;\\n    display: flex;\\n    flex-wrap: wrap;\\n    align-items: center;\\n    gap: var(--space-3);\\n\\n    @include viewport.from(sm) {\\n      border-top: 1px solid var(--primary-low);\\n      padding-top: var(--space-3);\\n    }\\n\\n    @include viewport.until(sm) {\\n      &::after {\\n        content: \\"\\";\\n        position: absolute;\\n        inset: 0;\\n        pointer-events: none;\\n        background: linear-gradient(\\n          to right,\\n          var(--secondary) 0,\\n          transparent 1rem,\\n          transparent calc(100% - 1rem),\\n          var(--secondary) 100%\\n        );\\n      }\\n    }\\n  }\\n\\n  &__category-tags {\\n    display: flex;\\n    gap: var(--space-2);\\n    overflow: auto;\\n\\n    @include viewport.until(sm) {\\n      padding-inline: var(--space-4);\\n    }\\n\\n    &::-webkit-scrollbar {\\n      display: none; // Chrome/Safari\\n    }\\n  }\\n\\n  &__category {\\n    flex-shrink: 0;\\n  }\\n\\n  &__stats {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-4);\\n    margin-left: auto;\\n    flex-shrink: 0;\\n\\n    @include viewport.until(sm) {\\n      padding-inline: var(--space-4);\\n    }\\n  }\\n\\n  &__replies,\\n  &__likes,\\n  &__votes {\\n    display: inline-flex;\\n    align-items: center;\\n    gap: var(--space-1);\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1-rem);\\n  }\\n\\n  &__last-reply {\\n    display: inline-flex;\\n    align-items: center;\\n    gap: var(--space-1);\\n    padding: $padding-pills-small;\\n    border-radius: var(--d-border-radius-small);\\n    background: var(--primary-very-low);\\n    font-size: var(--font-down-2-rem);\\n    color: var(--primary-medium);\\n\\n    .avatar {\\n      border-radius: 50%;\\n      height: 1rem;\\n      width: 1rem;\\n    }\\n\\n    @include viewport.until(sm) {\\n      .avatar {\\n        width: 1rem;\\n        height: 1rem;\\n      }\\n    }\\n  }\\n\\n  &__time {\\n    color: var(--primary-medium);\\n  }\\n}\\n",":root {\\n  --d-max-width: 1000px;\\n  --d-border-radius-large: 20px;\\n  --d-border-radius: 8px;\\n  --d-input-border-radius: 6px;\\n}\\n","@import \\"buttons\\";\\n@import \\"chat\\";\\n@import \\"categories-view\\";\\n@import \\"color-choice\\";\\n@import \\"compatibility\\";\\n@import \\"composer\\";\\n@import \\"composer-peek-mode\\";\\n@import \\"experimental-screen\\";\\n@import \\"discourse-events\\";\\n@import \\"header\\";\\n@import \\"hiddenstuff\\";\\n@import \\"login\\";\\n@import \\"main\\";\\n@import \\"misc\\";\\n@import \\"mobile-stuff\\";\\n@import \\"nav-pills\\";\\n@import \\"welcome-banner\\";\\n@import \\"sidebar\\";\\n@import \\"sidebar-new-topic-button\\";\\n@import \\"topic\\";\\n@import \\"topic-cards\\";\\n@import \\"topic-voting\\";\\n@import \\"high-context-cards\\";\\n@import \\"variables\\";\\n\\n:root {\\n  --d-nav-pill-border-radius: 0;\\n}\\n"]}
