  gap: 1rem;\\n\\n  .chat-message-creator-container {\\n    width: 100%;\\n  }\\n}\\n\\n// Info header\\n.c-channel-info-header {\\n  display: flex;\\n  justify-content: space-between;\\n  align-items: flex-start;\\n  padding: 1rem;\\n  box-sizing: border-box;\\n}\\n\\n.c-channel-info-header__title {\\n  font-size: var(--font-up-2);\\n  margin: 0;\\n}\\n",".chat-channel-divider__actions {\\n  display: flex;\\n  align-items: center;\\n  gap: var(--space-1);\\n}\\n\\n.chat-channel-list-options-button {\\n  padding: 0;\\n  background: transparent;\\n  color: var(--primary-medium);\\n  font-size: var(--font-0-rem);\\n\\n  &:hover {\\n    background: transparent;\\n  }\\n}\\n\\n.chat-channel-list-filter-menu,\\n.chat-channel-list-sort-menu {\\n  min-width: 17rem;\\n}\\n\\n.chat-channel-list-filter-menu .dropdown-menu__item,\\n.chat-channel-list-sort-menu .dropdown-menu__item,\\n.chat-channel-list-sort-choice {\\n  > .btn {\\n    height: auto;\\n    min-height: var(--d-sidebar-row-height);\\n\\n    > .d-icon {\\n      visibility: hidden;\\n    }\\n\\n    &[aria-checked=\\"true\\"] > .d-icon {\\n      visibility: visible;\\n    }\\n\\n    &.--with-description {\\n      padding-top: var(--space-2);\\n      padding-bottom: var(--space-2);\\n    }\\n  }\\n}\\n\\n.chat-channel-list-filter-menu__label,\\n.chat-channel-list-sort-menu__label {\\n  display: flex;\\n  flex-direction: column;\\n  align-items: flex-start;\\n}\\n\\n.chat-channel-list-filter-menu__label-description,\\n.chat-channel-list-sort-menu__label-description {\\n  color: var(--primary-medium);\\n  font-size: var(--font-down-1-rem);\\n  padding-inline-end: var(--space-2);\\n}\\n\\n.fk-d-menu-modal.chat-channel-list-options-menu-content {\\n  .dropdown-menu__subheader {\\n    padding-inline: var(--space-4);\\n  }\\n\\n  .dropdown-menu__divider {\\n    margin-block: var(--space-2);\\n  }\\n}\\n",".chat-channel-name {\\n  @include ellipsis;\\n  color: var(--primary);\\n\\n  .chat-channel-row__info & {\\n    display: flex;\\n    align-items: center;\\n    gap: 0.5em;\\n  }\\n\\n  .has-unread & {\\n    font-weight: bold;\\n  }\\n\\n  &__label {\\n    @include ellipsis;\\n  }\\n\\n  .emoji {\\n    height: 1em;\\n    width: 1em;\\n    vertical-align: baseline;\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.chat-thread:has(.chat-channel-preview-card) {\\n  .--channel-thread & {\\n    @include viewport.from(sm) {\\n      padding-bottom: var(--space-8);\\n      box-sizing: border-box;\\n    }\\n  }\\n}\\n\\n.chat-channel-preview-card {\\n  display: grid;\\n  grid-template-columns: auto 1fr auto;\\n  grid-template-areas:\\n    \\"icon title title\\"\\n    \\". body body\\"\\n    \\"actions actions actions\\";\\n  align-items: center;\\n  gap: var(--space-2) var(--space-3);\\n  padding: var(--space-4);\\n  border: 1px solid var(--tertiary-medium);\\n  background: rgb(var(--tertiary-rgb), 0.075);\\n  box-shadow: var(--shadow-card);\\n  border-radius: var(--d-border-radius-large);\\n  margin: var(--space-4) auto;\\n  margin-top: var(--space-1);\\n  width: max-content;\\n  min-width: 60%;\\n  box-sizing: border-box;\\n\\n  .--channel-thread & {\\n    @include viewport.from(sm) {\\n      display: none;\\n    }\\n  }\\n\\n  &.--no-access {\\n    grid-template-columns: auto 1fr;\\n    grid-template-areas:\\n      \\"icon title\\"\\n      \\"body body\\";\\n  }\\n\\n  @container (width >= 40rem) {\\n    grid-template-areas:\\n      \\"icon title actions\\"\\n      \\"icon body  actions\\";\\n\\n    &.--no-access {\\n      grid-template-areas:\\n        \\"icon title\\"\\n        \\"icon body\\";\\n    }\\n  }\\n\\n  .chat-drawer & {\\n    margin-inline: var(--space-4);\\n    max-width: calc(100% - var(--space-8));\\n  }\\n\\n  .full-page-chat & {\\n    @container (width < 40rem) {\\n      margin-inline: var(--space-4);\\n      max-width: calc(100% - var(--space-8));\\n    }\\n  }\\n\\n  &__icon {\\n    grid-area: icon;\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    flex: 0 0 auto;\\n    border-radius: 50%;\\n    background-color: var(--tertiary);\\n    color: var(--secondary);\\n    width: 2.5rem;\\n    height: 2.5rem;\\n\\n    @container (width < 40rem) {\\n      width: 2rem;\\n      height: 2rem;\\n    }\\n  }\\n\\n  &__title {\\n    grid-area: title;\\n    font-weight: 700;\\n  }\\n\\n  &__body {\\n    grid-area: body;\\n    color: var(--primary-high);\\n    font-size: var(--font-down-1);\\n  }\\n\\n  &__actions {\\n    grid-area: actions;\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-2);\\n\\n    @container (width < 40rem) {\\n      margin-top: var(--space-2);\\n    }\\n\\n    .chat-channel-preview-card.--anon & {\\n      justify-content: flex-end;\\n    }\\n  }\\n\\n  .toggle-channel-membership-button {\\n    @container (width < 40rem) {\\n      width: 100%;\\n    }\\n  }\\n}\\n",".chat-channel-title {\\n  @include ellipsis;\\n  display: flex;\\n  align-items: center;\\n  gap: 0.5rem;\\n\\n  &__user-info {\\n    overflow: hidden;\\n  }\\n\\n  .user-status-message {\\n    display: none; // we only show when in channels list\\n  }\\n\\n  &__user-status-message {\\n    flex-shrink: 3;\\n    overflow: hidden;\\n  }\\n\\n  .topic-chat-icon {\\n    color: var(--primary-medium);\\n    display: flex;\\n  }\\n\\n  .chat-unread-count {\\n    display: inline-block;\\n    color: var(--secondary);\\n    background-color: var(--tertiary-med-or-tertiary);\\n    font-size: var(--font-down-2);\\n    border-radius: 100%;\\n    min-width: 1.4em;\\n    min-height: 1.4em;\\n    height: 1.4em;\\n    width: 1.4em;\\n    padding: 1px;\\n    margin-left: 0.5rem;\\n    text-align: center;\\n  }\\n}\\n\\n.chat-channel-title__users-count {\\n  display: flex;\\n  border-radius: 50%;\\n  background: rgb(var(--primary-rgb), 0.1);\\n  width: 22px;\\n  height: 22px;\\n  box-sizing: border-box;\\n  justify-content: center;\\n  font-weight: 700;\\n  font-size: var(--font-down-1);\\n  align-items: center;\\n  padding: 0.25rem 0.5rem;\\n  color: var(--primary-high);\\n}\\n\\n.chat-channel-title__category-badge {\\n  color: var(--primary-medium);\\n  display: flex;\\n  font-size: var(--font-up-1);\\n  position: relative;\\n}\\n\\n.chat-channel-title__restricted-category-icon {\\n  background-color: var(--secondary);\\n  position: absolute;\\n  border-radius: 50%;\\n  padding: 2px 2px 3px;\\n  color: var(--primary-high);\\n  height: 0.5rem;\\n  width: 0.5rem;\\n  right: -0.5rem;\\n  top: -0.1rem;\\n}\\n\\n.chat-channel-title__category-title {\\n  .emoji {\\n    height: 1.2em;\\n    vertical-align: text-bottom;\\n    width: 1.2em;\\n  }\\n}\\n",".chat-composer-dropdown__trigger-btn {\\n  margin-left: 0.2rem;\\n\\n  .d-icon {\\n    padding: 5px;\\n    background: var(--primary-low);\\n    border-radius: 100%;\\n  }\\n\\n  &:focus,\\n  &:hover,\\n  &:active {\\n    .d-icon {\\n      color: var(--primary) !important;\\n    }\\n    background: none !important;\\n    background-image: none !important;\\n  }\\n}\\n\\n.chat-composer-dropdown__list {\\n  margin: 0;\\n  list-style: none;\\n  padding: 0.5rem;\\n}\\n\\n.chat-composer-dropdown__action-btn {\\n  width: 100%;\\n  justify-content: flex-start;\\n}\\n",".chat-composer-upload {\\n  display: inline-flex;\\n  height: 64px;\\n  padding: 0.5rem;\\n  border: 1px solid var(--primary-low-mid);\\n  margin-right: 0.5em;\\n  position: relative;\\n  border-radius: var(--d-border-radius);\\n  box-sizing: border-box;\\n\\n  &--image:not(.chat-composer-upload--in-progress) {\\n    padding: 0;\\n\\n    .preview-img {\\n      height: 62px;\\n      width: 62px;\\n      box-sizing: border-box;\\n    }\\n  }\\n\\n  &:last-child {\\n    margin-right: 0;\\n  }\\n\\n  &:hover {\\n    .chat-composer-upload__remove-btn {\\n      visibility: visible;\\n      background: rgb(var(--always-black-rgb), 0.9);\\n      padding: 5px;\\n      border-radius: 100%;\\n      font-size: var(--font-down-2);\\n    }\\n  }\\n\\n  &__remove-btn {\\n    border: 1px solid var(--primary-medium);\\n    position: absolute;\\n    top: -8px;\\n    right: -8px;\\n    visibility: hidden;\\n  }\\n\\n  .preview {\\n    width: 100%;\\n    height: 100%;\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    margin: 0;\\n\\n    .d-icon {\\n      font-size: var(--font-up-6);\\n      margin-right: 0.5rem;\\n    }\\n\\n    .preview-img {\\n      object-position: center;\\n      object-fit: cover;\\n      border-radius: var(--d-border-radius);\\n    }\\n  }\\n\\n  .data {\\n    display: flex;\\n    flex-direction: column;\\n    justify-content: center;\\n    line-height: var(--line-height-medium);\\n    font-size: var(--font-down-1);\\n    color: var(--primary-high);\\n\\n    .top-data,\\n    .bottom-data {\\n      display: flex;\\n      align-items: center;\\n    }\\n\\n    .file-name {\\n      display: inline-block;\\n      max-width: 150px;\\n      overflow: hidden;\\n      white-space: nowrap;\\n      text-overflow: ellipsis;\\n      margin-right: 0.5em;\\n    }\\n\\n    .uploading,\\n    .processing {\\n      font-size: var(--font-down-2);\\n      margin-right: 0.75em;\\n    }\\n\\n    .upload-progress {\\n      width: 110px;\\n    }\\n\\n    .extension-pill {\\n      background: var(--primary-low);\\n      border-radius: var(--d-border-radius);\\n      font-size: var(--font-down-2-rem);\\n      padding: 0.1em 0.4em;\\n    }\\n  }\\n}\\n",".chat-composer-uploads {\\n  max-width: 100%;\\n\\n  .chat-composer-uploads-container {\\n    padding: 0.5rem 1rem;\\n    display: flex;\\n    white-space: nowrap;\\n    overflow-x: auto;\\n  }\\n}\\n",".chat-thread__heading {\\n  padding: 0.5rem 0.5rem 0 0.5rem;\\n  display: flex;\\n  align-items: baseline;\\n}\\n\\n.chat-thread__heading-icon {\\n  color: var(--secondary-low);\\n  display: flex;\\n  background-color: var(--primary-100);\\n  padding: 0.5em;\\n  border-radius: 100%;\\n}\\n\\n.chat-thread__heading-title {\\n  padding-left: 0.5em;\\n  color: var(--secondary-low);\\n  margin-bottom: 0;\\n  word-break: break-word;\\n}\\n",":root {\\n  --d-chat-input-border-color: var(--primary-low);\\n  --d-chat-input-bg-color: rgb(var(--primary-very-low-rgb), 0.5);\\n  --d-chat-input-focused-shadow: 0 0 1px 0 var(--tertiary);\\n}\\n\\n.chat-composer {\\n  &__wrapper {\\n    display: flex;\\n    flex-direction: column;\\n    z-index: 3;\\n    padding: var(--space-1) 0 env(safe-area-inset-bottom) 0;\\n\\n    .keyboard-visible & {\\n      padding-bottom: 0;\\n    }\\n\\n    #chat-full-page-uploader,\\n    #chat-widget-uploader {\\n      display: none;\\n    }\\n\\n    .drop-a-file {\\n      display: none;\\n    }\\n\\n    .chat-replying-indicator {\\n      padding-inline: 1rem;\\n    }\\n  }\\n\\n  .chat-composer-button,\\n  .chat-composer-separator {\\n    align-self: flex-end;\\n  }\\n\\n  .chat-composer-separator {\\n    flex-shrink: 0;\\n  }\\n\\n  &__outer-container {\\n    display: flex;\\n    align-items: center;\\n    box-sizing: border-box;\\n    width: 100%;\\n    padding-inline: 1rem;\\n  }\\n\\n  &__inner-container {\\n    display: flex;\\n    align-items: center;\\n    box-sizing: border-box;\\n    width: 100%;\\n    flex-direction: row;\\n    border: 1px solid var(--d-chat-input-border-color);\\n    border-radius: var(--d-border-radius-large);\\n    background: var(--d-chat-input-bg-color);\\n    min-height: 50px;\\n    overflow: hidden;\\n\\n    .chat-composer.is-focused & {\\n      box-shadow: var(--d-chat-input-focused-shadow);\\n    }\\n\\n    .chat-composer.is-disabled & {\\n      background: var(--d-input-bg-color--disabled);\\n\\n      &:hover {\\n        cursor: not-allowed;\\n      }\\n    }\\n  }\\n\\n  &__input-container {\\n    display: flex;\\n    align-items: center;\\n    box-sizing: border-box;\\n    width: 100%;\\n    align-self: stretch;\\n  }\\n\\n  &__input {\\n    overflow-x: hidden;\\n    width: 100%;\\n    appearance: none;\\n    outline: none;\\n    border: 0;\\n    resize: none;\\n    max-height: 25dvh;\\n    background: none;\\n    padding: 0;\\n    margin: 5px 0;\\n    text-overflow: ellipsis;\\n    cursor: inherit;\\n    white-space: pre-wrap !important;\\n    min-width: 20px;\\n\\n    @include chat-scrollbar;\\n\\n    &[disabled] {\\n      background: none;\\n\\n      .d-icon {\\n        opacity: 0.4;\\n      }\\n    }\\n\\n    &:focus,\\n    &:active {\\n      outline: none;\\n    }\\n\\n    &::placeholder {\\n      overflow: hidden;\\n      text-overflow: ellipsis;\\n      white-space: nowrap;\\n    }\\n  }\\n}\\n\\n.chat-composer-message-details {\\n  margin: 0 1rem 0.5rem 1rem;\\n  display: flex;\\n  align-items: center;\\n\\n  .cancel-message-action {\\n    margin-left: auto;\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n.chat-composer-button {\\n  box-sizing: border-box;\\n  border: 0;\\n  height: 50px;\\n  background: none;\\n  padding-inline: 0.75rem;\\n\\n  @include viewport.until(sm) {\\n    width: 50px;\\n  }\\n\\n  .is-disabled & {\\n    cursor: not-allowed;\\n  }\\n\\n  &__wrapper {\\n    box-sizing: border-box;\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    align-self: flex-end;\\n  }\\n\\n  .d-icon {\\n    color: var(--primary-medium);\\n\\n    &:hover {\\n      color: var(--primary-medium);\\n    }\\n\\n    .is-focused & {\\n      color: var(--primary-high);\\n    }\\n\\n    .is-disabled & {\\n      color: var(--primary-low-mid);\\n      cursor: not-allowed;\\n    }\\n  }\\n\\n  &.-send {\\n    will-change: scale;\\n\\n    @keyframes sendingScales {\\n      0% {\\n        transform: scale(0.9);\\n      }\\n\\n      50% {\\n        transform: scale(1.2);\\n      }\\n\\n      100% {\\n        transform: scale(0.9);\\n      }\\n    }\\n\\n    .is-send-disabled & {\\n      cursor: default;\\n    }\\n\\n    .chat-composer.is-sending & {\\n      @media (prefers-reduced-motion: no-preference) {\\n        animation: sendingScales 1s infinite linear;\\n      }\\n    }\\n\\n    .d-icon {\\n      .is-send-enabled.is-focused & {\\n        color: var(--tertiary);\\n      }\\n    }\\n\\n    &:hover {\\n      .d-icon {\\n        .is-send-enabled & {\\n          transform: scale(1.2);\\n        }\\n      }\\n    }\\n  }\\n\\n  &.--emoji {\\n    transition: transform 0.1s ease-in-out;\\n\\n    &:hover {\\n      transform: scale(1.1);\\n    }\\n\\n    .d-icon {\\n      .is-focused & {\\n        color: var(--tertiary);\\n      }\\n    }\\n  }\\n}\\n",".chat-message__blocks {\\n  padding-block: 0.5em;\\n  display: flex;\\n  flex-direction: column;\\n  gap: 0.5em;\\n}\\n\\n.chat-message__block {\\n  .block__actions {\\n    display: flex;\\n    flex-wrap: wrap;\\n    gap: 0.5em;\\n  }\\n\\n  .block__button {\\n    .emoji {\\n      height: 18px;\\n      width: 18px;\\n    }\\n  }\\n\\n  .block__informative-wrapper {\\n    margin: 0.5em 0;\\n  }\\n\\n  .block__informative {\\n    display: flex;\\n    flex-direction: column;\\n    gap: 0.5em;\\n    padding: 0.5em 0;\\n  }\\n\\n  .block__informative-item {\\n    display: flex;\\n    align-items: stretch;\\n  }\\n\\n  .block__category {\\n    position: relative;\\n    display: flex;\\n    flex-direction: row;\\n    box-sizing: border-box;\\n    border-width: 0;\\n    border-radius: var(--d-border-radius);\\n    background-color: var(--d-category-box-background-color);\\n    border-left-width: var(--d-category-border-accent-width);\\n    border-style: solid;\\n    border-color: var(--category-badge-color, var(--primary-low));\\n    width: 100%;\\n  }\\n\\n  .block__category-inner {\\n    box-sizing: border-box;\\n    width: 100%;\\n    padding: 1em;\\n    display: flex;\\n    flex-direction: column;\\n    gap: 0.5em;\\n    border-width: var(--d-category-border-box-width);\\n    border-left-width: 0;\\n    border-style: solid;\\n    border-color: var(--primary-low);\\n    border-top-right-radius: var(--d-border-radius);\\n    border-bottom-right-radius: var(--d-border-radius);\\n  }\\n\\n  .block__category-heading {\\n    margin-bottom: 0.5em;\\n\\n    .badge-category__wrapper {\\n      font-size: var(--font-up-2);\\n    }\\n\\n    .badge-category__name {\\n      font-weight: bold;\\n      color: var(--primary);\\n    }\\n\\n    .block__category-link {\\n      text-decoration: none;\\n      color: inherit;\\n\\n      &:hover {\\n        .badge-category__name {\\n          color: var(--tertiary);\\n        }\\n      }\\n    }\\n  }\\n\\n  .block__category-parent {\\n    font-size: var(--font-down-1);\\n    color: var(--primary-high);\\n  }\\n\\n  .block__category-description {\\n    font-size: var(--font-0);\\n    color: var(--primary-high);\\n    line-height: var(--line-height-medium);\\n  }\\n}\\n","// Only push the drawer above the composer when JS has confirmed it should be\\n.chat-drawer-outlet-container.above-composer {\\n  padding-bottom: var(--composer-height, 0);\\n}\\n\\n.chat-drawer-resizer {\\n  position: absolute;\\n  top: -5px;\\n  width: 15px;\\n  height: 15px;\\n  z-index: z(\\"composer\\", \\"content\\");\\n\\n  .is-collapsed & {\\n    display: none;\\n  }\\n}\\n\\nhtml:not(.rtl) {\\n  .chat-drawer-resizer {\\n    cursor: nwse-resize;\\n    left: -5px;\\n  }\\n}\\n\\nhtml.rtl {\\n  .chat-drawer-resizer {\\n    cursor: nesw-resize;\\n    right: -5px;\\n  }\\n}\\n\\n.chat-drawer-outlet-container {\\n  // higher than timeline, lower than composer, dropdown, and user card\\n  z-index: z(\\"chat-drawer\\");\\n  position: fixed;\\n  right: var(--composer-right, 20px);\\n  left: 0;\\n  max-height: calc(100% - var(--header-offset) - 15px);\\n  margin: 0;\\n  padding: 0;\\n  display: flex;\\n  flex-direction: column;\\n  pointer-events: none !important;\\n  bottom: 0;\\n  box-sizing: border-box;\\n  transition: all 100ms ease-in;\\n  transition-property: bottom, padding-bottom;\\n}\\n\\n.peek-mode-active {\\n  .chat-drawer-outlet-container {\\n    z-index: z(\\"composer\\", \\"dropdown\\") + 1;\\n  }\\n\\n  .fk-d-menu[data-identifier=\\"chat-message-reaction-users\\"],\\n  .fk-d-menu[data-identifier=\\"chat-composer-dropdown__menu\\"] {\\n    z-index: z(\\"composer\\", \\"dropdown\\") + 2;\\n  }\\n}\\n\\n.chat-drawer {\\n  pointer-events: auto;\\n  align-self: flex-end;\\n  width: 400px;\\n  min-width: 250px !important; // important to override inline styles\\n  max-width: calc(100% - var(--composer-right));\\n  min-height: 300px !important; // important to override inline styles\\n  container-type: inline-size;\\n\\n  .chat-search__filters .filter-input-container {\\n    max-width: 250px;\\n  }\\n\\n  .chat-drawer-container {\\n    background: var(--secondary);\\n    border: 1px solid var(--content-border-color);\\n    border-bottom: 0;\\n    border-top-left-radius: var(--d-border-radius-large);\\n    border-top-right-radius: var(--d-border-radius-large);\\n    box-shadow: 0 0 4px rgb(0, 0, 0, 0.125);\\n    box-sizing: border-box;\\n    display: flex;\\n    flex-direction: column;\\n    position: relative;\\n    overflow: hidden;\\n  }\\n\\n  &.is-expanded {\\n    .chat-drawer-container {\\n      height: 100%;\\n    }\\n  }\\n\\n  &.is-collapsed {\\n    min-height: 0 !important;\\n    height: auto !important;\\n    max-width: 25vw;\\n  }\\n\\n  .chat-channel,\\n  .chat-thread,\\n  .chat-thread-list {\\n    height: 100%;\\n  }\\n}\\n\\n.chat-drawer-content {\\n  display: flex;\\n  flex-direction: column;\\n  box-sizing: border-box;\\n  height: 100%;\\n  min-height: 1px;\\n  position: relative;\\n  overflow-y: auto;\\n  overscroll-behavior: contain;\\n\\n  @include chat-scrollbar;\\n\\n  .c-channel-settings {\\n    flex-grow: 1;\\n\\n    .chat-form {\\n      height: 100%;\\n    }\\n\\n    .chat-form__section.--leave-channel {\\n      margin-top: auto;\\n      margin-bottom: 0;\\n    }\\n  }\\n}\\n",".chat-form {\\n  display: flex;\\n  flex-direction: column;\\n}\\n\\n.chat-form__section {\\n  display: flex;\\n  flex-direction: column;\\n  width: 100%;\\n  margin-bottom: 2rem;\\n\\n  &-title {\\n    font-weight: 700;\\n    font-size: var(--font-down-1);\\n    color: var(--primary-medium);\\n  }\\n\\n  &-title + &-content {\\n    margin-top: 0.25rem;\\n  }\\n\\n  &-content {\\n    gap: 1rem;\\n    display: flex;\\n    flex-direction: column;\\n  }\\n}\\n\\n.chat-form__row {\\n  display: flex;\\n  width: 100%;\\n\\n  // background: green;\\n  flex-direction: column;\\n  justify-content: center;\\n\\n  &.-separator {\\n    border-bottom: 1px solid var(--content-border-color);\\n  }\\n\\n  label,\\n  .d-toggle-switch__checkbox-slider {\\n    margin: 0;\\n  }\\n\\n  &-action {\\n    .chat-form__btn:first-child {\\n      padding-left: 0;\\n    }\\n  }\\n\\n  &-label + &-action {\\n    margin-left: auto;\\n  }\\n\\n  &.-link {\\n    color: var(--primary);\\n\\n    .d-icon {\\n      color: var(--primary-medium);\\n    }\\n  }\\n\\n  &-content {\\n    display: flex;\\n    flex-direction: row;\\n    justify-content: space-between;\\n    align-items: center;\\n    gap: 0.25rem;\\n  }\\n\\n  &-description {\\n    display: flex;\\n    padding-top: 3px;\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1);\\n  }\\n}\\n",".btn-floating.open-new-message-btn {\\n  position: fixed;\\n  background: var(--tertiary);\\n  bottom: 5rem;\\n  right: 2rem;\\n  border-radius: 50%;\\n  font-size: var(--font-up-3);\\n  padding: 0.5rem;\\n  transition:\\n    transform 0.25s ease,\\n    box-shadow 0.25s ease;\\n  z-index: z(\\"usercard\\");\\n  box-shadow: 0 5px 5px -1px rgb(0, 0, 0, 0.25);\\n\\n  .d-icon {\\n    color: var(--primary-very-low);\\n  }\\n\\n  &:active {\\n    box-shadow: 0 0 5px -1px rgb(0, 0, 0, 0.25);\\n    transform: scale(0.9);\\n  }\\n\\n  &:focus {\\n    @include default-focus;\\n    border-color: var(--d-nav-color--active);\\n    outline-color: var(--d-nav-color--active);\\n  }\\n}\\n\\n.channels-list,\\n.channels-list-container {\\n  position: relative;\\n  height: 100%;\\n  padding-bottom: 1rem;\\n\\n  @include chat-scrollbar;\\n\\n  .open-browse-page-btn,\\n  .open-draft-channel-page-btn,\\n  .chat-channel-leave-btn {\\n    position: relative;\\n    padding: 0;\\n    background: transparent;\\n    color: var(--primary-medium);\\n    font-size: var(--font-0-rem);\\n\\n    &::after {\\n      content: \\"\\";\\n      position: absolute;\\n      top: -50%;\\n      left: -50%;\\n      width: 200%;\\n      height: 200%;\\n    }\\n\\n    &:hover {\\n      background: transparent;\\n\\n      .d-icon {\\n        color: var(--primary);\\n      }\\n    }\\n  }\\n\\n  // keep the enlarged hit area from overlapping the adjacent metadata,\\n  // a stray tap there shouldn't close the channel\\n  @media (hover: none) {\\n    .chat-channel-leave-btn::after {\\n      inset-inline-start: 0;\\n      width: 100%;\\n    }\\n  }\\n\\n  &.starred-channels {\\n    padding-top: var(--space-2);\\n  }\\n}\\n\\n.chat-channel-divider {\\n  padding: 0.5rem 1rem 0.5rem 1rem;\\n  display: flex;\\n  align-items: center;\\n  justify-content: space-between;\\n  font-family: var(--heading-font-family);\\n  color: var(--primary);\\n  border-bottom: 1px solid var(--content-border-color);\\n\\n  .channel-title {\\n    line-height: var(--line-height-medium);\\n  }\\n}\\n",".chat-mention-warnings {\\n  display: flex;\\n  background: var(--tertiary-low);\\n  padding: 0.5em 0 0.5em 1em;\\n  color: var(--primary);\\n  margin: 0.5em;\\n\\n  .chat-mention-warning__icon,\\n  .chat-mention-warning__text {\\n    margin: 0.5em;\\n  }\\n\\n  .chat-mention-warnings-list__simple {\\n    margin: 0.5em 0 0 0;\\n    list-style: none;\\n  }\\n\\n  .chat-mention-warnings-list__multiple {\\n    margin: 0.5em 0 0 1em;\\n  }\\n\\n  .chat-mention-warning__header,\\n  .chat-mention-warning__icon {\\n    font-size: var(--font-up-2);\\n  }\\n}\\n\\n.full-page-chat .chat-mention-warnings {\\n  top: 2rem;\\n}\\n",".chat-message-actions-container {\\n  @include unselectable;\\n  position: absolute;\\n  width: max-content;\\n  right: var(--space-2);\\n  top: -0.75em;\\n  z-index: z(\\"composer\\", \\"content\\");\\n\\n  .-user-info-hidden & {\\n    top: -2em;\\n  }\\n\\n  &.is-size-full {\\n    padding-left: 60px; /* for easier mouse movement to the element */\\n  }\\n\\n  &.is-size-reduced {\\n    padding-left: 20px; /* for easier mouse movement to the element */\\n  }\\n}\\n\\n.chat-message-actions {\\n  border-radius: var(--d-border-radius);\\n  display: flex;\\n\\n  :is(button, summary):focus-visible {\\n    @include default-focus;\\n    z-index: 2;\\n  }\\n\\n  .link-to-message-btn {\\n    .d-icon {\\n      transition: all 0.25s ease-in-out;\\n    }\\n\\n    &.copied {\\n      .d-icon {\\n        transform: scale(1.1);\\n        color: var(--tertiary);\\n      }\\n    }\\n  }\\n\\n  .react-btn,\\n  .reply-btn,\\n  .chat-message-thread-btn,\\n  .bookmark-btn {\\n    margin-right: -1px;\\n    padding: 0.5em 0;\\n    width: 2.5em;\\n\\n    > * {\\n      pointer-events: none;\\n    }\\n\\n    &:focus-visible {\\n      .d-icon {\\n        color: var(--primary);\\n      }\\n    }\\n\\n    &:first-child:not(:hover) {\\n      border-color: var(--primary-300);\\n      border-right-color: transparent;\\n    }\\n\\n    .d-icon {\\n      color: var(--primary-medium);\\n\\n      &.bookmark-icon__bookmarked {\\n        color: var(--tertiary);\\n      }\\n    }\\n  }\\n\\n  &.has-no-secondary-actions {\\n    .reply-btn {\\n      border-right: 1px solid var(--primary-300);\\n      border-top: 1px solid var(--primary-300);\\n      border-bottom: 1px solid var(--primary-300);\\n    }\\n  }\\n\\n  .more-buttons.dropdown-select-box {\\n    .select-kit-header {\\n      background: none;\\n      border: 1px solid var(--primary-300);\\n      border-left-color: transparent;\\n      padding: 0.5em 0;\\n      width: 2.5em;\\n      transition: var(--d-button-transition);\\n      border-radius: var(--d-border-radius);\\n      border-top-left-radius: 0;\\n      border-bottom-left-radius: 0;\\n\\n      &:focus-visible {\\n        background: var(--primary-low);\\n\\n        .select-kit-header-wrapper .d-icon {\\n          color: var(--primary);\\n        }\\n      }\\n\\n      .select-kit-header-wrapper {\\n        justify-content: center;\\n\\n        .d-icon {\\n          color: var(--primary-medium);\\n          margin: 0;\\n        }\\n      }\\n\\n      &:hover {\\n        background: var(--primary-low);\\n        border-color: var(--primary-low-mid);\\n\\n        .select-kit-header-wrapper {\\n          .d-icon {\\n            color: var(--primary);\\n          }\\n        }\\n      }\\n    }\\n\\n    .select-kit-row {\\n      .texts .name {\\n        font-size: var(--font-0);\\n        font-weight: 500;\\n      }\\n\\n      .icons .d-icon {\\n        font-size: var(--font-0);\\n        color: var(--primary-medium);\\n      }\\n    }\\n  }\\n\\n  .chat-message-reaction {\\n    @include chat-reaction;\\n    align-items: center;\\n    border-radius: 0;\\n    border-left-color: transparent;\\n    border-right-color: transparent;\\n    box-sizing: border-box;\\n    font-size: var(--font-0);\\n    justify-content: center;\\n    margin: 0;\\n    margin-right: -1px;\\n    padding: 0.5em 0;\\n    width: 2.5em;\\n\\n    &:first-child {\\n      border-left-color: var(--primary-300);\\n      border-top-left-radius: var(--d-border-radius);\\n      border-bottom-left-radius: var(--d-border-radius);\\n    }\\n\\n    &.reacted {\\n      border-left-color: var(--tertiary-medium);\\n      z-index: 1;\\n    }\\n\\n    .emoji {\\n      height: 15px;\\n      width: auto;\\n      margin: 0;\\n    }\\n  }\\n}\\n","@mixin chat-reaction {\\n  align-items: center;\\n  display: inline-flex;\\n  padding: 0.3em 0.6em;\\n  margin: 1px 0.25em 1px 0;\\n  font-size: var(--font-down-2);\\n  border-radius: 4px;\\n  border: 1px solid var(--primary-300);\\n  background: transparent;\\n  cursor: pointer;\\n  user-select: none;\\n  transition:\\n    background 0.2s,\\n    border-color 0.2s;\\n\\n  &.reacted {\\n    border-color: var(--tertiary-medium);\\n    background: var(--tertiary-very-low);\\n    color: var(--tertiary-hover);\\n\\n    &:focus-visible,\\n    &:hover {\\n      background: var(--tertiary-low);\\n    }\\n  }\\n\\n  &:not(.reacted) {\\n    &:focus-visible,\\n    &:hover {\\n      background: var(--primary-low);\\n      border-color: var(--primary-low-mid);\\n    }\\n  }\\n\\n  .emoji {\\n    height: 15px;\\n    margin-right: 4px;\\n    width: auto;\\n  }\\n}\\n","$max_video_height: 150px;\\n\\n.chat-message-collapser {\\n  .chat-message-collapser-header {\\n    display: flex;\\n    align-items: center;\\n  }\\n\\n  .chat-message-collapser-header + div p {\\n    margin: 0;\\n  }\\n\\n  .chat-img-upload,\\n  .chat-other-upload,\\n  .chat-video-upload,\\n  .chat-message-collapser-header + div p img {\\n    margin-top: 0.25em;\\n    margin-bottom: 0.5em;\\n  }\\n\\n  .chat-video-upload {\\n    max-height: $max_video_height;\\n    width: calc(#{$max_video_height} / 9 * 16);\\n    max-width: 100%;\\n  }\\n\\n  .chat-message-collapser-link-small {\\n    font-size: 0.75em;\\n    white-space: nowrap;\\n    text-overflow: ellipsis;\\n    overflow: hidden;\\n  }\\n\\n  .chat-message-collapser-button {\\n    background: none;\\n    padding: unset;\\n    margin-left: 0.5em;\\n\\n    &:hover {\\n      background: none;\\n\\n      .d-icon {\\n        color: var(--primary);\\n      }\\n    }\\n  }\\n}\\n","$max_image_height: 150px;\\n$max_video_height: 250px;\\n\\n.chat-message {\\n  // append selectors to set images to a\\n  // max height of $max_image_height\\n  .onebox img:not(.ytp-thumbnail-image, .onebox-avatar-inline),\\n  img.onebox,\\n  .chat-uploads img,\\n  p img,\\n  aside.onebox .onebox-body .aspect-image-full-size,\\n  aside.onebox .onebox-body .aspect-image-full-size img,\\n  .chat-message-text p img:not(.emoji) {\\n    object-fit: contain;\\n    max-height: $max_image_height;\\n    max-width: 100%;\\n    width: unset;\\n    overflow: hidden;\\n  }\\n\\n  iframe.youtube-onebox {\\n    max-width: calc(#{$max_video_height} / 9 * 16);\\n  }\\n\\n  .onebox {\\n    &:not(img) {\\n      container-type: inline-size;\\n    }\\n\\n    .thumbnail {\\n      &.onebox-avatar {\\n        max-height: 100px;\\n        width: 20%;\\n        max-width: 60px;\\n        margin-right: 0.5rem;\\n      }\\n    }\\n\\n    .onebox-body .aspect-image {\\n      max-width: 50%;\\n    }\\n  }\\n\\n  .onebox:not(.githubpullrequest, .githubcommit, .githubissue) {\\n    @container (width < 400px) {\\n      .onebox-body {\\n        display: flex;\\n        flex-direction: column;\\n\\n        .thumbnail.onebox-avatar {\\n          display: none;\\n          max-width: 20%;\\n          margin-right: 0.5rem;\\n        }\\n\\n        .thumbnail {\\n          max-width: 100% !important;\\n          margin: 0;\\n        }\\n\\n        .aspect-image {\\n          margin-right: 0;\\n          max-width: 100%;\\n\\n          + h3 {\\n            margin-top: 0.25rem;\\n          }\\n        }\\n\\n        h3 {\\n          margin-block: 0.75rem 0;\\n        }\\n\\n        p {\\n          margin-top: 0.5rem;\\n        }\\n      }\\n    }\\n  }\\n\\n  .youtube-onebox {\\n    margin-top: var(--space-1);\\n  }\\n\\n  .onebox.twitterstatus {\\n    max-width: 500px;\\n\\n    .tweet-images {\\n      .tweet-video {\\n        height: calc(576px / (var(--aspect-ratio)));\\n        max-height: 400px;\\n      }\\n    }\\n\\n    .aspect-image-full-size {\\n      object-fit: initial;\\n      max-height: 400px;\\n\\n      .tweet-image {\\n        object-fit: initial;\\n        max-height: 400px;\\n      }\\n    }\\n\\n    .thumbnail.onebox-avatar {\\n      max-width: 38px;\\n      margin-right: var(--space-2);\\n      margin-top: var(--space-1);\\n    }\\n  }\\n\\n  .chat-message-collapser\\n    .chat-message-collapser-header\\n    + div\\n    .chat-message-collapser-lazy-video {\\n    object-fit: contain;\\n    max-height: $max_video_height;\\n    max-width: calc(#{$max_video_height} / 9 * 16);\\n    margin-top: var(--space-2);\\n\\n    &:has(div[data-provider-name=\\"tiktok\\"]) {\\n      max-height: unset;\\n    }\\n  }\\n}\\n",".chat-message-info {\\n  display: flex;\\n  align-items: center;\\n  justify-content: flex-start;\\n  gap: 0.25rem;\\n\\n  .chat-thread & {\\n    &:has(.chat-message-info__original-message) {\\n      flex-wrap: wrap;\\n    }\\n  }\\n}\\n\\n// The author of a chained message, carried for readers who cannot see that it belongs to\\n// the message above. `sr-only` clips it rather than removing it, so it stays focusable —\\n// it is left clipped even then, since revealing it would cover the message. The message\\n// takes the focus indicator in its place (see `.chat-message-container`).\\n.chat-message-info__username {\\n  display: inline-flex;\\n  align-items: baseline;\\n\\n  & + .chat-message-info__bot-indicator,\\n  & + .chat-message-info__date {\\n    white-space: nowrap;\\n    overflow: hidden;\\n    text-overflow: ellipsis;\\n  }\\n}\\n\\n.chat-message-info__username__name {\\n  color: var(--secondary-low);\\n  font-weight: 700;\\n\\n  @include ellipsis;\\n  max-width: 180px;\\n  padding: 0;\\n  border: none;\\n  background: none;\\n  font-size: inherit;\\n  font-family: inherit;\\n  line-height: inherit;\\n  cursor: pointer;\\n}\\n\\n.chat-message-info__bot-indicator {\\n  text-transform: uppercase;\\n  padding: 0.2rem 0.3rem;\\n  background: var(--primary-low);\\n  color: var(--primary-900);\\n  border-radius: var(--d-border-radius);\\n  font-size: var(--font-down-3);\\n  line-height: var(--line-height-medium);\\n  font-weight: 700;\\n  letter-spacing: 0.1ch;\\n}\\n\\n.chat-message-info__date {\\n  color: var(--primary-high);\\n  font-size: var(--font-down-1);\\n\\n  &:hover,\\n  &:focus {\\n    .chat-time {\\n      color: var(--primary);\\n    }\\n  }\\n}\\n\\n.chat-message-info__flag {\\n  color: var(--secondary-medium);\\n}\\n\\n.chat-message-info__bookmark {\\n  .d-icon-discourse-bookmark-clock,\\n  .d-icon-bookmark {\\n    color: var(--primary-low-mid);\\n    font-size: var(--font-down-2);\\n  }\\n}\\n\\n.chat-message-info__status {\\n  display: flex;\\n  margin-inline: 0.33rem;\\n\\n  .emoji {\\n    width: 15px;\\n    height: 15px;\\n  }\\n}\\n\\n.chat-message-info__original-message {\\n  @include ellipsis;\\n  display: flex;\\n  align-items: center;\\n  flex-wrap: wrap;\\n  font-size: var(--font-down-2);\\n  color: var(--primary-high);\\n  gap: 0.5em;\\n  line-height: 1.2;\\n  background: var(--tertiary-very-low);\\n  padding: 0.25em 0.75em;\\n  border-radius: 8px;\\n\\n  .chat-channel-title {\\n    gap: 0.25em;\\n  }\\n\\n  .chat-channel-name {\\n    color: var(--tertiary);\\n  }\\n\\n  .chat-channel-icon {\\n    .d-icon-d-chat {\\n      height: 0.9em;\\n      width: 0.9em;\\n    }\\n\\n    &__restricted-category-icon {\\n      background: var(--tertiary-very-low);\\n      height: 0.355em;\\n      width: 0.35em;\\n      margin-right: 0.4em;\\n      padding: 1px 1px 2px 1px;\\n    }\\n\\n    &:has(.--users-count) {\\n      display: none;\\n    }\\n  }\\n\\n  &__text,\\n  &__text:visited {\\n    color: var(--primary);\\n  }\\n}\\n",".chat-message-left-gutter {\\n  display: flex;\\n  align-items: center;\\n  justify-content: flex-start;\\n  flex-shrink: 0;\\n  width: var(--message-left-width);\\n}\\n\\n.chat-message-container:hover .chat-message-left-gutter {\\n  .chat-time {\\n    color: var(--secondary-medium);\\n  }\\n}\\n\\n.chat-message-left-gutter__date {\\n  color: var(--primary-high);\\n  font-size: var(--font-down-1);\\n}\\n\\n.chat-message-left-gutter__flag {\\n  color: var(--secondary-medium);\\n  padding-left: calc(50% - 15px);\\n}\\n\\n.chat-message-left-gutter__bookmark {\\n  .d-icon-discourse-bookmark-clock,\\n  .d-icon-bookmark {\\n    color: var(--primary-low-mid);\\n    font-size: var(--font-down-2);\\n    margin-left: 0.5em;\\n  }\\n}\\n",".chat-message-separator {\\n  @include unselectable;\\n  display: flex;\\n\\n  &-new {\\n    display: flex;\\n    justify-content: center;\\n    padding: 20px 0 20px var(--scrollbarWidth);\\n    position: relative;\\n\\n    .chat-message-separator__text-container {\\n      text-align: center;\\n      position: absolute;\\n      height: 40px;\\n      box-sizing: border-box;\\n      z-index: 1;\\n      top: 0;\\n      display: flex;\\n      align-items: center;\\n      justify-content: center;\\n\\n      .chat-message-separator__text {\\n        color: var(--danger-medium);\\n        background-color: var(--secondary);\\n        padding: 0.25rem 0.5rem;\\n        font-size: var(--font-down-1);\\n      }\\n    }\\n\\n    .chat-message-separator__line-container {\\n      width: 100%;\\n    }\\n\\n    .chat-message-separator__line {\\n      border-top: 1px solid var(--danger-medium);\\n    }\\n  }\\n\\n  &-date {\\n    box-sizing: border-box;\\n    position: absolute;\\n    width: 100%;\\n    z-index: 2;\\n    display: flex;\\n    align-items: flex-start;\\n    justify-content: center;\\n    padding-left: var(--scrollbarWidth);\\n    pointer-events: none;\\n\\n    &.with-last-visit {\\n      & + .chat-message-separator__line-container {\\n        .chat-message-separator__line {\\n          border-color: var(--danger-medium);\\n        }\\n      }\\n    }\\n\\n    .chat-message-separator__text-container {\\n      align-items: center;\\n      display: flex;\\n      height: 40px;\\n      position: sticky;\\n      top: -1px;\\n\\n      &.is-pinned,\\n      &.is-force-pinned {\\n        .chat-message-separator__text {\\n          border: 1px solid var(--primary-200);\\n          border-radius: var(--d-border-radius);\\n          color: var(--primary-800);\\n          background: var(--primary-50);\\n\\n          &:hover {\\n            border: 1px solid var(--secondary-high);\\n          }\\n        }\\n\\n        .chat-message-separator__last-visit {\\n          display: none;\\n        }\\n      }\\n    }\\n\\n    .chat-message-separator__last-visit {\\n      display: flex;\\n    }\\n\\n    .chat-message-separator__last-visit-separator {\\n      margin: 0 0.25rem;\\n    }\\n\\n    .chat-message-separator__text {\\n      @include unselectable;\\n      background-color: var(--secondary);\\n      border: 1px solid transparent;\\n      color: var(--secondary-low);\\n      font-size: var(--font-down-1);\\n      padding: 0.25rem 0.5rem;\\n      box-sizing: border-box;\\n      display: flex;\\n      cursor: pointer;\\n      pointer-events: all;\\n\\n      .no-touch & {\\n        &:hover {\\n          border: 1px solid var(--secondary-high);\\n          border-radius: var(--d-border-radius);\\n          color: var(--primary-800);\\n          background: var(--primary-50);\\n        }\\n      }\\n\\n      .touch & {\\n        &:active {\\n          border: 1px solid var(--secondary-high);\\n          border-radius: var(--d-border-radius);\\n          color: var(--primary-800);\\n          background: var(--primary-50);\\n        }\\n      }\\n\\n      &:active {\\n        transform: scale(0.98);\\n      }\\n    }\\n\\n    & + .chat-message-separator__line-container {\\n      padding: 20px var(--scrollbarWidth) 20px var(--scrollbarWidth);\\n      box-sizing: border-box;\\n\\n      .chat-message-separator__line {\\n        border-top: 1px solid var(--content-border-color);\\n        margin: 0 0 -1px;\\n      }\\n    }\\n  }\\n}\\n",".chat-message {\\n  container-type: inline-size;\\n}\\n\\n.chat-message-thread-indicator {\\n  cursor: pointer;\\n  grid-area: threadindicator;\\n  box-sizing: border-box;\\n  display: grid;\\n  grid-template-columns: auto 1fr auto auto;\\n  background-color: var(--primary-very-low);\\n  margin: 4px 0 -2px calc(var(--message-left-width) - 0.25rem);\\n  padding: 0.5rem;\\n  border-radius: var(--d-border-radius-large);\\n  color: var(--primary);\\n\\n  > * {\\n    pointer-events: none;\\n  }\\n\\n  &:visited,\\n  &:hover {\\n    color: var(--primary);\\n  }\\n\\n  &:hover {\\n    .chat-message-thread-indicator__replies-count {\\n      text-decoration: underline;\\n    }\\n  }\\n\\n  .no-touch & {\\n    &:hover {\\n      box-shadow: var(--shadow-dropdown);\\n    }\\n  }\\n\\n  &__last-reply-avatar {\\n    grid-area: avatar;\\n    margin-right: 0.5rem;\\n\\n    .chat-user-avatar {\\n      width: auto !important;\\n    }\\n  }\\n\\n  &__last-reply-username {\\n    @include ellipsis;\\n    font-weight: bold;\\n    color: var(--primary-very-high);\\n  }\\n\\n  &__last-reply-info {\\n    grid-area: info;\\n    display: flex;\\n    align-items: center;\\n    gap: 0.25rem;\\n  }\\n\\n  &__last-reply-timestamp {\\n    color: var(--primary-high);\\n    font-size: var(--font-down-3);\\n  }\\n\\n  &__last-reply-excerpt {\\n    @include ellipsis;\\n    grid-area: excerpt;\\n  }\\n\\n  .chat-thread-participants {\\n    grid-area: participants;\\n    flex-shrink: 0;\\n    display: flex;\\n    align-items: center;\\n    justify-content: flex-end;\\n    gap: 0.25rem;\\n    margin-left: 0.5rem;\\n  }\\n\\n  &__replies-count {\\n    @include ellipsis;\\n    color: var(--tertiary);\\n    font-size: var(--font-down-1);\\n    text-align: right;\\n  }\\n}\\n",".chat-message-text.-deleted,\\n.chat-message-text.-hidden {\\n  margin-left: calc(var(--message-left-width) + 0.75em);\\n  padding: 0;\\n\\n  .chat-message-expand {\\n    color: var(--primary-high);\\n    padding: 0.25em;\\n\\n    .d-button-label {\\n      text-align: left;\\n    }\\n\\n    &:hover {\\n      background: inherit;\\n      color: inherit;\\n    }\\n  }\\n}\\n\\n.chat-message-reaction {\\n  > * {\\n    pointer-events: none;\\n  }\\n}\\n\\n.chat-message {\\n  align-items: flex-start;\\n  padding: 0.25em 0.5em 0.25em 0.75em;\\n  display: flex;\\n  min-width: 0;\\n\\n  .search-highlight {\\n    background: var(--highlight-medium);\\n  }\\n\\n  .chat-message-reaction {\\n    @include chat-reaction;\\n    will-change: scale;\\n\\n    &:active {\\n      transform: scale(0.93);\\n    }\\n  }\\n\\n  .chat-message-content {\\n    display: flex;\\n    flex-direction: column;\\n    flex-grow: 1;\\n    word-break: break-word;\\n    overflow-wrap: break-word;\\n    min-width: 0;\\n  }\\n\\n  .chat-message-text {\\n    min-width: 0;\\n    width: 100%;\\n\\n    mark {\\n      background-color: var(--highlight);\\n    }\\n\\n    code {\\n      box-sizing: border-box;\\n      font-size: var(--font-down-1);\\n    }\\n\\n    span.mention {\\n      @include mention;\\n    }\\n\\n    .mention,\\n    span.mention.--wide {\\n      &.highlighted {\\n        background: var(--tertiary-low);\\n      }\\n\\n      .user-status-message {\\n        margin-left: var(--space-1);\\n\\n        .emoji {\\n          vertical-align: middle;\\n        }\\n      }\\n    }\\n\\n    // unlinked, invalid mention\\n    span.mention:not(.--wide) {\\n      color: var(--primary-high);\\n    }\\n\\n    // Automatic aspect-ratio mapping https://developer.mozilla.org/en-US/docs/Web/Media/images/aspect_ratio_mapping\\n    p img:not(.emoji) {\\n      max-width: 100%;\\n      height: auto;\\n    }\\n\\n    ul,\\n    ol {\\n      padding-left: 1.25em;\\n    }\\n  }\\n\\n  .chat-message-edited {\\n    display: inline-block;\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-2);\\n  }\\n\\n  .chat-message-reaction-list,\\n  .chat-transcript-reactions {\\n    @include unselectable;\\n    margin-top: 0.25em;\\n    display: flex;\\n    flex-wrap: wrap;\\n\\n    .react-btn {\\n      vertical-align: top;\\n      padding: 0 0.25em;\\n      background: none;\\n      border: none;\\n      will-change: scale;\\n\\n      &:active {\\n        transform: scale(0.93);\\n      }\\n\\n      > * {\\n        pointer-events: none;\\n      }\\n\\n      .d-icon {\\n        color: var(--primary-high);\\n      }\\n\\n      &:hover {\\n        .d-icon {\\n          color: var(--primary);\\n        }\\n      }\\n    }\\n  }\\n\\n  .chat-message-avatar .chat-user-avatar .chat-user-avatar__container .avatar,\\n  .chat-emoji-avatar .chat-emoji-avatar-container {\\n    width: 28px;\\n    height: 28px;\\n  }\\n}\\n\\n.touch .chat-message-container {\\n  &.-active {\\n    background: var(--d-hover);\\n    border-radius: var(--d-border-radius);\\n\\n    &.-bookmarked {\\n      background: var(--highlight-low);\\n    }\\n  }\\n}\\n\\n.no-touch .chat-message-container {\\n  &:hover {\\n    .chat-message-reaction-list .chat-message-react-btn {\\n      visibility: visible;\\n    }\\n  }\\n\\n  &:hover,\\n  &.-active {\\n    background: var(--d-hover);\\n\\n    &.-bookmarked {\\n      background: var(--highlight-medium);\\n    }\\n\\n    &.-deleted {\\n      background-color: var(--danger-low);\\n\\n      .chat-message-expand {\\n        color: var(--danger);\\n      }\\n    }\\n\\n    &.-highlighted {\\n      background-color: var(--tertiary-medium);\\n    }\\n  }\\n}\\n\\n.chat-message-container {\\n  background-color: var(--d-content-background, var(--secondary));\\n  width: 100%;\\n\\n  &.-errored {\\n    color: var(--primary-medium);\\n  }\\n\\n  &.-deleted {\\n    background-color: var(--danger-low);\\n    padding-block: 0.25rem;\\n  }\\n\\n  &.-bookmarked {\\n    background: var(--highlight-bg);\\n  }\\n\\n  &.-highlighted {\\n    background-color: var(--tertiary-low);\\n  }\\n\\n  &.has-reply {\\n    .chat-message {\\n      display: grid;\\n      grid-template-columns: var(--message-left-width) 1fr;\\n      grid-template-rows: 30px auto;\\n      grid-template-areas:\\n        \\"replyto replyto\\"\\n        \\"avatar message\\";\\n\\n      .chat-user-avatar {\\n        grid-area: avatar;\\n      }\\n\\n      .chat-message-content {\\n        grid-area: message;\\n      }\\n    }\\n  }\\n\\n  &.has-thread-indicator {\\n    .chat-message {\\n      display: grid;\\n      grid-template-columns: var(--message-left-width) 1fr;\\n      grid-template-rows: auto;\\n      grid-template-areas:\\n        \\"avatar message\\"\\n        \\"threadindicator threadindicator\\";\\n      padding-bottom: 0.65rem !important;\\n\\n      .chat-user-avatar {\\n        grid-area: avatar;\\n      }\\n\\n      .chat-message-content {\\n        grid-area: message;\\n      }\\n    }\\n  }\\n\\n  .chat-message-reaction-list .chat-message-react-btn {\\n    visibility: hidden;\\n  }\\n\\n  &.-not-interactive {\\n    .chat-message-content a,\\n    .chat-message-reaction-list,\\n    .chat-message-thread-indicator,\\n    .chat-message-info__date {\\n      pointer-events: none;\\n    }\\n  }\\n}\\n",".chat-notices {\\n  display: flex;\\n  flex-direction: column;\\n  gap: 0.5em;\\n  position: absolute;\\n  top: 0;\\n  z-index: 10;\\n  width: 100%;\\n\\n  .full-page-chat & {\\n    padding-inline: 1rem;\\n    box-sizing: border-box;\\n    top: 2rem;\\n  }\\n\\n  // float notices below the pinned bar only while it's actually visible\\n  .chat-channel:has(.chat-pinned-bar:not(.--dismissed, .--loading)) & {\\n    top: var(--chat-pinned-bar-height);\\n  }\\n\\n  &__notice,\\n  .chat-retention-reminder {\\n    display: flex;\\n    align-items: center;\\n    justify-content: space-between;\\n    background: var(--tertiary-low);\\n    padding: var(--space-2);\\n    color: var(--primary);\\n    min-width: 280px;\\n    margin-left: auto;\\n    margin-right: auto;\\n    gap: 0.25rem;\\n    box-sizing: border-box;\\n    border-radius: var(--d-border-radius);\\n\\n    .chat-drawer-outlet & {\\n      border-radius: 0;\\n    }\\n\\n    &:has(.dismiss-btn) {\\n      padding-right: 0;\\n    }\\n  }\\n\\n  .dismiss-btn {\\n    color: var(--primary-medium);\\n    align-self: flex-start;\\n\\n    .chat-drawer-outlet & {\\n      padding-top: var(--space-half);\\n    }\\n\\n    &:hover,\\n    &:focus {\\n      background: var(--tertiary-medium);\\n    }\\n  }\\n}\\n",".chat-onebox {\\n  .chat-onebox-body {\\n    .chat-onebox-title {\\n      display: inline;\\n      margin-bottom: 3px;\\n    }\\n\\n    .chat-onebox-description {\\n      color: var(--primary-medium);\\n    }\\n\\n    .chat-onebox-members-count {\\n      color: var(--primary-medium);\\n      margin-top: 1em;\\n      margin-bottom: 3px;\\n    }\\n\\n    .chat-onebox-members {\\n      align-items: center;\\n      color: var(--primary-medium);\\n      display: flex;\\n      flex-wrap: wrap;\\n\\n      .avatar {\\n        aspect-ratio: 30 / 30;\\n        margin-right: 0.25rem;\\n      }\\n    }\\n\\n    .chat-onebox-images.onebox {\\n      display: flex;\\n      flex-wrap: wrap;\\n\\n      img {\\n        width: auto;\\n        max-height: 150px;\\n        margin-right: 0.5rem;\\n        margin-top: 0.5em;\\n      }\\n    }\\n  }\\n}\\n\\n.chat-drawer-container .chat-message .onebox {\\n  width: 85%;\\n  border: 2px solid var(--primary-low);\\n\\n  header {\\n    margin-bottom: 0.5em;\\n  }\\n\\n  .onebox-body {\\n    grid-template-rows: auto auto auto;\\n    overflow: auto;\\n  }\\n\\n  h3 {\\n    @include line-clamp(2);\\n    font-weight: 500;\\n    font-size: var(--font-down-1);\\n  }\\n}\\n\\n.has-full-page-chat .chat-message .onebox:not(img),\\n.chat-drawer-container .chat-message .onebox {\\n  margin: 0.5em 0;\\n  border-width: 2px;\\n\\n  header {\\n    margin-bottom: 0.5em;\\n  }\\n\\n  h3 a,\\n  h4 a {\\n    font-size: 14px;\\n  }\\n\\n  pre {\\n    display: flex;\\n    max-height: 150px;\\n  }\\n\\n  p {\\n    overflow: hidden;\\n  }\\n}\\n",".chat-reply {\\n  align-items: center;\\n  display: grid;\\n  font-size: var(--font-down-1);\\n  grid: 1fr / auto-flow;\\n\\n  .d-icon {\\n    color: var(--primary-low-mid);\\n  }\\n\\n  .chat-user-presence-flair {\\n    width: 8px;\\n    height: 8px;\\n    right: -1px;\\n    bottom: -1px;\\n  }\\n\\n  .avatar {\\n    width: 20px;\\n    height: 20px;\\n  }\\n\\n  .chat-user-avatar {\\n    padding: 0 0.5rem;\\n  }\\n\\n  &.is-direct-reply {\\n    display: flex;\\n    cursor: pointer;\\n    grid-area: replyto;\\n  }\\n}\\n\\n.chat-reply__excerpt {\\n  @include ellipsis;\\n  color: var(--primary-high);\\n\\n  > * {\\n    margin-top: 0;\\n    display: inline-block;\\n  }\\n\\n  > p {\\n    margin-top: 0.35em;\\n  }\\n}\\n\\n.chat-reply__username {\\n  @include ellipsis;\\n  font-weight: 700;\\n  padding: 0 0.5em 0 0;\\n}\\n",".chat-replying-indicator {\\n  color: var(--primary-medium);\\n  display: inline-flex;\\n  font-size: var(--font-down-2);\\n\\n  &-container {\\n    display: flex;\\n    height: 1em; // Ensures the height is consistent even when empty\\n    line-height: normal;\\n  }\\n\\n  .chat-replying-indicator__text {\\n    display: inline-flex;\\n  }\\n\\n  .chat-replying-indicator__wave {\\n    flex: 0 0 auto;\\n    display: inline-flex;\\n\\n    .chat-replying-indicator__dot {\\n      display: inline-block;\\n\\n      @media (prefers-reduced-motion: no-preference) {\\n        animation: chat-replying-indicator__wave 1.8s linear infinite;\\n      }\\n\\n      &:nth-child(2) {\\n        animation-delay: -1.6s;\\n      }\\n\\n      &:nth-child(3) {\\n        animation-delay: -1.4s;\\n      }\\n    }\\n\\n    @keyframes chat-replying-indicator__wave {\\n      0%,\\n      60%,\\n      100% {\\n        transform: initial;\\n      }\\n\\n      30% {\\n        transform: translateY(-0.2em);\\n      }\\n    }\\n  }\\n}\\n",".chat-selection-management {\\n  border-top: 1px solid var(--content-border-color);\\n  display: flex;\\n  gap: 0.5rem;\\n  padding: 0.5rem;\\n\\n  .chat-drawer-content & {\\n    flex-direction: column;\\n  }\\n\\n  &__buttons {\\n    display: flex;\\n    flex-wrap: wrap;\\n    width: 100%;\\n    gap: 0.5rem;\\n\\n    button {\\n      flex: 1;\\n    }\\n  }\\n\\n  &__copy-success {\\n    animation: chat-quote-message-background-fade-highlight 2s ease-out 3s;\\n    animation-fill-mode: forwards;\\n    background-color: var(--success-low);\\n    color: var(--primary);\\n    flex: 1;\\n    line-height: normal;\\n    padding: 0.5rem 0.65rem;\\n\\n    @media (prefers-reduced-motion) {\\n      animation-duration: 0s;\\n    }\\n  }\\n\\n  @keyframes chat-quote-message-background-fade-highlight {\\n    100% {\\n      background-color: transparent;\\n      color: transparent;\\n    }\\n  }\\n}\\n",".chat-skeleton {\\n  height: auto;\\n\\n  &__body {\\n    padding: 