iner {\\n      display: flex;\\n      gap: 1rem;\\n    }\\n\\n    &__name {\\n      font-size: var(--font-up-1-rem);\\n      word-break: break-word;\\n\\n      &:hover {\\n        color: var(--primary-very-high);\\n      }\\n    }\\n  }\\n\\n  .chat-channel-icon {\\n    font-size: var(--font-down-1-rem);\\n  }\\n\\n  .chat-channel-name {\\n    font-size: var(--font-down-1-rem);\\n    color: var(--primary-high);\\n  }\\n\\n  .chat-channel-title__name {\\n    color: var(--primary-high);\\n    font-size: var(--font-down-1);\\n  }\\n}\\n\\n.c-list {\\n  overflow: auto;\\n}\\n\\n.c-list-empty-state {\\n  grid-column: 1/-1;\\n}\\n\\n.c-user-threads .empty-state-threads {\\n  display: flex;\\n  justify-content: center;\\n  padding: 1.25rem 1rem;\\n  font-size: var(--font-up-1-rem);\\n  color: var(--primary);\\n}\\n\\n// sidebar\\n#sidebar-section-content-user-threads {\\n  padding-bottom: 0.35em;\\n\\n  .sidebar-section-link-content-text {\\n    color: var(--d-sidebar-link-color);\\n  }\\n\\n  .active .sidebar-section-link-content-text {\\n    color: var(--d-sidebar-active-color);\\n  }\\n}\\n",".c-navbar-container {\\n  position: relative;\\n  border-bottom: 1px solid var(--content-border-color);\\n  background: var(--secondary);\\n  box-sizing: border-box;\\n  display: flex;\\n  padding: 0 0.67em;\\n\\n  &.-clickable {\\n    cursor: pointer;\\n  }\\n}\\n\\n.c-navbar {\\n  display: flex;\\n  align-items: flex-start;\\n  width: 100%;\\n  position: relative;\\n  container-type: inline-size;\\n\\n  .is-collapsed & {\\n    &__title {\\n      margin-left: 0 !important;\\n    }\\n\\n    &__toggle-drawer-button {\\n      // only shown for keyboard nav\\n      position: absolute;\\n      width: 1px;\\n      height: 1px;\\n      padding: 0;\\n      overflow: hidden;\\n      clip-path: inset(50%);\\n\\n      &:focus-visible {\\n        position: static;\\n        width: auto;\\n        height: auto;\\n        overflow: visible;\\n        clip-path: none;\\n      }\\n    }\\n  }\\n\\n  .single-select-header {\\n    padding: 0.3675rem 0.584rem;\\n  }\\n}\\n\\n.c-navbar__back-button {\\n  height: var(--chat-header-offset);\\n  padding: 0.5rem 0.8rem 0.5rem 0.25rem;\\n}\\n\\n.c-navbar__channel-title {\\n  @include ellipsis;\\n  font-weight: 700;\\n  height: var(--chat-header-offset);\\n  display: flex;\\n  align-items: center;\\n\\n  .chat-channel-title.is-dm .user-status-message {\\n    display: inline-flex;\\n  }\\n\\n  .chat-channel-title.is-dm .chat-channel-name__label {\\n    display: flex;\\n    align-items: center;\\n    gap: 0.5rem;\\n  }\\n}\\n\\n.c-navbar__star-channel-button {\\n  height: var(--chat-header-offset);\\n  color: var(--primary-medium);\\n\\n  &:hover,\\n  &:focus {\\n    color: var(--primary);\\n  }\\n\\n  &.--starred {\\n    color: var(--tertiary);\\n\\n    &:hover,\\n    &:focus {\\n      color: var(--tertiary-hover);\\n    }\\n  }\\n}\\n\\n.c-navbar__title {\\n  display: flex;\\n  align-items: center;\\n\\n  @include ellipsis;\\n  height: var(--chat-header-offset);\\n\\n  &-text {\\n    @include ellipsis;\\n    font-weight: 700;\\n    max-width: 100%;\\n    vertical-align: middle;\\n    padding-block: 5px;\\n\\n    > .d-icon {\\n      margin-right: 5px;\\n    }\\n  }\\n\\n  .d-icon {\\n    vertical-align: middle;\\n  }\\n}\\n\\n.c-navbar__sub-title {\\n  line-height: var(--line-height-small);\\n  font-size: var(--font-down-1-rem);\\n  font-weight: normal;\\n}\\n\\n.c-navbar__threads-list-button {\\n  gap: 0.25rem;\\n\\n  &.has-unreads {\\n    .d-icon-discourse-threads {\\n      color: var(--tertiary-med-or-tertiary);\\n    }\\n  }\\n}\\n\\n.c-navbar__actions {\\n  list-style: none;\\n  margin-left: auto;\\n  display: flex;\\n  align-items: center;\\n  height: var(--chat-header-offset);\\n\\n  .c-navbar__filter {\\n    &.active {\\n      .d-icon {\\n        color: var(--d-button-transparent-text-color--hover);\\n      }\\n    }\\n  }\\n}\\n\\n.c-navbar__back-button ~ .c-navbar__title {\\n  padding-left: 0;\\n}\\n",".chat__thread-title {\\n  display: flex;\\n\\n  &__name,\\n  &__name:visited {\\n    color: var(--primary);\\n  }\\n\\n  .chat-thread-list-item-unread-indicator {\\n    margin-left: 0.5rem;\\n  }\\n}\\n",".chat-audio-upload {\\n  max-width: 100%;\\n}\\n",".chat-message-container.-streaming {\\n  .stop-streaming-btn {\\n    margin-top: 0.5rem;\\n    margin-bottom: 0.25rem;\\n  }\\n}\\n",".chat-messages-scroller {\\n  flex-grow: 1;\\n  overflow-y: scroll;\\n  overscroll-behavior: contain;\\n  display: flex;\\n  flex-direction: column-reverse;\\n  z-index: 1;\\n  margin: 0 1px 0 0;\\n  will-change: transform;\\n  min-height: 1px;\\n  box-sizing: border-box;\\n\\n  @include chat-scrollbar {\\n    transition:\\n      scrollbar-color 0.25s ease-in-out,\\n      padding-top 0.2s ease-in-out;\\n  }\\n}\\n",".c-footer {\\n  grid-area: footer;\\n  background: var(--secondary);\\n  border-top: 1px solid var(--content-border-color);\\n  display: flex;\\n  align-items: flex-end;\\n  justify-content: space-between;\\n  position: sticky;\\n  bottom: 0;\\n  left: 0;\\n  padding-bottom: env(safe-area-inset-bottom);\\n\\n  html.footer-nav-ipad &,\\n  html.footer-nav-visible & {\\n    padding-bottom: calc(\\n      env(safe-area-inset-bottom) + var(--footer-nav-height, 0px)\\n    );\\n  }\\n\\n  &__item {\\n    display: flex;\\n    flex-direction: column;\\n    align-items: center;\\n    flex-basis: auto;\\n    flex-shrink: 1;\\n    flex-grow: 1;\\n    padding-block: 0.75rem;\\n    height: 100%;\\n    position: relative;\\n    color: var(--primary-medium);\\n\\n    &.--active {\\n      .d-icon,\\n      .d-button-label {\\n        color: var(--d-nav-color--active);\\n      }\\n    }\\n\\n    &:hover,\\n    &:focus {\\n      .discourse-no-touch &,\\n      .discourse-touch & {\\n        .d-icon,\\n        .d-button-label {\\n          color: var(--d-nav-color--active);\\n        }\\n      }\\n    }\\n\\n    .d-icon {\\n      margin-right: 0;\\n      font-size: var(--font-up-2);\\n      color: inherit;\\n\\n      &.d-icon-discourse-threads {\\n        font-size: var(--font-up-1); // visual correction\\n      }\\n    }\\n\\n    .d-button-label {\\n      font-size: var(--font-down-1-rem);\\n      color: var(--primary-medium);\\n    }\\n\\n    .c-unread-indicator {\\n      position: absolute;\\n      top: 0.35rem;\\n      right: unset;\\n      left: 50%;\\n      margin-left: 0.75rem;\\n\\n      &.-urgent {\\n        height: 1em;\\n        width: min-content;\\n        min-width: 0.6em;\\n        padding: 0.21em 0.42em;\\n      }\\n\\n      &:not(.-urgent) {\\n        width: 11px;\\n        height: 11px;\\n      }\\n    }\\n  }\\n}\\n\\n@container (max-width: 450px) {\\n  .c-footer {\\n    &__item {\\n      .d-button-label {\\n        font-size: var(--font-down-2-rem);\\n      }\\n    }\\n  }\\n}\\n\\n// iphone se is 375\\n@container (max-width: 374px) {\\n  .c-footer {\\n    &__item {\\n      .d-button-label {\\n        display: none;\\n      }\\n    }\\n  }\\n}\\n",".chat-message-search-entries {\\n  display: flex;\\n  flex-direction: column;\\n  gap: 0.5rem;\\n  padding: 0.5rem 0;\\n  list-style: none;\\n  margin: 0;\\n}\\n\\n.chat-message-search-entry {\\n  border: 1px solid var(--content-border-color);\\n  border-radius: var(--d-border-radius);\\n  padding: 0;\\n  cursor: pointer;\\n\\n  &__info {\\n    display: flex;\\n    align-items: center;\\n    gap: 0.5rem;\\n    padding: 0.65rem 1rem 0.15rem;\\n  }\\n\\n  &:hover,\\n  &:focus {\\n    box-shadow: var(--shadow-card);\\n  }\\n\\n  > * {\\n    pointer-events: none;\\n  }\\n\\n  .chat-message-container {\\n    background: none;\\n  }\\n\\n  .chat-thread__heading {\\n    padding: 0;\\n    align-items: center;\\n\\n    h2 {\\n      font-size: var(--font-0);\\n    }\\n  }\\n}\\n",".chat-channel__filter-bar {\\n  display: flex;\\n  width: 100%;\\n  gap: 0.5rem;\\n  border-bottom: 1px solid var(--content-border-color);\\n  background: var(--secondary);\\n  padding: 0.25rem 0.67em;\\n  box-sizing: border-box;\\n  flex-direction: column;\\n\\n  > div {\\n    display: flex;\\n    align-items: center;\\n    justify-content: space-between;\\n    gap: 0.25rem;\\n  }\\n\\n  .filter-input-container {\\n    margin-right: auto;\\n    border-color: var(--primary-low);\\n    width: 100%;\\n    max-width: 320px;\\n  }\\n\\n  .chat-channel__filter-position {\\n    white-space: nowrap;\\n    min-width: 40px;\\n    text-align: center;\\n    font-size: var(--font-down-1);\\n  }\\n}\\n",".c-routes.--search .c-search {\\n  flex: 1;\\n  min-height: 0;\\n  overflow-y: auto;\\n  padding-block: var(--space-5);\\n  margin-inline: var(--space-4);\\n}\\n\\n.c-routes.--search .c-search,\\n.c-drawer-routes.--search {\\n  .alert {\\n    margin-top: 0.5rem;\\n  }\\n}\\n\\n.chat-search__filters {\\n  display: flex;\\n  align-items: center;\\n  gap: 0.5rem;\\n  flex-wrap: wrap;\\n\\n  .filter-input-container {\\n    width: 100%;\\n    max-width: 500px;\\n  }\\n}\\n",".edit-category-chat {\\n  &__channel-name {\\n    .chat-channel-icon {\\n      font-size: var(--font-up-1);\\n      display: inline;\\n    }\\n  }\\n\\n  &__empty {\\n    color: var(--primary-medium);\\n  }\\n\\n  &__subcategory-toggle {\\n    display: flex;\\n    align-items: center;\\n    gap: 0.5em;\\n    margin-bottom: 1em;\\n  }\\n}\\n",".c-navbar__title .d-icon-thumbtack,\\n.chat-message-actions .d-icon-thumbtack {\\n  transform: rotate(45deg);\\n}\\n\\n.c-navbar__pinned-messages-btn {\\n  .d-icon {\\n    transform: rotate(45deg);\\n  }\\n}\\n\\n.chat-pinned-messages-list {\\n  display: flex;\\n  flex-direction: column;\\n  position: relative;\\n  overflow-y: scroll;\\n  box-sizing: border-box;\\n  overscroll-behavior: contain;\\n\\n  @include chat-scrollbar;\\n\\n  &.chat-messages-scroller {\\n    @include chat-height(\\n      calc(var(--chat-header-offset) + env(safe-area-inset-bottom))\\n    );\\n  }\\n}\\n\\n.chat-pinned-messages-list__empty {\\n  padding: 2rem;\\n  text-align: center;\\n  color: var(--primary-medium);\\n}\\n\\n.chat-pinned-messages-list__footer {\\n  position: sticky;\\n  inset-block-end: 0;\\n  margin-block-start: auto;\\n  padding: var(--space-2);\\n  background: var(--secondary);\\n  border-top: 1px solid var(--content-border-color);\\n}\\n\\n.chat-pinned-messages-list__dismiss,\\n.chat-pinned-messages-list__show {\\n  width: 100%;\\n  color: var(--primary-medium);\\n}\\n\\n.chat-pinned-message {\\n  position: relative;\\n  display: flex;\\n  align-items: flex-start;\\n  margin-inline: 1rem 0.75rem;\\n  border-bottom: 1px solid var(--content-border-color);\\n\\n  &__link {\\n    flex: 1;\\n    min-width: 0;\\n\\n    &,\\n    &:hover,\\n    &:visited,\\n    &:active {\\n      color: var(--primary);\\n      text-decoration: none;\\n    }\\n\\n    // stretch the click target across the whole row, under the unpin button\\n    &::before {\\n      content: \\"\\";\\n      position: absolute;\\n      inset: 0;\\n    }\\n  }\\n\\n  &__unpin {\\n    position: relative;\\n    z-index: 1;\\n    margin-block-start: 0.25em;\\n\\n    .discourse-no-touch & {\\n      opacity: 0;\\n    }\\n\\n    .discourse-no-touch .chat-pinned-message:hover &,\\n    &:focus-visible {\\n      opacity: 1;\\n    }\\n  }\\n\\n  .chat-message-container {\\n    background-color: transparent;\\n  }\\n\\n  .chat-user-avatar {\\n    width: auto;\\n  }\\n\\n  .chat-message-container:not(.-user-info-hidden) .chat-message {\\n    padding-inline: 0;\\n  }\\n\\n  .no-touch &:hover,\\n  .touch &:active {\\n    background-color: var(--d-hover);\\n    margin-inline: 0;\\n    padding-inline: 1rem 0.75rem;\\n  }\\n\\n  &__pinned-by {\\n    display: flex;\\n    align-items: center;\\n    gap: 0.25em;\\n    padding: 0.5em 0 0;\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1);\\n  }\\n\\n  &__pinned-by-icon {\\n    color: var(--tertiary);\\n    transform: rotate(45deg);\\n  }\\n}\\n\\n.chat-message-info__pinned {\\n  color: var(--primary-medium);\\n  margin-left: 0.25rem;\\n\\n  .d-icon {\\n    font-size: var(--font-down-2);\\n    transform: rotate(45deg);\\n  }\\n}\\n",".chat-channel {\\n  // shared by the bar (its height) and the floating notices (their top offset)\\n  --chat-pinned-bar-height: 2.75rem;\\n}\\n\\n.chat-pinned-bar {\\n  display: flex;\\n  align-items: stretch;\\n  gap: var(--space-1);\\n  min-width: 0; // allow the bar to shrink instead of forcing a min width on the channel/drawer\\n  min-height: var(--chat-pinned-bar-height);\\n  box-sizing: border-box;\\n  padding: var(--space-1) var(--space-2);\\n  border-bottom: 1px solid var(--content-border-color);\\n  background: var(--secondary);\\n  flex-shrink: 0;\\n  z-index: 2;\\n\\n  &.--loading,\\n  &.--dismissed {\\n    display: none;\\n  }\\n\\n  &__main {\\n    position: relative;\\n    flex: 1 1 auto;\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-2);\\n    min-width: 0;\\n    padding: var(--space-1) var(--space-2);\\n    text-align: start;\\n\\n    .no-touch &:hover .chat-pinned-bar__jump {\\n      background: var(--d-hover);\\n    }\\n  }\\n\\n  &__jump {\\n    position: absolute;\\n    inset: 0;\\n    padding: 0;\\n    background: transparent;\\n    border: 0;\\n    border-radius: 4px;\\n    cursor: pointer;\\n  }\\n\\n  &__indicator {\\n    position: relative;\\n    pointer-events: none;\\n    align-self: center;\\n    flex-shrink: 0;\\n    width: 3px;\\n    height: var(--chat-pinned-bar-indicator-height, 1.875rem);\\n    overflow: hidden;\\n    mask-image: linear-gradient(\\n      to bottom,\\n      transparent 0,\\n      black var(--chat-pinned-bar-fade-top, 0),\\n      black calc(100% - var(--chat-pinned-bar-fade-bottom, 0px)),\\n      transparent 100%\\n    );\\n  }\\n\\n  &__indicator-track {\\n    position: relative;\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--chat-pinned-bar-gap, 2px);\\n\\n    // scroll by one slot (bar + gap) per step\\n    transform: translateY(\\n      calc(\\n        var(--chat-pinned-bar-indicator-top, 0) *\\n          (var(--chat-pinned-bar-seg, 6px) + var(--chat-pinned-bar-gap, 2px)) *\\n          -1\\n      )\\n    );\\n\\n    @media (prefers-reduced-motion: no-preference) {\\n      transition: transform 150ms ease;\\n    }\\n  }\\n\\n  &__indicator-segment {\\n    flex: 0 0 auto;\\n    height: var(--chat-pinned-bar-seg, 6px);\\n\\n    // translucent tint of the active colour so dim bars keep contrast in both\\n    // schemes (--tertiary-low collapses into the dark-mode background)\\n    background: var(--tertiary);\\n    opacity: 0.4;\\n    border-radius: 3px;\\n  }\\n\\n  &__indicator-thumb {\\n    position: absolute;\\n    inset-inline: 0;\\n    inset-block-start: 0;\\n    height: var(--chat-pinned-bar-seg, 6px);\\n    background: var(--tertiary);\\n    border-radius: 3px;\\n    transform: translateY(\\n      calc(\\n        var(--chat-pinned-bar-active, 0) *\\n          (var(--chat-pinned-bar-seg, 6px) + var(--chat-pinned-bar-gap, 2px))\\n      )\\n    );\\n\\n    @media (prefers-reduced-motion: no-preference) {\\n      transition: transform 150ms ease;\\n    }\\n  }\\n\\n  &__content {\\n    // clicks still fall through to the overlay, except on links\\n    position: relative;\\n    pointer-events: none;\\n    display: flex;\\n    flex-direction: column;\\n    min-width: 0;\\n    overflow: hidden;\\n  }\\n\\n  &__label {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-1);\\n    color: var(--tertiary);\\n    font-size: var(--font-down-2);\\n    font-weight: 700;\\n\\n    .d-icon {\\n      font-size: var(--font-down-2);\\n      transform: rotate(45deg);\\n    }\\n  }\\n\\n  &__excerpt {\\n    @include ellipsis;\\n    color: var(--primary);\\n    font-size: var(--font-down-1);\\n\\n    // only links opt back into clicks; the rest of the bar jumps to the pin\\n    a {\\n      pointer-events: auto;\\n    }\\n  }\\n\\n  &__see-all,\\n  &__dismiss {\\n    position: relative;\\n    align-self: center;\\n    flex-shrink: 0;\\n\\n    .d-icon {\\n     