   background 0.15s ease;\\n\\n    .d-icon {\\n      width: 1.3rem;\\n      height: 1.3rem;\\n      color: var(--primary-medium);\\n    }\\n  }\\n\\n  &__empty-state-label {\\n    font-size: var(--font-down-2);\\n    font-weight: 400;\\n    line-height: 1.2;\\n    text-align: center;\\n    max-width: 10rem;\\n  }\\n\\n  &__rete-container {\\n    width: 100%;\\n    height: 100%;\\n    cursor: default;\\n\\n    &.is-selecting {\\n      cursor: crosshair;\\n    }\\n\\n    &.is-dragging {\\n      cursor: grabbing;\\n    }\\n\\n    * {\\n      transition: none !important;\\n    }\\n  }\\n\\n  &__selection-box {\\n    position: absolute;\\n    z-index: calc(var(--z-canvas-elements) + 3);\\n    pointer-events: none;\\n    border: 1px solid var(--tertiary);\\n    background: rgb(var(--tertiary-rgb), 0.14);\\n    border-radius: 2px;\\n  }\\n\\n  &__controls {\\n    position: absolute;\\n    bottom: var(--space-2);\\n    left: var(--space-2);\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-1);\\n    background: var(--secondary);\\n    border: 1px solid var(--primary-low-mid);\\n    border-radius: var(--d-border-radius);\\n    padding: var(--space-1);\\n    box-shadow: 0 2px 8px rgb(0, 0, 0, 0.1);\\n  }\\n\\n  &__zoom-label {\\n    font-size: var(--font-down-1);\\n    color: var(--primary-medium);\\n    min-width: 3em;\\n    text-align: center;\\n  }\\n\\n  &__publish-btn {\\n    min-width: 6.5em;\\n  }\\n\\n  &__top-bar {\\n    position: absolute;\\n    top: var(--space-2);\\n    right: var(--space-2);\\n    left: var(--space-2);\\n    z-index: var(--z-canvas-chrome);\\n    display: grid;\\n    grid-template-columns: minmax(0, 1fr) auto;\\n    align-items: start;\\n    gap: var(--space-2);\\n    pointer-events: none;\\n\\n    > * {\\n      pointer-events: auto;\\n    }\\n  }\\n\\n  &__publish-status {\\n    grid-column: 1;\\n    justify-self: center;\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-4);\\n    min-width: 0;\\n    max-width: min(100%, 36rem);\\n    padding: var(--space-1) var(--space-2);\\n    border: 1px solid var(--primary-low-mid);\\n    border-radius: var(--d-border-radius);\\n    background: var(--secondary);\\n    box-shadow: 0 2px 8px rgb(0, 0, 0, 0.1);\\n  }\\n\\n  &__publish-status-body {\\n    display: flex;\\n    align-items: flex-start;\\n    gap: var(--space-2);\\n    min-width: 0;\\n    line-height: 1.2;\\n  }\\n\\n  &__publish-status-icon {\\n    flex: 0 0 auto;\\n    margin-top: 0.1rem;\\n    color: var(--workflow-status-running);\\n    font-size: var(--font-down-1);\\n  }\\n\\n  &__publish-status-text {\\n    display: flex;\\n    flex-direction: column;\\n    min-width: 0;\\n  }\\n\\n  &__publish-status-title {\\n    overflow: hidden;\\n    color: var(--primary-high);\\n    font-size: var(--font-down-1);\\n    font-weight: 600;\\n    text-overflow: ellipsis;\\n    white-space: nowrap;\\n  }\\n\\n  &__publish-status-detail {\\n    overflow: hidden;\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-2);\\n    text-overflow: ellipsis;\\n    white-space: nowrap;\\n  }\\n\\n  &__publish-status-btn {\\n    flex: 0 0 auto;\\n  }\\n\\n  &__publish-status-actions {\\n    display: flex;\\n    flex: 0 0 auto;\\n    align-items: center;\\n    gap: var(--space-1);\\n  }\\n\\n  &__toolbar-top-right {\\n    grid-column: 2;\\n    justify-self: end;\\n    display: flex;\\n    gap: 6px;\\n  }\\n\\n  &__add-node-btn {\\n    background: var(--secondary);\\n    border: 1px solid var(--primary-low-mid);\\n    box-shadow: 0 2px 8px rgb(0, 0, 0, 0.1);\\n  }\\n\\n  &__menu-btn {\\n    background: var(--secondary);\\n    border: 1px solid var(--primary-low-mid);\\n    box-shadow: 0 2px 8px rgb(0, 0, 0, 0.1);\\n  }\\n\\n  &__context-menu {\\n    padding: var(--space-1) 0;\\n    min-width: 180px;\\n    max-height: 400px;\\n    overflow-y: auto;\\n  }\\n\\n  &__context-menu-item {\\n    width: 100%;\\n    justify-content: flex-start;\\n    padding: var(--space-1) var(--space-3);\\n    border-radius: 0;\\n    gap: var(--space-2);\\n    font-size: var(--font-down-1);\\n\\n    .d-icon {\\n      color: var(--node-icon-color, var(--primary-medium));\\n    }\\n\\n    &:hover {\\n      background: var(--primary-very-low);\\n    }\\n  }\\n}\\n\\n@keyframes workflow-highlight-pulse {\\n  0%,\\n  100% {\\n    box-shadow: 0 0 0 2px var(--tertiary-low);\\n  }\\n\\n  50% {\\n    box-shadow: 0 0 0 6px var(--tertiary-low);\\n  }\\n}\\n\\n@media screen and (width <= 767px) {\\n  .workflows-canvas {\\n    &__empty-state-options {\\n      gap: var(--space-4);\\n    }\\n\\n    &__empty-state-trigger {\\n      gap: 0.3rem;\\n    }\\n\\n    &__empty-state-tile {\\n      width: min(80px, calc(100vw - 3rem));\\n      border-radius: 8px;\\n\\n      .d-icon {\\n        width: 1.15rem;\\n        height: 1.15rem;\\n      }\\n    }\\n\\n    &__empty-state-label {\\n      font-size: var(--font-down-3);\\n    }\\n  }\\n}\\n\\n.workflow-rete-node {\\n  --icon-block-size: 56px;\\n  --icon-block-width: var(--icon-block-size);\\n  display: flex;\\n  flex-direction: column;\\n  align-items: center;\\n  position: relative;\\n  cursor: pointer;\\n  user-select: none;\\n  width: 130px;\\n\\n  &__icon-block,\\n  &__socket,\\n  &__label,\\n  &__description,\\n  &__unavailable-pill {\\n    pointer-events: auto;\\n  }\\n\\n  &__icon-row {\\n    position: relative;\\n  }\\n\\n  &__icon-block {\\n    width: var(--icon-block-width);\\n    height: var(--icon-block-size);\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    border-radius: 12px;\\n    border: 1px solid var(--primary-low-mid);\\n    background: var(--primary-very-low);\\n    position: relative;\\n    transition: border-color 0.15s;\\n  }\\n\\n  &:hover &__icon-block {\\n    border-color: var(--primary-medium);\\n  }\\n\\n  &.is-selected &__icon-block {\\n    border-color: var(--tertiary);\\n    background: color-mix(in srgb, var(--tertiary) 12%, var(--secondary));\\n    box-shadow: 0 0 0 1px var(--tertiary);\\n  }\\n\\n  @media (prefers-reduced-motion: no-preference) {\\n    &.is-highlighted &__icon-block {\\n      border-color: var(--tertiary);\\n      box-shadow: 0 0 0 3px var(--tertiary-low);\\n      animation: workflow-highlight-pulse 1.25s ease-in-out 4;\\n    }\\n  }\\n\\n  &.is-trigger {\\n    --icon-block-width: 74px;\\n  }\\n\\n  &.is-trigger &__icon-block {\\n    border-width: 2px;\\n    border-color: var(--node-icon-color, var(--primary-medium));\\n    border-radius: 999px 14px 14px 999px;\\n    background: rgb(\\n      from var(--node-icon-color, var(--primary-medium)) r g b / 0.12\\n    );\\n  }\\n\\n  &.is-trigger:hover &__icon-block {\\n    border-color: var(--primary-medium);\\n  }\\n\\n  &.is-trigger.is-selected &__icon-block {\\n    border-color: var(--tertiary);\\n  }\\n\\n  &__icon {\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    color: var(--node-icon-color, var(--primary-medium));\\n\\n    .d-icon {\\n      width: 24px;\\n      height: 24px;\\n    }\\n  }\\n\\n  &__unavailable-icon {\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    color: var(--danger);\\n\\n    .d-icon {\\n      width: 24px;\\n      height: 24px;\\n    }\\n  }\\n\\n  &__unavailable-pill {\\n    display: inline-flex;\\n    align-items: center;\\n    max-width: 100%;\\n    margin-top: var(--space-half);\\n    padding: 1px var(--space-1);\\n    border: 1px solid var(--danger-low-mid);\\n    border-radius: 3px;\\n    background: var(--danger-low);\\n    color: var(--danger);\\n    font-size: var(--font-down-3);\\n    font-weight: 600;\\n    line-height: 1.2;\\n  }\\n\\n  &__issues-badge {\\n    position: absolute;\\n    top: -6px;\\n    right: -6px;\\n    width: 20px;\\n    height: 20px;\\n    border-radius: 50%;\\n    background: var(--workflow-status-running);\\n    color: var(--secondary);\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    pointer-events: all;\\n    padding: 0;\\n    border: 2px solid var(--secondary);\\n    box-shadow: 0 1px 2px rgb(0 0 0 / 0.2);\\n    cursor: pointer;\\n\\n    .d-icon {\\n      width: 10px;\\n      height: 10px;\\n    }\\n  }\\n\\n  &__issues-title {\\n    padding: var(--space-1) var(--space-2) var(--space-half);\\n    font-size: var(--font-down-2);\\n    font-weight: bold;\\n    color: var(--primary);\\n  }\\n\\n  &__issues-list {\\n    margin: 0;\\n    padding: 0 var(--space-2) var(--space-1);\\n    font-size: var(--font-down-2);\\n    list-style: none;\\n    max-width: 260px;\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-half);\\n\\n    li {\\n      margin: 0;\\n      color: var(--primary);\\n      word-break: break-word;\\n    }\\n  }\\n\\n  &__label {\\n    margin-top: var(--space-1);\\n    font-size: var(--font-down-3);\\n    color: var(--primary);\\n    line-height: 1.2;\\n    text-align: center;\\n    max-width: 100%;\\n    overflow: hidden;\\n    display: -webkit-box;\\n    -webkit-line-clamp: 2;\\n    -webkit-box-orient: vertical;\\n  }\\n\\n  &__description {\\n    margin-top: var(--space-1);\\n    font-size: var(--font-down-3);\\n    color: var(--primary-medium);\\n    line-height: 1.2;\\n    text-align: center;\\n    max-width: 100%;\\n    overflow: hidden;\\n    display: -webkit-box;\\n    -webkit-line-clamp: 2;\\n    -webkit-box-orient: vertical;\\n  }\\n\\n  // Socket (port) styles\\n  &__socket {\\n    width: var(--socket-size);\\n    height: var(--socket-size);\\n    border-radius: 50%;\\n    background: var(--secondary);\\n    border: 1px solid var(--primary-low-mid);\\n    cursor: crosshair;\\n    flex-shrink: 0;\\n    transition: transform 0.15s;\\n    position: relative;\\n    z-index: var(--z-canvas-elements);\\n\\n    &:hover {\\n      transform: scale(1.3);\\n    }\\n\\n    &.is-connectable-hint {\\n      animation: workflow-socket-connectable-pulse 3s ease-in-out infinite;\\n    }\\n\\n    &.--output {\\n      &.--loop {\\n        cursor: default;\\n        pointer-events: none;\\n        animation: none;\\n      }\\n    }\\n  }\\n\\n  &__inputs {\\n    position: absolute;\\n    left: calc(-1 * (var(--socket-size) / 2));\\n    top: calc(50% - (var(--socket-size) / 2));\\n    display: flex;\\n    flex-direction: column;\\n    justify-content: center;\\n    gap: var(--space-1);\\n    z-index: var(--z-canvas-elements);\\n  }\\n\\n  &__input-row {\\n    width: var(--socket-size);\\n    height: var(--socket-size);\\n    position: relative;\\n    display: flex;\\n    align-items: center;\\n  }\\n\\n  &__inputs.has-multiple-inputs {\\n    top: calc(50% - (var(--socket-size) + 4px));\\n    gap: var(--space-2);\\n  }\\n\\n  &__input-label {\\n    position: absolute;\\n    right: 24px;\\n    top: 50%;\\n    transform: translateY(-50%);\\n    color: var(--primary-medium);\\n    font-size: 9px;\\n    font-weight: 400;\\n    letter-spacing: 0.3px;\\n    line-height: 1;\\n    pointer-events: none;\\n    padding: 2px 4px 2px 8px;\\n    background: var(--primary-very-low);\\n    border-radius: 3px;\\n    white-space: nowrap;\\n    z-index: calc(var(--z-canvas-elements) + 1);\\n  }\\n\\n  &__outputs {\\n    position: absolute;\\n    right: calc(-1 * (var(--socket-size) / 2) + 2px);\\n    top: calc(50% - (var(--socket-size) / 2));\\n    display: flex;\\n    flex-direction: column;\\n    justify-content: center;\\n    gap: var(--space-1);\\n  }\\n\\n  &.is-branching &__outputs {\\n    top: calc(50% - (var(--socket-size) + 4px));\\n    gap: var(--space-2);\\n  }\\n\\n  &__output-row {\\n    display: flex;\\n    align-items: center;\\n    gap: 10px;\\n    white-space: nowrap;\\n    position: relative;\\n    width: var(--socket-size);\\n    height: var(--socket-size);\\n  }\\n\\n  &__port-pill {\\n    font-size: 9px;\\n    font-weight: 400;\\n    text-transform: uppercase;\\n    letter-spacing: 0.3px;\\n    pointer-events: none;\\n    line-height: 1;\\n    white-space: nowrap;\\n    position: absolute;\\n    left: 14px;\\n    top: 50%;\\n    transform: translateY(-50%);\\n    color: var(--primary-medium);\\n    padding: 2px 8px 2px 4px;\\n    background: var(--primary-very-low);\\n    border-radius: 3px;\\n  }\\n\\n  &.is-unavailable {\\n    .workflow-rete-node__icon-block {\\n      border-color: var(--danger);\\n      border-style: dashed;\\n      background: color-mix(in srgb, var(--danger) 9%, var(--secondary));\\n      box-shadow: inset 0 0 0 1px rgb(from var(--secondary) r g b / 0.7);\\n    }\\n\\n    &:hover .workflow-rete-node__icon-block {\\n      border-color: var(--danger-hover);\\n    }\\n\\n    .workflow-rete-node__label {\\n      color: var(--primary-high);\\n    }\\n  }\\n}\\n\\n.workflow-rete-node__socket.is-invalid-connection-target {\\n  opacity: 0;\\n  pointer-events: none;\\n  transform: scale(0.75);\\n}\\n\\n.is-connection-dragging\\n  .workflow-rete-node-view:not(.is-connection-source)\\n  .workflow-rete-node {\\n  .workflow-rete-node__inputs:not(.has-multiple-inputs)\\n    .workflow-rete-node__socket.--input::after,\\n  &:not(.is-branching)\\n    .workflow-rete-node__socket.--output:not(.--loop)::after {\\n    content: \\"\\";\\n    position: absolute;\\n    top: calc((var(--socket-size) - var(--icon-block-size)) / 2);\\n    width: calc(var(--node-width) + var(--socket-size));\\n    height: var(--node-height);\\n  }\\n\\n  .workflow-rete-node__inputs:not(.has-multiple-inputs)\\n    .workflow-rete-node__socket.--input::after {\\n    left: calc((var(--icon-block-width) - var(--node-width)) / 2);\\n  }\\n\\n  &:not(.is-branching)\\n    .workflow-rete-node__socket.--output:not(.--loop)::after {\\n    left: calc(2px - (var(--node-width) + var(--icon-block-width)) / 2);\\n  }\\n}\\n\\n.is-connection-dragging\\n  .workflow-rete-node:has(.workflow-rete-node__socket:hover)\\n  .workflow-rete-node__icon-block {\\n  border-color: var(--tertiary);\\n}\\n\\n.workflow-rete-node-view {\\n  z-index: var(--z-canvas-elements);\\n  pointer-events: none;\\n}\\n\\n@keyframes workflow-socket-connectable-pulse {\\n  0%,\\n  65%,\\n  100% {\\n    border-color: var(--primary-low-mid);\\n    box-shadow: 0 0 0 0 rgb(var(--tertiary-rgb), 0);\\n  }\\n\\n  35% {\\n    border-color: var(--tertiary);\\n    box-shadow: 0 0 0 5px rgb(var(--tertiary-rgb), 0.18);\\n  }\\n}\\n\\n@media (prefers-reduced-motion: reduce) {\\n  .workflow-rete-node__socket.is-connectable-hint {\\n    animation: none;\\n    border-color: var(--tertiary);\\n    box-shadow: 0 0 0 2px rgb(var(--tertiary-rgb), 0.18);\\n  }\\n}\\n\\n// Handle styles (unlinked input/output -> [+] button)\\n.workflow-handle {\\n  .is-connection-dragging & {\\n    visibility: hidden;\\n  }\\n\\n  &__button-fo {\\n    pointer-events: all;\\n  }\\n\\n  &__add-btn {\\n    width: 14px;\\n    height: 14px;\\n    border-radius: 3px;\\n    border: 1px solid var(--primary-low-mid);\\n    background: var(--secondary);\\n    color: var(--primary-medium);\\n    cursor: pointer;\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    padding: 0;\\n\\n    .d-icon {\\n      width: 8px;\\n      height: 8px;\\n    }\\n\\n    &:hover {\\n      border-color: var(--tertiary);\\n      color: var(--tertiary);\\n    }\\n  }\\n}\\n\\n// Connection path styles\\n.workflow-connection {\\n  &__visible {\\n    transition:\\n      stroke 0.15s,\\n      stroke-width 0.15s;\\n    pointer-events: none;\\n  }\\n\\n  &__arrow {\\n    transition: fill 0.15s;\\n  }\\n\\n  &__hit {\\n    pointer-events: stroke;\\n    cursor: pointer;\\n\\n    &:hover ~ .workflow-connection__visible:not(.is-selected) {\\n      stroke: var(--primary-medium);\\n      stroke-width: 2;\\n    }\\n  }\\n\\n  &__toolbar-fo {\\n    pointer-events: none;\\n    opacity: 0;\\n    transition: opacity 0.15s;\\n\\n    &.is-visible {\\n      pointer-events: all;\\n      opacity: 1;\\n\\n      .workflow-canvas-toolbar {\\n        pointer-events: auto;\\n      }\\n    }\\n  }\\n}\\n\\n// Loop-back path (self-loop on Loop Over Items node)\\n.workflow-loop-back {\\n  &__path {\\n    pointer-events: none;\\n  }\\n\\n  &__button-fo {\\n    pointer-events: all;\\n  }\\n\\n  &__add-btn {\\n    width: 28px;\\n    height: 28px;\\n    border-radius: 50%;\\n    border: 1px solid var(--primary-low-mid);\\n    background: var(--secondary);\\n    color: var(--primary-medium);\\n    font-size: var(--font-up-1);\\n    cursor: pointer;\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    padding: 0;\\n    line-height: 1;\\n\\n    &:hover {\\n      border-color: var(--tertiary);\\n      color: var(--tertiary);\\n    }\\n  }\\n}\\n",".workflows-canvas {\\n  --workflows-canvas-ai-panel-top: calc(var(--space-2) + 3rem);\\n  --workflows-canvas-ai-panel-viewport-offset: 18rem;\\n\\n  &__ai-btn {\\n    background: var(--secondary);\\n    border: 1px solid var(--primary-low-mid);\\n    box-shadow: 0 2px 8px rgb(0, 0, 0, 0.1);\\n  }\\n\\n  &__ai-panel-shell {\\n    --workflows-canvas-ai-panel-available-height: min(\\n      calc(100% - var(--workflows-canvas-ai-panel-top) - var(--space-2)),\\n      calc(100dvh - var(--workflows-canvas-ai-panel-viewport-offset))\\n    );\\n    position: absolute;\\n    top: var(--workflows-canvas-ai-panel-top);\\n    right: var(--space-2);\\n    z-index: calc(var(--z-canvas-chrome) + 1);\\n    display: flex;\\n    align-items: flex-start;\\n    justify-content: flex-end;\\n    gap: var(--space-3);\\n    width: min(760px, calc(100% - var(--space-4)));\\n    height: var(--workflows-canvas-ai-panel-available-height);\\n    max-height: var(--workflows-canvas-ai-panel-available-height);\\n    pointer-events: none;\\n\\n    > * {\\n      pointer-events: auto;\\n    }\\n  }\\n\\n  &__ai-progress-panel {\\n    flex: 0 1 18rem;\\n    min-width: 14rem;\\n    max-height: 100%;\\n    min-height: 0;\\n    box-sizing: border-box;\\n    padding: var(--space-3);\\n    overflow-y: auto;\\n    border: 1px solid var(--primary-low);\\n    border-radius: var(--d-border-radius);\\n    background: var(--secondary);\\n    box-shadow: 0 10px 32px rgb(0, 0, 0, 0.16);\\n  }\\n\\n  &__ai-progress-title {\\n    margin: 0 0 var(--space-2);\\n    color: var(--primary-high);\\n    font-size: var(--font-down-1);\\n    font-weight: 700;\\n  }\\n\\n  &__ai-panel {\\n    display: flex;\\n    flex-direction: column;\\n    flex: 0 0 min(440px, 100%);\\n    gap: var(--space-4);\\n    width: min(440px, 100%);\\n    max-height: 100%;\\n    min-height: 0;\\n    min-width: 0;\\n    box-sizing: border-box;\\n    padding: var(--space-4);\\n    overflow-y: auto;\\n    border: 1px solid var(--primary-low);\\n    border-radius: 18px;\\n    background: var(--secondary);\\n    box-shadow: 0 16px 48px rgb(0, 0, 0, 0.22);\\n\\n    &.is-reviewing {\\n      overflow: hidden;\\n    }\\n  }\\n\\n  &__ai-panel-header {\\n    display: flex;\\n    align-items: flex-start;\\n    justify-content: space-between;\\n    gap: var(--space-3);\\n  }\\n\\n  &__ai-title-row {\\n    display: flex;\\n    flex-direction: column;\\n    min-width: 0;\\n\\n    h3 {\\n      margin: 0;\\n      color: var(--primary);\\n      font-size: var(--font-up-1);\\n      line-height: 1.15;\\n    }\\n\\n    p {\\n      margin: var(--space-half) 0 0;\\n      color: var(--primary-medium);\\n      font-size: var(--font-down-2);\\n      line-height: 1.25;\\n    }\\n  }\\n\\n  &__ai-title {\\n    display: flex;\\n    gap: var(--space-2);\\n    align-items: center;\\n  }\\n\\n  &__ai-title-icon {\\n    display: flex;\\n    flex: 0 0 auto;\\n    align-items: center;\\n    justify-content: center;\\n    width: 2.25rem;\\n    height: 2.25rem;\\n    border-radius: 50%;\\n    background: var(--tertiary-low);\\n    color: var(--tertiary);\\n  }\\n\\n  &__ai-close {\\n    flex: 0 0 auto;\\n  }\\n\\n  &__ai-status-row {\\n    display: flex;\\n    align-items: flex-start;\\n    gap: var(--space-2);\\n  }\\n\\n  &__ai-status {\\n    flex: 0 0 auto;\\n    padding: 0.2rem 0.55rem;\\n    border-radius: 999px;\\n    background: var(--primary-low);\\n    color: var(--primary-high);\\n    font-size: var(--font-down-3);\\n    font-weight: 700;\\n    line-height: 1.2;\\n    text-transform: uppercase;\\n\\n    &.is-working {\\n      background: var(--tertiary-low);\\n      color: var(--tertiary);\\n    }\\n\\n    &.is-ready {\\n      background: var(--success-low);\\n      color: var(--success);\\n    }\\n\\n    &.is-error {\\n      background: var(--danger-low);\\n      color: var(--danger);\\n    }\\n  }\\n\\n  &__ai-panel-description {\\n    margin: 0;\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1);\\n    line-height: 1.35;\\n  }\\n\\n  &__ai-prompt-wrap {\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-1);\\n\\n    label {\\n      color: var(--primary-high);\\n      font-size: var(--font-down-1);\\n      font-weight: 600;\\n    }\\n  }\\n\\n  &__ai-prompt {\\n    width: 100%;\\n    min-height: 11rem;\\n    box-sizing: border-box;\\n    resize: vertical;\\n    border-radius: var(--d-border-radius);\\n  }\\n\\n  &__ai-panel-actions,\\n  &__ai-review-actions {\\n    display: flex;\\n    flex-wrap: wrap;\\n    gap: var(--space-2);\\n    justify-content: flex-end;\\n  }\\n\\n  &__ai-start-over-btn {\\n    flex: 0 0 auto;\\n    min-width: 6.75rem;\\n    white-space: nowrap;\\n  }\\n\\n  &__ai-review-step {\\n    display: flex;\\n    flex: 1 1 auto;\\n    flex-direction: column;\\n    gap: var(--space-3);\\n    min-height: 0;\\n  }\\n\\n  &__ai-review-actions {\\n    flex: 0 0 auto;\\n    justify-content: flex-start;\\n  }\\n\\n  &__ai-review-footer {\\n    display: flex;\\n    flex: 0 0 auto;\\n    justify-content: flex-end;\\n    padding-top: var(--space-3);\\n    border-top: 1px solid var(--primary-low);\\n    background: var(--secondary);\\n  }\\n\\n  &__ai-clarification {\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-3);\\n  }\\n\\n  &__ai-clarification-header {\\n    h4,\\n    p {\\n      margin: 0;\\n   