ght: 600;\\n      line-height: 1.25;\\n    }\\n\\n    small {\\n      color: var(--primary-medium);\\n      font-size: var(--font-down-2);\\n      line-height: 1.25;\\n    }\\n\\n    &:hover,\\n    &.is-selected {\\n      border-color: var(--tertiary);\\n      box-shadow: 0 0 0 1px var(--tertiary-low);\\n    }\\n\\n    &.is-selected {\\n      background: var(--tertiary-low);\\n    }\\n  }\\n\\n  &__ai-custom-answer {\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-1);\\n    width: 100%;\\n\\n    > span {\\n      color: var(--primary-medium);\\n      font-size: var(--font-down-2);\\n      font-weight: 600;\\n    }\\n  }\\n\\n  &__ai-custom-answer-input {\\n    width: 100%;\\n    min-height: 4rem;\\n    box-sizing: border-box;\\n    resize: vertical;\\n    border-radius: var(--d-border-radius);\\n  }\\n\\n  &__ai-progress {\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-2);\\n    margin: 0;\\n    padding: 0;\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1);\\n    list-style: none;\\n\\n    li {\\n      position: relative;\\n      display: flex;\\n      align-items: flex-start;\\n      gap: var(--space-2);\\n      line-height: 1.35;\\n\\n      &:not(:last-child)::after {\\n        content: \\"\\";\\n        position: absolute;\\n        top: 1rem;\\n        left: 0.25rem;\\n        width: 1px;\\n        height: calc(100% - 0.35rem);\\n        background: var(--primary-low-mid);\\n      }\\n    }\\n\\n    &.is-working li:last-child .workflows-canvas__ai-progress-marker {\\n      animation: workflow-ai-progress-pulse 1.2s ease-in-out infinite;\\n    }\\n  }\\n\\n  &__ai-progress-marker {\\n    flex: 0 0 auto;\\n    width: 0.55rem;\\n    height: 0.55rem;\\n    margin-top: 0.35rem;\\n    border-radius: 50%;\\n    background: var(--tertiary);\\n    box-shadow: 0 0 0 3px var(--tertiary-low);\\n  }\\n\\n  &__ai-response,\\n  &__ai-proposal {\\n    max-width: 100%;\\n    min-width: 0;\\n    box-sizing: