danger);\\n  }\\n}\\n\\n@keyframes workflow-ai-progress-pulse {\\n  0%,\\n  100% {\\n    box-shadow: 0 0 0 3px var(--tertiary-low);\\n  }\\n\\n  50% {\\n    box-shadow: 0 0 0 6px var(--tertiary-low);\\n  }\\n}\\n",".workflow-canvas-toolbar {\\n  position: absolute;\\n  top: -30px;\\n  left: 50%;\\n  transform: translateX(-50%);\\n  display: flex;\\n  align-items: center;\\n  gap: 4px;\\n  opacity: 0;\\n  pointer-events: none;\\n  transition: opacity 0.15s;\\n  z-index: calc(var(--z-canvas-elements) + 2);\\n\\n  &.is-visible {\\n    opacity: 1;\\n    pointer-events: auto;\\n  }\\n\\n  &.--inline {\\n    position: static;\\n    transform: none;\\n    opacity: 1;\\n    width: fit-content;\\n    margin: 0 auto;\\n  }\\n\\n  .workflows-canvas__rete-container.is-dragging & {\\n    opacity: 0;\\n    pointer-events: none;\\n  }\\n\\n  &__btn,\\n  &__btn.btn {\\n    width: 22px;\\n    height: 22px;\\n    border-radius: 4px;\\n    border: none;\\n    background: var(--primary-very-high);\\n    color: var(--secondary);\\n    cursor: pointer;\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    padding: 0;\\n    box-shadow: 0 2px 8px rgb(0 0 0 / 0.15);\\n\\n    .d-icon {\\n      font-size: var(--font-down-3);\\n      color: inherit;\\n    }\\n\\n    &:hover,\\n    &:focus-visible {\\n      background: var(--primary-high);\\n\\n      .d-icon {\\n        color: inherit;\\n      }\\n    }\\n\\n    &.--success {\\n      background: var(--workflow-status-success);\\n\\n      &:hover {\\n        background: color-mix(\\n          in srgb,\\n          var(--workflow-status-success) 85%,\\n          black\\n        );\\n      }\\n    }\\n\\n    &.is-disabled,\\n    &:disabled {\\n      background: var(--primary-low-mid);\\n      color: var(--primary-medium);\\n      cursor: not-allowed;\\n      box-shadow: none;\\n      opacity: 1;\\n\\n      &:hover,\\n      &:focus-visible {\\n        background: var(--primary-low-mid);\\n        color: var(--primary-medium);\\n      }\\n    }\\n  }\\n}\\n",".workflows-node-panel {\\n  position: fixed;\\n  top: 0;\\n  right: 0;\\n  width: 320px;\\n  height: 100vh;\\n  display: flex;\\n  flex-direction: column;\\n  background: var(--secondary);\\n  border-left: 1px solid var(--primary-low-mid);\\n  overflow: hidden;\\n  z-index: 1001;\\n\\n  &__header {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-2);\\n    padding: var(--space-3) var(--space-4);\\n    border-bottom: 1px solid var(--primary-low-mid);\\n  }\\n\\n  &__title {\\n    flex: 1;\\n    font-size: var(--font-up-1);\\n    font-weight: 700;\\n    color: var(--primary);\\n  }\\n\\n  &__back {\\n    color: var(--primary-medium);\\n  }\\n\\n  &__close {\\n    color: var(--primary-medium);\\n  }\\n\\n  &__search {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-2);\\n    margin: var(--space-3) var(--space-4);\\n    padding: var(--space-2) var(--space-3);\\n    border: 1px solid var(--primary-low-mid);\\n    border-radius: var(--d-border-radius);\\n    background: var(--primary-very-low);\\n\\n    .d-icon {\\n      color: var(--primary-medium);\\n      flex-shrink: 0;\\n    }\\n  }\\n\\n  &__search-input {\\n    border: 0 !important;\\n    background: transparent !important;\\n    outline: none !important;\\n    box-shadow: none !important;\\n    margin: 0 !important;\\n    padding: 0 !important;\\n    width: 100%;\\n    font-size: var(--font-0);\\n    color: var(--primary);\\n\\n    &::placeholder {\\n      color: var(--primary-medium);\\n    }\\n  }\\n\\n  &__list {\\n    flex: 1;\\n    overflow-y: auto;\\n    display: flex;\\n    flex-direction: column;\\n    padding: 0 var(--space-2);\\n  }\\n\\n  &__category {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-3);\\n    width: 100%;\\n    padding: var(--space-3);\\n    border: 0;\\n    border-radius: var(--d-border-radius);\\n    background: none;\\n    cursor: pointer;\\n    text-align: left;\\n    color: var(--primary);\\n    font: inherit;\\n\\n    &:hover {\\n      background: var(--primary-very-low);\\n    }\\n  }\\n\\n  &__category-icon {\\n    flex-shrink: 0;\\n    display: flex;\\n    align-items: center;\\n\\n    .d-icon {\\n      color: var(--primary-medium);\\n    }\\n  }\\n\\n  &__category-name {\\n    flex: 1;\\n    font-weight: 700;\\n    font-size: var(--font-0);\\n  }\\n\\n  &__category-arrow {\\n    flex-shrink: 0;\\n    display: flex;\\n    align-items: center;\\n\\n    .d-icon {\\n      color: var(--primary-medium);\\n    }\\n  }\\n\\n  &__item {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-3);\\n    width: 100%;\\n    padding: var(--space-3);\\n    border: 0;\\n    border-radius: var(--d-border-radius);\\n    background: none;\\n    cursor: pointer;\\n    text-align: left;\\n    color: var(--primary);\\n    font: inherit;\\n\\n    &:hover {\\n      background: var(--primary-very-low);\\n    }\\n  }\\n\\n  &__item-icon {\\n    flex-shrink: 0;\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n\\n    .d-icon {\\n      color: var(--node-icon-color, var(--primary-medium));\\n    }\\n  }\\n\\n  &__item-content {\\n    flex: 1;\\n    min-width: 0;\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-1);\\n  }\\n\\n  &__item-name {\\n    font-weight: 700;\\n    font-size: var(--font-0);\\n    line-height: 1.2;\\n  }\\n\\n  &__item-description {\\n    font-size: var(--font-down-1);\\n    color: var(--primary-medium);\\n    line-height: 1.3;\\n  }\\n\\n  &__item-arrow {\\n    flex-shrink: 0;\\n    display: flex;\\n    align-items: center;\\n\\n    .d-icon {\\n      color: var(--primary-medium);\\n    }\\n  }\\n}\\n",".workflow-sticky-note {\\n  position: absolute;\\n  z-index: -1;\\n  border-radius: 4px;\\n  box-shadow: 0 2px 8px rgb(0 0 0 / 0.12);\\n  pointer-events: auto;\\n  cursor: grab;\\n  user-select: none;\\n  display: flex;\\n  flex-direction: column;\\n  overflow: visible;\\n  border: 1px solid var(--primary-low-mid);\\n\\n  &:active {\\n    cursor: grabbing;\\n  }\\n\\n  &:has(.workflow-sticky-note__color-picker) {\\n    z-index: calc(var(--z-canvas-chrome) + 1);\\n\\n    .workflow-canvas-toolbar {\\n      opacity: 1;\\n      pointer-events: auto;\\n    }\\n  }\\n\\n  &.is-editing {\\n    z-index: calc(var(--z-canvas-elements) + 1);\\n  }\\n\\n  &.is-selected {\\n    outline: 2px solid var(--tertiary);\\n    outline-offset: -1px;\\n  }\\n\\n  &__color-picker {\\n    position: absolute;\\n    top: -32px;\\n    left: 50%;\\n    transform: translateX(-50%);\\n    display: flex;\\n    align-items: center;\\n    gap: 4px;\\n    padding: 4px 6px;\\n    background: var(--secondary);\\n    border: 1px solid var(--primary-low-mid);\\n    border-radius: var(--d-border-radius);\\n    box-shadow: var(--shadow-dropdown);\\n    z-index: calc(var(--z-canvas-chrome) + 1);\\n  }\\n\\n  &__color-swatch {\\n    width: 18px;\\n    height: 18px;\\n    border-radius: 50%;\\n    border: 2px solid transparent;\\n    cursor: pointer;\\n    padding: 0;\\n    transition: border-color 0.15s;\\n\\n    &:hover {\\n      border-color: var(--primary-medium);\\n    }\\n\\n    &.is-active {\\n      border-color: var(--primary);\\n    }\\n  }\\n\\n  &__content {\\n    flex: 1;\\n    padding: 8px 10px;\\n    overflow: hidden;\\n    min-height: 0;\\n  }\\n\\n  &__textarea {\\n    width: 100%;\\n    height: 100%;\\n    border: none;\\n    background: transparent;\\n    resize: none;\\n    font-size: var(--font-down-3);\\n    font-family: inherit;\\n    line-height: 1.4;\\n    color: var(--primary);\\n    outline: none;\\n    padding: 0;\\n    cursor: text;\\n\\n    &:focus {\\n      border: none;\\n      outline: none;\\n    }\\n  }\\n\\n  &__text {\\n    font-size: var(--font-down-3);\\n    line-height: 1.4;\\n    color: var(--primary);\\n    word-break: break-word;\\n    overflow: hidden;\\n    height: 100%;\\n\\n    p {\\n      margin: 0 0 0.4em;\\n\\n      &:last-child {\\n        margin-bottom: 0;\\n      }\\n    }\\n\\n    a {\\n      color: var(--tertiary);\\n    }\\n\\n    code {\\n      background: var(--primary-very-low);\\n      padding: 1px 4px;\\n      border-radius: 3px;\\n      font-size: var(--font-down-2);\\n    }\\n  }\\n\\n  &__placeholder {\\n    color: var(--primary-medium);\\n    font-style: italic;\\n  }\\n\\n  &__edges {\\n    position: absolute;\\n    inset: 0;\\n    pointer-events: none;\\n  }\\n\\n  &__edge {\\n    position: absolute;\\n    pointer-events: auto;\\n\\n    &.--n,\\n    &.--s {\\n      left: 6px;\\n      right: 6px;\\n      height: 6px;\\n      cursor: ns-resize;\\n    }\\n\\n    &.--n {\\n      top: -3px;\\n    }\\n\\n    &.--s {\\n      bottom: -3px;\\n    }\\n\\n    &.--w,\\n    &.--e {\\n      top: 6px;\\n      bottom: 6px;\\n      width: 6px;\\n      cursor: ew-resize;\\n    }\\n\\n    &.--w {\\n      left: -3px;\\n    }\\n\\n    &.--e {\\n      right: -3px;\\n    }\\n\\n    &.--nw,\\n    &.--ne,\\n    &.--sw,\\n    &.--se {\\n      width: 10px;\\n      height: 10px;\\n    }\\n\\n    &.--nw {\\n      top: -3px;\\n      left: -3px;\\n      cursor: nwse-resize;\\n    }\\n\\n    &.--ne {\\n      top: -3px;\\n      right: -3px;\\n      cursor: nesw-resize;\\n    }\\n\\n    &.--sw {\\n      bottom: -3px;\\n      left: -3px;\\n      cursor: nesw-resize;\\n    }\\n\\n    &.--se {\\n      bottom: -3px;\\n      right: -3px;\\n      cursor: nwse-resize;\\n    }\\n  }\\n}\\n",".form-kit__object:has(.workflows-property-engine__collection-row) {\\n  --form-kit-gutter-y: var(--space-6);\\n}\\n\\n.workflows-configurator {\\n  &__tabs {\\n    display: flex;\\n    border-bottom: 2px solid var(--primary-low);\\n    margin-bottom: var(--space-4);\\n  }\\n\\n  &__tab {\\n    padding: var(--space-2) var(--space-4);\\n    border: 0;\\n    background: transparent;\\n    cursor: pointer;\\n    font-size: var(--font-0);\\n    color: var(--primary-medium);\\n    border-bottom: 2px solid transparent;\\n    margin-bottom: -2px;\\n\\n    &:hover {\\n      color: var(--primary);\\n    }\\n\\n    &.is-active {\\n      color: var(--tertiary);\\n      border-bottom-color: var(--tertiary);\\n    }\\n  }\\n\\n  &__field-with-picker {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-1);\\n\\n    input {\\n      flex: 1;\\n    }\\n  }\\n\\n  &__description {\\n    width: 100%;\\n    min-height: 3em;\\n    resize: vertical;\\n  }\\n\\n  &__hint {\\n    font-size: var(--font-down-1);\\n    color: var(--primary-medium);\\n    margin: 0 0 var(--space-2);\\n  }\\n\\n  &__key-value-row {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-2);\\n    margin-bottom: var(--space-2);\\n\\n    > .form-kit__field {\\n      flex: 1;\\n      min-width: 0;\\n    }\\n  }\\n}\\n\\n[data-identifier=\\"filter-navigation-menu-list\\"] {\\n  z-index: 1400;\\n}\\n\\n.workflows-configurator-form {\\n  align-items: stretch;\\n\\n  &.is-hidden {\\n    display: none;\\n  }\\n\\n  .topic-query-filter__icon,\\n  .topic-query-filter__clear-btn {\\n    display: none;\\n  }\\n\\n  .form-kit__section > .btn-default {\\n    width: 100%;\\n    justify-content: center;\\n  }\\n\\n  &__setting-toggle {\\n    display: grid;\\n    grid-template-columns: minmax(0, 1fr) auto;\\n    column-gap: var(--space-4);\\n    align-items: center;\\n\\n    .form-kit__container-title,\\n    .form-kit__container-description {\\n      grid-column: 1;\\n      width: auto;\\n      min-width: 0;\\n    }\\n\\n    .form-kit__container-content {\\n      grid-column: 2;\\n      grid-row: 1 / span 2;\\n      width: auto;\\n      min-width: 0;\\n    }\\n  }\\n}\\n\\n.workflows-property-engine {\\n  &__control-wrapper {\\n    position: relative;\\n    width: 100%;\\n\\n    > .d-toggle-switch {\\n      justify-content: flex-end;\\n    }\\n\\n    > .combo-box,\\n    > .d-native-select,\\n    > .icon-picker,\\n    > .select-kit.combo-box.category-chooser,\\n    > .user-chooser,\\n    > .mini-tag-chooser,\\n    > .select-kit.category-selector {\\n      width: 100%;\\n      min-width: 0;\\n    }\\n  }\\n\\n  &__mode-control {\\n    position: absolute;\\n    inset-block-start: calc(-1 * var(--space-1));\\n    transform: translateY(-100%);\\n    inset-inline-end: 0;\\n\\n    .form-kit__field-toggle & {\\n      inset-block-start: 50%;\\n      transform: translateY(-50%);\\n      inset-inline-end: 50px;\\n    }\\n  }\\n\\n  &__dynamic-hint {\\n    margin: var(--space-1) 0 0;\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1);\\n    line-height: var(--line-height-small);\\n  }\\n\\n  &__control-wrapper[data-supports-expression] {\\n    border-radius: var(--d-border-radius);\\n\\n    html[data-dragging-variable] & {\\n      outline: 2px dashed var(--tertiary);\\n      outline-offset: 2px;\\n    }\\n\\n    &.is-drag-over input,\\n    &.is-drag-over textarea {\\n      border-color: var(--tertiary) !important;\\n      background: var(--tertiary-50);\\n    }\\n\\n    // The toggle class lands on the hidden checkbox, so target its visible sibling.\\n    &.is-drag-over\\n      .form-kit__control-toggle\\n      + .d-toggle-switch__checkbox-slider {\\n      outline: 2px solid var(--tertiary);\\n      outline-offset: 2px;\\n    }\\n  }\\n\\n  &__collection-row {\\n    position: relative;\\n    border: 1px dashed var(--primary-low);\\n    padding: var(--space-5) var(--space-2) var(--space-4);\\n    border-radius: var(--d-border-radius-large);\\n    background: var(--primary-very-low);\\n  }\\n\\n  &__collection-delete {\\n    position: absolute;\\n    inset-block-start: 0;\\n    inset-inline-end: 0;\\n    transform: translate(25%, -50%);\\n    padding: var(--space-half);\\n    border-radius: 6px;\\n    font-size: var(--font-down-1-rem);\\n    background: var(--secondary);\\n    border: 1px solid var(--primary-low-mid);\\n\\n    &:hover {\\n      .discourse-no-touch & {\\n        background: var(--secondary);\\n        border: 1px solid var(--primary-low-mid);\\n\\n        .d-icon {\\n          color: var(--danger);\\n        }\\n      }\\n    }\\n  }\\n\\n  &__collection-order-controls {\\n    position: absolute;\\n    inset-block-start: 0;\\n    inset-inline-start: var(--space-2);\\n    transform: translateY(-50%);\\n    display: flex;\\n    gap: var(--space-half);\\n  }\\n\\n  &__collection-move {\\n    padding: var(--space-half);\\n    border-radius: 6px;\\n    font-size: var(--font-down-1-rem);\\n    background: var(--secondary);\\n    border: 1px solid var(--primary-low-mid);\\n  }\\n\\n  &__collection-fields {\\n    flex: 1;\\n    min-width: 0;\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-2);\\n  }\\n\\n  &__collection-flat {\\n    flex: 1;\\n    min-width: 0;\\n  }\\n\\n  &__block-field-label {\\n    font-size: var(--font-down-1);\\n    font-weight: 700;\\n    color: var(--primary-high);\\n  }\\n\\n  &__block-actions {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-2);\\n  }\\n\\n  &__nested-collection {\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-2);\\n  }\\n\\n  &__nested-collection-item {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-2);\\n    padding-bottom: var(--space-2);\\n    border-bottom: 1px dashed var(--primary-low);\\n\\n    .form-kit__container {\\n      flex: 1;\\n      min-width: 0;\\n      margin: 0;\\n    }\\n\\n    .form-kit__control-custom,\\n    .workflows-property-engine__control-wrapper {\\n      width: 100%;\\n      min-width: 0;\\n      box-sizing: border-box;\\n    }\\n\\n    textarea {\\n      min-height: 80px;\\n      min-width: 0;\\n      resize: vertical;\\n    }\\n\\n    > .btn {\\n      flex-shrink: 0;\\n    }\\n  }\\n\\n  &__add-attrs-btn {\\n    flex: 1;\\n    justify-content: center;\\n    gap: var(--space-2);\\n  }\\n}\\n\\n.workflows-data-table-column-select {\\n  width: 100%;\\n}\\n\\n.workflows-code-control {\\n  width: 100%;\\n}\\n\\n.workflows-actor-control {\\n  display: flex;\\n  flex-direction: column;\\n  gap: var(--space-1);\\n  width: 100%;\\n\\n  .combo-box,\\n  .user-chooser {\\n    width: 100%;\\n    min-width: 0;\\n  }\\n}\\n\\n.workflows-user-seen-duration {\\n  margin-inline-start: calc(var(--space-4) + var(--space-2));\\n\\n  > .form-kit__container-content {\\n    display: grid;\\n    grid-template-columns: minmax(4.5rem, 5.5rem) minmax(7rem, 8.5rem);\\n    align-items: center;\\n    gap: var(--space-2);\\n    width: fit-content;\\n  }\\n\\n  &__amount,\\n  &__unit {\\n    margin: 0;\\n    min-width: 0;\\n\\n    > .form-kit__container-content {\\n      width: 100%;\\n      min-width: 0;\\n    }\\n  }\\n}\\n\\n.workflows-field-path {\\n  width: 100%;\\n}\\n\\n// Each aggregation is its own short stack of lines, so the generic repeatable-row\\n// card is stripped back and a rule is used to tell one aggregation from the next.\\n.workflows-property-engine__collection-row:has(.workflows-summarize-row) {\\n  display: flex;\\n  align-items: flex-start;\\n  gap: var(--space-1);\\n  border: 0;\\n  background: transparent;\\n  padding-block: var(--space-2);\\n  padding-inline: 0;\\n\\n  + .workflows-property-engine__collection-row:has(.workflows-summarize-row) {\\n    border-block-start: 1px solid var(--primary-low);\\n  }\\n\\n  .workflows-property-engine__collection-delete {\\n    position: static;\\n    transform: none;\\n    order: 2;\\n    border: 0;\\n    background: transparent;\\n\\n    // Match the control height so the delete sits on the first line's centre.\\n    height: var(--space-9);\\n    display: flex;\\n    align-items: center;\\n  }\\n\\n  .workflows-property-engine__collection-fields {\\n    order: 1;\\n    min-width: 0;\\n  }\\n}\\n\\n.workflows-summarize-row {\\n  // Shared by every lead, which is what keeps the controls of one row - and of all\\n  // the rows below it - on a single vertical rule. Wide enough for the longest\\n  // aggregation name, since a truncated one reads as a different calculation.\\n  --summarize-lead-width: 11.5rem;\\n  display: flex;\\n  flex-direction: column;\\n  row-gap: var(--space-1);\\n  width: 100%;\\n\\n  &__line {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-1);\\n    min-width: 0;\\n  }\\n\\n  &__lead {\\n    flex: 0 0 var(--summarize-lead-width);\\n    min-width: 0;\\n\\n    &--label {\\n      text-align: end;\\n      color: var(--primary-medium);\\n    }\\n  }\\n\\n  &__control {\\n    flex: 1 1 auto;\\n    min-width: 0;\\n\\n    &--derived input::placeholder {\\n      font-style: italic;\\n    }\\n  }\\n\\n  // A line is a lead and its control, so the form fields inside must not reserve\\n  // vertical space for labels or impose a width of their own.\\n  .form-kit__field {\\n    margin: 0;\\n    min-width: 0;\\n  }\\n\\n  .form-kit__container-content {\\n    width: 100%;\\n    min-width: 0;\\n  }\\n\\n  // Every control shares the height form-kit gives its inputs, otherwise the selects,\\n  // the text inputs and the combo boxes each sit on a different baseline.\\n  .form-kit__control-select,\\n  .form-kit__control-input,\\n  .select-kit-header {\\n    height: var(--space-9);\\n    margin: 0;\\n  }\\n\\n  .form-kit__control-select,\\n  .form-kit__control-input {\\n    width: 100%;\\n  }\\n}\\n\\n.workflows-node-preview {\\n  margin-block-end: var(--space-3);\\n\\n  &__truncated {\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1);\\n  }\\n\\n  &__table-wrapper {\\n    overflow-x: auto;\\n    border: 1px solid var(--primary-low);\\n    border-radius: var(--d-border-radius);\\n  }\\n\\n  &__table {\\n    width: 100%;\\n    margin: 0;\\n    font-size: var(--font-down-1);\\n\\n    th,\\n    td {\\n      padding: var(--space-1) var(--space-2);\\n      text-align: start;\\n      white-space: nowrap;\\n    }\\n\\n    th {\\n      font-family: var(--d-font-family--monospace);\\n      font-weight: 500;\\n    }\\n  }\\n}\\n\\n.workflows-access-control {\\n  &__input-row {\\n    align-items: flex-start;\\n    gap: var(--space-12);\\n    padding-block: var(--space-3);\\n  }\\n\\n  &__groups {\\n    flex: 1 1 0;\\n    min-width: 0;\\n\\n    input {\\n      width: 100%;\\n      margin: 0;\\n    }\\n  }\\n\\n  &__permission {\\n    flex: 0 0 auto;\\n    text-align: end;\\n  }\\n}\\n",".workflows-page {\\n  scrollbar-gutter: stable;\\n}\\n\\n.workflows-configurator-modal {\\n  --input-border-color: var(--primary-low-mid);\\n\\n  .d-modal__container {\\n    max-width: 100%;\\n    width: 95vw;\\n    max-height: 95vh;\\n    height: 95vh;\\n  }\\n\\n  .d-modal__body {\\n    display: flex;\\n    flex-direction: column;\\n    overflow: hidden;\\n    padding: 0;\\n    flex: 1;\\n    min-height: 0;\\n    border-radius: var(--d-border-radius);\\n  }\\n\\n  &__header {\\n    display: flex;\\n    align-items: center;\\n    padding: var(--space-2) var(--space-3);\\n    border-bottom: 1px solid var(--primary-low);\\n    gap: var(--space-1);\\n  }\\n\\n  &__name,\\n  &__name-input {\\n    font-size: var(--font-up-1);\\n    font-weight: 700;\\n    font-family: inherit;\\n    padding: var(--space-1) var(--space-2);\\n    border: 1px solid transparent;\\n    border-radius: var(--d-border-radius);\\n    line-height: 1.5;\\n    height: 36px;\\n    box-sizing: border-box;\\n    margin: 0 !important;\\n  }\\n\\n  &__name {\\n    flex: 0 1 auto;\\n    cursor: pointer;\\n\\n    &:hover {\\n      background: var(--primary-very-low);\\n    }\\n  }\\n\\n  &__name-actions {\\n    display: inline-flex;\\n    align-items: center;\\n    gap: var(--space-1);\\n  }\\n\\n  &__name-error {\\n    color: var(--danger);\\n    font-size: var(--font-down-1);\\n  }\\n\\n  &__edit-name,\\n  &__save-name,\\n  &__cancel-name {\\n    flex-shrink: 0;\\n  }\\n\\n  &__node-icon {\\n    color: var(--node-icon-color, var(--primary-medium));\\n  }\\n\\n  &__name-input {\\n    flex: 0 1 auto;\\n    width: calc(var(--node-name-length) * 1ch) !important;\\n    min-width: 8ch;\\n    max-width: 100%;\\n    outline: none !important;\\n    box-shadow: none !important;\\n    border-color: var(--tertiary) !important;\\n    background: var(--primary-very-low);\\n  }\\n\\n  &__close {\\n    margin-left: auto;\\n    flex-shrink: 0;\\n  }\\n\\n  &__save-status {\\n    display: inline-flex;\\n    align-items: center;\\n    gap: var(--space-1);\\n    margin-left: auto;\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1);\\n    font-weight: 600;\\n    height: 36px;\\n    line-height: 1;\\n    opacity: 1;\\n    transition: opacity 0.5s ease-in-out;\\n    white-space: nowrap;\\n  }\\n\\n  &__save-status + &__close {\\n    margin-left: 0;\\n  }\\n\\n  &__save-status--saved {\\n    color: var(--workflow-status-success);\\n  }\\n\\n  &__save-status--fading {\\n    opacity: 0;\\n  }\\n\\n  &__save-spinner {\\n    display: inline-block;\\n    width: 0.85em;\\n    height: 0.85em;\\n    margin: 0;\\n    border-width: 2px;\\n  }\\n\\n  .loading-container {\\n    flex: 1;\\n    min-height: 0;\\n    display: flex;\\n    flex-direction: column;\\n  }\\n\\n  &__columns {\\n    display: grid;\\n    grid-template-columns: 1fr 1.5fr 1fr;\\n    grid-template-rows: 1fr;\\n    flex: 1;\\n    min-height: 0;\\n\\n    &:not(:has(> .--right)) {\\n      grid-template-columns: 1fr 1.5fr;\\n    }\\n  }\\n\\n  &__column {\\n    min-height: 0;\\n    padding: var(--space-3);\\n    overflow-y: auto;\\n\\n    // custom scrollbar styling\\n    --scrollbarBg: transparent;\\n    --scrollbarThumbBg: var(--primary-low);\\n    --scrollbarWidth: var(--space-2);\\n    scrollbar-color: transparent var(--scrollbarBg);\\n    transition: scrollbar-color 0.25s ease-in-out;\\n    transition-delay: 0.5s;\\n\\n    &::-webkit-scrollbar {\\n      width: var(--scrollbarWidth);\\n    }\\n\\n    &::-webkit-scrollbar-thumb {\\n      background-color: transparent;\\n      border-radius: calc(var(--scrollbarWidth) / 2);\\n    }\\n\\n    &::-webkit-scrollbar-track {\\n      background-color: transparent;\\n    }\\n\\n    &:hover {\\n      scrollbar-color: var(--scrollbarThumbBg) var(--scrollbarBg);\\n      transition-delay: 0s;\\n\\n      &::-webkit-scrollbar-thumb {\\n        background-color: var(--scrollbarThumbBg);\\n      }\\n    }\\n\\n    &.--left,\\n    &.--right {\\n      background-color: light-dark(var(--primary-very-low), var(--secondary));\\n      border-color: var(--primary-low);\\n    }\\n\\n    &.--left {\\n      border-right: 1px solid var(--primary-low);\\n      padding: var(--space-2);\\n    }\\n\\n    &.--right {\\n      border-left: 1px solid var(--primary-low);\\n      padding: var(--space-2);\\n    }\\n  }\\n\\n  &__run-scope {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-1);\\n    margin-bottom: var(--space-3);\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1);\\n\\n    .d-icon {\\n      color: var(--primary-medium);\\n    }\\n  }\\n\\n  &__node {\\n    border: 1px solid var(--content-border-color);\\n    padding: var(--space-2);\\n    margin-top: var(--space-4);\\n    border-radius: 4px;\\n  }\\n\\n  &__node-title {\\n    font-weight: bold;\\n    font-size: var(--font-down-1);\\n  }\\n\\n  &__node-description {\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1);\\n    margin: 0;\\n  }\\n\\n  &__node-version {\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-2);\\n  }\\n\\n  &__unavailable-banner {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-2);\\n    padding: var(--space-2) var(--space-3);\\n    background: var(--workflow-status-running-low);\\n    border-bottom: 1px solid var(--workflow-status-running);\\n    color: var(--primary-high);\\n    font-size: var(--font-down-1);\\n\\n    .d-icon {\\n      color: var(--workflow-status-running);\\n    }\\n  }\\n\\n  &__columns.is-unavailable {\\n    pointer-events: none;\\n    opacity: 0.5;\\n  }\\n\\n  .form-kit__field-code .form-kit__container-content {\\n    width: 100% !important;\\n  }\\n}\\n",".workflows-property-engine__select-with-action {\\n  display: flex;\\n  align-items: center;\\n  gap: var(--space-2);\\n\\n  .combo-box {\\n    flex: 1;\\n  }\\n}\\n",".workflows-url-preview {\\n  display: flex;\\n  align-items: center;\\n  gap: var(--space-2);\\n  padding: var(--space-2) var(--space-3);\\n  box-sizing: border-box;\\n  background: var(--primary-very-low);\\n  border: 1px solid var(--primary-low);\\n  border-radius: var(--d-border-radius);\\n  cursor: pointer;\\n  transition: border-color 0.15s;\\n\\n  &:hover {\\n    border-color: var(--primary-low-mid);\\n  }\\n\\n  &.is-loading,\\n  &.is-disabled {\\n    cursor: default;\\n  }\\n\\n  &.is-disabled {\\n    opacity: 0.65;\\n  }\\n\\n  code {\\n    flex: 1;\\n    min-width: 0;\\n    overflow: hidden;\\n    text-overflow: ellipsis;\\n    font-size: var(--font-down-1);\\n    color: var(--primary-high);\\n    background: none;\\n    padding: 0;\\n  }\\n\\n  .d-icon {\\n    flex-shrink: 0;\\n    color: var(--primary-medium);\\n  }\\n\\n  &.is-copied {\\n    border-color: var(--workflow-status-success);\\n\\n    .d-icon {\\n      color: var(--workflow-status-success);\\n    }\\n  }\\n\\n  &__status {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-2);\\n    margin-top: var(--space-1);\\n    font-size: var(--font-down-1);\\n    color: var(--primary-medium);\\n  }\\n}\\n\\n.workflows-url-preview-mode {\\n  display: inline-flex;\\n  align-items: center;\\n  gap: 0;\\n  width: max-content;\\n  margin-bottom: var(--space-2);\\n  border: 1px solid var(--primary-low);\\n  border-radius: var(--d-border-radius);\\n  overflow: hidden;\\n\\n  &__button {\\n    padding: var(--space-1) var(--space-2);\\n    border: 0;\\n    border-right: 1px solid var(--primary-low);\\n    background: var(--secondary);\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1);\\n    cursor: pointer;\\n\\n    &:last-child {\\n      border-right: 0;\\n    }\\n\\n    &.is-active {\\n      background: var(--tertiary);\\n      color: var(--secondary);\\n    }\\n  }\\n}\\n",".workflows-context-panel {\\n  display: flex;\\n  flex-direction: column;\\n  gap: var(--space-2);\\n  flex: 1;\\n  min-height: 0;\\n\\n  &__hint {\\n    border: 1px solid;\\n    border-color: var(--tertiary);\\n    border-radius: var(--d-border-radius);\\n    padding: var(--space-2);\\n    background-color: light-dark(var(--tertiary-100), var(--tertiary-500));\\n  }\\n\\n  &__hint-title {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-2);\\n    font-size: var(--font-down-1);\\n    font-weight: 700;\\n    margin: 0 0 var(--space-1);\\n    text-transform: uppercase;\\n    letter-spacing: 0.05em;\\n    font-family: monospace;\\n    color: var(--primary-900);\\n  }\\n\\n  &__hint-text {\\n    margin: 0;\\n    font-size: var(--font-down-2);\\n    color: var(--primary-900);\\n  }\\n\\n  &__hint-close {\\n    margin-left: auto;\\n    flex-shrink: 0;\\n    padding: 0;\\n  }\\n\\n  &__hint-close .d-icon {\\n    margin: 0;\\n  }\\n\\n  &__section {\\n    border: 1px solid;\\n    border-color: light-dark(var(--primary-100), var(--primary-200));\\n    border-radius: var(--d-border-radius);\\n    padding: var(--space-2);\\n    background-color: light-dark(var(--secondary), var(--primary-50));\\n    flex: 1;\\n    display: flex;\\n    flex-direction: column;\\n    min-height: 0;\\n  }\\n\\n  &__header {\\n    display: flex;\\n    align-items: center;\\n    justify-content: space-between;\\n    gap: var(--space-2);\\n    margin-bottom: var(--space-2);\\n    border-bottom: 2px solid var(--primary-low);\\n  }\\n\\n  &__header-actions {\\n    display: flex;\\n    align-items: stretch;\\n    gap: var(--space-1);\\n  }\\n\\n  &__title {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-2);\\n    font-size: var(--font-down-1);\\n    font-weight: 700;\\n    margin: 0;\\n    text-transform: uppercase;\\n    letter-spacing: 0.05em;\\n    font-family: monospace;\\n    color: var(--primary-800);\\n  }\\n\\n  &__title-meta {\\n    margin-left: auto;\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-2);\\n    font-weight: 400;\\n    text-transform: none;\\n  }\\n\\n  &__title-info {\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-2);\\n    font-weight: 400;\\n    text-transform: none;\\n  }\\n\\n  &__subsection + &__subsection {\\n    margin-top: var(--space-2);\\n  }\\n\\n  &__subtitle {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-2);\\n    color: var(--primary-medium);\\n    font-family: monospace;\\n    font-size: var(--font-down-2);\\n    font-weight: 700;\\n    letter-spacing: 0.05em;\\n    margin: 0 0 var(--space-1);\\n    text-transform: uppercase;\\n  }\\n\\n  &__empty {\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1);\\n    font-style: italic;\\n  }\\n\\n  &__tabs {\\n    display: flex;\\n    align-items: stretch;\\n  }\\n\\n  &__tab {\\n    padding: var(--space-1) var(--space-3);\\n    border: 0;\\n    background: transparent;\\n    cursor: pointer;\\n    font-size: var(--font-down-1);\\n    color: var(--primary-medium);\\n    border-bottom: 2px solid transparent;\\n    margin-bottom: -2px;\\n\\n    &:hover {\\n      color: var(--primary);\\n    }\\n\\n    &.is-active {\\n      color: var(--tertiary);\\n      border-bottom-color: var(--tertiary);\\n    }\\n  }\\n\\n  &__icon-btn {\\n    display: inline-flex;\\n    align-items: center;\\n    justify-content: center;\\n    background: transparent;\\n    border: 0;\\n    padding: var(--space-1);\\n    color: var(--primary-medium);\\n    cursor: pointer;\\n    border-radius: var(--d-border-radius);\\n\\n    &:hover:not([disabled]) {\\n      color: var(--primary);\\n      background: var(--primary-very-low);\\n    }\\n\\n    &[disabled] {\\n      opacity: 0.4;\\n      cursor: not-allowed;\\n    }\\n\\n    .d-icon {\\n      margin: 0;\\n    }\\n  }\\n\\n  &__pin-btn.is-pinned {\\n    color: var(--tertiary);\\n  }\\n\\n  &__pin-banner {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-2);\\n    padding: var(--space-1) var(--space-2);\\n    margin: 0;\\n    background: transparent;\\n    border-left: 2px solid var(--tertiary);\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-1);\\n\\n    .d-icon {\\n      color: var(--tertiary);\\n      flex-shrink: 0;\\n    }\\n  }\\n\\n  &__pin-banner-text {\\n    flex: 1;\\n  }\\n\\n  &__unpin-btn {\\n    padding: 0;\\n    color: var(--tertiary);\\n    font-size: var(--font-down-1);\\n\\n    &:hover {\\n      text-decoration: underline;\\n    }\\n  }\\n\\n  &__editor {\\n    display: flex;\\n    flex-direction: column;\\n    gap: var(--space-1);\\n    margin-top: var(--space-1);\\n  }\\n\\n  &__editor-toolbar {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-1);\\n    flex-wrap: wrap;\\n  }\\n\\n  &__editor-size {\\n    margin-left: auto;\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-2);\\n    font-family: monospace;\\n\\n    &--near {\\n      color: var(--love);\\n    }\\n\\n    &--exceeded {\\n      color: var(--workflow-status-error);\\n      font-weight: 700;\\n    }\\n  }\\n\\n  &__editor-codemirror {\\n    border: 1px solid;\\n    border-color: light-dark(var(--primary-100), var(--primary-200));\\n    border-radius: var(--d-border-radius);\\n    overflow: hidden;\\n    font-size: var(--font-down-1);\\n\\n    .cm-editor {\\n      max-height: 50vh;\\n    }\\n\\n    &--read-only .cm-editor {\\n      background-color: light-dark(var(--primary-very-low), var(--primary-100));\\n    }\\n  }\\n\\n  &__editor-read {\\n    margin: 0;\\n    padding: var(--space-2);\\n    background-color: light-dark(var(--primary-very-low), var(--primary-100));\\n    border: 1px solid;\\n    border-color: light-dark(var(--primary-100), var(--primary-200));\\n    border-radius: var(--d-border-radius);\\n    font-size: var(--font-down-1);\\n    font-family: monospace;\\n    white-space: pre-wrap;\\n    word-break: break-word;\\n    max-height: 50vh;\\n    overflow: auto;\\n  }\\n\\n  &__editor-loading {\\n    padding: var(--space-2);\\n    color: var(--primary-medium);\\n    font-style: italic;\\n    font-size: var(--font-down-1);\\n  }\\n\\n  &__editor-error,\\n  &__editor-notice {\\n    display: flex;\\n    align-items: flex-start;\\n    gap: var(--space-1);\\n    margin: 0;\\n    padding: var(--space-1) var(--space-2);\\n    font-size: var(--font-down-1);\\n  }\\n\\n  &__empty-state {\\n    flex: 1;\\n    display: flex;\\n    flex-direction: column;\\n    align-items: center;\\n    justify-content: center;\\n    gap: var(--space-3);\\n    padding: var(--space-4);\\n    text-align: center;\\n  }\\n\\n  &__empty-state-title {\\n    margin: 0;\\n    color: var(--primary);\\n    font-size: var(--font-up-2);\\n    font-weight: 600;\\n  }\\n\\n  &__empty-state-btn {\\n    padding: var(--space-2) var(--space-4);\\n    font-size: var(--font-0);\\n  }\\n}\\n",".workflows-schema-field-list {\\n  @include unstyled-list;\\n\\n  &.is-nested {\\n    padding-left: var(--space-9);\\n  }\\n}\\n\\n.workflows-schema-field {\\n  font-family: monospace;\\n\\n  &__row {\\n    display: flex;\\n    align-items: center;\\n    padding: 0.35em 0;\\n  }\\n\\n  &.has-children > &__row {\\n    &:hover .workflows-schema-field__key {\\n      color: var(--primary);\\n    }\\n  }\\n\\n  &__toggle {\\n    color: var(--primary-medium);\\n    margin-right: 0.25em;\\n  }\\n\\n  &__key {\\n    border: 1px solid var(--primary-200);\\n    padding: var(--space-half) var(--space-1);\\n    color: var(--primary-800);\\n    border-radius: 2px;\\n    gap: var(--space-1);\\n    display: flex;\\n    align-items: center;\\n    cursor: grab;\\n\\n    &:hover {\\n      background-color: var(--primary-100);\\n      border-color: var(--primary-300);\\n      color: var(--primary);\\n\\n      .workflows-schema-field__key-icon {\\n        border-color: var(--primary-300);\\n      }\\n    }\\n  }\\n\\n  &__key-icon {\\n    border-right: 1px solid var(--primary-200);\\n    padding-right: var(--space-1);\\n    font-size: var(--font-down-1);\\n  }\\n\\n  &__type {\\n    font-size: var(--font-down-2);\\n    padding: 0.1em 0.5em;\\n    border-radius: 0.75em;\\n    font-weight: 700;\\n    border: 1px solid;\\n  }\\n}\\n","// --------------------------------------------------\\n// Mixins used throughout the theme\\n// --------------------------------------------------\\n\\n// Media queries\\n// --------------------------------------------------\\n\\n@use \\"sass:color\\";\\n@use \\"sass:math\\";\\n@use \\"sass:string\\";\\n@use \\"sass:map\\";\\n@use \\"lib/viewport\\";\\n\\n$breakpoints: (\\n  mobile-small: map.get(viewport.$breakpoints, sm),\\n  mobile-medium: map.get(viewport.$breakpoints, sm),\\n  mobile-large: map.get(viewport.$breakpoints, sm),\\n  mobile-extra-large: map.get(viewport.$breakpoints, sm),\\n  tablet: map.get(viewport.$breakpoints, md),\\n  medium: map.get(viewport.$breakpoints, lg),\\n  large: map.get(viewport.$breakpoints, lg),\\n  extra-large: map.get(viewport.$breakpoints, xl),\\n);\\n\\n/* breakpoint is a legacy mixin. Use `@use \\"lib/viewport\\"` instead. */\\n@mixin breakpoint($bp, $rule: max-width, $type: screen, $sidebar: false) {\\n  /* stylelint-disable-next-line scss/no-global-function-names */\\n  $bp-value: map-get($breakpoints, $bp);\\n\\n  @if $rule == min-width {\\n    $bp-value: calc(#{$bp-value} + 1px);\\n  }\\n\\n  @media #{$type} and (#{$rule}: #{$bp-value}) {\\n    @content;\\n  }\\n\\n  // if you want to consider the sidebar in your breakpoint\\n  // you can pass in $sidebar: true\\n  // note that your breakpoint will need to be at the root level\\n  @if $sidebar {\\n    // when the sidebar is shown, we want to increase the breakpoints by the width of the sidebar\\n    /* stylelint-disable-next-line scss/no-global-function-names */\\n    @media #{$type} and (#{$rule}: calc(#{map-get($breakpoints, $bp)} + #{$d-sidebar-width})) {\\n      .has-sidebar-page {\\n        @content;\\n      }\\n    }\\n  }\\n}\\n\\n// CSS3 properties\\n// --------------------------------------------------\\n\\n// Clearfix\\n\\n@mixin clearfix() {\\n  &::before,\\n  &::after {\\n    content: \\"\\";\\n    display: table;\\n  }\\n\\n  &::after {\\n    clear: both;\\n  }\\n}\\n\\n@mixin linear-gradient($start-color, $end-color) {\\n  background-color: $start-color;\\n  background-image: linear-gradient(to bottom, $start-color, $end-color);\\n}\\n\\n@mixin darken-background($background-color, $amt) {\\n  $overlay: dark-light-choose(\\n    rgb(var(--primary-rgb), $amt),\\n    rgb(var(--secondary-rgb), $amt)\\n  );\\n  background-image: linear-gradient(to bottom, $overlay 100%, $overlay 100%);\\n}\\n\\n// Visibility\\n// --------------------------------------------------\\n\\n// Only shows hover on non-touch devices\\n@mixin hover {\\n  .discourse-no-touch &,\\n  .no-ember & {\\n    &:hover,\\n    &.btn-hover {\\n      @content;\\n    }\\n  }\\n}\\n\\n@mixin ellipsis {\\n  overflow: hidden;\\n  white-space: nowrap;\\n  text-overflow: ellipsis;\\n}\\n\\n@mixin line-clamp($lines) {\\n  display: -webkit-box;\\n  overflow: hidden;\\n  text-overflow: ellipsis;\\n  overflow-wrap: break-word;\\n  -webkit-line-clamp: $lines;\\n  -webkit-box-orient: vertical;\\n}\\n\\n//\\n// --------------------------------------------------\\n\\n$vpad: 0.5em;\\n$hpad: 0.65em;\\n\\n// for consistent sizing across inputs, buttons and dropdowns\\n@mixin form-item-sizing {\\n  border: 1px solid transparent;\\n  font-size: var(--font-0);\\n  line-height: normal;\\n  box-sizing: border-box;\\n  padding: $vpad $hpad;\\n}\\n\\n// Used to handle -webkit prefix, but now we have autoprefixer\\n// Keeping for backward-compat with plugins/themes only\\n@mixin user-select($mode) {\\n  user-select: $mode;\\n}\\n\\n// Unselectable (avoids unwanted selections with iPad, touch laptops, etc)\\n@mixin unselectable {\\n  cursor: default;\\n\\n  @include user-select(none);\\n}\\n\\n// Stuff we repeat\\n@mixin d-animation($name, $duration, $easing: ease) {\\n  animation: $name $duration $easing forwards;\\n\\n  @media (prefers-reduced-motion) {\\n    /* stylelint-disable-next-line no-invalid-position-declaration */\\n    animation-duration: 0s;\\n  }\\n}\\n\\n@mixin default-focus() {\\n  border-color: var(--d-input-focused-color);\\n  outline: 2px solid var(--d-input-focused-color);\\n  outline-offset: -2px;\\n}\\n\\n/// Helper function to easily use an SVG inline in CSS\\n/// without encoding it to base64, saving bytes.\\n/// It also helps with browser support, especially for IE11.\\n///\\n/// @author Jakob Eriksen\\n/// @link http://codepen.io/jakob-e/pen/doMoML\\n/// @param {String} $svg - SVG image to encode\\n/// @return {String} - Encoded SVG data uri\\n@function svg-uri($svg) {\\n  $encoded: \\"\\";\\n  $slice: 2000;\\n  $index: 0;\\n  $loops: math.ceil(math.div(string.length($svg), $slice));\\n\\n  @for $i from 1 through $loops {\\n    $chunk: string.slice($svg, $index, $index + $slice - 1);\\n    $chunk: str-replace($chunk, '\\"', \\"'\\");\\n    $chunk: str-replace($chunk, \\"<\\", \\"%3C\\");\\n    $chunk: str-replace($chunk, \\">\\", \\"%3E\\");\\n    $chunk: str-replace($chunk, \\"&\\", \\"%26\\");\\n    $chunk: str-replace($chunk, \\"#\\", \\"%23\\");\\n    $encoded: #{$encoded}#{$chunk};\\n    $index: $index + $slice;\\n  }\\n\\n  @return url(\\"data:image/svg+xml;charset=utf8,#{$encoded}\\");\\n}\\n\\n/// Replace `$search` with `$replace` in `$string`\\n/// @author Hugo Giraudel\\n/// @link http://sassmeister.com/gist/1b4f2da5527830088e4d\\n/// @param {String} $string - Initial string\\n/// @param {String} $search - Substring to replace\\n/// @param {String} $replace ('') - New value\\n/// @return {String} - Updated string\\n@function str-replace($string, $search, $replace: \\"\\") {\\n  $index: string.index($string, $search);\\n\\n  @if $index {\\n    @return string.slice($string, 1, $index - 1) + $replace +\\n      str-replace(\\n        string.slice($string, $index + string.length($search)),\\n        $search,\\n        $replace\\n      );\\n  }\\n\\n  @return $string;\\n}\\n\\n// SCSS accepts HEX or RGB colors for rgba($color, 0.5)\\n// CSS custom properties only accept RGB\\n// Example usage:\\n\\n// --primary-rgb: #{hexToRGB($primary)};\\n// ...\\n// rgba(var(--primary-low-rgb), 0.5)\\n\\n@function hexToRGB($hex) {\\n  @return color.red($hex), color.green($hex), color.blue($hex);\\n}\\n\\n@function schemeType() {\\n  @if is-light-color-scheme() {\\n    @return \\"light\\";\\n  } @else {\\n    @return \\"dark\\";\\n  }\\n}\\n\\n@function absolute-image-url($path) {\\n  // public_image_path is added by the stylesheet importer\\n  // it returns a CDN or subfolder path (if applicable).\\n  // SCSS will compile (and return the relative path) if public_image_path is missing.\\n  /* stylelint-disable-next-line scss/no-global-function-names */\\n  @if global-variable-exists(public_image_path) {\\n    @if string.index(\\"#{$path}\\", \\"/plugins\\") == 1 {\\n      $plugin_asset_path: str-replace($public_image_path, \\"/images\\", \\"\\");\\n\\n      @return url(\\"#{$plugin_asset_path}#{$path}\\");\\n    } @else {\\n      @return url(\\"#{$public_image_path}#{$path}\\");\\n    }\\n  } @else {\\n    @return url(\\"#{$path}\\");\\n  }\\n}\\n\\n@mixin mention() {\\n  // memo to self: do not make this inline-flex because it breaks text alignments and causes a whole avalance of unpleasant consequences\\n  display: inline-block;\\n  font-size: 0.93em;\\n  font-weight: normal;\\n  color: var(--primary);\\n  padding: 0.2em 0.34em;\\n  background: var(--mention-background-color);\\n  border-radius: 0.6em;\\n  text-decoration: none;\\n  text-wrap: nowrap;\\n  line-height: 1;\\n  unicode-bidi: plaintext;\\n\\n  &[data-valid=\\"false\\"] {\\n    background: unset;\\n    padding: 0;\\n  }\\n\\n  &.--bot {\\n    background: var(--success-low);\\n  }\\n\\n  &.--wide {\\n    background: var(--highlight-low-or-medium);\\n  }\\n}\\n\\n@mixin nav-active() {\\n  color: var(--d-nav-color--active);\\n  background: var(--d-nav-bg-color--active);\\n\\n  .d-icon {\\n    color: var(--d-nav-color--active);\\n  }\\n\\n  &::after {\\n    content: \\"\\";\\n    position: absolute;\\n    left: 0;\\n    bottom: 0;\\n    right: 0;\\n    height: var(--d-nav-underline-height);\\n    background: var(--d-nav-color--active);\\n\\n    // Forced colors drop backgrounds, which is the only thing that marks\\n    // the active item.\\n    @media (forced-colors: active) {\\n      background: Highlight;\\n      forced-color-adjust: none;\\n    }\\n  }\\n}\\n\\n@mixin nav-hover() {\\n  color: var(--d-nav-color--hover);\\n  background: var(--d-nav-bg-color--hover);\\n\\n  .d-icon {\\n    color: var(--d-nav-color--active);\\n  }\\n}\\n\\n// A strip that hides its scrollbar and fades the edge beyond which more\\n// content lies. The fade reads the data-d-scroll-* attributes stamped by\\n// the scroll-edges watcher, which DOverflowControls and the dScrollEdges\\n// modifier both run. The band starts fully transparent across --fade-inset\\n// so strip content never shows through a chevron parked on the edge, which\\n// assumes the chevron covers that band: a wrapper that pads the scroller's\\n// scrolling edge moves the chevron off it and hides content under nothing.\\n// #000 is deliberate: a mask reads only alpha, so a colour token would be\\n// wrong here.\\n@mixin scroll-strip() {\\n  // The bands are capped so the two ends cannot cross on a narrow strip.\\n  // Crossed bands leave no opaque middle.\\n  --scroll-strip-fade-start: min(var(--fade-inset, 0px), 15%);\\n  --scroll-strip-fade-end: min(\\n    calc(var(--fade-inset, 0px) + var(--fade-width, 2em)),\\n    40%\\n  );\\n  min-width: 0;\\n  min-height: 0;\\n  scrollbar-width: none;\\n  scroll-padding: calc(var(--fade-inset, 0px) + var(--fade-width, 2em));\\n\\n  &::-webkit-scrollbar {\\n    display: none;\\n  }\\n\\n  // Forced colors drop the mask, which would otherwise lower text contrast\\n  // for exactly the users who opted out of decoration.\\n  @media (forced-colors: none) {\\n    &[data-d-scroll-axis=\\"horizontal\\"][data-d-scroll-overflow] {\\n      mask-image: linear-gradient(\\n        to right,\\n        transparent var(--scroll-strip-fade-start),\\n        #000 var(--scroll-strip-fade-end),\\n        #000 calc(100% - var(--scroll-strip-fade-end)),\\n        transparent calc(100% - var(--scroll-strip-fade-start))\\n      );\\n\\n      // The edges are logical, the gradients physical, so RTL swaps them.\\n      &[data-d-scroll-at-start] {\\n        mask-image: linear-gradient(\\n          to right,\\n          #000 calc(100% - var(--scroll-strip-fade-end)),\\n          transparent calc(100% - var(--scroll-strip-fade-start))\\n        );\\n\\n        .rtl & {\\n          mask-image: linear-gradient(\\n            to left,\\n            #000 calc(100% - var(--scroll-strip-fade-end)),\\n            transparent calc(100% - var(--scroll-strip-fade-start))\\n          );\\n        }\\n      }\\n\\n      &[data-d-scroll-at-end] {\\n        mask-image: linear-gradient(\\n          to right,\\n          transparent var(--scroll-strip-fade-start),\\n          #000 var(--scroll-strip-fade-end)\\n        );\\n\\n        .rtl & {\\n          mask-image: linear-gradient(\\n            to left,\\n            transparent var(--scroll-strip-fade-start),\\n            #000 var(--scroll-strip-fade-end)\\n          );\\n        }\\n      }\\n    }\\n\\n    &[data-d-scroll-axis=\\"vertical\\"][data-d-scroll-overflow] {\\n      mask-image: linear-gradient(\\n        to bottom,\\n        transparent var(--scroll-strip-fade-start),\\n        #000 var(--scroll-strip-fade-end),\\n        #000 calc(100% - var(--scroll-strip-fade-end)),\\n        transparent calc(100% - var(--scroll-strip-fade-start))\\n      );\\n\\n      &[data-d-scroll-at-start] {\\n        mask-image: linear-gradient(\\n          to bottom,\\n          #000 calc(100% - var(--scroll-strip-fade-end)),\\n          transparent calc(100% - var(--scroll-strip-fade-start))\\n        );\\n      }\\n\\n      &[data-d-scroll-at-end] {\\n        mask-image: linear-gradient(\\n          to bottom,\\n          transparent var(--scroll-strip-fade-start),\\n          #000 var(--scroll-strip-fade-end)\\n        );\\n      }\\n    }\\n\\n    // The .rtl copy only exists to outrank the .rtl at-start/at-end rules\\n    // above, which score a class higher than the bare selector.\\n    &[data-d-scroll-overflow][data-d-scroll-at-start][data-d-scroll-at-end],\\n    .rtl\\n      &[data-d-scroll-overflow][data-d-scroll-at-start][data-d-scroll-at-end] {\\n      mask-image: none;\\n    }\\n  }\\n}\\n\\n// The scroll strip on the horizontal axis. The caller keeps its own items\\n// on one row; the mixin does not.\\n@mixin horizontal-scroll-strip() {\\n  @include scroll-strip;\\n  overflow-x: auto;\\n}\\n\\n@mixin click-counter-badge {\\n  content: attr(data-clicks);\\n  font-weight: normal;\\n  background-color: var(--primary-low);\\n  color: var(--primary-medium);\\n  position: relative;\\n  top: -1px;\\n  padding: 0.21em 0.42em;\\n  min-width: 0.5em;\\n  line-height: var(--line-height-small);\\n  font-size: var(--font-down-2);\\n  text-align: center;\\n  border-radius: 10px;\\n  white-space: nowrap;\\n  display: inline-block;\\n  margin: 0.15em;\\n}\\n\\n@mixin topic-list-icons {\\n  .d-icon-thumbtack {\\n    color: var(--primary-med-or-secondary-med);\\n  }\\n\\n  .d-icon-thumbtack.unpinned {\\n    color: var(--primary-med-or-secondary-med);\\n  }\\n\\n  a.title {\\n    color: var(--primary);\\n  }\\n\\n  .d-icon-bookmark {\\n    color: var(--primary-med-or-secondary-med);\\n  }\\n}\\n\\n@mixin hide-posters {\\n  width: 2em;\\n  text-align: center;\\n\\n  a:first-child .avatar.latest:not(.single) {\\n    top: 0;\\n    left: 0;\\n  }\\n\\n  a:not(.latest) {\\n    display: none;\\n  }\\n\\n  a.latest {\\n    width: 100%;\\n\\n    img {\\n      margin: 0 auto;\\n    }\\n  }\\n}\\n\\n@mixin dot-separator($size: 0.35em) {\\n  display: inline-block;\\n  width: $size;\\n  height: $size;\\n  margin-inline: var(--space-1);\\n  border-radius: 6.25em;\\n  background: var(--primary-low-mid);\\n  flex-shrink: 0;\\n}\\n\\n@mixin menu-item {\\n  display: inline-flex;\\n  gap: var(--d-sidebar-section-link-prefix-margin-right);\\n  padding: var(--space-2) var(--d-sidebar-row-horizontal-padding);\\n  width: 100%;\\n  justify-content: flex-start;\\n  background: rgb(0, 0, 0, 0);\\n  border-radius: var(--d-border-radius);\\n\\n  &:not(.notifications-tracking-btn, .--with-description, .pinned-options-btn) {\\n    height: var(--d-sidebar-row-height);\\n    padding-block: 0;\\n  }\\n\\n  &.-selected {\\n    background: var(--d-hover);\\n  }\\n\\n  &.btn-danger {\\n    color: var(--danger);\\n\\n    .d-icon {\\n      color: inherit;\\n    }\\n  }\\n\\n  .svg-icon {\\n    width: var(--d-sidebar-section-link-prefix-width);\\n    margin-right: 0;\\n  }\\n\\n  &:hover,\\n  &:focus-visible {\\n    .discourse-no-touch & {\\n      background: var(--d-hover);\\n      color: var(--primary);\\n\\n      .d-icon {\\n        color: inherit;\\n      }\\n\\n      &.btn-danger {\\n        background: var(--danger-low);\\n        color: var(--danger);\\n\\n        .d-icon {\\n          color: var(--danger-hover);\\n        }\\n      }\\n    }\\n  }\\n}\\n\\n@mixin unstyled-list {\\n  list-style: none;\\n  padding: 0;\\n  margin: 0;\\n}\\n",".workflows-variable-input {\\n  display: flex;\\n  flex-direction: column;\\n  width: 100%;\\n  border: 1px solid var(--primary-low-mid);\\n  border-radius: var(--d-border-radius);\\n  background: var(--secondary);\\n  box-sizing: border-box;\\n\\n  // Editor and scroller fill the wrapper, so a taller field has no dead strip\\n  // below the text where clicks and drops don't register.\\n  .cm-editor {\\n    flex: 1 1 auto;\\n\\n    // Text cursor over the whole field, so the empty area reads as editable.\\n    .cm-scroller {\\n      flex: 1 1 auto;\\n      cursor: text;\\n    }\\n  }\\n\\n  .cm-editor .cm-content {\\n    min-height: 60px;\\n    padding: 0.5em;\\n    font-size: var(--font-0);\\n    font-family: inherit;\\n  }\\n\\n  .cm-editor .cm-lineWrapping {\\n    word-break: break-all;\\n  }\\n\\n  &:focus-within {\\n    outline: none;\\n    border-color: var(--tertiary);\\n    box-shadow: 0 0 0 1px var(--tertiary);\\n  }\\n\\n  .is-drag-over & {\\n    border-color: var(--tertiary);\\n    background: var(--tertiary-50);\\n  }\\n\\n  .cm-editor {\\n    background: transparent;\\n    color: var(--primary);\\n\\n    &.cm-focused {\\n      outline: none;\\n    }\\n\\n    .cm-cursor {\\n      border-left-color: var(--primary);\\n    }\\n\\n    .cm-selectionBackground {\\n      background: var(--tertiary-low) !important;\\n    }\\n\\n    .cm-content {\\n      caret-color: var(--primary);\\n    }\\n\\n    .cm-activeLine {\\n      background: transparent;\\n    }\\n\\n    // Base override for all CM tooltips — CM injects a light baseTheme\\n    // dynamically, so we must override it for dark mode support.\\n    .cm-tooltip {\\n      z-index: z(\\"modal\\", \\"tooltip\\") !important;\\n      background: var(--secondary);\\n      border: 1px solid var(--primary-low-mid);\\n      border-radius: var(--d-border-radius);\\n      color: var(--primary);\\n      font-size: var(--font-down-2);\\n      box-shadow: var(--shadow-dropdown);\\n    }\\n\\n    .cm-tooltip-autocomplete {\\n      > ul {\\n        font-family: inherit;\\n\\n        > li {\\n          padding: 1px 0.4em;\\n        }\\n      }\\n\\n      li[aria-selected] {\\n        background: var(--tertiary-low);\\n        color: var(--primary);\\n      }\\n    }\\n\\n    // Section headers in the autocomplete dropdown\\n    .cm-expr-section-header {\\n      padding: 0.1em 0.4em;\\n      font-size: var(--font-down-3);\\n      font-weight: 700;\\n      color: var(--primary-medium);\\n      text-transform: uppercase;\\n      letter-spacing: 0.05em;\\n      border-bottom: 1px solid var(--primary-low);\\n    }\\n\\n    // Info tooltip panel next to autocomplete — inherits font-size\\n    // from .cm-tooltip (--font-down-2) for consistency with the list.\\n    .cm-completionInfo {\\n      padding: 0.3em 0.5em;\\n      max-width: 200px;\\n      width: 200px;\\n      box-sizing: border-box;\\n      overflow-wrap: break-word;\\n    }\\n\\n    .cm-expr-completion-info {\\n      &__signature {\\n        font-family: var(--d-font-family--monospace);\\n        font-weight: 600;\\n        margin-bottom: 0.15em;\\n        color: var(--primary-medium);\\n        word-break: break-all;\\n      }\\n\\n      &__description {\\n        color: var(--primary-high);\\n        margin-bottom: 0.15em;\\n        line-height: 1.3;\\n      }\\n\\n      &__example code {\\n        background: var(--primary-very-low);\\n        padding: 0.1em 0.2em;\\n        border-radius: 2px;\\n        font-family: var(--d-font-family--monospace);\\n        font-size: 0.9em;\\n        word-break: break-all;\\n      }\\n    }\\n\\n    // Syntax highlighting — theme-aware via Discourse CSS vars\\n    .cm-wf-text {\\n      color: var(--primary);\\n    }\\n\\n    .cm-wf-brace {\\n      color: var(--tertiary);\\n      opacity: 0.7;\\n      font-weight: 700;\\n    }\\n\\n    .cm-wf-keyword {\\n      color: var(--tertiary);\\n    }\\n\\n    .cm-wf-string {\\n      color: var(--success);\\n    }\\n\\n    .cm-wf-number {\\n      color: var(--success);\\n    }\\n\\n    .cm-wf-bool,\\n    .cm-wf-null {\\n      color: var(--tertiary);\\n    }\\n\\n    .cm-wf-variable {\\n      color: var(--primary-high);\\n    }\\n\\n    .cm-wf-property {\\n      color: var(--primary-high);\\n    }\\n\\n    .cm-wf-function {\\n      color: var(--tertiary-hover);\\n    }\\n\\n    .cm-wf-operator,\\n    .cm-wf-punctuation {\\n      color: var(--primary);\\n    }\\n\\n    .cm-wf-comment {\\n      color: var(--primary-medium);\\n      font-style: italic;\\n    }\\n\\n    // Validation underlines\\n    .cm-wf-error {\\n      text-decoration: wavy underline var(--danger);\\n      text-decoration-skip-ink: none;\\n      text-underline-offset: 3px;\\n    }\\n\\n    // Expression state colors — applied by backend evaluation results\\n    .cm-wf-valid-expression {\\n      background: color-mix(in srgb, var(--success) 12%, transparent);\\n      border-radius: 2px;\\n    }\\n\\n    .cm-wf-invalid-expression {\\n      background: color-mix(in srgb, var(--danger) 20%, transparent);\\n      border-radius: 2px;\\n      outline: 1px solid color-mix(in srgb, var(--danger) 30%, transparent);\\n    }\\n\\n    .cm-wf-empty-expression {\\n      background: color-mix(in srgb, var(--primary-low-mid) 20%, transparent);\\n      border-radius: 2px;\\n      outline: 1px dashed\\n        color-mix(in srgb, var(--primary-medium) 40%, transparent);\\n    }\\n\\n    .cm-wf-warning-expression {\\n      background: color-mix(in srgb, var(--highlight-medium) 40%, transparent);\\n      border-radius: 2px;\\n    }\\n\\n    .cm-wf-pending-expression {\\n      background: color-mix(in srgb, var(--primary-low-mid) 30%, transparent);\\n      border-radius: 2px;\\n    }\\n\\n    .cm-wf-reference-pill {\\n      display: inline-flex;\\n      align-items: center;\\n      gap: 0.25em;\\n      max-width: 100%;\\n      padding: 1px 0.5em;\\n\\n      // Inset shadow, not a border: a border would add to the pill's height.\\n      box-shadow: inset 0 0 0 1px var(--tertiary-low-mid, var(--tertiary-low));\\n      border-radius: 1em;\\n      background: var(--tertiary-low);\\n      color: var(--tertiary-hover);\\n      font-size: var(--font-down-1);\\n      line-height: 1.15;\\n      white-space: nowrap;\\n\\n      // Middle, not baseline, so pills with/without a path line up.\\n      vertical-align: middle;\\n      margin-block: 1px;\\n      cursor: grab;\\n\\n      &:hover {\\n        background: color-mix(in srgb, var(--tertiary) 22%, transparent);\\n      }\\n\\n      &:active {\\n        cursor: grabbing;\\n      }\\n\\n      &.--selected {\\n        background: color-mix(in srgb, var(--tertiary) 30%, transparent);\\n        box-shadow: inset 0 0 0 1px var(--tertiary);\\n      }\\n\\n      &.--incomplete {\\n        outline: 1px dashed color-mix(in srgb, var(--tertiary) 55%, transparent);\\n        outline-offset: -1px;\\n      }\\n\\n      &.--invalid {\\n        background: color-mix(in srgb, var(--danger) 12%, transparent);\\n        box-shadow: inset 0 0 0 1px var(--danger);\\n        color: var(--danger);\\n\\n        .cm-wf-reference-pill__icon,\\n        .cm-wf-reference-pill__drill {\\n          color: var(--danger);\\n        }\\n      }\\n\\n      &__icon {\\n        display: inline-flex;\\n        color: var(--tertiary);\\n\\n        .d-icon {\\n          width: 0.85em;\\n          height: 0.85em;\\n        }\\n      }\\n\\n      &__badge {\\n        flex-shrink: 0;\\n        max-width: 16ch;\\n        overflow: hidden;\\n        text-overflow: ellipsis;\\n        font-weight: 600;\\n      }\\n\\n      // Not monospace: the browser's monospace-size quirk made these pills\\n      // taller than badge-only ones.\\n      &__path {\\n        min-width: 0;\\n        overflow: hidden;\\n        text-overflow: ellipsis;\\n\\n        &::before {\\n          content: \\"›\\";\\n          margin-inline-end: 0.3em;\\n          opacity: 0.6;\\n        }\\n      }\\n\\n      &__drill {\\n        display: inline-flex;\\n        align-items: center;\\n        padding: 0;\\n        margin-inline-start: 0.1em;\\n        border: none;\\n        background: none;\\n        color: var(--tertiary);\\n        cursor: pointer;\\n\\n        .d-icon {\\n          width: 0.7em;\\n          height: 0.7em;\\n        }\\n\\n        &:hover {\\n          color: var(--tertiary-hover);\\n        }\\n      }\\n    }\\n\\n    // Drop cursor during variable drag\\n    .cm-dropCursor {\\n      position: absolute;\\n      width: 2px;\\n      background: var(--tertiary);\\n      pointer-events: none;\\n      z-index: 10;\\n    }\\n  }\\n\\n  .cm-tooltip-hover {\\n    background: var(--secondary) !important;\\n    border: 1px solid var(--primary-low-mid) !important;\\n    border-radius: var(--d-border-radius);\\n    box-shadow: var(--shadow-dropdown);\\n  }\\n\\n  .cm-wf-hover-tooltip {\\n    padding: 0.4em 0.6em;\\n    max-width: 260px;\\n    font-size: var(--font-down-2);\\n\\n    &__name {\\n      color: var(--tertiary);\\n      margin-bottom: 0.15em;\\n    }\\n\\n    &__description {\\n      color: var(--primary-high);\\n      line-height: 1.3;\\n    }\\n  }\\n\\n  .workflows-property-engine__collection-fields & {\\n    min-height: 100px;\\n\\n    &:focus-within {\\n      box-shadow: none;\\n    }\\n  }\\n}\\n\\n.fk-d-tooltip__content[data-identifier=\\"expression-preview\\"] {\\n  // Above normal content, below modal tooltips/popovers where CM autocomplete lives\\n  z-index: z(\\"tooltip\\") !important;\\n  box-sizing: border-box;\\n  pointer-events: auto;\\n  user-select: text;\\n\\n  .fk-d-tooltip__inner-content {\\n    display: block;\\n    width: 100%;\\n    pointer-events: auto;\\n    user-select: text;\\n  }\\n}\\n\\n.expression-preview {\\n  padding: 0.3em 0.5em;\\n  font-size: var(--font-down-2);\\n  font-family: var(--d-font-family--monospace);\\n  max-height: 80px;\\n  overflow-y: auto;\\n\\n  &__result {\\n    white-space: pre-wrap;\\n    word-break: break-word;\\n  }\\n\\n  &__label {\\n    float: right;\\n    font-weight: 700;\\n    font-size: var(--font-down-3);\\n    text-transform: uppercase;\\n    letter-spacing: 0.05em;\\n    color: var(--primary-low-mid);\\n    margin-left: 0.5em;\\n    user-select: none;\\n    pointer-events: none;\\n  }\\n\\n  &__error-text {\\n    color: var(--danger);\\n    background: color-mix(in srgb, var(--danger) 10%, transparent);\\n    border-radius: 2px;\\n    padding: 0.1em 0.2em;\\n  }\\n\\n  &__resolved {\\n    &.--valid {\\n      color: var(--tertiary);\\n    }\\n\\n    &.--invalid,\\n    &.--undefined {\\n      color: var(--danger);\\n      background: color-mix(in srgb, var(--danger) 10%, transparent);\\n      border-radius: 2px;\\n      padding: 0.1em 0.2em;\\n    }\\n\\n    &.--warning {\\n      color: var(--warning, light-dark(#b5651d, #e6a33e));\\n      background: color-mix(in srgb, var(--warning, #e6a33e) 10%, transparent);\\n      border-radius: 2px;\\n      padding: 0.1em 0.2em;\\n      font-style: italic;\\n    }\\n\\n    &.--pending {\\n      color: var(--primary-medium);\\n    }\\n\\n    &.--label {\\n      background: color-mix(in srgb, var(--primary-low-mid) 40%, transparent);\\n      border-radius: 2px;\\n      padding: 0.1em 0.4em;\\n      font-size: var(--font-down-1);\\n    }\\n  }\\n\\n  &__plaintext {\\n    color: var(--primary);\\n  }\\n}\\n\\n// The picker opens over the node configurator modal, so it must sit above it.\\n.fk-d-menu[data-identifier=\\"workflows-reference-picker\\"] {\\n  z-index: z(\\"modal\\", \\"tooltip\\") !important;\\n}\\n\\n.workflows-reference-picker {\\n  display: flex;\\n  flex-direction: column;\\n  min-width: 240px;\\n  max-width: 340px;\\n  font-size: var(--font-down-1);\\n\\n  &__header {\\n    display: flex;\\n    align-items: stretch;\\n    border-bottom: 1px solid var(--primary-low);\\n  }\\n\\n  // Scoped under __header (two classes) to out-specify the global\\n  // `input[type=text]` border/outline without !important.\\n  &__header &__filter {\\n    flex: 1 1 auto;\\n    min-width: 0;\\n    box-sizing: border-box;\\n    margin: 0;\\n    padding: 0.5em 0.75em;\\n    border: 0;\\n    border-radius: 0;\\n    background: transparent;\\n    font-size: var(--font-down-1);\\n\\n    &:focus {\\n      outline: none;\\n      box-shadow: none;\\n    }\\n\\n    &:focus-visible {\\n      outline: 1px solid var(--tertiary);\\n      outline-offset: -1px;\\n    }\\n  }\\n\\n  &__list {\\n    margin: 0;\\n    padding: 0.25em 0;\\n    max-height: 280px;\\n    overflow-y: auto;\\n    list-style: none;\\n  }\\n\\n  &__option {\\n    display: flex;\\n    align-items: baseline;\\n    gap: 0.5em;\\n    width: 100%;\\n    padding: 0.3em 0.75em;\\n    border: none;\\n    background: none;\\n    text-align: start;\\n    cursor: pointer;\\n\\n    &:hover,\\n    &:focus,\\n    &.--active {\\n      background: var(--tertiary-low);\\n    }\\n\\n    &.--current .workflows-reference-picker__name {\\n      font-weight: 700;\\n      color: var(--tertiary);\\n    }\\n  }\\n\\n  &__name {\\n    flex: 1 1 auto;\\n    overflow: hidden;\\n    text-overflow: ellipsis;\\n    font-family: var(--d-font-family--monospace), monospace;\\n  }\\n\\n  &__type {\\n    flex: 0 0 auto;\\n    color: var(--primary-medium);\\n    font-size: var(--font-down-2);\\n  }\\n\\n  &__empty {\\n    padding: 0.5em 0.75em;\\n    color: var(--primary-medium);\\n    font-style: italic;\\n  }\\n\\n  &__unavailable {\\n    flex: 1 1 auto;\\n    padding: 0.5em 0.75em;\\n    color: var(--primary-medium);\\n    font-style: italic;\\n  }\\n\\n  &__edit {\\n    flex: 0 0 auto;\\n    display: inline-flex;\\n    align-items: center;\\n    gap: 0.3em;\\n    padding: 0 0.75em;\\n    border: 0;\\n    border-inline-start: 1px solid var(--primary-low);\\n    background: none;\\n    color: var(--primary-high);\\n    white-space: nowrap;\\n    cursor: pointer;\\n\\n    .d-icon {\\n      color: var(--primary-medium);\\n      font-size: var(--font-down-2);\\n    }\\n\\n    &:hover,\\n    &:focus {\\n      background: var(--tertiary-low);\\n      color: var(--tertiary-hover);\\n\\n      .d-icon {\\n        color: var(--tertiary-hover);\\n      }\\n    }\\n  }\\n}\\n",".workflows-variables {\\n  &__creator {\\n    display: inline-flex;\\n    align-items: center;\\n    gap: var(--space-1);\\n  }\\n}\\n",".workflows-versions {\\n  &__author {\\n    display: inline-flex;\\n    align-items: center;\\n    gap: var(--space-1);\\n  }\\n\\n  &__badge {\\n    display: inline-block;\\n    margin-inline-start: var(--space-1);\\n    padding: 0 var(--space-1);\\n    border-radius: var(--d-border-radius);\\n    font-size: var(--font-down-2);\\n    line-height: var(--line-height-large);\\n\\n    &.--current {\\n      background: var(--primary-low);\\n      color: var(--primary-medium);\\n    }\\n\\n    &.--live {\\n      background: var(--success-low);\\n      color: var(--success);\\n    }\\n  }\\n}\\n",".workflows-executions {\\n  &__table {\\n    width: 100%;\\n\\n    td {\\n      padding: var(--space-2) var(--space-1);\\n    }\\n  }\\n\\n  &__badge {\\n    font-size: var(--font-down-1);\\n    padding: 0.2em 0.5em;\\n    border-radius: 0.25em;\\n\\n    &.--success {\\n      background: var(--workflow-status-success-low);\\n      color: var(--workflow-status-success);\\n    }\\n\\n    &.--error {\\n      background: var(--workflow-status-error-low);\\n      color: var(--workflow-status-error);\\n    }\\n\\n    &.--running {\\n      background: var(--workflow-status-running-low);\\n      color: var(--workflow-status-running);\\n    }\\n\\n    &.--pending {\\n      background: var(--primary-low);\\n      color: var(--primary-medium);\\n    }\\n  }\\n\\n  &__time {\\n    font-size: var(--font-down-1);\\n    color: var(--primary-medium);\\n  }\\n\\n  &__empty {\\n    color: var(--primary-medium);\\n  }\\n}\\n",".workflows-executions-manager {\\n  &__status {\\n    display: inline-flex;\\n    align-items: center;\\n    gap: var(--space-2);\\n\\n    .d-icon,\\n    .spinner {\\n      font-size: var(--font-up-1);\\n    }\\n\\n    .spinner {\\n      margin: 0;\\n    }\\n\\n    &.--success .d-icon {\\n      color: var(--workflow-status-success);\\n    }\\n\\n    &.--error .d-icon {\\n      color: var(--workflow-status-error);\\n    }\\n\\n    &.--running .d-icon {\\n      color: var(--workflow-status-running);\\n    }\\n\\n    &.--waiting .d-icon {\\n      color: var(--workflow-status-waiting);\\n    }\\n\\n    &.--pending .d-icon {\\n      color: var(--primary-medium);\\n    }\\n  }\\n}\\n",".workflows-execution-detail {\\n  &__progress {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-2);\\n    margin-bottom: var(--space-3);\\n    padding: var(--space-2) var(--space-3);\\n    border: 1px solid var(--workflow-status-running);\\n    border-radius: 0.375em;\\n    background: var(--workflow-status-running-low);\\n    color: var(--workflow-status-running);\\n  }\\n\\n  &__progress-label {\\n    font-weight: bold;\\n  }\\n\\n  &__progress-time {\\n    margin-inline-start: auto;\\n    font-variant-numeric: tabular-nums;\\n  }\\n\\n  &__step {\\n    border: 1.5px solid var(--primary-low);\\n    border-radius: 0.375em;\\n    padding: var(--space-3) var(--space-3);\\n    margin-bottom: var(--space-3);\\n\\n    &.--success {\\n      border-color: var(--workflow-status-success);\\n      background: var(--workflow-status-success-low);\\n    }\\n\\n    &.--error {\\n      border-color: var(--workflow-status-error);\\n    }\\n\\n    &.--running {\\n      border-color: var(--workflow-status-running);\\n    }\\n\\n    &.--skipped {\\n      border-color: var(--primary-low);\\n      opacity: 0.7;\\n    }\\n\\n    &.--filtered {\\n      border-color: var(--primary-medium);\\n      opacity: 0.7;\\n    }\\n\\n    &.--waiting {\\n      border-color: var(--workflow-status-waiting);\\n    }\\n  }\\n\\n  &__step-header {\\n    display: flex;\\n    align-items: center;\\n    gap: var(--space-2);\\n  }\\n\\n  &__step-icon {\\n    flex-shrink: 0;\\n    width: 1.25em;\\n    text-align: center;\\n    color: var(--primary-medium);\\n\\n    .--kind-trigger & {\\n      color: var(--workflow-node-color-orange);\\n    }\\n\\n    .--kind-condition & {\\n      color: var(--workflow-node-color-teal);\\n    }\\n\\n    .--kind-action & {\\n      color: var(--workflow-node-color-purple);\\n    }\\n\\n    .--kind-flow & {\\n      color: var(--workflow-node-color-indigo);\\n    }\\n  }\\n\\n  &__step-name {\\n    font-weight: bold;\\n  }\\n\\n  &__step-operation {\\n    font-size: var(--font-down-1);\\n    color: var(--primary-medium);\\n\\n    &::before {\\n      content: \\"›\\";\\n      margin-right: var(--space-1);\\n    }\\n  }\\n\\n  &__kind-badge {\\n    font-size: var(--font-down-2);\\n    font-weight: bold;\\n    text-transform: lowercase;\\n    letter-spacing: 0.04em;\\n    padding: 0.15em 0.45em;\\n    border-radius: 0.25em;\\n\\n    &.--trigger {\\n      background: color-mix(\\n        in srgb,\\n        var(--workflow-node-color-orange) 15%,\\n        transparent\\n      );\\n      color: var(--workflow-node-color-orange);\\n    }\\n\\n    &.--condition {\\n      background: color-mix(\\n        in srgb,\\n        var(--workflow-node-color-teal) 15%,\\n        transparent\\n      );\\n      color: var(--workflow-node-color-teal);\\n    }\\n\\n    &.--action {\\n      background: color-mix(\\n        in srgb,\\n        var(--workflow-node-color-purple) 15%,\\n        transparent\\n      );\\n      color: var(--workflow-node-color-purple);\\n    }\\n\\n    &.--flow {\\n      background: color-mix(\\n        in srgb,\\n        var(--workflow-node-color-indigo) 15%,\\n        transparent\\n      );\\n      color: var(--workflow-node-color-indigo);\\n    }\\n  }\\n\\n  &__step-summary {\\n    font-size: var(--font-down-1);\\n    color: var(--workflow-status-error);\\n    margin-top: var(--space-1);\\n    padding-left: calc(1.25em + var(--space-2));\\n  }\\n\\n  &__step-type {\\n    font-size: var(--font-down-1);\\n    color: var(--primary-medium);\\n  }\\n\\n  &__step-badge {\\n    font-size: var(--font-down-2);\\n    font-weight: bold;\\n    text-transform: lowercase;\\n    padding: 0.1em 0.4em;\\n    border-radius: 0.25em;\\n\\n    &.--success {\\n      background: var(--workflow-status-success-low);\\n      color: var(--workflow-status-success);\\n    }\\n\\n    &.--error {\\n      background: var(--workflow-status-error-low);\\n      color: var(--workflow-status-error);