s\\";\\n    }\\n\\n    ul,\\n    ol {\\n      @include unstyled-list;\\n      display: inline-block;\\n      width: 100%;\\n    }\\n\\n    li[data-poll-option-id] {\\n      color: var(--primary);\\n      padding: 0.5em 0;\\n      word-break: break-word;\\n\\n      button {\\n        background-color: transparent;\\n        border: none;\\n        width: 100%;\\n        cursor: pointer;\\n        display: flex;\\n        align-items: flex-start;\\n        gap: 0.5em;\\n        text-align: left;\\n      }\\n\\n      button svg {\\n        flex: 0 0 auto;\\n        margin-top: 0.15em;\\n      }\\n\\n      .option-text {\\n        flex: 1 1 auto;\\n        min-width: 0;\\n      }\\n    }\\n\\n    .ranked-choice-poll-options {\\n      display: flex;\\n      flex-direction: column;\\n      gap: 0.5em;\\n      padding: 0.5em;\\n\\n      .ranked-choice-poll-option {\\n        display: inline-flex;\\n        flex-wrap: wrap;\\n        align-items: center;\\n        gap: 0.5em;\\n        padding: 0.5em;\\n      }\\n    }\\n\\n    .tabs {\\n      display: none;\\n    }\\n\\n    .discourse-poll-ranked_choice-results {\\n      .tabs {\\n        &.nav-items {\\n          display: flex;\\n          gap: 0.5em;\\n\\n          .nav-btn {\\n            background-color: var(--secondary);\\n            border: none;\\n            color: var(--primary-medium);\\n          }\\n\\n          .active {\\n            .nav-btn {\\n              color: var(--primary);\\n            }\\n          }\\n        }\\n      }\\n\\n      .rank {\\n        display: inline-block;\\n        min-width: 20px;\\n      }\\n\\n      .poll-results-ranked_choice-subtitle-rounds {\\n        margin: 0.25em 0 0.67rem;\\n      }\\n    }\\n\\n    img {\\n      // Hacky way to stop images without width/height\\n      // from causing abrupt unintended scrolling\\n      &:not([width], .emoji),\\n      &:not([height], .emoji) {\\n        width: 200px !important;\\n        height: 200px !important;\\n        object-fit: contain;\\n      }\\n    }\\n\\n    .poll-info {\\n      box-sizing: border-box;\\n      grid-area: info;\\n      display: flex;\\n      line-height: var(--line-height-medium);\\n      color: var(--primary-medium);\\n\\n      @include viewport.until(sm) {\\n        border-top: 1px solid var(--content-border-color);\\n        flex-direction: row-reverse;\\n\\n        &_counts,\\n        &_instructions {\\n          padding: 1em;\\n        }\\n      }\\n\\n      @include viewport.from(sm) {\\n        gap: 0 1em;\\n        padding: var(--space-2);\\n        border-left: 1px solid var(--content-border-color);\\n        flex-direction: column;\\n        justify-content: center;\\n        align-items: center;\\n      }\\n\\n      &_counts {\\n        display: flex;\\n        flex-wrap: wrap;\\n        align-items: center;\\n        width: 100%;\\n        gap: 0.25em 0;\\n\\n        @include viewport.from(sm) {\\n          justify-content: center;\\n        }\\n\\n        @include viewport.until(sm) {\\n          flex: 1 1 auto;\\n        }\\n\\n        &-count {\\n          gap: 0.25em;\\n          line-height: 1;\\n          white-space: nowrap;\\n          text-align: left;\\n\\n          .info-label,\\n          .info-number {\\n            display: inline;\\n            margin-right: 0.25em;\\n            text-align: center;\\n          }\\n\\n          @include viewport.until(sm) {\\n            &:not(:last-child) {\\n              margin-right: 0.75em;\\n            }\\n          }\\n\\n          @include viewport.from(sm) {\\n            &:not(:last-child) {\\n              margin-bottom: 0.25em;\\n            }\\n            display: flex;\\n            flex-direction: column;\\n            align-items: center;\\n\\n            .info-label,\\n            .info-number {\\n              margin: 0;\\n            }\\n\\n            + .poll-info_counts-count {\\n              display: flex;\\n              flex-direction: row;\\n              flex-wrap: wrap;\\n              justify-content: center;\\n              min-width: 0;\\n              gap: 0 0.33em;\\n              margin: 0.5em;\\n\\n              .info-number,\\n              .info-label {\\n                font-size: var(--font-up-1);\\n                min-width: 0;\\n                white-space: normal;\\n                line-height: var(--line-height-medium);\\n              }\\n            }\\n          }\\n        }\\n\\n        @include viewport.from(sm) {\\n          + .poll-info_instructions:not(:empty) {\\n            margin-top: 1.25em;\\n          }\\n        }\\n      }\\n\\n      &_instructions {\\n        box-sizing: border-box;\\n        display: flex;\\n        flex-direction: column;\\n        justify-content: center;\\n        align-self: start;\\n\\n        &:empty {\\n          display: none;\\n        }\\n\\n        @include viewport.from(sm) {\\n          padding-top: 1.25em;\\n\\n          &:not(:empty) {\\n            border-top: 1px solid var(--content-border-color);\\n          }\\n        }\\n\\n        @include viewport.until(sm) {\\n          padding-right: 1em;\\n          height: 100%;\\n          flex: 1 1 auto;\\n\\n          &:not(:empty) {\\n            border-right: 1px solid var(--content-border-color);\\n          }\\n        }\\n\\n        li {\\n          display: flex;\\n          gap: 0.5em;\\n\\n          &.vote-recorded .d-icon {\\n            color: var(--success);\\n          }\\n\\n          &:not(:last-child) {\\n            margin-bottom: 0.5em;\\n          }\\n\\n          @include viewport.from(sm) {\\n            &:not(:last-child) {\\n              margin-bottom: 1em;\\n            }\\n\\n            &:not(:first-child:last-child) {\\n              // only applied when there are multiple items\\n              .d-icon {\\n                width: 15%;\\n              }\\n\\n              span {\\n                width: 85%;\\n              }\\n            }\\n\\n            &:first-child:last-child {\\n              // when there's a single item, it looks better centered\\n              display: inline;\\n              text-align: center;\\n            }\\n          }\\n        }\\n\\n        .d-icon {\\n          font-size: var(--font-down-1);\\n          margin-top: 0.2em;\\n        }\\n      }\\n\\n      .info-text {\\n        margin: 0.25em 0;\\n        display: block;\\n      }\\n\\n      @include viewport.from(sm) {\\n        .info-label {\\n          font-size: var(--font-up-2);\\n        }\\n\\n        .info-number {\\n          font-size: var(--font-up-6);\\n        }\\n      }\\n    }\\n\\n    .poll-container {\\n      box-sizing: border-box;\\n      grid-area: poll;\\n      padding: 1em;\\n      width: 100%;\\n      overflow: visible;\\n      align-self: center;\\n\\n      li {\\n        cursor: pointer;\\n        font-size: var(--font-up-1);\\n      }\\n\\n      .poll-results-number-rating {\\n        font-size: var(--font-up-5);\\n      }\\n\\n      .poll-voted-choices {\\n        &__title {\\n          color: var(--primary-medium);\\n        }\\n\\n        &__list {\\n          margin-top: 0.5em;\\n        }\\n\\n        &__choice {\\n          display: flex;\\n          align-items: flex-start;\\n          gap: 0.5em;\\n          padding: 0.25em 0;\\n          cursor: default;\\n          word-break: break-word;\\n\\n          .d-icon,\\n          .poll-voted-choices__rank {\\n            flex: 0 0 auto;\\n          }\\n\\n          .d-icon {\\n            margin-top: 0.3em;\\n            color: var(--success);\\n          }\\n\\n          .poll-voted-choices__rank {\\n            min-width: 1.5em;\\n            margin-top: 0.15em;\\n            text-align: center;\\n            background: var(--primary-low);\\n            border-radius: var(--d-border-radius);\\n            font-size: var(--font-down-1);\\n            line-height: 1.6em;\\n          }\\n        }\\n      }\\n    }\\n\\n    .poll-title {\\n      border-bottom: 1px solid var(--content-border-color);\\n      margin-bottom: 0.5em;\\n      padding-bottom: 0.5em;\\n    }\\n\\n    .poll-buttons {\\n      box-sizing: border-box;\\n      grid-area: buttons;\\n      display: flex;\\n      flex-wrap: wrap;\\n      gap: 0.5em;\\n      width: 100%;\\n      padding: 1em;\\n      border-top: 1px solid var(--content-border-color);\\n\\n      button {\\n        white-space: nowrap;\\n        align-self: start;\\n\\n        .d-button-label {\\n          @include ellipsis;\\n        }\\n\\n        @include viewport.until(md) {\\n          flex: 1 1 0;\\n\\n          &:first-child:last-child {\\n            // if there's only one button,\\n            // don't expand the width\\n            flex: 0 1 auto;\\n          }\\n\\n          &.toggle-results:first-child,\\n          &.keep-vote:first-child {\\n            // don't expand the back button\\n            flex: 0 1 auto;\\n            margin-right: auto;\\n          }\\n        }\\n\\n        @include viewport.until(sm) {\\n          &:first-child:last-child,\\n          &.cast-votes {\\n            // ok to expand button width on smaller screens\\n            flex: 1 1 100%;\\n          }\\n        }\\n      }\\n\\n      &:empty {\\n        display: none;\\n      }\\n    }\\n\\n    .poll-voters:not(:empty) {\\n      min-height: 30px;\\n      margin-bottom: 0.25em;\\n\\n      li {\\n        display: inline;\\n      }\\n    }\\n\\n    .poll-voters-toggle-expand {\\n      margin-top: 0.25em;\\n      width: 100%;\\n      text-align: center;\\n\\n      .spinner {\\n        margin-top: 0.25em;\\n      }\\n    }\\n\\n    .poll-buttons-dropdown,\\n    .export-results,\\n    .toggle-status,\\n    .show-breakdown,\\n    .show-tally,\\n    .show-percentage {\\n      // we want these controls to be separated\\n      // from voting controls\\n      margin-left: auto;\\n    }\\n\\n    .results {\\n      > li {\\n        cursor: default;\\n        padding: 0.25em 0;\\n\\n        &:last-child {\\n          padding-bottom: 0;\\n        }\\n      }\\n\\n      .option {\\n        p {\\n          margin: 0;\\n        }\\n      }\\n\\n      .percentage,\\n      .absolute {\\n        float: right;\\n        color: var(--primary-medium);\\n        margin-left: 0.25em;\\n      }\\n\\n      .bar-back {\\n        background: var(--poll-bar-background);\\n      }\\n\\n      .bar {\\n        height: 0.75em;\\n        background: var(--poll-bar-color);\\n      }\\n\\n      .chosen .bar {\\n        background: var(--poll-bar-color--chosen);\\n      }\\n    }\\n\\n    .pie-chart-legends {\\n      justify-content: center;\\n      text-align: center;\\n      margin-top: 0.5em;\\n\\n      .legend {\\n        align-items: center;\\n        cursor: pointer;\\n        display: inline-flex;\\n        flex-direction: row;\\n        margin-left: 1em;\\n        font-size: var(--font-down-0);\\n\\n        .swatch {\\n          margin-right: 0.5em;\\n          display: inline-block;\\n          height: 16px;\\n          width: 16px;\\n        }\\n      }\\n    }\\n\\n    .poll-grouped-pies-controls {\\n      display: flex;\\n      justify-content: space-between;\\n    }\\n\\n    .poll-results-chart {\\n      overflow-y: auto;\\n      overflow-x: hidden;\\n    }\\n  }\\n\\n  &[data-poll-type=\\"number\\"] {\\n    li[data-poll-option-id] {\\n      display: inline-block;\\n      width: 3.25em;\\n      margin-right: 0.25em;\\n    }\\n  }\\n}\\n\\n.d-editor-preview {\\n  .poll {\\n    ul {\\n      list-style-type: none;\\n      padding: 0;\\n    }\\n\\n    li[data-poll-option-id]::before {\\n      position: relative;\\n      vertical-align: baseline;\\n      border: 2px solid var(--primary);\\n      border-radius: 50%;\\n      display: inline-block;\\n      margin-right: 0.5em;\\n      width: 12px;\\n      height: 12px;\\n      content: \\"\\";\\n    }\\n\\n    &[data-poll-type=\\"multiple\\"],\\n    &[data-poll-type=\\"ranked_choice\\"] {\\n      [data-poll-option-id] {\\n        display: flex;\\n        align-items: center;\\n      }\\n    }\\n\\n    &[data-poll-type=\\"multiple\\"] {\\n      li[data-poll-option-id]::before {\\n        border-radius: 3px;\\n      }\\n    }\\n\\n    &[data-poll-type=\\"ranked_choice\\"] {\\n      li[data-poll-option-id] {\\n        position: relative;\\n\\n        &::before {\\n          mask-image: svg-uri(\\n            '<svg width=\\"0.75em\\" height=\\"0.75em\\" xmlns=\\"http://www.w3.org/2000/svg\\" viewBox=\\"0 0 448 512\\">\\\\3c !--!Font Awesome Free 6.6.0 by @fontawesome - https://fontawesome.com License - https://fontawesome.com/license/free Copyright 2024 Fonticons, Inc.--><path d=\\"M201.4 374.6c12.5 12.5 32.8 12.5 45.3 0l160-160c12.5-12.5 12.5-32.8 0-45.3s-32.8-12.5-45.3 0L224 306.7 86.6 169.4c-12.5-12.5-32.8-12.5-45.3 0s-12.5 32.8 0 45.3l160 160z\\"/></svg>'\\n          );\\n          z-index: 1;\\n          width: 0.75em;\\n          margin-right: 0.75em;\\n          left: 0.2em;\\n          background: var(--primary-high);\\n          border-radius: var(--d-button-border-radius);\\n          border: none;\\n        }\\n\\n        &::after {\\n          content: \\"\\";\\n          position: absolute;\\n          height: 1.125em;\\n          width: 1.125em;\\n          background: var(--primary-low);\\n          border-radius: var(--d-button-border-radius);\\n        }\\n      }\\n    }\\n  }\\n}\\n\\n// hides 0 vote count in crawler and print view\\nbody.crawler {\\n  .poll {\\n    .poll-info,\\n    .poll-button {\\n      display: none;\\n    }\\n  }\\n}\\n\\n// The cooked poll styles above also apply inside the editor, so the rules here\\n// that carry a `.poll` or a media query are deliberately written to outrank a\\n// specific one of them.\\n.composer-poll-node {\\n  &__content {\\n    min-width: 0;\\n\\n    > ul {\\n      margin: 0;\\n\\n      > li {\\n        position: relative;\\n        padding: 0.5em 0;\\n        padding-inline-start: 1.5em;\\n        overflow-wrap: anywhere;\\n\\n        > p {\\n          margin: 0;\\n        }\\n\\n        &::before {\\n          content: \\"\\";\\n          position: absolute;\\n          inset-inline-start: 0;\\n          top: 0.75em;\\n          width: 0.9em;\\n          height: 0.9em;\\n          box-sizing: border-box;\\n          border: 2px solid var(--primary);\\n          border-radius: 50%;\\n        }\\n      }\\n    }\\n  }\\n\\n  &__info {\\n    display: contents;\\n  }\\n\\n  .ProseMirror &.poll {\\n    grid-template-areas: \\"poll\\" \\"info\\" \\"buttons\\";\\n\\n    @include viewport.from(sm) {\\n      // sized to its content, so a setting is not split across lines\\n      grid-template-columns: 1fr max-content;\\n      grid-template-areas: \\"poll info\\" \\"buttons buttons\\";\\n    }\\n  }\\n\\n  @include viewport.from(sm) {\\n    .ProseMirror &.poll &__info .poll-info {\\n      max-width: 18em;\\n    }\\n  }\\n\\n  // the cooked column has a fixed width, so its lines share it by percentage;\\n  // here the column follows the text, which then needs its natural width\\n  .ProseMirror\\n    &.poll\\n    &__info\\n    .poll-info_instructions\\n    li:not(:first-child:last-child) {\\n    .d-icon,\\n    span {\\n      width: auto;\\n    }\\n  }\\n\\n  &.poll:not([data-poll-type=\\"number\\"]) &__content > ul > li {\\n    cursor: text;\\n  }\\n\\n  // a lone instruction is centred by the cooked styles, which lets the icon\\n  // fall onto a line of its own here: centre the pair instead\\n  @include viewport.from(sm) {\\n    &.poll &__info .poll-info_instructions li:first-child:last-child {\\n      display: flex;\\n      justify-content: center;\\n    }\\n  }\\n\\n  &.--untitled &__content > .poll-title::before {\\n    content: var(--poll-title-placeholder, \\"\\");\\n    color: var(--primary-medium);\\n    position: absolute;\\n    pointer-events: none;\\n  }\\n\\n  // the parsed info node is replaced by the one rendered below it\\n  &.poll &__content > .poll-info {\\n    display: none;\\n  }\\n\\n  &[data-poll-type=\\"multiple\\"] &__content > ul > li::before {\\n    border-radius: 0.15em;\\n  }\\n\\n  &[data-poll-type=\\"ranked_choice\\"] &__content > ul {\\n    counter-reset: poll-option;\\n\\n    > li::before {\\n      counter-increment: poll-option;\\n      content: counter(poll-option);\\n      top: 0.5em;\\n      width: 1em;\\n      height: auto;\\n      border: none;\\n      border-radius: 0;\\n      color: var(--primary-medium);\\n    }\\n  }\\n}\\n","@use \\"breakpoints\\";\\n\\n$breakpoints: breakpoints.$breakpoints;\\n\\n@mixin from($bp) {\\n  @media (width >= #{breakpoints.get($bp)}) {\\n    @content;\\n  }\\n}\\n\\n@mixin until($bp) {\\n  @media (width < #{breakpoints.get($bp)}) {\\n    @content;\\n  }\\n}\\n\\n@mixin between($from, $until) {\\n  @media (#{breakpoints.get($from)} <= width < #{breakpoints.get($until)}) {\\n    @content;\\n  }\\n}\\n","// --------------------------------------------------\\n// Mixins used throughout the theme\\n// --------------------------------------------------\\n\\n// Media queries\\n// --------------------------------------------------\\n\\n@use \\"sass:color\\";\\n@use \\"sass:math\\";\\n@use \\"sass:string\\";\\n@use \\"sass:map\\";\\n@use \\"lib/viewport\\";\\n\\n$breakpoints: (\\n  mobile-small: map.get(viewport.$breakpoints, sm),\\n  mobile-medium: map.get(viewport.$breakpoints, sm),\\n  mobile-large: map.get(viewport.$breakpoints, sm),\\n  mobile-extra-large: map.get(viewport.$breakpoints, sm),\\n  tablet: map.get(viewport.$breakpoints, md),\\n  medium: map.get(viewport.$breakpoints, lg),\\n  large: map.get(viewport.$breakpoints, lg),\\n  extra-large: map.get(viewport.$breakpoints, xl),\\n);\\n\\n/* breakpoint is a legacy mixin. Use `@use \\"lib/viewport\\"` instead. */\\n@mixin breakpoint($bp, $rule: max-width, $type: screen, $sidebar: false) {\\n  /* stylelint-disable-next-line scss/no-global-function-names */\\n  $bp-value: map-get($breakpoints, $bp);\\n\\n  @if $rule == min-width {\\n    $bp-value: calc(#{$bp-value} + 1px);\\n  }\\n\\n  @media #{$type} and (#{$rule}: #{$bp-value}) {\\n    @content;\\n  }\\n\\n  // if you want to consider the sidebar in your breakpoint\\n  // you can pass in $sidebar: true\\n  // note that your breakpoint will need to be at the root level\\n  @if $sidebar {\\n    // when the sidebar is shown, we want to increase the breakpoints by the width of the sidebar\\n    /* stylelint-disable-next-line scss/no-global-function-names */\\n    @media #{$type} and (#{$rule}: calc(#{map-get($breakpoints, $bp)} + #{$d-sidebar-width})) {\\n      .has-sidebar-page {\\n        @content;\\n      }\\n    }\\n  }\\n}\\n\\n// CSS3 properties\\n// --------------------------------------------------\\n\\n// Clearfix\\n\\n@mixin clearfix() {\\n  &::before,\\n  &::after {\\n    content: \\"\\";\\n    display: table;\\n  }\\n\\n  &::after {\\n    clear: both;\\n  }\\n}\\n\\n@mixin linear-gradient($start-color, $end-color) {\\n  background-color: $start-color;\\n  background-image: linear-gradient(to bottom, $start-color, $end-color);\\n}\\n\\n@mixin darken-background($background-color, $amt) {\\n  $overlay: dark-light-choose(\\n    rgb(var(--primary-rgb), $amt),\\n    rgb(var(--secondary-rgb), $amt)\\n  );\\n  background-image: linear-gradient(to bottom, $overlay 100%, $overlay 100%);\\n}\\n\\n// Visibility\\n// --------------------------------------------------\\n\\n// Only shows hover on non-touch devices\\n@mixin hover {\\n  .discourse-no-touch &,\\n  .no-ember & {\\n    &:hover,\\n    &.btn-hover {\\n      @content;\\n    }\\n  }\\n}\\n\\n@mixin ellipsis {\\n  overflow: hidden;\\n  white-space: nowrap;\\n  text-overflow: ellipsis;\\n}\\n\\n@mixin line-clamp($lines) {\\n  display: -webkit-box;\\n  overflow: hidden;\\n  text-overflow: ellipsis;\\n  overflow-wrap: break-word;\\n  -webkit-line-clamp: $lines;\\n  -webkit-box-orient: vertical;\\n}\\n\\n//\\n// --------------------------------------------------\\n\\n$vpad: 0.5em;\\n$hpad: 0.65em;\\n\\n// for consistent sizing across inputs, buttons and dropdowns\\n@mixin form-item-sizing {\\n  border: 1px solid transparent;\\n  font-size: var(--font-0);\\n  line-height: normal;\\n  box-sizing: border-box;\\n  padding: $vpad $hpad;\\n}\\n\\n// Used to handle -webkit prefix, but now we have autoprefixer\\n// Keeping for backward-compat with plugins/themes only\\n@mixin user-select($mode) {\\n  user-select: $mode;\\n}\\n\\n// Unselectable (avoids unwanted selections with iPad, touch laptops, etc)\\n@mixin unselectable {\\n  cursor: default;\\n\\n  @include user-select(none);\\n}\\n\\n// Stuff we repeat\\n@mixin d-animation($name, $duration, $easing: ease) {\\n  animation: $name $duration $easing forwards;\\n\\n  @media (prefers-reduced-motion) {\\n    /* stylelint-disable-next-line no-invalid-position-declaration */\\n    animation-duration: 0s;\\n  }\\n}\\n\\n@mixin default-focus() {\\n  border-color: var(--d-input-focused-color);\\n  outline: 2px solid var(--d-input-focused-color);\\n  outline-offset: -2px;\\n}\\n\\n/// Helper function to easily use an SVG inline in CSS\\n/// without encoding it to base64, saving bytes.\\n/// It also helps with browser support, especially for IE11.\\n///\\n/// @author Jakob Eriksen\\n/// @link http://codepen.io/jakob-e/pen/doMoML\\n/// @param {String} $svg - SVG image to encode\\n/// @return {String} - Encoded SVG data uri\\n@function svg-uri($svg) {\\n  $encoded: \\"\\";\\n  $slice: 2000;\\n  $index: 0;\\n  $loops: math.ceil(math.div(string.length($svg), $slice));\\n\\n  @for $i from 1 through $loops {\\n    $chunk: string.slice($svg, $index, $index + $slice - 1);\\n    $chunk: str-replace($chunk, '\\"', \\"'\\");\\n    $chunk: str-replace($chunk, \\"<\\", \\"%3C\\");\\n    $chunk: str-replace($chunk, \\">\\", \\"%3E\\");\\n    $chunk: str-replace($chunk, \\"&\\", \\"%26\\");\\n    $chunk: str-replace($chunk, \\"#\\", \\"%23\\");\\n    $encoded: #{$encoded}#{$chunk};\\n    $index: $index + $slice;\\n  }\\n\\n  @return url(\\"data:image/svg+xml;charset=utf8,#{$encoded}\\");\\n}\\n\\n/// Replace `$search` with `$replace` in `$string`\\n/// @author Hugo Giraudel\\n/// @link http://sassmeister.com/gist/1b4f2da5527830088e4d\\n/// @param {String} $string - Initial string\\n/// @param {String} $search - Substring to replace\\n/// @param {String} $replace ('') - New value\\n/// @return {String} - Updated string\\n@function str-replace($string, $search, $replace: \\"\\") {\\n  $index: string.index($string, $search);\\n\\n  @if $index {\\n    @return string.slice($string, 1, $index - 1) + $replace +\\n      str-replace(\\n        string.slice($string, $index + string.length($search)),\\n        $search,\\n        $replace\\n      );\\n  }\\n\\n  @return $string;\\n}\\n\\n// SCSS accepts HEX or RGB colors for rgba($color, 0.5)\\n// CSS custom properties only accept RGB\\n// Example usage:\\n\\n// --primary-rgb: #{hexToRGB($primary)};\\n// ...\\n// rgba(var(--primary-low-rgb), 0.5)\\n\\n@function hexToRGB($hex) {\\n  @return color.red($hex), color.green($hex), color.blue($hex);\\n}\\n\\n@function schemeType() {\\n  @if is-light-color-scheme() {\\n    @return \\"light\\";\\n  } @else {\\n    @return \\"dark\\";\\n  }\\n}\\n\\n@function absolute-image-url($path) {\\n  // public_image_path is added by the stylesheet importer\\n  // it returns a CDN or subfolder path (if applicable).\\n  // SCSS will compile (and return the relative path) if public_image_path is missing.\\n  /* stylelint-disable-next-line scss/no-global-function-names */\\n  @if global-variable-exists(public_image_path) {\\n    @if string.index(\\"#{$path}\\", \\"/plugins\\") == 1 {\\n      $plugin_asset_path: str-replace($public_image_path, \\"/images\\", \\"\\");\\n\\n      @return url(\\"#{$plugin_asset_path}#{$path}\\");\\n    } @else {\\n      @return url(\\"#{$public_image_path}#{$path}\\");\\n    }\\n  } @else {\\n    @return url(\\"#{$path}\\");\\n  }\\n}\\n\\n@mixin mention() {\\n  // memo to self: do not make this inline-flex because it breaks text alignments and causes a whole avalance of unpleasant consequences\\n  display: inline-block;\\n  font-size: 0.93em;\\n  font-weight: normal;\\n  color: var(--primary);\\n  padding: 0.2em 0.34em;\\n  background: var(--mention-background-color);\\n  border-radius: 0.6em;\\n  text-decoration: none;\\n  text-wrap: nowrap;\\n  line-height: 1;\\n  unicode-bidi: plaintext;\\n\\n  &[data-valid=\\"false\\"] {\\n    background: unset;\\n    padding: 0;\\n  }\\n\\n  &.--bot {\\n    background: var(--success-low);\\n  }\\n\\n  &.--wide {\\n    background: var(--highlight-low-or-medium);\\n  }\\n}\\n\\n@mixin nav-active() {\\n  color: var(--d-nav-color--active);\\n  background: var(--d-nav-bg-color--active);\\n\\n  .d-icon {\\n    color: var(--d-nav-color--active);\\n  }\\n\\n  &::after {\\n    content: \\"\\";\\n    position: absolute;\\n    left: 0;\\n    bottom: 0;\\n    right: 0;\\n    height: var(--d-nav-underline-height);\\n    background: var(--d-nav-color--active);\\n\\n    // Forced colors drop backgrounds, which is the only thing that marks\\n    // the active item.\\n    @media (forced-colors: active) {\\n      background: Highlight;\\n      forced-color-adjust: none;\\n    }\\n  }\\n}\\n\\n@mixin nav-hover() {\\n  color: var(--d-nav-color--hover);\\n  background: var(--d-nav-bg-color--hover);\\n\\n  .d-icon {\\n    color: var(--d-nav-color--active);\\n  }\\n}\\n\\n// A strip that hides its scrollbar and fades the edge beyond which more\\n// content lies. The fade reads the data-d-scroll-* attributes stamped by\\n// the scroll-edges watcher, which DOverflowControls and the dScrollEdges\\n// modifier both run. The band starts fully transparent across --fade-inset\\n// so strip content never shows through a chevron parked on the edge, which\\n// assumes the chevron covers that band: a wrapper that pads the scroller's\\n// scrolling edge moves the chevron off it and hides content under nothing.\\n// #000 is deliberate: a mask reads only alpha, so a colour token would be\\n// wrong here.\\n@mixin scroll