at-composer-uploads {\\n  .chat-composer-uploads-container {\\n    .full-page-chat & {\\n      flex-wrap: wrap;\\n      row-gap: 0.5rem;\\n    }\\n  }\\n}\\n",".chat-drawer-container .channels-list-container {\\n  .chat-channel-divider {\\n    padding: 1.5rem 0.5rem 0.5rem 1rem;\\n    font-size: var(--font-0);\\n  }\\n\\n  &.has-scrollbar {\\n    .chat-channel-row {\\n      margin-right: 0;\\n    }\\n  }\\n\\n  .chat-channel-row {\\n    height: 3.6em;\\n    padding: 0 0.5rem;\\n    margin: 0 0.5rem 0 0.5rem;\\n\\n    &:not(:last-of-type) {\\n      border-bottom: 1px solid var(--content-border-color);\\n    }\\n\\n    .chat-channel-metadata {\\n      .chat-channel-unread-indicator {\\n        margin-top: 0.25rem;\\n      }\\n    }\\n\\n    &.--threads {\\n      margin-top: 0.25rem;\\n\\n      .c-unread-indicator {\\n        width: 8px;\\n        height: 8px;\\n      }\\n\\n      .chat-channel-title {\\n        gap: 0.5rem;\\n        color: var(--primary);\\n      }\\n    }\\n  }\\n\\n  .toggle-channel-membership-button.-leave {\\n    margin-left: 0.5em;\\n  }\\n}\\n\\n.chat-drawer-container .c-channel-settings,\\n.chat-drawer-container .c-channel-info__nav,\\n.chat-drawer-container .c-channel-members,\\n.chat-drawer-container .c-search,\\n.chat-drawer-container .chat-message-creator-container {\\n  padding: 1rem;\\n  width: auto;\\n}\\n\\n.chat-drawer-container .c-channel-info__nav,\\n.chat-drawer-container .c-channel-info__nav .nav-pills {\\n  padding-bottom: 0;\\n}\\n\\n.chat-drawer-container .c-footer .chat-channel-unread-indicator.-urgent {\\n  width: min-content;\\n}\\n",".has-full-page-chat:not(.discourse-sidebar) {\\n  .full-page-chat {\\n    .channels-list {\\n      height: calc(100vh - var(--main-outlet-offset));\\n      border-right: 1px solid var(--content-border-color);\\n      background: var(--secondary);\\n      overflow-y: auto;\\n\\n      .chat-channel-divider {\\n        padding: 2rem 1rem 0.5rem 1rem;\\n\\n        &:first-of-type {\\n          padding-top: 1.5rem;\\n        }\\n      }\\n\\n      .loading-container {\\n        padding-bottom: 1em;\\n      }\\n\\n      .chat-channel-row {\\n        height: 2.5em;\\n        padding: 0 0.5rem;\\n        margin: 0 0.5rem 0.125rem 0.5rem;\\n\\n        &:hover,\\n        &.active {\\n          background-color: var(--primary-low);\\n\\n          .chat-channel-title {\\n            .category-chat-name,\\n            .chat-name,\\n            .dm-usernames {\\n              color: var(--primary);\\n            }\\n          }\\n        }\\n\\n        .chat-channel-metadata {\\n          &__date {\\n            display: none;\\n          }\\n        }\\n      }\\n    }\\n\\n    .channels-list-container {\\n      height: auto;\\n    }\\n\\n    .channels-list-container.center-empty-channels-list {\\n      height: 90%;\\n    }\\n  }\\n}\\n","@use \\"breakpoints\\";\\n\\n$breakpoints: breakpoints.$breakpoints;\\n\\n@mixin from($bp) {\\n  @media (width >= #{breakpoints.get($bp)}) {\\n    @content;\\n  }\\n}\\n\\n@mixin until($bp) {\\n  @media (width < #{breakpoints.get($bp)}) {\\n    @content;\\n  }\\n}\\n\\n@mixin between($from, $until) {\\n  @media (#{breakpoints.get($from)} <= width < #{breakpoints.get($until)}) {\\n    @content;\\n  }\\n}\\n","@use \\"lib/viewport\\";\\n\\n@include viewport.until(lg) {\\n  .main-chat-outlet.has-side-panel-expanded {\\n    .c-routes.--channel {\\n      display: none;\\n    }\\n\\n    .chat-side-panel {\\n      width: 100% !important; // overrides the inline auto width\\n      border: none;\\n\\n      .chat-side-panel-resizer {\\n        display: none;\\n      }\\n    }\\n  }\\n}\\n",".chat-message-actions {\\n  background-color: var(--secondary);\\n}\\n",".chat-message-actions {\\n  .react-btn,\\n  .reply-btn,\\n  .chat-message-thread-btn,\\n  .bookmark-btn {\\n    border: 1px solid transparent;\\n    border-bottom-color: var(--primary-300);\\n    border-radius: 0;\\n    border-top-color: var(--primary-300);\\n\\n    &:first-child {\\n      border-left-color: var(--primary-300);\\n      border-top-left-radius: var(--d-border-radius);\\n      border-bottom-left-radius: var(--d-border-radius);\\n    }\\n\\n    &:hover {\\n      background: var(--primary-low);\\n      border-color: var(--primary-low-mid);\\n      color: var(--primary-medium);\\n      z-index: 1;\\n    }\\n  }\\n}\\n",".c-channel-info {\\n  max-width: 500px;\\n}\\n",".chat-message-thread-indicator {\\n  max-width: 600px;\\n  grid-template-areas:\\n    \\"avatar info replies participants\\"\\n    \\"avatar excerpt excerpt excerpt\\";\\n\\n  &__replies-count {\\n    display: flex;\\n    align-self: center;\\n  }\\n}\\n\\n@container (max-width: 400px) {\\n  .chat-message-thread-indicator {\\n    grid-template-areas:\\n      \\"avatar info info participants\\"\\n      \\"excerpt excerpt excerpt replies\\";\\n\\n    &__replies-count {\\n      align-self: center;\\n      grid-area: replies;\\n      justify-content: flex-end;\\n    }\\n\\n    &__last-reply-excerpt {\\n      white-space: wrap;\\n      display: -webkit-box;\\n      -webkit-line-clamp: 2;\\n      -webkit-box-orient: vertical;\\n      margin-top: 0.5rem;\\n      margin-right: 0.25rem;\\n    }\\n  }\\n}\\n","#main-chat-outlet.chat-view {\\n  min-height: 0;\\n  display: grid;\\n  grid-template-areas: \\"main threads\\";\\n\\n  // minmax(0, …) lets the main area shrink below its content's min-content\\n  // (e.g. the pinned-message bar's text), so the side-panel divider can be\\n  // dragged freely instead of stopping at the widest no-wrap content.\\n  grid-template-columns: minmax(0, 1fr) auto;\\n}\\n\\n.chat-side-panel {\\n  box-sizing: border-box;\\n  border-left: 1px solid var(--content-border-color);\\n  position: relative;\\n  min-width: 250px;\\n\\n  &__list {\\n    flex-grow: 1;\\n    padding: 0 1.5em 1em;\\n  }\\n}\\n\\n#main-chat-outlet .chat-side-panel .c-navbar__title {\\n  margin-left: 0;\\n}\\n"]}
